		$anchor = isset( $assigned[ $dom_idx ] ) ? $dom_idx : -1;
		$ui = 0; $di = 0;
		foreach ( $size_defs as $i => $s ) { // $size_defs is sorted biggest → smallest, so walk outward from the anchor
			if ( isset( $assigned[ $i ] ) ) { continue; }
			$bigger = ( $anchor < 0 ) ? ( $i < $dom_idx ) : ( $i < $anchor );
			$pool = $bigger ? $up : $down;
			$sl = '';
			while ( $sl === '' ) { $cand = $bigger ? ( $pool[ $ui ] ?? '' ) : ( $pool[ $di ] ?? '' ); if ( $cand === '' ) { break; } if ( $bigger ) { $ui++; } else { $di++; } if ( empty( $used[ $cand ] ) ) { $sl = $cand; } }
			if ( $sl === '' ) { continue; } // beyond the 7-step ladder — dropped (never happens on real sites)
				$assigned[ $i ] = $sl; $used[ $sl ] = true; $auto[ $i ] = true;
		}
		// Sizes above the anchor were visited biggest-first, so their ladder steps are reversed: fix the order
		// (the NEAREST bigger size is Large, the farthest is 2X-Large).
		$free_up = array_values( array_filter( $up, function ( $u ) use ( $assigned, $auto ) { foreach ( $assigned as $j => $v ) { if ( $v === $u && empty( $auto[ $j ] ) ) { return false; } } return true; } ) );
		$above = array(); foreach ( $assigned as $i => $sl ) { if ( ! empty( $auto[ $i ] ) && in_array( $sl, $up, true ) ) { $above[] = $i; } }
		rsort( $above ); foreach ( $above as $k => $i ) { if ( isset( $free_up[ $k ] ) ) { $assigned[ $i ] = $free_up[ $k ]; } }
		foreach ( $size_defs as $i => $s ) {
			if ( ! isset( $assigned[ $i ] ) ) { continue; }
			list( $nm, $slug, $sid ) = $ladder[ $assigned[ $i ] ];
			if ( $i === $dom_idx && count( $size_defs ) > 1 && 'md' !== $slug ) { $nm .= ' (Default)'; } // a source-named default (e.g. btn-lg) still reads as the default
			$sz = array( 'id' => $sid, 'size_name' => $nm, 'slug' => $slug );
			if ( $s['fs'] !== '' )     { $u = $unit( $s['fs'] );     if ( $u ) { $sz['font_size']     = $u; } }
			if ( $s['lh'] !== '' && $s['lh'] !== 'normal' ) { $sz['line_height'] = $s['lh']; }
			if ( $s['py'] !== '' )     { $u = $unit( $s['py'] );     if ( $u ) { $sz['padding_y']     = $u; } }
			if ( $s['px'] !== '' )     { $u = $unit( $s['px'] );     if ( $u ) { $sz['padding_x']     = $u; } }
			if ( ! empty( $s['height'] ) ) { $u = $unit( $s['height'] ); if ( $u ) { $sz['min_height'] = $u; } } // fixed h-N → Min Height (content centres to it)
			if ( $s['radius'] !== '' ) { $u = $unit( $s['radius'] ); if ( $u ) { $sz['border_radius'] = $u; } } // 9999px = pill
			$sizes[] = $sz;
		}

		$out = array();
		if ( ! empty( $colors ) ) { $out['button_colors'] = $colors; }
		if ( ! empty( $sizes ) )  { $out['button_sizes']  = $sizes; }
		return $out;
	}

	/**
	 * Section Styles — cluster the source's distinctive section BANDS into reusable presets.
	 * PHP mirror of the capture service's sectionStyles() (to-presets.mjs): a section style is
	 * the reusable band SKIN (background + text/heading/link colours + border + radius). Only a
	 * band that DEVIATES from the page base (its own background fill, border, radius or shadow)
	 * becomes a preset; near-identical bands cluster into one; a text/heading colour is carried
	 * only when it differs from the base. Per-section PADDING stays a native section option, so
	 * presets leave padding empty (matching unysonplus_default_section_style_presets()).
	 *
	 * @param string $html
	 * @return array array('section_style_presets'=>…) or empty.
	 */
	public static function build_section_style_presets( $html ) {
		$html = (string) $html;
		if ( $html === '' || ! class_exists( 'FW_Site_Converter_Tailwind' ) ) { return array(); }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$body = null;
		foreach ( $dom->getElementsByTagName( 'body' ) as $b ) { $body = $b; break; }
		if ( ! $body ) { return array(); }
		$roots = self::section_roots( $body );
		if ( empty( $roots ) ) { return array(); }

		$parse = function ( $c ) {
			$c = strtolower( trim( (string) $c ) );
			if ( preg_match( '/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)(?:[,\s\/]+([0-9.]+))?/', $c, $m ) ) {
				return array( (int) $m[1], (int) $m[2], (int) $m[3], ( isset( $m[4] ) && $m[4] !== '' ? (float) $m[4] : 1.0 ) );
			}
			if ( preg_match( '/^#([0-9a-f]{3}|[0-9a-f]{6})$/', $c, $m ) ) {
				$h = $m[1]; if ( strlen( $h ) === 3 ) { $h = $h[0] . $h[0] . $h[1] . $h[1] . $h[2] . $h[2]; }
				return array( hexdec( substr( $h, 0, 2 ) ), hexdec( substr( $h, 2, 2 ) ), hexdec( substr( $h, 4, 2 ) ), 1.0 );
			}
			return null;
		};
		$norm = function ( $c ) use ( $parse ) {
			$p = $parse( $c );
			if ( ! $p || (float) $p[3] === 0.0 ) { return ''; }                 // transparent / none = no fill
			return $p[3] < 1 ? "rgba({$p[0]}, {$p[1]}, {$p[2]}, {$p[3]})" : "rgb({$p[0]}, {$p[1]}, {$p[2]})";
		};
		$lum  = function ( $c ) use ( $parse ) { $p = $parse( $c ); return $p ? ( 0.2126 * $p[0] + 0.7152 * $p[1] + 0.0722 * $p[2] ) : null; };
		$unit = function ( $v ) { $v = trim( (string) $v ); return preg_match( '/^(-?[0-9.]+)\s*(px|rem|em|%)?$/', $v, $m ) ? array( 'value' => $m[1], 'unit' => ( isset( $m[2] ) && $m[2] !== '' ? $m[2] : 'px' ) ) : null; };
		// Prefer the MEASURED heading color (data-sc-cs), falling back to the compiled Tailwind color — the
		// source's headings on a green CTA band are `text-white` etc. that only the computed style carries.
		$headOf = function ( $node ) use ( $norm ) {
			foreach ( array( 'h1', 'h2', 'h3' ) as $ht ) {
				foreach ( $node->getElementsByTagName( $ht ) as $hn ) {
					$cc = self::sc_css( $hn, 'color' );
					if ( $cc !== '' ) { return $norm( $cc ); }
					$hc = FW_Site_Converter_Tailwind::compile_class_set( self::cls( $hn ) );
					return isset( $hc['base']['color'] ) ? $norm( $hc['base']['color'] ) : '';
				}
			}
			return '';
		};

		// Pass 1 — read each section's skin from the MEASURED computed style (data-sc-cs) first, Tailwind
		// compile as fallback. Semantic band fills (`bg-primary` green CTA, `bg-background` tint) and full-bleed
		// background layers (`absolute inset-0 bg-primary`) only resolve via the computed style, so the earlier
		// compile-only pass collapsed every band to one "Light" preset. Also tally base text/heading.
		$secs = array(); $textTally = array(); $headTally = array();
		foreach ( $roots as $node ) {
			$c = FW_Site_Converter_Tailwind::compile_class_set( self::cls( $node ) );
			$b = isset( $c['base'] ) ? $c['base'] : array();
			// Effective background: the node's own opaque computed fill, else a full-bleed (`inset-0`) child
			// background layer's opaque fill, else the compiled Tailwind value. Low-alpha tints are ignored.
			$bg_raw = self::el_bg_opaque( $node );
			if ( $bg_raw === '' ) { $bg_raw = self::fullbleed_bg( $node ); }
			$bg     = $bg_raw !== '' ? $norm( $bg_raw ) : ( isset( $b['background-color'] ) ? $norm( $b['background-color'] ) : '' );
			$bw     = ( isset( $b['border-width'] ) && $b['border-width'] !== '0' && $b['border-width'] !== '0px' ) ? $b['border-width'] : '';
			$radius = ( isset( $b['border-radius'] ) && $b['border-radius'] !== '0' && $b['border-radius'] !== '0px' ) ? $b['border-radius'] : '';
			$shadow = ( isset( $b['box-shadow'] ) && $b['box-shadow'] !== 'none' ) ? $b['box-shadow'] : '';
			$tcs    = self::sc_css( $node, 'color' );
			$text   = $tcs !== '' ? $norm( $tcs ) : ( isset( $b['color'] ) ? $norm( $b['color'] ) : '' );
			$head   = $headOf( $node );
			$bdcol  = isset( $b['border-color'] ) ? $norm( $b['border-color'] ) : '';
			if ( $text !== '' ) { $textTally[ $text ] = ( isset( $textTally[ $text ] ) ? $textTally[ $text ] : 0 ) + 1; }
			if ( $head !== '' ) { $headTally[ $head ] = ( isset( $headTally[ $head ] ) ? $headTally[ $head ] : 0 ) + 1; }
			$secs[] = compact( 'bg', 'bw', 'radius', 'shadow', 'text', 'head', 'bdcol' );
		}
		arsort( $textTally ); arsort( $headTally );
		$baseText = $textTally ? (string) array_key_first( $textTally ) : '';
		$baseHead = $headTally ? (string) array_key_first( $headTally ) : '';

		// Pass 2 — cluster the distinctive bands.
		$groups = array();
		foreach ( $secs as $s ) {
			if ( $s['bg'] === '' && $s['bw'] === '' && $s['radius'] === '' && $s['shadow'] === '' ) { continue; } // plain band = default
			$key = $s['bg'] . '|' . $s['radius'] . '|' . $s['bw'] . $s['bdcol'];
			if ( ! isset( $groups[ $key ] ) ) { $groups[ $key ] = array_merge( $s, array( 'count' => 0 ) ); }
			$groups[ $key ]['count']++;
		}
		if ( empty( $groups ) ) { return array(); }
		uasort( $groups, function ( $a, $b ) { return $b['count'] - $a['count']; } );

		$empty = array( 'predefined' => '', 'custom' => '' );
		$u0    = array( 'value' => '', 'unit' => 'px' );
		$pad0  = array(
			'margin'  => array( 'all' => '', 'top' => '', 'right' => '', 'bottom' => '', 'left' => '' ),
			'padding' => array( 'all' => '', 'top' => '', 'right' => '', 'bottom' => '', 'left' => '' ),
		);
		$used = array(); $n = 0; $presets = array();
		foreach ( $groups as $g ) {
			$L      = $lum( $g['bg'] );
			$base   = ( $L === null ) ? 'Band' : ( $L < 90 ? 'Dark' : ( $L > 245 ? 'Light' : 'Alt' ) );
			$used[ $base ] = ( isset( $used[ $base ] ) ? $used[ $base ] : 0 ) + 1;
			$name   = $used[ $base ] > 1 ? $base . ' ' . $used[ $base ] : $base;
			$isDark = ( $L !== null && $L < 90 );
			$rad    = $g['radius'] !== '' ? $unit( $g['radius'] ) : null;
			$bwu    = $g['bw'] !== '' ? $unit( $g['bw'] ) : null;
			$presets[] = array(
				'id'            => 's' . str_pad( (string) ( ++$n ), 9, '0', STR_PAD_LEFT ),
				'style_name'    => $name,
				'background'    => $g['bg'] !== '' ? array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => $g['bg'] ) ) ) : array( 'color' => array( 'value' => $empty ) ),
				'text_color'    => ( $g['text'] !== '' && ( $isDark || $g['text'] !== $baseText ) ) ? array( 'predefined' => '', 'custom' => $g['text'] ) : $empty,
				'heading_color' => ( $g['head'] !== '' && ( $isDark || $g['head'] !== $baseHead ) ) ? array( 'predefined' => '', 'custom' => $g['head'] ) : $empty,
				'link_color'    => $empty,
				'border'        => $bwu ? array( 'width' => $bwu, 'style' => 'solid', 'color' => ( $g['bdcol'] !== '' ? array( 'predefined' => '', 'custom' => $g['bdcol'] ) : $empty ) ) : array( 'width' => $u0, 'style' => '', 'color' => $empty ),
				'border_sides'  => array( 'top', 'right', 'bottom', 'left' ),
				'border_extent' => array( 'mode' => 'full' ),
				'border_radius' => $rad ? $rad : $u0,
				'padding'       => $pad0,
			);
		}
		return empty( $presets ) ? array() : array( 'section_style_presets' => $presets );
	}

	/**
	 * CONTAINER WIDTHS (Theme Settings → Components → Section Styles → Container Widths). Gathers the source's
	 * distinct content-band max-widths (centered content containers), CLUSTERS them (±16px, so measurement
	 * noise doesn't spawn near-duplicates), and returns a preset library: the three built-ins (Narrow 768 /
	 * Medium 896 / Wide 1024) plus one named preset per additional distinct width the source actually uses —
	 * reusing friendly standard names on a value match (max-w-2xl…7xl) and "Content NNN" otherwise. Sections
	 * then reference these by name (set in map_container_width), so a whole converted site SHARES named widths
	 * instead of repeating a custom value. Returns array( 'container_width_presets' => [...] ) or empty.
	 *
	 * @param string $html
	 * @return array
	 */
	public static function build_container_width_presets( $html ) {
		$html = (string) $html;
		if ( $html === '' ) { return array(); }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$xp = new DOMXPath( $dom );
		// Tally content-band max-widths: a computed `max-width` in the content range on a CENTERED wrapper
		// (mx-auto / margin auto) or a `container*`/`max-w-*` class — i.e. a content cap, not a random box.
		$tally = array();
		foreach ( $xp->query( '//*[@data-sc-cs]' ) as $el ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/', $cs, $m ) ) { continue; }
			$px = (float) $m[1];
			if ( $px < 480 || $px > 1760 ) { continue; } // outside the plausible content-band range
			$cls = ' ' . strtolower( (string) $el->getAttribute( 'class' ) ) . ' ';
			$centered = self::cap_is_centred( $el, $cls, $cs );
			if ( ! $centered ) { continue; }
			$key = (int) round( $px );
			$tally[ $key ] = ( $tally[ $key ] ?? 0 ) + 1;
		}
		// Cluster the measured widths (±16px) into distinct buckets, weighted by frequency.
		$clusters = array();
		krsort( $tally ); // largest first so a big popular width anchors its cluster
		arsort( $tally );
		foreach ( $tally as $px => $w ) {
			// (by INDEX, not a reference: `$hit = null` through a reference nulled the cluster it pointed at on the next pass)
			$hi = -1;
			foreach ( $clusters as $ci => $c ) { if ( is_array( $c ) && abs( $c['px'] - $px ) <= 16 ) { $hi = $ci; break; } }
			if ( $hi >= 0 ) { $clusters[ $hi ]['w'] += $w; } else { $clusters[] = array( 'px' => $px, 'w' => $w ); }
		}
		// Friendly names for the standard Tailwind max-w steps (px → name). Match within ±10px.
		$std = array( 640 => 'Small', 672 => 'Prose', 768 => 'Narrow', 896 => 'Medium', 1024 => 'Wide', 1152 => 'Wide L', 1280 => 'Wide XL', 1440 => 'Wide XXL' );
		$name_for = function ( $px ) use ( $std ) {
			foreach ( $std as $sv => $nm ) { if ( abs( $sv - $px ) <= 10 ) { return array( $nm, $sv ); } }
			return array( 'Content ' . (int) $px, (int) $px );
		};
		// Seed with the three built-ins so narrow/medium/wide always exist (zero migration); then add any
		// source width that isn't one of them. Dedupe by the resolved standard value / slug.
		$presets = self::default_container_width_presets();
		$have = array( 640 => true, 672 => true, 768 => true, 896 => true, 1024 => true, 1152 => true, 1280 => true, 1440 => true ); // full standard scale
		$seen_slug = array( 'small' => true, 'prose' => true, 'narrow' => true, 'medium' => true, 'wide' => true, 'wide-l' => true, 'wide-xl' => true, 'wide-xxl' => true );
		foreach ( $clusters as $c ) {
			if ( $c['w'] < 1 ) { continue; }
			list( $nm, $val ) = $name_for( $c['px'] );
			if ( isset( $have[ $val ] ) ) { continue; }               // already covered by a built-in
			$slug = trim( preg_replace( '/[^a-z0-9]+/', '-', strtolower( $nm ) ), '-' );
			if ( $slug === '' || isset( $seen_slug[ $slug ] ) ) { continue; }
			$seen_slug[ $slug ] = true; $have[ $val ] = true;
			$presets[] = array( 'id' => 'cw_' . $slug, 'width_name' => $nm, 'width' => array( 'value' => (string) $val, 'unit' => 'px' ) );
		}
		return array( 'container_width_presets' => $presets );
	}

	/**
	 * The FULL standard container-width scale, seeded on every conversion so EVERY slug map_container_width()
	 * can emit (small…wide-xxl) is a REGISTERED, resolvable named preset — not just narrow/medium/wide. A
	 * section/flexbox mapped to `wide-xl` (1280, a very common `max-w-7xl`) used to resolve to nothing when the
	 * source had no `max-w-*` wrapper to cluster that width, so the band rendered edge-to-edge. (The plugin's
	 * container-width map safety net now also guarantees these, but registering them keeps the picker labelled.)
	 */
	private static function default_container_width_presets() {
		return array(
			array( 'id' => 'cw_small',    'width_name' => 'Small',    'width' => array( 'value' => '640',  'unit' => 'px' ) ),
			array( 'id' => 'cw_prose',    'width_name' => 'Prose',    'width' => array( 'value' => '672',  'unit' => 'px' ) ),
			array( 'id' => 'cw_narrow',   'width_name' => 'Narrow',   'width' => array( 'value' => '768',  'unit' => 'px' ) ),
			array( 'id' => 'cw_medium',   'width_name' => 'Medium',   'width' => array( 'value' => '896',  'unit' => 'px' ) ),
			array( 'id' => 'cw_wide',     'width_name' => 'Wide',     'width' => array( 'value' => '1024', 'unit' => 'px' ) ),
			array( 'id' => 'cw_wide-l',   'width_name' => 'Wide L',   'width' => array( 'value' => '1152', 'unit' => 'px' ) ),
			array( 'id' => 'cw_wide-xl',  'width_name' => 'Wide XL',  'width' => array( 'value' => '1280', 'unit' => 'px' ) ),
			array( 'id' => 'cw_wide-xxl', 'width_name' => 'Wide XXL', 'width' => array( 'value' => '1440', 'unit' => 'px' ) ),
		);
	}

	/**
	 * Map a section's content-band max-width (px) → a container_width preset value for the section shortcode:
	 * the matching preset's SLUG when it lands on one (± tolerance), else a Custom width. Uses the same std
	 * names as build_container_width_presets so a converted section references the shared named width. Returns
	 * the `container_width` att array, or null to leave it as Inherit.
	 *
	 * @param float $px measured content max-width in px (0 = none)
	 * @return array|null
	 */
	public static function map_container_width( $px ) {
		$px = (float) $px;
		if ( $px < 480 || $px > 1760 ) { return null; } // full-width / none → Inherit
		$std = array( 640 => 'small', 672 => 'prose', 768 => 'narrow', 896 => 'medium', 1024 => 'wide', 1152 => 'wide-l', 1280 => 'wide-xl', 1440 => 'wide-xxl' );
		foreach ( $std as $sv => $slug ) { if ( abs( $sv - $px ) <= 12 ) { return array( 'preset' => $slug ); } }
		// Non-standard: reference the "Content NNN" preset build_container_width_presets emits for this width
		// (same slug), so the section still points at a SHARED named width — not a repeated per-section custom.
		return array( 'preset' => 'content-' . (int) round( $px ) );
	}

	/**
	 * SPACING SCALE (Theme Settings → Components → Spacing — the `spacing_scale` addable-box: {name,size} rows).
	 * The source is Tailwind, so its spacing steps ARE the Bootstrap-aligned base scale (the plugin default,
	 * 0–12); we emit that as the editable scale (instead of the converter leaving it empty → silent theme
	 * fallback), then APPEND any arbitrary off-scale spacing the source genuinely uses — a Tailwind arbitrary
	 * token like `pt-[192px]` / `py-[3.5rem]` — as a `[value]` entry (the exact class the converter emits and
	 * the per-page CSS renders). Only spacing-prefixed arbitrary tokens are harvested (not decorative `w-[800px]`
	 * blobs), and only when they aren't already on the base scale. Deterministic: the base is the source's own
	 * Tailwind scale; the extras are values literally present in the markup.
	 *
	 * @param array  $tokens
	 * @param string $html
	 * @return array {name,size} rows (base scale + arbitraries), or [] when nothing to emit.
	 */
	public static function build_spacing_scale( array $tokens, $html ) {
		// Base = the Bootstrap-aligned scale (= the theme's unysonplus_default_spacing_scale()). Kept in sync
		// here so the converter is self-contained (the theme default isn't loaded in the capture/bundle path).
		$base = array(
			array( 'name' => '0',  'size' => '0' ),
			array( 'name' => '1',  'size' => '0.25rem' ),
			array( 'name' => '2',  'size' => '0.5rem' ),
			array( 'name' => '3',  'size' => '1rem' ),
			array( 'name' => '4',  'size' => '1.5rem' ),
			array( 'name' => '5',  'size' => '3rem' ),
			array( 'name' => '6',  'size' => '3.5rem' ),
			array( 'name' => '7',  'size' => '4rem' ),
			array( 'name' => '8',  'size' => '4.5rem' ),
			array( 'name' => '9',  'size' => '5rem' ),
			array( 'name' => '10', 'size' => '6rem' ),
			array( 'name' => '11', 'size' => '7rem' ),
			array( 'name' => '12', 'size' => '8rem' ),
		);
		$have = array();
		foreach ( $base as $e ) { $have[ trim( strtolower( $e['size'] ) ) ] = true; }

		// Harvest arbitrary SPACING tokens actually present in the markup: p/px/py/pt/pb/pl/pr and the m-* family
		// with a bracketed length — e.g. `pt-[192px]`, `mb-[3.5rem]`. Skip w-/h-/inset (sizes). Gap / space-x/y
		// tokens are NO LONGER harvested here — they feed the dedicated GAP scale (build_gap_scale) instead.
		$extras = array();
		if ( preg_match_all( '/\b(?:p[trblxy]?|m[trblxy]?)-\[([0-9.]+(?:px|rem|em))\]/', (string) $html, $mm ) ) {
			foreach ( array_unique( $mm[1] ) as $val ) {
				$k = trim( strtolower( $val ) );
				if ( isset( $have[ $k ] ) ) { continue; }
				// Only meaningful, larger off-scale values (avoid a flood of tiny 1px odds); keep ≥ 2.5rem / 40px.
				$px = self::spacing_to_px( $val );
				if ( $px < 40 ) { continue; }
				$have[ $k ] = true;
				$extras[ $px ] = array( 'name' => '[' . $val . ']', 'size' => $val );
			}
		}

		// Pass #5 MEASURED FOLD — a source whose off-scale rhythm lives only in COMPUTED style (a
		// non-Tailwind / visual builder: no `pt-[…]` class to scan, the vertical spacing is stamped
		// only on `data-sc-cs`) still contributes its real rhythm to the editable scale. Scan every
		// stamped element's computed vertical padding/margin and keep the OFF-scale values (≥40px, not
		// within 1px of a base-scale step) as exact `[NNpx]` tokens — the SAME values the section
		// distillation emits as `pt-[NNpx]`. Byte-for-byte mirror of the JS capture-extract
		// spacingTokens measured harvest (same `body *` element set, ≥40px threshold, 1px on-scale
		// tolerance, dedupe-by-px, appended into the shared extras before the ascending sort).
		$base_px  = array( 0, 4, 8, 16, 24, 48, 56, 64, 72, 80, 96, 112, 128 );
		$on_scale = function ( $px ) use ( $base_px ) {
			foreach ( $base_px as $b ) { if ( abs( $b - $px ) <= 1 ) { return true; } }
			return false;
		};
		if ( preg_match_all( '/data-sc-cs="([^"]*)"/i', (string) $html, $csm ) ) {
			foreach ( $csm[1] as $cs ) {
				foreach ( self::cs_vspace_px( $cs ) as $raw ) {
					$px = (int) round( $raw );
					if ( $px < 40 || $on_scale( $px ) || isset( $extras[ $px ] ) ) { continue; }
					$extras[ $px ] = array( 'name' => '[' . $px . 'px]', 'size' => $px . 'px' );
				}
			}
		}

		ksort( $extras );
		return array_merge( $base, array_values( $extras ) );
	}

	/**
	 * GAP SCALE (Theme Settings → Components → Spacing → Gaps — the `gap_scale` {name,size} rows). Mirrors the
	 * theme default (0-12 + the `[32px]`/`[40px]` mid-range, kept in sync here so the converter is
	 * self-contained), then APPENDS any OFF-scale gutter the source genuinely uses — a Tailwind arbitrary
	 * `gap-[20px]` / `space-x-[Npx]`, or a COMPUTED grid `gap:Npx` (visual builders). Each off-scale value
	 * becomes an exact `[NNpx]` entry so `gap_slug()`'s arbitrary output has a real preset to render against
	 * (`.section--gap-NNpx` / `--gap-NNpx`). Parallels build_spacing_scale; keeps gaps OUT of the spacing scale.
	 */
	public static function build_gap_scale( array $tokens, $html ) {
		$base = array(
			array( 'name' => '0', 'size' => '0' ),
			array( 'name' => '1', 'size' => '0.25rem' ),
			array( 'name' => '2', 'size' => '0.5rem' ),
			array( 'name' => '3', 'size' => '1rem' ),
			array( 'name' => '4', 'size' => '1.5rem' ),
			array( 'name' => '[32px]', 'size' => '32px' ),
			array( 'name' => '[40px]', 'size' => '40px' ),
			array( 'name' => '5', 'size' => '3rem' ),
			array( 'name' => '6', 'size' => '3.5rem' ),
			array( 'name' => '7', 'size' => '4rem' ),
			array( 'name' => '8', 'size' => '4.5rem' ),
			array( 'name' => '9', 'size' => '5rem' ),
			array( 'name' => '10', 'size' => '6rem' ),
			array( 'name' => '11', 'size' => '7rem' ),
			array( 'name' => '12', 'size' => '8rem' ),
		);
		// px values already covered (0,4,8,16,24,32,40,48,56,64,72,80,96,112,128) — an off-scale gap must be >1px
		// from ALL of these to earn its own entry.
		$base_px  = array( 0, 4, 8, 16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128 );
		$on_scale = function ( $px ) use ( $base_px ) {
			foreach ( $base_px as $b ) { if ( abs( $b - $px ) <= 1 ) { return true; } }
			return false;
		};
		$extras = array();
		// (a) Tailwind arbitrary gap classes — `gap-[20px]`, `gap-x-[18px]`, `space-x-[Npx]`.
		if ( preg_match_all( '/\b(?:gap(?:-[xy])?|space-[xy])-\[([0-9.]+(?:px|rem|em))\]/', (string) $html, $mm ) ) {
			foreach ( array_unique( $mm[1] ) as $val ) {
				$px = (int) round( self::spacing_to_px( $val ) );
				if ( $px < 4 || $on_scale( $px ) || isset( $extras[ $px ] ) ) { continue; }
				$extras[ $px ] = array( 'name' => '[' . $px . 'px]', 'size' => $px . 'px' );
			}
		}
		// (b) COMPUTED grid/flex gap (`gap:Npx` in data-sc-cs) — non-Tailwind / visual-builder sources.
		if ( preg_match_all( '/data-sc-cs="([^"]*)"/i', (string) $html, $csm ) ) {
			foreach ( $csm[1] as $cs ) {
				if ( preg_match_all( '/(?:^|;)\s*(?:column-|row-)?gap\s*:\s*([0-9.]+)px/i', $cs, $gm ) ) {
					foreach ( $gm[1] as $raw ) {
						$px = (int) round( (float) $raw );
						if ( $px < 8 || $on_scale( $px ) || isset( $extras[ $px ] ) ) { continue; }
						$extras[ $px ] = array( 'name' => '[' . $px . 'px]', 'size' => $px . 'px' );
					}
				}
			}
		}
		ksort( $extras );
		return array_merge( $base, array_values( $extras ) );
	}

	/**
	 * From a `data-sc-cs` computed-style string, the VERTICAL spacing lengths in px — padding top/bottom
	 * and margin top/bottom — handling BOTH the longhand (`padding-top:…`) and, primarily, the `padding` /
	 * `margin` SHORTHAND (`T`, `T RL`, `T RL B`, `T R B L`) the capture stamps. Positive px values only
	 * (negatives / `auto` / var() skipped), so it mirrors the JS reading paddingTop/Bottom & marginTop/Bottom.
	 */
	private static function cs_vspace_px( $cs ) {
		$cs  = (string) $cs;
		$out = array();
		foreach ( array( 'padding', 'margin' ) as $box ) {
			$top = $bot = '';
			if ( preg_match( '/(?:^|;)\s*' . $box . '-top\s*:\s*([^;]+)/i', $cs, $m ) )    { $top = trim( $m[1] ); }
			if ( preg_match( '/(?:^|;)\s*' . $box . '-bottom\s*:\s*([^;]+)/i', $cs, $m ) ) { $bot = trim( $m[1] ); }
			if ( ( $top === '' || $bot === '' ) && preg_match( '/(?:^|;)\s*' . $box . '\s*:\s*([^;]+)/i', $cs, $m ) ) {
				$p = preg_split( '/\s+/', trim( $m[1] ) );
				$n = count( $p );
				$t = $p[0];
				$b = ( $n === 1 || $n === 2 ) ? $p[0] : $p[2]; // T | T RL | T RL B | T R B L → bottom = 3rd (or 1st when ≤2)
				if ( $top === '' ) { $top = $t; }
				if ( $bot === '' ) { $bot = $b; }
			}
			foreach ( array( $top, $bot ) as $v ) {
				if ( preg_match( '/^([0-9.]+)px$/', trim( (string) $v ), $mm ) ) { $out[] = (float) $mm[1]; }
			}
		}
		return $out;
	}

	/** A spacing length ('192px' | '3.5rem' | '2em') → approximate pixels (rem/em = ×16). 0 when unparseable. */
	private static function spacing_to_px( $v ) {
		$v = trim( (string) $v );
		if ( preg_match( '/^([0-9.]+)px$/', $v, $m ) )        { return (float) $m[1]; }
		if ( preg_match( '/^([0-9.]+)(rem|em)$/', $v, $m ) )  { return (float) $m[1] * 16; }
		return 0.0;
	}

	/**
	 * Derive BACKGROUND PATTERN presets (Theme Settings → Components → Background Patterns) from the source's
	 * decorative tiles — the PHP parity of the JS `to-presets.mjs` backgroundPatterns(). A pattern is a
	 * `bg-[url('data:image/svg…')]` (Tailwind arbitrary) OR a data-URI/repeating-gradient in a computed
	 * background-image (data-sc-cs). Deduped by image; emitted only when the source actually has one (else the
	 * default library stands). Shape mirrors unysonplus_default_pattern_presets(): { id, pattern_name,
	 * root_class, html, css }. Returns array( 'background_patterns' => [...] ) or array().
	 */
	/** A section's decorative background PATTERN ({ image, opacity }) from its own HTML — a
	 *  `bg-[url('data:image/svg…')]` Tailwind arbitrary or a data-URI/repeating-gradient computed background —
	 *  stashed on the section mapping so the mapper can overlay it. Null when the section has none. */
	private static function detect_section_pattern( $node ) {
		if ( ! ( $node instanceof DOMElement ) || ! $node->ownerDocument ) { return null; }
		$html = (string) $node->ownerDocument->saveHTML( $node );
		if ( '' === $html ) { return null; }
		// A section's DECORATIVE BACKDROP is very often a `::before` / `::after` overlay (a faint diagonal-stripe
		// `repeating-linear-gradient`, a data-URI SVG grid). getComputedStyle(el) — and therefore this deterministic
		// converter reading rendered.html — can NEVER see a pseudo-element, so the capture STAMPS it as
		// `data-sc-pattern` (image) + `data-sc-pattern-opacity` on the hosting block. Read that FIRST: it is the
		// faithful source that no inline style carries. (The inline/class checks below still cover a real element bg.)
		if ( preg_match( '/data-sc-pattern\s*=\s*(["\'])(.*?)\1/is', $html, $pm ) ) {
			$pimg = trim( html_entity_decode( $pm[2], ENT_QUOTES ) );
			if ( '' !== $pimg && 'none' !== strtolower( $pimg ) ) {
				$pop = 0.3;
				if ( preg_match( '/data-sc-pattern-opacity\s*=\s*(["\'])([0-9.]+)\1/i', $html, $pom ) ) { $pop = min( 1.0, (float) $pom[2] ); }
				$extra = ''; // the tile's size / blend (a dot grid's `background-size:32px 32px`, a `mix-blend-mode`)
				if ( preg_match( '/data-sc-pattern-extra\s*=\s*(["\'])([^"\']*)\1/i', $html, $pxm ) && preg_match( '/^[a-z0-9:;\s.%-]+$/i', $pxm[2] ) ) { $extra = trim( $pxm[2] ); }
				return array( 'image' => $pimg, 'opacity' => $pop, 'extra' => $extra );
			}
		}
		$img = '';
		if ( preg_match( '/bg-\[url\((?:&#0?39;|&quot;|[\'"])?(data:image\/svg[^)\'"]+?)(?:&#0?39;|&quot;|[\'"])?\)\]/i', $html, $m ) ) {
			$img = 'url("' . html_entity_decode( $m[1] ) . '")';
		} elseif ( preg_match( '/background-image:\s*(url\(\s*"?data:image\/svg[^")]+"?\s*\)|repeating-(?:linear|radial)-gradient\([^;"]+\))/i', $html, $m2 ) ) {
			$img = trim( $m2[1] );
		}
		if ( '' === $img ) { return null; }
		$op = 0.3;
		if ( preg_match( '/opacity-(\d{1,3})(?=\s|"|$)/', $html, $om ) ) { $op = min( 1.0, (int) $om[1] / 100 ); }
		elseif ( preg_match( '/opacity:\s*([0-9.]+)/', $html, $om2 ) ) { $op = min( 1.0, (float) $om2[1] ); }
		return array( 'image' => $img, 'opacity' => $op );
	}

	/**
	 * A section's SHAPE DIVIDER ({ placement, shape, height, color, flip }) from an edge-pinned SVG — the
	 * wave/tilt/curve/triangle band at a section's top or bottom. The theme has a native Section Divider
	 * option (top/bottom shape + height + flip + color), so the detector classifies the path silhouette
	 * against the built-in four and the mapper sets the option (NOT a preset). Null when the section has none.
	 *
	 * Classification is COARSE (curve-command count → wave/curve; line-only → triangle/tilt) — verified on a
	 * synthetic fixture; real-world robustness wants a source that actually uses dividers (see the kit doc).
	 */
	private static function detect_section_divider( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return null; }
		foreach ( $node->getElementsByTagName( 'svg' ) as $svg ) {
			// Climb up to the positioned wrapper; a divider is `absolute` + pinned to top-0 or bottom-0.
			$placement = ''; $flip = 'no';
			$w = $svg;
			for ( $i = 0; $i < 3 && ( $w instanceof DOMElement ); $i++ ) {
				$cls = self::cls( $w );
				$cs  = (string) $w->getAttribute( 'data-sc-cs' );
				$abs = ( strpos( $cls, 'absolute' ) !== false ) || ( strpos( $cs, 'position:absolute' ) !== false ) || ( strpos( $cs, 'position:fixed' ) !== false );
				if ( preg_match( '/(?:^|\s)-?scale-x-\[?-1|(?:^|\s)rotate-180|(?:^|\s)flip(?:-x)?\b/', $cls ) || strpos( $cs, 'scalex(-1)' ) !== false ) { $flip = 'yes'; }
				if ( $abs ) {
					if ( preg_match( '/(?:^|\s)-?top-0(?:\s|$)/', $cls ) || preg_match( '/(?:^|;)top:\s*0px/', $cs ) ) { $placement = 'top'; }
					elseif ( preg_match( '/(?:^|\s)-?bottom-0(?:\s|$)/', $cls ) || preg_match( '/(?:^|;)bottom:\s*0px/', $cs ) ) { $placement = 'bottom'; }
					break;
				}
				$w = $w->parentNode;
			}
			if ( '' === $placement ) { continue; } // full-bleed edge SVGs only, not an inline icon
			$path = $svg->getElementsByTagName( 'path' )->item( 0 );
			if ( ! $path ) { continue; }
			$d = (string) $path->getAttribute( 'd' );
			if ( '' === $d ) { continue; }
			$curves = preg_match_all( '/[CcSsQqTt]/', $d );
			if ( $curves >= 3 )      { $shape = 'wave'; }
			elseif ( $curves >= 1 )  { $shape = 'curve'; }
			else                     { $shape = ( preg_match_all( '/[Ll]/', $d ) >= 3 ) ? 'triangle' : 'tilt'; }
			// Height — svg `height` attr, else a Tailwind `h-N` on the svg/wrapper (N×4px).
			$height = '';
			if ( preg_match( '/^([0-9.]+)/', (string) $svg->getAttribute( 'height' ), $hm ) ) { $height = (string) (int) round( (float) $hm[1] ); }
			elseif ( preg_match( '/(?:^|\s)h-(\d+)(?:\s|$)/', self::cls( $svg ), $hm2 ) ) { $height = (string) ( (int) $hm2[1] * 4 ); }
			// Colour — the path fill (the divider's own colour).
			$fill = (string) $path->getAttribute( 'fill' );
			if ( '' === $fill || 'currentColor' === $fill ) { $fill = (string) $svg->getAttribute( 'fill' ); }
			$color = ( '' !== $fill && 'currentcolor' !== strtolower( $fill ) && 'none' !== strtolower( $fill ) ) ? self::color_to_hex( $fill ) : '';
			return array( 'placement' => $placement, 'shape' => $shape, 'height' => $height, 'color' => $color, 'flip' => $flip );
		}
		return null;
	}

	public static function build_background_patterns( $html ) {
		$html = (string) $html;
		if ( $html === '' ) { return array(); }
		// image-url => array( 'op' => opacity, 'bg' => preview background colour ). The preview_bg (editor-only)
		// is the resolved background COLOUR of the section the pattern sits on — a light/white mark captured from
		// a coloured band (the green section-9) is invisible on the editor's white preview, so we paint the row's
		// preview iframe with the band's colour to show the pattern in context. It is NEVER emitted into the
		// pattern's output CSS (the pattern stays a reusable overlay). Resolved via a DOM ancestor climb below.
		$found = array();
		$doc = new DOMDocument();
		$prev = libxml_use_internal_errors( true );
		$parsed = $doc->loadHTML( '<?xml encoding="utf-8"?>' . $html );
		libxml_clear_errors();
		libxml_use_internal_errors( $prev );
		if ( $parsed ) {
			$xp = new DOMXPath( $doc );
			foreach ( $xp->query( '//*[@class or @data-sc-cs]' ) as $el ) {
				if ( ! ( $el instanceof DOMElement ) ) { continue; }
				$cls     = self::cls( $el );
				// RAW class — base64 is CASE-SENSITIVE, so the data-URI must be read from the
				// original attribute, NOT the lowercased cls() (which mangles PHN2… → phn2…,
				// producing an undecodable SVG that renders blank). Class-NAME matching
				// (opacity-N below) still uses the lowercased $cls.
				$raw_cls = (string) $el->getAttribute( 'class' );
				$cs  = (string) $el->getAttribute( 'data-sc-cs' );
				$img = ''; $op = 1.0;
				// (a) Tailwind arbitrary `bg-[url('data:image/svg…')]` — the data-URI lives in the class.
				if ( preg_match( '/bg-\[url\((?:&#0?39;|&quot;|[\'"])?(data:image\/svg[^)\'"]+?)(?:&#0?39;|&quot;|[\'"])?\)\]/i', $raw_cls, $mm ) ) {
					$img = 'url("' . html_entity_decode( $mm[1] ) . '")';
					$op  = ( preg_match( '/(?:^|\s)opacity-(\d{1,3})(?:\s|$)/', $cls, $om ) ) ? min( 1.0, (int) $om[1] / 100 ) : 1.0;
				// (b) computed background-image (data-sc-cs) — a data-URI SVG or a repeating gradient.
				} elseif ( preg_match( '/background-image:\s*([^;]+)/i', $cs, $m2 ) ) {
					$bg = trim( $m2[1] );
					if ( ! preg_match( '/data:image\/svg|repeating-(?:linear|radial)-gradient/i', $bg ) ) { continue; }
					if ( strlen( $bg ) > 3000 ) { continue; }
					$img = $bg;
					$op  = ( preg_match( '/opacity:([0-9.]+)/', $cs, $om ) ) ? min( 1.0, (float) $om[1] ) : 1.0;
				}
				if ( '' === $img || isset( $found[ $img ] ) ) { continue; }
				$found[ $img ] = array( 'op' => $op, 'bg' => self::pattern_preview_bg( $el ) );
			}
		}
		// Fallback: raw string scan (no DOM / no computed styles) — keeps the old behaviour, preview_bg stays ''.
		if ( ! $found ) {
			if ( preg_match_all( '/class="([^"]*bg-\[url\((?:&#0?39;|&quot;|[\'"])?(data:image\/svg[^)\'"]+?)(?:&#0?39;|&quot;|[\'"])?\)\][^"]*)"/i', $html, $m, PREG_SET_ORDER ) ) {
				foreach ( $m as $mm ) {
					$img = 'url("' . html_entity_decode( $mm[2] ) . '")';
					$op  = ( preg_match( '/(?:^|\s)opacity-(\d{1,3})(?:\s|$)/', $mm[1], $om ) ) ? min( 1.0, (int) $om[1] / 100 ) : 1.0;
					if ( ! isset( $found[ $img ] ) ) { $found[ $img ] = array( 'op' => $op, 'bg' => '' ); }
				}
			}
			if ( preg_match_all( '/data-sc-cs="([^"]*background-image:([^;"]+)[^"]*)"/i', $html, $m2, PREG_SET_ORDER ) ) {
				foreach ( $m2 as $mm ) {
					$bg = trim( $mm[2] );
					if ( ! preg_match( '/data:image\/svg|repeating-(?:linear|radial)-gradient/i', $bg ) ) { continue; }
					if ( strlen( $bg ) > 3000 ) { continue; }
					if ( ! isset( $found[ $bg ] ) ) {
						$op = ( preg_match( '/opacity:([0-9.]+)/', $mm[1], $om ) ) ? min( 1.0, (float) $om[1] ) : 1.0;
						$found[ $bg ] = array( 'op' => $op, 'bg' => '' );
					}
				}
			}
		}
		if ( ! is_array( $found ) ) { $found = array(); }
		$out = array(); $n = 0; $used = array();
		// (1) Section-APPLIED patterns FIRST — a section references these by id (apply_section_pattern set its
		// Background Pattern option), so each MUST have a registered preset with the SAME deterministic id, or
		// the reference dangles. Emit them ahead of the scan set and outside the top-5 cap.
		if ( class_exists( 'FW_Site_Converter_Mapper' ) && ! empty( FW_Site_Converter_Mapper::captured( 'pattern' ) ) ) {
			foreach ( FW_Site_Converter_Mapper::captured( 'pattern' ) as $pid => $sp ) {
				$img = (string) ( $sp['image'] ?? '' );
				if ( '' === $img || isset( $used[ $img ] ) ) { continue; }
				$used[ $img ] = true;
				$op = isset( $sp['opacity'] ) ? (float) $sp['opacity'] : 1.0;
				$pv = ( isset( $found[ $img ] ) && is_array( $found[ $img ] ) ) ? (string) $found[ $img ]['bg'] : '';
				$out[] = self::pattern_preset_entry( (string) $pid, ++$n, $img, $op, $pv, (string) ( $sp['extra'] ?? '' ) );
			}
		}
		// (2) The remaining scanned patterns (not already applied to a section) — capped, deterministic id.
		foreach ( $found as $img => $info ) {
			if ( isset( $used[ $img ] ) ) { continue; }
			if ( $n >= 5 ) { break; }
			$op  = is_array( $info ) ? (float) $info['op'] : (float) $info;
			$pv  = is_array( $info ) ? (string) $info['bg'] : '';
			$pid = class_exists( 'FW_Site_Converter_Mapper' ) ? FW_Site_Converter_Mapper::pattern_id_for_image( $img ) : 'captured-' . substr( md5( $img ), 0, 8 );
			$used[ $img ] = true;
			$out[] = self::pattern_preset_entry( $pid, ++$n, $img, $op, $pv );
		}
		if ( ! $out ) { return array(); }
		// The importer REPLACES the whole option, so emit the captured patterns ON TOP of the plugin defaults —
		// otherwise the built-in pattern library is erased. (Same rule as Box Presets — converted first, defaults below.)
		$defaults = function_exists( 'unysonplus_default_pattern_presets' ) ? unysonplus_default_pattern_presets() : array();
		return array( 'background_patterns' => array_merge( $out, $defaults ) );
	}

	/** One Background Pattern preset entry ({id, pattern_name, root_class, html, css, preview_bg}). The id is
	 *  deterministic (pattern_id_for_image) so a section's applied-pattern reference resolves; $n is the display
	 *  index for the name. `preview_bg` is preview-only editor metadata and never enters the output `css`. */
	private static function pattern_preset_entry( $id, $n, $img, $op, $pv, $extra = '' ) {
		$cls   = 'pat-' . $id; // pat-captured-<hash>
		$decls = 'background-image:' . $img . ';' . ( $op < 1 ? 'opacity:' . $op . ';' : '' ) . ( '' !== (string) $extra ? trim( (string) $extra, ';' ) . ';' : '' );
		return array(
			'id'           => $id,
			'pattern_name' => 'Captured Pattern ' . $n,
			'root_class'   => $cls,
			'html'         => '<div class="' . $cls . '"></div>',
			'css'          => '.' . $cls . '{width:100%;height:100%;' . $decls . '}',
			'preview_bg'   => (string) $pv,
		);
	}

	/**
	 * Derive BOX PRESETS (Theme Settings → Components → Box Presets — the border_presets data model,
	 * the boxp-{slug} card skins) from the source's cards / containers / image frames. Walks every
	 * box-like element, compiles its Tailwind classes to CSS (border / corner radius / shadow + the
	 * hover shadow & lift), clusters the DISTINCT designs across the page, and appends the top few as
	 * named presets on top of the plugin defaults. Same DOM + Tailwind-compile pattern as
	 * build_section_style_presets()/build_button_presets(). Returns array( 'border_presets' => [...] ).
	 */
	public static function build_box_presets( $html ) {
		$html = (string) $html;
		if ( $html === '' || ! class_exists( 'FW_Site_Converter_Tailwind' ) ) { return array(); }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$body = null;
		foreach ( $dom->getElementsByTagName( 'body' ) as $b ) { $body = $b; break; }
		if ( ! $body ) { return array(); }

		$unit = function ( $v ) {
			$v = trim( (string) $v );
			return preg_match( '/^(-?[0-9.]+)\s*(px|rem|em|%)?$/', $v, $m )
				? array( 'value' => $m[1], 'unit' => ( isset( $m[2] ) && $m[2] !== '' ? $m[2] : 'px' ) )
				: array( 'value' => '', 'unit' => 'px' );
		};
		// Normalize a compiled Tailwind color (which may carry a `/ var(--tw-*-opacity)`) to a clean
		// rgb()/rgba() — or '' for transparent. Mirrors the section-preset color handling.
		$norm = function ( $c ) {
			$c = strtolower( trim( (string) $c ) );
			$has_var = ( strpos( $c, 'var(' ) !== false );
			if ( preg_match( '/rgba?\(\s*([0-9.]+)[,\s]+([0-9.]+)[,\s]+([0-9.]+)(?:[,\s\/]+([0-9.]+))?/', $c, $m ) ) {
				$a = ( ! $has_var && isset( $m[4] ) && $m[4] !== '' ) ? (float) $m[4] : 1.0;
				if ( $a === 0.0 ) { return ''; }
				return $a < 1 ? "rgba({$m[1]}, {$m[2]}, {$m[3]}, {$a})" : "rgb({$m[1]}, {$m[2]}, {$m[3]})";
			}
			if ( preg_match( '/^#([0-9a-f]{3}|[0-9a-f]{6})$/', $c, $m ) ) {
				$h = $m[1]; if ( strlen( $h ) === 3 ) { $h = $h[0] . $h[0] . $h[1] . $h[1] . $h[2] . $h[2]; }
				return 'rgb(' . hexdec( substr( $h, 0, 2 ) ) . ', ' . hexdec( substr( $h, 2, 2 ) ) . ', ' . hexdec( substr( $h, 4, 2 ) ) . ')';
			}
			// oklch()/oklab()/hsl() — the modern colour spaces AI-built sites use for card fills. The scan only
			// understood rgb()/#hex, so an oklch fill normalised to '' → the card failed the has-surface check →
			// NO preset was emitted → the mapper's box_style ref dangled → the card fell back to the theme default
			// (WHITE on a dark site: the-line's `.pillar-card` / `.metric-orb` use `oklch(0.16 … / 0.6)` fills).
			// color_to_hex() resolves the RGB (it already handles oklch/oklab/hsl); carry any alpha for translucency.
			if ( preg_match( '/^(?:oklch|oklab|hsla?|color)\(/', $c ) ) {
				$a = 1.0;
				if ( preg_match( '#/\s*([0-9.]+)(%?)\s*\)#', $c, $am ) ) { $a = ( '' !== $am[2] ) ? (float) $am[1] / 100 : (float) $am[1]; }
				elseif ( preg_match( '/hsla\(\s*[^,]+,\s*[^,]+,\s*[^,]+,\s*([0-9.]+)/', $c, $am ) ) { $a = (float) $am[1]; }
				if ( $a <= 0.0 ) { return ''; }
				$hex = self::color_to_hex( $c );
				if ( '' === $hex ) { return ''; }
				$hh = ltrim( $hex, '#' );
				$r = hexdec( substr( $hh, 0, 2 ) ); $g = hexdec( substr( $hh, 2, 2 ) ); $b = hexdec( substr( $hh, 4, 2 ) );
				return ( $a < 1 ) ? "rgba($r, $g, $b, $a)" : "rgb($r, $g, $b)";
			}
			return '';
		};
		// Parse the FIRST box-shadow layer into the preset's { x, y, blur, spread, color, inset } shape.
		// The native Box Shadow field holds ONE layer: split a (possibly multi-layer) box-shadow on its top-level
		// commas and pick the MOST VISIBLE layer — a non-inset drop shadow over an inset highlight, then the widest
		// blur. (Taking the FIRST layer gave a glass card's `inset 0 1px 0 …, 0 22px 60px …` only its 1px inset
		// highlight; the real drop was dropped.) The FULL multi-layer value rides in the preset CSS ($shadow_css) —
		// native first, the rest advanced — the same rule the button presets use.
		$shadow_layers = function ( $s ) use ( $norm ) {
			$s = trim( (string) $s );
			if ( $s === '' || strtolower( $s ) === 'none' ) { return array(); }
			$layers = array(); $depth = 0; $cur = '';
			for ( $i = 0, $len = strlen( $s ); $i < $len; $i++ ) {
				$ch = $s[ $i ];
				if ( $ch === '(' ) { $depth++; } elseif ( $ch === ')' ) { $depth--; }
				if ( $ch === ',' && $depth === 0 ) { $layers[] = $cur; $cur = ''; } else { $cur .= $ch; }
			}
			if ( trim( $cur ) !== '' ) { $layers[] = $cur; }
			$out = array();
			foreach ( $layers as $layer ) {
				$layer = trim( $layer );
				$inset = ( stripos( $layer, 'inset' ) !== false );
				$rest  = preg_replace( '/inset/i', '', $layer );
				$color = '';
				if ( preg_match( '/(rgba?\([^)]*\)|#[0-9a-fA-F]{3,8})/', $rest, $cm ) ) { $color = $norm( $cm[1] ); $rest = str_replace( $cm[1], '', $rest ); }
				if ( $color === '' ) { continue; } // transparent layer → skip
				$L = array();
				foreach ( preg_split( '/\s+/', trim( $rest ) ) as $tok ) { if ( preg_match( '/^(-?[0-9.]+)(?:px)?$/', $tok, $tm ) ) { $L[] = (int) round( (float) $tm[1] ); } }
				if ( ! array_filter( $L ) ) { continue; } // a 0 0 0 0 layer is no shadow
				$out[] = array( 'x' => $L[0] ?? 0, 'y' => $L[1] ?? 0, 'blur' => $L[2] ?? 0, 'spread' => $L[3] ?? 0, 'color' => $color, 'inset' => $inset, 'raw' => $layer );
			}
			return $out;
		};
		$parse_shadow = function ( $s ) use ( $shadow_layers ) {
			$cands = $shadow_layers( $s );
			if ( empty( $cands ) ) { return null; }
			usort( $cands, function ( $a, $b ) { if ( $a['inset'] !== $b['inset'] ) { return $a['inset'] ? 1 : -1; } return ( $b['blur'] + $b['spread'] ) <=> ( $a['blur'] + $a['spread'] ); } );
			$best = $cands[0]; unset( $best['raw'] );
			return $best;
		};
		// The FULL multi-layer shadow (>= 2 visible layers) as a preset-CSS rule, '' for a single layer (the
		// native field already carries it exactly). Whitelisted chars only (a plain rgba/px value).
		$shadow_css = function ( $s ) use ( $shadow_layers ) {
			$cands = $shadow_layers( $s );
			if ( count( $cands ) < 2 ) { return ''; }
			$full = implode( ', ', array_map( function ( $c ) { return $c['raw']; }, $cands ) );
			return preg_match( '/^[a-z0-9()%.,\s#-]+$/i', $full ) ? '{{SELECTOR}}{box-shadow:' . $full . ' !important;}' : '';
		};

		// Parse a data-sc-cs computed-style string into a { prop => value } map.
		$parse_cs = function ( $cs ) {
			$out = array();
			foreach ( explode( ';', (string) $cs ) as $d ) {
				$cp = strpos( $d, ':' );
				if ( $cp === false ) { continue; }
				$out[ trim( substr( $d, 0, $cp ) ) ] = trim( substr( $d, $cp + 1 ) );
			}
			return $out;
		};
		// The FIRST non-transparent box-shadow layer (a computed shadow often starts with a
		// `rgba(0,0,0,0) 0px 0px 0px 0px` placeholder layer that means "no shadow").
		// The MOST VISIBLE layer of a (multi-layer) box-shadow, raw — the cluster key and the native field's layer
		// (a non-inset drop over an inset highlight, then the widest blur). JS twin: firstRealShadow.
		$first_real_shadow = function ( $s ) use ( $shadow_layers ) {
			$c = $shadow_layers( $s );
			if ( empty( $c ) ) { return ''; }
			usort( $c, function ( $p, $q ) { if ( $p['inset'] !== $q['inset'] ) { return $p['inset'] ? 1 : -1; } return ( $q['blur'] + $q['spread'] ) <=> ( $p['blur'] + $p['spread'] ); } );
			return $c[0]['raw'];
		};

		$skip  = array( 'html', 'head', 'body', 'section', 'nav', 'header', 'footer', 'main', 'script', 'style', 'svg', 'path', 'button', 'a', 'input', 'select', 'textarea', 'img' );
		$boxes = array();
		foreach ( $body->getElementsByTagName( '*' ) as $node ) {
			if ( in_array( strtolower( $node->tagName ), $skip, true ) ) { continue; }
			$cs = (string) $node->getAttribute( 'data-sc-cs' );
			if ( $cs === '' ) { continue; }
			$d      = $parse_cs( $cs );
			$radius = ( isset( $d['border-radius'] ) && ! in_array( (string) $d['border-radius'], array( '', '0', '0px' ), true ) ) ? (string) $d['border-radius'] : '';
			$bw     = ( isset( $d['border-top-width'] ) && ! in_array( (string) $d['border-top-width'], array( '', '0', '0px' ), true ) ) ? (string) $d['border-top-width'] : '';
			$shadow = $first_real_shadow( isset( $d['box-shadow'] ) ? $d['box-shadow'] : '' );
			$fill   = isset( $d['background-color'] ) ? $norm( (string) $d['background-color'] ) : '';
			$backdrop = ( isset( $d['backdrop-filter'] ) && strtolower( (string) $d['backdrop-filter'] ) !== 'none' ) ? (string) $d['backdrop-filter'] : '';
			// A BOX PRESET is a CARD/PANEL/CHIP: it must be ROUNDED or SHADOWED (a square-cornered bare border
			// is a section/divider, not a card) AND carry a real surface (a fill, a border, or a shadow).
			$rounded_or_elev = ( $radius !== '' || $shadow !== '' || $backdrop !== '' );
			$has_surface     = ( $fill !== '' || $bw !== '' || $shadow !== '' || $backdrop !== '' );
			if ( ! $rounded_or_elev || ! $has_surface ) { continue; }
			// HOVER (no class dropped): the source's `hover:` utilities — fill / border / shadow / transform —
			// resolved via the Tailwind compiler + parsed transforms. Carried onto the preset's hover state.
			$cls = self::cls( $node );
			$hv  = array();
			if ( strpos( $cls, 'hover:' ) !== false ) {
				$c  = FW_Site_Converter_Tailwind::compile_class_set( $cls );
				$hb = isset( $c['hover'] ) ? $c['hover'] : array();
				if ( ! empty( $hb['background-color'] ) ) { $hv['fill']   = $norm( (string) $hb['background-color'] ); }
				if ( ! empty( $hb['border-color'] ) )     { $hv['bdcol']  = $norm( (string) $hb['border-color'] ); }
				$hsh = $first_real_shadow( isset( $hb['box-shadow'] ) ? $hb['box-shadow'] : '' );
				if ( $hsh !== '' ) { $hv['shadow'] = $hsh; }
				// Transforms: lift (translate-y) is a native hover_fx; scale / other transforms go to custom_css.
				if ( preg_match( '/hover:-?translate-y-(\[[^\]]+\]|[0-9.]+)/', $cls, $tm ) ) { $hv['lift'] = true; }
				if ( preg_match( '/hover:scale-(\d+)/', $cls, $sm ) ) { $hv['scale'] = (int) $sm[1] / 100; }
			}
			$boxes[] = array(
				'fill'     => $fill,
				'radius'   => $radius,
				'bw'       => $bw,
				'bdcol'    => isset( $d['border-top-color'] ) ? $norm( (string) $d['border-top-color'] ) : '',
				'shadow'   => $shadow,
				'shadow_full' => isset( $d['box-shadow'] ) ? trim( (string) $d['box-shadow'] ) : '', // every layer, for the preset CSS
				'backdrop' => $backdrop,
				'hover'    => $hv,
				'hov'      => (string) $node->getAttribute( 'data-sc-hover' ),
				'kf'       => (string) $node->getAttribute( 'data-sc-keyframes' ),
				'pseudoOwned' => $node->hasAttribute( 'data-sc-decor-pseudo' ),
			);
		}
		// Don't bail on an empty scan when the mapper REGISTERED boxes (a class-only source has no data-sc-cs
		// boxes to scan, but its columns still assigned box presets that MUST be emitted below).
		$_has_reg = ( class_exists( 'FW_Site_Converter_Mapper' ) && ! empty( FW_Site_Converter_Mapper::captured( 'box' ) ) );
		if ( empty( $boxes ) && ! $_has_reg ) { return array(); }

		// Cluster the distinct box designs by their FULL skin (fill INCLUDED, so a red-tint card and a green-tint
		// card don't merge) — keep the most common dozen (every meaningful kind, not just the top 5).
		$groups = array();
		foreach ( $boxes as $bx ) {
			$key = $bx['fill'] . '|' . $bx['radius'] . '|' . preg_replace( '/\s+/', '', $bx['shadow'] ) . '|' . $bx['bw'] . '|' . $bx['bdcol'] . '|' . preg_replace( '/\s+/', '', $bx['backdrop'] ) . '|' . md5( (string) $bx['hov'] ); // distinct states → distinct presets
			if ( ! isset( $groups[ $key ] ) ) { $groups[ $key ] = array_merge( $bx, array( 'count' => 0 ) ); }
			$groups[ $key ]['count']++;
			// Prefer a group member that actually carries hover data.
			if ( ! empty( $bx['hover'] ) && empty( $groups[ $key ]['hover'] ) ) { $groups[ $key ]['hover'] = $bx['hover']; }
		}
		uasort( $groups, function ( $a, $b ) { return $b['count'] - $a['count']; } );
		$groups = array_slice( $groups, 0, 12, true );

		$empty = array( 'predefined' => '', 'custom' => '' );
		$u0    = array( 'value' => '', 'unit' => 'px' );
		$pad0  = array(
			'margin'  => array( 'all' => '', 'top' => '', 'right' => '', 'bottom' => '', 'left' => '' ),
			'padding' => array( 'all' => '', 'top' => '', 'right' => '', 'bottom' => '', 'left' => '' ),
		);
		// A background-pro SOLID fill value (mirrors the section-style / topbar fill shape used elsewhere).
		// Background-Pro fill value. A card GRADIENT maps to the native `gradient.data` sub-field (parsed to
		// {type,angle,stops}), layered over the colour fallback — so a gradient card is a real Box Preset, not
		// scoped CSS (docs: "the box is ALWAYS a real Box Preset"). Mirrors the button preset's Background Gradient.
		$fill_val = function ( $rgba, $gradient = '' ) {
			$bg = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => ( $rgba !== '' ? $rgba : '' ) ) ) );
			if ( '' !== (string) $gradient && class_exists( 'FW_Site_Converter_Mapper' ) ) {
				$gv = FW_Site_Converter_Mapper::parse_linear_gradient( (string) $gradient );
				if ( is_array( $gv ) ) { $bg['gradient'] = array( 'data' => $gv ); }
			}
			return $bg;
		};
		$used = array(); $n = 0; $derived = array();
		foreach ( $groups as $g ) {
			$has_shadow = ( $g['shadow'] !== '' );
			$has_border = ( $g['bw'] !== '' );
			$has_fill   = ( $g['fill'] !== '' );
			$has_glass  = ( $g['backdrop'] !== '' );
			// Auto-name from the skin (the local-AI naming pass refines these later): Glass, Card (fill+border),
			// Tinted (fill only), Elevated (shadow), Outline (border), Rounded.
			$base = $has_glass ? 'Glass' : ( ( $has_fill && $has_border ) ? 'Card' : ( $has_shadow ? 'Elevated' : ( $has_border ? 'Outline' : ( $has_fill ? 'Tinted' : 'Rounded' ) ) ) );
			$used[ $base ] = ( isset( $used[ $base ] ) ? $used[ $base ] : 0 ) + 1;
			$name = $used[ $base ] > 1 ? $base . ' ' . $used[ $base ] : $base;

			// DEFAULT state: fill + border + shadow.
			$default = array( 'background' => $fill_val( $g['fill'] ) );
			if ( $has_border ) {
				$default['border_style'] = 'solid';
				$default['border_width'] = $unit( $g['bw'] );
				$default['border_color'] = $g['bdcol'] !== '' ? array( 'predefined' => '', 'custom' => $g['bdcol'] ) : $empty;
			}
			$sh = $parse_shadow( $g['shadow'] );
			if ( $sh ) { $default['box_shadow'] = $sh; }

			// HOVER state (no class dropped): fill / border / shadow changes.
			$hv    = is_array( $g['hover'] ) ? $g['hover'] : array();
			$hover = array();
			if ( ! empty( $hv['fill'] ) )  { $hover['background']   = $fill_val( $hv['fill'] ); }
			if ( ! empty( $hv['bdcol'] ) ) { $hover['border_color'] = array( 'predefined' => '', 'custom' => $hv['bdcol'] ); }
			$hsh = $parse_shadow( isset( $hv['shadow'] ) ? $hv['shadow'] : '' );
			if ( $hsh ) { $hover['box_shadow'] = $hsh; }

			$hover_fx = array();
			if ( ! empty( $hv['lift'] ) )                { $hover_fx[] = 'lift'; }
			if ( ! empty( $hv['shadow'] ) || $hsh )      { $hover_fx[] = 'glow'; }

			// custom_css (tier-3, no native field): the frosted backdrop-filter + a hover SCALE the structured
			// options can't express. Scoped to {{SELECTOR}} = the preset's `.boxp-<slug>`.
			$ccss = '';
			if ( $has_glass )              { $ccss .= '{{SELECTOR}}{backdrop-filter:' . $g['backdrop'] . ';-webkit-backdrop-filter:' . $g['backdrop'] . ';}'; }
			// MULTI-LAYER shadow (an inset highlight + a drop): the native field holds the most visible layer; the full
			// value rides in the preset CSS so the card keeps both (native first, the rest advanced — as buttons do).
			$ccss .= $shadow_css( isset( $g['shadow_full'] ) ? $g['shadow_full'] : $g['shadow'] );
			if ( ! empty( $hv['scale'] ) ) { $ccss .= '{{SELECTOR}}:hover{transform:scale(' . $hv['scale'] . ');}'; }
			// A NON-LINEAR fill (a radial / conic gradient, or several layers) has no native gradient field (the
			// Background-Pro gradient is linear-only) → the preset CSS carries it verbatim, so a radial ring keeps its fill.
			$gfill = trim( (string) ( $g['gradient'] ?? '' ) );
			if ( '' !== $gfill && class_exists( 'FW_Site_Converter_Mapper' ) && ! is_array( FW_Site_Converter_Mapper::parse_linear_gradient( $gfill ) )
				&& preg_match( '/^[a-z0-9()%.,\s#-]+$/i', $gfill ) ) { $ccss .= '{{SELECTOR}}{background-image:' . $gfill . ';}'; }

			$states = array( 'default' => $default );
			if ( $hover ) { $states['hover'] = $hover; }
			$scan_state_css = self::state_css( (string) ( $g['hov'] ?? '' ), (string) ( $g['kf'] ?? '' ), ! empty( $g['pseudoOwned'] ), array( 'background-color', 'background', 'border-color', 'box-shadow' ) );
			if ( '' !== $scan_state_css ) { $ccss = trim( $ccss . "\n" . $scan_state_css ); }

			$derived[] = array(
				'id'            => 'b' . str_pad( (string) ( 100 + ( ++$n ) ), 9, '0', STR_PAD_LEFT ),
				'preset_name'   => $name,
				'border_sides'  => 'all',
				'border_radius' => $g['radius'] !== '' ? $unit( $g['radius'] ) : $u0,
				'padding'       => $pad0,
				'transition'    => '200',
				'hover_fx'      => array_values( array_unique( $hover_fx ) ),
				'custom_css'    => $ccss,
				'states'        => $states,
				// Skin MATCH KEY (fill|radius|border) — used to build the assignment lookup so the mapper can point
				// a matching box element at this preset. Border colour only counts when there's a real border
				// width (a borderless box always carries a computed border-color that would pollute the key).
				'_mkey'         => $g['fill'] . '|' . $g['radius'] . '|' . $g['bw'] . '|' . ( $g['bw'] !== '' ? $g['bdcol'] : '' ),
			);
		}
		// REGISTERED boxes — skins the mapper ASSIGNED to a column/card via register_box_preset() (its
		// border_preset = `boxp-<slug>`). These MUST become presets or the reference dangles — and unlike the
		// scan above they work on a class-only source (no data-sc-cs). Named "Box <hash>" so the slugified name
		// equals the mapper's slug (`box-<hash>`). Runs AFTER build_pages (theme-settings pass), so $card_boxes
		// is populated. Deduped by slug (same skin → one preset, referenced by every column that uses it).
		$reg = array();
		if ( class_exists( 'FW_Site_Converter_Mapper' ) && ! empty( FW_Site_Converter_Mapper::captured( 'box' ) ) ) {
			foreach ( FW_Site_Converter_Mapper::captured( 'box' ) as $slug => $sk ) {
				if ( ! is_array( $sk ) ) { continue; }
				$default = array( 'background' => $fill_val( (string) ( $sk['bg'] ?? '' ), (string) ( $sk['gradient'] ?? '' ) ) );
				if ( '' !== (string) ( $sk['bw'] ?? '' ) ) {
					$default['border_style'] = 'solid';
					$default['border_width'] = $unit( (string) $sk['bw'] );
					$default['border_color'] = ( '' !== (string) ( $sk['bd'] ?? '' ) ) ? array( 'predefined' => '', 'custom' => (string) $sk['bd'] ) : $empty;
				}
				$rsh0 = $parse_shadow( (string) ( $sk['shadow'] ?? '' ) ); // resting box-shadow → native Box Shadow field
				if ( $rsh0 ) { $default['box_shadow'] = $rsh0; }
				// The card's inner padding rides IN the preset, so the box pads the WHOLE card — incl. a decomposed
				// feature_list on the column — not just the icon_box header. Emitted via the preset's own custom_css
				// (exact source px, no scale snapping) WITHOUT !important, so a column's own Padding can still
				// override it. Blank → no padding rule.
				$reg_pad_px  = trim( (string) ( $sk['padding'] ?? '' ) );
				$reg_pad_css = ( '' !== $reg_pad_px && preg_match( '/^[0-9.]+px(?:\s+[0-9.]+px){0,3}$/', $reg_pad_px ) ) ? '{{SELECTOR}}{padding:' . $reg_pad_px . ';box-sizing:border-box;}' : ''; // 1–4 value shorthand
				// HOVER state — the card's captured `hover:bg-*`/border/shadow + lift/scale (e.g. a glass card's
				// `hover:bg-slate-800/80`) → the preset's hover state + hover_fx, so the source card's hover
				// survives. A scale (`group-hover:scale`) has no native field → the preset's own custom_css.
				$reg_hover = array(); $reg_hover_fx = array(); $reg_hover_css = '';
				$rhv = is_array( $sk['hover'] ?? null ) ? $sk['hover'] : array();
				if ( '' !== (string) ( $rhv['bg'] ?? '' ) ) { $reg_hover['background']   = $fill_val( (string) $rhv['bg'] ); }
				if ( '' !== (string) ( $rhv['bd'] ?? '' ) ) { $reg_hover['border_color'] = array( 'predefined' => '', 'custom' => (string) $rhv['bd'] ); }
				$rhsh = $parse_shadow( (string) ( $rhv['shadow'] ?? '' ) );
				if ( $rhsh ) { $reg_hover['box_shadow'] = $rhsh; }
				// The card's captured hover MOTION → the SHARED Hover Animations library (the same native effects a
				// button gets, editable in the preset's Hover Animation picker): a grow (`group-hover:scale`) → Grow;
				// a lift → Lift. FIDELITY GUARD (as for buttons): the cloned Lift forces a hover drop-shadow, so a
				// card that keeps its own resting shadow with no hover shadow change keeps the plain `hover_fx` lift
				// (a bare translateY) instead — the library must never add chrome the source lacks.
				$reg_anim = '';
				if ( ! empty( $rhv['scale'] ) && (float) $rhv['scale'] > 1.0 ) { $reg_anim = 'btnfx-grow'; }
				elseif ( ! empty( $rhv['lift'] ) ) {
					$rest_sh = trim( (string) ( $sk['shadow'] ?? '' ) );
					$has_rest_shadow = ( '' !== $rest_sh && 'none' !== strtolower( $rest_sh ) && preg_match( '/[1-9]/', $rest_sh ) );
					if ( $rhsh || ! $has_rest_shadow ) { $reg_anim = 'btnfx-lift'; }
				}
				// EXACT over library: a CAPTURED hover transform (data-sc-hover `hover-self{transform:…}`) rides the preset CSS verbatim
				// (state_css below) — a -3px lift stays -3px, a rotate stays a rotate — and no Lift / Grow is substituted on top.
				$reg_exact_tf = (bool) preg_match( '/hover-self\{[^}]*transform\s*:/i', (string) ( $sk['hov'] ?? '' ) );
				if ( $reg_exact_tf ) { $reg_anim = ''; }
				if ( ! empty( $rhv['lift'] ) && 'btnfx-lift' !== $reg_anim && ! $reg_exact_tf ) { $reg_hover_fx[] = 'lift'; }
				if ( $rhsh )                   { $reg_hover_fx[] = 'glow'; }
				if ( ! empty( $rhv['scale'] ) && 'btnfx-grow' !== $reg_anim && ! $reg_exact_tf ) { $reg_hover_css = '{{SELECTOR}}:hover{transform:scale(' . (float) $rhv['scale'] . ');}'; }
				// FROSTED GLASS — the card's `backdrop-filter: blur()` has no native Box-Preset field, so carry it
				// via the preset's own custom_css (applies to every element using this box). The translucent fill
				// then reads as real frosted glass. Whitelisted chars only (a `blur(Npx)`-shape value).
				$reg_bf     = trim( (string) ( $sk['backdrop'] ?? '' ) );
				$reg_bf_css = ( '' !== $reg_bf && preg_match( '/^[a-z0-9()%.\s,-]+$/i', $reg_bf ) )
					? '{{SELECTOR}}{-webkit-backdrop-filter:' . $reg_bf . ';backdrop-filter:' . $reg_bf . ';}'
					: '';
				// MEDIA FRAME — a rounded box around an image / video clips its content to the radius (the source's
				// `overflow:hidden`); no native field, so it rides in the preset CSS (a tile preset, distinct slug).
				if ( ! empty( $sk['clip'] ) ) { $reg_bf_css .= '{{SELECTOR}}{overflow:hidden;}'; }
				// a PER-CORNER radius (`rounded-t-[20px]` → `20px 20px 0px 0px`: the first row of a stacked list) has no single-value
				// field — the preset's CSS carries it; the single field stayed empty and the corners went square (a fixture from the feed)
				$reg_rad = trim( (string) ( $sk['radius'] ?? '' ) );
				if ( '' !== $reg_rad && '' === (string) ( $unit( $reg_rad )['value'] ?? '' ) && preg_match( '/^[0-9.]+(?:px|rem|em|%)?(?:\s+[0-9.]+(?:px|rem|em|%)?){1,3}$/', $reg_rad ) ) { $reg_bf_css .= '{{SELECTOR}}{border-radius:' . $reg_rad . ';}'; }
				// The long tail of box-level visual props (Stitch box_extra_css: opacity / filter / clip / mask / blend /
				// outline / side border / border-image / bg geometry / transforms / sticky) → the preset's own CSS.
				$reg_extra = trim( (string) ( $sk['extra'] ?? '' ) );
				if ( '' !== $reg_extra && preg_match( '/^[a-z0-9()%.,:;\s#\/+!-]+$/i', $reg_extra ) ) { $reg_bf_css .= '{{SELECTOR}}{' . $reg_extra . ';}'; } // (`!important` allowed: a side colour must outrank the preset's own `border` rule)
				$reg_bf_css .= $shadow_css( (string) ( $sk['shadow'] ?? '' ) ); // multi-layer shadow → full value in the preset CSS
				// A NON-LINEAR fill (radial / conic / several layers) has no native gradient field (Background-Pro is
				// linear-only) → the preset CSS carries it verbatim, so a radial ring keeps its fill (parity with the scan above).
				$reg_grad = trim( (string) ( $sk['gradient'] ?? '' ) );
				if ( '' !== $reg_grad && ! is_array( FW_Site_Converter_Mapper::parse_linear_gradient( $reg_grad ) ) && preg_match( '/^[a-z0-9()%.,\s#-]+$/i', $reg_grad ) ) {
					$reg_bf_css .= '{{SELECTOR}}{background-image:' . $reg_grad . ';}';
				}
				$reg_states = array( 'default' => $default );
				if ( $reg_hover ) { $reg_states['hover'] = $reg_hover; }
				$reg[] = array(
					'id'            => 'r' . substr( md5( (string) $slug ), 0, 8 ),
					'preset_name'   => 'Box ' . substr( (string) $slug, 4 ), // slug `box-<hash>` → name "Box <hash>" → slugifies back to the slug
					'border_sides'  => ( ! empty( $sk['sides'] ) && 'all' !== $sk['sides'] ) ? (string) $sk['sides'] : 'all', // a one-sided hairline keeps its side
					'border_radius' => ( '' !== (string) ( $sk['radius'] ?? '' ) ) ? $unit( (string) $sk['radius'] ) : $u0,
					'padding'       => $pad0,
					'transition'    => '200',
					'hover_animation' => $reg_anim, // the shared library's native effect (Lift / Grow), when the source's hover is one
					'hover_fx'      => array_values( array_unique( $reg_hover_fx ) ),
					'custom_css'    => trim( $reg_pad_css . $reg_hover_css . $reg_bf_css . ( '' !== ( $reg_state_css = self::state_css( (string) ( $sk['hov'] ?? '' ), (string) ( $sk['kf'] ?? '' ), ! empty( $sk['pseudoOwned'] ), array( 'background-color', 'background', 'border-color', 'box-shadow' ) ) ) /* the exact hover transform rides the CSS unless a native lift / grow already carries it */ ? "\n" . $reg_state_css : '' ) ),
					'states'        => $reg_states,
				);
			}
		}
		if ( empty( $derived ) && empty( $reg ) ) { return array(); }

		// Site-specific presets go ON TOP of the plugin defaults (the converted design system is primary — a
		// user picks a site-matching box first — while the built-in Card/Outline/… library stays available below).
		$base_presets = function_exists( 'unysonplus_default_border_presets' ) ? unysonplus_default_border_presets() : array();
		$all = array_merge( $derived, $reg, $base_presets );
		// Assignment LOOKUP: skin match-key → the `.boxp-<slug>` slug (derived from preset_name, deduped IN ORDER
		// across the whole list — exactly like unysonplus_border_preset_slug_map()), so the mapper can set a box
		// element's border_preset/box_style to a real, matching preset instead of one-off CSS.
		$seen = array(); $slug_of = array();
		foreach ( $all as $bp ) {
			$id = preg_replace( '/[^a-zA-Z0-9_-]/', '', (string) ( $bp['id'] ?? '' ) );
			if ( $id === '' ) { continue; }
			$slug = trim( preg_replace( '/[^a-z0-9]+/', '-', strtolower( (string) ( $bp['preset_name'] ?? '' ) ) ), '-' );
			if ( $slug === '' ) { $slug = $id; }
			$base = $slug; $k = 1;
			while ( isset( $seen[ $slug ] ) ) { $k++; $slug = $base . '-' . $k; }
			$seen[ $slug ] = true; $slug_of[ $id ] = $slug;
		}
		$lookup = array();
		foreach ( $derived as $dp ) { if ( isset( $slug_of[ $dp['id'] ] ) ) { $lookup[ $dp['_mkey'] ] = $slug_of[ $dp['id'] ]; } }
		foreach ( $all as &$bp ) { unset( $bp['_mkey'] ); } unset( $bp );
		return array( 'border_presets' => $all, 'box_lookup' => $lookup );
	}

	/**
	 * Derive TEXT STYLES (Theme Settings → Components → Text Styles — the `font_sizes` key: named
	 * size + weight + line-height + letter-spacing + transform utilities). Reads the source's headings
	 * (h1–h6) for the DISPLAY size scale (largest rendered size per level, across breakpoints) and
	 * detects the distinctive EYEBROW/overline treatment (uppercase + tracking). Emits a faithful
	 * `font_sizes` scale: Display 1..N (class display-N) + Lead + Eyebrow. Same DOM+Tailwind pattern
	 * as build_box_presets(). Returns array( 'font_sizes' => [...] ).
	 */
	public static function build_text_styles( $html ) {
		$html = (string) $html;
		if ( $html === '' || ! class_exists( 'FW_Site_Converter_Tailwind' ) ) { return array(); }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$body = null;
		foreach ( $dom->getElementsByTagName( 'body' ) as $b ) { $body = $b; break; }
		if ( ! $body ) { return array(); }

		$to_px = function ( $v ) {
			$v = trim( (string) $v );
			if ( $v === '' ) { return null; }
			if ( preg_match( '/^(-?[0-9.]+)(rem|em)$/', $v, $m ) ) { return (float) $m[1] * 16; }
			if ( preg_match( '/^(-?[0-9.]+)px$/', $v, $m ) ) { return (float) $m[1]; }
			if ( preg_match( '/^(-?[0-9.]+)$/', $v ) ) { return (float) $v; }
			return null;
		};

		// --- Display scale from headings: the largest rendered size (across base/md/lg) per heading. ---
		$disp = array();
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $ht ) {
			foreach ( $body->getElementsByTagName( $ht ) as $hn ) {
				$c = FW_Site_Converter_Tailwind::compile_class_set( self::cls( $hn ) );
				$size = null; $weight = ''; $lh = '';
				foreach ( array( 'base', 'md', 'lg' ) as $bp ) {
					if ( ! isset( $c[ $bp ] ) || ! is_array( $c[ $bp ] ) ) { continue; }
					$bk = $c[ $bp ];
					if ( isset( $bk['font-size'] ) ) {
						$px = $to_px( $bk['font-size'] );
						if ( $px !== null && ( $size === null || $px > $size ) ) {
							$size   = $px;
							$weight = isset( $bk['font-weight'] ) ? (string) $bk['font-weight'] : $weight;
							$lh     = isset( $bk['line-height'] ) ? (string) $bk['line-height'] : $lh;
						}
					}
				}
				$bb = isset( $c['base'] ) ? $c['base'] : array();
				if ( $weight === '' && isset( $bb['font-weight'] ) ) { $weight = (string) $bb['font-weight']; }
				if ( $lh === '' && isset( $bb['line-height'] ) ) { $lh = (string) $bb['line-height']; }
				if ( $size === null || $size < 20 ) { continue; } // ignore tiny / unstyled headings
				$key = (string) (int) round( $size );
				if ( ! isset( $disp[ $key ] ) ) { $disp[ $key ] = array( 'size' => (int) round( $size ), 'weight' => $weight, 'lh' => $lh, 'count' => 0 ); }
				$disp[ $key ]['count']++;
			}
		}
		uasort( $disp, function ( $a, $b ) { return $b['size'] - $a['size']; } ); // largest first

		// --- Eyebrow / overline: uppercase + letter-spacing (tracking), most common instance. ---
		$eye = null; $eye_best = -1;
		foreach ( $body->getElementsByTagName( '*' ) as $node ) {
			$cls = self::cls( $node );
			if ( $cls === '' || ! preg_match( '/uppercase/i', $cls ) || ! preg_match( '/tracking|letter/i', $cls ) ) { continue; }
			$c = FW_Site_Converter_Tailwind::compile_class_set( $cls );
			$b = isset( $c['base'] ) ? $c['base'] : array();
			if ( ( isset( $b['text-transform'] ) ? $b['text-transform'] : '' ) !== 'uppercase' ) { continue; }
			$ls = isset( $b['letter-spacing'] ) ? (string) $b['letter-spacing'] : '';
			if ( $ls === '' ) { continue; }
			$sz = isset( $b['font-size'] ) ? $to_px( $b['font-size'] ) : null;
			// Prefer a SMALL eyebrow (overlines are small); keep the smallest-sized candidate.
			$score = ( $sz !== null ) ? ( 1000 - $sz ) : 0;
			if ( $score > $eye_best ) {
				$eye_best = $score;
				$eye = array(
					'size'   => $sz !== null ? (string) (int) round( $sz ) : '',
					'weight' => isset( $b['font-weight'] ) ? (string) $b['font-weight'] : '',
					'ls'     => $ls,
				);
			}
		}

		// --- BODY SCALE from PARAGRAPHS (data-sc-cs): distill the source's non-base body type roles
		// (Lead / Subtitle / Small / Caption) so a converted text block references an editable Text Style
		// preset instead of a frozen per-element size. Length-weighted per rounded-px size (mirrors
		// detect_typography's dominant-size approach): the DOMINANT size = the body base (16) → NO preset;
		// each distinct non-base size carrying meaningful total text → a stable-classed preset. ---
		$lh_ratio = function ( $lh, $size ) {
			$lh = trim( (string) $lh ); $size = (float) $size;
			if ( $lh === '' || strtolower( $lh ) === 'normal' || $size <= 0 ) { return ''; }
			if ( preg_match( '/^([0-9.]+)px$/', $lh, $m ) ) { return (string) round( ( (float) $m[1] ) / $size, 2 ); }
			if ( preg_match( '/^([0-9.]+)$/', $lh, $m ) ) { return (string) round( (float) $m[1], 2 ); }
			return '';
		};
		$ls_px = function ( $ls ) {
			$ls = trim( (string) $ls );
			if ( $ls === '' || strtolower( $ls ) === 'normal' ) { return ''; }
			// Computed letter-spacing is ALWAYS in px. Keep the `px` UNIT — the Text Style consumer reads a
			// BARE number as em (so "0.5" would render 0.5em = 10px on 20px text, wildly tracked out). The
			// source's real 0.5px must stay 0.5px, so emit the unit explicitly.
			if ( preg_match( '/^(-?[0-9.]+)px$/', $ls, $m ) ) { $v = round( (float) $m[1], 2 ); return abs( $v ) < 0.01 ? '' : ( $v . 'px' ); }
			return '';
		};
		$wt_norm = function ( $w ) {
			$w = strtolower( trim( (string) $w ) );
			if ( preg_match( '/^[1-9]00$/', $w ) ) { return $w; }
			if ( $w === 'bold' ) { return '700'; }
			if ( $w === 'normal' ) { return '400'; }
			return '';
		};
		$blen = array(); $brep = array(); $breplen = array();
		foreach ( $body->getElementsByTagName( 'p' ) as $p ) {
			$cs = ( $p instanceof DOMElement ) ? (string) $p->getAttribute( 'data-sc-cs' ) : '';
			if ( $cs === '' ) { continue; }
			$sz = self::sc_css( $p, 'font-size' );
			if ( ! preg_match( '/^([0-9.]+)px$/', trim( (string) $sz ), $m ) ) { continue; }
			$px  = (int) round( (float) $m[1] );
			$len = strlen( trim( self::text( $p ) ) );
			if ( $len <= 0 ) { continue; }
			$blen[ $px ] = ( isset( $blen[ $px ] ) ? $blen[ $px ] : 0 ) + $len;
			if ( $len > ( isset( $breplen[ $px ] ) ? $breplen[ $px ] : 0 ) ) { $breplen[ $px ] = $len; $brep[ $px ] = $p; }
		}
		$body_presets = array();
		if ( ! empty( $blen ) ) {
			arsort( $blen );                       // most total body text first
			$base_px = (int) array_key_first( $blen );
			unset( $blen[ $base_px ] );            // the dominant size = the base = no preset
			$disp_sizes = array();
			foreach ( $disp as $dd ) { $disp_sizes[ (int) $dd['size'] ] = true; }
			$MIN_TEXT = 24;                        // meaningful total text (chars) to earn a preset
			// LEAD: the representative lead size = the non-base size >= 19 carrying the MOST text (fallback 20).
			$lead_px = null; $lead_len = -1;
			foreach ( $blen as $px => $len ) { if ( $px >= 19 && $len > $lead_len ) { $lead_px = $px; $lead_len = $len; } }
			$lead_size = ( $lead_px !== null ) ? $lead_px : 20;
			$rep_meta = function ( $px ) use ( $brep, $lh_ratio, $ls_px, $wt_norm ) {
				$out = array( 'w' => '', 'lh' => '', 'ls' => '', 'color' => '' );
				if ( ! isset( $brep[ $px ] ) ) { return $out; }
				$r = $brep[ $px ];
				$out['w']  = $wt_norm( self::sc_css( $r, 'font-weight' ) );
				$out['lh'] = $lh_ratio( self::sc_css( $r, 'line-height' ), $px );
				$out['ls'] = $ls_px( self::sc_css( $r, 'letter-spacing' ) );
				// Carry the part's colour into the Text Style only when it's a DISTINCTIVE MID-TONE (a muted
				// grey / accent), NOT a near-white or near-black — those are just the body ink, which the
				// element inherits. So a muted subtitle keeps its muted tone; a body-coloured one stays blank.
				$c = self::color_to_hex( (string) self::sc_css( $r, 'color' ) );
				if ( $c !== '' && ! self::is_near_bw( $c ) ) { $out['color'] = $c; }
				return $out;
			};
			$lm = $rep_meta( $lead_px !== null ? $lead_px : -1 );
			$body_presets[] = array( 'order' => $lead_size, 'name' => 'Lead', 'size' => $lead_size, 'weight' => ( $lm['w'] === '400' ? '' : $lm['w'] ), 'lh' => $lm['lh'], 'ls' => $lm['ls'], 'color' => $lm['color'], 'class' => 'lead' );
			// SUBTITLE (17–18) / SMALL (13–15) / CAPTION (11–12): one preset per bucket, the size with most text.
			$buckets = array(); // class => { name, size, len }
			foreach ( $blen as $px => $len ) {
				if ( $len < $MIN_TEXT ) { continue; }
				if ( $px === $lead_px ) { continue; }          // already the Lead
				if ( $px >= 19 ) { continue; }                  // lead-range handled above
				if ( isset( $disp_sizes[ $px ] ) ) { continue; } // de-dupe: a size that's also a heading Display
				if ( $px >= 17 )      { $name = 'Subtitle'; $class = 'font-subtitle'; }
				elseif ( $px >= 13 )  { $name = 'Small';    $class = 'font-small'; }
				elseif ( $px >= 11 )  { $name = 'Caption';  $class = 'font-caption'; }
				else { continue; }
				if ( ! isset( $buckets[ $class ] ) || $len > $buckets[ $class ]['len'] ) {
					$buckets[ $class ] = array( 'name' => $name, 'size' => $px, 'len' => $len );
				}
			}
			foreach ( $buckets as $class => $bk ) {
				$m2 = $rep_meta( $bk['size'] );
				$body_presets[] = array( 'order' => $bk['size'], 'name' => $bk['name'], 'size' => $bk['size'], 'weight' => ( $m2['w'] === '400' ? '' : $m2['w'] ), 'lh' => $m2['lh'], 'ls' => $m2['ls'], 'color' => $m2['color'], 'class' => $class );
			}
			// Emit largest → smallest (Lead, Subtitle, Small, Caption).
			usort( $body_presets, function ( $a, $b ) { return $b['order'] - $a['order']; } );
		}

		if ( empty( $disp ) && ! $eye && empty( $body_presets ) ) { return array(); }

		$mk = function ( $name, $size, $weight, $lh, $ls, $transform, $class, $color = '' ) {
			$out = array(
				'name'           => $name,
				'size'           => (string) $size,
				'weight'         => (string) $weight,
				'line_height'    => (string) $lh,
				'letter_spacing' => (string) $ls,
				'transform'      => (string) $transform,
				'class'          => (string) $class,
			);
			// Colour is a compact preset value ({ predefined, custom }) — the shape the Text Style Color field
			// and css-tokens (unysonplus_preset_color_to_css) expect. Emitted only when a colour was detected.
			$color = (string) $color;
			if ( $color !== '' ) { $out['color'] = array( 'predefined' => '', 'custom' => $color ); }
			return $out;
		};

		$presets = array();
		$dv = array_values( $disp );
		$n  = min( 6, count( $dv ) );
		for ( $i = 0; $i < $n; $i++ ) {
			$presets[] = $mk( 'Display ' . ( $i + 1 ), $dv[ $i ]['size'], $dv[ $i ]['weight'], $dv[ $i ]['lh'], '', '', 'display-' . ( $i + 1 ) );
		}
		// BODY roles distilled from the source's paragraphs (Lead / Subtitle / Small / Caption). Replaces
		// the old hardcoded 22px Lead with the real captured lead size. De-duped against heading Displays.
		if ( ! empty( $body_presets ) ) {
			foreach ( $body_presets as $bp ) {
				$presets[] = $mk( $bp['name'], $bp['size'], $bp['weight'], $bp['lh'], $bp['ls'], '', $bp['class'], isset( $bp['color'] ) ? $bp['color'] : '' );
			}
		} else {
			$presets[] = $mk( 'Lead', 20, '', '', '', '', 'lead' ); // sensible fallback when no body paragraphs captured
		}
		if ( $eye ) {
			$presets[] = $mk( 'Eyebrow', $eye['size'], $eye['weight'], '', $eye['ls'], 'uppercase', '' ); // → .font-eyebrow
		}
		return array( 'font_sizes' => $presets );
	}

	/**
	 * Derive IMAGE STYLES (Theme Settings → Components → Image Styles — the `image_styles` key, the
	 * .imgs-{slug} treatments). Walks each <img> (and its immediate wrapper) for corner radius / circle,
	 * aspect-ratio and colour filter, clusters the distinct treatments, and appends them to the default
	 * library. Same DOM+Tailwind pattern as build_box_presets(). Returns array( 'image_styles' => [...] ).
	 */
	public static function build_image_styles( $html ) {
		$html = (string) $html;
		if ( $html === '' || ! class_exists( 'FW_Site_Converter_Tailwind' ) ) { return array(); }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$body = null;
		foreach ( $dom->getElementsByTagName( 'body' ) as $b ) { $body = $b; break; }
		if ( ! $body ) { return array(); }

		$aspect_slug = function ( $ar ) {
			$ar = str_replace( ' ', '', strtolower( (string) $ar ) );
			$map = array( '1/1' => '1-1', '4/3' => '4-3', '3/4' => '3-4', '16/9' => '16-9', '3/2' => '3-2' );
			return isset( $map[ $ar ] ) ? $map[ $ar ] : 'auto';
		};
		$filter_slug = function ( $f ) {
			$f = strtolower( (string) $f );
			foreach ( array( 'grayscale', 'sepia', 'blur', 'contrast', 'saturate' ) as $k ) {
				if ( strpos( $f, $k ) !== false ) { return $k; }
			}
			return 'none';
		};
		// A radius counts as a "circle" if it's rounded-full (9999/50%) or a very large px.
		$radius_of = function ( $props ) {
			$r = isset( $props['border-radius'] ) ? trim( (string) $props['border-radius'] ) : '';
			if ( $r === '' || $r === '0' || $r === '0px' ) { return array( '', false ); }
			if ( strpos( $r, '9999' ) !== false || strpos( $r, '50%' ) !== false || ( preg_match( '/^([0-9.]+)px$/', $r, $m ) && (float) $m[1] >= 500 ) ) {
				return array( '', true ); // circle
			}
			return array( $r, false );
		};

		$imgs = array();
		foreach ( $body->getElementsByTagName( 'img' ) as $img ) {
			$ci = FW_Site_Converter_Tailwind::compile_class_set( self::cls( $img ) );
			$bi = isset( $ci['base'] ) ? $ci['base'] : array();
			list( $radius, $circle ) = $radius_of( $bi );
			$aspect = isset( $bi['aspect-ratio'] ) ? $aspect_slug( $bi['aspect-ratio'] ) : 'auto';
			$filter = isset( $bi['filter'] ) ? $filter_slug( $bi['filter'] ) : 'none';
			// Radius / aspect are often on the wrapping element (rounded overflow-hidden frame).
			if ( ( $radius === '' && ! $circle ) || $aspect === 'auto' ) {
				$p = $img->parentNode;
				if ( $p instanceof DOMElement ) {
					$cp = FW_Site_Converter_Tailwind::compile_class_set( self::cls( $p ) );
					$bp = isset( $cp['base'] ) ? $cp['base'] : array();
					if ( $radius === '' && ! $circle ) { list( $radius, $circle ) = $radius_of( $bp ); }
					if ( $aspect === 'auto' && isset( $bp['aspect-ratio'] ) ) { $aspect = $aspect_slug( $bp['aspect-ratio'] ); }
				}
			}
			if ( $radius === '' && ! $circle && $aspect === 'auto' && $filter === 'none' ) { continue; } // untreated
			$key = ( $circle ? 'circle' : $radius ) . '|' . $aspect . '|' . $filter;
			if ( ! isset( $imgs[ $key ] ) ) { $imgs[ $key ] = array( 'radius' => $radius, 'circle' => $circle, 'aspect' => $aspect, 'filter' => $filter, 'count' => 0 ); }
			$imgs[ $key ]['count']++;
		}
		if ( empty( $imgs ) ) { return array(); }
		uasort( $imgs, function ( $a, $b ) { return $b['count'] - $a['count']; } );
		$imgs = array_slice( $imgs, 0, 5, true );

		$mask = function ( $key ) { return array( 'mask' => $key, 'custom' => array( 'custom_svg' => '', 'custom_clip' => '' ) ); };
		$col0 = array( 'predefined' => '', 'custom' => '' );
		$used = array(); $n = 0; $derived = array();
		foreach ( $imgs as $s ) {
			$base_name = $s['circle'] ? 'Circle' : ( $s['filter'] === 'grayscale' ? 'Monochrome' : ( $s['filter'] !== 'none' ? ucfirst( $s['filter'] ) : ( $s['aspect'] === '1-1' ? 'Square' : ( in_array( $s['aspect'], array( '16-9', '3-2', '4-3' ), true ) ? 'Wide' : ( $s['aspect'] === '3-4' ? 'Portrait' : 'Rounded' ) ) ) ) );
			$used[ $base_name ] = ( isset( $used[ $base_name ] ) ? $used[ $base_name ] : 0 ) + 1;
			$name = $used[ $base_name ] > 1 ? $base_name . ' ' . $used[ $base_name ] : $base_name;
			$derived[] = array(
				'id'          => 'img' . str_pad( (string) ( 100 + ( ++$n ) ), 6, '0', STR_PAD_LEFT ),
				'style_name'  => $name,
				'aspect'      => $s['aspect'],
				'radius'      => $s['circle'] ? '' : $s['radius'],
				'mask'        => $s['circle'] ? $mask( 'circle' ) : $mask( 'none' ),
				'filter'      => $s['filter'],
				'duo_color'   => $col0,
				'scrim'       => 'none',
				'scrim_color' => $col0,
			);
		}
		if ( empty( $derived ) ) { return array(); }
		$base_lib = function_exists( 'unysonplus_default_image_style_presets' ) ? unysonplus_default_image_style_presets() : array();
		return array( 'image_styles' => array_merge( $base_lib, $derived ) );
	}

	/**
	 * Derive COLOR PRESETS (Theme Settings → Components → Color Presets — the `theme_colors` key, shape
	 * `[ { name, color:#hex }, … ]` read by unysonplus_get_color_presets()) from the source's BRAND palette.
	 * The brand colours are pulled from the captured design tokens (accent/primary → Primary, dark → Dark,
	 * text → Ink, muted → Muted, background → Light, secondary/tertiary → Secondary) — the same lookups the
	 * chrome/theme-design derivation uses — with a markup scan as the accent fallback. The brand entries are
	 * PREPENDED to the plugin default palette (so the referenced default slugs — light-gray / indigo / white,
	 * used by the bundled Box/Icon-Badge presets — stay resolvable), de-duped by hex. Only emitted when a real
	 * brand colour was found (never an empty / default-only palette). A brand "Primary" prepended before the
	 * default "Primary" wins the `primary` slug, so the default button/box presets that reference `primary`
	 * pick up the brand colour. Returns array( 'theme_colors' => [...] ).
	 *
	 * @param array  $tokens design tokens (palette)
	 * @param string $html   source markup (accent scan fallback)
	 * @return array array('theme_colors'=>…) or empty.
	 */
	public static function build_color_presets( array $tokens, $html = '' ) {
		$normc = function ( $h ) {
			$h = strtolower( trim( (string) $h ) );
			// Expand #abc → #aabbcc so short/long forms de-dupe against each other.
			if ( preg_match( '/^#([0-9a-f]{3})$/', $h, $m ) ) {
				$h = '#' . $m[1][0] . $m[1][0] . $m[1][1] . $m[1][1] . $m[1][2] . $m[1][2];
			}
			return $h;
		};
		$brand = array();
		$seen  = array();
		$add   = function ( $name, $hex ) use ( &$brand, &$seen, $normc ) {
			$hex = trim( (string) $hex );
			if ( $hex === '' ) { return; }
			$key = $normc( $hex );
			if ( $key === '' || isset( $seen[ $key ] ) ) { return; }
			$seen[ $key ]  = true;
			$brand[]       = array( 'name' => $name, 'color' => $hex );
		};

		// COMPUTED-STYLE semantic colours — the real brand palette on a rendered SPA (React/shadcn/a second AI-page generator:
		// no inline tailwind.config, so parse_tokens() sees nothing, but the capture stamps each element's
		// getComputedStyle onto data-sc-cs). FW_Site_Converter_Tailwind::extract_semantic_colors() pairs a
		// base colour utility (bg-primary / text-foreground / …) with that computed value → name => #hex. We
		// harvest only KNOWN colour ROLES (primary / secondary / accent / foreground / background / muted /
		// dark) so typography/layout utility names that leak through (text-sm, text-center, text-xl → sm /
		// center / xl) are ignored. This is what recovers the golden fixture green (#21c45d) + dark-green ink
		// (#293d36) that the neutral fallback used to miss.
		$sem = ( $html !== '' && class_exists( 'FW_Site_Converter_Tailwind' ) && method_exists( 'FW_Site_Converter_Tailwind', 'extract_semantic_colors' ) )
			? (array) FW_Site_Converter_Tailwind::extract_semantic_colors( (string) $html )
			: array();
		$sem_of = function ( $names ) use ( $sem ) {
			foreach ( (array) $names as $n ) { if ( ! empty( $sem[ $n ] ) ) { return (string) $sem[ $n ]; } }
			return '';
		};
		// Prefer a real tailwind.config token; fall back to the computed-style semantic colour.
		$pick = function ( $token_keys, $sem_keys ) use ( $tokens, $sem_of ) {
			$v = self::token_color( $tokens, (array) $token_keys );
			return $v !== '' ? $v : $sem_of( $sem_keys );
		};

		// Brand ACTION colour, in priority order: (1) real tailwind.config accent/primary token; (2) the
		// computed-style semantic primary/accent/brand; (3) a vivid markup accent scan; (4) the primary
		// button's real fill (build_button_presets — the CTA bg IS the brand colour); (5) token tertiary/
		// secondary/ink; (6) the neutral fallback ONLY if nothing vivid was found.
		// INK = the source's real BODY text colour when it declares one (a dark site sets
		// `body{color:#f8fafc}` = light text — no accent utility carries that, so the semantic pass used to
		// invert the role to a near-black default). Falls back to the semantic foreground/ink token.
		$body_ink = self::color_to_hex( self::detect_body_text( (string) $html ) );
		$ink    = $body_ink !== '' ? $body_ink : $pick( array( 'text', 'on-background', 'on-surface' ), array( 'foreground', 'ink', 'text' ) );
		// Last resort (only when body{color} AND the semantic foreground are both absent — the class-based
		// `<body class="text-white">` case): sample the dominant text colour off the page's headings.
		if ( $ink === '' && $html !== '' ) { $ink = self::color_to_hex( self::sample_ink( (string) $html ) ); }
		// PRIMARY role → prefer the source's explicit `primary` semantic/token over `accent`. When a site
		// separates the two (modfii: `text-primary` = green brand ink, `text-accent` = orange CTA), picking
		// accent-first inverted them — `--color-primary` became orange, so every `text-primary` element (e.g.
		// a green "We Fixed It." highlight) rendered in the CTA orange. `primary` first keeps the brand colour
		// correct; the loud CTA colour still reaches buttons via build_button_presets (the real button fill)
		// and the Accent role below. Sites that define ONLY `accent` are unaffected (primary is absent → accent).
		$accent = $pick( array( 'primary', 'accent', 'brand', 'cta' ), array( 'primary', 'accent', 'brand', 'cta' ) );
		if ( $accent === '' && $html !== '' && method_exists( __CLASS__, 'scan_accent' ) ) { $accent = self::scan_accent( (string) $html ); }
		if ( $accent === '' && $html !== '' && method_exists( __CLASS__, 'build_button_presets' ) ) {
			$bp = self::build_button_presets( (string) $html );
			if ( ! empty( $bp['button_colors'] ) ) {
				foreach ( $bp['button_colors'] as $b ) {
					$bg = isset( $b['states']['default']['bg_color']['custom'] ) ? (string) $b['states']['default']['bg_color']['custom'] : '';
					if ( isset( $b['color_name'] ) && $b['color_name'] === 'Primary' && $bg !== '' ) { $accent = $bg; break; }
				}
			}
		}
		if ( $accent === '' ) { $accent = self::token_color( $tokens, array( 'tertiary', 'secondary', 'on-surface', 'on-background' ) ); }
		if ( $accent === '' ) { $accent = $ink !== '' ? $ink : '#141414'; }

		// ACCENT = the source's SECONDARY vivid colour. Prefer an `accent`-named semantic; else harvest it
		// from the gradients (e.g. the yellow half of a green→yellow hero gradient), distinct from Primary —
		// so the palette stops defaulting the Accent role to a stock colour the source never used.
		$accent2 = $sem_of( array( 'accent' ) );
		if ( $accent2 === '' ) { $accent2 = self::color_to_hex( self::scan_gradient_accent( (string) $html, (string) $accent ) ); }

		$add( 'Primary',   $accent );
		$add( 'Ink',       $ink !== '' ? $ink : '#1a1a1a' );
		$add( 'Secondary', $pick( array( 'secondary', 'tertiary' ), array( 'secondary' ) ) );
		$add( 'Accent',    $accent2 );
		$add( 'Dark',      $pick( array( 'deep-black', 'black', 'surface-container-lowest' ), array( 'dark' ) ) );
		// MUTED is the theme's secondary TEXT ink (`--color-muted` paints .text-muted, captions, meta) — a shadcn/Tailwind
		// `muted` token is the muted SURFACE (a pale tint) and `muted-foreground` the ink; picking the surface made every
		// theme component that writes in muted ink (a testimonial's role line) near-invisible (a real-site audit). The
		// ink token first; a surface-light pick is replaced by the page's sampled muted text colour.
		$muted = $pick( array( 'muted-foreground', 'on-surface-variant', 'muted' ), array( 'muted-foreground', 'muted' ) );
		if ( '' === $muted || self::is_surface_light( $muted ) ) { $mi = self::color_to_hex( self::sample_muted_ink( (string) $html ) ); if ( '' !== $mi ) { $muted = $mi; } }
		$add( 'Muted',     $muted );
		$add( 'Light',     $pick( array( 'page-bg', 'background', 'surface', 'white-soft' ), array( 'background', 'surface' ) ) );

		// Nothing resolved at all (should never happen — Primary/Ink always fall back) → leave defaults.
		if ( empty( $brand ) ) { return array(); }

		// Slug from a preset name the SAME way css-tokens.php / unysonplus_color_preset_slug_map() derive it.
		$slugify = function ( $name ) {
			return trim( preg_replace( '/[^a-z0-9]+/', '-', strtolower( (string) $name ) ), '-' );
		};
		// The brand entries OWN their role names/slugs (Primary, Secondary, Accent, Ink, Dark, Light). When
		// prepending the default palette, DROP any default whose slug collides with a brand role — so there's
		// exactly ONE "Primary" (brand), ONE "Secondary" (brand), etc. Defaults with a non-colliding slug the
		// Box/Badge presets reference (light-gray / indigo / white / …) stay so those references keep resolving.
		$brand_slugs = array();
		foreach ( $brand as $b ) { $brand_slugs[ $slugify( $b['name'] ) ] = true; }

		$defaults = function_exists( 'unysonplus_default_color_presets' ) ? unysonplus_default_color_presets() : array();
		$merged   = $brand;
		foreach ( $defaults as $d ) {
			if ( empty( $d['color'] ) ) { continue; }
			if ( isset( $brand_slugs[ $slugify( isset( $d['name'] ) ? $d['name'] : '' ) ] ) ) { continue; } // name/slug collides with a brand role
			$hx  = self::norm_hex( (string) $d['color'] );
			$key = $normc( $hx !== '' ? $hx : $d['color'] );
			if ( isset( $seen[ $key ] ) ) { continue; } // same hex already present under another name
			$seen[ $key ] = true;
			$merged[]     = $d;
		}
		return array( 'theme_colors' => $merged );
	}

	/**
	 * Derive ICON BADGE PRESETS (Theme Settings → Components → Icon Badges — the `icon_badge_presets` key,
	 * the `.iconb-{slug}` tiles read by unysonplus_get_icon_badge_presets()) from the source's icon-in-a-tile
	 * pattern: an icon (`<svg>` / `<i>`) inside a small, roughly-square container that has a background fill
	 * (or a ring) and a corner radius — e.g. the golden fixture's feature-card heart/shield/clock in rounded tiles.
	 * Walks candidate tiles, compiles their Tailwind → fill / radius / size / border + the inner glyph colour,
	 * clusters the distinct designs, and appends the top few (named by shape) to the plugin defaults. Same
	 * DOM→Tailwind-compile→cluster pattern as build_box_presets(). Shape mirrors unysonplus_default_icon_badge_presets():
	 * badge_shape / badge_size{value,unit} / icon_size / border_radius / states{ default:{ background (background-pro),
	 * icon_color (compact), border_* }, hover }. Only emitted when the source actually HAS an icon tile.
	 * Returns array( 'icon_badge_presets' => [...] ).
	 *
	 * @param string $html
	 * @return array array('icon_badge_presets'=>…) or empty.
	 */
	public static function build_icon_badge_presets( $html ) {
		$html = (string) $html;
		if ( $html === '' || ! class_exists( 'FW_Site_Converter_Tailwind' ) ) { return array(); }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$body = null;
		foreach ( $dom->getElementsByTagName( 'body' ) as $b ) { $body = $b; break; }
		if ( ! $body ) { return array(); }

		$unit = function ( $v ) {
			$v = trim( (string) $v );
			return preg_match( '/^(-?[0-9.]+)\s*(px|rem|em|%)?$/', $v, $m )
				? array( 'value' => $m[1], 'unit' => ( isset( $m[2] ) && $m[2] !== '' ? $m[2] : 'px' ) )
				: null;
		};
		$px = function ( $v ) { // rough px magnitude of a length (px/rem) for size/shape thresholds
			$v = trim( (string) $v );
			if ( preg_match( '/^(-?[0-9.]+)\s*(px)?$/', $v, $m ) ) { return (float) $m[1]; }
			if ( preg_match( '/^(-?[0-9.]+)\s*rem$/', $v, $m ) ) { return (float) $m[1] * 16; }
			if ( preg_match( '/^(-?[0-9.]+)\s*em$/', $v, $m ) )  { return (float) $m[1] * 16; }
			return null;
		};
		$norm = function ( $c ) {
			$c = strtolower( trim( (string) $c ) );
			$has_var = ( strpos( $c, 'var(' ) !== false );
			if ( preg_match( '/rgba?\(\s*([0-9.]+)[,\s]+([0-9.]+)[,\s]+([0-9.]+)(?:[,\s\/]+([0-9.]+))?/', $c, $m ) ) {
				$a = ( ! $has_var && isset( $m[4] ) && $m[4] !== '' ) ? (float) $m[4] : 1.0;
				if ( $a === 0.0 ) { return ''; }
				return $a < 1 ? "rgba({$m[1]}, {$m[2]}, {$m[3]}, {$a})" : "rgb({$m[1]}, {$m[2]}, {$m[3]})";
			}
			if ( preg_match( '/^#([0-9a-f]{3}|[0-9a-f]{6})$/', $c, $m ) ) {
				$h = $m[1]; if ( strlen( $h ) === 3 ) { $h = $h[0] . $h[0] . $h[1] . $h[1] . $h[2] . $h[2]; }
				return 'rgb(' . hexdec( substr( $h, 0, 2 ) ) . ', ' . hexdec( substr( $h, 2, 2 ) ) . ', ' . hexdec( substr( $h, 4, 2 ) ) . ')';
			}
			return '';
		};

		$tiles = array();
		foreach ( $body->getElementsByTagName( '*' ) as $node ) {
			$tag = strtolower( $node->tagName );
			if ( in_array( $tag, array( 'a', 'button', 'svg', 'path', 'i', 'body', 'section', 'nav', 'header', 'footer', 'main' ), true ) ) { continue; }
			$cls = self::cls( $node );
			if ( $cls === '' ) { continue; }
			// Cheap pre-filter: must read like a tile (rounded / fill / ring).
			if ( ! preg_match( '/(?:^|\s)(rounded|bg-|border|ring)/i', $cls ) ) { continue; }
			// The tile's DIRECT content is essentially just an icon (svg or <i>), no real text.
			$icon = null; $text = '';
			foreach ( $node->childNodes as $ch ) {
				if ( $ch instanceof DOMElement ) {
					$t = strtolower( $ch->tagName );
					if ( $t === 'svg' || $t === 'i' ) { if ( ! $icon ) { $icon = $ch; } }
				} elseif ( $ch instanceof DOMText ) {
					$text .= $ch->wholeText;
				}
			}
			if ( ! $icon ) {
				// One-level-deep single icon wrapper still counts (a <span><svg/></span> inside the tile).
				foreach ( $node->getElementsByTagName( 'svg' ) as $sv ) { $icon = $sv; break; }
				if ( ! $icon ) { foreach ( $node->getElementsByTagName( 'i' ) as $ii ) { $icon = $ii; break; } }
			}
			if ( ! $icon ) { continue; }
			if ( trim( preg_replace( '/\s+/', '', $text ) ) !== '' ) { continue; } // has real text → it's a card, not a badge tile

			$c  = FW_Site_Converter_Tailwind::compile_class_set( $cls );
			$b  = isset( $c['base'] ) ? $c['base'] : array();
			$bg = isset( $b['background-color'] ) ? $norm( (string) $b['background-color'] ) : '';
			$bw = ( isset( $b['border-width'] ) && ! in_array( (string) $b['border-width'], array( '', '0', '0px' ), true ) ) ? (string) $b['border-width'] : '';
			$radius = ( isset( $b['border-radius'] ) && ! in_array( (string) $b['border-radius'], array( '', '0', '0px' ), true ) ) ? (string) $b['border-radius'] : '';
			// A badge tile must have a visible surface (fill or ring). A bare radius on a big card isn't one.
			if ( $bg === '' && $bw === '' ) { continue; }

			$w = isset( $b['width'] ) ? $px( (string) $b['width'] ) : null;
			$h = isset( $b['height'] ) ? $px( (string) $b['height'] ) : null;
			$size = null;
			if ( $w !== null && $h !== null ) { if ( abs( $w - $h ) > max( 6, 0.35 * max( $w, $h ) ) ) { continue; } $size = ( $w + $h ) / 2; }
			elseif ( $w !== null ) { $size = $w; }
			elseif ( $h !== null ) { $size = $h; }
			// Badge tiles are small squares — skip anything that's clearly a full card / section.
			if ( $size !== null && ( $size < 24 || $size > 120 ) ) { continue; }

			// Shape from the corner radius vs the tile size (rounded-full / >=50% → circle).
			$rpx = $radius !== '' ? $px( $radius ) : 0;
			$is_full = ( stripos( $cls, 'rounded-full' ) !== false ) || ( $radius !== '' && ( strpos( $radius, '9999' ) !== false || ( $size !== null && $rpx !== null && $rpx >= $size * 0.5 - 1 ) ) );
			$shape = $is_full ? 'circle' : ( $radius !== '' ? 'rounded' : 'square' );

			// Inner glyph colour: the icon's own color, else the tile's text color.
			$icls = self::cls( $icon );
			$ic   = $icls !== '' ? FW_Site_Converter_Tailwind::compile_class_set( $icls ) : array();
			$icol = isset( $ic['base']['color'] ) ? $norm( (string) $ic['base']['color'] ) : '';
			if ( $icol === '' && isset( $b['color'] ) ) { $icol = $norm( (string) $b['color'] ); }

			$tiles[] = array(
				'shape'  => $shape,
				'size'   => $size !== null ? (int) round( $size ) : 0,
				'radius' => ( $shape === 'rounded' && $radius !== '' ) ? $radius : '',
				'bg'     => $bg,
				'bw'     => $bw,
				'bdcol'  => isset( $b['border-color'] ) ? $norm( (string) $b['border-color'] ) : '',
				'icol'   => $icol,
			);
		}
		// Don't bail on an empty scan when the mapper REGISTERED icon badges (a class-only source, or one whose
		// chips the tile scan didn't catch, still has icon_box cards that assigned an icon_badge_preset which MUST
		// be emitted below or the reference dangles). Mirrors build_box_presets()'s $_has_reg guard.
		$_has_reg = ( class_exists( 'FW_Site_Converter_Mapper' ) && ! empty( FW_Site_Converter_Mapper::captured( 'icon_badge' ) ) );
		if ( empty( $tiles ) && ! $_has_reg ) { return array(); }

		// Cluster the distinct tile designs; keep the most common few.
		$groups = array();
		foreach ( $tiles as $t ) {
			$key = $t['shape'] . '|' . $t['bg'] . '|' . preg_replace( '/\s+/', '', $t['radius'] ) . '|' . $t['bw'] . $t['bdcol'];
			if ( ! isset( $groups[ $key ] ) ) { $groups[ $key ] = array_merge( $t, array( 'count' => 0 ) ); }
			$groups[ $key ]['count']++;
		}
		uasort( $groups, function ( $a, $b ) { return $b['count'] - $a['count']; } );
		$groups = array_slice( $groups, 0, 4, true );

		$empty  = array( 'predefined' => '', 'custom' => '' );
		$fill   = function ( $val ) { return array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => (string) $val ) ) ); };
		$nofill = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => '' ) ) );
		$used   = array(); $n = 0; $derived = array();
		foreach ( $groups as $g ) {
			$base = ( $g['shape'] === 'circle' ) ? 'Circle' : ( $g['shape'] === 'rounded' ? 'Rounded Tile' : 'Square' );
			if ( $g['bg'] === '' && $g['bw'] !== '' ) { $base = ( $g['shape'] === 'circle' ) ? 'Outline Ring' : 'Outline Tile'; }
			$used[ $base ] = ( isset( $used[ $base ] ) ? $used[ $base ] : 0 ) + 1;
			$name = $used[ $base ] > 1 ? $base . ' ' . $used[ $base ] : $base;

			$size = $g['size'] > 0 ? $g['size'] : 48;
			$icon_size = (int) round( $size * 0.5 );
			$default = array(
				'background'   => $g['bg'] !== '' ? $fill( $g['bg'] ) : $nofill,
				'icon_color'   => $g['icol'] !== '' ? array( 'predefined' => '', 'custom' => $g['icol'] ) : $empty,
				'border_style' => $g['bw'] !== '' ? 'solid' : '',
				'border_color' => $g['bw'] !== '' && $g['bdcol'] !== '' ? array( 'predefined' => '', 'custom' => $g['bdcol'] ) : $empty,
			);
			if ( $g['bw'] !== '' ) { $bwu = $unit( $g['bw'] ); if ( $bwu ) { $default['border_width'] = $bwu; } }

			$derived[] = array(
				'id'            => 'i' . str_pad( (string) ( 100 + ( ++$n ) ), 9, '0', STR_PAD_LEFT ),
				'preset_name'   => $name,
				'badge_shape'   => $g['shape'],
				'badge_size'    => array( 'value' => (string) $size, 'unit' => 'px' ),
				'icon_size'     => array( 'value' => (string) $icon_size, 'unit' => 'px' ),
				'border_radius' => ( $g['shape'] === 'rounded' && $g['radius'] !== '' && $unit( $g['radius'] ) ) ? $unit( $g['radius'] ) : array( 'value' => '', 'unit' => 'px' ),
				'transition'    => '200',
				'hover_fx'      => array(),
				'custom_css'    => '',
				'states'        => array( 'default' => $default, 'hover' => array() ),
			);
		}
		// REGISTERED badges — chip skins the mapper ASSIGNED to an icon_box via register_icon_badge_preset()
		// (its icon_badge_preset = `iconb-<slug>`). These MUST become presets or the reference dangles — and
		// unlike the scan above they work on a class-only source. Named "Badge <hash>" so the slugified name
		// equals the mapper's slug (`badge-<hash>`) -> the front-end `.iconb-badge-<hash>` the icon_box points at.
		// Deduped by slug (same chip -> one preset, referenced by every card that uses it). Mirrors build_box_presets().
		$reg = array();
		if ( class_exists( 'FW_Site_Converter_Mapper' ) && ! empty( FW_Site_Converter_Mapper::captured( 'icon_badge' ) ) ) {
			foreach ( FW_Site_Converter_Mapper::captured( 'icon_badge' ) as $slug => $sk ) {
				if ( ! is_array( $sk ) ) { continue; }
				$shape = in_array( (string) ( $sk['shape'] ?? '' ), array( 'circle', 'rounded', 'square' ), true ) ? (string) $sk['shape'] : 'circle';
				$size  = ( '' !== (string) ( $sk['size'] ?? '' ) ) ? (int) $sk['size'] : 48;
				if ( $size < 24 || $size > 120 ) { $size = 48; }
				$isize = (int) round( $size * 0.5 );
				$bw    = (string) ( $sk['bw'] ?? '' );
				$default = array(
					'background'   => ( '' !== (string) ( $sk['bg'] ?? '' ) ) ? $fill( (string) $sk['bg'] ) : $nofill,
					'icon_color'   => ( '' !== (string) ( $sk['icol'] ?? '' ) ) ? array( 'predefined' => '', 'custom' => (string) $sk['icol'] ) : $empty,
					'border_style' => ( '' !== $bw ) ? 'solid' : '',
					'border_color' => ( '' !== $bw && '' !== (string) ( $sk['bd'] ?? '' ) ) ? array( 'predefined' => '', 'custom' => (string) $sk['bd'] ) : $empty,
				);
				if ( '' !== $bw ) { $bwu = $unit( $bw ); if ( $bwu ) { $default['border_width'] = $bwu; } }
				$shadow = trim( (string) ( $sk['shadow'] ?? '' ) );
				$ccss   = ( '' !== $shadow && 'none' !== strtolower( $shadow ) ) ? '{{SELECTOR}}{box-shadow:' . $shadow . ';}' : '';
				$rrad   = (string) ( $sk['radius'] ?? '' );
				$reg[] = array(
					'id'            => 'g' . substr( md5( (string) $slug ), 0, 8 ),
					'preset_name'   => 'Badge ' . substr( (string) $slug, 6 ), // slug `badge-<hash>` -> name "Badge <hash>" -> slugifies back to the slug
					'badge_shape'   => $shape,
					'badge_size'    => array( 'value' => (string) $size, 'unit' => 'px' ),
					'icon_size'     => array( 'value' => (string) $isize, 'unit' => 'px' ),
					'border_radius' => ( 'rounded' === $shape && '' !== $rrad && $unit( $rrad ) ) ? $unit( $rrad ) : array( 'value' => '', 'unit' => 'px' ),
					'transition'    => '200',
					'hover_fx'      => array(),
					'custom_css'    => $ccss,
					'states'        => array( 'default' => $default, 'hover' => array() ),
				);
			}
		}
		if ( empty( $derived ) && empty( $reg ) ) { return array(); }
		$base_lib = function_exists( 'unysonplus_default_icon_badge_presets' ) ? unysonplus_default_icon_badge_presets() : array();
		return array( 'icon_badge_presets' => array_merge( $base_lib, $derived, $reg ) );
	}

	/**
	 * Table Presets from the skins the mapper REGISTERED (register_table_preset → captured('table')): each becomes
	 * an entry in the `table_presets` Theme-Settings library, in the shape of unysonplus_default_table_presets(),
	 * named "Table <hash>" so its slug is the mapper's `table-<hash>` → the front-end `.tbl-table-<hash>` the table
	 * node points at. The built-in library rides along so the user keeps the defaults. What the preset fields can't
	 * express (the header's face / size / tracking / own padding, the body weight / face / line-height, a vertical
	 * rule) rides the preset's own Custom CSS ({{SELECTOR}}-scoped; descendant selectors — the field strips `>`).
	 * Mirrors build_icon_badge_presets(). JS twin: buildTablePresets.
	 *
	 * @return array array('table_presets'=>…) or empty.
	 */
	public static function build_table_presets() {
		if ( ! class_exists( 'FW_Site_Converter_Mapper' ) ) { return array(); }
		$reg = FW_Site_Converter_Mapper::captured( 'table' );
		if ( empty( $reg ) || ! is_array( $reg ) ) { return array(); }
		$empty = array( 'predefined' => '', 'custom' => '' );
		$c     = function ( $v ) use ( $empty ) { $v = trim( (string) $v ); return '' === $v ? $empty : array( 'predefined' => '', 'custom' => $v ); };
		$u     = function ( $v ) {
			$v = trim( (string) $v );
			return preg_match( '/^(-?[0-9.]+)\s*(px|rem|em|%)?$/', $v, $m ) ? array( 'value' => $m[1], 'unit' => ( isset( $m[2] ) && '' !== $m[2] ? $m[2] : 'px' ) ) : array( 'value' => '', 'unit' => 'px' );
		};
		$noshadow = array( 'x' => 0, 'y' => 0, 'blur' => 0, 'spread' => 0, 'color' => '', 'inset' => false );
		$shadow = function ( $sh ) use ( $noshadow ) {
			// "rgba(..) 0px 4px 12px 0px" / "0px 4px 12px rgba(..)" → the box-shadow field (first layer only)
			$sh = trim( (string) $sh );
			if ( '' === $sh || 'none' === strtolower( $sh ) ) { return $noshadow; }
			$first = preg_split( '/,(?![^(]*\))/', $sh )[0];
			$inset = false !== stripos( $first, 'inset' );
			$col   = '';
			if ( preg_match( '/(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', $first, $m ) ) { $col = $m[1]; $first = str_replace( $m[1], '', $first ); }
			$nums = array();
			if ( preg_match_all( '/-?[0-9.]+(?=px)/', $first, $mm ) ) { $nums = $mm[0]; }
			if ( count( $nums ) < 2 ) { return $noshadow; }
			return array( 'x' => (float) $nums[0], 'y' => (float) $nums[1], 'blur' => isset( $nums[2] ) ? (float) $nums[2] : 0, 'spread' => isset( $nums[3] ) ? (float) $nums[3] : 0, 'color' => $col, 'inset' => $inset );
		};
		$line = function ( $l ) { // "width|style|color" → [w, style, color]
			$p = explode( '|', (string) $l );
			return ( count( $p ) === 3 ) ? $p : array( '', '', '' );
		};
		$out = array();
		foreach ( $reg as $slug => $sk ) {
			if ( ! is_array( $sk ) ) { continue; }
			$hd = is_array( $sk['header'] ?? null ) ? $sk['header'] : array();
			$bd = is_array( $sk['body'] ?? null ) ? $sk['body'] : array();
			$ft = is_array( $sk['footer'] ?? null ) ? $sk['footer'] : array();
			$cp = is_array( $sk['caption'] ?? null ) ? $sk['caption'] : array();
			$fr = is_array( $sk['frame'] ?? null ) ? $sk['frame'] : array();
			list( $hw, $hs, $hc ) = $line( $sk['hline'] ?? '' );
			list( $vw, $vs, $vc ) = $line( $sk['vline'] ?? '' );
			list( $dw, $ds, $dc ) = $line( $hd['line'] ?? '' );
			list( $fw, $fs, $fc ) = $line( $ft['line'] ?? '' );
			$grid = ( '' !== $hw && '' !== $vw ) ? 'both' : ( '' !== $hw ? 'horizontal' : ( '' !== $vw ? 'vertical' : 'none' ) );
			$ob = array( '', '', '' );
			if ( ! empty( $fr['border'] ) && preg_match( '/^([0-9.]+px)\s+(\w+)\s+(.+)$/', trim( (string) $fr['border'] ), $m ) ) { $ob = array( $m[1], $m[2], $m[3] ); }
			$hov = array();
			foreach ( explode( ';', (string) ( $sk['hover'] ?? '' ) ) as $dd ) { $cp2 = strpos( $dd, ':' ); if ( false !== $cp2 ) { $hov[ trim( substr( $dd, 0, $cp2 ) ) ] = trim( substr( $dd, $cp2 + 1 ) ); } }
			// the long tail → the preset's Custom CSS (descendant selectors; `!important` to outrank the theme's table base)
			$css = array();
			$imp = function ( array $decl ) { $o = array(); foreach ( $decl as $p => $v ) { if ( '' !== trim( (string) $v ) ) { $o[] = $p . ':' . $v . ' !important'; } } return implode( ';', $o ); };
			$hx = $imp( array( 'font-family' => $hd['family'] ?? '', 'font-size' => $hd['size'] ?? '', 'letter-spacing' => $hd['tracking'] ?? '', 'line-height' => $hd['lh'] ?? '', 'padding' => $hd['pad'] ?? '' ) );
			if ( '' !== $hx ) { $css[] = '{{SELECTOR}} thead th,{{SELECTOR}} thead td{' . $hx . ';}'; }
			$bx = $imp( array( 'font-family' => $bd['family'] ?? '', 'font-weight' => $bd['weight'] ?? '', 'letter-spacing' => $bd['tracking'] ?? '', 'text-transform' => $bd['transform'] ?? '', 'line-height' => $bd['lh'] ?? '' ) );
			if ( '' !== $bx ) { $css[] = '{{SELECTOR}} tbody td{' . $bx . ';}'; }
			if ( '' !== $hw && '' === $vw ) { $css[] = '{{SELECTOR}} tbody tr:last-child td{border-bottom:0 !important;}'; } // a divide-y source rules BETWEEN rows only
			if ( '' !== ( $sk['minw'] ?? '' ) ) { $css[] = '{{SELECTOR}}{overflow-x:auto;}{{SELECTOR}} table{min-width:' . $sk['minw'] . ';}'; }
			$hash = substr( (string) $slug, 6 ); // slug `table-<hash>` → name "Table <hash>" → slugifies back to the slug
			$out[] = array(
				'id'                 => 'tc' . substr( md5( (string) $slug ), 0, 8 ),
				'preset_name'        => 'Table ' . $hash,
				'cell_padding_y'     => $u( $sk['pad_y'] ?? '' ),
				'cell_padding_x'     => $u( $sk['pad_x'] ?? '' ),
				'grid_lines'         => $grid,
				'grid_style'         => '' !== $hw ? $hs : $vs,
				'grid_width'         => $u( '' !== $hw ? $hw : $vw ),
				'grid_color'         => $c( '' !== $hw ? $hc : $vc ),
				'outer_border_style' => $ob[1],
				'outer_border_width' => $u( $ob[0] ),
				'outer_border_color' => $c( $ob[2] ),
				'border_radius'      => $u( $fr['radius'] ?? '' ),
				'outer_shadow'       => $shadow( $fr['shadow'] ?? '' ),
				'cell_font_size'     => $u( $bd['size'] ?? '' ),
				'transition'         => '' !== (string) ( $sk['transition'] ?? '' ) ? (string) $sk['transition'] : '150',
				'custom_css'         => implode( "\n", $css ),
				'sections'           => array(
					'header'  => array( 'bg_color' => $c( $hd['bg'] ?? '' ), 'text_color' => $c( $hd['color'] ?? '' ), 'font_weight' => (string) ( $hd['weight'] ?? '' ), 'text_transform' => (string) ( $hd['transform'] ?? '' ), 'border_style' => $ds, 'border_width' => $u( $dw ), 'border_color' => $c( $dc ) ),
					'body'    => array( 'bg_color' => $c( $bd['bg'] ?? '' ), 'text_color' => $c( $bd['color'] ?? '' ) ),
					'striped' => array( 'enabled' => '' !== (string) ( $sk['stripe_bg'] ?? '' ) ? 'yes' : 'no', 'bg_color' => $c( $sk['stripe_bg'] ?? '' ) ),
					'hover'   => array( 'bg_color' => $c( $hov['background-color'] ?? '' ), 'text_color' => $c( $hov['color'] ?? '' ) ),
					'footer'  => array( 'bg_color' => $c( $ft['bg'] ?? '' ), 'text_color' => $c( $ft['color'] ?? '' ), 'font_weight' => (string) ( $ft['weight'] ?? '' ), 'border_style' => $fs, 'border_width' => $u( $fw ), 'border_color' => $c( $fc ) ),
					'caption' => array( 'color' => $c( $cp['color'] ?? '' ), 'font_size' => $u( $cp['size'] ?? '' ), 'font_style' => (string) ( $cp['style'] ?? '' ) ),
				),
			);
		}
		if ( empty( $out ) ) { return array(); }
		$base_lib = function_exists( 'unysonplus_default_table_presets' ) ? unysonplus_default_table_presets() : array();
		return array( 'table_presets' => array_merge( $base_lib, $out ) );
	}

	public static function tokens_to_theme_settings_chrome( array $tokens, $html, $title ) {
		$el  = function ( $type, $settings = null ) {
			$et = array( 'element' => $type );
			if ( is_array( $settings ) ) { $et[ $type ] = $settings; }
			return array( 'element_type' => $et );
		};
		$hex = function ( $h ) { return array( 'predefined' => '', 'custom' => self::clean_color_value( (string) $h ) ); };

		$hdr   = self::detect_header( (string) $html );
		$logo  = self::detect_logo( (string) $html, (string) $title );
		$menu  = self::design_menu( (string) $html, 'primary' );

		// Palette-derived chrome colors (fall back to sensible neutrals).
		$ink        = self::token_color( $tokens, array( 'text', 'on-background', 'on-surface' ) );
		$accent     = self::brand_accent_color( $html );
		if ( '' === $accent ) { $accent     = self::accent_token_color( $tokens ); }
		$dark       = self::token_color( $tokens, array( 'deep-black', 'black', 'surface-container-lowest' ) );
		if ( $dark === '' ) { $dark = '#141414'; }
		$muted      = self::token_color( $tokens, array( 'muted', 'on-surface-variant' ) );
		$link_col   = $muted !== '' ? $muted : ( $ink !== '' ? $ink : '#94a3b8' );
		$header_bg  = $hdr['dark'] ? $dark : ( $ink !== '' ? '#ffffff' : '#ffffff' );

		$values = array();

		/* --- header_logo — faithful to the SOURCE brand. An icon+wordmark lockup → logo_type 'custom' (the
		   real inline SVG mark + wordmark, in their source colors + optional colored frame tile). A pure
		   image logo → logo_type 'simple' (portable via the upload shape; the media pipeline resolves it).
		   Emitted in the NESTED multi-picker shape so it BOTH renders (unysonplus_header_logo_cfg flattens
		   it) AND pre-populates the Theme Settings → Header → Identity UI. --- */
		// Site title / logo wordmark. When the source has a real brand, that wins. Otherwise the passed title
		// is the generic page role ('Home' default from html_to_mapping), which rendered the theme's "Home"
		// fallback in the masthead — wrong for a BRAND-LESS but titled page (a single-scene page with no
		// header/nav — crafting-the-nocturnal-web "Aether House", synthetic-light "Lumina Gen"). Derive the
		// brand from the source <title>'s first segment (before a | – — · : separator), mirroring the theme-name
		// derivation, so the masthead shows the real brand instead of "Home".
		$site_title = $logo['text'];
		if ( $site_title === '' ) {
			$passed = trim( (string) $title );
			if ( $passed === '' || 0 === strcasecmp( $passed, 'Home' ) ) {
				$raw       = trim( (string) self::title_from_html( (string) $html, '' ) );
				$brand     = $raw !== '' ? trim( (string) preg_split( '/\s*[|\x{2013}\x{2014}\x{00B7}:]\s*/u', $raw, 2 )[0] ) : '';
				$site_title = $brand !== '' ? $brand : ( $passed !== '' ? $passed : 'Site' );
			} else {
				$site_title = $passed;
			}
		}
		$title_color = $logo['title_color'] !== '' ? $logo['title_color'] : ( $hdr['dark'] ? '#ffffff' : ( $ink !== '' ? $ink : '#111111' ) );

		// H6 — Logo layout. Detectable high-confidence case: an icon/wordmark source with a REAL glyph but no
		// visible wordmark text and no image logo → 'icon-only' (the title stays as the a11y name). The
		// stacked/eyebrow and icon-right variants need icon-position/tagline signals the logo detector does not
		// currently expose, so they keep the safe 'inline-left' default (correct for the overwhelming majority).
		$has_mark    = ( $logo['svg'] !== '' || $logo['icon'] !== '' );
		$has_tagline = ( trim( (string) ( $logo['tagline'] ?? '' ) ) !== '' );
		// icon-only when there's a mark but no wordmark/image; a detected tagline → stacked (title with the
		// sub-line under it, beside the icon — kage's KAGE / HIDDEN REALMS OF KYOTO); else inline.
		// eyebrow-left when the sub-line sits ABOVE the wordmark (the small tracked-out kicker over a
		// larger title); stacked-left when it sits under it; inline when there is no sub-line at all.
		$tagline_above = ! empty( $logo['tagline_above'] );
		$logo_layout = ( $logo['text'] === '' && $logo['image'] === '' && $has_mark )
			? 'icon-only'
			: ( $has_tagline ? ( $tagline_above ? 'eyebrow-left' : 'stacked-left' ) : 'inline-left' );
		$logo_custom = array(
			'site_title'   => $site_title,
			'logo_layout'  => $logo_layout,
			// Wordmark weight/size from the MEASURED span (fall back to a bold default when unmeasured).
			'title_weight' => ( $logo['title_weight'] !== '' ? $logo['title_weight'] : '700' ),
			'color'        => $hex( $title_color ),
		);
		if ( $logo['title_size'] !== '' ) {
			$ts = self::css_len_to_unit( $logo['title_size'] );
			if ( $ts ) { $logo_custom['title_size'] = $ts; }
		}
		// Tagline / sub-line of the lockup (the source's `<i>`/`.tagline` beside the wordmark).
		if ( $has_tagline ) { $logo_custom['tagline_text'] = (string) $logo['tagline']; }
		// The icon mark: inline SVG (verbatim) preferred, else a Lucide library id, else a RASTER emblem.
		if ( $logo['svg'] !== '' ) {
			$logo_custom['logo_icon'] = array( 'type' => 'svg', 'svg-source' => 'inline', 'markup' => $logo['svg'] );
		} elseif ( $logo['icon'] !== '' ) {
			$logo_custom['logo_icon'] = array( 'type' => 'svg', 'svg-source' => 'library', 'svg-id' => $logo['icon'] );
		} elseif ( $logo['image'] !== '' && $logo['text'] !== '' ) {
			// A RASTER emblem (a PNG/JPG brand mark) paired with the wordmark → the icon+wordmark lockup with a
			// real IMAGE icon. logo_icon is an icon-v2, which renders a `custom-upload` value as an `<img>` — so a
			// non-SVG logo mark finally SHOWS beside the wordmark (was dropped when only SVG/library were mapped).
			// Portable upload shape (url + attachment-id); the media pipeline re-attaches it on the target site.
			$logo_custom['logo_icon'] = array( 'type' => 'custom-upload', 'url' => (string) $logo['image'], 'attachment-id' => false );
			// Size the mark to the source emblem height (e.g. `h-8` = 32px) when known, else a sensible default.
			if ( ! empty( $logo['image_height'] ) ) { $logo_custom['logo_icon_size'] = array( 'value' => (string) (int) $logo['image_height'], 'unit' => 'px' ); }
		}
		if ( isset( $logo_custom['logo_icon'] ) ) {
			$icon_col = $logo['icon_color'] !== '' ? $logo['icon_color'] : ( $accent !== '' ? $accent : $title_color );
			$logo_custom['logo_icon_color'] = $hex( $icon_col );
			// The measured icon glyph size (e.g. `w-6` = 24px). Drives the mark + (scaled) frame tile.
			if ( $logo['icon_size'] !== '' ) {
				$is = self::css_len_to_unit( $logo['icon_size'] );
				if ( $is ) { $logo_custom['logo_icon_size'] = $is; }
			}
			// A colored tile behind the mark (e.g. the golden fixture's green paw tile) — shape inferred from its radius.
			if ( $logo['frame'] !== 'none' && ( $logo['frame_bg'] !== '' || '' !== (string) ( $logo['frame_border'] ?? '' ) ) ) {
				$logo_custom['logo_icon_frame']    = in_array( $logo['frame'], array( 'circle', 'squircle', 'rounded', 'square' ), true ) ? $logo['frame'] : 'rounded';
				if ( $logo['frame_bg'] !== '' ) { $logo_custom['logo_icon_frame_bg'] = $hex( $logo['frame_bg'] ); }
				// the ring (a border-only tile) + the tile's measured size ride the logo's own Custom CSS — the option has no border / size field
				$fcss = array();
				if ( '' !== (string) ( $logo['frame_border'] ?? '' ) && preg_match( '/^[a-z0-9#(),.%\s-]+$/i', (string) $logo['frame_border'] ) ) { $fcss[] = 'border:' . $logo['frame_border']; if ( $logo['frame_bg'] === '' ) { $fcss[] = 'background:transparent'; } }
				if ( '' !== (string) ( $logo['frame_size'] ?? '' ) && preg_match( '/^[0-9.]+(px|rem|em)?$/', (string) $logo['frame_size'] ) ) { $fs = (string) $logo['frame_size']; if ( preg_match( '/^[0-9.]+$/', $fs ) ) { $fs .= 'px'; } $fcss[] = 'width:' . $fs; $fcss[] = 'height:' . $fs; }
				if ( $fcss ) { $logo_custom['logo_custom_css'] = trim( (string) ( $logo_custom['logo_custom_css'] ?? '' ) . "
" . '.site-logo__mark--framed{' . implode( ';', $fcss ) . ';box-sizing:border-box;}' ); }
			}
		}
		// TWO-TONE wordmark residual: a single `color` field can't split a wordmark's ink part + accent part. The base
		// tone maps natively above; emit the accent as scoped CSS on the wordmark's trailing text (documented
		// residual path — header.md logo_custom_css hooks). Best-effort: colors the emphasized run if the theme
		// wraps it; otherwise it is a no-op (never wrong, never double-applied to a native field).
		if ( $logo['title_accent_color'] !== '' && $logo['title_accent_color'] !== $title_color ) {
			$logo_custom['logo_custom_css'] = trim( (string) ( $logo_custom['logo_custom_css'] ?? '' ) . "
" . '.site-title-text .accent,.site-title-text b,.site-title-text strong{color:' . $logo['title_accent_color'] . '}' ); // (appends: the frame ring css above stays)
			// SPLIT the wordmark so the scoped CSS above has something to paint: wrap the measured accent run
			// (the accent run) in `<span class="accent">`, leaving the ink part bare. The theme prints site_title
			// RAW inside `.site-title-text` (helpers.php), so this two-tone lockup renders natively — richer than
			// a single-color `site_title`. Falls back to the plain wordmark when no accent run was measured.
			$acc = $logo['title_accent_text'];
			if ( $acc !== '' && $site_title !== '' && ( $pos = strpos( $site_title, $acc ) ) !== false ) {
				$ink_part = substr( $site_title, 0, $pos );
				$tail     = substr( $site_title, $pos + strlen( $acc ) );
				$logo_custom['site_title'] = esc_html( $ink_part ) . '<span class="accent">' . esc_html( $acc ) . '</span>' . esc_html( $tail );
			}
		}

		// NEVER-DROP wordmark skin — font-family (`font-serif`), letter-spacing (`tracking-tight`) and the
		// hover colour (`hover:text-primary`) have no native logo option, so carry them as scoped
		// logo_custom_css (the theme injects it verbatim; the wordmark renders inside `.site-title-text`).
		$logo_css = isset( $logo_custom['logo_custom_css'] ) ? $logo_custom['logo_custom_css'] : '';
		$base_decls = '';
		$fam = trim( (string) $logo['title_font'] );
		if ( $fam !== '' ) {
			$parts   = array_map( 'trim', explode( ',', $fam ) );
			$generic = strtolower( (string) end( $parts ) );
			// Carry only a DISTINCTIVE family (serif / mono / display, or a named font) — skip a plain
			// system-sans stack that already matches the theme body, so we don't needlessly override it.
			if ( in_array( $generic, array( 'serif', 'monospace', 'cursive', 'fantasy' ), true ) || preg_match( '/["\']/', $fam ) ) {
				$base_decls .= 'font-family:' . $fam . ';';
			}
		}
		if ( trim( (string) $logo['title_ls'] ) !== '' ) { $base_decls .= 'letter-spacing:' . trim( $logo['title_ls'] ) . ';'; }
		if ( ! empty( $logo['title_transform'] ) ) { $base_decls .= 'text-transform:' . $logo['title_transform'] . ';'; }
		if ( $base_decls !== '' ) { $logo_css .= '.site-title-text{' . $base_decls . '}'; }
		if ( $logo['title_hover'] !== '' ) {
			$hvar = self::palette_var_for_token( $logo['title_hover'] );  // '' for a token the palette lacks (`brand`→primary)
			if ( $hvar !== '' ) { $logo_css .= '.site-title a:hover .site-title-text,.site-title a:hover{color:' . $hvar . '}'; }
		}
		if ( $logo_css !== '' ) { $logo_custom['logo_custom_css'] = $logo_css; }

		$logo_type = ( $logo['text'] === '' && $logo['image'] !== '' ) ? 'simple' : 'custom';
		$logo_simple = array();
		if ( $logo['image'] !== '' ) {
			// Portable upload shape; attachment_id is resolved when the media pipeline sideloads it.
			$logo_simple['image'] = array( 'url' => $logo['image'], 'attachment_id' => 0 );
			$logo_simple['alt']   = $site_title;
			// the logo's RENDERED width → the Simple logo's Width option (empty auto-sizes to the bar and drew a 119×80 mark tiny)
			if ( ! empty( $logo['image_width'] ) ) { $logo_simple['width'] = array( 'value' => (string) (int) round( (float) $logo['image_width'] ), 'unit' => 'px' ); }
			// The image logo renders the site Tagline beneath it, falling back to the WordPress Tagline
			// (which this converter also sets). Most sources show no tagline in their header, so leaving
			// it On invented a line the design never had — and it inflated the header height with it.
			// Turn it off unless the SOURCE header actually shows the tagline text.
			$tag_txt = '';
			if ( isset( $logo['tagline'] ) && '' !== trim( (string) $logo['tagline'] ) ) {
				$tag_txt = trim( (string) $logo['tagline'] );
			} elseif ( isset( $tokens['site']['tagline'] ) ) {
				$tag_txt = trim( (string) $tokens['site']['tagline'] );
			}
			$shows_tagline = false;
			if ( '' !== $tag_txt && preg_match( '/<header\b[^>]*>(.*?)<\/header>/is', (string) $html, $hm ) ) {
				$header_text = trim( preg_replace( '/\s+/', ' ', wp_strip_all_tags( $hm[1] ) ) );
				$shows_tagline = ( '' !== $header_text && false !== stripos( $header_text, $tag_txt ) );
			}
			$logo_simple['logo_tagline_show'] = $shows_tagline ? 'yes' : 'no';
		}
		$values['header_logo'] = array(
			'logo_type' => array(
				'logo_type' => $logo_type,
				'custom'    => $logo_custom,
				'simple'    => $logo_simple,
			),
		);

		/* --- header_main: logo · menu · CTA --- */
		$right = array();
		// Decorative bars/pips that sat beside the source CTA (a progress meter, a rule) — emitted as
		// `custom_html` so they survive. They precede the CTA, matching the source's action cluster.
		if ( ! empty( $hdr['cta']['decor'] ) && is_array( $hdr['cta']['decor'] ) ) {
			foreach ( $hdr['cta']['decor'] as $markup ) {
				$right[] = array( 'element_type' => array(
					'element'     => 'custom_html',
					'custom_html' => array( 'custom_html_content' => (string) $markup ),
				) );
			}
		}
		// HEADER CTAs — EVERY masthead action (detect_header → ctas, DOM order), each resolved through the SHARED
		// button-preset resolver to the colour + size preset matching its OWN skin, exactly as body buttons
		// are. The presets are built here (they were only built later, at the pages step) and handed to the
		// mapper so the resolver has them. A CTA the resolver can't place falls back to its fill-class role
		// (first CTA only — the legacy single-CTA read) and to Default size; the style falls back to '' (the
		// bare `.btn`), NOT btn-primary — the theme-generator maps the SOURCE's own button onto `.btn` so an
		// unclassified CTA inherits the source look, whereas btn-primary resolved to the framework's default
		// #0d6efd blue, a colour that need not exist anywhere in the source palette.
		$btn_presets = self::build_button_presets( (string) $html );
		if ( ! empty( $btn_presets ) && method_exists( 'FW_Site_Converter_Mapper', 'set_button_presets' ) ) {
			FW_Site_Converter_Mapper::set_button_presets(
				isset( $btn_presets['button_colors'] ) ? $btn_presets['button_colors'] : array(),
				isset( $btn_presets['button_sizes'] ) ? $btn_presets['button_sizes'] : array()
			);
		}
		$has_lg_size = false;
		foreach ( (array) ( $btn_presets['button_sizes'] ?? array() ) as $sz ) { if ( ( $sz['slug'] ?? '' ) === 'lg' ) { $has_lg_size = true; break; } }
		// SECONDARY TEXT LINKS (detect_header → textLinks): "Sign in" beside the CTA → list_item elements ahead of the buttons,
		// each with the link's own colour / size / weight + hover as scoped CSS keyed by its element class.
		$tl_css = '';
		foreach ( (array) ( $hdr['textLinks'] ?? array() ) as $ti => $tl ) {
			if ( ! is_array( $tl ) || '' === trim( (string) ( $tl['label'] ?? '' ) ) ) { continue; }
			$tcls = 'sc-hdr-link' . ( $ti > 0 ? '-' . ( $ti + 1 ) : '' );
			$node = $el( 'list_item', array( 'li_text' => (string) $tl['label'], 'li_link_type' => 'url', 'li_link' => (string) ( $tl['href'] ?? '#' ), 'li_target' => '_self' ) );
			$node['element_css_class'] = $tcls;
			$right[] = $node;
			$tcs = (string) ( $tl['cs'] ?? '' ); $d = array( 'white-space:nowrap' );
			foreach ( array( 'color', 'font-size', 'font-weight', 'letter-spacing', 'text-transform', 'text-decoration-line' ) as $pr ) { if ( preg_match( '/(?:^|;)\s*' . preg_quote( $pr, '/' ) . ':\s*([^;]+)/i', $tcs, $m ) && ! in_array( strtolower( trim( $m[1] ) ), array( 'none', 'normal' ), true ) ) { $d[] = ( 'text-decoration-line' === $pr ? 'text-decoration' : $pr ) . ':' . trim( $m[1] ); } }
			$tl_css .= "\n/* Source header text link */\n.site-header ." . $tcls . " .list-item, .site-header ." . $tcls . " .list-item a{" . implode( ';', $d ) . ";}";
			if ( preg_match( '/hover-self\{[^}]*color:\s*([^;}]+)/i', (string) ( $tl['hov'] ?? '' ), $hm ) ) { $tl_css .= "\n.site-header ." . $tcls . " .list-item a:hover{color:" . preg_replace( '/\s*\/\s*var\([^)]*\)/', '', trim( $hm[1] ) ) . ";}"; }
		}
		$ctas = ( ! empty( $hdr['ctas'] ) && is_array( $hdr['ctas'] ) ) ? $hdr['ctas'] : array();
		if ( ! $ctas && $hdr['cta']['label'] !== '' ) { $ctas = array( array( 'label' => $hdr['cta']['label'], 'href' => $hdr['cta']['href'], 'cls' => '', 'cs' => '' ) ); }
		foreach ( $ctas as $ci => $c ) {
			$res = array( 'style' => '', 'size' => '' );
			if ( ( '' !== $c['cls'] || '' !== $c['cs'] ) && method_exists( 'FW_Site_Converter_Mapper', 'button_preset_for' ) ) {
				$res = FW_Site_Converter_Mapper::button_preset_for( $c['cls'], $c['cs'] );
			}
			$style = '' !== $res['style'] ? $res['style'] : ( ( 0 === $ci && ! empty( $hdr['cta']['style'] ) ) ? $hdr['cta']['style'] : '' );
			// No size match → the Default size; a Large preset that exists in the source keeps the historic
			// "header CTA = the chunky Large" choice.
			$size = '' !== $res['size'] ? $res['size'] : ( $has_lg_size ? 'btn-lg' : 'btn-md' );
			$right[] = $el( 'cta_button', array(
				'cta_text'  => $c['label'],
				'cta_link'  => '' !== $c['href'] ? $c['href'] : '#',
				'cta_style' => $style,
				'cta_size'  => $size,
			) );
		}
		// TEXT CHIPS (detect_header → chips) → native list_item elements: text + an SVG dot icon, the source's
		// responsive hide as the element's Hide On, its pill skin as scoped CSS keyed by the element CSS Class.
		$chip_els = array(); $chip_css = $tl_css;
		foreach ( (array) ( $hdr['chips'] ?? array() ) as $ci => $chip ) {
			$ccls = 'sc-hdr-chip' . ( $ci > 0 ? '-' . ( $ci + 1 ) : '' );
			$li   = array( 'li_text' => $chip['text'], 'li_link_type' => 'none', 'li_link' => '' );
			if ( ! empty( $chip['dot'] ) ) {
				$sz = (int) $chip['dot']['size'];
				$li['li_icon'] = array( 'type' => 'svg', 'svg-source' => 'inline', 'svg-id' => '',
					'markup' => '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10" width="' . $sz . '" height="' . $sz . '" aria-hidden="true"><circle cx="5" cy="5" r="5" fill="' . esc_attr( $chip['dot']['color'] ) . '"/></svg>' );
			}
			$node = $el( 'list_item', $li );
			if ( ! empty( $chip['hide'] ) ) { $node['visibility'] = $chip['hide']; }
			$node['element_css_class'] = $ccls;
			$chip_els[] = $node;
			$chip_css  .= self::header_chip_css( $chip, $ccls );
		}
		// HEADER ICON BUTTONS — a source header often ends with icon-only utility buttons (search, cart/bag).
		// Map a search icon → the native `search` element; a cart/bag icon → a `custom_html` element carrying
		// the source SVG verbatim (there is no native cart element, and on a non-WooCommerce site it's a
		// decorative link anyway). These were previously DROPPED entirely (detect_header only captured a single
		// text CTA). They ride in the RIGHT zone, before any CTA button.
		$icons    = self::detect_header_icons( (string) $html );
		$icon_els = array();
		if ( ! empty( $icons['search'] ) ) { $icon_els[] = $el( 'search' ); }
		if ( ! empty( $icons['cart_svg'] ) ) { $icon_els[] = $el( 'custom_html', array( 'custom_html_content' => $icons['cart_svg'] ) ); }
		// Place the menu in the zone the SOURCE used (detect_header → menu_pos), not a hardcoded centre.
		// centered-logo: menu LEFT · logo CENTER · icons/CTA RIGHT (the split-nav pattern — a nav cluster on
		// EACH side of a centered wordmark/emblem); right: logo-left, menu+CTA-right (`justify-between`);
		// left: menu beside the logo; center (default): logo-left, menu-center, CTA-right (classic three-zone).
		$menu_el = $el( 'menu_area', array( 'menu_location' => 'primary' ) );
		$mpos    = isset( $hdr['menu_pos'] ) ? $hdr['menu_pos'] : 'center';
		// TWO-ROW masthead (detect_header → rows): the brand row keeps logo · chips · CTAs and the links-only
		// nav row becomes the native Bottom Bar (or Top Bar) below, carrying the menu — instead of the menu
		// being squeezed into the brand row's right zone and the second row lost.
		$rows    = ( ! empty( $hdr['rows'] ) && is_array( $hdr['rows'] ) ) ? $hdr['rows'] : array();
		$two_row = ! empty( $rows['nav_pos'] );
		if ( $two_row ) {
			$header_main = array( 'main_left' => array( $el( 'logo' ) ), 'main_center' => $chip_els, 'main_right' => array_merge( $icon_els, $right ) );
		} elseif ( $chip_els ) {
			// One-row header with a chip: it rides in the right zone ahead of the icons/CTAs (the centre holds the menu).
			$icon_els = array_merge( $chip_els, $icon_els );
		}
		if ( $two_row ) {
			// (assembled above)
		} elseif ( self::detect_logo_centered( (string) $html ) ) {
			// Split nav: the Primary (left cluster) menu LEFT, logo CENTER, the Secondary (right cluster) menu
			// + icons/CTA RIGHT — reproducing the source's two-zone nav. extract_menus fills both locations; a
			// source with no real right cluster leaves Secondary empty and its menu_area renders nothing.
			$menu_right  = $el( 'menu_area', array( 'menu_location' => 'secondary' ) );
			$header_main = array( 'main_left' => array( $menu_el ), 'main_center' => array( $el( 'logo' ) ), 'main_right' => array_merge( array( $menu_right ), $icon_els, $right ) );
		} elseif ( 'right' === $mpos ) {
			$header_main = array( 'main_left' => array( $el( 'logo' ) ), 'main_center' => array(), 'main_right' => array_merge( array( $menu_el ), $icon_els, $right ) );
		} elseif ( 'left' === $mpos ) {
			$header_main = array( 'main_left' => array( $el( 'logo' ), $menu_el ), 'main_center' => array(), 'main_right' => array_merge( $icon_els, $right ) );
		} else {
			$header_main = array( 'main_left' => array( $el( 'logo' ) ), 'main_center' => array( $menu_el ), 'main_right' => array_merge( $icon_els, $right ) );
		}
		// A LABEL-ONLY masthead (header_label_zones): no link anywhere → no menu_area (the theme would print the WP primary menu
		// where the source had none); the labels ride as chips in their zones, the logo in the brand leaf's zone.
		$lbl_zones = self::header_label_zones( (string) $html, (string) $title );
		if ( is_array( $lbl_zones ) && empty( $right ) && empty( $icon_els ) ) {
			$header_main = array( 'main_left' => array(), 'main_center' => array(), 'main_right' => array() );
			$header_main[ 'main_' . $lbl_zones['logo'] ][] = $el( 'logo' );
			$li_n = count( (array) ( $hdr['chips'] ?? array() ) );
			foreach ( array( 'left', 'center', 'right' ) as $z ) {
				foreach ( $lbl_zones[ $z ] as $lab ) {
					$ccls = 'sc-hdr-chip' . ( $li_n > 0 ? '-' . ( $li_n + 1 ) : '' ); $li_n++;
					$node = $el( 'list_item', array( 'li_text' => $lab['text'], 'li_link_type' => 'none', 'li_link' => '' ) );
					$node['element_css_class'] = $ccls;
					$header_main[ 'main_' . $z ][] = $node;
					$chip_css .= self::header_chip_css( array( 'cs' => $lab['cs'] ), $ccls );
				}
			}
		}
		$values['header_main'] = $header_main;

		/* --- header chrome + nav styles read from the captured computed styles (data-sc-cs) --- */
		$hstyle = self::detect_header_chrome_styles( (string) $html );
		$mstyle = self::detect_menu_styles( (string) $html );
		// Two-row masthead: the at-rest height the theme applies to its main row is the BRAND row's own
		// height, not the two source rows stacked (the nav row is laid out as its own Bottom / Top Bar).
		if ( $two_row && ! empty( $rows['brand_height'] ) ) { $hstyle['rest_height'] = (int) $rows['brand_height']; }

		/* --- header_menu --- default colors, overridden by the REAL nav link styles when detected. --- */
		// Active/hover colour: the captured link :hover when available, else the BASE link colour brightened
		// (a translucent nav link like rgba(255,255,255,.6) → the same colour at ~.9 alpha). Falling back to a
		// brighter tint of the nav's OWN colour keeps the active/current item in the nav's palette; leaving it
		// empty let the theme paint `.current-menu-item` with `--menu-link-hover: var(--color-primary)` = the
		// brand GREEN, which no source with a white/muted nav ever has (cloud-forest's active item went green).
		$hover_c = isset( $mstyle['hover_color'] ) ? (string) $mstyle['hover_color'] : '';
		if ( '' === $hover_c ) {
			$base_c = isset( $mstyle['link_color'] ) ? (string) $mstyle['link_color'] : (string) $link_col;
			if ( preg_match( '/^rgba\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*\)$/i', $base_c, $bm ) && (float) $bm[4] < 0.9 ) {
				$hover_c = 'rgba(' . $bm[1] . ', ' . $bm[2] . ', ' . $bm[3] . ', 0.9)';
			} elseif ( '' !== trim( $base_c ) ) {
				$hover_c = $base_c;
			} else {
				$hover_c = $hdr['dark'] ? '#ffffff' : ( $accent !== '' ? $accent : $ink );
			}
		}
		$menu = array(
			'menu_link_color'       => $hex( isset( $mstyle['link_color'] ) ? $mstyle['link_color'] : $link_col ),
			'menu_link_hover_color' => $hex( $hover_c ),
		);
		if ( isset( $mstyle['font_size'] ) )   { $menu['menu_link_font_size'] = $mstyle['font_size']; }
		if ( ! empty( $mstyle['font_family'] ) ) { $menu['menu_font'] = array( 'family' => (string) $mstyle['font_family'] ); } // the nav's own face (Header → Menu → Menu Font Family)
		if ( isset( $mstyle['font_weight'] ) ) { $menu['menu_link_font_weight'] = $mstyle['font_weight']; }
		// NEVER-DROP menu typography — the source's `tracking-*` + `uppercase` utilities → native options.
		if ( isset( $mstyle['letter_spacing'] ) ) { $menu['menu_link_letter_spacing'] = $mstyle['letter_spacing']; }
		if ( ! empty( $mstyle['uppercase'] ) )    { $menu['menu_link_uppercase'] = 'yes'; }
		// H3 — Menu Item Style + item fill + link padding (only on a real signal from detect_menu_styles).
		if ( isset( $mstyle['item_style'] ) )  { $menu['menu_item_style'] = $mstyle['item_style']; }
		if ( isset( $mstyle['item_bg'] ) )     { $menu['menu_item_bg'] = $hex( $mstyle['item_bg'] ); }
		if ( isset( $mstyle['pad_x'] ) )       { $menu['menu_link_padding_x'] = $mstyle['pad_x']; }
		if ( isset( $mstyle['pad_y'] ) )       { $menu['menu_link_padding_y'] = $mstyle['pad_y']; }
		// Padding-less nav (spaced by the row's gap): the gap has no native menu field → a scoped rule on the
		// theme's own menu list, so the items keep the source spacing now that the link inset is 0.
		$menu_gap_css = ( ! empty( $mstyle['gap'] ) ) ? "\n/* Source nav item gap (padding-less links) */\n.site-header .primary-menu{gap:" . (int) $mstyle['gap'] . 'px;}' : '';
		// H4 — Submenu / dropdown panel styling, when the source header actually has a dropdown.
		$sub = self::detect_submenu_styles( (string) $html );
		if ( isset( $sub['menu_dropdown_bg'] ) )     { $menu['menu_dropdown_bg'] = $hex( $sub['menu_dropdown_bg'] ); }
		if ( isset( $sub['menu_dropdown_link'] ) )   { $menu['menu_dropdown_link'] = $hex( $sub['menu_dropdown_link'] ); }
		if ( isset( $sub['menu_dropdown_radius'] ) ) { $menu['menu_dropdown_radius'] = $sub['menu_dropdown_radius']; }
		if ( isset( $sub['menu_dropdown_width'] ) )  { $menu['menu_dropdown_width'] = $sub['menu_dropdown_width']; }
		if ( isset( $sub['menu_dropdown_style'] ) )  { $menu['menu_dropdown_style'] = $sub['menu_dropdown_style']; }
		$values['header_menu'] = $menu;

		/* --- header_layout — switches/bg driven by the detected header chrome (only override defaults on a
		   real signal, so we never write a false 'yes'). --- */
		$has_src_bg    = isset( $hstyle['bg'] ) && '' !== (string) $hstyle['bg']; // did the SOURCE header carry a real fill?
		$header_bg_val = $has_src_bg ? (string) $hstyle['bg'] : $header_bg;
		// GLASS double-reduction guard. The theme's CLASSIC glass frosts the header to ~72% of --header-bg. A
		// source header fill that is ALREADY translucent (e.g. `bg-background/80` = rgba(…, .8)) would then
		// double-reduce (.8 → .576) — too see-through, so the hero bleeds up and it reads "too transparent".
		// When a CLASSIC header is glass, feed the OPAQUE colour so the single 72% frost lands cleanly.
		// EXCEPTION — PILL design: the pill's own tint is `color-mix(--header-bg 72%, transparent)`, so a
		// LOW-opacity source fill (cloud-forest's `rgba(0,0,0,0.3)`) must stay TRANSLUCENT — flattening it to
		// opaque made the pill a ~72% near-black slab instead of the source's see-through 30% smoke (v2 Bug 2).
		$header_bg_glass = $header_bg_val;
		// Header DESIGN — classic | pill | card | centered — from the deterministic classifier (reads the real
		// nav SURFACE + its float treatment, not just "a rounded-full descendant exists" which mis-pilled every
		// header carrying a round logo/CTA). Computed here so the glass guard + design assignment agree.
		$h_design        = self::detect_header_design( (string) $html );
		$is_pill_hdr     = ( 'pill' === $h_design );
		if ( ! $is_pill_hdr && ! empty( $hstyle['glass'] ) && preg_match( '/^rgba?\(\s*([\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+)\s*,\s*(?:0?\.\d+|0)\s*\)\s*$/i', (string) $header_bg_val, $am ) ) {
			$header_bg_glass = 'rgb(' . trim( $am[1] ) . ')';
		}
		// Header DESIGN + the TWO-STATE model (see the Header Layout doc). POSITION comes from the RESTING
		// snapshot: a pinned (fixed/sticky) header with a TRANSPARENT fill sitting over the hero = overlay; a
		// pinned SOLID header = sticky; otherwise static. AT-TOP appearance = the resting reads; ON-SCROLL
		// appearance = the captured scroll state (data-sc-scrolled).
		$h_design_sub = self::header_design_sub( (string) $html, $h_design, $hstyle );
		// LAYOUT MODE — top (a normal horizontal header, whose Design is $h_design) vs a non-top mode
		// (vertical side rail / off-canvas-only / overlay fullscreen). A non-top mode replaces the top+design
		// structure entirely with its own value tree (rail side/width, etc.).
		$h_mode = self::detect_header_mode( (string) $html );
		$header_mode_val = ( 'top' === $h_mode )
			? array( 'mode' => 'top', 'top' => array( 'header_design' => array_merge( array( 'design' => $h_design ), ( $h_design_sub ? array( $h_design => $h_design_sub ) : array() ) ) ) )
			: self::header_mode_values( (string) $html, $h_mode );
		$h_bg      = isset( $hstyle['bg'] ) ? (string) $hstyle['bg'] : '';
		$h_solid   = $h_bg !== '' && empty( $hstyle['glass'] ) && ! preg_match( '/rgba?\([^)]*[,\/]\s*(0|0?\.\d+)\s*\)/i', $h_bg );
		$h_pinned  = ! empty( $hdr['sticky'] );
		$position  = $h_pinned ? ( $h_solid ? 'sticky' : 'overlay' ) : 'static';
		// A header with NO captured fill that is GLASS or sits OVERLAY over the hero is TRANSPARENT by design
		// (a frosted bar you see the hero through). Its bg_color must stay EMPTY — otherwise the #ffffff
		// fallback default ($header_bg) turns a transparent glass nav into a solid WHITE bar (the reported bug).
		$header_transparent = ! $has_src_bg && ( ! empty( $hstyle['glass'] ) || 'overlay' === $position );
		$values['header_layout'] = array(
			'header_mode'          => $header_mode_val,
			'header_position'      => $position,
			'header_uppercase_nav' => ! empty( $mstyle['uppercase'] ) ? 'yes' : 'no',
			// Appearance — AT TOP (the resting look only). bg_color = the resting SOLID fill from the SOURCE;
			// EMPTY for a transparent / overlay header (its scrolled fill, if any, is scroll_bg_color below).
			// Only a real source fill is used — never the #ffffff fallback on a transparent header.
			'bg_color'             => ( ! $header_transparent && $header_bg_glass !== '' ) ? $hex( $header_bg_glass ) : array( 'predefined' => '', 'custom' => '' ),
			'header_glass'         => ! empty( $hstyle['glass'] ) ? 'yes' : 'no',
			'header_border'        => ! empty( $hstyle['border'] ) ? 'yes' : 'no',
			'header_shadow'        => ! empty( $hstyle['shadow'] ) ? 'yes' : 'no',
		);
		// Frost radius / saturation and shadow depth apply to BOTH states, so they sit beside the
		// at-top chrome rather than inside the on-scroll block. Each is emitted only when it differs
		// from the theme's historic baked-in value, so a default conversion is unchanged.
		// At-rest header height. The theme default is 80px, so any other source height was silently
		// normalised to 80 — visible immediately as a bar that is the wrong size before you scroll.
		// A FLOATING card / pill design: the theme's min-height is the CARD row's (the bar = card + the design's offsets), so the
		// measured height of the floating SURFACE is the value — the whole bar's height (surface + its gaps) stacked the gaps twice
		// (a 122px source bar became 181px: a 122px card inside 20px offsets).
		if ( in_array( $h_design, array( 'card', 'pill' ), true ) ) {
			$hdom_s = self::load_dom( (string) $html ); $hroot_s = $hdom_s ? self::header_root( $hdom_s ) : null; $surf_s = ( $hroot_s instanceof DOMElement ) ? self::header_float_surface( $hroot_s ) : null;
			if ( $surf_s instanceof DOMElement && preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', (string) $surf_s->getAttribute( 'data-sc-cs' ), $shm ) && (float) $shm[1] >= 32 ) {
				// the min-height is the surface's CONTENT height (the theme adds the card's padding + border around it)
				$spad = self::sc_padding_box( $surf_s ); $sb = preg_match( '/(?:^|;)\s*border-top-width:\s*([0-9.]+)px/i', (string) $surf_s->getAttribute( 'data-sc-cs' ), $sbm ) ? (float) $sbm[1] : 0.0;
				$hstyle['rest_height'] = max( 32, (int) round( (float) $shm[1] - (float) $spad['top'] - (float) $spad['bottom'] - 2 * $sb ) );
			}
		}
		if ( ! empty( $hstyle['rest_height'] ) ) {
			$values['header_layout']['min_height'] = array( 'value' => (string) (int) $hstyle['rest_height'], 'unit' => 'px' );
		}
		// A source that blurs WITHOUT saturating must say so: the theme's frost adds saturate(1.4) by
		// default, which over-saturates what shows through against a literal blur-only source.
		// Frost radius / saturation: prefer the scrolled reading, else the RESTING backdrop-filter
		// (`glass_backdrop`), which is the only signal a header that never changes on scroll has.
		if ( empty( $hstyle['glass_blur'] ) && ! empty( $hstyle['glass_backdrop'] ) ) {
			if ( preg_match( '/blur\(\s*([0-9.]+)px/i', $hstyle['glass_backdrop'], $rbm ) ) {
				$hstyle['glass_blur'] = (int) round( (float) $rbm[1] );
			}
			if ( preg_match( '/saturate\(\s*([0-9.]+)(%?)/i', $hstyle['glass_backdrop'], $rsm ) ) {
				$hstyle['glass_saturate'] = (int) round( '%' === $rsm[2] ? (float) $rsm[1] : ( (float) $rsm[1] * 100 ) );
			}
		}
		if ( ! empty( $hstyle['glass_blur'] ) && empty( $hstyle['glass_saturate'] ) ) {
			$values['header_layout']['header_glass_saturate'] = 100;
		}
		if ( ! empty( $hstyle['glass_blur'] ) && 10 !== (int) $hstyle['glass_blur'] ) {
			$values['header_layout']['header_glass_blur'] = array( 'value' => (string) (int) $hstyle['glass_blur'], 'unit' => 'px' );
		}
		if ( ! empty( $hstyle['glass_saturate'] ) ) {
			$gs = (int) $hstyle['glass_saturate'];
			if ( $gs >= 100 && $gs <= 200 && 140 !== $gs ) { $values['header_layout']['header_glass_saturate'] = $gs; }
		}
		if ( ! empty( $hstyle['shadow_depth'] ) && 'medium' !== $hstyle['shadow_depth'] ) {
			$values['header_layout']['header_shadow_depth'] = (string) $hstyle['shadow_depth'];
		}
		// Appearance — ON SCROLL, from the captured scroll state (data-sc-scrolled). When the scrolled header
		// differs from resting (a bg / backdrop-blur / border / shadow / padding revealed on scroll), enable
		// Change-on-scroll and map each delta to its scroll_* option — the OBSIDIAN pattern (clear over the
		// hero, then a frosted + shrunk bar) reproduces natively instead of being flattened into one enum.
		$sc_glass  = ! empty( $hstyle['scroll_glass'] );
		$sc_border = ! empty( $hstyle['scroll_border'] );
		$sc_shadow = ! empty( $hstyle['scroll_shadow'] );
		$sc_shrink = ! empty( $hstyle['scroll_shrink'] );
