			} elseif ( ( $sc_glass || 'overlay' === $position ) && '' !== $dark ) {
				$nav_col = ( isset( $mstyle['link_color'] ) && is_string( $mstyle['link_color'] ) && '' !== $mstyle['link_color'] )
					? $mstyle['link_color']
					: ( is_string( $link_col ) ? $link_col : '' );
				if ( '' !== $nav_col && ! self::color_is_dark( $nav_col ) ) {
