					'topbar_left'   => array(),
					'topbar_center' => array( array( 'element_type' => array( 'element' => 'custom_html', 'custom_html' => array( 'custom_html_content' => $marq ) ) ) ),
					'topbar_right'  => array(),
				);
			} else {
