					'topbar_left'   => '' !== $tb['left']   ? array( $tcell( $tb['left'] ) )   : array(),
					'topbar_center' => '' !== $tb['center'] ? array( $tcell( $tb['center'] ) ) : array(),
					'topbar_right'  => '' !== $tb['right']  ? array( $tcell( $tb['right'] ) )  : array(),
