			$bar    = ( 'top' === $rows['nav_pos'] && empty( $tb['has'] ) ) ? 'topbar' : 'bottombar';
			$col    = $bar . '_' . ( isset( $rows['align'] ) ? $rows['align'] : 'center' );
			$bar_k  = 'header_' . $bar;
