				$bcs[ $bar . '_border' ]        = array( 'width' => array( 'value' => (string) (int) $rows['border']['width'], 'unit' => 'px' ), 'style' => (string) $rows['border']['style'], 'color' => array( 'predefined' => '', 'custom' => $bcus ) );
				$bcs[ $bar . '_border_sides' ]  = array( (string) $rows['border']['side'] );
