		// the CTA's white 30px display heading is the "first footer heading" and its colour/size get applied to
		// the real column headings (white-on-white), and the CTA's white text is read as the footer text colour.
		// `$html` keeps the CTA (footer_split_cta works on a copy) for the lead/CTA styling that needs it.
		$cta_split  = self::footer_split_cta( (string) $html );
		$route_html = ( is_array( $cta_split ) && isset( $cta_split['rest'] ) ) ? (string) $cta_split['rest'] : (string) $html;

		/* --- footer colors (background-pro shape for the fill) --- read the SOURCE footer's real colors
		   from its captured computed style, falling back to palette-dark only when unknown. --- */
		$fstyle      = self::detect_footer_style( $route_html );
		$footer_text = $fstyle['text'] !== '' ? $fstyle['text'] : '#94a3b8';
		$footer_bg   = $fstyle['bg'];
		// Contrast guard: NEVER pair a dark bg with dark text (the old palette-dark fallback did exactly that
		// on a light footer → an unreadable near-black band). If no bg was detected, or bg-vs-text contrast is
		// too low, derive a bg that contrasts the text: dark text → light footer, else the palette dark.
		$bl = self::rel_luma( $footer_bg );
		$tl = self::rel_luma( $footer_text );
		if ( $footer_bg === '' || ( $bl !== null && $tl !== null && abs( $bl - $tl ) < 0.3 ) ) {
			$footer_bg = ( $tl !== null && $tl < 0.5 ) ? '#f4f4f7' : $dark;
		}
		$values['footer_background'] = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => $footer_bg ) ) );
		// A GRADIENT footer background: one linear layer → the native Background gradient; a multi-layer stack (a
		// radial glow over a linear wash) → the whole value verbatim on .footer (the native field holds one layer).
		$fbg_verbatim = '';
		$fbg_el = self::footer_root_el( $route_html );
		$fbgi   = ( $fbg_el instanceof DOMElement ) ? trim( (string) self::sc_css( $fbg_el, 'background-image' ) ) : '';
		if ( $fbgi !== '' && stripos( $fbgi, 'gradient' ) !== false && stripos( $fbgi, 'url(' ) === false ) {
			$gv = class_exists( 'FW_Site_Converter_Mapper' ) ? FW_Site_Converter_Mapper::parse_linear_gradient( $fbgi ) : null;
			if ( is_array( $gv ) ) { $values['footer_background']['gradient'] = array( 'data' => $gv ); }
			else { $fbg_verbatim = '.footer{background-image:' . $fbgi . ';}'; }
		}
		$values['footer_text_color'] = $hex( $footer_text );
		$values['footer_link_color'] = $hex( $footer_text );
		// Footer numeric refinements (theme 2.5.92), read from the capture's `data-sc-footer` stamp —
		// a hover colour needs a real pointer, and the column gap / phone column count are computed
		// values, so none of them can be recovered from the static HTML alone.
		$f_stamp = '';
		if ( preg_match( '/<footer[^>]*\sdata-sc-footer="([^"]*)"/i', (string) $html, $fm ) ) {
			$f_stamp = html_entity_decode( $fm[1], ENT_QUOTES );
		}
		if ( '' !== $f_stamp ) {
			$fp = array();
			foreach ( explode( ';', $f_stamp ) as $d ) {
				$cp = strpos( $d, ':' );
				if ( false === $cp ) { continue; }
				$fp[ strtolower( trim( substr( $d, 0, $cp ) ) ) ] = trim( substr( $d, $cp + 1 ) );
			}
			// Column gap — the theme's grid default is 40px, so only a real difference is worth storing.
			if ( ! empty( $fp['col-gap'] ) && preg_match( '/([0-9.]+)px/', $fp['col-gap'], $gm ) ) {
				$g = (int) round( (float) $gm[1] );
				if ( $g >= 0 && abs( $g - 40 ) > 2 ) {
					$values['footer_col_gap'] = array( 'value' => (string) $g, 'unit' => 'px' );
				}
			}
			// Link hover colour — 90% of real footers change it; the theme used to only fade.
			if ( ! empty( $fp['link-hover'] ) && $fp['link-hover'] !== $footer_text ) {
				$values['footer_link_hover_color'] = $hex( $fp['link-hover'] );
			}
			// Columns kept on a phone (the footer otherwise stacks unconditionally under 768px).
			if ( ! empty( $fp['mobile-cols'] ) && (int) $fp['mobile-cols'] >= 2 ) {
				$values['footer_mobile_columns'] = '2';
			}
		}
		// Exact footer padding when the source is OFF the theme's spacing scale (which tops out at
		// 8rem) — otherwise a 160-240px footer clamps to the ceiling and loses up to 112px.
		if ( preg_match( '/<footer[^>]*\sdata-sc-cs="([^"]*)"/i', (string) $html, $fcm ) ) {
			$cs_raw = html_entity_decode( $fcm[1], ENT_QUOTES );
			if ( preg_match( '/(?:^|;)\s*padding\s*:\s*([^;]+)/i', $cs_raw, $pm ) ) {
				$parts = preg_split( '/\s+/', trim( $pm[1] ) );
				$scale = array( 0, 4, 8, 16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128 );
				$on_scale = function ( $px ) use ( $scale ) {
					foreach ( $scale as $v ) { if ( abs( $v - $px ) <= 1 ) { return true; } }
					return false;
				};
				$ptop = isset( $parts[0] ) ? (float) $parts[0] : 0;
				$pbot = isset( $parts[2] ) ? (float) $parts[2] : $ptop;
				if ( $ptop > 0 && ! $on_scale( $ptop ) ) { $values['footer_padding_top_custom'] = array( 'value' => (string) (int) round( $ptop ), 'unit' => 'px' ); }
				if ( $pbot > 0 && ! $on_scale( $pbot ) ) { $values['footer_padding_bottom_custom'] = array( 'value' => (string) (int) round( $pbot ), 'unit' => 'px' ); }
			}
		}

		/* --- SITE (body/page) background → the editable Site Background option (General Layout). The
		   background RESOLVER detected the source's real page canvas — including a `<style> body{background:…}`
		   an AI page sets that no Tailwind token carries, with oklch/hsl normalized to hex — into the
		   `background` token. Surface it as the NATIVE, editable `background-pro` option (→ --site-bg-color)
		   instead of ONLY a baked body rule. The child theme's body fallback reads `var(--site-bg-color, …)`
		   (no !important), so editing this option takes effect. Only set on a real detected canvas. --- */
		// Include `bg` / `canvas` — the extractor keys the page canvas as `bg` (e.g. a dark `rgb(10,10,10)`),
		// NOT `background`; the old list missed it, so a dark source's <body> stayed the palette default WHITE
		// (light body text then rendered invisible on white in any uncovered gap).
		// GROUND TRUTH FIRST: the RENDERED <body>/<html> background the capture stamped (data-sc-cs) — the
		// browser already resolved it to rgb()/oklch()/hsl() regardless of how the source declared its canvas
		// (a `class="dark"` theme, an oklch() body rule, a CSS var). color_to_hex resolves oklch/hsl. This
		// OUTRANKS the palette `bg`/`canvas` token because the token builder sometimes mis-defaults an
		// unresolvable dark canvas to WHITE — which kept a dark AI page white (light body text then invisible
		// in any uncovered gap). Only when the rendered body carries no solid canvas do we fall back to the token.
		$site_bg = self::color_to_hex( self::detect_body_background( (string) $html ) );
		if ( '' === $site_bg ) {
			$site_bg = self::token_color( $tokens, array( 'background', 'bg', 'canvas', 'surface', 'surface-container-lowest' ) );
		}
		if ( $site_bg !== '' ) {
			// NOTE: the theme reads Site Background from the `general_layout` container
			// (theme-vars.php merges general_layout/sidebar/preloader → $layout['site_background']),
			// NOT a top-level `site_background` key — a top-level key is silently ignored, leaving the
			// page canvas at the palette default (#ffffff) even for a dark source. Nest it correctly.
			if ( ! isset( $values['general_layout'] ) || ! is_array( $values['general_layout'] ) ) { $values['general_layout'] = array(); }
			$values['general_layout']['site_background'] = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => $site_bg ) ) );
		}
		// PAGE-WIDE FIXED PATTERN layer — a body-level fixed inset-0 decorative wrapper (pointer-events none, no text) painting a
		// CSS gradient grid / a data-URI tile (a console design's terminal grid) → Theme Settings → General → Layout → Site
		// Background Pattern, backed by a registered Background Pattern preset carrying the image + its tile size. The theme
		// prints it once, fixed, behind all content — exactly the source's layer. (A blurred glow blob beside it is not a tile.)
		$spat = self::detect_page_fixed_pattern( (string) $html );
		if ( is_array( $spat ) ) {
			$pid = class_exists( 'FW_Site_Converter_Mapper' ) ? FW_Site_Converter_Mapper::pattern_id_for_image( $spat['image'] ) : 'captured-' . substr( md5( $spat['image'] ), 0, 8 );
			if ( class_exists( 'FW_Site_Converter_Mapper' ) ) { FW_Site_Converter_Mapper::register_captured( 'pattern', $pid, array( 'image' => $spat['image'], 'opacity' => $spat['opacity'], 'extra' => $spat['extra'] ) ); }
			if ( ! isset( $values['general_layout'] ) || ! is_array( $values['general_layout'] ) ) { $values['general_layout'] = array(); }
			$values['general_layout']['site_background_pattern'] = array( 'pattern' => $pid );
		}

		// PAGE-WIDE FIXED VIDEO backdrop → the Site Background's video layer in FIXED mode. A single
		// `position:fixed` full-viewport <video> the whole page scrolls over (lumina-arctic's `div.video-portal`)
		// is not a per-section background — CSS can't pin a <video> and UnysonPlus backgrounds are per-section —
		// so route it to the SITE background, where the theme prints it once behind all content. The source URLs
		// are written in the `{ url, attachment_id }` upload shape so localize_media() sideloads them on import.
		$pfv = self::detect_page_fixed_video( (string) $html );
		if ( is_array( $pfv ) && ( ! empty( $pfv['mp4'] ) || ! empty( $pfv['webm'] ) ) ) {
			if ( ! isset( $values['general_layout'] ) || ! is_array( $values['general_layout'] ) ) { $values['general_layout'] = array(); }
			if ( empty( $values['general_layout']['site_background'] ) || ! is_array( $values['general_layout']['site_background'] ) ) {
				$values['general_layout']['site_background'] = array();
			}
			$video = array(
				'enabled'     => 'yes',
				'position'    => 'fixed',
				'loop'        => 'yes',
				'autoplay'    => 'yes',
				'mute'        => 'yes',
				'playsinline' => 'yes',
			);
			if ( ! empty( $pfv['mp4'] ) )    { $video['source_mp4']  = array( 'url' => $pfv['mp4'],    'attachment_id' => '' ); }
			if ( ! empty( $pfv['webm'] ) )   { $video['source_webm'] = array( 'url' => $pfv['webm'],   'attachment_id' => '' ); }
			if ( ! empty( $pfv['poster'] ) ) { $video['poster']      = array( 'url' => $pfv['poster'], 'attachment_id' => '' ); }
			$values['general_layout']['site_background']['video'] = $video;
			self::$page_backdrop_css = (string) ( $pfv['css'] ?? '' ); // the layer's own geometry / mask / filter / glow → Misc Custom CSS (appended with the shell rules)
		}

		/* --- BODY TEXT (ink) → Typography body colour (→ --color-text). The source declares a real body
		   text colour (a dark site sets `body{color:#f8fafc}` = light ink). Without carrying it, every
		   element that inherits --color-text (card titles, card copy, overlines/meta, testimonial author,
		   any heading without an explicit colour) keeps the theme default #212529 (near-black) — INVISIBLE
		   on a dark canvas. theme-vars.php reads `typography.body.color` → --color-text unconditionally
		   (works in preset mode too), so surface the detected ink as the NATIVE, editable Typography body
		   colour. Only set on a real detected colour; a light source resolves to a dark ink = the default. --- */
		// Resolve it here; it is folded into the Typography `body.color` where the $typo container is
		// assembled below (that assignment rebuilds $values['typography'], so setting it earlier is lost).
		$body_ink = self::color_to_hex( self::detect_body_text( (string) $html ) );
		// Fallback when no `body{color}` is declared (the class-based `text-white` / per-wrapper case):
		// sample the DOMINANT text colour off the page — same chain the brand-palette Ink role uses.
		if ( $body_ink === '' ) { $body_ink = self::color_to_hex( self::sample_ink( (string) $html ) ); }

		// LIGHT-TEXT ⇒ DARK-CANVAS safety net: a dark source whose canvas lives only in a fixed / WebGL /
		// full-page-video backdrop the capture couldn't stamp leaves $site_bg empty — yet the body text is
		// LIGHT (near-white). Light text on the theme's default WHITE page is invisible. When NOTHING else
		// detected a canvas but the resolved body ink reads light, infer a neutral near-black page background
		// so the light text stays legible (an editable Site Background the user can retint). Never fires for a
		// light source (dark ink) or when a real canvas was already found.
		if ( '' === $site_bg && $body_ink !== '' ) {
			$ink_l = self::rel_luma( $body_ink );
			if ( $ink_l !== null && $ink_l > 0.6 ) {
				if ( ! isset( $values['general_layout'] ) || ! is_array( $values['general_layout'] ) ) { $values['general_layout'] = array(); }
				if ( empty( $values['general_layout']['site_background'] ) ) {
					$values['general_layout']['site_background'] = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => '#0a0a0f' ) ) );
				}
			}
		}

		/* --- footer chrome (padding / top border) → native footer_layout options, from computed styles. --- */
		$fchrome = self::detect_footer_chrome_styles( (string) $html );
		if ( isset( $fchrome['pad_top'] ) )    { $r = self::css_len_to_rem( $fchrome['pad_top'] );    if ( $r !== '' ) { $values['footer_padding_top'] = $r; } }
		if ( isset( $fchrome['pad_bottom'] ) ) { $r = self::css_len_to_rem( $fchrome['pad_bottom'] ); if ( $r !== '' ) { $values['footer_padding_bottom'] = $r; } }
		// The footer's measured vertical padding is the WHOLE inset (the source's `py-12` sits on the footer, its row has none):
		// the main section's own default 1rem top + bottom rode on top of it (a 133px footer rendered 165 — a real-site report),
		// so the section takes zero padding through its Custom Styling (the footer builder's `_padding` spacing option).
		// …the section's own inset is the main ROW's measured vertical margin + padding (`mb-16` under a link grid = 64 below,
		// nothing above), snapped to the nearest spacing-scale slug (the Custom Styling spacing option renders scale utilities only).
		if ( isset( $fchrome['pad_top'] ) || isset( $fchrome['pad_bottom'] ) ) {
			$mrow = self::footer_main_row_el( self::footer_root_el( (string) $html ) );
			if ( $mrow instanceof DOMElement ) {
				$rm = self::el_margin( $mrow ); $rp = self::cs_decls_pad( (string) $mrow->getAttribute( 'data-sc-cs' ) );
				$top = max( 0.0, (float) ( $rm['top'] ?? 0 ) ) + ( is_array( $rp ) ? (float) $rp['top'] : (float) self::sc_pad_top_px( $mrow ) );
				$bot = max( 0.0, (float) ( $rm['bottom'] ?? 0 ) ) + ( is_array( $rp ) ? (float) $rp['bottom'] : 0.0 );
				$slug = function ( $px ) { $scale = array( 0 => '0', 4 => '1', 8 => '2', 16 => '3', 24 => '4', 48 => '5', 56 => '6', 64 => '7', 72 => '8', 80 => '9', 96 => '10', 112 => '11', 128 => '12' ); $best = '0'; $bd = PHP_INT_MAX; foreach ( $scale as $v => $sl ) { $d = abs( $v - $px ); if ( $d < $bd ) { $bd = $d; $best = $sl; } } return $best; };
				$cur = ( isset( $values['main_footer_custom_styling']['yes'] ) && is_array( $values['main_footer_custom_styling']['yes'] ) ) ? $values['main_footer_custom_styling']['yes'] : array();
				$cur['main_footer_padding'] = array( 'margin' => array( 'all' => '', 'top' => '', 'right' => '', 'bottom' => '', 'left' => '' ), 'padding' => array( 'all' => '', 'top' => 'pt-' . $slug( $top ), 'right' => '', 'bottom' => 'pb-' . $slug( $bot ), 'left' => '' ), 'advanced' => array() );
				$values['main_footer_custom_styling'] = array( 'enabled' => 'yes', 'yes' => $cur );
			}
		}
		if ( isset( $fchrome['border'] ) && is_array( $fchrome['border'] ) ) {
			$bw = self::css_len_to_unit( $fchrome['border']['width'] );
			if ( $bw ) {
				$values['footer_border_top']       = array( 'width' => $bw, 'style' => ( $fchrome['border']['style'] !== '' ? $fchrome['border']['style'] : 'solid' ), 'color' => $hex( $fchrome['border']['color'] ) );
				$values['footer_border_sides']     = array( 'top' );
				$values['footer_border_top_extent'] = array( 'mode' => 'full' );
			}
		}

		// Footer LOGO legibility: the footer `logo` element renders the SAME lockup as the header, which
		// carries the header's (often DARK) wordmark/mark color — invisible on a dark footer. Scope the footer
		// brand to the footer text color so it reads LIGHT. The framed icon tile (its own bg + mark) is left
		// alone (it's designed to contrast). This is the native model's footer-scoped-CSS escape hatch.
		$residual = array();
		if ( ! empty( $fbg_verbatim ) ) { $residual[] = $fbg_verbatim; } // a multi-layer footer gradient (see footer_background above)
		if ( '' !== self::$header_card_css ) { $residual[] = self::$header_card_css; self::$header_card_css = ''; } // the floating card's side inset + cap
		// A BLENDED masthead (`mix-blend-mode:difference` on a transparent fixed bar: white labels that read dark over a light
		// page and light over the dark footage below) — the blend is the header's legibility; without it the white labels
		// vanish on the light ground. Carried on the theme's header (which paints no fill of its own in overlay mode).
		{ $hdom = self::load_dom( (string) $html ); $hroot = $hdom ? self::header_root( $hdom ) : null;
			if ( $hroot instanceof DOMElement && preg_match( '/(?:^|;)\s*mix-blend-mode:\s*(?!normal)([a-z-]+)/i', (string) $hroot->getAttribute( 'data-sc-cs' ), $bmm ) ) { $residual[] = '.site-header{mix-blend-mode:' . strtolower( $bmm[1] ) . ';background:transparent !important;}'; } }
		// HEADER GLASS — exact frost. `header_glass=yes` (native) supplies the translucent bg + the theme's
		// default blur; the source's EXACT `backdrop-filter` has no native field, so carry it as a scoped
		// override here. Safe unconditionally: backdrop-filter only shows over a translucent fill, so if the
		// user later turns Translucent/Glass OFF (opaque bg), this blur has nothing behind it to show — the
		// native toggle still governs the visible result. This is the native-option + child-CSS-override pattern.
		if ( ! empty( $hstyle['glass_backdrop'] ) && preg_match( '/^[a-z0-9()%.\s,-]+$/i', (string) $hstyle['glass_backdrop'] ) ) {
			$hbfv        = trim( (string) $hstyle['glass_backdrop'] );
			$hdr_design  = isset( $values['header_layout']['header_mode']['top']['header_design']['design'] ) ? (string) $values['header_layout']['header_mode']['top']['header_design']['design'] : '';
			if ( 'pill' === $hdr_design && preg_match( '/blur\(\s*([0-9.]+)px/i', $hbfv, $bpm ) && (float) $bpm[1] > 0 && (float) $bpm[1] <= 100 ) {
				// PILL design: the theme scopes the frost to the CONTAINED pill (`.header-main > .fw-container`)
				// via the `--glass-blur` variable. Feed only the blur STRENGTH — NEVER a raw full-width
				// backdrop-filter on `.site-header`/`.header-main`, which frosted the whole bar and, over the dark
				// hero, rendered it as a black full-width band with an empty pill outline (v2 report Bug 1).
				$bpx = rtrim( rtrim( sprintf( '%.2f', (float) $bpm[1] ), '0' ), '.' );
				$residual[] = ".site-header{--glass-blur:{$bpx}px}";
			} else {
				// CLASSIC (full-width) header: the whole bar IS the frosted surface (the theme's classic glass has
				// no --glass-blur hook), so carry the exact backdrop-filter. Correct for a bar; only the pill case
				// above must avoid it.
				$residual[] = ".site-header,.site-header .header-main{-webkit-backdrop-filter:{$hbfv};backdrop-filter:{$hbfv}}";
			}
		}
		$residual[] = ".footer .site-title-text,.footer .site-logo__eyebrow,.footer .site-logo__sub{color:{$footer_text} !important}";
		$residual[] = ".footer .site-logo__mark:not(.site-logo__mark--framed){color:{$footer_text} !important}";
		// NEVER-DROP footer COLUMN-HEADING typography — a footer whose titles are e.g.
		// `uppercase tracking-[0.3em] text-[10px]` has no native footer-heading option, so carry the
		// transform / letter-spacing / weight / size / colour as a scoped `.footer-links-title` rule.
		// Read from the CTA-stripped html so the FIRST heading/link/tagline sampled is a real MAIN-footer one —
		// not the CTA band's white 30px display heading (which would paint every column title white-on-white).
		$fh_css = self::footer_heading_css( $route_html );
		if ( $fh_css !== '' ) { $residual[] = $fh_css; }
		$fl_css = self::footer_link_css( $route_html );
		if ( $fl_css !== '' ) { $residual[] = $fl_css; }
		$ft_css = self::footer_tagline_css( $route_html );
		if ( $ft_css !== '' ) { $residual[] = $ft_css; }
		// NEVER-DROP footer LEAD-HEADING (display CTA lockup, e.g. "Tell us your story / Get in touch") →
		// scoped `.footer-lead-title` / `.footer-lead-subtitle` rules. detect_footer_lead_heading() emits the
		// clean markup with those hook classes; the look rides here, not as inline styles in the element.
		$fld_css = self::footer_lead_css( (string) $html );
		if ( $fld_css !== '' ) { $residual[] = $fld_css; }
		// The FOOTER's own brand lockup differs from the masthead's (a bare 20px glyph + a 14px wordmark, no white circle):
		// the theme reuses the header logo in the footer, so re-measure the footer's mark + wordmark and scope them.
		$fbr_css = self::footer_brand_css( $route_html, (string) $site_title );
		if ( $fbr_css !== '' ) { $residual[] = $fbr_css; }
		// RESIDUAL (no native option): a rounded footer top (e.g. `rounded-t-[3rem]`) → scoped CSS. Not
		// double-applied (there is no native footer border-radius option). Header chrome with no option can
		// join here too; for now only the footer top-radius is emitted when the source has one.
		if ( isset( $fchrome['radius'] ) && $fchrome['radius'] !== '' ) {
			// Keep only the TOP corners (a footer rounds its top edge onto the page above it).
			$parts = preg_split( '/\s+/', trim( (string) $fchrome['radius'] ) );
			$tl = isset( $parts[0] ) ? $parts[0] : '0';
			$tr = isset( $parts[1] ) ? $parts[1] : $tl;
			if ( self::css_len_present( $tl ) || self::css_len_present( $tr ) ) {
				$residual[] = "#colophon .footer,#colophon.footer,.footer{border-top-left-radius:{$tl};border-top-right-radius:{$tr}}";
			}
		}
		// FOOTER container width — from the footer's INNER content wrapper computed max-width (same detection as
		// the header). The footer's native content-width control is the per-bar Custom Styling `container`
		// (Fixed Width / Full Width) — footer.md documents no per-bar NUMERIC width: a Fixed-Width footer bar
		// caps at the SITE-WIDE Container Width. So: full-bleed → container-fluid; a real capped width →
		// 'container' (Fixed Width, centered) on the Main Footer + Copyright bars, which then INHERIT the
		// site-wide Container Width set below (header/footer/body all share ONE width). We no longer emit a
		// footer-scoped numeric cap — the old `calc(px + 2*gutter)` rule rendered 2×gutter too wide vs source.
		if ( isset( $fchrome['container'] ) && $fchrome['container'] !== '' ) {
			$fluid = ( $fchrome['container'] === 'fluid' );
			$fcontainer = $fluid ? 'container-fluid' : 'container';
			foreach ( array( 'main_footer_custom_styling', 'copyright_custom_styling' ) as $ck ) {
				$prefix = ( $ck === 'main_footer_custom_styling' ) ? 'main_footer' : 'copyright';
				$curc = ( isset( $values[ $ck ]['yes'] ) && is_array( $values[ $ck ]['yes'] ) ) ? $values[ $ck ]['yes'] : array(); // (merge — the section padding set above rides along)
				$curc[ $prefix . '_container' ] = $fcontainer;
				$values[ $ck ] = array( 'enabled' => 'yes', 'yes' => $curc );
			}
		}

		// BOXED BODY — the footer's content rows sit in ONE inset panel (a hairline-bordered, tinted, padded shell
		// with a width cap). Native: Footer → Layout → Boxed Body (theme 2.5.97). The bars inside it go Full Width
		// (the panel's padding is their gutter). Decor strips inside the shell ride as the panel's pseudo-elements.
		$cs_foot = self::footer_root_el( (string) $html );
		$shell   = self::detect_footer_shell( $cs_foot );
		$copy_in_box = false;
		if ( $shell instanceof DOMElement ) {
			$fbv = self::footer_box_values( $shell );
			$fields = $fbv['fields'];
			// The bottom bar (© line or a label bar) lives INSIDE the panel when it is one of the shell's own rows.
			$shell_rows = self::el_children( $shell );
			foreach ( $shell_rows as $sr ) { if ( self::band_is_copyright( $sr, $sr === end( $shell_rows ) ) ) { $copy_in_box = true; break; } }
			if ( ! $copy_in_box ) { $ce = self::footer_copyright_el( $cs_foot ); if ( $ce instanceof DOMElement && self::is_ancestor( $shell, $ce ) ) { $copy_in_box = true; } }
			$fields['footer_box_copyright_inside'] = $copy_in_box ? 'yes' : 'no';
			$values['footer_body_box'] = array( 'enabled' => 'yes', 'yes' => $fields );
			foreach ( $fbv['css'] as $r ) { $residual[] = $r; }
			foreach ( array( 'pre_footer', 'main_footer', 'post_footer', 'copyright' ) as $bp ) {
				$ck  = $bp . '_custom_styling';
				$cur = ( isset( $values[ $ck ]['yes'] ) && is_array( $values[ $ck ]['yes'] ) ) ? $values[ $ck ]['yes'] : array();
				$cur[ $bp . '_container' ] = 'container-fluid';
				$values[ $ck ] = array( 'enabled' => 'yes', 'yes' => $cur );
			}
			// Inside a panel the theme's default 1rem bar padding is replaced by the rows' own measured box: the
			// main row's padding, and the bottom bar's margin-top (its gap above the divider) + padding.
			$main_row = null; $bestn = 1;
			foreach ( $shell_rows as $sr ) { $n = self::band_column_count( $sr ); $t = mb_strlen( trim( $sr->textContent ) ); if ( ! self::band_is_copyright( $sr, $sr === end( $shell_rows ) ) && ( null === $main_row || $t > $bestn ) ) { $main_row = $sr; $bestn = $t; } }
			if ( $main_row instanceof DOMElement ) {
				$pp = preg_split( '/\s+/', trim( (string) self::sc_css( $main_row, 'padding' ) ) );
				$pt = isset( $pp[0] ) ? $pp[0] : '0px'; $pb = isset( $pp[2] ) ? $pp[2] : $pt;
				$residual[] = '.footer--boxed .footer__body > .footer-section--main-footer{padding-top:' . ( preg_match( '/^[0-9.]+px$/', $pt ) ? $pt : '0' ) . ';padding-bottom:' . ( preg_match( '/^[0-9.]+px$/', $pb ) ? $pb : '0' ) . ';}';
			}
			if ( $copy_in_box ) {
				$last = end( $shell_rows );
				$mp = preg_split( '/\s+/', trim( (string) self::sc_css( $last, 'margin' ) ) ); $mt = isset( $mp[0] ) ? $mp[0] : '0px';
				$pp = preg_split( '/\s+/', trim( (string) self::sc_css( $last, 'padding' ) ) ); $pt = isset( $pp[0] ) ? $pp[0] : '0px'; $pb = isset( $pp[2] ) ? $pp[2] : $pt;
				$residual[] = '.footer--boxed .footer__body > .footer-section--copyright{margin-top:' . ( preg_match( '/^[0-9.]+px$/', $mt ) ? $mt : '0' ) . ';padding-top:' . ( preg_match( '/^[0-9.]+px$/', $pt ) ? $pt : '0' ) . ';padding-bottom:' . ( preg_match( '/^[0-9.]+px$/', $pb ) ? $pb : '0' ) . ';}';
