		// become three bars (a fixture from the feed)
		$f_root = self::footer_root_el( (string) $html );
		if ( $f_root instanceof DOMElement && self::footer_is_single_row( $f_root ) && ! empty( $values['main_footer_columns']['count'] ) ) {
			$mfc = $values['main_footer_columns']; $n0 = (int) $mfc['count']; $n1 = min( 6, $n0 + 1 );
			if ( $n1 > $n0 && isset( $mfc[ (string) $n0 ] ) && is_array( $mfc[ (string) $n0 ] ) ) {
				$cols0 = $mfc[ (string) $n0 ]; $cols0[ 'main_footer_col_' . $n1 ] = array( array( 'element_type' => array( 'element' => 'text', 'text' => array( 'text_content' => $copy ) ), 'element_css_class' => 'text-end' ) );
				$values['main_footer_columns'] = array( 'count' => (string) $n1, (string) $n1 => $cols0 );
				$values['copyright_settings'] = array( 'enabled' => 'no' );
			}
		}
		} // end: © line vs label bar
		unset( $values['_footer_brand_only'] );

		/* --- button_colors / button_sizes: presets derived from the source's real button skin --- */
		// ($btn_presets was built up front, beside header_main, so the header CTAs could resolve against it.)
		if ( ! empty( $btn_presets ) ) {
			$values = array_merge( $values, $btn_presets );
		}

		/* --- section_style_presets: reusable band skins clustered from the source's sections --- */
		$sec_presets = self::build_section_style_presets( (string) $html );
		if ( ! empty( $sec_presets ) ) {
			$values = array_merge( $values, $sec_presets );
		}

		/* --- container_width_presets: named content-band widths gathered from the source (Narrow/Medium/Wide
		   + any distinct widths the site uses), so converted sections reference SHARED named widths --- */
		$cw_presets = self::build_container_width_presets( (string) $html );
		if ( ! empty( $cw_presets ) ) {
			$values = array_merge( $values, $cw_presets );
		}

		/* --- border_presets (Box Presets): reusable card/box skins clustered from the source --- */
		$box_presets = self::build_box_presets( (string) $html );
		if ( ! empty( $box_presets ) ) {
			$values = array_merge( $values, $box_presets );
		}

		/* --- background_patterns (Background Patterns): captured SVG/gradient decorative tiles (PHP parity
		       of the JS backgroundPatterns()); the mapper injects the matching overlay onto its section --- */
		$bg_patterns = self::build_background_patterns( (string) $html );
		if ( ! empty( $bg_patterns ) ) {
			$values = array_merge( $values, $bg_patterns );
		}

		/* --- font_sizes (Text Styles): display scale + eyebrow derived from the source's headings --- */
		$text_styles = self::build_text_styles( (string) $html );
		if ( ! empty( $text_styles ) ) {
			$values = array_merge( $values, $text_styles );
		}

		/* --- image_styles (Image Styles): radius / circle / aspect / filter from the source's images --- */
		$img_styles = self::build_image_styles( (string) $html );
		if ( ! empty( $img_styles ) ) {
			$values = array_merge( $values, $img_styles );
		}

		/* --- theme_colors (Color Presets): the source's brand palette → editable Components colours --- */
		$color_presets = self::build_color_presets( $tokens, (string) $html );
		if ( ! empty( $color_presets ) ) {
			$values = array_merge( $values, $color_presets );
		}

		/* --- icon_badge_presets (Icon Badges): the source's icon-in-a-tile pattern → editable badge presets --- */
		$badge_presets = self::build_icon_badge_presets( (string) $html );
		if ( ! empty( $badge_presets ) ) {
			$values = array_merge( $values, $badge_presets );
		}

		/* --- table_presets (Tables): every table the mapper registered from its MEASURED skin → an editable
		   Table Preset (cell padding, grid lines, header / body faces, row hover, zebra, frame) --- */
		$tbl_presets = self::build_table_presets();
		if ( ! empty( $tbl_presets ) ) {
			$values = array_merge( $values, $tbl_presets );
		}

		/* --- spacing_scale (Components → Spacing): the source's spacing steps → editable scale (so the
		   converted site carries a real scale instead of falling back to the theme default). --- */
		$spacing = self::build_spacing_scale( $tokens, (string) $html );
		if ( ! empty( $spacing ) ) {
			$values['spacing_scale'] = $spacing;
		}

		/* --- gap_scale (Components → Spacing → Gaps): the source's column/grid gutters → editable gap scale.
		   Mirrors the extended default (0-12 + 32/40px) and appends any off-scale gutter the source uses, so a
		   `gap-16` (64px) lands on slug 7 and a `gap-[20px]` gets an exact `[20px]` entry — no snap-to-48px. --- */
		$gap_scale = self::build_gap_scale( $tokens, (string) $html );
		if ( ! empty( $gap_scale ) ) {
			$values['gap_scale'] = $gap_scale;
		}

		/* --- TYPOGRAPHY (General → Typography): map the SOURCE type system into native Theme-Settings so the
		   converted site carries real fonts + a heading scale (not just the child-theme --font-* tokens). The
		   families come from the same source-of-truth tokens_to_design_config() uses (tailwind fontFamily +
		   the Google-Fonts URL); the sizes/weights/line-heights/tracking come from the MEASURED computed styles
		   (data-sc-cs) of the source's real <p> and h1–h6. Only levels the source actually renders are set —
		   an undetected heading keeps the theme default. Shapes per theme-settings/typography.md: heading_font
		   = { family }, body/h1–h6 = { family, variation, size:{value,unit}, line-height, letter-spacing, color }. */
		list( $ty_head, $ty_body ) = self::pick_fonts_raw( $tokens );
		$ty_google = '';
		foreach ( ( $tokens['fonts'] ?? array() ) as $href ) { $ty_google = $href; break; }
		$ty_gf = self::fonts_from_google( $ty_google );
		$ty = self::detect_typography( (string) $html );
		// The MEASURED families come before the Google-URL ORDER guess: a page that loads "Outfit|JetBrains Mono" sets its
		// paragraphs in Outfit and its labels / code in the mono — the second font in the URL is not the body font. The
		// tailwind fontFamily tokens (pick_fonts_raw) still win when declared; the URL order is the last resort only.
		if ( $ty_head === '' ) { foreach ( array( 'h1', 'h2', 'h3' ) as $lvl ) { if ( ! empty( $ty[ $lvl ]['family'] ) ) { $ty_head = $ty[ $lvl ]['family']; break; } } }
		if ( $ty_body === '' && ! empty( $ty['body']['family'] ) ) { $ty_body = $ty['body']['family']; }
		if ( $ty_head === '' && isset( $ty_gf[0] ) ) { $ty_head = $ty_gf[0]; }
		// a measured SYSTEM body stack keeps the theme's sans default — the heading's single Google face is never the body's
		if ( $ty_body === '' && empty( $ty['body']['system'] ) ) { $ty_body = isset( $ty_gf[1] ) ? $ty_gf[1] : ( isset( $ty_gf[0] ) ? $ty_gf[0] : '' ); }
		elseif ( $ty_body === '' && isset( $ty_gf[1] ) ) { $ty_body = $ty_gf[1]; }
		// Fallback to the MEASURED families when the token/Google-URL path yielded none (a captured DOM carries
		// the resolved font-family on data-sc-cs even when no tailwind.config / Google <link> was extracted).
		if ( $ty_head === '' ) {
			foreach ( array( 'h1', 'h2', 'h3' ) as $lvl ) { if ( ! empty( $ty[ $lvl ]['family'] ) ) { $ty_head = $ty[ $lvl ]['family']; break; } }
		}
		if ( $ty_body === '' && ! empty( $ty['body']['family'] ) ) { $ty_body = $ty['body']['family']; }
		/* The Typography options live INSIDE the `typography` multi container (General → Typography). css-tokens
		   reads fw_get_db_settings_option('typography') and looks up ['heading_font'] / ['body'] / ['h1'..] on
		   THAT array — so the values MUST be nested under $values['typography'][...], not stored flat at the
		   settings root (a flat store reads back via fw_get_db_settings_option('heading_font') but is invisible
		   to unysonplus_typography_config, so --font-heading / the h1–h6 scale would never emit). */
		$typo = array();
		// Heading Font — family only (empty inherits body). Loads via css-tokens `google` list.
		if ( $ty_head !== '' ) { $typo['heading_font'] = array( 'family' => $ty_head ); }
		// Body Font & Text — family + measured base size/line-height/letter-spacing.
		if ( $ty_body !== '' || ! empty( $ty['body'] ) ) {
			$body_val = array( 'family' => $ty_body, 'variation' => 'regular', 'color' => '' );
			if ( isset( $ty['body']['size'] ) )          { $body_val['size'] = array( 'value' => (string) $ty['body']['size'], 'unit' => 'px' ); }
			if ( isset( $ty['body']['line-height'] ) )    { $body_val['line-height'] = $ty['body']['line-height']; }
			if ( isset( $ty['body']['letter-spacing'] ) ) { $body_val['letter-spacing'] = $ty['body']['letter-spacing']; }
			$typo['body'] = $body_val;
		}
		// Per-heading scale H1–H6 — only levels the source actually uses. `variation` carries the weight
		// (the typography option stores weight/style in variation); family left '' to inherit the Heading Font
		// unless the source heading uses a DIFFERENT family than the heading font.
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $lvl ) {
			if ( empty( $ty[ $lvl ] ) ) { continue; }
			$h = $ty[ $lvl ];
			$hv = array( 'family' => '', 'variation' => ( isset( $h['weight'] ) && $h['weight'] !== '' && (int) $h['weight'] !== 400 ? (string) $h['weight'] : 'regular' ), 'color' => '' );
			if ( isset( $h['family'] ) && $h['family'] !== '' && strcasecmp( $h['family'], $ty_head ) !== 0 ) { $hv['family'] = $h['family']; }
			if ( isset( $h['size'] ) )            { $hv['size'] = array( 'value' => (string) $h['size'], 'unit' => 'px' ); }
			if ( isset( $h['line-height'] ) )     { $hv['line-height'] = $h['line-height']; }
			if ( isset( $h['letter-spacing'] ) )  { $hv['letter-spacing'] = $h['letter-spacing']; }
			if ( isset( $h['text-transform'] ) )  { $hv['text-transform'] = $h['text-transform']; }
			$typo[ $lvl ] = $hv;
		}
		// BODY TEXT (ink) → Typography body colour (→ --color-text via theme-vars.php, read unconditionally
		// even in preset mode). Without it, everything that inherits --color-text (card titles, card copy,
		// overlines/meta, testimonial author, any heading with no explicit colour) keeps the theme default
		// #212529 (near-black) — INVISIBLE on a dark canvas. Detected from `body{color}` or, failing that,
		// the page's dominant text colour. A light source resolves to a dark ink = the current default.
		if ( $body_ink !== '' ) {
			if ( ! isset( $typo['body'] ) || ! is_array( $typo['body'] ) ) { $typo['body'] = array( 'family' => '', 'variation' => 'regular' ); }
			$typo['body']['color'] = $body_ink;
		}
		// A measured source authors FIXED sizes: the theme's fluid growth (body ×1.15 on wide screens, headings shrinking on phones)
		// would resize what the capture measured — off for a conversion (Typography → Fluid Sizes).
		if ( ! empty( $typo ) ) { $typo['type_fluid_enable'] = 'no'; }
		if ( ! empty( $typo ) ) { $values['typography'] = $typo; }

		// CUSTOM CURSOR — the source replaces the native pointer with a JS-followed element → the Animation
		// Engine's Site-wide UX → Cursor (`animation_cursor`). Map the shape (ring/dot/dot_ring) + colour; the
		// importer auto-activates animation-engine (see the needs_extensions detection in build_bundle).
		$cursor = self::detect_custom_cursor( (string) $html );
		if ( is_array( $cursor ) && ! empty( $cursor['shape'] ) ) {
			$ac = array(
				'enable' => 'yes',
				'style'  => array( 'shape' => (string) $cursor['shape'] ),
			);
			if ( ! empty( $cursor['color'] ) ) { $ac['color'] = array( 'predefined' => '', 'custom' => (string) $cursor['color'] ); }
			$values['animation_cursor'] = $ac;
		}

		// PRELOADER — a full-screen loading overlay in the source → the Animation Engine's Preloader module,
		// "Custom (code)" style, filled with the extracted HTML/CSS (+ self-contained JS when present). The
		// importer auto-activates animation-engine (needs_extensions detection in build_bundle).
		$pre = self::detect_preloader( (string) $html );
		if ( is_array( $pre ) && '' !== trim( (string) ( $pre['html'] ?? '' ) ) ) {
			$pre_js = (string) ( $pre['js'] ?? '' );
			// AI tier: when the source loader's JS was intertwined with the app (couldn't be extracted), ask the
			// capture service to synthesize a cosmetic loader script from the HTML+CSS. Gated by the "Refine with
			// AI" opt-in + service URL; best-effort (stays JS-less on any failure).
			if ( '' === trim( $pre_js ) && class_exists( 'FW_Site_Converter_Mapper' )
				&& FW_Site_Converter_Mapper::$entrance_anim_ai && '' !== FW_Site_Converter_Mapper::$entrance_anim_svc ) {
				$ai_js = FW_Site_Converter_Mapper::ai_preloader_js( (string) $pre['html'], (string) ( $pre['css'] ?? '' ) );
				if ( '' !== $ai_js ) { $pre_js = $ai_js; }
			}
			$values['animation_preloader'] = array( 'enable' => 'yes' );
			$values['preloader_style']     = array(
				'style'  => 'custom',
				'custom' => array(
					'html' => (string) $pre['html'],
					'css'  => (string) ( $pre['css'] ?? '' ),
					'js'   => $pre_js,
				),
			);
		}

		// SCROLL-PROGRESS RAIL — a fixed edge rail (kage's `.rail`) tracking reading progress → the Animation
		// Engine's Scroll Progress module, "Custom (code)" style, carrying the extracted HTML/CSS (+ self-
		// contained JS). The module driver exposes --sp-progress / window.upwScrollProgress so the carried rail
		// animates on scroll. Same auto-activation of animation-engine as the preloader (needs_extensions).
		$rail = self::detect_scroll_rail( (string) $html );
		if ( is_array( $rail ) && '' !== trim( (string) ( $rail['html'] ?? '' ) ) ) {
			$values['animation_scrollprog'] = array( 'enable' => 'yes' );
			$values['scrollprog']           = array(
				'kind'   => 'custom',
				'custom' => array(
					'html' => (string) $rail['html'],
					'css'  => (string) ( $rail['css'] ?? '' ),
					'js'   => (string) ( $rail['js'] ?? '' ),
				),
			);
		}

		return array( 'values' => $values );
	}

	/**
	 * Read the SOURCE type system from captured computed styles (data-sc-cs): the base body run (the densest
	 * <p>) and each heading level h1–h6 actually present. Returns { body: {size,line-height,letter-spacing,
	 * family}, h1..h6: {size,weight,line-height,letter-spacing,family} } with ONLY the keys measured — an
	 * unmeasured level/prop is absent so the caller leaves the theme default. Sizes = px int; line-height =
	 * unitless ratio (computed px ÷ font-size, rounded); letter-spacing = px number ('normal' → 0, dropped);
	 * family = the first family name in the computed stack (deals with `'Nunito', sans-serif`).
	 */
	private static function detect_typography( $html ) {
		$out = array();
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return $out; }
		$first_family = function ( $stack ) {
			$stack = trim( (string) $stack );
			if ( $stack === '' ) { return ''; }
			$one = trim( (string) preg_split( '/\s*,\s*/', $stack )[0] );
			$one = trim( $one, "\"' " );
			// Drop generic keywords — they carry no web font.
			if ( $one === '' || in_array( strtolower( $one ), array( 'inherit', 'initial', 'sans-serif', 'serif', 'monospace', 'system-ui', '-apple-system', 'ui-sans-serif', 'ui-serif' ), true ) ) { return ''; }
			return $one;
		};
		$lh_ratio = function ( $lh, $size ) {
			$lh = trim( (string) $lh ); $size = (float) $size;
			if ( $lh === '' || strtolower( $lh ) === 'normal' || $size <= 0 ) { return ''; }
			if ( preg_match( '/^([0-9.]+)px$/', $lh, $m ) ) { return (string) round( ( (float) $m[1] ) / $size, 2 ); }
			if ( preg_match( '/^([0-9.]+)$/', $lh, $m ) ) { return (string) round( (float) $m[1], 2 ); } // already unitless
			return '';
		};
		$ls_px = function ( $ls ) {
			$ls = trim( (string) $ls );
			if ( $ls === '' || strtolower( $ls ) === 'normal' ) { return ''; }
			if ( preg_match( '/^(-?[0-9.]+)px$/', $ls, $m ) ) { $v = round( (float) $m[1], 2 ); return abs( $v ) < 0.01 ? '' : (string) $v; }
			return '';
		};

		// BODY — the DOMINANT paragraph font-size: the size carrying the MOST total body text, not a
		// single "densest paragraph" (one long 18/20px lead-in used to mis-set the whole base — the golden fixture
		// is 16px base with a few 18–20px leads, so the base was wrongly detected as 20px). Accumulate
		// text length per rounded-px size; read family/line-height/letter-spacing from the longest
		// paragraph AT that dominant size.
		$len_by_size = array(); $rep_by_size = array(); $replen_by_size = array();
		foreach ( $dom->getElementsByTagName( 'p' ) as $p ) {
			$cs = ( $p instanceof DOMElement ) ? (string) $p->getAttribute( 'data-sc-cs' ) : '';
			if ( $cs === '' ) { continue; }
			$sz = self::sc_css( $p, 'font-size' );
			if ( ! preg_match( '/^([0-9.]+)px$/', trim( (string) $sz ), $m ) ) { continue; }
			$px  = (int) round( (float) $m[1] );
			if ( $px > 28 ) { continue; } // a DISPLAY-size <p> (a 48px serif hero line) is never body copy — it set the whole site's body to Instrument Serif 48px (a finding from the feed)
			$len = strlen( trim( self::text( $p ) ) );
			if ( $len <= 0 ) { continue; }
			$len_by_size[ $px ] = ( isset( $len_by_size[ $px ] ) ? $len_by_size[ $px ] : 0 ) + $len;
			if ( $len > ( isset( $replen_by_size[ $px ] ) ? $replen_by_size[ $px ] : 0 ) ) { $replen_by_size[ $px ] = $len; $rep_by_size[ $px ] = $p; }
		}
		if ( $len_by_size ) {
			arsort( $len_by_size ); // most total body text first
			$px = (int) array_key_first( $len_by_size );
			// The ROOT size wins over the paragraph mode: the Body size sets the rem root the theme measures everything against, so a
			// page whose copy is mostly `text-lg` (18px) over a 16px root had every rem / em measure inflated by 12.5 % (a finding
			// filed on eleven conversions). The <body> stamp's font-size is the root the source authored; the paragraphs' mode is
			// only the fallback when the body carries no stamp.
			$body_el = $dom->getElementsByTagName( 'body' )->item( 0 );
			if ( $body_el instanceof DOMElement && preg_match( '/^([0-9.]+)px$/', trim( (string) self::sc_css( $body_el, 'font-size' ) ), $bm ) && (float) $bm[1] >= 12 && (float) $bm[1] <= 22 ) { $px = (int) round( (float) $bm[1] ); }
			$rp = isset( $rep_by_size[ $px ] ) ? $rep_by_size[ $px ] : $rep_by_size[ (int) array_key_first( $len_by_size ) ];
			$body = array( 'size' => $px );
			// the FAMILY / line-height come from the <body> stamp when it carries a named face (the root the source authored — every
			// paragraph inherits it); the representative paragraph is the fallback for a body with no stamp
			$fam = ( $body_el instanceof DOMElement ) ? $first_family( self::sc_css( $body_el, 'font-family' ) ) : '';
			if ( '' === $fam ) { $fam = $first_family( self::sc_css( $rp, 'font-family' ) ); }
			elseif ( $body_el instanceof DOMElement && '' !== $lh_ratio( self::sc_css( $body_el, 'line-height' ), $px ) ) { $rp = $body_el; }
			if ( $fam !== '' ) { $body['family'] = $fam; }
			// a SYSTEM stack (`ui-sans-serif, system-ui, …`) resolves to no named face: remember it, so the caller never fills the
			// body slot with the heading's Google face (a serif display face on every paragraph — a fixture from the feed)
			elseif ( preg_match( '/^\s*(?:ui-sans-serif|system-ui|-apple-system|blinkmacsystemfont|sans-serif|ui-serif|serif|ui-monospace|monospace)/i', (string) self::sc_css( $rp, 'font-family' ) ) ) { $body['system'] = true; }
			$lh = $lh_ratio( self::sc_css( $rp, 'line-height' ), $px );
			if ( $lh !== '' ) { $body['line-height'] = $lh; }
			// Letter-spacing only when it is the page's PROSE norm — the mode across every paragraph weighted by text length, and
			// covering at least 60 % of the copy; one `tracking-wide` hero paragraph used to track every paragraph and link on the site.
			$ls_len = array(); $ls_total = 0;
			foreach ( $dom->getElementsByTagName( 'p' ) as $p2 ) { if ( ! ( $p2 instanceof DOMElement ) || '' === (string) $p2->getAttribute( 'data-sc-cs' ) ) { continue; } $l2 = strlen( trim( self::text( $p2 ) ) ); if ( $l2 <= 0 ) { continue; } $k = (string) $ls_px( self::sc_css( $p2, 'letter-spacing' ) ); $ls_len[ $k ] = ( $ls_len[ $k ] ?? 0 ) + $l2; $ls_total += $l2; }
			if ( $ls_len && $ls_total > 0 ) { arsort( $ls_len ); $lsk = (string) array_key_first( $ls_len ); if ( '' !== $lsk && '0' !== $lsk && $ls_len[ $lsk ] >= $ls_total * 0.6 ) { $body['letter-spacing'] = (float) $lsk; } }
			$out['body'] = $body;
		}

		// HEADINGS h1–h6 — the FIRST occurrence of each level with a computed style + text.
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $lvl ) {
			foreach ( $dom->getElementsByTagName( $lvl ) as $h ) {
				$cs = ( $h instanceof DOMElement ) ? (string) $h->getAttribute( 'data-sc-cs' ) : '';
				if ( $cs === '' || trim( self::text( $h ) ) === '' ) { continue; }
				$rec = array();
				$sz  = self::sc_css( $h, 'font-size' );
				if ( preg_match( '/^([0-9.]+)px$/', trim( (string) $sz ), $m ) ) { $rec['size'] = (int) round( (float) $m[1] ); }
				$w = trim( (string) self::sc_css( $h, 'font-weight' ) );
				if ( preg_match( '/^[1-9]00$/', $w ) ) { $rec['weight'] = $w; }
				elseif ( strtolower( $w ) === 'bold' ) { $rec['weight'] = '700'; }
				elseif ( strtolower( $w ) === 'normal' ) { $rec['weight'] = '400'; }
				$fam = $first_family( self::sc_css( $h, 'font-family' ) );
				if ( $fam !== '' ) { $rec['family'] = $fam; }
				$lh = $lh_ratio( self::sc_css( $h, 'line-height' ), isset( $rec['size'] ) ? $rec['size'] : 0 );
				if ( $lh !== '' ) { $rec['line-height'] = $lh; }
				$ls = $ls_px( self::sc_css( $h, 'letter-spacing' ) );
				if ( $ls !== '' ) { $rec['letter-spacing'] = $ls; }
				// text-transform — a source whose headings are uppercased purely by CSS (no `uppercase` class,
				// e.g. a display font like Syncopate) otherwise renders mixed-case after conversion. Carry the
				// computed casing per level so `Our Services` reproduces the source's `OUR SERVICES`.
				$htt = strtolower( trim( (string) self::sc_css( $h, 'text-transform' ) ) );
				if ( in_array( $htt, array( 'uppercase', 'lowercase', 'capitalize' ), true ) ) { $rec['text-transform'] = $htt; }
				if ( $rec ) { $out[ $lvl ] = $rec; }
				break; // first real occurrence of this level is representative
			}
		}
		return $out;
	}

	/**
	 * Is a deterministic chrome mapping FAITHFUL enough to drive the native (Theme-Settings) chrome path,
	 * versus falling back to the raw-chrome bake? The header is generally safe (always has a wordmark +
	 * menu-area + layout), so the gate is on the FOOTER — the part that used to collapse: require a detected
	 * multi-column grid (≥2 columns, i.e. brand + at least one content column) OR a copyright bar. When the
	 * footer structure wasn't confidently detected (a messy source), $dyn bakes the source footer verbatim
	 * instead so nothing renders broken.
	 *
	 * @param array $chrome tokens_to_theme_settings_chrome() result
	 * @return bool
	 */
	public static function chrome_mapping_faithful( $chrome ) {
		if ( empty( $chrome['values'] ) || ! is_array( $chrome['values'] ) ) { return false; }
		$v = $chrome['values'];
		// Header sanity: a logo wordmark/image and a header_main with element zones.
		$has_header = ! empty( $v['header_logo'] ) && ! empty( $v['header_main'] );
		// Footer sanity: a real multi-column grid, or at least a copyright bar.
		$has_grid = false; $ncols = 0;
		if ( ! empty( $v['main_footer_columns']['count'] ) ) {
			$cnt = $v['main_footer_columns']['count'];
			$blk = isset( $v['main_footer_columns'][ $cnt ] ) ? $v['main_footer_columns'][ $cnt ] : array();
			$ncols = 0;
			foreach ( (array) $blk as $k => $col ) { if ( strpos( (string) $k, 'main_footer_col_' ) === 0 && ! empty( $col ) ) { $ncols++; } }
			$has_grid = $ncols >= 2;
		}
		$has_copyright = ! empty( $v['copyright_settings']['enabled'] ) && $v['copyright_settings']['enabled'] === 'yes';
		// A brand-only footer (one column, © bar deliberately OFF because the source shows no © line) is a faithful mapping too.
		$brand_only = ( $ncols >= 1 ) && isset( $v['copyright_settings']['enabled'] ) && 'no' === $v['copyright_settings']['enabled'];
		return $has_header && ( $has_grid || $has_copyright || $brand_only );
	}

	/**
	 * AI-REFINEMENT applier: merge an AI header/footer mapping (from the capture service's /translate-chrome
	 * → translateHeader / translateFooter) OVER the deterministic native chrome, correcting the ambiguous
	 * judgment calls the heuristics can get wrong (which band = which bar, CTA label/style, transparent-overlay
	 * behavior, column ratios). The AI JSON follows the header/footer translation guides; this converts each
	 * guide shape into the REAL Theme-Settings shapes (matching tokens_to_theme_settings_chrome) and overlays
	 * only the keys it can confidently set — so a partial/weak AI result never regresses the deterministic base.
	 *
	 * @param array  $chrome tokens_to_theme_settings_chrome() result (the deterministic base) — { values: … }
	 * @param array  $ai_header header guide JSON: { left, center, right, layout, identity, menu } (or null)
	 * @param array  $ai_footer footer guide JSON: { background, text_color, link_color, bars:{…} } (or null)
	 * @param string $title site name (fallbacks)
	 * @return array{ values: array, refined_header: bool, refined_footer: bool }
	 */
	public static function apply_ai_chrome( $chrome, $ai_header, $ai_footer, $title = '' ) {
		$values = ( isset( $chrome['values'] ) && is_array( $chrome['values'] ) ) ? $chrome['values'] : array();
		$hex = function ( $h ) { $h = trim( (string) $h ); return array( 'predefined' => '', 'custom' => self::clean_color_value( $h ) ); };
		$el  = function ( $type, $settings = null ) {
			$et = array( 'element' => $type );
			if ( is_array( $settings ) ) { $et[ $type ] = $settings; }
			return array( 'element_type' => $et );
		};
		$refined_header = false;
		$refined_footer = false;

		/* ---------- HEADER ---------- */
		if ( is_array( $ai_header ) ) {
			$zones = array( 'left' => 'main_left', 'center' => 'main_center', 'right' => 'main_right' );
			$hm    = isset( $values['header_main'] ) && is_array( $values['header_main'] ) ? $values['header_main'] : array();
			$built_any = false;
			foreach ( $zones as $zk => $mk ) {
				if ( ! isset( $ai_header[ $zk ] ) || ! is_array( $ai_header[ $zk ] ) ) { continue; }
				$out_zone = array();
				foreach ( $ai_header[ $zk ] as $item ) {
					if ( ! is_array( $item ) || empty( $item['type'] ) ) { continue; }
					switch ( $item['type'] ) {
						case 'logo':
							$out_zone[] = $el( 'logo' );
							break;
						case 'menu_area':
							$out_zone[] = $el( 'menu_area', array( 'menu_location' => 'primary' ) );
							break;
						case 'cta_button':
							$style = isset( $item['style'] ) ? (string) $item['style'] : 'filled';
							$map   = array( 'filled' => 'btn-primary', 'outline' => 'btn-secondary', 'pill' => 'btn-primary' );
							$out_zone[] = $el( 'cta_button', array(
								'cta_text'  => isset( $item['text'] ) ? (string) $item['text'] : 'Get Started',
								'cta_link'  => ( isset( $item['link'] ) && $item['link'] !== '' ) ? (string) $item['link'] : '#',
								'cta_style' => isset( $map[ $style ] ) ? $map[ $style ] : 'btn-primary',
								'cta_size'  => 'btn-md',
							) );
							break;
						case 'icon_text':
						case 'list_item':
							$it_lnk  = isset( $item['link'] ) ? (string) $item['link'] : '';
							$it_type = ( $it_lnk === '' ) ? 'none' : ( strpos( $it_lnk, 'tel:' ) === 0 ? 'phone' : ( strpos( $it_lnk, 'mailto:' ) === 0 ? 'email' : 'url' ) );
							$it_set  = array(
								'li_text'      => isset( $item['text'] ) ? (string) $item['text'] : '',
								'li_link'      => $it_lnk,
								'li_link_type' => $it_type,
							);
							$it_ico = self::contact_icon_v2( self::contact_icon_name_svg( isset( $item['icon'] ) ? $item['icon'] : '' ), '' );
							if ( $it_ico ) { $it_set['li_icon'] = $it_ico; }
							$out_zone[] = $el( 'list_item', $it_set );
							break;
						case 'social_icons':
							$out_zone[] = $el( 'social_icons' );
							break;
						case 'search':
							$out_zone[] = $el( 'search' );
							break;
					}
				}
				if ( $out_zone ) { $hm[ $mk ] = $out_zone; $built_any = true; }
			}
			// Only overwrite header_main if the AI produced a logo + a menu somewhere (else keep deterministic).
			$flat = wp_json_encode( $hm );
			if ( $built_any && strpos( (string) $flat, '"logo"' ) !== false && strpos( (string) $flat, 'menu_area' ) !== false ) {
				$values['header_main'] = $hm;
				$refined_header = true;
			}

			// identity → header_logo (nested multi-picker) custom branch. Only refine colors/title/layout —
			// do NOT clobber a good deterministic inline-SVG icon + frame the AI can't reproduce from text.
			if ( ! empty( $ai_header['identity'] ) && is_array( $ai_header['identity'] ) ) {
				$id = $ai_header['identity'];
				$hl = isset( $values['header_logo'] ) && is_array( $values['header_logo'] ) ? $values['header_logo'] : array();
				if ( ! isset( $hl['logo_type'] ) || ! is_array( $hl['logo_type'] ) ) { $hl['logo_type'] = array( 'logo_type' => 'custom', 'custom' => array(), 'simple' => array() ); }
				$cu = isset( $hl['logo_type']['custom'] ) && is_array( $hl['logo_type']['custom'] ) ? $hl['logo_type']['custom'] : array();
				if ( ! empty( $id['site_title'] ) )  { $cu['site_title'] = (string) $id['site_title']; }
				if ( ! empty( $id['title_color'] ) ) { $cu['color'] = $hex( $id['title_color'] ); }
				if ( ! empty( $id['layout'] ) )      { $cu['logo_layout'] = (string) $id['layout']; }
				if ( ! empty( $id['icon_color'] ) && empty( $cu['logo_icon_frame_bg'] ) ) { $cu['logo_icon_color'] = $hex( $id['icon_color'] ); }
				$hl['logo_type']['custom'] = $cu;
				$values['header_logo'] = $hl;
				$refined_header = true;
			}

			// menu → header_menu colors + item style + uppercase.
			if ( ! empty( $ai_header['menu'] ) && is_array( $ai_header['menu'] ) ) {
				$mn = $ai_header['menu'];
				$hmenu = isset( $values['header_menu'] ) && is_array( $values['header_menu'] ) ? $values['header_menu'] : array();
				if ( ! empty( $mn['link_color'] ) )       { $hmenu['menu_link_color'] = $hex( $mn['link_color'] ); }
				if ( ! empty( $mn['link_hover_color'] ) ) { $hmenu['menu_link_hover_color'] = $hex( $mn['link_hover_color'] ); }
				if ( ! empty( $mn['item_style'] ) )       { $hmenu['menu_item_style'] = ( $mn['item_style'] === 'underline' ) ? 'underline-grow' : (string) $mn['item_style']; }
				$values['header_menu'] = $hmenu;
				if ( isset( $mn['uppercase'] ) && ! empty( $values['header_layout'] ) && is_array( $values['header_layout'] ) ) {
					$values['header_layout']['header_uppercase_nav'] = $mn['uppercase'] ? 'yes' : 'no';
				}
				$refined_header = true;
			}

			// layout → behavior / design / container / bg.
			if ( ! empty( $ai_header['layout'] ) && is_array( $ai_header['layout'] ) ) {
				$ly = $ai_header['layout'];
				$hlay = isset( $values['header_layout'] ) && is_array( $values['header_layout'] ) ? $values['header_layout'] : array();
				$beh_map = array( 'static' => 'static', 'sticky' => 'sticky', 'sticky-shrink' => 'sticky-shrink', 'hide-on-scroll' => 'hide-on-scroll', 'transparent-overlay' => 'transparent-overlay' );
				if ( ! empty( $ly['behavior'] ) && isset( $beh_map[ $ly['behavior'] ] ) ) { $hlay['header_behavior'] = $beh_map[ $ly['behavior'] ]; }
				if ( ! empty( $ly['design'] ) && in_array( $ly['design'], array( 'classic', 'pill', 'card', 'centered' ), true ) ) {
					$hlay['header_mode'] = array( 'mode' => 'top', 'top' => array( 'header_design' => array( 'design' => (string) $ly['design'] ) ) );
				}
				if ( ! empty( $ly['container'] ) && in_array( $ly['container'], array( 'container', 'container-fluid' ), true ) ) { $hlay['container'] = (string) $ly['container']; }
				if ( isset( $ly['bg_color'] ) && $ly['bg_color'] !== '' ) { $hlay['bg_color'] = $hex( $ly['bg_color'] ); }
				$values['header_layout'] = $hlay;
				$refined_header = true;
			}
		}

		/* ---------- FOOTER ---------- */
		if ( is_array( $ai_footer ) ) {
			if ( ! empty( $ai_footer['background'] ) ) { $values['footer_background'] = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => (string) $ai_footer['background'] ) ) ); }
			if ( ! empty( $ai_footer['text_color'] ) ) { $values['footer_text_color'] = $hex( $ai_footer['text_color'] ); }
			if ( ! empty( $ai_footer['link_color'] ) ) { $values['footer_link_color'] = $hex( $ai_footer['link_color'] ); }

			$bars = isset( $ai_footer['bars'] ) && is_array( $ai_footer['bars'] ) ? $ai_footer['bars'] : array();

			// Build a set of footer-column elements from a guide "column".
			$build_col = function ( $col ) use ( $el ) {
				$out = array();
				$elements = ( is_array( $col ) && isset( $col['elements'] ) && is_array( $col['elements'] ) ) ? $col['elements'] : array();
				foreach ( $elements as $e ) {
					if ( ! is_array( $e ) || empty( $e['type'] ) ) { continue; }
					switch ( $e['type'] ) {
						case 'logo':
							$out[] = $el( 'footer_logo' );
							break;
						case 'social_icons':
							$out[] = $el( 'social_icons' );
							break;
						case 'text':
							$out[] = array( 'element_type' => array( 'element' => 'text', 'text' => array( 'text_content' => '<p>' . esc_html( isset( $e['content'] ) ? (string) $e['content'] : '' ) . '</p>' ) ) );
							break;
						case 'heading':
							// Atomic `heading` element (F1, footer.md) — not a Text `<h4>`. Mirrors footer_group_to_column.
							$htxt = isset( $e['text'] ) ? trim( (string) $e['text'] ) : '';
							if ( $htxt !== '' ) {
								$hlvl  = ( isset( $e['level'] ) && (int) $e['level'] >= 2 && (int) $e['level'] <= 6 ) ? 'h' . (int) $e['level'] : 'h3';
								$out[] = $el( 'heading', array( 'heading_text' => $htxt, 'heading_level' => $hlvl ) );
							}
							break;
						case 'menu':
							// A captured link list → an optional Heading (title) + one atomic `link` element per row
							// (F1, footer.md). Inline hrefs can't vanish from a missing WP menu object, so footer link
							// columns never map to a registered `menu` element. Mirrors footer_group_to_column.
							$mtitle = isset( $e['title'] ) ? trim( (string) $e['title'] ) : '';
							if ( $mtitle !== '' ) { $out[] = $el( 'heading', array( 'heading_text' => $mtitle, 'heading_level' => 'h3' ) ); }
							$links = ( isset( $e['links'] ) && is_array( $e['links'] ) ) ? $e['links'] : array();
							foreach ( $links as $l ) {
								if ( ! is_array( $l ) ) { continue; }
								$llabel = isset( $l['text'] ) ? trim( (string) $l['text'] ) : '';
								if ( $llabel === '' ) { continue; }
								$out[] = $el( 'link', array(
									'link_label'  => $llabel,
									'link_url'    => ( ! empty( $l['href'] ) ? (string) $l['href'] : '#' ),
									'link_target' => '_self',
								) );
							}
							break;
						case 'icon_text':
						case 'list_item':
							$e_lnk  = isset( $e['link'] ) ? (string) $e['link'] : '';
							$e_type = ( $e_lnk === '' ) ? 'none' : ( strpos( $e_lnk, 'tel:' ) === 0 ? 'phone' : ( strpos( $e_lnk, 'mailto:' ) === 0 ? 'email' : 'url' ) );
							$e_set  = array(
								'li_text'      => isset( $e['text'] ) ? (string) $e['text'] : '',
								'li_link'      => $e_lnk,
								'li_link_type' => $e_type,
							);
							$e_ico = self::contact_icon_v2( self::contact_icon_name_svg( isset( $e['icon'] ) ? $e['icon'] : '' ), '' );
							if ( $e_ico ) { $e_set['li_icon'] = $e_ico; }
							$out[] = $el( 'list_item', $e_set );
							break;
					}
				}
				return $out;
			};

			// main bar → main_footer_columns (its columns become the grid). REFINEMENT rule: only replace the
			// deterministic grid when the AI found AT LEAST as many columns — a truncated/partial AI footer
			// (common when the footer markup is large and gets trimmed) must never REGRESS a faithful 4-col
			// deterministic grid down to 2. The deterministic base already captured the full grid structure.
			if ( ! empty( $bars['main']['columns'] ) && is_array( $bars['main']['columns'] ) ) {
				$cols = array();
				foreach ( $bars['main']['columns'] as $col ) { $built = $build_col( $col ); if ( $built ) { $cols[] = $built; } }
				$cols = array_slice( $cols, 0, 8 );
				$n = count( $cols );
				// Count the deterministic base's columns to compare.
				$base_n = 0;
				if ( ! empty( $values['main_footer_columns']['count'] ) ) {
					$bk = $values['main_footer_columns']['count'];
					foreach ( (array) ( $values['main_footer_columns'][ $bk ] ?? array() ) as $kk => $cc ) { if ( strpos( (string) $kk, 'main_footer_col_' ) === 0 && ! empty( $cc ) ) { $base_n++; } }
				}
				if ( $n >= 1 && $n >= $base_n ) {
					$mfc = array();
					for ( $i = 0; $i < $n; $i++ ) { $mfc[ 'main_footer_col_' . ( $i + 1 ) ] = $cols[ $i ]; }
					// A wider brand column (auto-width space-between) → fifths brand-spans-2 when 4 cols.
					if ( 4 === $n ) { $mfc['main_footer_layout'] = 'f5-2-1-1-1'; $ck = '5'; }
					else { $ck = (string) $n; }
					if ( ! empty( $bars['main']['auto_width'] ) ) { $mfc[ 'main_footer_auto' ] = 'yes'; $mfc['main_footer_justify'] = ! empty( $bars['main']['justify'] ) ? (string) $bars['main']['justify'] : 'between'; }
					$values['main_footer_columns'] = array( 'count' => $ck, $ck => $mfc );
					$refined_footer = true;
				}
			}

			// copyright bar → copyright_settings. Same refinement rule: don't regress a 2-col deterministic
			// copyright (© + legal menu) to a 1-col AI copyright.
			if ( ! empty( $bars['copyright']['columns'] ) && is_array( $bars['copyright']['columns'] ) ) {
				$ccols = array();
				foreach ( $bars['copyright']['columns'] as $col ) { $built = $build_col( $col ); if ( $built ) { $ccols[] = $built; } }
				$ccols = array_slice( $ccols, 0, 3 );
				$n = count( $ccols );
				$base_cn = 0;
				if ( ! empty( $values['copyright_settings']['yes']['copyright_columns']['count'] ) ) {
					$bck = $values['copyright_settings']['yes']['copyright_columns']['count'];
					foreach ( (array) ( $values['copyright_settings']['yes']['copyright_columns'][ $bck ] ?? array() ) as $kk => $cc ) { if ( strpos( (string) $kk, 'copyright_col_' ) === 0 && ! empty( $cc ) ) { $base_cn++; } }
				}
				if ( $n >= 1 && $n >= $base_cn ) {
					$cc = array();
					for ( $i = 0; $i < $n; $i++ ) { $cc[ 'copyright_col_' . ( $i + 1 ) ] = $ccols[ $i ]; }
					$values['copyright_settings'] = array( 'enabled' => 'yes', 'yes' => array( 'copyright_columns' => array( 'count' => (string) $n, (string) $n => $cc ) ) );
					$refined_footer = true;
				}
			}
		}

		return array( 'values' => $values, 'refined_header' => $refined_header, 'refined_footer' => $refined_footer );
	}

	/**
	 * Detect the brand LOGO: its wordmark text and (if an inline icon precedes the text) a Lucide
	 * icon id to reproduce as the native Logo Icon. Returns { text, icon, image }.
	 *   - text  = the wordmark string (empty for a pure image logo)
	 *   - icon  = a 'lucide/<name>' id when an <svg>/icon element sits before the text, else ''
	 *   - image = the logo <img> src for an image logo, else ''
	 * Heuristic + conservative: only emits an icon id we can confidently map (data-lucide / a
	 * lucide-* class / an iconify lucide:<name>); otherwise leaves icon empty (wordmark only).
	 */
	/**
	 * Detect header UTILITY ICON buttons — an icon-only search toggle and a cart/bag icon. Returns
	 * { search:bool, cart_svg:string }. A search icon → the theme's native `search` element; a cart/bag →
	 * a `custom_html` element carrying the source SVG (no native cart element). Icon-only = a <button>/<a>
	 * with an <svg> glyph and NO text label; classified by aria-label or the svg's lucide icon class.
	 */
	private static function detect_header_icons( $html ) {
		$out = array( 'search' => false, 'cart_svg' => '' );
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! $header ) { return $out; }
		foreach ( array( 'button', 'a' ) as $tag ) {
			foreach ( $header->getElementsByTagName( $tag ) as $b ) {
				if ( trim( self::text_no_icons( $b ) ) !== '' ) { continue; } // has a text label → not an icon button
				$svg = null;
				foreach ( $b->getElementsByTagName( 'svg' ) as $s ) { $svg = $s; break; }
				if ( ! ( $svg instanceof DOMElement ) ) { continue; }        // no glyph → skip (e.g. a hamburger handled elsewhere)
				$label = strtolower( trim( (string) $b->getAttribute( 'aria-label' ) ) );
				$scls  = strtolower( self::cls( $svg ) );
				$blob  = $label . ' ' . $scls;
				if ( strpos( $blob, 'menu' ) !== false && strpos( $blob, 'search' ) === false ) { continue; } // mobile hamburger toggle
				if ( strpos( $blob, 'search' ) !== false || strpos( $blob, 'magnif' ) !== false ) { $out['search'] = true; continue; }
				if ( strpos( $blob, 'cart' ) !== false || strpos( $blob, 'bag' ) !== false || strpos( $blob, 'basket' ) !== false || strpos( $blob, 'shopping' ) !== false ) {
					if ( $out['cart_svg'] === '' ) {
						$mk = $dom->saveHTML( $svg );
						if ( is_string( $mk ) && $mk !== '' && strlen( $mk ) < 8000 ) { $out['cart_svg'] = self::strip_cs( $mk ); }
					}
					continue;
				}
			}
		}
		return $out;
	}

	/**
	 * Is the brand logo CENTERED between two nav clusters (the split-nav "luxury" header — a menu on each
	 * side of a centered wordmark/emblem)? True when the header has ≥2 qualifying <nav> clusters, or the
	 * brand link itself carries a centering utility. Drives the menu-LEFT · logo-CENTER · icons-RIGHT layout.
	 */
	private static function detect_logo_centered( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return false; }
		$header = self::header_root( $dom );
		if ( ! $header ) { return false; }
		$nav_clusters = 0;
		foreach ( $header->getElementsByTagName( 'nav' ) as $n ) {
			$links = 0;
			foreach ( $n->getElementsByTagName( 'a' ) as $a ) {
				if ( ! self::is_button( $a ) && trim( self::text_no_icons( $a ) ) !== '' ) { $links++; }
			}
			if ( $links >= 1 ) { $nav_clusters++; }
		}
		if ( $nav_clusters >= 2 ) { return true; }
		// Single-nav sources can still centre the logo with an explicit utility on the brand link.
		foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
			if ( $a->getElementsByTagName( 'img' )->length === 0 ) { continue; }
			$lc = ' ' . strtolower( self::cls( $a ) ) . ' ';
			if ( strpos( $lc, ' mx-auto ' ) !== false || strpos( $lc, ' justify-center ' ) !== false || strpos( $lc, ' absolute ' ) !== false ) { return true; }
			break;
		}
		return false;
	}

	/** The header's leftmost LOGO slot when there is no brand <a> (a link-less text/image logo). Descends
	 *  through single-child wrappers to the header ROW, then returns its first child that reads like a logo —
	 *  an image, or short brand text (<=24 chars) — and is NOT the nav (no <nav>, <=1 link). Null if none. */
	private static function header_brand_block( $header ) {
		if ( ! ( $header instanceof DOMElement ) ) { return null; }
		$row = $header; $guard = 0;
		while ( $guard++ < 6 ) {
			$kids = self::el_children( $row );
			if ( count( $kids ) === 1 && in_array( strtolower( $kids[0]->tagName ), array( 'div', 'header', 'a', 'nav' ), true ) && strtolower( $kids[0]->tagName ) !== 'nav' ) { $row = $kids[0]; continue; }
			break;
		}
		return self::find_brand_slot( $row, 0 );
	}

	/**
	 * DEPTH-FIRST leftmost search for the brand SLOT under a header row. A direct child that is a tight
	 * brand element (an image, or short wordmark text) wins; but when the leftmost child is a WRAPPER that
	 * holds the brand ALONGSIDE other chrome (a `<div class="header-top">` carrying the brand + a status chip
	 * + a CTA, so its combined text overflows the 48-char guard — e.g. regenerative-landscapes), the old
	 * flat scan rejected the wrapper and returned NULL, dropping the wordmark → the theme fell back to the
	 * site title ("Home"). Descend into such a wrapper to find the leftmost brand slot inside it. A nav / a
	 * link-cluster (>1 anchor) is never the brand and is skipped without recursing.
	 *
	 * @param DOMElement $row
	 * @param int        $depth
	 * @return DOMElement|null
	 */
	private static function find_brand_slot( $row, $depth ) {
		if ( ! ( $row instanceof DOMElement ) || $depth > 4 ) { return null; }
		foreach ( self::el_children( $row ) as $slot ) {
			if ( ! ( $slot instanceof DOMElement ) ) { continue; }
			if ( strtolower( $slot->tagName ) === 'nav' || $slot->getElementsByTagName( 'nav' )->length ) { continue; }
			if ( $slot->getElementsByTagName( 'a' )->length > 1 ) { continue; } // a link cluster = the menu, not the logo
			$hasimg = $slot->getElementsByTagName( 'img' )->length > 0;
			$t = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $slot ) ) );
			if ( $hasimg || ( $t !== '' && ( mb_strlen( $t ) <= 24 || ( str_word_count( $t ) >= 2 && mb_strlen( $t ) <= 48 ) ) ) ) { return $slot; }
			// This child isn't itself the brand (too long / no brand text), but it's a non-nav WRAPPER — the
			// brand may sit inside it beside other chrome. Descend to the leftmost brand slot within.
			if ( $slot->getElementsByTagName( '*' )->length > 0 ) {
				$inner = self::find_brand_slot( $slot, $depth + 1 );
				if ( $inner ) { return $inner; }
			}
		}
		return null;
	}

	/** The <title>'s brand segment (before a | – — · : separator), '' when the title is empty. */
	private static function title_brand_segment( $title ) {
		$t = trim( html_entity_decode( (string) $title, ENT_QUOTES, 'UTF-8' ) ); if ( '' === $t ) { return ''; }
		$parts = preg_split( '/\s*[|\x{2013}\x{2014}\x{00B7}:]\s+/u', $t, 2 );
		$b = trim( (string) ( $parts[0] ?? '' ) );
		return ( mb_strlen( $b ) >= 2 && mb_strlen( $b ) <= 40 ) ? $b : '';
	}

	/** Among a header's short text LEAVES (no link inside), the one whose text starts with the <title>'s brand segment (case-
	 *  insensitive) — the wordmark of a link-less masthead. null when none matches. */
	private static function title_matched_brand_leaf( $header, $title ) {
		if ( ! ( $header instanceof DOMElement ) ) { return null; }
		// the document's own <title> first (the caller's title is the page NAME, "Home"), the given one as the fallback
		$doc_title = ''; if ( $header->ownerDocument ) { $tt = $header->ownerDocument->getElementsByTagName( 'title' )->item( 0 ); if ( $tt ) { $doc_title = trim( (string) $tt->textContent ); } }
		$seg = mb_strtolower( self::title_brand_segment( '' !== $doc_title ? $doc_title : $title ) ); if ( '' === $seg ) { return null; }
		foreach ( $header->getElementsByTagName( '*' ) as $e ) {
			if ( ! ( $e instanceof DOMElement ) || $e->getElementsByTagName( '*' )->length > 2 || $e->getElementsByTagName( 'a' )->length ) { continue; }
			$t = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $e ) ) );
			if ( '' === $t || mb_strlen( $t ) > 48 ) { continue; }
			if ( 0 === strpos( mb_strtolower( $t ), $seg ) ) { return $e; }
		}
		return null;
	}

	/**
	 * A LABEL-ONLY masthead: a fixed bar whose zones hold plain text labels and NO link / button at all (a status line left,
	 * the wordmark centred, a node label right). There is no menu to print; each non-brand label rides as a chip (list_item
	 * with the label's type) in the zone its DOM position gives it (first → left, last → right, between → centre), and the
	 * logo takes the brand leaf's zone. Returns { left:[], center:[], right:[], logo:'left'|'center'|'right' } or null when
	 * the header carries any link / button (a normal masthead). JS twin: labelOnlyMasthead.
	 */
	private static function header_label_zones( $html, $title ) {
		$dom = self::load_dom( (string) $html ); if ( ! $dom ) { return null; }
		$header = self::header_root( $dom ); if ( ! ( $header instanceof DOMElement ) ) { return null; }
		if ( $header->getElementsByTagName( 'a' )->length || $header->getElementsByTagName( 'button' )->length || $header->getElementsByTagName( 'nav' )->length && 'nav' !== strtolower( $header->tagName ) ) { return null; }
		$row = $header; $guard = 0;
		while ( $guard++ < 4 ) { $kids = self::el_children( $row ); if ( 1 === count( $kids ) && in_array( strtolower( $kids[0]->tagName ), array( 'div', 'header' ), true ) ) { $row = $kids[0]; continue; } break; }
		$kids = self::el_children( $row ); $n = count( $kids );
		if ( $n < 2 ) { return null; }
		$brand = self::title_matched_brand_leaf( $header, $title );
		$out = array( 'left' => array(), 'center' => array(), 'right' => array(), 'logo' => 'left' );
		$bi = -1;
		foreach ( $kids as $i => $k ) { if ( $brand && ( $k === $brand || self::is_ancestor( $k, $brand ) ) ) { $bi = $i; } }
		if ( $bi < 0 ) { $bi = 0; }
		foreach ( $kids as $i => $k ) {
			$zone = ( 0 === $i ) ? 'left' : ( ( $i === $n - 1 ) ? 'right' : 'center' );
			if ( $i === $bi ) { $out['logo'] = $zone; continue; }
			$t = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $k ) ) );
			if ( '' === $t || mb_strlen( $t ) > 48 ) { continue; }
			$leaf = $k; while ( $leaf instanceof DOMElement && 1 === count( self::el_children( $leaf ) ) && '' === trim( self::own_text_of( $leaf ) ) ) { $leaf = self::el_children( $leaf )[0]; }
			$out[ $zone ][] = array( 'text' => $t, 'cs' => (string) $leaf->getAttribute( 'data-sc-cs' ) );
		}
		return $out;
	}

	/** An element's own (direct) text, descendants excluded. */
	private static function own_text_of( $el ) {
		$t = ''; if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		foreach ( $el->childNodes as $c ) { if ( XML_TEXT_NODE === $c->nodeType ) { $t .= $c->nodeValue; } }
		return trim( preg_replace( '/\s+/', ' ', $t ) );
	}

	private static function detect_logo( $html, $title ) {
		$out = array( 'text' => '', 'tagline' => '', 'tagline_above' => false, 'icon' => '', 'image' => '', 'image_height' => 0, 'image_width' => 0, 'svg' => '', 'icon_color' => '', 'frame' => 'none', 'frame_bg' => '', 'frame_border' => '', 'frame_size' => '', 'title_color' => '', 'title_size' => '', 'title_weight' => '', 'title_font' => '', 'title_ls' => '', 'title_transform' => '', 'title_hover' => '', 'icon_size' => '', 'title_accent_color' => '', 'title_accent_text' => '' );
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! $header ) { return $out; }

		// Prefer an explicit brand link/element: an <a> whose href is '/', '#', or home. A naive "first home
		// anchor" grabbed a NAV link "Home" (which is ALSO href="/") and rendered its text as the wordmark
		// ("HOME"), when the real brand is a LATER `<a href="/"><img alt="NOIR Logo"></a>`. So rank the home
		// anchors: an anchor CONTAINING an <img> (an image logo) wins; else one that is NOT inside a <nav>
		// (a brand link sits outside the menu); else the first home anchor. This fixes the "HOME" logo bug.
		$brand = null; $brand_img = null; $brand_nonnav = null; $brand_any = null;
		foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
			$href = trim( (string) $a->getAttribute( 'href' ) );
			if ( ! ( $href === '' || $href === '#' || $href === '/' || preg_match( '~^https?://[^/]+/?$~', $href ) ) ) { continue; }
			if ( self::is_button( $a ) ) { continue; }
			if ( $brand_any === null ) { $brand_any = $a; }
			$in_nav = false;
			for ( $p = $a->parentNode; $p instanceof DOMElement; $p = $p->parentNode ) { if ( strtolower( $p->tagName ) === 'nav' ) { $in_nav = true; break; } }
			if ( $brand_img === null && $a->getElementsByTagName( 'img' )->length > 0 ) { $brand_img = $a; }
			if ( $brand_nonnav === null && ! $in_nav ) { $brand_nonnav = $a; }
		}
		$brand = $brand_img ? $brand_img : ( $brand_nonnav ? $brand_nonnav : $brand_any );
		// The only home-anchor candidates are MENU links in a LINK CLUSTER (a masthead that IS the <nav>: every '#' link
		// is "in nav", so the first menu item — "Products" — was read as the wordmark and became the site title). A
		// link-less brand block (icon + wordmark span) that PRECEDES that cluster is the real brand → the leftmost slot.
		if ( $brand instanceof DOMElement && $brand === $brand_any && null === $brand_img && $brand->parentNode instanceof DOMElement && $brand->parentNode->getElementsByTagName( 'a' )->length >= 2 ) {
			$slot = self::header_brand_block( $header );
			if ( $slot instanceof DOMElement && $slot !== $brand && ! self::is_ancestor( $slot, $brand ) && self::dom_precedes( $slot, $brand, $header ) ) { $brand = $slot; }
		}
		// No brand ANCHOR at all? Many sites use a LINK-LESS text/image logo — e.g. modfii's
		// `<div class="flex items-center gap-2">Mod<span>Fii</span></div>` (no <a>). Falling back to the
		// whole <header> made text_no_icons() harvest the ENTIRE header ("ModFiiFinancingResources…Get
		// Started") as the wordmark. Locate the header's leftmost logo SLOT instead.
		// A LINK-LESS masthead of plain labels (a fixed bar of "Headless Architecture · Brand Spatial · Low-Latency Node"): the
		// label that starts with the <title>'s brand segment is the wordmark, wherever it sits — not the leftmost label.
		if ( $brand === null ) { $brand = self::header_brand_block( $header ); }
		if ( $brand instanceof DOMElement && 0 === $header->getElementsByTagName( 'a' )->length ) {
			$leaf = self::title_matched_brand_leaf( $header, (string) $title );
			if ( $leaf instanceof DOMElement && $leaf !== $brand && ! self::is_ancestor( $brand, $leaf ) ) {
				$seg = mb_strtolower( self::title_brand_segment( (string) ( $header->ownerDocument && $header->ownerDocument->getElementsByTagName( 'title' )->item( 0 ) ? $header->ownerDocument->getElementsByTagName( 'title' )->item( 0 )->textContent : $title ) ) );
				if ( '' === $seg || false === strpos( mb_strtolower( trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $brand ) ) ) ), $seg ) ) { $brand = $leaf; } // the leftmost slot is a label, the brand sits elsewhere
			}
		}
		if ( $brand === null ) { $brand = $header; }

		// Image logo?
		foreach ( $brand->getElementsByTagName( 'img' ) as $img ) {
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( $src !== '' && strpos( $src, 'data:' ) !== 0 ) {
				$out['image'] = $src;
				// The emblem's rendered HEIGHT (so an image logo-icon is sized like the source, not oversized):
				// a Tailwind `h-[Npx]` / `h-N` (N×4px) class, or the computed height.
				$ic = ' ' . strtolower( self::cls( $img ) ) . ' ';
				// the MEASURED size first (`h-16 lg:h-20` is 80px at the capture width — the bare class is the phone value); the
				// class only when the capture stamped none. The rendered width feeds the Simple logo's Width option.
				$ih = self::sc_css( $img, 'height' ); $iw = self::sc_css( $img, 'width' );
				if ( preg_match( '/^([0-9.]+)px$/', $ih, $hm ) && (float) $hm[1] >= 8 ) { $out['image_height'] = (float) $hm[1]; }
				elseif ( preg_match( '/\bh-\[([0-9.]+)px\]/', $ic, $hm ) )      { $out['image_height'] = (float) $hm[1]; }
				elseif ( preg_match( '/\bh-(\d{1,3})\b/', $ic, $hm ) )      { $out['image_height'] = (int) $hm[1] * 4; }
				if ( preg_match( '/^([0-9.]+)px$/', $iw, $wm ) && (float) $wm[1] >= 8 ) { $out['image_width'] = (float) $wm[1]; }
			}
			break;
		}

		// Wordmark text (icons stripped) + its computed color.
		$txt = self::text_no_icons( $brand );
		$txt = trim( preg_replace( '/\s+/', ' ', (string) $txt ) );
		// Two-part brand LOCKUP: a primary wordmark element (<b>/<strong>) + a secondary TAGLINE element
		// (<i>/<em>/<small>, or a `.tagline`/`.sub`/`.eyebrow` class). kage: `<b>KAGE</b><i>HIDDEN REALMS OF
		// KYOTO</i>`. Splitting them keeps the long glued string ("KAGEHIDDEN REALMS…") from blowing the
		// 24-char wordmark guard below (which otherwise drops BOTH the title and the tagline).
		$primary_el = null; $tagline_el = null; $lockup_title = false;
		foreach ( array( 'b', 'strong' ) as $tg ) { foreach ( $brand->getElementsByTagName( $tg ) as $e ) { if ( '' !== trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $e ) ) ) ) { $primary_el = $e; break 2; } } }
		foreach ( array( 'i', 'em', 'small' ) as $tg ) { foreach ( $brand->getElementsByTagName( $tg ) as $e ) { if ( $e !== $primary_el && '' !== trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $e ) ) ) ) { $tagline_el = $e; break 2; } } }
		if ( ! $tagline_el ) { foreach ( array( 'span', 'small', 'div', 'p' ) as $tg ) { foreach ( $brand->getElementsByTagName( $tg ) as $e ) { if ( $e !== $primary_el && preg_match( '/\b(tagline|subtitle|eyebrow|sub|kicker)\b/i', self::cls( $e ) ) && '' !== trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $e ) ) ) ) { $tagline_el = $e; break 2; } } } }
		// TWO-LINE TEXT LOCKUP with NO semantic tags: a brand that stacks a short wordmark over a tagline as
		// plain <div>/<span>/<p> lines — no <b>/<i>, no `tagline`-ish class — e.g. art-of-living's
		// "Vesta Atelier" / "Curated Living Spaces", colosseum's "S.P.Q.R." / "Roma Antiqua". Their COMBINED
		// text ("Vesta Atelier Curated Living Spaces" = 5 words) blows the ≤4-word wordmark guard below and
		// BOTH lines are dropped → the theme falls back to "Home". Split the first SHORT line off as the
		// wordmark and keep the second as the tagline. Take the innermost text LEAVES (so a wrapping flex
		// column isn't counted as its own line) in document order; require the first to look like a wordmark.
		if ( ! $primary_el ) {
			$lines = array();
			foreach ( $brand->getElementsByTagName( '*' ) as $e ) {
				if ( ! in_array( strtolower( $e->tagName ), array( 'span', 'div', 'p' ), true ) ) { continue; }
				$child_text = false;
				foreach ( self::el_children( $e ) as $ce ) { if ( '' !== trim( self::text_no_icons( $ce ) ) ) { $child_text = true; break; } }
				if ( $child_text ) { continue; } // not a leaf line — its text lives in a child we'll visit
				$lt = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $e ) ) );
				if ( '' !== $lt ) { $lines[] = array( $e, $lt ); }
				if ( count( $lines ) >= 2 ) { break; }
			}
			// Word count by WHITESPACE tokens, not str_word_count() — a dotted acronym wordmark ("S.P.Q.R.")
			// is ONE visual token but str_word_count() reads it as 4 (periods split it) and wrongly rejects it.
			// Guard $lines[0] — a header with no qualifying text lines leaves $lines empty (was an Undefined-key warning).
			$w_tokens = ( ! empty( $lines ) ) ? count( preg_split( '/\s+/', trim( $lines[0][1] ) ) ) : 0;
			if ( count( $lines ) >= 2 && $w_tokens <= 3 ) {
				// WHICH line is the wordmark? Not necessarily the first. A very common lockup puts a
				// small tracked-out EYEBROW above the real title ("Prime Gravity" over "The Art of the
				// Burger"), and taking DOM order made the eyebrow the site title while the actual title
				// became a 7px tagline. Decide by visual PROMINENCE from the captured computed styles:
				// font-size first, then weight, then a non-dimmed colour. DOM order is only the tie-break.
				$prom = function ( $el ) {
					$cs = ( $el instanceof DOMElement ) ? (string) $el->getAttribute( 'data-sc-cs' ) : '';
					$fs = 0.0; $fw = 400; $alpha = 1.0;
					if ( '' !== $cs ) {
						if ( preg_match( '/font-size\s*:\s*([0-9.]+)px/i', $cs, $m ) ) { $fs = (float) $m[1]; }
						if ( preg_match( '/font-weight\s*:\s*(\d{3})/i', $cs, $m ) ) { $fw = (int) $m[1]; }
						if ( preg_match( '/(?:^|;)\s*color\s*:\s*rgba?\([^)]*[,\/]\s*([0-9.]+)\s*\)/i', $cs, $m ) ) { $alpha = (float) $m[1]; }
					}
					return array( 'fs' => $fs, 'fw' => $fw, 'alpha' => $alpha );
				};
				$a = $prom( $lines[0][0] );
				$b = $prom( $lines[1][0] );
				$second_wins = false;
				if ( $a['fs'] > 0 && $b['fs'] > 0 && abs( $a['fs'] - $b['fs'] ) >= 1 ) {
					$second_wins = ( $b['fs'] > $a['fs'] );
				} elseif ( $a['fw'] !== $b['fw'] ) {
					$second_wins = ( $b['fw'] > $a['fw'] );
				} elseif ( abs( $a['alpha'] - $b['alpha'] ) > 0.05 ) {
					$second_wins = ( $b['alpha'] > $a['alpha'] );
				}
				$title_i = $second_wins ? 1 : 0;
				$tag_i   = $second_wins ? 0 : 1;
				// Keep the original 24-char wordmark guard, but apply it to the line actually chosen.
				if ( mb_strlen( $lines[ $title_i ][1] ) <= 24 || ( $second_wins && mb_strlen( $lines[ $title_i ][1] ) <= 48 ) ) {
					// This title came from an IDENTIFIED two-line lockup chosen on measured prominence,
					// not from scraping a row — so the anti-nav word guard below can be relaxed for it.
					// Only when the prominence check OVERRODE DOM order — that is the case the old
					// <=4-word cap breaks. A first-line title keeps the previous, tighter guard, so
					// nothing that converted correctly before can change.
					$lockup_title = $second_wins;
					$primary_el = $lines[ $title_i ][0];
					$tagline_el = $tagline_el ? $tagline_el : $lines[ $tag_i ][0];
					// The tagline sitting ABOVE the title is the EYEBROW arrangement, which the theme
					// supports natively (logo_layout "<arrangement>-<side>", arrangement eyebrow).
					$out['tagline_above'] = $second_wins;
				}
			}
		}
		if ( $primary_el ) {
			$pt = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $primary_el ) ) );
			if ( '' !== $pt && mb_strlen( $pt ) <= 40 ) {
				$txt = $pt; // the wordmark is just the primary part; the guard below then accepts it
				if ( $tagline_el ) {
					$tg = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $tagline_el ) ) );
					if ( '' !== $tg && mb_strlen( $tg ) <= 60 ) { $out['tagline'] = $tg; }
				}
			}
		}
		// An IMAGE logo (`<a><img alt="AURA Logo"></a>`) carries the wordmark/emblem/tagline baked into the
		// graphic and has NO real text node — text_no_icons falls back to the <img alt>, which would set a
		// wordmark and flip logo_type to 'custom' (rendering plain alt text INSTEAD of the logo image). So when
		// the brand has no real text content but does have an image, keep the wordmark empty → logo_type stays
		// 'simple' and the actual logo graphic renders. A real icon+wordmark lockup (a `<span>` beside the icon)
		// has real text content and is unaffected.
		$real_text = trim( preg_replace( '/\s+/', ' ', (string) $brand->textContent ) );
		if ( $real_text === '' && $out['image'] !== '' ) { $txt = ''; }
		// Guard against grabbing the whole nav: a brand wordmark is short (<= 4 words AND <= 24 chars).
		// The char cap matters because Tailwind strips whitespace between inline nav items, so a whole
		// glued header row ("ModFiiFinancingResources…") can read as only ~4 "words".
		// The <=4-word cap guards against swallowing a glued nav row. A title taken from an identified
		// two-line lockup is already known to be the wordmark, and real titles run longer than four
		// words ("The Art of the Burger" is five), so widen the cap for that case only.
		$word_cap = $lockup_title ? 6 : 4;
		$char_cap = $lockup_title ? 48 : 24;
		if ( $txt !== '' && str_word_count( $txt ) <= $word_cap
			&& ( mb_strlen( $txt ) <= $char_cap || ( str_word_count( $txt ) >= 2 && mb_strlen( $txt ) <= 48 ) ) ) { $out['text'] = $txt; }
		// The wordmark text color + SIZE + WEIGHT: the deepest element whose text STARTS the wordmark (the first
		// <span>), plus — for a TWO-TONE wordmark (an ink part + a later accent part) — a later sibling span
		// whose color differs = the accent tone. The base `color` maps natively; the accent is a documented
		// residual (a single color field can't split a wordmark), surfaced as title_accent_color for logo_custom_css.
		// BASE (ink) tone = the wordmark's OWN color/size/weight, read off the brand element — NOT "the first
		// span". A two-tone wordmark's accent is often the ONLY span (e.g. "Apex <span>Injury</span>
		// Advocates") with the base as bare text on the <a>; reading the first span as base mis-set the whole
		// title to the accent color and dropped the split. (resolved computed values, so inheritance is fine.)
		// Prefer the WORDMARK element (the <span>/text node carrying the wordmark) for the type treatment. An
		// image-logo lockup styles the wordmark ON that span (`font-serif uppercase tracking-widest`), while the
		// <a> wrapper is a plain flex container in the default sans — reading the <a> dropped the serif, the
		// UPPERCASE, and the letter-spacing (rendering a bare "Aura" instead of the serif "AURA"). Fall back to
		// $brand when there's no distinct wordmark span (a plain bare-text wordmark).
		$wm = $brand;
		if ( $out['text'] !== '' ) {
			foreach ( array( 'span', 'strong', 'b', 'p', 'div', 'h1', 'h2' ) as $tg ) {
				foreach ( $brand->getElementsByTagName( $tg ) as $e ) {
					$et = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $e ) ) );
					if ( $et !== '' && $et === $out['text'] && $e->getElementsByTagName( '*' )->length <= 1 ) { $wm = $e; break 2; }
				}
			}
		}
		$out['title_color'] = self::sc_css( $wm, 'color' );
		$out['title_size']  = self::sc_css( $wm, 'font-size' );
		$fwt_b = self::sc_css( $wm, 'font-weight' );   if ( preg_match( '/^(300|400|500|600|700|800|900)$/', trim( $fwt_b ) ) ) { $out['title_weight'] = trim( $fwt_b ); }
		$ff_b  = self::sc_css( $wm, 'font-family' );    if ( $ff_b !== '' ) { $out['title_font'] = $ff_b; }
		$ls_b  = self::sc_css( $wm, 'letter-spacing' ); if ( $ls_b !== '' && $ls_b !== 'normal' && $ls_b !== '0px' ) { $out['title_ls'] = $ls_b; }
		// Wordmark CASE: a source `text-transform:uppercase` / `uppercase` class → title_transform, so the
		// converted wordmark reads "AURA" (serif kicker) like the source, not the raw-cased "Aura".
		$tt_b = strtolower( trim( (string) self::sc_css( $wm, 'text-transform' ) ) );
		if ( in_array( $tt_b, array( 'uppercase', 'lowercase', 'capitalize' ), true ) ) { $out['title_transform'] = $tt_b; }
		// ACCENT tone = a sub-run span whose color differs from the base ink → the emit SPLITS the wordmark
		// into the ink part + <span class="accent">accent run</span> ("Injury" of "Apex Injury Advocates",
		// "Paws" of "FreshPaws"). A span wrapping the WHOLE wordmark is not an accent run.
		foreach ( $brand->getElementsByTagName( 'span' ) as $sp ) {
			$st = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $sp ) ) );
			if ( $st === '' || $out['text'] === '' || $st === $out['text'] || strpos( $out['text'], $st ) === false ) { continue; }
			$c = self::sc_css( $sp, 'color' );
			if ( $c !== '' && $out['title_color'] !== '' && $c !== $out['title_color'] && $out['title_accent_color'] === '' ) {
				$out['title_accent_color'] = $c;   // the second-tone (accent) span color
				$out['title_accent_text']  = $st;  // the accent RUN → split into ink + <span class="accent">
			}
		}
		if ( $out['title_color'] === '' ) { $out['title_color'] = self::sc_css( $brand, 'color' ); }
		if ( $out['title_size'] === '' )  { $out['title_size']  = self::sc_css( $brand, 'font-size' ); }
		// Wordmark FONT-FAMILY + LETTER-SPACING (the `font-serif` / `tracking-tight` residual) — no native logo
		// option, so carried as scoped logo_custom_css below. Fall back to the brand element's own computed
		// values when the text sat directly on the <a> (no measured inner span).
		if ( $out['title_font'] === '' ) { $out['title_font'] = self::sc_css( $brand, 'font-family' ); }
		if ( $out['title_ls'] === '' )   { $lsb = self::sc_css( $brand, 'letter-spacing' ); if ( $lsb !== '' && $lsb !== 'normal' && $lsb !== '0px' ) { $out['title_ls'] = $lsb; } }
		// Hover colour (`hover:text-primary`) — computed styles can't see :hover, so read the SEMANTIC token
		// from the brand link's class and map it to the theme's Color-Preset var below (portable + editable).
		$bcls = self::cls( $brand );
		if ( preg_match( '/hover:text-([a-z][a-z0-9-]*)/', $bcls, $hvm ) ) { $out['title_hover'] = $hvm[1]; }

		// Icon: an inline <svg> mark (kept VERBATIM — icon-v2 renders inline SVG via currentColor), plus its
		// color + an optional colored frame TILE (a wrapper div with a background + rounded corners — the
		// the golden fixture "green rounded paw tile" pattern). Fall back to a Lucide library id when no inline svg.
		$svg = null;
		foreach ( $brand->getElementsByTagName( 'svg' ) as $s ) { $svg = $s; break; }
		if ( $svg instanceof DOMElement ) {
			// Strip capture-only attributes (data-sc-*) from the icon subtree before serializing — otherwise the
			// stored inline SVG carries the whole computed-style blob on every node (bloat + noise in the option).
			$svg_nodes = array( $svg );
			foreach ( $svg->getElementsByTagName( '*' ) as $sn ) { if ( $sn instanceof DOMElement ) { $svg_nodes[] = $sn; } }
			foreach ( $svg_nodes as $sn ) {
				$rm = array();
				foreach ( $sn->attributes as $a ) { if ( 0 === stripos( $a->nodeName, 'data-sc-' ) ) { $rm[] = $a->nodeName; } }
				foreach ( $rm as $n ) { $sn->removeAttribute( $n ); }
			}
			$markup = $dom->saveHTML( $svg );
			if ( is_string( $markup ) && $markup !== '' && strlen( $markup ) < 12000 ) { $out['svg'] = $markup; }
			// Icon color: a `text-white`/`text-*` class or the svg's computed color; else the wordmark color.
			$scls = self::cls( $svg );
			if ( strpos( $scls, 'text-white' ) !== false ) { $out['icon_color'] = '#ffffff'; }
			else {
				$out['icon_color'] = self::sc_css( $svg, 'color' );
				// The capture never stamps an <svg> itself; a glyph painted with currentColor takes its ink from the nearest
				// stamped ancestor (the <iconify-icon> host / the mark wrapper: `text-pearl` = black on a white circle). Without
				// this the frame fallback below painted it white-on-white.
				if ( '' === $out['icon_color'] ) { for ( $ap = $svg->parentNode, $ai = 0; $ap instanceof DOMElement && $ai < 3; $ap = $ap->parentNode, $ai++ ) { $ac = self::sc_css( $ap, 'color' ); if ( '' !== $ac ) { $out['icon_color'] = $ac; break; } } }
			}
			// Icon glyph size: computed width, else a Tailwind `w-N`/`w-[..]` class (N × 4px). e.g. `w-6` = 24px.
			$isz = self::sc_css( $svg, 'width' );
			if ( $isz === '' ) { $isz = self::tw_size_px( $scls ); }
			if ( $isz !== '' && preg_match( '/^[0-9.]+(px|rem|em)?$/', trim( $isz ) ) ) { $out['icon_size'] = trim( $isz ); }
			// Frame tile: the nearest ancestor (within the brand) that has a real background + rounding. Infer the
			// frame SHAPE from the tile's corner-radius vs its size: a radius ≥ ~48% of the box → circle (fully
			// rounded), a smaller-but-present radius → rounded box, none → square.
			$anc = $svg->parentNode;
			while ( $anc instanceof DOMElement && $anc !== $brand ) {
				$bg = self::sc_css( $anc, 'background-color' );
				$br = self::sc_css( $anc, 'border-radius' );
				$has_fill = ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/i', $bg ) );
				// a RING tile — a bordered box with no fill (`w-8 h-8 rounded-lg border border-white/20`) — is a frame too; its hairline
				// rides logo_custom_css since the frame option only has a fill (a finding filed on six conversions)
				$bw = self::sc_css( $anc, 'border-top-width' ); $has_ring = ( '' !== $bw && preg_match( '/^([0-9.]+)px$/', $bw, $bwm ) && (float) $bwm[1] > 0 );
				if ( $has_fill || $has_ring ) {
					if ( $has_fill ) { $out['frame_bg'] = $bg; }
					if ( $has_ring ) { $bc = self::sc_css( $anc, 'border-top-color' ); $out['frame_border'] = $bw . ' solid ' . ( '' !== $bc ? $bc : 'currentColor' ); }
					$tile_px = self::sc_css( $anc, 'width' );
					if ( $tile_px === '' ) { $tile_px = self::tw_size_px( self::cls( $anc ) ); }
					if ( '' !== $tile_px ) { $out['frame_size'] = $tile_px; }
					$out['frame'] = self::infer_frame_shape( $br, $tile_px );
					if ( $has_fill && $out['icon_color'] === '' ) { $out['icon_color'] = '#ffffff'; } // colored tile ⇒ white mark
					break;
				}
				$anc = $anc->parentNode;
			}
		}
		// CSS-COMPOSED MARK → inline SVG. A brand whose icon is drawn in pure CSS (nested gradient <div>s, no
		// <img>/<svg>) carries no capturable mark — the capture stage reconstructs it as a faithful inline SVG and
		// stamps it on the mark root as `data-sc-logo-svg`. Lift that verbatim into the icon (svg-inline) so the
		// gradient logo survives, sized to the mark's own box. (Synthesis lives in capture-extract.mjs, where the
		// live geometry is; PHP just consumes the stamped markup — one source of truth, no duplicated geometry math.)
		if ( $out['svg'] === '' ) {
			$mark_el = null;
			$b_svg   = trim( (string) $brand->getAttribute( 'data-sc-logo-svg' ) );
			if ( 0 === stripos( $b_svg, '<svg' ) ) { $mark_el = $brand; }
			else {
				foreach ( $brand->getElementsByTagName( '*' ) as $el ) {
					$v = trim( (string) $el->getAttribute( 'data-sc-logo-svg' ) );
					if ( 0 === stripos( $v, '<svg' ) ) { $mark_el = $el; $b_svg = $v; break; }
				}
			}
			if ( $mark_el && strlen( $b_svg ) < 12000 ) {
				$out['svg'] = $b_svg;
				// Size the icon to the reconstructed mark's own box (the capture stamped the source width).
				$mw = self::sc_css( $mark_el, 'width' );
				if ( $mw === '' ) { $mw = self::tw_size_px( self::cls( $mark_el ) ); }
				if ( $out['icon_size'] === '' && $mw !== '' && preg_match( '/^([0-9.]+)(px|rem|em)?$/', trim( $mw ) ) ) { $out['icon_size'] = trim( $mw ); }
				// The synthesized mark carries its OWN gradient fills → no icon tint / frame tile to infer.
				// ...UNLESS the glyph is monochrome. A `currentColor` mark (an icon-font/iconify glyph
				// lifted out of its shadow DOM) takes BOTH its tint and its tile from CSS, so the
				// gradient-logo assumption above does not hold: infer them from the mark element the
				// same way the real-<svg> path does. Without this a gold glyph on a rounded tile
				// converts to a bare white icon - the only accent in the header, silently dropped.
				if ( false !== stripos( $b_svg, 'currentcolor' ) ) {
					if ( '' === $out['icon_color'] ) {
						// The GLYPH carries the deliberate tint; the mark wrapper usually just inherits the
						// header's text colour. So prefer a descendant colour that DIFFERS from the wrapper's
						// - taking the wrapper's own first yielded plain white and dropped the gold entirely.
						$own = self::sc_css( $mark_el, 'color' );
						$c   = '';
						foreach ( $mark_el->getElementsByTagName( '*' ) as $kid ) {
							$kc = self::sc_css( $kid, 'color' );
							if ( '' !== $kc && $kc !== $own ) { $c = $kc; break; }
						}
						if ( '' === $c ) { $c = $own; }
						if ( '' !== $c ) { $out['icon_color'] = $c; }
					}
					$mbg = self::sc_css( $mark_el, 'background-color' );
					if ( '' !== $mbg && false === stripos( $mbg, 'transparent' ) && ! preg_match( '/rgba\([^)]*[,\/]\s*0\s*\)/i', $mbg ) ) {
						$out['frame_bg'] = $mbg;
						$tile = self::sc_css( $mark_el, 'width' );
						if ( '' === $tile ) {
							// The zone/decor stamp carries the real box when data-sc-cs does not.
							$dec = (string) $mark_el->getAttribute( 'data-sc-decor' );
							if ( '' !== $dec && preg_match( '/w:\s*([0-9.]+px)/i', $dec, $wm ) ) { $tile = $wm[1]; }
						}
						$rad = self::sc_css( $mark_el, 'border-radius' );
						if ( '' === $rad ) {
							$dec = (string) $mark_el->getAttribute( 'data-sc-decor' );
							if ( '' !== $dec && preg_match( '/radius:\s*([0-9.]+px)/i', $dec, $rm2 ) ) { $rad = $rm2[1]; }
						}
						$out['frame'] = self::infer_frame_shape( $rad, $tile );
					}
				}
			}
		}
		if ( $out['svg'] === '' ) { $out['icon'] = self::detect_lucide_in( $brand ); }
		return $out;
	}

	/**
	 * A pixel size (as a `NNpx` string) from a Tailwind sizing class: `w-6`/`h-6` (N × 4px = 24px),
	 * `size-10` (40px), or an arbitrary `w-[40px]`/`w-[2.5rem]`. Returns '' when no sizing class is present.
	 */
	private static function tw_size_px( $cls ) {
		$cls = ' ' . (string) $cls . ' ';
		if ( preg_match( '/\s(?:w|h|size)-\[([0-9.]+)(px|rem|em)\]/', $cls, $m ) ) {
			$v = (float) $m[1]; return ( $m[2] === 'px' ) ? ( rtrim( rtrim( (string) $v, '0' ), '.' ) . 'px' ) : ( (string) $v . $m[2] );
		}
		if ( preg_match( '/\s(?:w|h|size)-([0-9]+(?:\.[0-9]+)?)\s/', $cls, $m ) ) { return (string) ( (float) $m[1] * 4 ) . 'px'; }
		return '';
	}

	/**
	 * Infer the logo frame SHAPE (`circle` | `squircle` | `rounded` | `square`) from a tile's border-radius vs
	 * its box size. A `%`/`50%` radius or a pill `9999px` is a true CIRCLE. For a FINITE px radius the key is
	 * that CSS CLAMPS border-radius to HALF the box (`min(r, box/2)`), so a radius ≥ 50% of the box renders as
	 * a FULL CIRCLE — e.g. the golden fixture's `rounded-2xl` = 24px on a 40px tile (ratio 0.6) clamps to a circle, so it
	 * IS a circle, not a squircle. A large-but-sub-half corner (`rounded-xl`/`2xl`/`3xl`, ~0.22–0.5 ratio) is
	 * the app-icon **squircle** look; a small finite radius → rounded; `0`/absent → square. Box unknown: a
	 * moderate px radius (≥10px) reads as squircle, a small one as rounded.
	 */
	private static function infer_frame_shape( $radius, $box_px ) {
		$radius = trim( (string) $radius );
		if ( $radius === '' || preg_match( '/^0(px|rem|em)?(\s+0(px|rem|em)?)*$/', $radius ) ) { return 'square'; }
		// A percent radius or a huge pill radius = a full CIRCLE regardless of size (the `rounded-full` idiom).
		if ( strpos( $radius, '%' ) !== false || preg_match( '/(?:^|\s)(?:99\d\d|[1-9]\d{4,})px/', $radius ) ) { return 'circle'; }
		$r = 0.0; if ( preg_match( '/([0-9.]+)px/', $radius, $rm ) ) { $r = (float) $rm[1]; }
		$b = 0.0; if ( preg_match( '/([0-9.]+)px/', (string) $box_px, $bm ) ) { $b = (float) $bm[1]; }
		if ( $r > 0 && $b > 0 ) {
			$ratio = $r / $b;
			// CSS clamps radius to box/2, so ratio ≥ ~0.5 is a fully-rounded CIRCLE (not merely a squircle).
			if ( $ratio >= 0.5 ) { return 'circle'; }
			if ( $ratio >= 0.22 ) { return 'squircle'; }  // rounded-xl/2xl/3xl app-icon tile (sub-half corner)
			return 'rounded';                              // gentle corner
		}
		// Box size unknown — judge by the raw radius: a moderate finite corner is the squircle look.
		if ( $r >= 10 ) { return 'squircle'; }
		return ( $r > 0 ) ? 'rounded' : 'square';
	}

	/** An element's OPAQUE computed background-color (data-sc-cs), or '' when transparent / absent / low-alpha (≤0.25). */
	private static function el_bg_opaque( $el ) {
		$bg = self::sc_css( $el, 'background-color' );
		if ( $bg === '' || stripos( $bg, 'transparent' ) !== false ) { return ''; }
		if ( preg_match( '/rgba\([^)]*,\s*([0-9.]+)\s*\)/i', $bg, $m ) && (float) $m[1] <= 0.25 ) { return ''; }
		return $bg;
	}

	/**
	 * PREVIEW-ONLY: the resolved background COLOUR of the section a captured pattern sits on. Climbs the
	 * pattern element's ancestors for the first opaque `background-color` (computed `data-sc-cs` OR an inline
	 * `style`), else a gradient band's first colour stop (a hero over a green gradient). Returns a raw CSS
	 * colour string the color-picker + preview iframe consume directly, or '' when none is resolvable (the
	 * editor then shows its checkerboard). NEVER emitted into the pattern's output CSS — editor metadata only.
	 */
	private static function pattern_preview_bg( $el ) {
		$depth = 0;
		for ( $p = $el; $p instanceof DOMElement && $depth < 14; $p = $p->parentNode, $depth++ ) {
			$bg = self::el_bg_opaque( $p );
			if ( '' !== $bg ) { return $bg; }
			// Inline style background-color (a non-captured source keeps its colours inline).
			$style = (string) $p->getAttribute( 'style' );
			if ( '' !== $style && preg_match( '/background(?:-color)?:\s*(#[0-9a-f]{3,8}|rgba?\([^)]*\)|hsla?\([^)]*\))/i', $style, $sm ) && stripos( $sm[1], 'transparent' ) === false ) { return $sm[1]; }
			// A band whose visible fill is a GRADIENT (computed or inline) → its first colour stop.
			$grad = self::sc_css( $p, 'background-image' );
			if ( '' === $grad && '' !== $style && preg_match( '/background(?:-image)?:\s*([^;]*(?:linear|radial)-gradient[^;]*)/i', $style, $gm ) ) { $grad = $gm[1]; }
			if ( '' !== $grad && preg_match( '/(?:linear|radial)-gradient/i', $grad ) && preg_match( '/(#[0-9a-f]{3,8}|rgba?\([^)]*\)|hsla?\([^)]*\))/i', $grad, $cm ) ) { return $cm[1]; }
			if ( 'section' === strtolower( (string) $p->tagName ) ) { break; }
		}
		return '';
	}

	/** The opaque fill of a full-bleed (`absolute inset-0`) background LAYER inside a band (the overlay pattern
	 *  a `<div class="absolute inset-0 bg-primary">` behind a CTA section), or '' when none. Skips decorative
	 *  low-alpha blobs (handled by el_bg_opaque's alpha gate). */
	private static function fullbleed_bg( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return ''; }
		foreach ( $node->getElementsByTagName( 'div' ) as $d ) {
			$c = ' ' . self::cls( $d ) . ' ';
			if ( strpos( $c, ' inset-0' ) === false && strpos( $c, 'inset-0 ' ) === false ) { continue; }
			$r = self::el_bg_opaque( $d );
			if ( $r !== '' ) { return $r; }
		}
		return '';
	}

	/** Read a single CSS property value from an element's captured `data-sc-cs` computed-style attribute. '' if absent. */
	private static function sc_css( $el, $prop ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( $cs === '' ) { return ''; }
		if ( preg_match( '/(?:^|;)\s*' . preg_quote( $prop, '/' ) . '\s*:\s*([^;]+)/i', $cs, $m ) ) { return trim( $m[1] ); }
		return '';
	}

	/** Sniff a Lucide icon id ('lucide/<name>') from data-lucide / class lucide-<name> / iconify lucide:<name>. */
	/** An svg that is a CONTROL glyph rather than the card's icon: inside a <button> (a wishlist toggle, a close), or inside an
	 *  absolutely-positioned overlay of the card (a corner badge / a hover pill) — a product card's heart had become the
	 *  card's icon above its title (a real-site audit). */
	private static function is_control_glyph( $sv, $root ) {
		$p = $sv->parentNode; $d = 0;
		while ( $p instanceof DOMElement && $p !== $root && $d++ < 8 ) {
			if ( 'button' === strtolower( $p->tagName ) ) { return true; }
			if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', (string) $p->getAttribute( 'data-sc-cs' ) ) || preg_match( '/\s(?:absolute|fixed)\s/', ' ' . self::cls( $p ) . ' ' ) ) { return true; }
			$p = $p->parentNode;
		}
		return false;
	}

	private static function detect_lucide_in( $node ) {
		// data-lucide="wind" (Lucide's own web-component / data attr)
		foreach ( $node->getElementsByTagName( 'i' ) as $i ) {
			$dl = trim( (string) $i->getAttribute( 'data-lucide' ) );
			if ( $dl !== '' ) { return 'lucide/' . sanitize_title( $dl ); }
			$cls = self::cls( $i );
			if ( preg_match( '/\blucide-([a-z0-9-]+)/', $cls, $m ) ) { return 'lucide/' . $m[1]; }
		}
		// lucide-react / lucide-static render the icon as `<svg class="lucide lucide-star …">` — the commonest shape on AI-built
		// pages; it was invisible here, so every such card lost its icon (a fixture from the feed)
		foreach ( $node->getElementsByTagName( 'svg' ) as $sv ) {
			if ( self::is_control_glyph( $sv, $node ) ) { continue; } // a wishlist / close / arrow CONTROL on the card, not its icon
			if ( preg_match( '/(?:^|\s)lucide-([a-z0-9-]+)(?:\s|$)/', self::cls( $sv ), $m ) && 'lucide' !== $m[1] ) { return 'lucide/' . $m[1]; }
		}
		// iconify-icon icon="lucide:wind"
		foreach ( $node->getElementsByTagName( '*' ) as $any ) {
			$ic = trim( (string) $any->getAttribute( 'icon' ) );
			if ( preg_match( '/^lucide:([a-z0-9-]+)$/', $ic, $m ) ) { return 'lucide/' . $m[1]; }
			$dl = trim( (string) $any->getAttribute( 'data-lucide' ) );
			if ( $dl !== '' ) { return 'lucide/' . sanitize_title( $dl ); }
		}
		return '';
	}

	/** TRUE when $el holds (or is) an icon / media element: img, svg, picture, video, canvas, an icon-font <i>, an
	 *  <iconify-icon>, or any custom element (a tag with a hyphen — lottie-player, dotlottie-player, …). */
	private static function holds_icon_or_media( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tags = array( 'img', 'svg', 'picture', 'video', 'canvas', 'i', 'iconify-icon' );
		if ( in_array( strtolower( $el->tagName ), $tags, true ) || false !== strpos( $el->tagName, '-' ) ) { return true; }
		foreach ( $tags as $t ) { if ( $el->getElementsByTagName( $t )->length > 0 ) { return true; } }
		foreach ( $el->getElementsByTagName( '*' ) as $d ) { if ( false !== strpos( $d->tagName, '-' ) ) { return true; } }
		return false;
	}
	/** The ELEMENT that carries a Lucide/iconify icon inside $node — an `<iconify-icon icon="lucide:…">`,
	 *  an `<i data-lucide>`/`<i class="lucide-…">`, or an inline `<svg>` — so its class + computed colour +
	 *  chip can be read (a web-component icon has no light-DOM <svg>). Returns the DOMElement or null. */
	private static function lucide_icon_el( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return null; }
		foreach ( $node->getElementsByTagName( '*' ) as $e ) {
			if ( trim( (string) $e->getAttribute( 'icon' ) ) !== '' ) { return $e; }
			if ( trim( (string) $e->getAttribute( 'data-lucide' ) ) !== '' ) { return $e; }
			if ( preg_match( '/\blucide-[a-z0-9-]+/', self::cls( $e ) ) ) { return $e; }
			if ( 'svg' === strtolower( $e->tagName ) ) { return $e; }
		}
		return null;
	}

	/** The footer's copyright line (a © / "rights reserved" text node), or '' if none. */
	/** Plain text leaves (no link) that sit in the legal-link row beside the © line — a status label — as { text, color }. */
	private static function detect_footer_legal_tail( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return array(); }
		$cp = self::footer_copyright_el( $footer );
		if ( ! ( $cp instanceof DOMElement ) || ! ( $cp->parentNode instanceof DOMElement ) ) { return array(); }
		$out = array();
		foreach ( self::el_children( $cp->parentNode ) as $sib ) {
			if ( $sib === $cp || 0 === $sib->getElementsByTagName( 'a' )->length ) { continue; } // the row that holds the links
			foreach ( self::el_children( $sib ) as $k ) {
				if ( 'a' === strtolower( $k->tagName ) || 0 !== $k->getElementsByTagName( '*' )->length ) { continue; }
				$t = trim( preg_replace( '/\s+/', ' ', (string) $k->textContent ) );
				if ( '' === $t || mb_strlen( $t ) > 40 ) { continue; }
				$c = self::color_keep_alpha( (string) self::sc_css( $k, 'color' ) );
				$out[] = array( 'text' => $t, 'color' => $c );
			}
		}
		return $out;
	}

	private static function detect_footer_copyright( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return ''; }
		$best = '';
		$cp = self::footer_copyright_el( $footer );
		if ( $cp instanceof DOMElement ) { $best = trim( (string) $cp->textContent ); }
		if ( $best !== '' ) {
			// Normalize a year to the live token so it stays current.
			$best = preg_replace( '/\b(19|20)\d{2}\b/', '{{current_year}}', $best, 1 );
			$best = esc_html( $best );
			// Normalize the copyright glyph to the entity — DOMDocument's textContent can hand back the
			// UTF-8 © as the mojibake pair `Â©` (bytes C2 A9 read as Latin-1); collapse both forms so the
			// stored copyright line never carries a stray `Â`.
			$best = str_replace( array( "\xc3\x82\xc2\xa9", 'Â©', "\xc2\xa9", '©' ), '&copy;', $best );
		}
		return $best;
	}

	/** The footer's bottom-bar SECONDARY tagline — a short text `<p>` sitting in the same row as the ©
	 *  line (a `justify-between` bottom bar: "© …" left, "Designed for the modern professional." right),
	 *  which is NOT the copyright and NOT a legal-link list. Returns '' when the bar has only the © line. */
	private static function detect_footer_bottom_tagline( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return ''; }
		$copy_p = self::footer_copyright_el( $footer );
		if ( ! ( $copy_p instanceof DOMElement ) || ! ( $copy_p->parentNode instanceof DOMElement ) ) { return ''; }
		foreach ( self::el_children( $copy_p->parentNode ) as $sib ) {
			if ( $sib === $copy_p ) { continue; }
			// a sibling <p>, OR a small status lockup (a status dot + one label span: "● System operational") — a text-only
			// sibling with no link, ≤ 80 chars; a painted dot inside carries no text and is dropped with the wrapper
			$stag = strtolower( $sib->tagName );
			if ( 'p' !== $stag && ! ( in_array( $stag, array( 'div', 'span' ), true ) && $sib->getElementsByTagName( '*' )->length <= 3 ) ) { continue; }
			if ( $sib->getElementsByTagName( 'a' )->length > 0 ) { continue; } // legal-link list — handled separately
			$t = trim( preg_replace( '/\s+/', ' ', (string) $sib->textContent ) );
			if ( $t !== '' && mb_strlen( $t ) <= 80 && stripos( $t, 'rights reserved' ) === false && strpos( $t, '©' ) === false ) { self::$bottom_tagline_dot = self::status_dot_html( $sib ); return $t; }
		}
		return '';
	}

	/** The status DOT of the last detected bottom-bar lockup (a kses-safe inline span, '' when none) — set by detect_footer_bottom_tagline. */
	private static $bottom_tagline_dot = '';

	/** A small painted empty leaf inside a status lockup ("● Node Connected": a `w-2 h-2 rounded-full bg-emerald-400` span before
	 *  the label) → an inline dot the label can carry (`<span style="…">` — hex fill, kses-safe), or ''. */
	private static function status_dot_html( $lockup ) {
		if ( ! ( $lockup instanceof DOMElement ) ) { return ''; }
		foreach ( $lockup->getElementsByTagName( '*' ) as $d ) {
			if ( $d->getElementsByTagName( '*' )->length || '' !== trim( (string) $d->textContent ) ) { continue; }
			$cs = (string) $d->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/background-color:\s*([^;]+)/i', $cs, $bm ) || preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent/i', $bm[1] ) ) { continue; }
			$h = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $hm ) ? (float) $hm[1] : 0;
			$w = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $cs, $wm ) ? (float) $wm[1] : $h;
			if ( $h <= 0 || $h > 16 || $w > 16 ) { continue; }
			$hex = self::color_to_hex( trim( $bm[1] ) ); if ( '' === $hex ) { continue; }
			$round = ( false !== strpos( self::cls( $d ), 'rounded-full' ) || preg_match( '/border-radius:\s*(?:9999px|50%)/i', $cs ) ) ? '50%' : '0';
			$gap = 8; if ( $d->parentNode instanceof DOMElement && preg_match( '/(?:^|;)\s*gap:\s*([0-9.]+)px/i', (string) $d->parentNode->getAttribute( 'data-sc-cs' ), $gm ) ) { $gap = (int) round( (float) $gm[1] ); }
			return '<span style="display:inline-block;width:' . $w . 'px;height:' . $h . 'px;border-radius:' . $round . ';background-color:' . $hex . ';margin-right:' . $gap . 'px;vertical-align:middle"></span>';
		}
		return '';
	}

	/**
	 * Map a social URL's host to a library icon id, or '' if not a known network.
	 *
	 * Uses Tabler's brand set, NOT Lucide: Lucide removed its brand/social
	 * icons, so 'lucide/twitter', 'lucide/facebook', 'lucide/github' (and 6
	 * more this map used) resolve to nothing and every converted site ended up
	 * with blank social icons. Tabler is bundled and still ships real brand
	 * glyphs for all of them — which also replaces the generic stand-ins this
	 * map fell back on (tiktok -> lucide/music, pinterest -> lucide/image,
	 * discord/whatsapp -> lucide/message-circle) with the actual logos.
	 */
	private static function social_lucide( $url ) {
		$host = strtolower( (string) parse_url( (string) $url, PHP_URL_HOST ) );
		$map  = array(
			'twitter'   => 'tabler/brand-twitter',  'x.com'      => 'tabler/brand-x',
			'facebook'  => 'tabler/brand-facebook', 'instagram'  => 'tabler/brand-instagram',
			'linkedin'  => 'tabler/brand-linkedin', 'youtube'    => 'tabler/brand-youtube',
			'github'    => 'tabler/brand-github',   'discord'    => 'tabler/brand-discord',
			'dribbble'  => 'tabler/brand-dribbble', 'twitch'     => 'tabler/brand-twitch',
			'tiktok'    => 'tabler/brand-tiktok',   'pinterest'  => 'tabler/brand-pinterest',
			'telegram'  => 'tabler/brand-telegram', 't.me'       => 'tabler/brand-telegram',
			'whatsapp'  => 'tabler/brand-whatsapp', 'slack'      => 'tabler/brand-slack',
			'mastodon'  => 'tabler/brand-mastodon',
		);
		foreach ( $map as $needle => $id ) { if ( $host !== '' && strpos( $host, $needle ) !== false ) { return $id; } }
		return '';
	}

	/**
	 * Network → Lucide-library icon id, for social detection by ICON (not just href). Keys are the network
	 * name as it appears in an icon class / aria-label (`lucide-facebook`, `fab fa-instagram`, `aria-label="Twitter"`).
	 */
	private static function social_network_map() {
		// Tabler brand glyphs — see social_lucide() for why not Lucide.
		return array(
			'facebook'  => 'tabler/brand-facebook',  'instagram' => 'tabler/brand-instagram',
			'twitter'   => 'tabler/brand-twitter',   'x-twitter' => 'tabler/brand-x',
			'youtube'   => 'tabler/brand-youtube',   'linkedin'  => 'tabler/brand-linkedin',
			'github'    => 'tabler/brand-github',    'tiktok'    => 'tabler/brand-tiktok',
			'dribbble'  => 'tabler/brand-dribbble',  'twitch'    => 'tabler/brand-twitch',
			'pinterest' => 'tabler/brand-pinterest', 'discord'   => 'tabler/brand-discord',
			'telegram'  => 'tabler/brand-telegram',  'whatsapp'  => 'tabler/brand-whatsapp',
			'slack'     => 'tabler/brand-slack',     'mastodon'  => 'tabler/brand-mastodon',
		);
	}

	/**
	 * Identify the social network of a link by its ICON — the source often uses a placeholder `href="#"`
	 * (so host-based detection misses it). Reads the network from the icon SVG/`<i>`/`<use>` class
	 * (`lucide-<net>`, `fa-<net>`/`fab fa-<net>`, `bi-<net>`, `icon-<net>`), the link's `aria-label`/`title`,
	 * then falls back to the href host. Returns array( 'key' => <net>, 'icon' => '<pack>/<name>' ) or null.
	 */
	private static function social_network_of( $a, $href ) {
		$map = self::social_network_map();
		// Haystack: the <a>'s own class/aria/title/icon + every descendant's class + icon-name attribute
		// (`icon="lucide:twitter"` / `data-lucide` / `<use href>`). The `icon=` attribute is how an iconify
		// `<Icon icon="lucide:twitter">` / `<iconify-icon>` carries the network — a rendered iconify <svg>
		// has NO "twitter" in its class, so without reading `icon=` the footer socials went undetected and
		// the theme's default profiles (Facebook…) stayed. `:` → `-` so the prefix match below fires.
		$icon_attr = function ( $el ) { $v = strtolower( trim( (string) $el->getAttribute( 'icon' ) ) ); return $v !== '' ? ' ' . str_replace( ':', '-', $v ) : ''; };
		$hay = ' ' . self::cls( $a ) . ' ' . strtolower( (string) $a->getAttribute( 'aria-label' ) )
			. ' ' . strtolower( (string) $a->getAttribute( 'title' ) ) . $icon_attr( $a ) . ' ';
		foreach ( $a->getElementsByTagName( '*' ) as $node ) {
			$hay .= ' ' . self::cls( $node ) . $icon_attr( $node );
			$dl = strtolower( trim( (string) $node->getAttribute( 'data-lucide' ) ) );
			if ( $dl !== '' ) { $hay .= ' lucide-' . $dl; }
			if ( strtolower( $node->tagName ) === 'use' ) { $hay .= ' ' . strtolower( (string) $node->getAttribute( 'href' ) ) . ' ' . strtolower( (string) $node->getAttribute( 'xlink:href' ) ); }
		}
		$hay = ' ' . preg_replace( '/\s+/', ' ', $hay ) . ' ';
		foreach ( $map as $key => $icon ) {
			$word = preg_quote( $key, '/' );
			// A network icon class/name prefix (lucide-/fa-/fab-/bi-/icon-/ion-/social-/simple-icons-/si-),
			// OR the network as a standalone word in a class/aria-label (only for names ≥4 chars, so a stray
			// "x" can't match).
			if ( preg_match( '/(?:lucide-|fa-|fab-|fa-brands.|bi-|icon-|ion-|social-|simple-icons-|si-)' . $word . '\b/', $hay )
				|| ( strlen( $key ) >= 4 && preg_match( '/\b' . $word . '\b/', $hay ) ) ) {
				$k = ( $key === 'x-twitter' ) ? 'twitter' : $key;
				return array( 'key' => $k, 'icon' => $icon );
			}
		}
		// Fallback: the href host (a real social URL).
		$h = self::social_lucide( $href );
		if ( $h !== '' ) {
			foreach ( $map as $key => $icon ) { if ( $icon === $h ) { return array( 'key' => ( $key === 'x-twitter' ? 'twitter' : $key ), 'icon' => $icon ); } }
			return array( 'key' => str_replace( 'lucide/', '', $h ), 'icon' => $h );
		}
		return null;
	}

	/**
	 * Footer social links → social_profiles [{ name, link, new_tab, icon }], deduped by network. Detects each
	 * link's network by its ICON (social_network_of), so placeholder `href="#"`/empty/missing hrefs still map
	 * (the golden fixture footer's `<a href="#"><svg class="lucide lucide-facebook">` pattern). The profile `link`
	 * is the real URL when present, else `#` — the theme's social element SKIPS an EMPTY link, so `#` keeps
	 * the icon rendered.
	 */
	/** A footer DISCLAIMER paragraph (small-text legal prose like "… is a marketplace, not a lender. …
	 *  Equal Housing Opportunity.") → its clean inline HTML, or ''. A `text-xs`-ish `<p>` of >=60 chars that
	 *  isn't the © line. Appended under the copyright so the legal notice isn't dropped. */
	private static function detect_footer_disclaimer( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		// the brand column's TAGLINE (the same small paragraph detect_footer_tagline puts under the logo) is not a disclaimer —
		// it was doubling into the copyright bar
		$tagline = trim( preg_replace( '/\s+/', ' ', (string) self::detect_footer_tagline( $html ) ) );
		foreach ( $footer->getElementsByTagName( 'p' ) as $p ) {
			$cls = ' ' . strtolower( self::cls( $p ) ) . ' ';
			if ( strpos( $cls, 'text-xs' ) === false && strpos( $cls, 'text-\[' ) === false ) { continue; }
			$t = trim( preg_replace( '/\s+/', ' ', self::text( $p ) ) );
			if ( mb_strlen( $t ) < 60 ) { continue; }
			if ( '' !== $tagline && $t === $tagline ) { continue; }
			if ( stripos( $t, 'all rights reserved' ) !== false ) { continue; } // the © line, not a disclaimer
			// …nor the SIGNUP's description: a small <p> in the column that holds the email field is the newsletter's copy — it
			// had doubled into the copyright bar (a real-site audit)
			$in_signup = false; for ( $q = $p->parentNode, $qi = 0; $q instanceof DOMElement && $q !== $footer && $qi < 3; $q = $q->parentNode, $qi++ ) { if ( $q->getElementsByTagName( 'input' )->length ) { $in_signup = true; break; } }
			if ( $in_signup ) { continue; }
			return '<p class="footer-disclaimer">' . self::clean_inline_html( $p ) . '</p>';
		}
		return '';
	}

	/** The footer BRAND column's contact block → HTML (an email `mailto` line + address/phone lines), or ''.
	 *  Anchored on a `mailto:` link; gathers its sibling icon+text rows (address, phone) from the same
	 *  container. Icons are dropped (lucide) but the content — email + "Headquartered in …" — is preserved. */
	private static function detect_footer_contact( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		$email = ''; $email_href = ''; $lines = array();
		foreach ( $footer->getElementsByTagName( 'a' ) as $a ) {
			$h = trim( (string) $a->getAttribute( 'href' ) );
			if ( 0 !== stripos( $h, 'mailto:' ) ) { continue; }
			$email = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $a ) ) );
			$email_href = $h;
			$cont = $a->parentNode;
			if ( $cont instanceof DOMElement ) {
				foreach ( self::el_children( $cont ) as $r ) {
					if ( $r === $a ) { continue; }
					if ( $r->getElementsByTagName( 'a' )->length > 0 ) { continue; } // a nav link, not a contact row
					$t = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $r ) ) );
					if ( $t !== '' && mb_strlen( $t ) <= 60 ) { $lines[] = $t; }
				}
			}
			break;
		}
		if ( '' === $email && ! $lines ) { return ''; }
		$out = '<p class="footer-contact">';
		if ( '' !== $email ) { $out .= '<a href="' . esc_url( $email_href ) . '">' . esc_html( $email ) . '</a>'; }
		foreach ( $lines as $ln ) { $out .= ( $out === '<p class="footer-contact">' ? '' : '<br>' ) . esc_html( $ln ); }
		return $out . '</p>';
	}

	private static function detect_footer_social( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return array(); }
		$out  = array();
		$seen = array();
		$rows = array(); // the parents of recognised social links — their OTHER icon-only links belong to the same row
		foreach ( $footer->getElementsByTagName( 'a' ) as $a ) {
			$href = trim( (string) $a->getAttribute( 'href' ) );
			$net  = self::social_network_of( $a, $href );
			if ( $net === null || isset( $seen[ $net['key'] ] ) ) { continue; }
			$seen[ $net['key'] ] = true;
			if ( $a->parentNode instanceof DOMElement ) { $rows[ spl_object_hash( $a->parentNode ) ] = $a->parentNode; }
			$link = preg_match( '~^https?://~i', $href ) ? $href : '#'; // real URL, else '#' (non-empty ⇒ renders)
			$out[] = array(
				'name'    => ucfirst( $net['key'] ),
				'link'    => $link,
				'new_tab' => 'yes',
				'icon'    => array( 'type' => 'svg', 'svg-source' => 'library', 'svg-id' => $net['icon'] ),
				'_el'     => $a,
			);
			if ( count( $out ) >= 8 ) { break; }
		}
		// The same icon row's OTHER icon-only links (a "terminal" / "cpu" glyph beside the GitHub mark — a network the library
		// doesn't name) keep their place as profiles with their own inline glyph, in DOM order; the row is what the source shows.
		if ( $out && $rows ) {
			$ordered = array();
			foreach ( $rows as $row ) {
				foreach ( self::el_children( $row ) as $a ) {
					if ( 'a' !== strtolower( $a->tagName ) || '' !== trim( self::text_no_icons( $a ) ) ) { continue; }
					$known = null; foreach ( $out as $o ) { if ( isset( $o['_el'] ) && $o['_el'] === $a ) { $known = $o; break; } }
					if ( $known ) { $ordered[] = $known; continue; }
					$svg = null; foreach ( $a->getElementsByTagName( 'svg' ) as $sv ) { $svg = $sv; break; }
					if ( ! $svg || ! $a->ownerDocument ) { continue; }
					$markup = self::strip_cs( (string) $a->ownerDocument->saveHTML( $svg ) );
					if ( '' === $markup || strlen( $markup ) > 8000 ) { continue; }
					$ico = ''; foreach ( $a->getElementsByTagName( 'iconify-icon' ) as $ii ) { $ico = (string) $ii->getAttribute( 'icon' ); break; }
					if ( '' === $ico ) { $ico = (string) $svg->getAttribute( 'data-sc-iconify' ); }
					$name = ucwords( trim( preg_replace( '/[-_]+/', ' ', preg_replace( '/^[a-z0-9]+:|-(?:light|bold|fill|thin|regular|duotone|outline)$/', '', $ico ) ) ) );
					if ( '' === $name ) { $name = 'Link ' . ( count( $ordered ) + 1 ); }
					$href = trim( (string) $a->getAttribute( 'href' ) );
					$ordered[] = array( 'name' => $name, 'link' => preg_match( '~^https?://~i', $href ) ? $href : '#', 'new_tab' => 'yes', 'icon' => array( 'type' => 'svg', 'svg-source' => 'inline', 'markup' => $markup, 'svg-id' => '' ) );
					if ( count( $ordered ) >= 8 ) { break 2; }
				}
			}
			foreach ( $out as $o ) { $found = false; foreach ( $ordered as $q ) { if ( isset( $q['_el'] ) && isset( $o['_el'] ) && $q['_el'] === $o['_el'] ) { $found = true; break; } } if ( ! $found ) { $ordered[] = $o; } }
			$out = $ordered;
		}
		// NO named network at all, but an ICON-ONLY LINK ROW (≥ 2 glyph links side by side — a terminal / cpu / activity
		// trio under an "Interface" label): the row IS the source's social slot. Its links become profiles with their own
		// inline glyphs, in order — never the theme's default Facebook / X / Instagram set, which the source never showed.
		if ( ! $out ) {
			$row = self::footer_icon_link_row( $footer );
			if ( $row ) {
				foreach ( self::el_children( $row ) as $a ) {
					if ( 'a' !== strtolower( $a->tagName ) || '' !== trim( self::text_no_icons( $a ) ) ) { continue; }
					$svg = null; foreach ( $a->getElementsByTagName( 'svg' ) as $sv ) { $svg = $sv; break; }
					if ( ! $svg || ! $a->ownerDocument ) { continue; }
					$markup = self::strip_cs( (string) $a->ownerDocument->saveHTML( $svg ) );
					if ( '' === $markup || strlen( $markup ) > 8000 ) { continue; }
					$ico = ''; foreach ( $a->getElementsByTagName( 'iconify-icon' ) as $ii ) { $ico = (string) $ii->getAttribute( 'icon' ); break; }
					if ( '' === $ico ) { $ico = (string) $svg->getAttribute( 'data-sc-iconify' ); }
					$name = ucwords( trim( preg_replace( '/[-_]+/', ' ', preg_replace( '/^[a-z0-9]+:|-(?:light|bold|fill|thin|regular|duotone|outline)$/', '', $ico ) ) ) );
					if ( '' === $name ) { $name = 'Link ' . ( count( $out ) + 1 ); }
					$href = trim( (string) $a->getAttribute( 'href' ) );
					$out[] = array( 'name' => $name, 'link' => preg_match( '~^https?://~i', $href ) ? $href : '#', 'new_tab' => 'yes', 'icon' => array( 'type' => 'svg', 'svg-source' => 'inline', 'markup' => $markup, 'svg-id' => '' ) );
					if ( count( $out ) >= 8 ) { break; }
				}
			}
		}
		foreach ( $out as &$o ) { unset( $o['_el'] ); } unset( $o );
		return $out;
	}

	/** The footer's icon-only link ROW (a parent whose element children are ≥ 2 glyph-only `<a>`s), or null. */
	private static function footer_icon_link_row( $footer ) {
		if ( ! ( $footer instanceof DOMElement ) ) { return null; }
		$parents = array();
		foreach ( $footer->getElementsByTagName( 'a' ) as $a ) {
			if ( '' !== trim( self::text_no_icons( $a ) ) ) { continue; }
			if ( ! $a->getElementsByTagName( 'svg' )->length && ! $a->getElementsByTagName( 'iconify-icon' )->length && ! $a->getElementsByTagName( 'i' )->length ) { continue; }
			$par = $a->parentNode; if ( ! ( $par instanceof DOMElement ) ) { continue; }
			$k = spl_object_hash( $par ); if ( ! isset( $parents[ $k ] ) ) { $parents[ $k ] = array( 'el' => $par, 'n' => 0 ); } $parents[ $k ]['n']++;
		}
		foreach ( $parents as $pinfo ) {
			if ( $pinfo['n'] < 2 ) { continue; }
			$kids = self::el_children( $pinfo['el'] ); $links = 0;
			foreach ( $kids as $k ) { if ( 'a' === strtolower( $k->tagName ) ) { $links++; } }
			if ( $links >= 2 && $links === count( $kids ) ) { return $pinfo['el']; }
		}
		return null;
	}

	/**
	 * The footer social icons' LOOK -> the theme's `social_style` (Theme Settings -> Social). The source
	 * usually wraps each social <a> in a shaped chip (`w-10 h-10 rounded-full bg-white/10 hover:bg-primary`);
	 * without this the converter set only the profile LIST and left the style at the default `bare`, dropping
	 * the circular chip + fill + hover the source clearly had. Reads the FIRST social chip: shape (rounded-full
	 * -> circle, +border -> circle-outline, rounded-* -> rounded, else square), diameter (`w-N`/computed),
	 * gap (container `gap-N`/computed), chip background + hover background (resolved via the source's semantic
	 * colours), and a transform hover -> lift/scale. Returns the FLAT `social_style` values, or empty for a
	 * genuinely bare source. Colour option values are plain strings (color-picker).
	 */
	private static function detect_footer_social_style( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return array(); }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return array(); }
		$chip = null;
		foreach ( $footer->getElementsByTagName( 'a' ) as $a ) {
			if ( self::social_network_of( $a, (string) $a->getAttribute( 'href' ) ) !== null ) { $chip = $a; break; }
		}
		if ( ! ( $chip instanceof DOMElement ) ) { // no named network: the icon-only link row's first link is the chip (detect_footer_social's fallback)
			$row = self::footer_icon_link_row( $footer );
			if ( $row ) { foreach ( self::el_children( $row ) as $k ) { if ( 'a' === strtolower( $k->tagName ) ) { $chip = $k; break; } } }
		}
		if ( ! ( $chip instanceof DOMElement ) ) { return array(); }

		$cls   = ' ' . strtolower( self::cls( $chip ) ) . ' ';
		$props = array();
		foreach ( explode( ';', (string) $chip->getAttribute( 'data-sc-cs' ) ) as $d ) {
			$cp = strpos( $d, ':' ); if ( $cp === false ) { continue; }
			$props[ strtolower( trim( substr( $d, 0, $cp ) ) ) ] = trim( substr( $d, $cp + 1 ) );
		}
		$sem = method_exists( 'FW_Site_Converter_Tailwind', 'extract_semantic_colors' ) ? FW_Site_Converter_Tailwind::extract_semantic_colors( (string) $html ) : array();
		$norm = function ( $c ) {
			$c = strtolower( trim( (string) $c ) );
			if ( $c === '' || $c === 'transparent' || $c === 'none' ) { return ''; }
			if ( preg_match( '/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)(?:[,\s\/]+([0-9.]+))?/', $c, $m ) ) {
				$a = ( isset( $m[4] ) && $m[4] !== '' ) ? (float) $m[4] : 1.0;
				if ( $a <= 0.02 ) { return ''; }
				return $a < 1 ? "rgba({$m[1]}, {$m[2]}, {$m[3]}, {$a})" : "rgb({$m[1]}, {$m[2]}, {$m[3]})";
			}
