		}
		if ( preg_match( '/\shover:scale-\d/', $cls ) )          { $out['social_icon_hover_fx'] = 'scale'; }
		elseif ( preg_match( '/\shover:-?translate-y/', $cls ) ) { $out['social_icon_hover_fx'] = 'lift'; }

		return $out;
	}


	/**
	 * A BRAND-AREA newsletter signup (a "Stay Connected" email form that rides with the brand block in the
	 * footer's top row, NOT as a grid column). Its label is frequently a styled `<p>` / `<span>` — not an
	 * h-tag — so `detect_footer_columns` (heading-driven) misses it and the form is dropped. This finds the
	 * footer's email `<input>`, then its label (nearest short heading OR styled `<p>` before the form), an
	 * optional description, the placeholder, and the submit button label. Returns { title, tagline,
	 * placeholder, button } or array() when the footer has no signup form.
	 *
	 * @param string $html
	 * @return array
	 */
	/** The brand column's status chip: a short (≤ 40 chars) skinned inline pill (fill / border / radius, padding) holding no link
	 *  and no input, in the footer's first column; optionally a small round dot before the label. Returns the chip as inline
	 *  HTML wearing its measured skin, or ''. */
	private static function detect_footer_brand_chip( $html ) {
		$dom = self::load_dom( $html ); if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 ); if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		foreach ( $footer->getElementsByTagName( 'div' ) as $d ) {
			$cs = (string) $d->getAttribute( 'data-sc-cs' ); $cls = ' ' . strtolower( self::cls( $d ) ) . ' ';
			if ( ! preg_match( '/(?:^|;)\s*display:\s*inline-flex/i', $cs ) && strpos( $cls, ' inline-flex ' ) === false ) { continue; }
			if ( $d->getElementsByTagName( 'a' )->length || $d->getElementsByTagName( 'input' )->length || $d->getElementsByTagName( 'button' )->length ) { continue; }
			$t = trim( preg_replace( '/\s+/u', ' ', self::text_no_icons( $d ) ) );
			if ( '' === $t || mb_strlen( $t ) > 40 ) { continue; }
			$painted = preg_match( '/(?:^|;)\s*background-color:\s*(?!rgba\([^)]*,\s*0\s*\)|transparent)[^;]+/i', $cs ) || preg_match( '/(?:^|;)\s*border-top-width:\s*[1-9]/i', $cs );
			if ( ! $painted ) { continue; }
			$d0 = array(); foreach ( array( 'background-color', 'border-top-width', 'border-top-color', 'border-radius', 'padding', 'font-size', 'color', 'letter-spacing', 'text-transform', 'gap' ) as $k0 ) { $v0 = trim( (string) self::sc_css( $d, $k0 ) ); if ( '' !== $v0 ) { $d0[ $k0 ] = $v0; } }
			$st = array( 'display:inline-flex', 'align-items:center' );
			if ( ! empty( $d0['gap'] ) ) { $st[] = 'gap:' . $d0['gap']; }
			foreach ( array( 'background-color', 'border-radius', 'padding', 'font-size', 'color', 'letter-spacing', 'text-transform' ) as $k ) { if ( ! empty( $d0[ $k ] ) && preg_match( '/^[a-z0-9()%.,\s#\/-]+$/i', $d0[ $k ] ) ) { $st[] = $k . ':' . $d0[ $k ]; } }
			if ( ! empty( $d0['border-top-width'] ) && ! empty( $d0['border-top-color'] ) ) { $st[] = 'border:' . $d0['border-top-width'] . ' solid ' . $d0['border-top-color']; }
			$dot = '';
			foreach ( self::el_children( $d ) as $k ) {
				$kcs = (string) $k->getAttribute( 'data-sc-cs' );
				if ( '' === trim( self::text( $k ) ) && preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $kcs, $wm ) && (float) $wm[1] <= 16 && preg_match( '/(?:^|;)\s*background-color:\s*([^;]+)/i', $kcs, $bm ) ) {
					$dh = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $kcs, $hm ) ? (float) $hm[1] : (float) $wm[1];
					$dot = 'display:inline-block;width:' . (float) $wm[1] . 'px;height:' . $dh . 'px;border-radius:9999px;background:' . trim( $bm[1] ) . ';flex:0 0 auto';
					break;
				}
			}
			self::$footer_chip_css = '.footer .footer-chip{margin:0;}.footer .footer-chip__pill{' . implode( ';', $st ) . ';}' . ( '' !== $dot ? '.footer .footer-chip__dot{' . $dot . '}' : '' );
			return '<p class="footer-chip"><span class="footer-chip__pill">' . ( '' !== $dot ? '<span class="footer-chip__dot"></span>' : '' ) . esc_html( $t ) . '</span></p>';
		}
		return '';
	}
	private static $footer_chip_css = '';

	/** The footer signup's MEASURED skin (the field's fill / border / radius / type / ink, the submit's fill / ink / radius) scoped to
	 *  the footer newsletter element — the widget's own look (a white field, an orange button) replaced the source's (a real-site
	 *  audit). Whitelisted values only. */
	private static function footer_newsletter_css( $html ) {
		$nl = self::detect_footer_newsletter( $html ); if ( ! $nl ) { $nl = array(); }
		$ok = function ( $v ) { return '' !== (string) $v && preg_match( '/^[a-z0-9()%.,\s#\/\'"-]+$/i', (string) $v ); };
		$pick = function ( $cs, $keys ) use ( $ok ) { $o = array(); foreach ( $keys as $k ) { if ( preg_match( '/(?:^|;)\s*' . preg_quote( $k, '/' ) . ':\s*([^;]+)/i', (string) $cs, $m ) && $ok( trim( $m[1] ) ) ) { $o[ $k ] = trim( $m[1] ); } } return $o; };
		$css = '';
		$i = $pick( (string) ( $nl['inputCs'] ?? '' ), array( 'background-color', 'border-top-width', 'border-top-color', 'border-radius', 'font-size', 'color', 'padding', 'font-family', 'height' ) );
		if ( $i ) {
			$d = array();
			if ( isset( $i['background-color'] ) ) { $d[] = 'background:' . $i['background-color'] . ' !important'; }
			if ( isset( $i['border-top-width'], $i['border-top-color'] ) && '0px' !== $i['border-top-width'] ) { $d[] = 'border:' . $i['border-top-width'] . ' solid ' . $i['border-top-color'] . ' !important'; }
			foreach ( array( 'border-radius', 'font-size', 'color', 'padding', 'font-family', 'height' ) as $k ) { if ( isset( $i[ $k ] ) ) { $d[] = $k . ':' . $i[ $k ] . ' !important'; } }
			if ( $d ) { $css .= '.footer .fw-nl__input{' . implode( ';', $d ) . ';}'; }
			if ( isset( $i['color'] ) ) { $css .= '.footer .fw-nl__input::placeholder{color:' . $i['color'] . ';opacity:.4;}'; }
		}
		$b = $pick( (string) ( $nl['buttonCs'] ?? '' ), array( 'background-color', 'color', 'border-radius', 'font-size', 'padding' ) );
		if ( $b ) {
			$d = array(); foreach ( array( 'background-color' => 'background', 'color' => 'color', 'border-radius' => 'border-radius', 'font-size' => 'font-size', 'padding' => 'padding' ) as $k => $prop ) { if ( isset( $b[ $k ] ) ) { $d[] = $prop . ':' . $b[ $k ] . ' !important'; } }
			if ( $d ) { $css .= '.footer .fw-nl__btn{' . implode( ';', $d ) . ';border:0 !important;}'; }
		}
		// the newsletter's DESCRIPTION line keeps the source's size / ink (the widget's body size is not the footer's 12px muted copy)
		if ( ! empty( $nl['descCs'] ) ) { $dd = $pick( (string) $nl['descCs'], array( 'font-size', 'color', 'line-height', 'font-weight' ) ); $d = array(); foreach ( $dd as $k => $v ) { $d[] = $k . ':' . $v . ' !important'; } if ( $d ) { $css .= '.footer .fw-nl__desc,.footer .fw-nl p{' . implode( ';', $d ) . ';}'; } }
		self::detect_footer_brand_chip( $html ); $css .= self::$footer_chip_css; // (the chip's skin — read here: the misc css is assembled before the brand column)
		return '' !== $css ? "\n/* Source footer signup skin */\n" . $css : '';
	}

	private static function detect_footer_newsletter( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return array(); }
		// The signup input: type=email, or a text input whose placeholder mentions an email.
		$input = null;
		foreach ( $footer->getElementsByTagName( 'input' ) as $inp ) {
			$t  = strtolower( trim( (string) $inp->getAttribute( 'type' ) ) );
			$ph = strtolower( (string) $inp->getAttribute( 'placeholder' ) );
			if ( $t === 'email' || ( in_array( $t, array( '', 'text' ), true ) && strpos( $ph, 'email' ) !== false ) ) { $input = $inp; break; }
		}
		if ( ! ( $input instanceof DOMElement ) ) { return array(); }
		$placeholder = trim( (string) $input->getAttribute( 'placeholder' ) );
		// Walk up to the enclosing <form>, then its container — the newsletter block scope.
		$form = null; $p = $input->parentNode;
		for ( $d = 0; $d < 5 && $p instanceof DOMElement; $d++ ) { if ( strtolower( $p->tagName ) === 'form' ) { $form = $p; break; } $p = $p->parentNode; }
		$scope = ( $form && $form->parentNode instanceof DOMElement ) ? $form->parentNode : ( $form ? $form : $footer );
		// Title = a short label in the block: an h-tag first, else a short (≤4-word) <p>/<span> that ISN'T the
		// description and precedes the input (the "Stay Connected" pattern). Tagline = a longer descriptive <p>.
		$title = ''; $tagline = '';
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $ht ) {
			foreach ( $scope->getElementsByTagName( $ht ) as $hh ) { $t = trim( preg_replace( '/\s+/', ' ', (string) $hh->textContent ) ); if ( $t !== '' && str_word_count( $t ) <= 5 ) { $title = $t; break 2; } }
		}
		foreach ( $scope->getElementsByTagName( 'p' ) as $pp ) {
			$t = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $pp ) ) );
			if ( $t === '' ) { continue; }
			$wc = str_word_count( $t );
			if ( $title === '' && $wc <= 4 ) { $title = $t; }        // a short styled <p> label (Stay Connected)
			elseif ( $tagline === '' && $wc >= 4 && $t !== $title ) { $tagline = $t; } // a real description line
		}
		// Submit button label (a real word; an icon-only submit → '' so the emit falls back to "Subscribe").
		$button = '';
		$bscope = $form ? $form : $scope;
		$icon_only = false; $btn_el = null;
		foreach ( $bscope->getElementsByTagName( 'button' ) as $b ) { if ( ! $btn_el ) { $btn_el = $b; } $bt = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $b ) ) ); if ( $bt !== '' ) { $button = $bt; $btn_el = $b; break; } }
		if ( '' === $button && $btn_el instanceof DOMElement && ( $btn_el->getElementsByTagName( 'svg' )->length || $btn_el->getElementsByTagName( 'i' )->length || $btn_el->getElementsByTagName( 'iconify-icon' )->length ) ) { $icon_only = true; }
		$desc_cs = ''; foreach ( $scope->getElementsByTagName( 'p' ) as $pp ) { if ( trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $pp ) ) ) === $tagline ) { $desc_cs = (string) $pp->getAttribute( 'data-sc-cs' ); break; } }
		return array( 'title' => $title, 'tagline' => $tagline, 'placeholder' => $placeholder, 'button' => $button, 'iconOnly' => $icon_only, 'descCs' => $desc_cs,
			'inputCs' => (string) $input->getAttribute( 'data-sc-cs' ), 'buttonCs' => $btn_el instanceof DOMElement ? (string) $btn_el->getAttribute( 'data-sc-cs' ) : '' );
	}

	/** The <footer> element for a captured page, or null. */
	private static function footer_root_el( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return null; }
		return $dom->getElementsByTagName( 'footer' )->item( 0 );
	}

	/** A band whose text is a copyright / legal strip (© / "rights reserved" / a row of Privacy-Terms links). */
	/**
	 * Is this footer band a genuine MULTI-COLUMN row — a flex/grid container with >=2 substantial cells
	 * (e.g. a pre-footer whose brand and newsletter sit in separate columns)? Used to decide whether the
	 * brand band should split into brand | newsletter columns rather than merge them into one.
	 */
	private static function footer_band_is_multicol( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return false; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return false; }
		foreach ( $footer->getElementsByTagName( 'div' ) as $d ) {
			$cls = self::cls( $d );
			if ( strpos( $cls, 'flex' ) === false && strpos( $cls, 'grid' ) === false ) { continue; }
			$subs = 0;
			foreach ( self::el_children( $d ) as $k ) { if ( self::is_substantial_cell( $k ) ) { $subs++; } }
			if ( $subs >= 2 ) { return true; }
		}
		return false;
	}

	private static function band_is_copyright( $el, $is_last = false ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$t = strtolower( trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) ) );
		if ( $t === '' ) { return false; }
		if ( $is_last && self::band_is_label_bar( $el ) ) { return true; }
		if ( strpos( $t, '©' ) !== false || strpos( $t, '&copy;' ) !== false || strpos( $t, 'copyright' ) !== false
			|| strpos( $t, 'rights reserved' ) !== false || strpos( $t, 'all rights' ) !== false ) { return true; }
		// Or a short strip that is predominantly legal links (Privacy / Terms / Cookies) and little else —
		// but NOT a genuine multi-column NAV grid. A real footer link grid can legitimately have a "Legal"
		// column with a Privacy link; it is distinguished by carrying COLUMN HEADINGS (h1–h6) and/or being a
		// ≥2-column grid. Only a flat, heading-less, single-row strip is the copyright/legal bar. (Without
		// this guard a 4-column Shop|About|Help|Legal grid was mis-flagged copyright, dropped from the
		// content bands, and the whole footer collapsed to a single mis-split bar.)
		if ( preg_match( '/privacy|terms|cookie|imprint|sitemap/i', $t ) && str_word_count( $t ) <= 16 ) {
			$has_heading = false;
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) {
				if ( $el->getElementsByTagName( $h )->length > 0 ) { $has_heading = true; break; }
			}
			if ( ! $has_heading && self::band_column_count( $el ) < 2 ) { return true; }
		}
		return false;
	}

	/**
	 * A footer BOTTOM BAR without a © line: a flex row of ≥ 2 short (≤ 8 words), small (≤ 14px) text cells and
	 * nothing else — "Studio name · palette · site claim". The theme's Copyright bar IS that bottom bar (its
	 * columns auto-align left / centre / right), so the band routes there instead of being dropped.
	 * @return array|false the cell texts, or false
	 */
	private static function band_is_label_bar( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'img', 'svg', 'form', 'input', 'ul' ) as $tag ) { if ( $el->getElementsByTagName( $tag )->length ) { return false; } }
		$disp = strtolower( self::sc_css( $el, 'display' ) );
		if ( $disp !== 'flex' && $disp !== 'grid' && $disp !== 'inline-flex' ) { return false; }
		$cells = array();
		foreach ( self::el_children( $el ) as $k ) {
			$t = trim( preg_replace( '/\s+/', ' ', self::text( $k ) ) );
			if ( $t === '' ) { continue; }
			if ( str_word_count( preg_replace( '/[^a-z0-9 ]/i', ' ', $t ) ) > 8 || mb_strlen( $t ) > 60 ) { return false; }
			$fs = self::sc_css( $k, 'font-size' ); if ( $fs === '' ) { $fs = self::sc_css( $el, 'font-size' ); }
			if ( preg_match( '/^([0-9.]+)px$/', $fs, $m ) && (float) $m[1] > 14 ) { return false; }
			$cells[] = $t;
		}
		return count( $cells ) >= 2 ? $cells : false;
	}

	/** Rough column count of a band = the widest grid/flex row's element-child count (for main-anchor ranking). */
	private static function band_column_count( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return 0; }
		$best = 0;
		foreach ( $el->getElementsByTagName( 'div' ) as $d ) {
			$c = ' ' . strtolower( self::cls( $d ) ) . ' ';
			if ( strpos( $c, 'grid' ) === false && strpos( $c, 'flex' ) === false ) { continue; }
			$n = 0;
			foreach ( self::el_children( $d ) as $k ) { if ( trim( $k->textContent ) !== '' || $k->getElementsByTagName( 'img' )->length ) { $n++; } }
			if ( $n > $best ) { $best = $n; }
		}
		// Fall back to heading count (each footer column is a heading-led block).
		if ( $best === 0 ) { foreach ( array( 'h2','h3','h4','h5','h6' ) as $h ) { $best += $el->getElementsByTagName( $h )->length; } }
		return $best;
	}

	/**
	 * Segment a <footer> into its ordered content BANDS (full-width horizontal strips) so each can map to a
	 * DISTINCT theme footer bar (Pre / Main / Post / Copyright) per footer.md. CONSERVATIVE: dives through
	 * single-child wrappers to the band container, then treats its content children as bands ONLY when there
	 * is a STRONG structural signal that they are genuinely separate strips (a border divider between them, or
	 * a copyright strip present). Otherwise returns [] so the caller keeps today's exact single-bar behavior.
	 *
	 * @param string $html
	 * @return array[] ordered bands: [{ html:'<footer>…band…</footer>', is_copyright:bool, ncols:int }] or []
	 */
	private static function footer_bands_html( $html ) {
		$footer = self::footer_root_el( $html );
		if ( ! $footer ) { return array(); }
		$node = $footer;
		for ( $d = 0; $d < 4; $d++ ) {
			$kids = self::el_children( $node );
			if ( count( $kids ) >= 2 ) { break; }
			if ( count( $kids ) === 1 ) { $node = $kids[0]; continue; }
			return array();
		}
		$rows = array();
		foreach ( self::el_children( $node ) as $k ) {
			if ( trim( $k->textContent ) !== '' || $k->getElementsByTagName( 'img' )->length || $k->getElementsByTagName( 'svg' )->length ) { $rows[] = $k; }
		}
		if ( count( $rows ) < 2 ) { return array(); }
		// STRONG signal gate: a border divider on some row, a copyright strip, OR a row with its OWN opaque
		// background fill that differs from the footer's (a coloured CTA band — the burger-source's red
		// "Craving a Juicy Burger?" pre-footer sits in a `bg-primary` div above the white link grid). Without a
		// strong signal, treat the footer as one band (don't split a normal single-row footer into false strips).
		$footer_bg = self::color_to_hex( (string) self::sc_css( $footer, 'background-color' ) );
		$is_filled_band = function ( $r ) use ( $footer_bg ) {
			$bg = (string) self::sc_css( $r, 'background-color' );
			if ( $bg === '' || stripos( $bg, 'transparent' ) !== false || preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) { return false; }
			$hex = self::color_to_hex( $bg );
			return $hex !== '' && strcasecmp( $hex, (string) $footer_bg ) !== 0;
		};
		$strong = false;
		foreach ( $rows as $r ) {
			$c = ' ' . strtolower( self::cls( $r ) ) . ' ';
			if ( strpos( $c, 'border-t' ) !== false || strpos( $c, 'border-b' ) !== false ) { $strong = true; break; }
			if ( self::band_is_copyright( $r, $r === end( $rows ) ) ) { $strong = true; break; }
			if ( $is_filled_band( $r ) ) { $strong = true; break; }
			// A computed top hairline on a later row (border-top:1px solid rgba(...) with no border-t class) is
			// the same divider signal as the utility class.
			$bw = self::sc_css( $r, 'border-top-width' ); $bs = self::sc_css( $r, 'border-top-style' ); $bc = self::sc_css( $r, 'border-top-color' );
			if ( $r !== reset( $rows ) && $bw !== '' && (float) $bw > 0 && $bs !== '' && $bs !== 'none' && $bc !== '' && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bc ) ) { $strong = true; break; }
		}
		if ( ! $strong ) { return array(); }
		$doc  = $footer->ownerDocument;
		$fcls = self::cls( $footer );
		$out  = array();
		foreach ( $rows as $r ) {
			$inner = $doc ? (string) $doc->saveHTML( $r ) : '';
			if ( trim( $inner ) === '' ) { continue; }
			$out[] = array(
				'html'         => '<footer class="' . esc_attr( $fcls ) . '">' . $inner . '</footer>',
				'is_copyright' => self::band_is_copyright( $r, $r === end( $rows ) ),
				'ncols'        => self::band_column_count( $r ),
				// The band's own custom-styling fields (opaque background + borders) so a coloured band (the red
				// CTA) can carry its fill onto its Pre/Post bar. Prefix is fixed up per-bar by the router.
				'el'           => $r,
			);
		}
		return count( $out ) >= 2 ? $out : array();
	}

	/**
	 * Split a leading FILLED CTA band out of the footer. A footer's first band-level child can be a coloured
	 * call-to-action (an opaque fill different from the footer's own bg) holding a lead heading + a button —
	 * the burger-source's red "Craving a Juicy Burger? … BOOK A TABLE" pre-footer, which lives INSIDE `<footer>`
	 * above the white link grid. Left in place it renders white-on-white in the main footer's brand column (its
	 * heading/button are white, designed for the red band) and its subtitle leaks in as the brand tagline. This
	 * lifts that band OUT so it becomes its own Pre-Footer bar (with its fill), and returns the REST of the page
	 * html (CTA removed) for the normal footer detection. Returns null when there's no such band.
	 *
	 * @param string $html full page html
	 * @return array|null { cta: synthetic-footer html of the band, bg: pre_footer custom fields, rest: page html w/o the band }
	 */
	private static function footer_split_cta( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return null; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return null; }
		$node = $footer;
		for ( $d = 0; $d < 4; $d++ ) {
			$kids = self::el_children( $node );
			if ( count( $kids ) >= 2 ) { break; }
			if ( count( $kids ) === 1 ) { $node = $kids[0]; continue; }
			return null;
		}
		$rows = self::el_children( $node );
		if ( count( $rows ) < 2 ) { return null; }
		$footer_bg = self::color_to_hex( (string) self::sc_css( $footer, 'background-color' ) );
		$fcls      = self::cls( $footer );
		foreach ( $rows as $r ) {
			$bg = (string) self::sc_css( $r, 'background-color' );
			if ( $bg === '' || stripos( $bg, 'transparent' ) !== false || preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) { continue; }
			$hex = self::color_to_hex( $bg );
			if ( $hex === '' || strcasecmp( $hex, (string) $footer_bg ) === 0 ) { continue; }
			// A filled band qualifies as a CTA only when it reads as a lead-heading lockup (heading + button) —
			// not just any coloured strip (a solid copyright bar, a divider).
			$syn = '<footer class="' . esc_attr( $fcls ) . '">' . $dom->saveHTML( $r ) . '</footer>';
			if ( self::detect_footer_lead_heading( $syn ) === '' ) { continue; }
			$bgfields = self::detect_band_custom_fields( $r, 'pre_footer' ); // read fill BEFORE detaching
			if ( $r->parentNode ) { $r->parentNode->removeChild( $r ); }
			return array( 'cta' => $syn, 'bg' => $bgfields, 'rest' => (string) $dom->saveHTML() );
		}
		return null;
	}

	/**
	 * One detected footer column-group → the native element list for that column: a CONTACT group → heading +
	 * `icon_text` rows; a NEWSLETTER group → the `newsletter` element; a NAV/TEXT group → heading + link/item
	 * list. Factored out of the footer-emit loop so ALL footer bars (pre/main/post) build columns identically.
	 *
	 * @param array $group { title, tag, links, items, kind, rows, newsletter }
	 * @return array list of element_type wrappers
	 */
	/** H10 — stamp each element in a footer column with its responsive `visibility` (from the source column's
	 *  Tailwind display classes). No-op when the column is visible everywhere, so it only ever ADDS a signal. */
	private static function attach_visibility( array $els, $cls ) {
		$vis = self::responsive_hide_visibility( (string) $cls );
		if ( ! $vis ) { return $els; }
		foreach ( $els as &$el ) { if ( is_array( $el ) && isset( $el['element_type'] ) ) { $el['visibility'] = $vis; } }
		unset( $el );
		return $els;
	}

	/**
	 * A footer's links when it has no COLUMN structure at all — a flat row. Skips icon-only/social
	 * anchors (no visible text) and anything that reads as a copyright line, and de-dupes by label.
	 *
	 * @param string $html footer-scoped markup
	 * @return array<int,array{label:string,url:string}>
	 */
	/** Side channel of footer_flat_links: { row, gap, justify, skin } of the links' container / first link. */
	private static $flat_links_meta = array();

	/** Scoped CSS that lays the flat-link column out like the source (a horizontal, end-justified row of pill links)
	 *  — '' when the source stacks them. Targets the theme's footer list, which only the flat fallback fills. */
	private static function footer_flat_links_css() {
		$m = self::$flat_links_meta;
		if ( empty( $m ) || empty( $m['row'] ) ) { return ''; }
		$d = array( 'display:flex', 'flex-wrap:wrap', 'list-style:none', 'padding:0', 'margin:0', 'align-items:center' );
		if ( preg_match( '/^([0-9.]+)px/', (string) $m['gap'], $gm ) ) { $d[] = 'gap:' . (int) round( (float) $gm[1] ) . 'px'; }
		$jmap = array( 'flex-end' => 'flex-end', 'end' => 'flex-end', 'center' => 'center', 'space-between' => 'space-between', 'flex-start' => 'flex-start' );
		if ( isset( $jmap[ (string) $m['justify'] ] ) ) { $d[] = 'justify-content:' . $jmap[ (string) $m['justify'] ]; }
		$css = "\n/* Source footer: a horizontal row of links */\n.footer-column ul.footer-links-list{" . implode( ';', $d ) . ";}\n.footer-column ul.footer-links-list > li{margin:0;}";
		if ( '' !== (string) $m['skin'] ) { $css .= "\n.footer-column ul.footer-links-list > li > .list-item{display:inline-block;" . $m['skin'] . ";}"; }
		return $css;
	}

	private static function footer_flat_links( $html ) {
		$out = array();
		if ( ! is_string( $html ) || '' === trim( $html ) ) { return $out; }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		// SCOPE to the footer. `$route_html` carries the whole routed page, so collecting anchors from the
		// document pulled the HEADER nav in ("Telemetry / Biome Sync / …") and the footer rendered the
		// wrong navigation — worse than emitting nothing. Narrow to <footer>, else a footer-classed
		// wrapper, and only fall back to the document when neither exists.
		$scope = null;
		$fts = $dom->getElementsByTagName( 'footer' );
		if ( $fts->length ) { $scope = $fts->item( $fts->length - 1 ); }
		if ( ! $scope ) {
			foreach ( $dom->getElementsByTagName( '*' ) as $e ) {
				if ( preg_match( '/\b(footer|colophon|site-info)\b/i', self::cls( $e ) ) ) { $scope = $e; }
			}
		}
		if ( ! $scope ) { $scope = $dom; }
		$seen = array();
		self::$flat_links_meta = array();
		foreach ( $scope->getElementsByTagName( 'a' ) as $a ) {
			$label = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $a ) ) );
			if ( '' === $label || mb_strlen( $label ) > 40 ) { continue; }
			if ( preg_match( '/(©|copyright|all rights reserved)/i', $label ) ) { continue; }
			$key = mb_strtolower( $label );
			if ( isset( $seen[ $key ] ) ) { continue; }
			$seen[ $key ] = 1;
			// The FIRST link's container layout + the link's own pill skin (a footer's `flex gap-14 justify-end` row of
			// rounded, tinted links): the column's List Items otherwise stack vertically in the theme's default list.
			if ( empty( self::$flat_links_meta ) && $a->parentNode instanceof DOMElement ) {
				$pcs = (string) $a->parentNode->getAttribute( 'data-sc-cs' );
				$g = function ( $cs, $pr ) { return preg_match( '/(?:^|;)\s*' . preg_quote( $pr, '/' ) . ':\s*([^;]+)/i', $cs, $m ) ? trim( $m[1] ) : ''; };
				$row = preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $pcs ) && ! preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $pcs );
				$acs = (string) $a->getAttribute( 'data-sc-cs' ); $skin = array();
				foreach ( array( 'background-color', 'padding', 'border-radius', 'font-size', 'letter-spacing', 'text-transform', 'line-height' ) as $pr ) {
					$v = $g( $acs, $pr );
					if ( '' === $v || 'none' === $v || '0px' === $v || 'normal' === $v || preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent/i', $v ) || ! preg_match( '/^[a-z0-9(),.\s#%-]+$/i', $v ) ) { continue; }
					$skin[] = $pr . ':' . $v;
				}
				$bw = $g( $acs, 'border-top-width' ); $bc = $g( $acs, 'border-top-color' );
				if ( preg_match( '/^[0-9.]+px$/', $bw ) && '0px' !== $bw && '' !== $bc && preg_match( '/^[a-z0-9(),.\s#%]+$/i', $bc ) ) { $skin[] = 'border:' . $bw . ' solid ' . $bc; }
				self::$flat_links_meta = array( 'row' => $row, 'gap' => $g( $pcs, 'gap' ), 'justify' => $g( $pcs, 'justify-content' ), 'skin' => implode( ';', $skin ) );
			}
			$href = trim( (string) $a->getAttribute( 'href' ) );
			if ( 0 === stripos( $href, 'javascript:' ) ) { $href = ''; }
			$out[] = array( 'label' => $label, 'url' => $href );
			if ( count( $out ) >= 8 ) { break; }
		}
		return $out;
	}

	private static function footer_group_to_column( array $group ) {
		// Every footer column now emits the UNIFIED `list_item` element (text + optional icon + optional smart
		// link) for its rows — the theme's column renderer auto-groups a run of 2+ into a semantic <ul><li>.
		// This retires the old split emit (nav → `link`, contact → `icon_text`, text-only → a `<ul>` frozen in
		// a Text element): a menu link, an icon contact row, and a plain address line are ALL editable rows now.
		$title = trim( (string) ( $group['title'] ?? '' ) );
		$mk_heading = function ( $deftag ) use ( $group, $title ) {
			if ( $title === '' ) { return null; }
			$tag = preg_match( '/^h[2-6]$/', (string) ( $group['tag'] ?? '' ) ) ? $group['tag'] : $deftag;
			return array( 'element_type' => array( 'element' => 'heading', 'heading' => array( 'heading_text' => $title, 'heading_level' => $tag ) ) );
		};
		$mk_item = function ( $text, $icon = null, $link = '', $type = 'none' ) {
			$li = array( 'li_text' => (string) $text, 'li_link_type' => $type );
			if ( $icon )        { $li['li_icon']   = $icon; }
			if ( $link !== '' ) { $li['li_link']   = $link; }
			if ( 'url' === $type ) { $li['li_target'] = '_self'; }
			return array( 'element_type' => array( 'element' => 'list_item', 'list_item' => $li ) );
		};

		// CONTACT column (icon + text rows) → heading + one List Item per row (icon tinted; tel/mailto/url link).
		if ( ( $group['kind'] ?? '' ) === 'contact' && ! empty( $group['rows'] ) ) {
			$els = array(); $h = $mk_heading( 'h4' ); if ( $h ) { $els[] = $h; }
			foreach ( $group['rows'] as $r ) {
				$txt = isset( $r['text'] ) ? (string) $r['text'] : '';
				if ( $txt === '' ) { continue; }
				$ico  = ( isset( $r['icon'] ) && $r['icon'] !== '' ) ? self::contact_icon_v2( $r['icon'], isset( $r['color'] ) ? $r['color'] : '' ) : null;
				$lnk  = isset( $r['link'] ) ? (string) $r['link'] : '';
				$type = ( $lnk !== '' ) ? ( ( stripos( $lnk, 'tel:' ) === 0 ) ? 'phone' : ( ( stripos( $lnk, 'mailto:' ) === 0 ) ? 'email' : 'url' ) ) : 'none';
				$els[] = $mk_item( $txt, $ico, $lnk, $type );
			}
			// The source's social row lives in THIS column (a "Get in Touch" contact column) — append the
			// social_icons element here (it renders the site-wide social_profiles) so the icons sit where the
			// source put them instead of duplicating into the brand column.
			if ( ! empty( $group['append_social'] ) ) { $els[] = array( 'element_type' => array( 'element' => 'social_icons' ) ); }
			return $els;
		}

		// SOCIAL column → its heading + the site's social icons (where the source puts them).
		if ( ( $group['kind'] ?? '' ) === 'social' ) {
			$els = array(); $h = $mk_heading( 'h4' ); if ( $h ) { $els[] = $h; }
			$els[] = array( 'element_type' => array( 'element' => 'social_icons' ) );
			return $els;
		}
		// NEWSLETTER column → the native newsletter element (unchanged).
		if ( ( $group['kind'] ?? '' ) === 'newsletter' && ! empty( $group['newsletter'] ) ) {
			$nw = $group['newsletter'];
			// the column's label is a footer column HEADING like its siblings' (the same 10px tracked uppercase) — as the
			// newsletter's own title it rendered in the widget's display face beside plain-label columns (a real-site audit);
			// an icon-only submit (an arrow glyph) keeps an arrow, never an invented "Subscribe"
			$els = array(); $h = $mk_heading( 'h4' ); if ( $h ) { $els[] = $h; }
			$els[] = array( 'element_type' => array( 'element' => 'newsletter', 'newsletter' => array(
				'newsletter_title' => '',
				'newsletter_desc' => (string) ( $nw['tagline'] ?? '' ),
				'newsletter_email_ph' => ( ! empty( $nw['placeholder'] ) ? (string) $nw['placeholder'] : 'Your email address' ),
				'newsletter_button' => ( ! empty( $nw['button'] ) ? (string) $nw['button'] : ( ! empty( $nw['iconOnly'] ) ? '→' : 'Subscribe' ) ),
				'show_name'         => 'no',
				'design'            => 'inline',
			) ) );
			return $els;
		}

		// NAV column (real <a> links) → heading + one List Item (URL link) per {label,href}.
		if ( ! empty( $group['links'] ) ) {
			$els = array(); $h = $mk_heading( 'h3' ); if ( $h ) { $els[] = $h; }
			$had = false;
			foreach ( $group['links'] as $l ) {
				$label = trim( (string) $l['label'] );
				if ( $label === '' ) { continue; }
				$had = true;
				$els[] = $mk_item( $label, null, ( isset( $l['href'] ) && $l['href'] !== '' ) ? $l['href'] : '#', 'url' );
			}
			if ( $had ) { return $els; }
		}

		// TEXT-ONLY column (plain lines, no icons/links — e.g. address / city / email / phone) → heading + one
		// List Item per line. A bare email / phone line becomes a mailto: / tel: link so it stays actionable.
		$els = array(); $h = $mk_heading( 'h4' ); if ( $h ) { $els[] = $h; }
		foreach ( ( $group['items'] ?? array() ) as $line ) {
			$line = trim( (string) $line );
			if ( $line === '' ) { continue; }
			if ( preg_match( '/^[^\s@]+@[^\s@]+\.[^\s@]+$/', $line ) ) {
				$els[] = $mk_item( $line, null, $line, 'email' );
			} elseif ( preg_match( '/^[\d\s()+.\-]+$/', $line ) && strlen( preg_replace( '/[^0-9+]/', '', $line ) ) >= 7 ) {
				$els[] = $mk_item( $line, null, $line, 'phone' );
			} else {
				$els[] = $mk_item( $line );
			}
		}
		return $els;
	}

	/**
	 * Build ONE footer bar's Theme-Settings value ({ count, '<count>' => { <prefix>_col_N, <prefix>_split|layout } })
	 * from detected column-groups, optionally prepended with pre-built lead columns (e.g. the brand column).
	 * `$prefix` is `main_footer` / `pre_footer` / `post_footer`, so the same builder fills every band's bar.
	 *
	 * @param array  $groups    detect_footer_columns() output for this band
	 * @param string $prefix    main_footer | pre_footer | post_footer
	 * @param string $html      source html (for wide-brand ratio detection)
	 * @param array  $lead_cols pre-built columns to place first (each an element_type list)
	 * @return array|null the bar value, or null when there are no columns
	 */
	private static function build_footer_bar( array $groups, $prefix, $html, array $lead_cols = array() ) {
		$cols = array();
		foreach ( $lead_cols as $lc ) { if ( ! empty( $lc ) ) { $cols[] = $lc; } }
		foreach ( $groups as $group ) { $cols[] = self::attach_visibility( self::footer_group_to_column( $group ), $group['cls'] ?? '' ); }
		return self::footer_columns_to_bar( $cols, $prefix, $html );
	}

	/**
	 * Assemble a footer bar's Theme-Settings value from pre-built COLUMNS (each an element_type list). Shared
	 * by the single-band path (build_footer_bar) and the per-band router, so every bar (pre/main/post) is built
	 * identically: count + <count> → { <prefix>_col_N } + the twelfths split / fifths layout ratio.
	 *
	 * @param array  $cols   columns (each an element_type list)
	 * @param string $prefix main_footer | pre_footer | post_footer
	 * @param string $html   source html (wide-brand ratio detection)
	 * @return array|null
	 */
	private static function footer_columns_to_bar( array $cols, $prefix, $html ) {
		$cols  = array_slice( $cols, 0, 8 ); // the footer builder supports up to an 8-col row
		$count = count( $cols );
		if ( 0 === $count ) { return null; }
		$bar = array();
		for ( $i = 0; $i < $count; $i++ ) { $bar[ $prefix . '_col_' . ( $i + 1 ) ] = $cols[ $i ]; }
		// Ratio from the source grid's true widths: EQUAL by default; weight the first (brand) column only when
		// it is genuinely ~1.5-2x wider. 2/3/4/6 carry the ratio on the twelfths split; 5 uses the fifths picker.
		// 7/8 columns have no twelfths/fifths representation, so they map to Auto Width (a content-sized flex
		// row) — matching the footer builder, which forces auto for count >= 7 (see footer-builder.php).
		$wide = self::detect_footer_wide_brand( (string) $html, $count );
		// The main row IS a content-sized FLEX row (`flex justify-between items-center`: a brand lockup left, a tagline right —
		// no grid tracks): the footer builder's own Auto Width + Distribution reproduces it exactly; a fixed 50 / 50 split
		// left the right-aligned tagline ending mid-row (a real-site report). `space-evenly` maps to the builder's `around`.
		$flex_dist = self::footer_flex_distribution( (string) $html, $count );
		if ( '' !== $flex_dist ) { $bar[ $prefix . '_auto' ] = 'yes'; $bar[ $prefix . '_justify' ] = $flex_dist; }
		elseif ( $count >= 7 ) {
			$bar[ $prefix . '_auto' ] = 'yes'; $bar[ $prefix . '_justify' ] = 'between';
			// …with the source grid's MEASURED tracks: a `grid-cols-8` whose brand spans two tracks (318px) beside 143px link
			// columns — the theme's even 1.7 : 1 flex split drew the brand 214px and the links 131px, and a ninth cell that
			// the source wraps to a second row was squeezed into the first (a real-site audit). Desktop only; the theme's
			// phone rule stands.
			if ( 'main_footer' === $prefix ) { self::$footer_track_css = self::footer_track_css( (string) $html, $count ); }
		}
		elseif ( $count >= 2 && 5 !== $count ) {
			// MEASURED first: the source row's computed grid tracks (747.5px 552.5px → 57 / 43) when the track
			// count matches the column count; the equal / wide-brand heuristic only when there is no such row.
			$measured = self::footer_measured_split( (string) $html, $count );
			$bar[ $prefix . '_split' ] = $measured ? $measured : self::footer_split_segments( $count, $wide );
		}
		elseif ( 5 === $count ) { $bar[ $prefix . '_layout' ] = '5-equal'; }
		return array( 'count' => (string) $count, (string) $count => $bar );
	}

	/** The main row's DISTRIBUTION when it is a content-sized flex ROW of exactly $count cells: the builder's `between` /
	 *  `around` / `center` / `start` / `end` from its computed `justify-content` — '' for a grid, a column, or a `normal`
	 *  start-packed row whose cells fill the width (a fixed split says the same). */
	private static function footer_flex_distribution( $html, $count ) {
		$footer = self::footer_root_el( $html );
		$row = self::footer_main_row_el( $footer );
		if ( ! ( $row instanceof DOMElement ) ) { return ''; }
		$cs = (string) $row->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $cs ) || preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $cs ) ) { return ''; }
		if ( count( self::el_children( $row ) ) !== (int) $count ) { return ''; }
		$jc = preg_match( '/(?:^|;)\s*justify-content:\s*([a-z-]+)/i', $cs, $jm ) ? strtolower( $jm[1] ) : '';
		$map = array( 'space-between' => 'between', 'space-around' => 'around', 'space-evenly' => 'around', 'center' => 'center', 'flex-end' => 'end', 'end' => 'end', 'flex-start' => 'start', 'start' => 'start' );
		if ( ! isset( $map[ $jc ] ) ) { return ''; }
		// a start-packed row whose cells fill the row (`flex-1` cells) is a fixed split, not a content-sized row
		if ( 'start' === $map[ $jc ] ) {
			$rw = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $cs, $wm ) ? (float) $wm[1] : 0.0; $sum = 0.0;
			foreach ( self::el_children( $row ) as $k ) { $sum += (float) self::sc_css( $k, 'width' ); }
			if ( $rw <= 0 || $sum >= 0.9 * $rw ) { return ''; }
		}
		return $map[ $jc ];
	}

	/** The footer's MAIN row (the grid / flex row with the most text and ≥ 2 content children), or null. */
	private static function footer_main_row_el( $scope ) {
		if ( ! ( $scope instanceof DOMElement ) ) { return null; }
		$best = null; $bestt = -1;
		foreach ( $scope->getElementsByTagName( 'div' ) as $d ) {
			$disp = strtolower( self::sc_css( $d, 'display' ) );
			if ( $disp !== 'grid' && $disp !== 'flex' ) { continue; }
			$n = 0; foreach ( self::el_children( $d ) as $k ) { if ( trim( $k->textContent ) !== '' || $k->getElementsByTagName( 'img' )->length ) { $n++; } }
			if ( $n < 2 ) { continue; }
			$t = mb_strlen( trim( preg_replace( '/\s+/', ' ', (string) $d->textContent ) ) );
			if ( $t > $bestt ) { $bestt = $t; $best = $d; }
		}
		return $best;
	}

	/** Split segments from the main row's computed grid-template-columns when it has exactly $count px tracks
	 *  that differ (≥ 5 % apart); array() otherwise (equal tracks → the caller's equal split is already right). */
	/** Scoped desktop CSS pinning a ≥7-column (Auto Width) footer's columns to the source grid's MEASURED track widths
	 *  (a `col-span-N` cell = N tracks + the gaps between) and its gap, so the row wraps exactly where the source does. */
	private static $footer_track_css = '';
	private static function footer_track_css( $html, $count ) {
		$footer = self::footer_root_el( $html );
		$row = self::footer_main_row_el( $footer );
		if ( ! ( $row instanceof DOMElement ) ) { return ''; }
		$gtc = self::sc_css( $row, 'grid-template-columns' );
		if ( ! preg_match_all( '/([0-9.]+)px/', $gtc, $m ) || count( $m[1] ) < 2 ) { return ''; }
		$tracks = array_map( 'floatval', $m[1] ); $nt = count( $tracks );
		$gap = (float) self::grid_gap_px( $row );
		$kids = self::el_children( $row ); if ( count( $kids ) !== (int) $count ) { return ''; }
		$rules = array(); $ti = 0;
		foreach ( $kids as $i => $k ) {
			$span = max( 1, (int) self::col_span( self::cls( $k ) ) );
			if ( $ti + $span > $nt ) { $ti = 0; } // the cell wrapped to the next grid row
			$w = 0.0; for ( $s = 0; $s < $span; $s++ ) { $w += $tracks[ $ti + $s ]; }
			$w += ( $span - 1 ) * $gap; $ti += $span;
			$rules[] = '.footer-section .footer-row--equal > .footer-col--auto:nth-child(' . ( $i + 1 ) . '){flex:0 0 ' . (int) round( $w ) . 'px;min-width:0;}';
		}
		if ( ! $rules ) { return ''; }
		return '@media (min-width:783px){.footer-section .footer-row--equal{gap:' . (int) round( $gap ) . 'px;justify-content:flex-start;}' . implode( '', $rules ) . '}';
	}

	/** Append a pending ≥7-column footer track rule (footer_track_css) to the misc Custom CSS, once. */
	private static function flush_footer_track_css( array &$values ) {
		if ( '' === self::$footer_track_css ) { return; }
		$values['misc_custom_css']['custom_css'] = (string) ( $values['misc_custom_css']['custom_css'] ?? '' ) . "
/* Footer: the source grid's measured tracks */
" . self::$footer_track_css;
		self::$footer_track_css = '';
	}

	private static function footer_measured_split( $html, $count ) {
		$footer = self::footer_root_el( $html );
		$row = self::footer_main_row_el( $footer );
		if ( ! ( $row instanceof DOMElement ) ) { return array(); }
		$gtc = self::sc_css( $row, 'grid-template-columns' );
		if ( ! preg_match_all( '/([0-9.]+)px/', $gtc, $m ) || count( $m[1] ) !== (int) $count ) {
			// A 12-TRACK grid whose cells SPAN (`grid-cols-12`: a `col-span-4` brand column beside a `col-span-8` that holds a nested
			// `grid-cols-3` of link columns) has 12 px tracks, not one per column — the equal split squeezed the brand column to a
			// quarter (a finding filed on thirteen conversions). Read each direct cell's span (`col-span-N`, else its measured
			// `track-frac`), and split a nested grid's span evenly among its own columns; use it only when the count matches.
			$segs = array(); $kids = self::el_children( $row );
			$ntracks = preg_match_all( '/([0-9.]+)px/', $gtc, $mm ) ? count( $mm[1] ) : 0;
			foreach ( $kids as $k ) {
				$kcls = self::cls( $k ); $span = self::col_span( $kcls );
				$frac = 0.0; if ( preg_match( '/(?:^|;)\s*track-frac:\s*([0-9.]+)/', (string) $k->getAttribute( 'data-sc-cs' ), $fm ) ) { $frac = (float) $fm[1]; }
				if ( $span >= 1 && $ntracks >= 2 ) { $frac = $span / $ntracks; }
				if ( $frac <= 0 ) { $segs = array(); break; }
				$inner = self::grid_col_count( $k );
				if ( $inner < 2 ) { $kd = strtolower( (string) self::sc_css( $k, 'display' ) ); if ( 'grid' === $kd && preg_match_all( '/[0-9.]+px/', (string) self::sc_css( $k, 'grid-template-columns' ), $im ) ) { $inner = count( $im[0] ); } }
				if ( $inner >= 2 && count( self::el_children( $k ) ) >= $inner ) { for ( $i = 0; $i < $inner; $i++ ) { $segs[] = array( 'w' => $frac / $inner, 'name' => '' ); } }
				else { $segs[] = array( 'w' => $frac, 'name' => '' ); }
			}
			if ( count( $segs ) !== (int) $count ) { return array(); }
			$tot = array_sum( wp_list_pluck( $segs, 'w' ) ); if ( $tot <= 0 ) { return array(); }
			foreach ( $segs as &$sg ) { $sg['w'] = (int) round( $sg['w'] / $tot * 100 ); } unset( $sg );
			$segs[0]['w'] += 100 - array_sum( wp_list_pluck( $segs, 'w' ) );
			return $segs;
		}
		$tracks = array_map( 'floatval', $m[1] ); $sum = array_sum( $tracks );
		if ( $sum <= 0 || ( max( $tracks ) - min( $tracks ) ) / $sum < 0.05 ) { return array(); }
		$segs = array(); foreach ( $tracks as $t ) { $segs[] = array( 'w' => (int) round( $t / $sum * 100 ), 'name' => '' ); }
		$segs[0]['w'] += 100 - array_sum( wp_list_pluck( $segs, 'w' ) );
		return $segs;
	}

	/**
	 * Footer content COLUMNS → [{ title, links:[{label,href}], items:[text] }]. A heading (h3-h6) plus its
	 * following content, which is EITHER a link list (Quick Links) OR a plain text list (Services: bare
	 * `<li>`s) OR icon+text lines (Contact Info: address/phone/email). Earlier this required ≥2 real `<a>`
	 * links, which silently DROPPED the text-only "Services"/"Contact Info" columns and collapsed a faithful
	 * 4-column footer down to 2 (brand + one link column) — the fidelity gap that made the $dyn path bake the
	 * footer verbatim instead of using native Theme Settings. Now a column is kept when it has ≥2 links OR ≥2
	 * text items, so the whole grid maps into `main_footer_columns`. `links` and `items` are mutually
	 * preferred (links win when present); the builder renders links as an `<a>` list, items as a plain list.
	 */
	/** `prop:val;prop:val` built from an element's captured computed styles (data-sc-cs) for the given props —
	 *  used to emit a SCOPED CSS rule (not inline styles) that carries a heading's source look
	 *  (font/size/weight/colour/italic). Skips empty / inherit / default-normal; spaced rgb()→hex. */
	private static function cs_decl_str( $el, array $props ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$decls = array();
		foreach ( $props as $p ) {
			$v = trim( (string) self::sc_css( $el, $p ) );
			if ( $v === '' || stripos( $v, 'inherit' ) !== false ) { continue; }
			if ( ( $p === 'font-style' || $p === 'letter-spacing' ) && strcasecmp( $v, 'normal' ) === 0 ) { continue; }
			if ( ( $p === 'color' || $p === 'background-color' ) && preg_match( '/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i', $v, $m ) ) {
				$v = sprintf( '#%02x%02x%02x', min( 255, (int) $m[1] ), min( 255, (int) $m[2] ), min( 255, (int) $m[3] ) );
			}
			$decls[] = $p . ':' . $v;
		}
		return implode( ';', $decls );
	}

	/**
	 * The footer band's CTA LEAD heading element — an h1/h2 lockup, OR an h3 when the band is a CTA
	 * (it holds a button-styled link, e.g. the the burger restaurant source "Craving a Juicy Burger? … BOOK A TABLE"
	 * pre-footer). h3 is admitted ONLY in a CTA band because bare h3/h4 are normal footer COLUMN titles;
	 * requiring a CTA button keeps a column heading from being mistaken for the lead. A logo/brand column
	 * (heading beside an <img>) is skipped. Shared by detect_footer_lead_heading() + footer_lead_css() so
	 * they never disagree on WHICH heading is the lead.
	 */
	private static function footer_lead_heading_el( $footer ) {
		if ( ! ( $footer instanceof DOMElement ) ) { return null; }
		$has_cta_btn = false;
		foreach ( $footer->getElementsByTagName( 'a' ) as $a ) { if ( self::is_button( $a ) ) { $has_cta_btn = true; break; } }
		foreach ( array( 'h1', 'h2', 'h3' ) as $tag ) {
			if ( 'h3' === $tag && ! $has_cta_btn ) { continue; }
			foreach ( $footer->getElementsByTagName( $tag ) as $cand ) {
				$txt = trim( preg_replace( '/\s+/', ' ', self::text( $cand ) ) );
				if ( $txt === '' || str_word_count( $txt ) < 2 ) { continue; }
				$parent = $cand->parentNode;
				if ( $parent instanceof DOMElement && $parent->getElementsByTagName( 'img' )->length > 0 ) { continue; }
				return $cand;
			}
		}
		return null;
	}

	/** The lead heading's immediately-following subtitle <p>/<span>/<div> (a CTA sentence, ≤ 14 words), or null. */
	private static function footer_lead_subtitle_el( $h ) {
		if ( ! ( $h instanceof DOMElement ) ) { return null; }
		$n = $h->nextSibling;
		while ( $n && $n->nodeType !== XML_ELEMENT_NODE ) { $n = $n->nextSibling; }
		if ( $n instanceof DOMElement && in_array( strtolower( $n->nodeName ), array( 'p', 'span', 'div' ), true ) ) {
			$st = trim( preg_replace( '/\s+/', ' ', self::text( $n ) ) );
			if ( $st !== '' && str_word_count( $st ) <= 40 ) { return $n; }
		}
		return null;
	}

	/** "margin-top:0 !important;" / "margin-bottom:0 !important;" for each vertical margin the source computes as 0 —
	 *  significant_text_decls only carries POSITIVE margins, so a theme default (an h3's bottom margin) would
	 *  otherwise leak into a lockup whose source had none. */
	private static function zero_margin_decls( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$out = '';
		$m = preg_split( '/\s+/', trim( (string) self::sc_css( $el, 'margin' ) ) );
		$mt = isset( $m[0] ) ? $m[0] : ''; $mb = isset( $m[2] ) ? $m[2] : $mt;
		if ( $mt === '0px' ) { $out .= 'margin-top:0 !important;'; }
		if ( $mb === '0px' ) { $out .= 'margin-bottom:0 !important;'; }
		return $out;
	}

	/**
	 * The footer's OWN brand lockup measures → scoped CSS on the footer logo element (the theme renders the header
	 * logo there). The wordmark = the footer leaf whose text is the site title; its type (size / weight / colour /
	 * tracking) → .footer .site-title-text. The mark = the svg beside it; when its wrapper paints NO frame the header's
	 * framed circle is dropped in the footer and the glyph takes the footer's measured size + ink. '' when no lockup.
	 */
	private static function footer_brand_css( $html, $site_title ) {
		$footer = self::footer_root_el( $html );
		if ( ! ( $footer instanceof DOMElement ) || '' === trim( (string) $site_title ) ) { return ''; }
		$want = strtolower( trim( preg_replace( '/\s+/', ' ', (string) $site_title ) ) );
		$word = null;
		foreach ( $footer->getElementsByTagName( '*' ) as $e ) {
			if ( ! in_array( strtolower( $e->tagName ), array( 'span', 'div', 'a', 'p', 'strong', 'b' ), true ) ) { continue; }
			if ( 0 !== $e->getElementsByTagName( '*' )->length ) { continue; }
			if ( strtolower( trim( preg_replace( '/\s+/', ' ', self::text( $e ) ) ) ) === $want ) { $word = $e; break; }
		}
		if ( ! ( $word instanceof DOMElement ) ) { return ''; }
		$css = '';
		$wd = FW_Site_Converter_Mapper::cs_decls( (string) $word->getAttribute( 'data-sc-cs' ), array( 'font-size', 'font-weight', 'letter-spacing', 'color', 'text-transform' ) );
		$d = array();
		if ( ! empty( $wd['font-size'] ) && preg_match( '/^[0-9.]+px$/', $wd['font-size'] ) ) { $d[] = 'font-size:' . $wd['font-size']; }
		if ( ! empty( $wd['font-weight'] ) && preg_match( '/^[1-9]00$/', $wd['font-weight'] ) ) { $d[] = 'font-weight:' . $wd['font-weight']; }
		if ( ! empty( $wd['letter-spacing'] ) && preg_match( '/^-?[0-9.]+px$/', $wd['letter-spacing'] ) ) { $d[] = 'letter-spacing:' . $wd['letter-spacing']; }
		if ( ! empty( $wd['color'] ) && preg_match( '/^rgba?\(/i', $wd['color'] ) ) { $d[] = 'color:' . $wd['color']; }
		if ( $d ) { $css .= '.footer .site-title-text{' . implode( ' !important;', $d ) . ' !important;}'; }
		// The mark beside the wordmark (a sibling svg / icon host, within the same lockup wrapper).
		$wrap = $word->parentNode; $mark = null;
		if ( $wrap instanceof DOMElement ) { foreach ( $wrap->getElementsByTagName( 'svg' ) as $sv ) { if ( ! self::is_ancestor( $word, $sv ) ) { $mark = $sv; break; } } }
		if ( $mark instanceof DOMElement ) {
			$host = $mark->parentNode; $tile = null;
			for ( $ap = $host, $i = 0; $ap instanceof DOMElement && $ap !== $wrap && $i < 3; $ap = $ap->parentNode, $i++ ) {
				$bg = self::sc_css( $ap, 'background-color' );
				if ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) { $tile = $ap; break; }
			}
			$m = array();
			if ( ! $tile ) {
				// unframed in the footer → no circle / tile there; the glyph is sized + inked by its host's computed style
				$m[] = 'background:transparent'; $m[] = 'border-radius:0'; $m[] = 'box-shadow:none'; $m[] = 'border:0'; $m[] = 'padding:0'; // (the framed mark's hairline drew a square around the plain footer glyph — a real-site report)
				$hs = ( $host instanceof DOMElement ) ? self::sc_css( $host, 'font-size' ) : '';
				$hh = ( $host instanceof DOMElement ) ? self::sc_css( $host, 'height' ) : '';
				$sz = preg_match( '/^[0-9.]+px$/', $hh ) ? $hh : ( preg_match( '/^[0-9.]+px$/', $hs ) ? $hs : '' );
				if ( '' !== $sz ) { $m[] = 'width:' . $sz; $m[] = 'height:' . $sz; $m[] = 'font-size:' . $sz; }
				$hc = ( $host instanceof DOMElement ) ? self::sc_css( $host, 'color' ) : '';
				if ( '' !== $hc ) { $m[] = 'color:' . $hc; }
			}
			if ( $m ) { $css .= '.footer .site-logo__mark{' . implode( ' !important;', $m ) . ' !important;}'; }
		}
		return $css;
	}

	/** The lead heading's EYEBROW: the previous element sibling when it is a short (≤ 40 chars) leaf that reads
	 *  small (≤ 13px) or uppercase — "The Rooftop Footer" over a display heading. Null otherwise. */
	private static function footer_lead_eyebrow_el( $h ) {
		if ( ! ( $h instanceof DOMElement ) ) { return null; }
		$n = $h->previousSibling;
		while ( $n && $n->nodeType !== XML_ELEMENT_NODE ) { $n = $n->previousSibling; }
		if ( ! ( $n instanceof DOMElement ) || ! in_array( strtolower( $n->nodeName ), array( 'div', 'span', 'p', 'small', 'em', 'strong' ), true ) ) { return null; }
		if ( $n->getElementsByTagName( 'img' )->length || $n->getElementsByTagName( 'svg' )->length || $n->getElementsByTagName( 'a' )->length ) { return null; }
		$t = trim( preg_replace( '/\s+/', ' ', self::text( $n ) ) );
		if ( $t === '' || mb_strlen( $t ) > 40 || preg_match( '/[.!?]$/', $t ) ) { return null; }
		$fs = self::sc_css( $n, 'font-size' );
		$small = preg_match( '/^([0-9.]+)px$/', $fs, $m ) && (float) $m[1] <= 13;
		$upper = stripos( self::sc_css( $n, 'text-transform' ), 'uppercase' ) !== false || ( preg_match( '/[a-z]/i', $t ) && $t === mb_strtoupper( $t ) );
		return ( $small || $upper ) ? $n : null;
	}

	/** The footer band's CTA button (a button-styled <a> with a text label), or null. */
	private static function footer_lead_button_el( $footer ) {
		if ( ! ( $footer instanceof DOMElement ) ) { return null; }
		foreach ( $footer->getElementsByTagName( 'a' ) as $a ) {
			if ( self::is_button( $a ) && trim( self::text( $a ) ) !== '' ) { return $a; }
		}
		return null;
	}

	/**
	 * NEVER-DROP footer LEAD-HEADING typography → scoped `.footer-lead-title` / `.footer-lead-subtitle`
	 * rules (or ''). The source's first footer column can be a display CTA lockup ("Tell us your story /
	 * Get in touch") with a distinctive display font / size / colour / italic subtitle the footer builder
	 * has no native option for. detect_footer_lead_heading() emits CLEAN markup with those two hook classes;
	 * this carries the look as a scoped rule in the misc_custom_css residual — the documented pattern (same
	 * as footer_heading_css / footer_link_css), NOT inline styles in the Text element content.
	 */
	private static function footer_lead_css( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		$h = self::footer_lead_heading_el( $footer );
		if ( ! ( $h instanceof DOMElement ) ) { return ''; }
		$sub = self::footer_lead_subtitle_el( $h );
		$btn = self::footer_lead_button_el( $footer );
		$css = '';
		// Centre the whole lockup when the source band is centred (a CTA pre-footer is `text-center`), so the
		// heading/subtitle/button stack sits centred like the source instead of flush-left in the footer column.
		$centered = ( stripos( (string) $h->getAttribute( 'data-sc-cs' ), 'text-align:center' ) !== false );
		if ( $centered ) { $css .= '.footer-lead{text-align:center;}'; }
		// The complete text translator (max-width / margin / padding / line-height / letter-spacing / size /
		// weight / align / colour), PLUS font-family (a wordmark concern the general helper leaves out).
		$dff = self::cs_decl_str( $h, array( 'font-family' ) );
		$d   = ( $dff !== '' ? $dff . ';' : '' ) . self::significant_text_decls( (string) $h->getAttribute( 'data-sc-cs' ), array(), true );
		$d .= self::zero_margin_decls( $h );
		if ( $d !== '' ) { $css .= '.footer-lead-title{' . $d . '}'; }
		// The lockup's EYEBROW (a small mono / uppercase label above the lead heading) — its type (family,
		// size, tracking, case, colour with its alpha) as a scoped rule. JS twin: footerLeadEyebrow.
		$eb = self::footer_lead_eyebrow_el( $h );
		if ( $eb instanceof DOMElement ) {
			$dff2 = self::cs_decl_str( $eb, array( 'font-family' ) );
			$d0   = ( $dff2 !== '' ? $dff2 . ';' : '' ) . self::significant_text_decls( (string) $eb->getAttribute( 'data-sc-cs' ), array(), true );
			$css .= '.footer-lead-eyebrow{display:block;' . $d0 . self::zero_margin_decls( $eb ) . '}';
		}
		if ( $sub instanceof DOMElement ) {
			$d2 = self::significant_text_decls( (string) $sub->getAttribute( 'data-sc-cs' ), array(), true );
			// A capped subtitle (`max-w-md mx-auto`) keeps only its max-width (the horizontal auto-margins are
			// dropped by significant_text_decls), so it pins LEFT instead of centring under the heading. When the
			// lockup is centred, re-assert the auto side-margins so the narrowed box sits centred like the source.
			if ( $centered && stripos( $d2, 'max-width' ) !== false ) { $d2 .= 'margin-left:auto !important;margin-right:auto !important;'; }
			$d2 .= self::zero_margin_decls( $sub );
			if ( $d2 !== '' ) { $css .= '.footer-lead-subtitle{' . $d2 . '}'; }
		}
		// The CTA button's fill / ink / padding / radius / typography → a scoped `.footer-lead-btn` rule so the
		// "BOOK A TABLE" pill reproduces the source (white fill, dark ink, uppercase) instead of a plain link.
		if ( $btn instanceof DOMElement ) {
			$bd = self::cs_decl_str( $btn, array( 'background-color', 'color', 'padding', 'border-radius', 'font-family', 'font-size', 'font-weight', 'text-transform', 'letter-spacing' ) );
			// !important on each decl so the button's own fill/ink beats the generic footer-link colour rule
			// (`.footer a{color:rgba(…,.7)}`) that otherwise tints the CTA button text translucent.
			if ( '' !== $bd ) { $bd = str_replace( ';', ' !important;', $bd ) . ' !important'; }
			$css .= '.footer-lead-btn{display:inline-flex !important;align-items:center;gap:8px;text-decoration:none !important;margin-top:4px;' . ( $bd !== '' ? $bd . ';' : '' ) . '}';
		}
		return $css;
	}

	/**
	 * A display HEADING that IS the source footer's first column — a CTA lockup like "Tell us your story /
	 * Get in touch" — as opposed to a column TITLE (short, uppercase, h3+) or a logo/brand column. Returns
	 * the heading (italic spans kept) + its immediately-following short subtitle as text_content HTML, or ''
	 * when the first column is a normal logo/brand column. Lets footer_brand_col reproduce the real CTA
	 * instead of substituting the site logo + a disclaimer tagline (the "wrong first footer column" bug).
	 *
	 * @param string $html footer band HTML
	 * @return string
	 */
	private static function detect_footer_lead_heading( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		$h = self::footer_lead_heading_el( $footer );
		if ( ! ( $h instanceof DOMElement ) ) { return ''; }
		// Bake the source's computed look via scoped `.footer-lead-*` rules (footer_lead_css), NOT inline
		// styles — the Text element's kses would drop inline soup, and scoped rules are the documented pattern.
		// CLEAN semantic HTML only, wrapped in `.footer-lead` so the whole CTA lockup can be centred as one.
		$out = '';
		$eb  = self::footer_lead_eyebrow_el( $h );
		if ( $eb instanceof DOMElement ) { $out .= '<span class="footer-lead-eyebrow">' . esc_html( trim( preg_replace( '/\s+/', ' ', self::text( $eb ) ) ) ) . '</span>'; }
		$out .= '<h3 class="footer-lead-title">' . self::clean_inline_html( $h ) . '</h3>';
		$sub = self::footer_lead_subtitle_el( $h );
		if ( $sub instanceof DOMElement ) { $out .= '<p class="footer-lead-subtitle">' . self::clean_inline_html( $sub ) . '</p>'; }
		// The CTA button ("BOOK A TABLE") — carried as a real link with the `.footer-lead-btn` skin. Text label
		// only (icons stripped): the footer Text element's kses drops <svg>, so a source arrow would leave a gap.
		$btn = self::footer_lead_button_el( $footer );
		if ( $btn instanceof DOMElement ) {
			$href  = trim( (string) $btn->getAttribute( 'href' ) );
			$label = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $btn ) ) );
			if ( '' === $label ) { $label = trim( preg_replace( '/\s+/', ' ', self::text( $btn ) ) ); }
			if ( '' !== $label ) {
				$tgt = ( strtolower( (string) $btn->getAttribute( 'target' ) ) === '_blank' ) ? ' target="_blank" rel="noopener noreferrer"' : '';
				$out .= '<a class="footer-lead-btn" href="' . esc_attr( '' !== $href ? $href : '#' ) . '"' . $tgt . '>' . esc_html( $label ) . '</a>';
			}
		}
		return '<div class="footer-lead">' . $out . '</div>';
	}

	/**
	 * Linkify a bare footer contact line: wrap a standalone email in `<a href="mailto:">` and a phone
	 * number in `<a href="tel:">`, so a plain-text Contact column (address / email / phone with no source
	 * anchors) stays actionable — WITHOUT inventing the leading icons the source never had (an icon-bearing
	 * contact column takes the structured icon_text path instead). A plain address line passes through
	 * escaped, unchanged. Digits-only comparison ignores spaces / dashes / parens in the displayed number.
	 */
	private static function footer_linkify_contact( $line ) {
		$line = trim( (string) $line );
		if ( $line === '' ) { return ''; }
		if ( preg_match( '/^[^\s@]+@[^\s@]+\.[^\s@]+$/', $line ) ) {
			return '<a class="footer-link hf-link" href="mailto:' . esc_attr( $line ) . '">' . esc_html( $line ) . '</a>';
		}
		if ( preg_match( '/^[\d\s()+.\-]+$/', $line ) ) {
			$digits = preg_replace( '/[^0-9+]/', '', $line );
			if ( strlen( $digits ) >= 7 ) {
				return '<a class="footer-link hf-link" href="tel:' . esc_attr( $digits ) . '">' . esc_html( $line ) . '</a>';
			}
		}
		return esc_html( $line );
	}

	/** LABEL elements acting as footer column titles: a short uppercase / tracked leaf <div>/<span>/<p> that OPENS a column of ≥ 2 links. */
	private static function footer_label_heads( $footer ) {
		$out = array();
		if ( ! ( $footer instanceof DOMElement ) ) { return $out; }
		foreach ( array( 'div', 'span', 'p' ) as $ltag ) {
			foreach ( $footer->getElementsByTagName( $ltag ) as $lb ) {
				if ( 0 !== $lb->getElementsByTagName( '*' )->length ) { continue; } // a leaf
				$lt = trim( preg_replace( '/\s+/', ' ', (string) $lb->textContent ) );
				if ( '' === $lt || mb_strlen( $lt ) > 24 || str_word_count( $lt ) > 3 ) { continue; }
				$lcs = (string) $lb->getAttribute( 'data-sc-cs' );
				$upper = preg_match( '/text-transform:\s*uppercase/i', $lcs ) || ( preg_match( '/[a-z]/i', $lt ) && $lt === mb_strtoupper( $lt ) );
				$tracked = preg_match( '/letter-spacing:\s*([0-9.]+)px/i', $lcs, $lsm ) && (float) $lsm[1] >= 1;
				if ( ! $upper && ! $tracked ) { continue; }
				$par = $lb->parentNode; if ( ! ( $par instanceof DOMElement ) ) { continue; }
				$first = null; foreach ( self::el_children( $par ) as $pc ) { $first = $pc; break; }
				if ( $first !== $lb ) { continue; } // the label OPENS its column
				$links = 0; foreach ( self::el_children( $par ) as $pc ) { if ( 'a' === strtolower( $pc->tagName ) ) { $links++; } } if ( $links < 2 ) { $links = $par->getElementsByTagName( 'a' )->length; }
				if ( $links < 2 ) { continue; }
				$out[] = $lb;
			}
		}
		return $out;
	}

	private static function detect_footer_columns( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return array(); }
		$out  = array();
		$seen = array(); // dedupe headings shared across h-levels
		// The column TITLES: real headings, plus a LABEL <div> / <span> that acts as one — a short uppercase / tracked leaf
		// ("NAVIGATION", "SOCIAL SIGNAL") that opens a column of ≥ 2 links (the source never used a heading tag).
		$heads = array();
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $htag ) { foreach ( $footer->getElementsByTagName( $htag ) as $h ) { $heads[] = array( $h, $htag ); } }
		foreach ( self::footer_label_heads( $footer ) as $lb ) { $heads[] = array( $lb, 'h4' ); }
		foreach ( $heads as $hh ) {
			{
				list( $h, $htag ) = $hh;
				$title = trim( preg_replace( '/\s+/', ' ', (string) $h->textContent ) );
				if ( $title === '' || str_word_count( $title ) > 4 || isset( $seen[ $title ] ) ) { continue; }
				$parent = $h->parentNode;
				if ( ! ( $parent instanceof DOMElement ) ) { continue; }
				// Prefer real links (a nav column). Skip the copyright band's legal links (they live in the
				// same footer but belong to the copyright bar) — those are detected separately.
				$links = array();
				foreach ( $parent->getElementsByTagName( 'a' ) as $a ) {
					$lbl = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $a ) ) );
					$hrf = trim( (string) $a->getAttribute( 'href' ) );
					if ( $lbl !== '' && self::social_lucide( $hrf ) === '' ) { $links[] = array( 'label' => $lbl, 'href' => $hrf ); }
					if ( count( $links ) >= 10 ) { break; }
				}
				// No link list? Fall back to the column's text items (`<li>` rows — plain text or icon+text).
				$items = array();
				$rows  = array(); // structured icon+text rows (a CONTACT column: address/phone/email)
				// A column whose links are tel:/mailto: is a CONTACT column (address/phone/email), not a nav-link
				// column — gather its icon+text rows so it maps to icon_text (incl. the address, which is not a link).
				$contact_links = 0; foreach ( $links as $l ) { $lh = strtolower( (string) $l['href'] ); if ( 0 === strpos( $lh, 'tel:' ) || 0 === strpos( $lh, 'mailto:' ) ) { $contact_links++; } }
				if ( count( $links ) < 2 || ( $links && $contact_links >= (int) ceil( count( $links ) / 2 ) ) ) {
					$links = array();
					foreach ( $parent->getElementsByTagName( 'li' ) as $li ) {
						$row = self::footer_contact_row( $li );
						$t   = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $li ) ) );
						if ( $t !== '' ) { $items[] = $t; }
						if ( $row !== null ) { $rows[] = $row; }
						if ( count( $items ) >= 10 ) { break; }
					}
					// No <li> list? A CONTACT column commonly lists address / phone / email as `<div class="flex
					// items-center gap-2">` (icon + text/link) rows — or bare tel:/mailto: links — instead of a <ul>.
					// Gather those DIRECT-child rows so the column maps to icon_text instead of being dropped as empty.
					if ( ! $rows ) {
						// Rows are usually wrapped in a container (e.g. <div class="space-y-2">) — descend to the
						// element whose OWN children are the individual rows (address / phone / email), skipping headings.
						$scope = $parent; $guard = 0;
						while ( $guard++ < 4 ) {
							$kids = array();
							foreach ( self::el_children( $scope ) as $k ) { if ( ! preg_match( '/^h[1-6]$/', strtolower( $k->nodeName ) ) ) { $kids[] = $k; } }
							if ( count( $kids ) === 1 && 'div' === strtolower( $kids[0]->nodeName ) ) { $scope = $kids[0]; continue; }
							break;
						}
						foreach ( self::el_children( $scope ) as $ch ) {
							$tag = strtolower( $ch->nodeName );
							if ( preg_match( '/^h[1-6]$/', $tag ) || ! in_array( $tag, array( 'div', 'p', 'a', 'address', 'span' ), true ) ) { continue; }
							// Skip a SOCIAL row/link (a `flex gap-3` of platform icon links, or a bare social <a>) — it's
							// rendered as the social_icons element, not as contact rows. Folding it in produced a garbled
							// row (an Instagram icon + the TikTok "TT" text + the Instagram link mashed together).
							$is_social_row = false;
							if ( 'a' === $tag ) {
								if ( self::social_lucide( (string) $ch->getAttribute( 'href' ) ) !== '' ) { $is_social_row = true; }
							} else {
								$na = 0; $ns = 0;
								foreach ( $ch->getElementsByTagName( 'a' ) as $sa ) { $na++; if ( self::social_lucide( (string) $sa->getAttribute( 'href' ) ) !== '' ) { $ns++; } }
								if ( $na > 0 && $ns === $na ) { $is_social_row = true; }
							}
							if ( $is_social_row ) { continue; }
							$has_svg = $ch->getElementsByTagName( 'svg' )->length > 0;
							$has_ct  = false;
							foreach ( $ch->getElementsByTagName( 'a' ) as $a ) { $h = strtolower( (string) $a->getAttribute( 'href' ) ); if ( 0 === strpos( $h, 'tel:' ) || 0 === strpos( $h, 'mailto:' ) ) { $has_ct = true; break; } }
							if ( ! $has_svg && ! $has_ct && strpos( strtolower( self::cls( $ch ) ), 'items-' ) === false ) { continue; }
							$row = self::footer_contact_row( $ch );
							$t   = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $ch ) ) );
							if ( $t !== '' ) { $items[] = $t; }
							if ( $row !== null ) { $rows[] = $row; }
							if ( count( $rows ) >= 12 ) { break; }
						}
					}
				}
				// A "contact" column = its rows are predominantly icon+text (a leading svg per row): keep the
				// structured rows so the emit can reproduce each leading icon (map-pin/phone/mail) + its color,
				// instead of flattening to a text blob that also glued the address lines together.
				// Backfill a missing per-row icon color from a sibling row (some inline svgs carry no computed
				// style of their own, but the column's icons share one tint — the brand-green `text-primary`).
				$ccolor = ''; foreach ( $rows as $r ) { if ( $r['color'] !== '' ) { $ccolor = $r['color']; break; } }
				if ( $ccolor !== '' ) { foreach ( $rows as &$r ) { if ( $r['icon'] !== '' && $r['color'] === '' ) { $r['color'] = $ccolor; } } unset( $r ); }
				$kind = 'text';
				$with_icon = 0; foreach ( $rows as $r ) { if ( $r['icon'] !== '' ) { $with_icon++; } }
				// A single icon + tel:/mailto: row is still a CONTACT column (the "Get in Touch" column: a mail icon +
				// email, with the social row rendered separately). Without this a 1-row contact column fell below the
				// ≥2-rows bar and was dropped, taking its heading + email + social with it.
				$contact_row_link = false;
				foreach ( $rows as $r ) { $rl = strtolower( (string) ( $r['link'] ?? '' ) ); if ( 0 === strpos( $rl, 'tel:' ) || 0 === strpos( $rl, 'mailto:' ) ) { $contact_row_link = true; break; } }
				if ( count( $rows ) >= 2 && $with_icon >= 2 && $with_icon >= (int) ceil( count( $rows ) / 2 ) ) { $kind = 'contact'; }
				elseif ( $contact_row_link && $with_icon >= 1 ) { $kind = 'contact'; }
				// A NEWSLETTER / signup column: a heading whose column carries an email/text `<input>` (an email
				// capture) but NO link list / text list / contact rows — so the three checks above would drop it
				// (the "Sprinkles Club" 4th column of a 4-col footer collapsing to 3). Recognize it as its own
				// column kind and capture the tagline + placeholder + button label so the emit can reproduce it
				// with the native `newsletter` element instead of silently losing the column.
				$news = null;
				if ( count( $links ) < 2 && count( $items ) < 2 && $kind !== 'contact' ) {
					$input = null;
					foreach ( $parent->getElementsByTagName( 'input' ) as $inp ) {
						$it = strtolower( trim( (string) $inp->getAttribute( 'type' ) ) );
						if ( $it === '' || in_array( $it, array( 'email', 'text', 'search' ), true ) ) { $input = $inp; break; }
					}
					if ( $input !== null ) {
						$tagline = '';
						foreach ( $parent->getElementsByTagName( 'p' ) as $pp ) { $t = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $pp ) ) ); if ( $t !== '' ) { $tagline = $t; break; } }
						$ph = trim( (string) $input->getAttribute( 'placeholder' ) );
						$btn = '';
						foreach ( array( 'button', 'a' ) as $bt ) { foreach ( $parent->getElementsByTagName( $bt ) as $b ) { $bl = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $b ) ) ); if ( $bl !== '' ) { $btn = $bl; break 2; } } }
						// an icon-only submit (an arrow glyph in the field's corner) keeps an arrow — never an invented "Subscribe" (a real-site audit)
						$icon_only = false; if ( '' === $btn ) { foreach ( $parent->getElementsByTagName( 'button' ) as $b ) { if ( $b->getElementsByTagName( 'svg' )->length || $b->getElementsByTagName( 'i' )->length || $b->getElementsByTagName( 'iconify-icon' )->length ) { $icon_only = true; break; } } }
						$news = array( 'tagline' => $tagline, 'placeholder' => $ph, 'button' => ( $btn !== '' ? $btn : ( $icon_only ? '→' : 'Subscribe' ) ), 'iconOnly' => $icon_only );
					}
				}
				// A SOCIAL column: a heading ("Telemetry" / "Follow us") over a row of ≥ 2 icon-only links (an svg / iconify / icon-font
				// glyph, no label) and nothing else → its own column kind: the heading + the site's social icons, where the source
				// puts them (they were hung on the brand column and this column vanished).
				$social_n = 0;
				if ( count( $links ) < 2 && count( $items ) < 2 && $kind !== 'contact' && null === $news ) {
					foreach ( $parent->getElementsByTagName( 'a' ) as $a ) {
						if ( '' !== trim( self::text_no_icons( $a ) ) ) { continue; }
						if ( $a->getElementsByTagName( 'svg' )->length || $a->getElementsByTagName( 'iconify-icon' )->length || $a->getElementsByTagName( 'i' )->length || $a->getElementsByTagName( 'img' )->length ) { $social_n++; }
					}
				}
				if ( count( $links ) >= 2 || count( $items ) >= 2 || ( $kind === 'contact' && count( $rows ) >= 1 ) || $news !== null || $social_n >= 2 ) {
					$out[] = array( 'title' => $title, 'tag' => $htag, 'links' => $links, 'items' => $items, 'kind' => ( $news !== null ? 'newsletter' : ( $social_n >= 2 ? 'social' : $kind ) ), 'rows' => ( $kind === 'contact' ? $rows : array() ), 'newsletter' => $news, 'cls' => self::cls( $parent ), 'append_social' => ( $social_n >= 2 ) );
					$seen[ $title ] = true;
				}
				if ( count( $out ) >= 8 ) { break; }
			}
		}
		return $out;
	}

	/**
	 * A single footer CONTACT row from an `<li>`: its leading inline-icon (verbatim svg markup), the icon's
	 * color (the `text-primary` green — from data-sc-cs / a text-* class), and the row VALUE as HTML with line
	 * breaks preserved (a `<br>` inside the address `<span>` survives as `<br>`, so "123 Fresh Meadow Lane" and
	 * "Springfield, SP 12345" don't glue together). Returns null when the `<li>` has no meaningful text.
	 * Shape: array( 'icon' => <svg markup|''>, 'color' => <css color|''>, 'html' => <value html> ).
	 */
	private static function footer_contact_row( $li ) {
		if ( ! ( $li instanceof DOMElement ) ) { return null; }
		$dom = $li->ownerDocument;
		// Leading icon: the first descendant <svg> (Lucide inline mark). Keep it verbatim (small guard).
		$icon = ''; $color = '';
		foreach ( $li->getElementsByTagName( 'svg' ) as $s ) {
			$m = $dom ? $dom->saveHTML( $s ) : '';
			if ( is_string( $m ) && $m !== '' && strlen( $m ) < 8000 ) { $icon = $m; }
			$color = self::sc_css( $s, 'color' );
			// The root <svg> often carries no computed style — read the tint off a painted descendant
			// (its `currentColor` stroke resolves there, e.g. the green `text-primary` on a child path/circle).
			if ( $color === '' ) {
				foreach ( $s->getElementsByTagName( '*' ) as $ch ) { $cc = self::sc_css( $ch, 'color' ); if ( $cc !== '' ) { $color = $cc; break; } }
			}
			break;
		}
		// Row value: prefer the text-bearing <span>/<p>/<a>; keep <br>s as line breaks. Strip icon svgs.
		$val = null;
		foreach ( array( 'span', 'p', 'a' ) as $t ) { $n = $li->getElementsByTagName( $t )->item( 0 ); if ( $n ) { $val = $n; break; } }
		$src = $val instanceof DOMElement ? $val : $li;
		$clone = $src->cloneNode( true );
		foreach ( iterator_to_array( $clone->getElementsByTagName( 'svg' ) ) as $sv ) { if ( $sv->parentNode ) { $sv->parentNode->removeChild( $sv ); } }
		$inner = $dom ? $dom->saveHTML( $clone ) : '';
		// Keep <br>, drop every other tag, collapse whitespace → clean value HTML with line breaks intact.
		$inner = preg_replace( '~<br\s*/?>~i', "\n", (string) $inner );
		$inner = trim( preg_replace( '/[ \t]*\n[ \t]*/', "\n", preg_replace( '/[ \t]+/', ' ', wp_strip_all_tags( $inner ) ) ) );
		if ( $inner === '' ) { return null; }
		$html = str_replace( "\n", '<br>', esc_html( $inner ) );
		// Single-line value + destination link for a NATIVE icon_text element (the
		// icon_text field is single-line, so a multi-line address folds to one line
		// with commas). `link`: the row's tel:/mailto: (preferred) or first URL — so
		// the phone/email stay click-to-call/mail. `text` stays RAW (the element
		// escapes on render); `multiline` flags rows the Text-HTML fallback should keep.
		$text_line = trim( preg_replace( '/\s*,\s*/', ', ', str_replace( "\n", ', ', $inner ) ) );
		$link = '';
		// The row's own href counts too: a contact row is often the `<a href="mailto:…">` ITSELF (the "Get in
		// Touch" email), so getElementsByTagName('a') — which returns only DESCENDANTS — would miss it, dropping
		// the mailto/tel link (the row then failed the contact-column test and the whole column was lost).
		$anchors = array();
		if ( 'a' === strtolower( $li->nodeName ) ) { $anchors[] = $li; }
		foreach ( $li->getElementsByTagName( 'a' ) as $a ) { $anchors[] = $a; }
		foreach ( $anchors as $a ) {
			$href = trim( (string) $a->getAttribute( 'href' ) );
			if ( $href === '' || $href === '#' ) { continue; }
			if ( stripos( $href, 'tel:' ) === 0 || stripos( $href, 'mailto:' ) === 0 ) { $link = $href; break; }
			if ( $link === '' ) { $link = $href; }
		}
		return array( 'icon' => $icon, 'color' => $color, 'html' => $html, 'text' => $text_line, 'link' => $link, 'multiline' => ( strpos( $inner, "\n" ) !== false ) );
	}

	/**
	 * Build an icon-v2 value (inline-SVG mode) for a contact row's leading icon,
	 * from VERBATIM captured `<svg>` markup. The exact source glyph is preserved;
	 * the brand tint is baked in by resolving the Lucide `currentColor` stroke/fill
	 * to the row's captured colour (so the icon keeps its colour inside icon_text,
	 * whose glyph would otherwise inherit the footer text colour). Returns null when
	 * there is no usable markup.
	 *
	 * @param string $svg   Raw <svg>…</svg> markup.
	 * @param string $color CSS colour (e.g. 'rgb(33, 196, 93)') or ''.
	 * @return array|null   icon-v2 value { type, svg-source, markup, svg-id } or null.
	 */
	private static function contact_icon_v2( $svg, $color ) {
		$svg = trim( (string) $svg );
		if ( $svg === '' || ! preg_match( '/^<svg\b/i', $svg ) ) { return null; }
		if ( $color !== '' && stripos( $svg, 'currentcolor' ) !== false ) {
			$svg = str_ireplace( 'currentColor', $color, $svg );
		}
		return array( 'type' => 'svg', 'svg-source' => 'inline', 'markup' => $svg, 'svg-id' => '' );
	}

	/**
	 * Minimal inline SVG for a NAMED contact icon (the AI footer/header path gives an
	 * icon NAME — 'map-pin' | 'phone' | 'mail' | 'clock' — not markup). Simple generic
	 * geometric glyphs (not lifted from any icon set), stroke `currentColor` so they
	 * inherit the element colour. Returns '' for an unknown / empty name.
	 *
	 * @param string $name
	 * @return string <svg> markup or ''.
	 */
	private static function contact_icon_name_svg( $name ) {
		$name = strtolower( trim( (string) $name ) );
		if ( $name === '' ) { return ''; }
		$key = ( strpos( $name, 'pin' ) !== false || strpos( $name, 'map' ) !== false || strpos( $name, 'location' ) !== false || strpos( $name, 'marker' ) !== false ) ? 'pin'
			: ( ( strpos( $name, 'phone' ) !== false || strpos( $name, 'tel' ) !== false || strpos( $name, 'call' ) !== false ) ? 'phone'
			: ( ( strpos( $name, 'mail' ) !== false || strpos( $name, 'email' ) !== false || strpos( $name, 'envelope' ) !== false ) ? 'mail'
			: ( ( strpos( $name, 'clock' ) !== false || strpos( $name, 'time' ) !== false || strpos( $name, 'hour' ) !== false ) ? 'clock' : '' ) ) );
		$paths = array(
			'pin'   => '<path d="M12 21s-6-5.686-6-10a6 6 0 1 1 12 0c0 4.314-6 10-6 10z"/><circle cx="12" cy="11" r="2.2"/>',
			'phone' => '<path d="M6.5 4h3l1.4 3.5-2 1.4a11 11 0 0 0 5.2 5.2l1.4-2 3.5 1.4v3a2 2 0 0 1-2.2 2A16 16 0 0 1 4.5 6.2 2 2 0 0 1 6.5 4z"/>',
			'mail'  => '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3.5 6.5 8.5 6 8.5-6"/>',
			'clock' => '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
		);
		if ( $key === '' || ! isset( $paths[ $key ] ) ) { return ''; }
		return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' . $paths[ $key ] . '</svg>';
	}

	/**
	 * The footer's copyright-bar LEGAL links (Privacy / Terms / Cookies / Sitemap …) → [{label,href}]. These
	 * sit in the last footer band beside the © line and belong to the Copyright bar's SECOND column (a policy
	 * menu), not the main grid. Detected as the footer `<a>`s that are NOT social and NOT inside the main
	 * column grid — i.e. links that live in the same band as the © text. Empty when the footer has none.
	 */
	private static function detect_footer_legal_links( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return array(); }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return array(); }
		// Find the copyright © node, then collect the sibling links within its band.
		$band = null;
		$cp = self::footer_copyright_el( $footer );
		if ( $cp instanceof DOMElement ) { $band = $cp->parentNode instanceof DOMElement ? $cp->parentNode : null; } // the band that also holds the legal links
		if ( ! ( $band instanceof DOMElement ) ) { return array(); }
		// a ONE-ROW footer (logo | links | ©): the © shares its row with the BRAND and the main links — those are the menu, not
		// legal links; they were cloned into the copyright bar beneath the same links (a fixture from the feed)
		if ( self::footer_is_single_row( $footer ) ) { return array(); }
		$out = array();
		foreach ( $band->getElementsByTagName( 'a' ) as $a ) {
			$lbl = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $a ) ) );
			$hrf = trim( (string) $a->getAttribute( 'href' ) );
			if ( $lbl !== '' && self::social_lucide( $hrf ) === '' ) { $out[] = array( 'label' => $lbl, 'href' => $hrf ); }
			if ( count( $out ) >= 6 ) { break; }
		}
		return $out;
	}

	/**
	 * The footer's REAL background + text color, read from the captured `data-sc-cs` computed-style attribute
	 * on the <footer> element (the capture service records the resolved color there, e.g. a Tailwind
	 * `bg-foreground` → `background-color:rgb(41, 61, 54)`). Returns [ 'bg' => hex/rgb|'', 'text' => …|'' ].
	 * This fixes the "footer lost its dark background" regression: without it the mapping fell back to a
	 * generic `#141414`, dropping the source's actual (often brand-tinted) dark footer color.
	 */
	/**
	 * NEVER-DROP footer COLUMN-HEADING typography → a scoped `.footer-links-title` CSS rule (or '').
	 * Reads the first real footer column heading's computed style (from data-sc-cs): text-transform
	 * (uppercase), letter-spacing (`tracking-*`), font-weight, font-size, colour — the properties the
	 * footer builder has no native option for. Appended to the misc_custom_css chrome residual.
	 */
	private static function footer_heading_css( $html ) {
		$footer = self::footer_root_el( $html );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		$h = null;
		// the first COLUMN title: a heading whose parent holds a link list (≥ 2 links), else a LABEL div / span that opens one
		// (the same titles detect_footer_columns builds on) — never the footer's lead h2 ("Ready to float?" at 48px)
		$links_in = function ( $el ) { return ( $el->parentNode instanceof DOMElement ) ? $el->parentNode->getElementsByTagName( 'a' )->length : 0; };
		foreach ( array( 'h3', 'h4', 'h5', 'h6', 'h2' ) as $tag ) {
			foreach ( $footer->getElementsByTagName( $tag ) as $el ) {
				$t = trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) );
				if ( $t !== '' && str_word_count( $t ) <= 4 && ! self::band_is_copyright( $el ) && $links_in( $el ) >= 2 ) { $h = $el; break 2; }
			}
		}
		if ( ! ( $h instanceof DOMElement ) ) { foreach ( self::footer_label_heads( $footer ) as $lb ) { $h = $lb; break; } }
		if ( ! ( $h instanceof DOMElement ) ) {
			foreach ( array( 'h3', 'h4', 'h5', 'h6', 'h2' ) as $tag ) {
				foreach ( $footer->getElementsByTagName( $tag ) as $el ) {
					$t = trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) );
					if ( $t !== '' && str_word_count( $t ) <= 4 && ! self::band_is_copyright( $el ) ) { $h = $el; break 2; }
				}
			}
		}
		if ( ! ( $h instanceof DOMElement ) ) { return ''; }
		$decls = '';
		$ff = self::sc_css( $h, 'font-family' );      if ( $ff !== '' && stripos( $ff, 'inherit' ) === false ) { $decls .= 'font-family:' . $ff . ';'; }
		$tt = self::sc_css( $h, 'text-transform' );  if ( stripos( $tt, 'uppercase' ) !== false ) { $decls .= 'text-transform:uppercase;'; }
		$ls = self::sc_css( $h, 'letter-spacing' );  if ( $ls !== '' && $ls !== 'normal' && $ls !== '0px' ) { $decls .= 'letter-spacing:' . $ls . ';'; }
		$fw = self::sc_css( $h, 'font-weight' );     if ( preg_match( '/^(300|400|500|600|700|800|900)$/', trim( $fw ) ) ) { $decls .= 'font-weight:' . trim( $fw ) . ';'; }
		$fs = self::sc_css( $h, 'font-size' );        if ( preg_match( '/^[0-9.]+px$/', trim( $fs ) ) ) { $decls .= 'font-size:' . trim( $fs ) . ';'; }
		$c  = self::sc_css( $h, 'color' );            if ( $c !== '' ) { $decls .= 'color:' . $c . ';'; }
		// measured = authoritative: outranks the generated site-wide heading family (which is !important)
		$decls = str_replace( ';', ' !important;', $decls );
		return $decls !== '' ? '.footer-links-title{' . $decls . '}' : '';
	}

	/** Whether the capture's `data-sc-footer` stamp carries the named signal (e.g. `link-hover`, a measured colour). */
	private static function footer_stamp_has( $html, $key ) {
		if ( ! preg_match( '/<footer[^>]*\sdata-sc-footer="([^"]*)"/i', (string) $html, $fm ) ) { return false; }
		return (bool) preg_match( '/(?:^|;)\s*' . preg_quote( $key, '/' ) . '\s*:\s*[^;]+/i', html_entity_decode( $fm[1], ENT_QUOTES ) );
	}

	/**
	 * A utility colour token (`hover:text-<token>`) → the theme palette var it maps to (`var(--color-primary)`), or ''
	 * when the theme defines no such colour. Generic design-system names alias onto the theme's roles (brand →
	 * primary, background → bg, foreground → text); an unknown token (`brand-500`, `emerald-400`) yields '' rather
	 * than an undefined var that silently resolves to the resting colour.
	 */
	private static function palette_var_for_token( $token ) {
		$tok = preg_replace( '/[^a-z0-9-]/', '', strtolower( (string) $token ) );
		$alias = array( 'brand' => 'primary', 'background' => 'bg', 'foreground' => 'text', 'fg' => 'text', 'body' => 'text', 'inherit' => '', 'current' => '', 'transparent' => '' );
		if ( array_key_exists( $tok, $alias ) ) { $tok = $alias[ $tok ]; }
		$known = array( 'primary', 'secondary', 'accent', 'muted', 'ink', 'light', 'text', 'bg', 'border', 'white', 'black', 'gray', 'light-gray', 'blue-gray', 'red', 'pink', 'purple', 'deep-purple', 'indigo', 'blue', 'light-blue', 'cyan', 'teal', 'green', 'light-green', 'lime', 'yellow', 'orange', 'deep-orange', 'brown' );
		return ( $tok !== '' && in_array( $tok, $known, true ) ) ? 'var(--color-' . $tok . ')' : '';
	}

	/**
	 * NEVER-DROP footer LINK typography → a scoped `.footer-menu a` rule (or ''). Reads the first real footer
	 * nav link's DISTINCTIVE utilities (text-transform / letter-spacing / font-weight) — colour is already the
	 * native footer_link_color and size usually inherits, so only the residual look is carried here.
	 */
	private static function footer_link_css( $html ) {
		$footer = self::footer_root_el( $html );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		$a = null;
		foreach ( $footer->getElementsByTagName( 'li' ) as $li ) {
			foreach ( $li->getElementsByTagName( 'a' ) as $x ) {
				$t = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $x ) ) );
				$href = trim( (string) $x->getAttribute( 'href' ) );
				if ( $t !== '' && str_word_count( $t ) <= 4 && self::social_lucide( $href ) === '' ) { $a = $x; break 2; }
			}
		}
		if ( ! ( $a instanceof DOMElement ) ) { return ''; }
		$decls = '';
		$ff = self::sc_css( $a, 'font-family' );      if ( $ff !== '' && stripos( $ff, 'inherit' ) === false ) { $decls .= 'font-family:' . $ff . ';'; }
		$tt = self::sc_css( $a, 'text-transform' );  if ( stripos( $tt, 'uppercase' ) !== false ) { $decls .= 'text-transform:uppercase;'; }
		$ls = self::sc_css( $a, 'letter-spacing' );  if ( $ls !== '' && $ls !== 'normal' && $ls !== '0px' ) { $decls .= 'letter-spacing:' . $ls . ';'; }
		$fw = self::sc_css( $a, 'font-weight' );     if ( preg_match( '/^(300|400|500|600|700|800|900)$/', trim( $fw ) ) ) { $decls .= 'font-weight:' . trim( $fw ) . ';'; }
		$fs = self::sc_css( $a, 'font-size' );        if ( preg_match( '/^[0-9.]+px$/', trim( $fs ) ) ) { $decls .= 'font-size:' . trim( $fs ) . ';'; }
		// LINE-HEIGHT — the source footer text sets its own (e.g. 20px for 14px links); the theme's tighter
		// default (~15px) leaves the list looking cramped even once the item gap matches. Captured separately
		// so it can be applied to EVERY list item (links AND plain-text contact rows), which inherit it.
		$lh = trim( self::sc_css( $a, 'line-height' ) );
		$lh = ( $lh !== '' && $lh !== 'normal' && preg_match( '/^[0-9.]+(px|rem|em)$/', $lh ) ) ? $lh : '';
		// Retarget: footer links now render as `.footer-link` (the unified List Item), not `.footer-menu a`.
		$css = $decls !== '' ? '.footer-column .footer-link{' . $decls . '}' : '';
		// line-height on the list items so both the links and the non-link (address) rows breathe like the source.
		if ( $lh !== '' ) { $css .= '.footer-column .footer-links-list>li,.footer-column .footer-links-list .list-item__text{line-height:' . $lh . '}'; }
		// Hover colour (`hover:text-<token>`) → the theme's Color-Preset var (portable + editable) — ONLY when the
		// capture did not MEASURE the hover (`data-sc-footer` link-hover → the native footer_link_hover_color option,
		// which this scoped rule would out-rank at (0,3,0) and make un-editable), and only for a token the theme
		// actually defines: `hover:text-brand` emitted `var(--color-brand)`, which no palette declares, so the
		// hover resolved to the resting colour and the source's green never showed (a real-site report).
		if ( ! self::footer_stamp_has( $html, 'link-hover' ) && preg_match( '/hover:text-([a-z][a-z0-9-]*)/', self::cls( $a ), $hm ) ) {
			$var = self::palette_var_for_token( $hm[1] );
			if ( $var !== '' ) { $css .= '.footer-column .footer-link:hover{color:' . $var . '}'; }
		}
		// LIST-ITEM SPACING — the source's footer link list sets its own vertical rhythm (a `space-y-4`/`gap-4`
		// utility on the <ul>, or a real computed margin/gap), which the theme's default `.footer-links-list>li
		// {margin:0 0 .5rem}` (8px) doesn't match — so a source with 16px gaps renders visibly cramped. Read the
		// list gap and, when it differs from the 8px default, emit a scoped `li` margin so the rhythm matches.
		$gap = self::footer_list_gap_px( $a );
		if ( $gap > 0 && abs( $gap - 8 ) >= 1 ) {
			$css .= '.footer-column .footer-links-list>li:not(:last-child){margin-bottom:' . $gap . 'px}';
		}
		return $css;
	}

	/**
	 * Resolve the vertical spacing (px) a footer link list uses between its items, from the FIRST link node
	 * `$a`. Sources: (1) a Tailwind `space-y-<n>` / `gap-y-<n>` / `gap-<n>` utility on the nearest <ul>/list
	 * container (n × 4px — the Tailwind spacing scale); (2) the computed `row-gap`/`gap` on the container
	 * (data-sc-cs); (3) the computed `margin-top` a `space-y-*` stamps on a following sibling `<li>`. Returns
	 * 0 when nothing usable is found (the theme's 8px default then stands).
	 */
	private static function footer_list_gap_px( $a ) {
		if ( ! ( $a instanceof DOMElement ) ) { return 0; }
		$px = function ( $v ) {
			$v = trim( (string) $v );
			if ( preg_match( '/^([0-9.]+)px$/', $v, $m ) )  { return (float) $m[1]; }
			if ( preg_match( '/^([0-9.]+)rem$/', $v, $m ) ) { return (float) $m[1] * 16; }
			return 0.0;
		};
		// Walk up to the enclosing list container (<ul>/<ol>/<nav>), reading utilities + computed gap.
		$node = $a;
		for ( $i = 0; $i < 6 && $node instanceof DOMElement; $i++ ) {
			$tag = strtolower( $node->tagName );
			$cls = ' ' . strtolower( (string) $node->getAttribute( 'class' ) ) . ' ';
			if ( preg_match( '/\s(?:space-y|gap-y|gap)-(\d+(?:\.\d+)?)\s/', $cls, $m ) ) { return (float) $m[1] * 4; }
			$cs = (string) $node->getAttribute( 'data-sc-cs' );
			if ( $cs !== '' && preg_match( '/(?:^|;)\s*(?:row-)?gap\s*:\s*([0-9.]+(?:px|rem))/i', $cs, $m ) ) { $g = $px( $m[1] ); if ( $g > 0 ) { return $g; } }
			if ( in_array( $tag, array( 'ul', 'ol', 'nav' ), true ) ) {
				// space-y-* stamps margin-top on the 2nd+ child — read it off a following sibling <li>.
				$lis = $node->getElementsByTagName( 'li' );
				if ( $lis->length >= 2 && $lis->item( 1 ) instanceof DOMElement ) {
					$mt = self::sc_css( $lis->item( 1 ), 'margin-top' ); $g = $px( $mt ); if ( $g > 0 ) { return $g; }
				}
				break;
			}
			$node = $node->parentNode;
		}
		return 0;
	}

	/**
	 * NEVER-DROP — the ONE complete translator for a text/content element's SIGNIFICANT layout + typography,
	 * from its computed (data-sc-cs) style: `max-width` (a measure), `margin` top/bottom (spacing — incl. the
	 * shorthand the capture stamps), `padding`, `line-height`, `letter-spacing`, `font-size/weight/style`,
	 * `text-align`, `text-transform`, `color`. Returns a CSS declaration string for a SCOPED rule (or '' when
	 * nothing notable). Behind the per-element footer/body text emit sites, so no property gets forgotten
	 * per-case (the old hand-picked helpers each missed max-width / margin — this is the fix for THAT).
	 *
	 * @param string $cs        a data-sc-cs computed-style string.
	 * @param array  $skip      props already carried by a native option at the call site (don't double-emit).
	 * @param bool   $important append `!important` — for a scoped footer rule that must beat the theme's own
	 *                          `.footer-element` resets (e.g. a last-child `margin-bottom:0`) to reproduce
	 *                          the source spacing/measure exactly.
	 */
	private static function significant_text_decls( $cs, array $skip = array(), $important = false ) {
		$cs = (string) $cs;
		if ( $cs === '' ) { return ''; }
		$bang = $important ? ' !important' : '';
		$raw = array();
		foreach ( explode( ';', $cs ) as $d ) { $d = trim( $d ); $cp = strpos( $d, ':' ); if ( $cp === false ) { continue; } $raw[ trim( substr( $d, 0, $cp ) ) ] = trim( substr( $d, $cp + 1 ) ); }
		// Expand the margin/padding SHORTHAND (the capture stamps `margin:0px 0px 32px`, not per-edge longhands).
		foreach ( array( 'margin', 'padding' ) as $bx ) {
			if ( empty( $raw[ $bx ] ) || strpos( $raw[ $bx ], 'var(' ) !== false ) { continue; }
			$pp = preg_split( '/\s+/', trim( $raw[ $bx ] ) ); $t = $pp[0]; $r = isset( $pp[1] ) ? $pp[1] : $t; $b = isset( $pp[2] ) ? $pp[2] : $t; $l = isset( $pp[3] ) ? $pp[3] : $r;
			foreach ( array( 'top' => $t, 'right' => $r, 'bottom' => $b, 'left' => $l ) as $side => $v ) { if ( ! isset( $raw[ $bx . '-' . $side ] ) ) { $raw[ $bx . '-' . $side ] = $v; } }
		}
		$out = '';
		$add = function ( $prop, $val ) use ( &$out, $skip, $bang ) { if ( ! in_array( $prop, $skip, true ) ) { $out .= $prop . ':' . $val . $bang . ';'; } };
		$g   = function ( $k ) use ( $raw ) { return isset( $raw[ $k ] ) ? trim( (string) $raw[ $k ] ) : ''; };
		$mw = $g( 'max-width' );      if ( $mw !== '' && $mw !== 'none' && preg_match( '/^[0-9.]+(px|rem|em|%|ch|vw)$/', $mw ) ) { $add( 'max-width', $mw ); }
		foreach ( array( 'margin-top', 'margin-bottom', 'padding-top', 'padding-bottom', 'padding-left', 'padding-right' ) as $bp ) { $v = $g( $bp ); if ( preg_match( '/^[0-9.]+(px|rem|em)$/', $v ) && (float) $v > 0 ) { $add( $bp, $v ); } }
		$fs = $g( 'font-size' );      if ( preg_match( '/^[0-9.]+px$/', $fs ) ) { $add( 'font-size', $fs ); }
		$lh = $g( 'line-height' );    if ( $lh !== '' && $lh !== 'normal' && $lh !== '0px' && preg_match( '/^[0-9.]+(px|rem|em)?$/', $lh ) ) { $add( 'line-height', $lh ); }
		$ls = $g( 'letter-spacing' ); if ( $ls !== '' && $ls !== 'normal' && $ls !== '0px' && preg_match( '/^-?[0-9.]+px$/', $ls ) ) { $add( 'letter-spacing', $ls ); }
		$fw = $g( 'font-weight' );    if ( preg_match( '/^(?:[5-9]00|bold)$/', $fw ) ) { $add( 'font-weight', $fw ); }
		if ( 'italic' === $g( 'font-style' ) ) { $add( 'font-style', 'italic' ); }
		$tt = strtolower( $g( 'text-transform' ) ); if ( in_array( $tt, array( 'uppercase', 'lowercase', 'capitalize' ), true ) ) { $add( 'text-transform', $tt ); }
		$ta = strtolower( $g( 'text-align' ) );     if ( in_array( $ta, array( 'center', 'right' ), true ) ) { $add( 'text-align', $ta ); }
		$c  = $g( 'color' );          if ( $c !== '' && stripos( $c, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0(?:\.0+)?\s*\)/', $c ) ) { $add( 'color', $c ); }
		return $out;
	}

	/**
	 * NEVER-DROP footer TAGLINE typography → a scoped `.footer-tagline` rule (or ''). Finds the same tagline
	 * `<p>` detect_footer_tagline() emits (the first long, non-copyright paragraph) and carries its FULL
	 * significant style (max-width / margin / line-height / colour / …) via significant_text_decls — the
	 * tagline text element has no native typography option. The emit tags the paragraph with the
	 * `footer-tagline` class so this rule has something to paint.
	 */
	private static function footer_tagline_css( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return ''; }
		$p = null;
		foreach ( $footer->getElementsByTagName( 'p' ) as $x ) {
			$t = trim( preg_replace( '/\s+/', ' ', (string) $x->textContent ) );
			if ( $t !== '' && strlen( $t ) >= 40 && strpos( $t, '©' ) === false && stripos( $t, 'rights reserved' ) === false && stripos( $t, 'copyright' ) === false ) { $p = $x; break; }
		}
		if ( ! ( $p instanceof DOMElement ) ) { return ''; }
		$decls = self::significant_text_decls( (string) $p->getAttribute( 'data-sc-cs' ), array(), true );
		return $decls !== '' ? '.footer-tagline{' . $decls . '}' : '';
	}

	/**
	 * CHROME never-drop AUDIT — the dropped-class QA gate extended to chrome. For the logo, first menu link
	 * and first footer heading, map each VISUALLY-SIGNIFICANT source utility to the CSS property it controls
	 * and check whether that property was carried (a native option OR the element's scoped custom CSS). Any
	 * significant class that landed nowhere is a silent style loss. Returns [ where => [class, …] ] (empty =
	 * clean). Content has its own gate (dropped_measures); this is the chrome twin.
	 *
	 * @return array<string,string[]>
	 */
	private static function chrome_dropped_classes( $html, array $values ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return array(); }
		// Map a significant typography/colour utility → the CSS property it controls ('' = inert/ignored).
		$prop_of = function ( $c ) {
			if ( preg_match( '/^(?:[a-z0-9]+:)*font-(serif|mono|sans)$/', $c ) ) { return 'font-family'; }
			if ( preg_match( '/^(?:[a-z0-9]+:)*font-(thin|extralight|light|normal|medium|semibold|bold|extrabold|black)$/', $c ) ) { return 'font-weight'; }
			if ( preg_match( '/^(?:[a-z0-9]+:)*tracking-/', $c ) ) { return 'letter-spacing'; }
			if ( preg_match( '/^(?:[a-z0-9]+:)*(uppercase|lowercase|capitalize)$/', $c ) ) { return 'text-transform'; }
			if ( preg_match( '/^(?:[a-z0-9]+:)*(italic|not-italic)$/', $c ) ) { return 'font-style'; }
			if ( preg_match( '/^hover:text-/', $c ) ) { return 'hover-color'; }
			if ( preg_match( '/^(?:[a-z0-9]+:)*text-(xs|sm|base|lg|xl|[0-9]xl|\[)/', $c ) ) { return 'font-size'; }
			if ( preg_match( '/^(?:[a-z0-9]+:)*text-(?!left$|center$|right$|justify$|nowrap$|wrap$|balance$|pretty$|ellipsis$|clip$)[a-z]/', $c ) ) { return 'color'; }
			return '';
		};
		$audit = function ( $el, array $carried ) use ( $prop_of ) {
			if ( ! ( $el instanceof DOMElement ) ) { return array(); }
			$out = array();
			foreach ( preg_split( '/\s+/', self::cls( $el ), -1, PREG_SPLIT_NO_EMPTY ) as $c ) {
				$p = $prop_of( $c );
				if ( $p !== '' && empty( $carried[ $p ] ) ) { $out[] = $c; }
			}
			return $out;
		};

		$result = array();
		$has = function ( $s, $needle ) { return false !== strpos( (string) $s, $needle ); };

		/* --- LOGO: native color/weight/size + logo_custom_css (font-family/letter-spacing/hover). --- */
		$lc       = $values['header_logo']['logo_type']['custom'] ?? array();
		$logo_css = (string) ( $lc['logo_custom_css'] ?? '' );
		$logo_carried = array(
			'font-family'    => $has( $logo_css, 'font-family' ),
			'letter-spacing' => $has( $logo_css, 'letter-spacing' ),
			'hover-color'    => $has( $logo_css, ':hover' ),
			'text-transform' => $has( $logo_css, 'text-transform' ),
			'font-style'     => $has( $logo_css, 'font-style' ),
			'color'          => ! empty( $lc['color']['custom'] ) || ! empty( $lc['color']['predefined'] ),
			'font-weight'    => ! empty( $lc['title_weight'] ),
			'font-size'      => ! empty( $lc['title_size'] ),
		);
		/* --- MENU: the native menu_link_* options. --- */
		$mv = $values['header_menu'] ?? array();
		$menu_carried = array(
			'letter-spacing' => isset( $mv['menu_link_letter_spacing'] ),
			'text-transform' => isset( $mv['menu_link_uppercase'] ),
			'font-weight'    => isset( $mv['menu_link_font_weight'] ),
			'font-size'      => isset( $mv['menu_link_font_size'] ),
			'color'          => isset( $mv['menu_link_color'] ),
			'hover-color'    => isset( $mv['menu_link_hover_color'] ),
			'font-family'    => ! empty( $mv['menu_font']['family'] ),
			'font-style'     => false,
		);
		/* --- FOOTER heading: the scoped .footer-links-title rule in the misc_custom_css residual. --- */
		$misc = (string) ( $values['misc_custom_css']['custom_css'] ?? '' );
		$fh_rule = preg_match( '/\.footer-links-title\{([^}]*)\}/', $misc, $fhm ) ? $fhm[1] : '';
		$fh_carried = array(
			'text-transform' => $has( $fh_rule, 'text-transform' ),
			'letter-spacing' => $has( $fh_rule, 'letter-spacing' ),
			'font-weight'    => $has( $fh_rule, 'font-weight' ),
			'font-size'      => $has( $fh_rule, 'font-size' ),
			'color'          => $has( $fh_rule, 'color' ),
			'font-family'    => $has( $fh_rule, 'font-family' ),
			'hover-color'    => false,
			'font-style'     => false,
		);
		/* --- FOOTER links: the scoped .footer-menu a rule (transform/tracking/weight) + native link colour. --- */
		$fl_rule = preg_match( '/\.footer-menu a\{([^}]*)\}/', $misc, $flm ) ? $flm[1] : '';
		$fl_carried = array(
			'text-transform' => $has( $fl_rule, 'text-transform' ),
			'letter-spacing' => $has( $fl_rule, 'letter-spacing' ),
			'font-weight'    => $has( $fl_rule, 'font-weight' ),
			'font-size'      => $has( $fl_rule, 'font-size' ),
			'color'          => isset( $values['footer_link_color'] ),
			'hover-color'    => $has( $misc, '.footer-menu a:hover' ),
			'font-family'    => false,
			'font-style'     => false,
		);

		/* --- find the source elements + audit each. --- */
		$header = $dom->getElementsByTagName( 'header' )->item( 0 );
		$is_home = function ( $a ) { $h = trim( (string) $a->getAttribute( 'href' ) ); return ( $h === '' || $h === '#' || $h === '/' || (bool) preg_match( '~^https?://[^/]+/?$~', $h ) ); };
		if ( $header instanceof DOMElement ) {
			$logo_a = null;
			foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
				if ( $is_home( $a ) && trim( self::text_no_icons( $a ) ) !== '' ) { $logo_a = $a; break; }
			}
			if ( $logo_a ) { $d = $audit( $logo_a, $logo_carried ); if ( $d ) { $result['logo'] = $d; } }
			$menu_a = null;
			foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
				if ( $a === $logo_a || self::is_button( $a ) ) { continue; }
				if ( $a->getElementsByTagName( 'svg' )->length || $a->getElementsByTagName( 'img' )->length ) { continue; }
				if ( $is_home( $a ) ) { $hfs = self::sc_css( $a, 'font-size' ); if ( preg_match( '/([0-9.]+)px/', $hfs, $hm ) && (float) $hm[1] >= 20 ) { continue; } }
				if ( trim( self::text_no_icons( $a ) ) !== '' && str_word_count( trim( self::text_no_icons( $a ) ) ) <= 4 ) { $menu_a = $a; break; }
			}
			if ( $menu_a ) { $d = $audit( $menu_a, $menu_carried ); if ( $d ) { $result['menu'] = $d; } }
		}
		$footer = self::footer_root_el( $html );
		if ( $footer instanceof DOMElement ) {
			$fh = null;
			foreach ( array( 'h3', 'h4', 'h5', 'h6', 'h2' ) as $tag ) {
				foreach ( $footer->getElementsByTagName( $tag ) as $el ) {
					$t = trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) );
					if ( $t !== '' && str_word_count( $t ) <= 4 && ! self::band_is_copyright( $el ) ) { $fh = $el; break 2; }
				}
			}
			if ( $fh ) { $d = $audit( $fh, $fh_carried ); if ( $d ) { $result['footer_heading'] = $d; } }
			$fl = null;
			foreach ( $footer->getElementsByTagName( 'li' ) as $li ) {
				foreach ( $li->getElementsByTagName( 'a' ) as $x ) {
					$t = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $x ) ) );
					if ( $t !== '' && str_word_count( $t ) <= 4 && self::social_lucide( trim( (string) $x->getAttribute( 'href' ) ) ) === '' ) { $fl = $x; break 2; }
				}
			}
			if ( $fl ) { $d = $audit( $fl, $fl_carried ); if ( $d ) { $result['footer_link'] = $d; } }
			// Tagline (the first long, non-copyright <p>) — carried via the `.footer-tagline` residual rule.
			$ft_rule = preg_match( '/\.footer-tagline\{([^}]*)\}/', $misc, $ftm ) ? $ftm[1] : '';
			$ft_carried = array(
				'font-size'      => $has( $ft_rule, 'font-size' ),
				'color'          => $has( $ft_rule, 'color' ),
				'font-weight'    => $has( $ft_rule, 'font-weight' ),
				'letter-spacing' => $has( $ft_rule, 'letter-spacing' ),
				'text-transform' => $has( $ft_rule, 'text-transform' ),
				'font-family'    => $has( $ft_rule, 'font-family' ),
				'hover-color'    => false,
				'font-style'     => false,
			);
			$tag = null;
			foreach ( $footer->getElementsByTagName( 'p' ) as $x ) {
				$t = trim( preg_replace( '/\s+/', ' ', (string) $x->textContent ) );
				if ( $t !== '' && strlen( $t ) >= 40 && strpos( $t, '©' ) === false && stripos( $t, 'rights reserved' ) === false && stripos( $t, 'copyright' ) === false ) { $tag = $x; break; }
			}
			if ( $tag ) { $d = $audit( $tag, $ft_carried ); if ( $d ) { $result['footer_tagline'] = $d; } }
		}
		return $result;
	}

	/** A non-transparent `background-color` value from a data-sc-cs string, or '' (transparent / absent). */
	private static function sc_cs_bg( $cs ) {
		if ( (string) $cs === '' ) { return ''; }
		if ( preg_match( '/(?:^|;)\s*background-color\s*:\s*([^;]+)/i', $cs, $m ) ) {
			$c = trim( $m[1] );
			if ( $c !== '' && stripos( $c, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/i', $c ) ) { return $c; }
		}
		return '';
	}

	/** Relative luminance (0..1) of a hex / rgb(a) colour, or null if unparseable. For a contrast sanity check. */
	private static function rel_luma( $color ) {
		$s = trim( (string) $color );
		if ( preg_match( '/^#?([0-9a-f]{6})$/i', $s, $m ) ) {
			$r = hexdec( substr( $m[1], 0, 2 ) ); $g = hexdec( substr( $m[1], 2, 2 ) ); $b = hexdec( substr( $m[1], 4, 2 ) );
		} elseif ( preg_match( '/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/i', $s, $m ) ) {
			$r = (int) $m[1]; $g = (int) $m[2]; $b = (int) $m[3];
		} else { return null; }
		return ( 0.2126 * $r + 0.7152 * $g + 0.0587 * $b ) / 255;
	}

	/**
	 * Detect a leading UTILITY / TOP BAR inside the source <header> — a short full-width row ABOVE the main
	 * logo/nav row (e.g. a dark strip with a certification badge + star reviews + language). Returns its
	 * left/center/right text, its background + text colour, and whether the source hides it below md.
	 *
	 * @param string $html
	 * @return array{has:bool,left:string,center:string,right:string,bg:string,text:string,mobile_hide:bool}
	 */
	/** Styled inner HTML for one top-bar cell (for a custom_html element, which — unlike a text element —
	 *  does NOT scrub inline styles): a pill/badge keeps its captured background, ★ svgs become unicode stars
	 *  in their captured amber colour, plain text stays. */
	private static function topbar_cell_html( $g, $tcolor ) {
		$stars = 0; $scolor = '';
		foreach ( $g->getElementsByTagName( 'svg' ) as $sv ) { if ( stripos( self::cls( $sv ), 'star' ) !== false ) { $stars++; if ( '' === $scolor ) { $scolor = self::sc_css( $sv, 'color' ); } } }
		$badge = null; $badge_bg = '';
		foreach ( $g->getElementsByTagName( '*' ) as $e ) { $b = self::sc_cs_bg( (string) $e->getAttribute( 'data-sc-cs' ) ); if ( '' !== $b ) { $badge = $e; $badge_bg = $b; break; } }
		$full = trim( preg_replace( '/\s+/', ' ', self::text( $g ) ) );
		if ( '' === $full && 0 === $stars ) { return ''; }
		if ( $badge instanceof DOMElement ) {
			$bt = trim( preg_replace( '/\s+/', ' ', self::text( $badge ) ) );
			$bc = self::sc_css( $badge, 'color' ); if ( '' === $bc ) { $bc = '#ffffff'; }
			$html = '<span style="display:inline-block;background:' . esc_attr( $badge_bg ) . ';color:' . esc_attr( $bc ) . ';padding:2px 12px;border-radius:4px;font-size:11px;font-weight:600">' . esc_html( $bt ) . '</span>';
			$rest = trim( str_replace( $bt, '', $full ) );
			if ( '' !== $rest ) { $html .= ' ' . esc_html( $rest ); }
			return $html;
		}
		$html = '';
		if ( $stars > 0 ) { $html .= '<span style="color:' . esc_attr( '' !== $scolor ? $scolor : '#f59e0b' ) . '">' . str_repeat( '★', min( $stars, 5 ) ) . '</span> '; }
		$html .= esc_html( $full );
		return trim( $html );
	}

	/**
	 * A leading header bar that is an auto-scrolling ANNOUNCEMENT TICKER (a `<marquee>`, or a single text track
	 * with a marquee/scroll animation) rather than left/center/right utility groups → its UNIQUE announcement
	 * phrase. The source repeats the phrase to fill the track ("BOOK A TABLE · THE NEW MENU IS HERE · RESERVE
	 * YOUR SPOT · BOOK A TABLE · …"); we dedupe back to one cycle so the topbar shows it once. '' when the bar
	 * isn't a ticker.
	 */
	private static function topbar_ticker_text( $bar ) {
		if ( ! ( $bar instanceof DOMElement ) ) { return ''; }
		$is_ticker = $bar->getElementsByTagName( 'marquee' )->length > 0;
		if ( ! $is_ticker ) {
			$nodes = array( $bar );
			foreach ( $bar->getElementsByTagName( '*' ) as $d ) { if ( $d instanceof DOMElement ) { $nodes[] = $d; } }
			foreach ( $nodes as $d ) {
				$sig = ' ' . strtolower( (string) $d->getAttribute( 'data-sc-cs' ) ) . ' ' . strtolower( self::cls( $d ) ) . ' ';
				if ( preg_match( '/animation[^;"\']*(?:marquee|scroll|ticker)|animate-(?:marquee|scroll)|\b(?:marquee|ticker)\b/', $sig ) ) { $is_ticker = true; break; }
			}
		}
		if ( ! $is_ticker ) { return ''; }
		$t = trim( preg_replace( '/\s+/', ' ', (string) self::text( $bar ) ) );
		if ( '' === $t ) { return ''; }
		// Dedupe the repeated cycle: split on the separator (·/•/|/–/—) and keep segments until the first repeats.
		$parts = preg_split( '/\s*[·•|–—]\s*/u', $t, -1, PREG_SPLIT_NO_EMPTY );
		$parts = array_values( array_filter( array_map( 'trim', (array) $parts ) ) );
		if ( count( $parts ) >= 2 ) {
			$cycle = array();
			foreach ( $parts as $i => $seg ) { if ( $i > 0 && 0 === strcasecmp( $seg, $parts[0] ) ) { break; } $cycle[] = $seg; }
			$seen = array(); $uniq = array();
			foreach ( $cycle as $seg ) { $k = mb_strtolower( $seg ); if ( ! isset( $seen[ $k ] ) ) { $seen[ $k ] = 1; $uniq[] = $seg; } }
			$phrase = implode( ' · ', $uniq );
		} else {
			$phrase = $t;
		}
		return ( mb_strlen( $phrase ) > 240 ) ? '' : $phrase; // absurdly long → not a real announcement
	}

	private static function detect_topbar( $html ) {
		$out = array( 'has' => false, 'left' => '', 'center' => '', 'right' => '', 'bg' => '', 'text' => '', 'mobile_hide' => false, 'ticker' => '' );
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return $out; }
		$children = self::el_children( $header );
		if ( count( $children ) < 2 ) { return $out; } // a single row → no top bar

		// The MAIN row is the direct child that contains the <nav> (or, lacking one, the logo). The top bar is
		// a direct child that comes BEFORE it — take the first child when it precedes the main row.
		$nav = null;
		foreach ( $header->getElementsByTagName( 'nav' ) as $n ) { $nav = $n; break; }
		$main_idx = -1;
		foreach ( $children as $i => $ch ) {
			$is_main = false;
			if ( $nav instanceof DOMElement ) { $p = $nav; while ( $p ) { if ( $p === $ch ) { $is_main = true; break; } $p = $p->parentNode; } }
			if ( $is_main ) { $main_idx = $i; break; }
		}
		if ( $main_idx < 1 ) { return $out; } // nothing sits above the main row
		$bar  = $children[0];
		$bcls = ' ' . strtolower( self::cls( $bar ) ) . ' ';

		// The bar's painted background (itself or a painted descendant).
		$bg = self::sc_cs_bg( (string) $bar->getAttribute( 'data-sc-cs' ) );
		if ( '' === $bg ) { foreach ( $bar->getElementsByTagName( '*' ) as $d ) { $bg = self::sc_cs_bg( (string) $d->getAttribute( 'data-sc-cs' ) ); if ( '' !== $bg ) { break; } } }
		// A utility bar is short: a distinct fill, or small (text-xs/text-sm) type. Otherwise it's not a top bar.
		if ( '' === $bg && strpos( $bcls, ' text-xs ' ) === false && strpos( $bcls, ' text-sm ' ) === false ) { return $out; }

		$txt = self::sc_css( $bar, 'color' );

		// SCROLLING ANNOUNCEMENT TICKER — the bar is a single auto-scrolling marquee (not left/center/right
		// utility groups), so the group scan below would find no cells and drop the bar entirely. Capture its
		// unique phrase and mark it a ticker; the header emit reproduces it as a scrolling strip in the topbar.
		$ticker = self::topbar_ticker_text( $bar );
		if ( '' !== $ticker ) {
			// Ticker text COLOUR = the scrolling track's own colour (white on the red bar), not the bar
			// wrapper's default dark ink — else the announcement is dark-on-red and unreadable. Read the first
			// text-bearing descendant's computed colour; fall back to the bar colour, then white on a real bg.
			$tk_color = '';
			foreach ( $bar->getElementsByTagName( '*' ) as $d ) {
				if ( ! ( $d instanceof DOMElement ) ) { continue; }
				if ( '' === trim( (string) self::text( $d ) ) ) { continue; }
				$c = self::sc_css( $d, 'color' );
				if ( '' !== $c ) { $tk_color = $c; break; }
			}
			if ( '' === $tk_color ) { $tk_color = ( '' !== $txt ) ? $txt : ''; }
			if ( '' === $tk_color && '' !== $bg ) { $tk_color = '#ffffff'; } // saturated bar, no readable ink → white
			$out['has']         = true;
			$out['ticker']      = $ticker;
			$out['bg']          = $bg;
			$out['text']        = $tk_color;
			$out['mobile_hide'] = ( strpos( $bcls, ' hidden ' ) !== false && (bool) preg_match( '/\s(?:sm|md|lg|xl):(?:block|flex|grid)/', $bcls ) );
			return $out;
		}

		// Content: bar → inner container → left / (center) / right groups (a flex justify-between row). Each
		// group is turned into STYLED HTML (badge pill kept, ★ svgs → unicode in their amber colour) so the
		// top bar's look survives — carried via a custom_html element, not a text element that scrubs styles.
		$container = $bar;
		foreach ( self::el_children( $bar ) as $cc ) { $container = $cc; break; }
		$cells = array();
		foreach ( self::el_children( $container ) as $g ) {
			$h = self::topbar_cell_html( $g, ( '' !== $txt ? $txt : '#ffffff' ) );
			if ( '' !== $h ) { $cells[] = $h; }
		}
		if ( ! $cells ) { return $out; }
		$n = count( $cells );
		if ( 1 === $n )      { $out['left'] = $cells[0]; }
		elseif ( 2 === $n )  { $out['left'] = $cells[0]; $out['right'] = $cells[1]; }
		else                 { $out['left'] = $cells[0]; $out['center'] = $cells[1]; $out['right'] = implode( '  ', array_slice( $cells, 2 ) ); }

		$out['has']         = true;
		$out['bg']          = $bg;
		$out['text']        = $txt;
		$out['mobile_hide'] = ( strpos( $bcls, ' hidden ' ) !== false && (bool) preg_match( '/\s(?:sm|md|lg|xl):(?:block|flex|grid)/', $bcls ) );
		return $out;
	}

	private static function detect_footer_style( $html ) {
		$out = array( 'bg' => '', 'text' => '' );
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return $out; }
		$cs = (string) $footer->getAttribute( 'data-sc-cs' );
		// The <footer> element is often transparent (Tailwind/SPA footers paint the fill on an inner
		// wrapper). Read its own background-color; if none, WALK DESCENDANTS for the first element that
		// carries a real one — otherwise the mapper falls back to palette-dark and yields a dark-on-dark band.
		$bg = self::sc_cs_bg( $cs );
		if ( $bg === '' ) {
			foreach ( $footer->getElementsByTagName( '*' ) as $d ) {
				$bg = self::sc_cs_bg( (string) $d->getAttribute( 'data-sc-cs' ) );
				if ( $bg !== '' ) { break; }
			}
		}
		$out['bg'] = $bg;
		// Footer TEXT colour: the <footer> element's OWN computed colour is usually just the inherited body
		// ink (near-white on a dark footer), NOT the muted colour the footer content actually uses. Sample
		// the dominant colour across the footer's real body text (links / list items / paragraphs) instead
		// — the source's slate-400 links, not the inherited white. Fall back to the footer's own colour.
		$text = self::sample_text_color( $footer );
		if ( $text === '' && preg_match( '/(?:^|;)\s*color\s*:\s*([^;]+)/i', $cs, $m ) ) { $text = trim( $m[1] ); }
		$out['text'] = $text;
		return $out;
	}

	/** The DOMINANT computed text colour across an element's real body text (links, list items, paragraphs),
	 *  from data-sc-cs. '' when nothing carries a computed colour. Used for the footer's default text colour. */
	private static function sample_text_color( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$counts = array();
		foreach ( array( 'a', 'li', 'p' ) as $tg ) {
			foreach ( $el->getElementsByTagName( $tg ) as $t ) {
				$c = self::sc_css( $t, 'color' );
				if ( $c === '' || stripos( $c, 'transparent' ) !== false ) { continue; }
				$counts[ $c ] = ( isset( $counts[ $c ] ) ? $counts[ $c ] : 0 ) + 1;
			}
		}
		if ( ! $counts ) { return ''; }
		arsort( $counts );
		return (string) key( $counts );
	}

	/**
	 * Read a padding side ('top'|'bottom') from an element's computed style, handling BOTH the `padding-top`
	 * longhand AND the `padding` shorthand (`padding:T R B L` / `T V` / `T RL B` — the capture often emits
	 * the shorthand, e.g. the golden fixture footer `padding:64px 0px 32px`). Returns the length string or ''.
	 */
	private static function sc_pad( $el, $side ) {
		$long = self::sc_css( $el, 'padding-' . $side );
		if ( $long !== '' ) { return $long; }
		$sh = self::sc_css( $el, 'padding' );
		if ( $sh === '' ) { return ''; }
		$p = preg_split( '/\s+/', trim( $sh ) );
		$n = count( $p );
		if ( $n === 1 ) { return $p[0]; }
		if ( $n === 2 ) { return $p[0]; }              // T/B = first
		if ( $n >= 3 )  { return ( $side === 'top' ) ? $p[0] : $p[2]; } // T … B
		return '';
	}

	/** A CSS length is "present" (a non-zero px/rem/em value). '' / '0' / '0px' / 'none' are absent. */
	private static function css_len_present( $v ) {
		$v = trim( (string) $v );
		return $v !== '' && $v !== 'none' && ! preg_match( '/^0(?:px|rem|em|%)?$/', $v );
	}

	/** A CSS length → a spacing string in rem (px÷16), e.g. `64px` → `4rem`, `1.5rem` → `1.5rem`. '' if unparseable. */
	private static function css_len_to_rem( $v ) {
		$v = trim( (string) $v );
		if ( preg_match( '/^(-?[0-9.]+)px$/', $v, $m ) ) { $r = round( ( (float) $m[1] ) / 16, 3 ); return rtrim( rtrim( (string) $r, '0' ), '.' ) . 'rem'; }
		if ( preg_match( '/^(-?[0-9.]+)(rem|em)$/', $v, $m ) ) { return $m[1] . 'rem'; }
		return '';
	}

	/**
	 * Convert a source chrome/content container BOX width (its computed max-width, which INCLUDES the
	 * source's own horizontal gutters) into the UnysonPlus CONTENT width to store as Container Width.
	 * UnysonPlus's Container Width is a CONTENT width and the theme ADDS gutters OUTSIDE it (rendered
	 * .fw-container box = content + 2 x --container-gutter, default 1.5rem = 24px each side, with
	 * box-sizing:border-box). So to make the RENDERED box equal the source box, store box - 2*24 = box-48.
	 * Falls back to the raw box when the subtraction would drop below a sane floor.
	 */
	private static function chrome_box_to_content_px( $box_px ) {
		$box     = (int) round( (float) $box_px );
		$content = $box - 48; // theme default gutter 1.5rem (24px) each side; box = content + 2*gutter
		return ( $content >= 320 ) ? $content : $box;
	}

	/** A CSS length → a unit-input value array `{ value, unit }` (px|rem|em). null if unparseable. */
	private static function css_len_to_unit( $v ) {
		$v = trim( (string) $v );
		if ( preg_match( '/^(-?[0-9.]+)\s*(px|rem|em)?$/', $v, $m ) ) { return array( 'value' => $m[1], 'unit' => ( isset( $m[2] ) && $m[2] !== '' ? $m[2] : 'px' ) ); }
		return null;
	}

	/**
	 * The HEADER's chrome styles read from the <header> computed `data-sc-cs`:
	 *   bg (background-color, non-transparent), border (bottom hairline present), shadow (box-shadow present),
	 *   glass (backdrop-filter blur), pad_top/pad_bottom, radius (border-radius when rounded).
	 * Only keys we actually detected are present (callers must not write defaults).
	 */
	/**
	 * The header/footer INNER CONTENT container width, read from computed styles (data-sc-cs). The cap lives
	 * on the wrapper that centers the content (a `.container` / `.mx-auto` / `max-w-*`), NOT the
	 * <header>/<footer> element itself (that's why the earlier style pass — which only looked at the element
	 * — left it unset). Returns the LARGEST capped `max-width` in px (the OUTERMOST content container; inner
	 * text columns cap smaller, so the max is the real content width), 'fluid' when a wrapper spans full width
	 * (container-fluid / max-w-full / max-w-none with no numeric cap), or '' when no content wrapper is found.
	 * Mirrors the mirror-path container algorithm (the largest matching cap wins).
	 */
	/**
	 * Does the source site use the literal Tailwind `container` class for its content wrapper? True when a
	 * `<header>`/`<footer>`/`<section>`/`<main>` descendant carries the exact `container` token (NOT
	 * `container-fluid`, NOT a fixed `max-w-[..]`). Signals a RESPONSIVE breakpoint ladder (sm/md/lg/xl/2xl)
	 * rather than a single fixed max-width, so the container-width mapping emits the upper tiers as scoped CSS.
	 */
	private static function site_uses_tw_container( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return false; }
		foreach ( array( 'header', 'footer', 'section', 'main' ) as $tag ) {
			foreach ( $dom->getElementsByTagName( $tag ) as $root ) {
				foreach ( $root->getElementsByTagName( '*' ) as $el ) {
					$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
					if ( strpos( $cls, ' container ' ) !== false ) { return true; } // exact token, not container-fluid
				}
			}
		}
		return false;
	}

	/**
	 * The site's MAIN CONTENT WIDTH, read from the `data-sc-content-width` the capture service stamps on
	 * <html> (the heaviest centered, inset content column measured live in the browser). This is the ONLY
	 * signal that captures a FULL-WIDTH source (sections span the viewport, content inset by px gutters, no
	 * max-width wrapper) — which `detect_chrome_container` (max-width classes only) cannot see, so it fell
	 * back to the theme's narrow default. Returns the content width in px (int), or 0 when unstamped
	 * (a static / non-captured HTML paste, where the max-width detection remains the fallback).
	 *
	 * @param string $html
	 * @return int
	 */
	private static function detect_site_content_width( $html ) {
		if ( preg_match( '/<html\b[^>]*\bdata-sc-content-width\s*=\s*["\']?([0-9]+)/i', (string) $html, $m ) ) {
			$w = (int) $m[1];
			if ( $w >= 600 && $w <= 2400 ) {
				// The stamp is a MEASUREMENT at the capture viewport; the source's DECLARED cap wins when it is
				// larger (a `width:min(1440px, calc(100% - 48px))` shell measures 1392 at 1440 wide).
				$d = self::declared_container_cap( (string) $html, $w );
				$w = $d > 0 ? $d : $w;
				$o = self::outer_container_wins( (string) $html, $w );
				return $o > 0 ? $o : $w;
			}
		}
		return 0;
	}

	/**
	 * THE OUTER CONTAINER WINS over the inner caps it wraps. The stamp is the heaviest centred width by area, so a
	 * `.container max-w-7xl px-6` (1280) whose bands centre a `max-w-6xl` (1152) block inside it stamped 1152 and the
	 * theme's Container Width came out 128px under the design (a feed regression). When every element measuring the
	 * stamped width sits INSIDE a centred box of a wider width (≤ 1.25×) that spans as many bands, that box is the site
	 * container and the narrow one a per-section cap. Returns the outer width or 0. JS twin: capture.mjs (same rule).
	 */
	private static function outer_container_wins( $html, $w ) {
		$dom = self::load_dom( $html ); if ( ! $dom ) { return 0; }
		$inner = array(); $outer = array();
		$band = function ( $el ) { for ( $a = $el; $a instanceof DOMElement; $a = $a->parentNode ) { if ( in_array( strtolower( $a->tagName ), array( 'section', 'header', 'footer', 'main', 'body' ), true ) ) { return $a; } } return null; };
		foreach ( $dom->getElementsByTagName( '*' ) as $el ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' ); if ( '' === $cs ) { continue; }
			$cw = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $cs, $m ) ? (float) $m[1] : 0.0;
			$mw = preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/i', $cs, $m ) ? (float) $m[1] : 0.0;
			$box = $cw >= 600 ? $cw : $mw; if ( $box < 600 ) { continue; }
			if ( abs( $box - $w ) <= 8 ) { $inner[] = $el; continue; }
			if ( $box <= $w || $box > $w * 1.25 ) { continue; }
			$centred = (bool) preg_match( '/(?:^|;)\s*margin(?:-left)?:\s*(?:0px\s+)?(?:auto|[1-9][0-9.]*px)/i', $cs ) || preg_match( '/\b(?:mx-auto|container)\b/', self::cls( $el ) );
			if ( ! $centred ) { continue; }
			$k = (string) ( (int) round( $box / 8 ) * 8 ); $outer[ $k ][] = $el;
		}
		if ( ! $outer ) { return 0; }
		if ( ! $inner ) { // nothing in this document measures the stamp (a band cut from a page whose other bands carried the inner cap): the centred container box IS the width
			krsort( $outer, SORT_NUMERIC ); return (int) array_key_first( $outer );
		}
		$n_inner_bands = count( array_unique( array_map( function ( $e ) use ( $band ) { $b = $band( $e ); return $b ? spl_object_id( $b ) : 0; }, $inner ) ) );
		krsort( $outer, SORT_NUMERIC );
		foreach ( $outer as $k => $els ) {
			$wraps = true;
			foreach ( $inner as $ie ) { $ok = false; foreach ( $els as $oe ) { if ( $oe !== $ie && self::is_ancestor( $oe, $ie ) ) { $ok = true; break; } } if ( ! $ok ) { $wraps = false; break; } }
			if ( ! $wraps ) { continue; }
			$n_bands = count( array_unique( array_map( function ( $e ) use ( $band ) { $b = $band( $e ); return $b ? spl_object_id( $b ) : 0; }, $els ) ) );
			if ( $n_bands >= (int) ceil( $n_inner_bands * 0.6 ) ) { return (int) $k; }
		}
		return 0;
	}

	/**
	 * The DECLARED cap of the site's repeated content container, read from the source stylesheet — the
	 * design's real container width, as opposed to the browser-measured `data-sc-content-width` stamp, which
	 * is viewport-limited: a `.shell{width:min(1440px, calc(100% - 48px))}` container measures 1392px at the
	 * 1440px capture viewport, so the converted site capped at 1392 and never reached the source's 1440 on a
	 * wider screen. Accepts a rule `width:min(Npx, …)` / `max-width:min(Npx, …)` / `max-width:Npx` on a
	 * single-class selector that ≥2 elements carry (a per-section shell), with N between the measured width
	 * and 1.25× it (the measurement is the declared cap squeezed by the viewport, so the two must agree —
	 * an unrelated wide rule can't hijack it). Rules inside @media are skipped (a responsive `.container`
	 * ladder is handled by the container-ladder emit). Returns N (px) or 0. JS twin: capture.mjs stamp.
	 */
	private static function declared_container_cap( $html, $measured ) {
		$r = self::declared_container_rule( $html, $measured );
		return (int) $r['cap'];
	}

	/**
	 * The site container's declared GUTTER (px per side) — the `G` of the winning shell rule
	 * `width:min(Npx, calc(100% - Gpx))` / `min(100% - Gpx, Npx)`, halved (it is the sum of both sides). A capture stamped with
	 * `data-sc-content-gutter` wins. → Theme Settings `layout_container_gutter` (--container-gutter), which the flexbox
	 * Content Width cap (`min(cap, 100% - 2×gutter)`) and .fw-container both honour — so a converted band keeps the
	 * source's exact side breathing room at EVERY viewport, not just the capture width. 0 = leave the theme default.
	 */
	private static function declared_container_gutter( $html ) {
		// THE CONTAINER'S OWN PADDING WINS over a stamped gutter that disagrees with it: the box that measures the stamped content
		// width (`max-width:1400px … padding:0 24px`) carries its gutter INSIDE that width, so a stamp of 48 (a wider tier's value,
		// a sibling band's inset) put the theme gutter OUTSIDE 1400 and the rail rendered 1304 (a fixture from the feed). Measured:
		// the container's equal side padding, and the width is then an OUTER width.
		if ( preg_match( '/<html\b[^>]*\bdata-sc-content-width\s*=\s*["\']?([0-9]+)/i', (string) $html, $wm0 ) ) {
			$w0 = (int) $wm0[1]; $dom0 = self::load_dom( (string) $html );
			if ( $dom0 && $w0 >= 600 ) {
				foreach ( $dom0->getElementsByTagName( '*' ) as $c0 ) {
					$c0cs = (string) $c0->getAttribute( 'data-sc-cs' ); if ( '' === $c0cs ) { continue; }
					$c0w = preg_match( '/(?:^|;)\s*(?:max-)?width:\s*([0-9.]+)px/i', $c0cs, $c0m ) ? (float) $c0m[1] : 0.0;
					if ( abs( $c0w - $w0 ) > 2 || ! preg_match( '/\b(?:container|mx-auto)\b/', self::cls( $c0 ) ) && ! preg_match( '/(?:^|;)\s*margin(?:-left)?:\s*(?:0px\s+)?(?:auto|[1-9][0-9.]*px)/i', $c0cs ) ) { continue; }
					// the DESKTOP tier (`px-6 md:px-12` → 48, not the phone's 24 — the base tier is the mobile-first value); the stamped
					// computed padding is the desktop truth when the classes carry tiers
					$pad0 = self::el_padding( $c0 ); $pl0 = 0.0; $pr0 = 0.0;
					foreach ( array( 'lg', 'md', 'base' ) as $tier0 ) { if ( null !== ( $pad0[ $tier0 ]['left'] ?? null ) ) { $pl0 = (float) $pad0[ $tier0 ]['left']; $pr0 = (float) ( $pad0[ $tier0 ]['right'] ?? $pl0 ); break; } }
					if ( preg_match( '/(?:^|;)\s*padding(?:-left)?:\s*(?:[0-9.]+px\s+)?([0-9.]+)px/i', $c0cs, $cpm ) ) { $cpd = self::cs_decls_pad( $c0cs ); if ( null !== $cpd && abs( $cpd['left'] - $cpd['right'] ) < 1 && $cpd['left'] > 0 ) { $pl0 = $cpd['left']; $pr0 = $cpd['right']; } }
					if ( $pl0 > 0 && $pl0 <= 200 && abs( $pl0 - $pr0 ) < 1 ) { self::$gutter_inside = true; return (int) round( $pl0 ); }
					break; // the first container-sized centred box decides
				}
			}
		}
		if ( preg_match( '/<html\b[^>]*\bdata-sc-content-gutter\s*=\s*["\']?([0-9]+)/i', (string) $html, $m ) ) {
			$g = (int) $m[1];
			if ( $g > 0 && $g <= 200 ) { return $g; }
		}
		$w = 0;
		if ( preg_match( '/<html\b[^>]*\bdata-sc-content-width\s*=\s*["\']?([0-9]+)/i', (string) $html, $m ) ) { $w = (int) $m[1]; }
		if ( $w >= 600 ) {
			$r = self::declared_container_rule( $html, $w );
			if ( (int) $r['gutter'] > 0 ) { return (int) $r['gutter']; }
		}
		// (no content-width stamp — a fixture, an older capture — still measures the bands' padding below)
		// MEASURED (JS twin: capture.mjs contentGutter fallback): no calc() rule — the gutter is the equal side padding of the
		// sections' content containers (`mx-auto max-w-[1600px] px-8` → 32; a `<section class="px-8">` → 32). The mode wins.
		$dom = self::load_dom( (string) $html ); if ( ! $dom ) { return 0; }
		$tally = array();
		foreach ( $dom->getElementsByTagName( 'section' ) as $sec ) {
			$cands = array( $sec ); foreach ( self::el_children( $sec ) as $k ) { $cands[] = $k; }
			foreach ( $cands as $c ) {
				// only a CONTAINER-sized box counts (≥ 600px wide, or a declared max-width ≥ 600): a padded pill / card inside the band is not the gutter
				$ccs = (string) $c->getAttribute( 'data-sc-cs' );
				$cw  = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $ccs, $cwm ) ? (float) $cwm[1] : 0.0;
				$cmw = preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/i', $ccs, $cmm ) ? (float) $cmm[1] : 0.0;
				if ( $c !== $sec && $cw < 600 && $cmw < 600 ) { continue; }
				$pad = self::el_padding( $c ); $pl = (float) ( $pad['base']['left'] ?? 0 ); $pr = (float) ( $pad['base']['right'] ?? 0 );
				if ( $pl > 0 && $pl <= 200 && abs( $pl - $pr ) < 1 ) { $k = (int) round( $pl ); $tally[ $k ] = ( $tally[ $k ] ?? 0 ) + 1; break; }
			}
		}
		if ( ! $tally ) { return 0; }
		arsort( $tally ); $best = (int) array_key_first( $tally );
		$n_secs = $dom->getElementsByTagName( 'section' )->length;
		if ( $tally[ $best ] >= 2 || ( 1 === $n_secs && $tally[ $best ] >= 1 ) ) { self::$gutter_inside = true; return $best; } // one band = its padding is the gutter
		return 0;
	}

	/** The four sides of a stamped `padding:` shorthand (1–4 values) as px, or null. */
	private static function cs_decls_pad( $cs ) {
		if ( ! preg_match( '/(?:^|;)\s*padding:\s*([^;]+)/i', (string) $cs, $m ) ) { return null; }
		$v = preg_split( '/\s+/', trim( $m[1] ) ); $px = array(); foreach ( $v as $x ) { if ( ! preg_match( '/^([0-9.]+)px$/', $x, $xm ) ) { return null; } $px[] = (float) $xm[1]; }
		if ( ! $px || count( $px ) > 4 ) { return null; }
		$t = $px[0]; $r = $px[1] ?? $t; $b = $px[2] ?? $t; $l = $px[3] ?? $r;
		return array( 'top' => $t, 'right' => $r, 'bottom' => $b, 'left' => $l );
	}

	/** True when the container gutter sits INSIDE its measured width (the container's own padding — `max-w-7xl px-6`: 1280
	 *  outer, 1232 content): the stamp `data-sc-content-gutter-inside`, or the measured-padding fallback above. */
	private static $gutter_inside = false;
	private static function container_gutter_inside( $html ) {
		if ( preg_match( '/<html\b[^>]*\bdata-sc-content-gutter-inside\s*=\s*["\']?1/i', (string) $html ) ) { return true; }
		return self::$gutter_inside;
	}

	/**
	 * The container's PHONE gutter (px per side): the capture stamp `data-sc-content-gutter-sm` (>= 1.10.97), else the winning
	 * shell class's phone-pass margin (`data-sc-cs-sm="margin:0px 16px"`). 0 = same as desktop / unknown. → a max-width:767px
	 * --container-gutter override in the misc CSS (the native Container Gutter is one value). JS twin: contentGutterSm.
	 */
	private static function declared_container_gutter_sm( $html ) {
		if ( preg_match( '/<html\b[^>]*\bdata-sc-content-gutter-sm\s*=\s*["\']?([0-9]+)/i', (string) $html, $m ) ) { $g = (int) $m[1]; return ( $g > 0 && $g <= 120 ) ? $g : 0; }
		$w = 0; if ( preg_match( '/<html\b[^>]*\bdata-sc-content-width\s*=\s*["\']?([0-9]+)/i', (string) $html, $m ) ) { $w = (int) $m[1]; }
		if ( $w < 600 ) { return 0; }
		$r = self::declared_container_rule( $html, $w );
		if ( empty( $r['class'] ) ) { return 0; }
		if ( preg_match( '/\bclass\s*=\s*"(?:[^"]*\s)?' . preg_quote( $r['class'], '/' ) . '(?:\s[^"]*)?"[^>]*\bdata-sc-cs-sm\s*=\s*"[^"]*(?:^|;)\s*margin:\s*0px\s+([0-9.]+)px/i', (string) $html, $mm ) ) { $g = (int) round( (float) $mm[1] ); return ( $g > 0 && $g <= 120 ) ? $g : 0; }
		return 0;
	}

	/** Shared parser behind declared_container_cap / declared_container_gutter: { cap:int, gutter:int (per side) }. */
	private static function declared_container_rule( $html, $measured ) {
		$measured = (int) $measured;
		$none = array( 'cap' => 0, 'gutter' => 0, 'class' => '' );
		if ( $measured <= 0 ) { return $none; }
		$css = self::all_style_css( $html );
		if ( '' === $css ) { return $none; }
		// Drop every @media { … } block (brace-matched) so only root-level rules are read.
		$out = ''; $pos = 0; $len = strlen( $css );
		while ( $pos < $len ) {
			$at = strpos( $css, '@media', $pos );
			if ( false === $at ) { $out .= substr( $css, $pos ); break; }
			$out .= substr( $css, $pos, $at - $pos );
			$br = strpos( $css, '{', $at );
			if ( false === $br ) { break; }
			$depth = 1; $p = $br + 1;
			while ( $p < $len && $depth > 0 ) { $ch = $css[ $p ]; if ( '{' === $ch ) { $depth++; } elseif ( '}' === $ch ) { $depth--; } $p++; }
			$pos = $p;
		}
		if ( ! preg_match_all( '/([^{}]+)\{([^}]*)\}/', $out, $rules, PREG_SET_ORDER ) ) { return $none; }
		$best = 0; $best_n = 0; $best_g = 0; $best_c = '';
		foreach ( $rules as $r ) {
			$n = 0.0; $g = 0;
			if ( preg_match( '/(?:^|;)\s*(?:max-)?width\s*:\s*min\(\s*([0-9.]+)px/i', $r[2], $m ) ) { $n = (float) $m[1]; }
			elseif ( preg_match( '/(?:^|;)\s*(?:max-)?width\s*:\s*min\(\s*(?:calc\()?\s*100%\s*-\s*[0-9.]+px\s*\)?\s*,\s*([0-9.]+)px/i', $r[2], $m ) ) { $n = (float) $m[1]; }
			elseif ( preg_match( '/(?:^|;)\s*max-width\s*:\s*([0-9.]+)px\s*(?:;|$)/i', $r[2], $m ) ) { $n = (float) $m[1]; }
			if ( $n < $measured || $n > $measured * 1.25 || $n > 2400 ) { continue; }
			// The rule's own gutter: `100% - Gpx` inside the min() (both sides together) → per side.
			if ( preg_match( '/(?:max-)?width\s*:\s*min\([^;]*100%\s*-\s*([0-9.]+)px/i', $r[2], $gm ) ) { $g = (int) round( (float) $gm[1] / 2 ); }
			foreach ( explode( ',', $r[1] ) as $sel ) {
				if ( ! preg_match( '/^\s*\.([A-Za-z0-9_-]+)\s*$/', $sel, $sm ) ) { continue; }
				$cnt = preg_match_all( '/\bclass\s*=\s*"(?:[^"]*\s)?' . preg_quote( $sm[1], '/' ) . '(?:\s[^"]*)?"/i', (string) $html );
				if ( $cnt >= 2 && $cnt > $best_n ) { $best_n = $cnt; $best = (int) round( $n ); $best_g = $g; $best_c = $sm[1]; }
			}
		}
		return array( 'cap' => $best, 'gutter' => $best_g, 'class' => $best_c );
	}

	/**
	 * FALLBACK site content width — the dominant CENTERED content-band max-width measured across the body,
	 * for a capture that carries no `data-sc-content-width` stamp AND no header/footer `.container` chrome
	 * (so detect_site_content_width() and the chrome box both come back 0). Without this the site's global
	 * Container Width was left unset → `--container-max-desktop` empty → every section full-bleed (content
	 * flush to the monitor edges). Tallies computed `max-width` on centered wrappers (mx-auto / container /
	 * max-w-*) in the 700–1900px band — skipping typographic reading measures on text leaves — and returns
	 * the MODE (ties → the widest), or 0 when the source genuinely caps nothing.
	 *
	 * @param string $html
	 * @return int px, or 0
	 */
	private static function detect_dominant_container_width( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return 0; }
		$leaf = array( 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'span', 'a', 'li', 'blockquote', 'figcaption', 'label' );
		$tally = array();
		foreach ( $dom->getElementsByTagName( '*' ) as $el ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( $cs === '' || ! preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/', $cs, $m ) ) { continue; }
			$px = (float) $m[1];
			if ( $px < 700 || $px > 1900 ) { continue; }
			if ( in_array( strtolower( (string) $el->tagName ), $leaf, true ) ) { continue; } // reading-measure cap, not a band
			$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$centered = self::cap_is_centred( $el, $cls, $cs );
			if ( ! $centered ) { continue; }
			$b = (int) round( $px );
			$tally[ $b ] = ( $tally[ $b ] ?? 0 ) + 1;
		}
		if ( ! $tally ) { return 0; }
		arsort( $tally );
		$mode = array_key_first( $tally ); $modec = $tally[ $mode ];
		foreach ( $tally as $w => $c ) { if ( $c === $modec && $w > $mode ) { $mode = $w; } } // tie → widest
		return (int) $mode;
	}

	/**
	 * D2 — the site's GLOBAL border/divider colour → `layout_border_color` (drives `--color-border`, used by
	 * cards / dividers / inputs across ~21 consumers; otherwise they fall back to the default subtle 10% black).
	 * Tallies the computed `border-top-color` of every element that actually HAS a border (non-zero width) and
	 * returns the most common non-transparent value, or '' when the source uses no real borders.
	 *
	 * @param string $html
	 * @return string css colour or ''
	 */
	private static function detect_border_color( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$xp = new DOMXPath( $dom );
		$tally = array();
		foreach ( $xp->query( '//*[@data-sc-cs]' ) as $el ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/border-top-width:\s*([0-9.]+)px/', $cs, $wm ) || (float) $wm[1] <= 0 ) { continue; }
			if ( ! preg_match( '/border-top-color:\s*(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', $cs, $cm ) ) { continue; }
			$c = strtolower( trim( $cm[1] ) );
			if ( preg_match( '/rgba?\([^)]*,\s*0?\.?0*\)$/', $c ) || $c === 'transparent' ) { continue; } // fully transparent
			$tally[ $c ] = ( $tally[ $c ] ?? 0 ) + 1;
		}
		if ( ! $tally ) { return ''; }
		arsort( $tally );
		return (string) array_key_first( $tally );
	}

	/**
	 * D1 — dominant card/button corner radius → the global Border Roundness radio. Tallies the computed
	 * `border-radius` of boxy elements that carry a fill or border (cards, buttons, inputs, chips), takes the
	 * MODE, and buckets it: sharp (<4px) · subtle (4–11) · rounded (12–23) · soft (>=24, incl. pill/full).
	 * Returns '' when there are too few rounded boxes to be sure. See design-system / general-layout.md.
	 */
	private static function detect_global_roundness( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$xp = new DOMXPath( $dom );
		$tally = array(); $n = 0;
		foreach ( $xp->query( '//*[@data-sc-cs]' ) as $el ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/(?:^|;)\s*border-radius:\s*([0-9.]+)px/', $cs, $rm ) ) { continue; }
			$r = (float) $rm[1];
			// Count CONTROLS (buttons/links/inputs) at any radius — they define the "button roundness" — and any
			// OTHER element only when it is genuinely rounded (r>0), so full-bleed colored sections at radius 0
			// (which aren't cards) don't drag the whole site to 'sharp'. A fill or border is still required.
			$tag        = strtolower( $el->nodeName );
			$is_control = in_array( $tag, array( 'button', 'a', 'input', 'select', 'textarea' ), true ) || self::is_button( $el );
			$has_fill   = preg_match( '/(?:^|;)\s*background-color:/', $cs );
			$has_border = preg_match( '/border-top-width:\s*([0-9.]+)px/', $cs, $bw ) && (float) $bw[1] > 0;
			if ( ! $has_fill && ! $has_border ) { continue; }
			if ( ! $is_control && $r <= 0 ) { continue; }
			if ( $r > 400 ) { $r = 28; } // a huge pill/full radius (9999px) counts as 'soft'
			$bucket = $r < 4 ? 'sharp' : ( $r < 12 ? 'subtle' : ( $r < 24 ? 'rounded' : 'soft' ) );
			$tally[ $bucket ] = ( $tally[ $bucket ] ?? 0 ) + 1; $n++;
		}
		if ( $n < 3 ) { return ''; } // too few rounded surfaces to commit a global default
		arsort( $tally );
		return (string) array_key_first( $tally );
	}

	/**
	 * D3 — Content Density from the median `<section>` vertical padding (top+bottom). compact (<96px total) ·
	 * cozy (96–159) · spacious (>=160). Reads the stamped `padding` shorthand of each section-like band.
	 * Returns '' when fewer than 3 measurable sections (not enough to set a global rhythm).
	 */
	private static function detect_section_density( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$totals = array();
		foreach ( $dom->getElementsByTagName( 'section' ) as $sec ) {
			$pad = self::sc_css( $sec, 'padding' );
			if ( $pad === '' ) { continue; }
			$pp = preg_split( '/\s+/', trim( $pad ) ); $c = count( $pp );
			$top = preg_match( '/([0-9.]+)px/', $pp[0] ?? '', $tm ) ? (float) $tm[1] : 0;
			$botv = $c >= 3 ? $pp[2] : ( $pp[0] ?? '' );
			$bot = preg_match( '/([0-9.]+)px/', (string) $botv, $bm ) ? (float) $bm[1] : $top;
			$sum = $top + $bot;
			if ( $sum > 0 ) { $totals[] = $sum; }
		}
		if ( count( $totals ) < 3 ) { return ''; }
		sort( $totals );
		$med = $totals[ intval( floor( ( count( $totals ) - 1 ) / 2 ) ) ];
		return $med < 96 ? 'compact' : ( $med < 160 ? 'cozy' : 'spacious' );
	}

	/**
	 * D4 — Body Link Underline from in-text links (anchors sitting inside paragraphs, not nav/buttons).
	 * always when most such links carry `text-decoration-line:underline` at rest, never when most are
	 * un-underlined; '' (leave theme default 'hover') when the signal is mixed or too small.
	 */
	private static function detect_link_underline( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$under = 0; $plain = 0;
		foreach ( $dom->getElementsByTagName( 'p' ) as $p ) {
			foreach ( $p->getElementsByTagName( 'a' ) as $a ) {
				if ( self::is_button( $a ) ) { continue; }
				if ( ! $a->hasAttribute( 'data-sc-cs' ) ) { continue; } // only measured links count
				// Capture DROPS text-decoration-line:none, so an empty value = not underlined (plain).
				$td = self::sc_css( $a, 'text-decoration-line' );
				if ( stripos( $td, 'underline' ) !== false ) { $under++; } else { $plain++; }
			}
		}
		$tot = $under + $plain;
		if ( $tot < 2 ) { return ''; }
		if ( $under >= $tot * 0.75 ) { return 'always'; }
		if ( $plain >= $tot * 0.75 ) { return 'never'; }
		return '';
	}

	private static function detect_chrome_container( $root, $bare_is_fluid = false ) {
		if ( ! ( $root instanceof DOMElement ) ) { return ''; }
		$best = 0.0; $saw_wrap = false; $saw_fluid = false;
		foreach ( $root->getElementsByTagName( '*' ) as $el ) {
			$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$mw  = trim( (string) self::sc_css( $el, 'max-width' ) );
			// A REAL layout container: a literal `.container`/`.container-fluid`. A bare `mx-auto` / `max-w-*`
			// is only a container CANDIDATE — it's just as often a PROSE or FORM measure (`max-w-sm` newsletter,
			// `max-w-3xl` paragraph), so it must be LAYOUT-SCALE (≥ 900px) to count. Without this the site-wide
			// Container Width latched onto a footer `max-w-sm` input (384px) and squashed every section.
			// A plain-CSS wrapper (`.header-inner{max-width:1200px}`, no utility class) is a candidate by its
			// COMPUTED max-width alone — framework-agnostic, same layout-scale bar.
			$is_real = ( strpos( $cls, ' container ' ) !== false || strpos( $cls, ' container-fluid ' ) !== false );
			$is_cand = $is_real || strpos( $cls, ' mx-auto ' ) !== false || (bool) preg_match( '/\smax-w-/', $cls )
				|| ( preg_match( '/^([0-9.]+)px$/', $mw, $cm ) && (float) $cm[1] >= 900 && (float) $cm[1] <= 2200 );
			if ( ! $is_cand ) { continue; }
			$saw_wrap = true;
			if ( strpos( $cls, ' container-fluid ' ) !== false || preg_match( '/\smax-w-(full|none)\b/', $cls ) ) { $saw_fluid = true; }
			if ( $mw === '' || strtolower( $mw ) === 'none' ) { continue; }
			if ( preg_match( '/^([0-9.]+)px$/', $mw, $m ) ) {
				$px  = (float) $m[1];
				$min = $is_real ? 320 : 900; // a bare max-w-* must be layout-scale, not a prose/form measure
				if ( $px >= $min && $px <= 2200 && $px > $best ) { $best = $px; }
			}
		}
		if ( $best > 0 ) { return (string) (int) round( $best ); }
		if ( $saw_wrap && $saw_fluid ) { return 'fluid'; }
		// NO wrapper of any kind (no container class, no capped max-width anywhere): the bar's rows span the
		// full viewport, inset only by their own padding — a FULL-WIDTH header. Leaving it '' let the theme's
		// default fixed container cap it (the logo sat 80px in where the source had 28px). Opt-in per caller
		// (a hug-width floating pill also has no wrapper, and must NOT go full width).
		if ( $bare_is_fluid && ! $saw_wrap ) { return 'fluid'; }
		return '';
	}

	/** Horizontal (LEFT) padding of an element from its computed `padding-left` / `padding` shorthand (px string or ''). */
	private static function sc_pad_x( $el ) {
		$long = self::sc_css( $el, 'padding-left' );
		if ( $long !== '' ) { return $long; }
		$sh = self::sc_css( $el, 'padding' );
		if ( $sh === '' ) { return ''; }
		$p = preg_split( '/\s+/', trim( $sh ) );
		$n = count( $p );
		if ( $n === 1 ) { return $p[0]; }
		if ( $n === 4 ) { return $p[3]; }
		return $p[1]; // 2 or 3 values: L/R = second
	}

	/**
	 * The frosted "PILL" inside a floating/overlay header. Many modern headers keep the <header> root a
	 * transparent positioning wrapper and paint the real chrome (translucent fill + blur + shadow + border +
	 * pill radius) on an INNER container. Return the OUTERMOST such surface-bearing container that also holds
	 * the nav (a link), so `detect_header_chrome_styles` reads the true appearance. Null when the header itself
	 * carries the chrome (an ordinary bar). Shallow BFS (≤3 levels) — the pill is always near the top.
	 */
	private static function header_pill( $header ) {
		if ( ! ( $header instanceof DOMElement ) ) { return null; }
		$queue = array( array( $header, 0 ) );
		while ( $queue ) {
			list( $el, $d ) = array_shift( $queue );
			if ( $el !== $header && self::el_is_header_surface( $el ) ) { return $el; }
			if ( $d >= 3 ) { continue; }
			foreach ( self::el_children( $el ) as $c ) { $queue[] = array( $c, $d + 1 ); }
		}
		return null;
	}

	/** Does this element read as a header "surface" — a blurred/shadowed/filled-pill bar that HOLDS nav content? */
	private static function el_is_header_surface( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( $el->getElementsByTagName( 'a' )->length < 1 ) { return false; } // must hold the nav, not a decorative layer
		$bf = self::sc_css( $el, 'backdrop-filter' );
		if ( '' === $bf || stripos( $bf, 'blur' ) === false ) { $bf = self::sc_css( $el, '-webkit-backdrop-filter' ); }
		$glass  = ( stripos( (string) $bf, 'blur' ) !== false );
		$sh     = self::sc_css( $el, 'box-shadow' );
		$shadow = ( $sh !== '' && $sh !== 'none' );
		$bg     = self::sc_css( $el, 'background-color' );
		$fill   = ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/i', $bg ) );
		$cls    = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$radius = self::sc_css( $el, 'border-top-left-radius' );
		$pill   = (bool) preg_match( '/\srounded-(full|3xl|2xl)\s/', $cls ) || (float) $radius >= 16 || strpos( (string) $radius, '50%' ) !== false;
		// a real header surface = blurred OR shadowed, OR a pill-radius bar carrying a translucent fill
		return $glass || $shadow || ( $fill && $pill );
	}

	private static function detect_header_chrome_styles( $html ) {
		$out = array();
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return $out; }
		// A floating / overlay header commonly paints its APPEARANCE (translucent fill, blur, shadow, border,
		// pill radius) on an INNER "pill" container, while the <header> root is a transparent positioning
		// wrapper (AI-page nature previews: `<header class="fixed top-6 left-1/2 -translate-x-1/2"><div
		// class="header-float rounded-full ...">`). Reading chrome off the root then saw nothing — the pill's
		// frost/shadow/fill were dropped and the bar rendered flat + full-width. Read chrome off the pill when
		// there is one, falling back to the header itself for a normal bar. Twin of the JS to-pages path.
		$pill   = self::header_pill( $header );
		$chrome = ( $pill instanceof DOMElement ) ? $pill : $header;
		$cw = self::detect_chrome_container( $header, ! ( $pill instanceof DOMElement ) );
		if ( $cw !== '' ) { $out['container'] = $cw; }
		// The bar's own horizontal inset (a full-width header is inset only by its row padding — carried so
		// the logo/CTAs sit where the source put them, not at the theme's default gutter). Read the first
		// padded row (the header itself, else a stamped zone row / a padded descendant within 3 levels).
		$px = self::sc_pad_x( $header );
		if ( '' === $px ) {
			$queue = array( array( $header, 0 ) );
			while ( $queue && '' === $px ) {
				list( $qel, $qd ) = array_shift( $queue );
				foreach ( self::el_children( $qel ) as $c ) {
					$cp = self::sc_pad_x( $c );
					if ( '' !== $cp && (float) $cp > 0 ) { $px = $cp; break; }
					if ( $qd < 2 ) { $queue[] = array( $c, $qd + 1 ); }
				}
			}
		}
		if ( preg_match( '/^([0-9.]+)px$/', $px, $pxm ) && (float) $pxm[1] > 0 ) { $out['pad_x'] = (int) round( (float) $pxm[1] ); }
		// FLOATING PILL width. The theme's Floating Pill has two width modes: "hug content" (default — the pill
		// shrinks to its content and centers, the compact source look) and "fixed" (a set container width). Pick
		// from the SOURCE pill: a genuine `max-width` (a deliberately-capped bar) → FIXED at that width; no
		// max-width (a shrink-to-fit inline-flex pill, cloud-forest) → HUG (leave container UNSET so the theme's
		// hug default sizes it to content — emitting a fixed 1024 here made it a wide bar before the theme grew
		// a hug mode). `pill_hug` / `pill_fixed` drive the theme's header_design.pill.pill_width option below.
		// Read the pill's OWN computed max-width UNCONDITIONALLY (was gated behind `'' === $cw`, so a pill in a
		// header that also reported a chrome-container width was skipped → left at the theme's hug default, and
		// a genuinely FIXED pill — apple-vision-pro's `max-w-5xl` = 1024px — rendered narrow, looking like it
		// borrowed another site's hug pill). A real max-width cap → FIXED at that width (its own cap wins over
		// $cw); no cap (cloud-forest's shrink-to-fit inline pill) → HUG.
		if ( $pill instanceof DOMElement ) {
			$pmw = trim( (string) self::sc_css( $pill, 'max-width' ) );
			if ( preg_match( '/^([0-9.]+)px$/', $pmw, $pm ) && (float) $pm[1] >= 400 && (float) $pm[1] <= 1600 ) {
				$out['container']   = (string) (int) round( (float) $pm[1] );
				$out['pill_fixed']  = $out['container']; // fixed-width pill → stamp container_width + pill_width:fixed
			} else {
				$out['pill_hug'] = true; // content-width pill → theme hugs it (no fixed container_width)
			}
		}
		$bg = self::sc_css( $chrome, 'background-color' );
		if ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/i', $bg ) ) { $out['bg'] = $bg; }
		// A GRADIENT header ground (`bg-gradient-to-b from-black/80 to-transparent` — a fade over the hero) has no header option; it
		// rides Misc CSS on .site-header (a finding filed on six conversions). Also the header's own padding when the bar is a
		// padded band (pt-8 pb-16) rather than a fixed-height bar.
		$bgi = trim( (string) self::sc_css( $chrome, 'background-image' ) );
		if ( '' !== $bgi && preg_match( '/^(linear|radial)-gradient\(/i', $bgi ) && false === stripos( $bgi, 'url(' ) && strlen( $bgi ) < 600 ) { $out['bg_gradient'] = $bgi; }
		// Border — a bar shows a bottom hairline; a PILL shows a uniform all-round border, so read any side.
		if ( self::css_len_present( self::sc_css( $chrome, 'border-bottom-width' ) ) || self::css_len_present( self::sc_css( $chrome, 'border-top-width' ) ) ) {
			$st  = self::sc_css( $chrome, 'border-bottom-style' ); if ( $st === '' || $st === 'none' ) { $st = self::sc_css( $chrome, 'border-top-style' ); }
			$bc  = self::sc_css( $chrome, 'border-bottom-color' ); if ( $bc === '' ) { $bc = self::sc_css( $chrome, 'border-top-color' ); }
			$transparent_border = ( $bc !== '' && ( stripos( $bc, 'transparent' ) !== false || preg_match( '/rgba\([^)]*,\s*0\s*\)/i', $bc ) ) );
			if ( $st !== '' && $st !== 'none' && ! $transparent_border ) { $out['border'] = true; }
		}
		$sh = self::sc_css( $chrome, 'box-shadow' );
		if ( $sh !== '' && $sh !== 'none' ) { $out['shadow'] = true; }
		// GLASS + its EXACT backdrop-filter value. header_glass=yes maps the INTENT (native, editable); the
		// precise blur has no native field, so we ALSO capture the exact value here → emitted as a scoped
		// override on the header (misc_custom_css) so the frost matches the source, not the theme default.
		$hbf = self::sc_css( $chrome, 'backdrop-filter' );
		if ( '' === $hbf || stripos( $hbf, 'blur' ) === false ) { $hbf = self::sc_css( $chrome, '-webkit-backdrop-filter' ); }
		if ( stripos( $hbf, 'blur' ) !== false ) { $out['glass'] = true; $out['glass_backdrop'] = trim( $hbf ); }
		// Resting HEIGHT from the always-present `data-sc-header` stamp. (The scrolled stamp only exists
		// when the header actually changes on scroll, so a static bar had no height signal at all.)
		$h_stamp = ( $header instanceof DOMElement ) ? (string) $header->getAttribute( 'data-sc-header' ) : '';
		// the capture stamps the masthead IT measured — a fixed <nav> inside a wrapper <header> (a ticker bar + the nav): read
		// the stamp off that descendant when the root carries none (the bar rendered at the theme's default height; a
		// real-site audit)
		if ( '' === $h_stamp && $header instanceof DOMElement ) { foreach ( $header->getElementsByTagName( '*' ) as $hd ) { if ( $hd instanceof DOMElement && '' !== (string) $hd->getAttribute( 'data-sc-header' ) ) { $h_stamp = (string) $hd->getAttribute( 'data-sc-header' ); break; } } }
		if ( '' !== $h_stamp && preg_match( '/rest-height\s*:\s*([0-9.]+)px/i', $h_stamp, $rhm ) ) {
			$rh = (float) $rhm[1];
			if ( $rh >= 32 ) { $out['rest_height'] = (int) round( $rh ); }
		}
		// CLASS fallbacks — capture services often DON'T record `backdrop-filter` or `border-bottom-*` in the
		// computed style, yet a modern header declares them as utility classes (`backdrop-blur-lg`, `border-b`).
		// Read those so a FROSTED translucent header (modfii's `bg-background/80 backdrop-blur-lg border-b`)
		// keeps its blur + hairline instead of flattening to a bare transparent bar.
		$hcls = ' ' . strtolower( self::cls( $header ) ) . ' ';
		// (…but a header whose REST stamp carries no blur while its SCROLLED stamp does is glass on scroll only: the blur class is
		// toggled by the page's script — the rest state must stay clear, else a 24px frost sat over the hero's top (a real-site audit))
		$scroll_only_glass = ( '' !== (string) $chrome->getAttribute( 'data-sc-cs' ) ) && ( $header instanceof DOMElement ) && stripos( (string) $header->getAttribute( 'data-sc-scrolled' ), 'backdrop-filter' ) !== false;
		if ( empty( $out['glass'] ) && ! $scroll_only_glass && preg_match( '/\sbackdrop-blur(?:-([a-z0-9]+))?\s/', $hcls, $hbm ) ) {
			$out['glass'] = true;
			$scale = array( '' => '8px', 'sm' => '4px', 'md' => '12px', 'lg' => '16px', 'xl' => '24px', '2xl' => '40px', '3xl' => '64px' );
			$bk    = isset( $hbm[1] ) ? $hbm[1] : '';
			if ( isset( $scale[ $bk ] ) && empty( $out['glass_backdrop'] ) ) { $out['glass_backdrop'] = 'blur(' . $scale[ $bk ] . ')'; }
		}
		if ( empty( $out['border'] ) && ( preg_match( '/\sborder-b(?:-\d+)?\s/', $hcls ) || preg_match( '/\sborder-b(?:order)?\s/', $hcls ) ) ) { $out['border'] = true; }
		// STYLESHEET fallback — the computed stamp carried no bottom border (captures before 1.10.78 never
		// recorded border-bottom-*), yet the source sheet's own rule for the bar (`.header-shell{border-bottom:
		// 1px solid …}`) declares the hairline. Read it there; a real width + visible colour = the hairline.
		if ( empty( $out['border'] ) ) {
			$decl = self::stylesheet_decl( $html, $chrome, 'border-bottom' );
			if ( preg_match( '/^([0-9.]+)px\s+(solid|dashed|dotted|double)\s+(.+)$/i', $decl, $dm ) && (float) $dm[1] > 0
				&& stripos( $dm[3], 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $dm[3] ) ) {
				$out['border'] = true;
				if ( empty( $out['border_color'] ) ) { $out['border_color'] = trim( $dm[3] ); }
			}
		}
		// The hairline's OWN colour (computed border-bottom-color, else the declared one above) so the emit can
		// reproduce the source's exact rule instead of the theme's default hairline tint.
		if ( ! empty( $out['border'] ) && empty( $out['border_color'] ) ) {
			$bcc = self::sc_css( $chrome, 'border-bottom-color' );
			if ( '' === $bcc || (float) self::sc_css( $chrome, 'border-bottom-width' ) <= 0 ) { $bcc = ''; }
			if ( '' !== $bcc && stripos( $bcc, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bcc ) ) { $out['border_color'] = $bcc; }
		}
		// PROMINENT bottom border on the header's INNER bar — the class-less `<header>` pattern, where the
		// visible nav bar is a `border-b-4 border-primary` child (the burger source). The header-level reads above miss it.
		// Capture the WIDTH (`border-b-N` → Npx) + the COLOUR TOKEN so the converter reproduces the real thick
		// accent rule instead of the theme's default 1px hairline. Only a THICK border (≥2px) qualifies — a bare
		// `border-b` (1px) is already covered by the hairline toggle.
		if ( empty( $out['border_width'] ) ) {
			foreach ( $header->getElementsByTagName( '*' ) as $d ) {
				if ( ! ( $d instanceof DOMElement ) ) { continue; }
				$dc = ' ' . strtolower( self::cls( $d ) ) . ' ';
				if ( ! preg_match( '/\bborder-b-([2-9]|1[0-9])\b/', $dc, $bm ) ) { continue; }
				$col = '';
				if ( preg_match( '/\bborder-(primary|secondary|accent)\b/', $dc, $cm ) ) { $col = $cm[1]; }
				elseif ( preg_match( '/\bborder-\[(#[0-9a-f]{3,8})\]/i', $dc, $cm ) ) { $col = $cm[1]; }
				elseif ( preg_match( '/(?<![\w-])border(?:-bottom)?-color:\s*(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', (string) $d->getAttribute( 'data-sc-cs' ), $cm ) ) { $col = trim( $cm[1] ); }
				if ( '' === $col ) { continue; }
				$out['border']       = true;
				$out['border_width'] = (int) $bm[1];
				$out['border_color'] = $col;
				break;
			}
		}
		// SCROLL-STATE (data-sc-scrolled, stamped by the capture service after scrolling the page): a fixed /
		// transparent header that reveals a bg / backdrop-blur / border / shadow ONLY on scroll. The resting
		// reads above can't see it (the effect is JS-applied on a scroll listener), so fold the scrolled state
		// in here → the native header_glass / header_border / header_shadow toggles + a solid scrolled bg. This
		// is what lets the PHP build_from_html path reproduce the scroll effect without the JS-bundle mapper.
		$scrolled = ( $header instanceof DOMElement ) ? (string) $header->getAttribute( 'data-sc-scrolled' ) : '';
		if ( $scrolled !== '' ) {
			$sp = array();
			foreach ( explode( ';', $scrolled ) as $d ) {
				$cp = strpos( $d, ':' );
				if ( $cp === false ) { continue; }
				$sp[ strtolower( trim( substr( $d, 0, $cp ) ) ) ] = trim( substr( $d, $cp + 1 ) );
			}
			// TWO-STATE model: the scrolled reads map to the ON-SCROLL options (scroll_*), kept SEPARATE from
			// the resting at-top glass/border/shadow above — so the converter fills Appearance-At-top from the
			// resting snapshot and Appearance-On-scroll from here.
			if ( isset( $sp['backdrop-filter'] ) && stripos( $sp['backdrop-filter'], 'blur' ) !== false ) { $out['scroll_glass'] = true; }
			if ( ! empty( $sp['box-shadow'] ) && 'none' !== strtolower( $sp['box-shadow'] ) ) { $out['scroll_shadow'] = true; }
			$sbb = isset( $sp['border-bottom'] ) ? $sp['border-bottom'] : '';
			if ( $sbb !== '' && stripos( $sbb, 'none' ) === false && ! preg_match( '/^0(px)?\s/', $sbb ) ) { $out['scroll_border'] = true; }
			// An OPAQUE scrolled bg (the header repaints solid on scroll) → the Scrolled Background. A transparent
			// scrolled bg (blur only) leaves this unset (the mapper supplies a dark tint for a dark site).
			$sbg = isset( $sp['background-color'] ) ? $sp['background-color'] : '';
			if ( $sbg !== '' && stripos( $sbg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*[,\/]\s*0\s*\)/i', $sbg ) ) { $out['scrolled_bg'] = $sbg; }
			// SHRINK: the header tightens its padding on scroll (padTop meaningfully smaller than at rest).
			$spt = isset( $sp['padding-top'] ) ? (float) $sp['padding-top'] : -1;
			$rpt = (float) self::sc_pad( $header, 'top' );
			if ( $spt >= 0 && $rpt > 0 && $spt < $rpt - 2 ) { $out['scroll_shrink'] = true; }
			// NUMERIC refinements (theme 2.5.90). scroll_shrink says the bar tightens; these say by how
			// much, and whether the nav text restyles with it. The capture stamps both into
			// data-sc-scrolled (height:NNpx / color:...), so they arrive with the rest of the state.
			if ( isset( $sp['height'] ) ) {
				$sh = (float) $sp['height'];
				if ( $sh >= 32 ) { $out['scroll_height'] = (int) round( $sh ); }
			}
			if ( ! empty( $sp['color'] ) ) { $out['scroll_link_color'] = trim( $sp['color'] ); }
			if ( isset( $sp['rest-height'] ) ) {
				$rh = (float) $sp['rest-height'];
				if ( $rh >= 32 ) { $out['rest_height'] = (int) round( $rh ); }
			}
			// Frost RADIUS + saturation of the scrolled state — the theme's glass was a fixed 10px.
			if ( isset( $sp['backdrop-filter'] ) && preg_match( '/blur\(\s*([0-9.]+)px/i', $sp['backdrop-filter'], $bm ) ) {
				$out['glass_blur'] = (int) round( (float) $bm[1] );
			}
			if ( isset( $sp['backdrop-filter'] ) && preg_match( '/saturate\(\s*([0-9.]+)(%?)/i', $sp['backdrop-filter'], $stm ) ) {
				$out['glass_saturate'] = (int) round( '%' === $stm[2] ? (float) $stm[1] : ( (float) $stm[1] * 100 ) );
			}
			// Shadow DEPTH from the blur radius of the first length triple (soft < 12px, strong > 26px).
			// `0 1px 4px` (unitless zero) is as common as `0px 1px 4px`; requiring px on all three
			// silently skipped those shadows and no depth was ever emitted. Mirror of the JS twin.
			if ( ! empty( $sp['box-shadow'] ) && preg_match( '/(-?[0-9.]+)(?:px)?\s+(-?[0-9.]+)(?:px)?\s+(-?[0-9.]+)px/', $sp['box-shadow'], $dm ) ) {
				$b = (float) $dm[3];
				$out['shadow_depth'] = $b < 12 ? 'soft' : ( $b > 26 ? 'strong' : 'medium' );
			}
		}
		$pt = self::sc_pad( $header, 'top' );  if ( $pt !== '' ) { $out['pad_top'] = $pt; }
		$pb = self::sc_pad( $header, 'bottom' ); if ( $pb !== '' ) { $out['pad_bottom'] = $pb; }
		// Mobile breakpoint: the responsive class that swaps the inline nav for the hamburger — a desktop nav
		// `hidden md:flex` / a `md:hidden` toggle ⇒ mobile below 768px (`md`); the `lg:` variants ⇒ below 992px
		// (`lg`, the theme default). Only emit on a real signal so we never write a false default.
		$bp = '';
		foreach ( $header->getElementsByTagName( '*' ) as $el ) {
			$c = ' ' . self::cls( $el ) . ' ';
			if ( preg_match( '/\shidden\s+(md|lg):flex\b/', $c, $m ) || preg_match( '/\s(md|lg):hidden\b/', $c, $m ) ) { $bp = $m[1]; break; }
		}
		if ( $bp === 'md' || $bp === 'lg' ) { $out['mobile_breakpoint'] = $bp; }
		return $out;
	}

	/* --------------------------------------------------------------------- *
	 * Header DESIGN classifier — pick one of the theme's four Header Designs
	 * (classic | pill | card | centered) deterministically from the source DOM.
	 * --------------------------------------------------------------------- */

	/**
	 * Classify the SOURCE header into a theme Header Design. Returns 'classic' | 'pill' | 'card' | 'centered'.
	 *
	 * The prior logic collapsed everything to "any rounded-full descendant ⇒ pill", which turned a classic
	 * bar into a floating pill whenever it merely held a round logo mark or a round CTA (payment-operations'
	 * 8×8 `rounded-full` logo badge did exactly that). This reads the real NAV SURFACE and its float treatment:
	 *
	 *   centered — the header stacks a centred logo ABOVE a centred nav (theme 'centered'). NOT the
	 *              nav-logo-nav split, which the theme documents as Classic with a centred logo column.
	 *   pill/card — the nav MENU is wrapped in a distinct, inset, rounded SURFACE that floats inside the
	 *              header (fill/blur/shadow + all-round radius + narrower than the header). pill = capsule
	 *              roundness (rounded-full / radius ≥ 28px); card = moderate radius (~8–28px) with a shadow.
	 *   classic — everything else (a full-width flush bar, incl. one holding a round logo/CTA).
	 */
	private static function detect_header_design( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return 'classic'; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return 'classic'; }
		if ( self::header_is_stacked_centered( $header ) ) { return 'centered'; }
		$surface = self::header_float_surface( $header );
		if ( $surface instanceof DOMElement ) {
			return self::surface_reads_pill( $surface ) ? 'pill' : 'card';
		}
		return 'classic';
	}

	/**
	 * The header's positioning box (position/left/right/top/bottom/width/height) from its data-sc-cs + inline
	 * style AND the source stylesheet rule for its tag / #id / .class — many rail headers set position + size
	 * via a class rule (`.header-rail{position:fixed;left:20px;width:88px}`), not Tailwind, so the computed
	 * snapshot alone misses it. Returns only the properties actually present, as raw CSS value strings.
	 */
	private static function header_source_geom( $html, $header ) {
		$props = array( 'position', 'left', 'right', 'top', 'bottom', 'width', 'height', 'min-height' );
		$out   = array();
		$cs    = (string) $header->getAttribute( 'data-sc-cs' ) . ';' . strtolower( (string) $header->getAttribute( 'style' ) );
		foreach ( $props as $p ) {
			if ( preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', $cs, $m ) ) { $out[ $p ] = trim( $m[1] ); }
		}
		$sels = array( preg_quote( strtolower( $header->tagName ), '/' ) );
		$hid  = trim( (string) $header->getAttribute( 'id' ) );
		if ( '' !== $hid ) { $sels[] = '#' . preg_quote( $hid, '/' ); }
		foreach ( preg_split( '/\s+/', (string) self::cls( $header ) ) as $c ) { $c = trim( $c ); if ( '' !== $c ) { $sels[] = '\.' . preg_quote( $c, '/' ); } }
		$re = '/(?:' . implode( '|', $sels ) . ')(?![\w-])[^{}]*\{([^}]*)\}/i';
		if ( preg_match_all( $re, self::all_style_css( $html ), $mm ) ) {
			foreach ( $mm[1] as $decls ) {
				foreach ( $props as $p ) {
					if ( ! isset( $out[ $p ] ) && preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', $decls, $dm ) ) { $out[ $p ] = trim( $dm[1] ); }
				}
			}
		}
		return $out;
	}

	/**
	 * Classify the header LAYOUT MODE — 'top' | 'vertical' | 'off-canvas-only' | 'overlay'. 'top' is the
	 * default (a normal horizontal header, whose structural Design is then picked by detect_header_design).
	 * The non-top modes are gated tightly so a normal horizontal bar never trips them (no AI-generated
	 * classic header should ever read as anything but 'top').
	 */
	private static function detect_header_mode( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return 'top'; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return 'top'; }
		$hc   = ' ' . strtolower( self::cls( $header ) ) . ' ';

		// VERTICAL side rail — a POSITIONED, COLUMN-stacked header that is full-height OR narrow (bespoke's
		// `.header-rail`: fixed; left/top/bottom set; width:88px; flex-direction:column). Requires positioning
		// + column + (full-height | narrow | vertical nav) so a horizontal top bar never matches.
		$geom = self::header_source_geom( $html, $header );
		$pos  = strtolower( (string) ( $geom['position'] ?? '' ) );
		$positioned = in_array( $pos, array( 'fixed', 'absolute', 'sticky' ), true ) || (bool) preg_match( '/\s(?:fixed|absolute|sticky)\s/', $hc );
		$fd     = strtolower( (string) self::sc_css( $header, 'flex-direction' ) );
		$column = ( 'column' === $fd ) || (bool) preg_match( '/\sflex-col\s/', $hc );
		$full_h = ( isset( $geom['top'] ) && isset( $geom['bottom'] ) )
			|| (bool) preg_match( '/\s(?:inset-y-0|h-screen|min-h-screen|h-full)\s/', $hc )
			|| ( isset( $geom['height'] ) && preg_match( '/(?:100vh|100%)/', (string) $geom['height'] ) )
			|| ( isset( $geom['min-height'] ) && preg_match( '/100vh/', (string) $geom['min-height'] ) );
		$narrow = false;
		if ( isset( $geom['width'] ) && preg_match( '/^([0-9.]+)px$/', trim( (string) $geom['width'] ), $wm ) && (float) $wm[1] <= 360 ) { $narrow = true; }
		if ( preg_match( '/\sw-(?:16|20|24|28|32|40|48|56|64|72|80)\b/', $hc ) || preg_match( '/\sw-\[[0-9.]+(?:px|rem)\]/', $hc ) ) { $narrow = true; }
		$nav  = $header->getElementsByTagName( 'nav' )->item( 0 );
		$vnav = false;
		if ( $nav instanceof DOMElement ) { $nfd = strtolower( (string) self::sc_css( $nav, 'flex-direction' ) ); $vnav = ( 'column' === $nfd ) || (bool) preg_match( '/\sflex-col\s/', ' ' . strtolower( self::cls( $nav ) ) . ' ' ); }
		// A rail is TALLER than it is wide, and its menu runs down. A floating centred PILL bar (`fixed top-6
		// left-1/2 -translate-x-1/2 w-[640px]`, a column wrapper around a horizontal nav) is wide + short with a
		// ROW nav — it was read as a vertical-left rail (a finding filed twice). The measured box decides.
		$hw = preg_match( '/^([0-9.]+)px$/', trim( (string) self::sc_css( $header, 'width' ) ), $hwm ) ? (float) $hwm[1] : 0.0;
		$hh = preg_match( '/^([0-9.]+)px$/', trim( (string) self::sc_css( $header, 'height' ) ), $hhm ) ? (float) $hhm[1] : 0.0;
		$wide_short = ( $hw > 0 && $hh > 0 && $hw > $hh );
		$row_nav = false;
		if ( $nav instanceof DOMElement ) { $nfd2 = strtolower( (string) self::sc_css( $nav, 'flex-direction' ) ); $row_nav = ( 'row' === $nfd2 || '' === $nfd2 ) && $nav->getElementsByTagName( 'a' )->length >= 3 && ! $vnav; }
		if ( $positioned && $column && ( $full_h || $narrow || $vnav ) && ! ( $wide_short && $row_nav ) ) { return 'vertical'; }

		// DESKTOP INLINE NAV gate — overlay / off-canvas-only apply ONLY when the header has NO real desktop
		// menu. A responsive site ships a mobile hamburger + a fixed full-viewport menu in the DOM ALONGSIDE
		// its desktop inline bar; the capture may even leave that mobile menu open. So count the header's
		// INLINE nav links (visible <a> with text that are NOT inside a fixed/absolute full-viewport overlay
		// container). ≥3 inline links ⇒ a normal desktop menu ⇒ 'top', regardless of any mobile overlay markup.
		$is_overlay_host = function ( $el ) use ( $header ) {
			for ( $p = $el->parentNode; $p instanceof DOMElement && $p !== $header; $p = $p->parentNode ) {
				$pcs = (string) $p->getAttribute( 'data-sc-cs' );
				$pc  = ' ' . strtolower( self::cls( $p ) ) . ' ';
				$pfixed = ( stripos( $pcs, 'position: fixed' ) !== false || stripos( $pcs, 'position:fixed' ) !== false || stripos( $pcs, 'position: absolute' ) !== false || stripos( $pcs, 'position:absolute' ) !== false || preg_match( '/\s(?:fixed|absolute)\s/', $pc ) );
				$pfull  = (bool) preg_match( '/\sinset-0\s/', $pc ) || ( preg_match( '/width:\s*100(?:vw|%)/i', $pcs ) && preg_match( '/height:\s*100(?:vh|%)/i', $pcs ) );
				if ( $pfixed && $pfull ) { return true; }
			}
			return false;
		};
		$inline_links = 0;
		foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
			$txt = trim( self::text_no_icons( $a ) );
			if ( '' === $txt ) { continue; }
			if ( 'none' === strtolower( (string) self::sc_css( $a, 'display' ) ) ) { continue; }
			if ( $is_overlay_host( $a ) ) { continue; }
			$inline_links++;
		}
		if ( $inline_links >= 3 ) { return 'top'; } // a real desktop menu → top bar (mobile overlay is just responsive)

		// OVERLAY fullscreen — a FIXED full-viewport container that HOLDS the primary nav (≥3 links) AND there
		// is no desktop inline menu (gated above): the hamburger→fullscreen-menu design.
		foreach ( $header->getElementsByTagName( 'div' ) as $d ) {
			$dc  = ' ' . strtolower( self::cls( $d ) ) . ' ';
			$dcs = (string) $d->getAttribute( 'data-sc-cs' );
			$fixed = ( stripos( $dcs, 'position: fixed' ) !== false || stripos( $dcs, 'position:fixed' ) !== false || preg_match( '/\sfixed\s/', $dc ) );
			$fullv = (bool) preg_match( '/\sinset-0\s/', $dc )
				|| ( preg_match( '/(?:^|;)\s*width:\s*100(?:vw|%)/i', $dcs ) && preg_match( '/(?:^|;)\s*height:\s*100(?:vh|%)/i', $dcs ) );
			if ( $fixed && $fullv && $d->getElementsByTagName( 'a' )->length >= 3 ) { return 'overlay'; }
		}

		// OFF-CANVAS ONLY — a hamburger/toggle is the header's only nav affordance (gated above: no desktop
		// inline menu), with no fullscreen overlay menu host.
		foreach ( $header->getElementsByTagName( 'button' ) as $b ) {
			$bc = ' ' . strtolower( self::cls( $b ) . ' ' . (string) $b->getAttribute( 'aria-label' ) ) . ' ';
			if ( preg_match( '/\b(?:hamburger|menu-toggle|nav-toggle|burger|toggle-menu|open-menu)\b/', $bc ) || preg_match( '/\bmenu\b/', (string) $b->getAttribute( 'aria-label' ) ) ) { return 'off-canvas-only'; }
		}

		return 'top';
	}

	/**
	 * Build the header_mode value tree for a detected non-top MODE (vertical / off-canvas-only / overlay),
	 * deriving the mode's own sub-options from the source (rail side + width for vertical). 'top' is handled
	 * by the caller (design classification). Returns the array to store at header_layout.header_mode.
	 */
	private static function header_mode_values( $html, $mode ) {
		$dom    = self::load_dom( $html );
		$header = $dom ? self::header_root( $dom ) : null;
		if ( 'vertical' === $mode && $header instanceof DOMElement ) {
			$geom = self::header_source_geom( $html, $header );
			$hc   = ' ' . strtolower( self::cls( $header ) ) . ' ';
			// SIDE — a right-anchored rail (right set, left unset, or a `right-*` class) → right; else left.
			$right = ( isset( $geom['right'] ) && ! isset( $geom['left'] ) ) || preg_match( '/\s(?:right-0|right-\d|inset-y-0\s+right)/', $hc );
			$side  = $right ? 'right' : 'left';
			// WIDTH — the rail's own width (px→rem, or an explicit rem), else the theme default (16.25rem).
			$wv = '16.25'; $wu = 'rem';
			if ( isset( $geom['width'] ) ) {
				$w = trim( (string) $geom['width'] );
				if ( preg_match( '/^([0-9.]+)px$/', $w, $m ) )      { $wv = (string) round( (float) $m[1] / 16, 2 ); $wu = 'rem'; }
				elseif ( preg_match( '/^([0-9.]+)rem$/', $w, $m ) ) { $wv = $m[1]; $wu = 'rem'; }
			}
			return array(
				'mode'     => 'vertical',
				'vertical' => array(
					'vertical_side'  => array( 'side' => $side ),
					'vertical_width' => array( 'value' => $wv, 'unit' => $wu ),
				),
			);
		}
		if ( 'overlay' === $mode ) {
			return array( 'mode' => 'overlay', 'overlay' => array( 'overlay_style' => array( 'style' => 'panel' ) ) );
		}
		if ( 'off-canvas-only' === $mode ) {
			return array( 'mode' => 'off-canvas-only' );
		}
		return array( 'mode' => 'top' );
	}

	/** Does this element WRAP THE NAV MENU (a `<nav>`, or ≥3 links) — i.e. it's the nav bar, not a logo/CTA? */
	private static function surface_wraps_nav( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( $el->getElementsByTagName( 'nav' )->length >= 1 ) { return true; }
		return $el->getElementsByTagName( 'a' )->length >= 3;
	}

	/** Rounded on ALL corners — a `rounded-{full,3xl,2xl,xl,lg}` class or a computed border-radius ≥ 10px. */
	private static function surface_radius_px( $el ) {
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( preg_match( '/\srounded-full\s/', $cls ) ) { return 9999.0; }
		$rad = self::sc_css( $el, 'border-top-left-radius' );
		if ( '' === $rad ) { $rad = self::sc_css( $el, 'border-radius' ); }
		if ( preg_match( '/([0-9.]+)px/', (string) $rad, $m ) ) { return (float) $m[1]; }
		if ( strpos( (string) $rad, '50%' ) !== false || strpos( (string) $rad, '9999' ) !== false ) { return 9999.0; }
		// class-only fallback (radius may not be in the computed snapshot): map the Tailwind scale to px.
		if ( preg_match( '/\srounded-3xl\s/', $cls ) ) { return 24.0; }
		if ( preg_match( '/\srounded-2xl\s/', $cls ) ) { return 16.0; }
		if ( preg_match( '/\srounded-xl\s/', $cls ) )  { return 12.0; }
		if ( preg_match( '/\srounded-lg\s/', $cls ) )  { return 8.0; }
		if ( preg_match( '/\srounded-\[([0-9.]+)(?:px|rem)\]/', $cls, $m ) ) { $v = (float) $m[1]; return strpos( $m[0], 'rem' ) !== false ? $v * 16 : $v; }
		return 0.0;
	}

	/**
	 * The VISIBLE layers of a computed box-shadow, or '' when none paint. A utility-built shadow (Tailwind's
	 * `var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow)`) computes with two transparent
	 * `rgba(0, 0, 0, 0) 0px 0px 0px 0px` placeholder layers FIRST, so a "first layer transparent → no shadow" test
	 * dropped every real `shadow-[…]` / `shadow-lg` behind them. Drop placeholder layers (a transparent colour, or an all-zero
	 * geometry) and keep the rest, in order. JS twin: shadowLayersOf (box-presets.mjs).
	 */
	public static function visible_shadow( $s ) {
		$s = trim( (string) $s );
		if ( '' === $s || 'none' === strtolower( $s ) ) { return ''; }
		$layers = array(); $depth = 0; $cur = '';
		for ( $i = 0, $len = strlen( $s ); $i < $len; $i++ ) {
			$ch = $s[ $i ];
			if ( '(' === $ch ) { $depth++; } elseif ( ')' === $ch ) { $depth--; }
			if ( ',' === $ch && 0 === $depth ) { $layers[] = $cur; $cur = ''; } else { $cur .= $ch; }
		}
		if ( '' !== trim( $cur ) ) { $layers[] = $cur; }
		$keep = array();
		foreach ( $layers as $layer ) {
			$layer = trim( $layer );
			if ( '' === $layer ) { continue; }
			if ( preg_match( '/rgba?\(\s*[0-9.]+[,\s]+[0-9.]+[,\s]+[0-9.]+[,\s\/]+0(?:\.0+)?\s*\)/i', $layer ) || stripos( $layer, 'transparent' ) !== false ) { continue; } // transparent colour
			$geo = preg_replace( '/(rgba?\([^)]*\)|#[0-9a-fA-F]{3,8}|\binset\b)/i', '', $layer );
			if ( ! preg_match( '/[1-9]/', $geo ) ) { continue; } // 0 0 0 0 → paints nothing
			$keep[] = $layer;
		}
		return implode( ', ', $keep );
	}

	/** Chrome = a real surface treatment: a backdrop blur, a box-shadow, or a non-transparent fill. */
	private static function surface_has_chrome( $el ) {
		$bf = self::sc_css( $el, 'backdrop-filter' );
		if ( '' === $bf || stripos( $bf, 'blur' ) === false ) { $bf = self::sc_css( $el, '-webkit-backdrop-filter' ); }
		if ( stripos( (string) $bf, 'blur' ) !== false ) { return true; }
		if ( '' !== self::visible_shadow( self::sc_css( $el, 'box-shadow' ) ) ) { return true; }
		$bg = self::sc_css( $el, 'background-color' );
		return ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/i', $bg ) );
	}

	/** Is the surface INSET from the header edges (a distinct floating bar, not an edge-to-edge classic bar) —
	 *  a `max-w-*` / `mx-auto` / margin cap on the surface OR ANY ANCESTOR up to the header (many sources put
	 *  the `max-w-7xl mx-auto` on a parent wrapper, not the rounded surface itself), a computed max-width, a
	 *  header that floats below the viewport top, or a `rounded-full` capsule (inherently a floating chip). */
	private static function surface_is_inset( $el, $header ) {
		// The surface, or any ancestor up to (and including) the header, carries a width cap / centering.
		for ( $n = $el; $n instanceof DOMElement; $n = $n->parentNode ) {
			$cls = ' ' . strtolower( self::cls( $n ) ) . ' ';
			if ( preg_match( '/\smax-w-(?!none|full)\S+/', $cls ) || preg_match( '/\smx-auto\s/', $cls ) || preg_match( '/\smx-[0-9]/', $cls ) ) { return true; }
			$mw = trim( (string) self::sc_css( $n, 'max-width' ) );
			if ( preg_match( '/^[0-9.]+px$/', $mw ) ) { return true; }
			if ( $n === $header ) { break; }
		}
		// The HEADER floats below the viewport top (top-4/6/8…, not top-0) OR is horizontally inset.
		$hc = ' ' . strtolower( self::cls( $header ) ) . ' ';
		if ( preg_match( '/\stop-\[?([1-9][0-9]*)/', $hc ) || preg_match( '/\s(?:inset-x-[1-9]|left-[1-9]|mx-auto)\b/', $hc ) ) { return true; }
		// A rounded-full nav surface is inherently a floating capsule even without an explicit cap.
		$sc = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( preg_match( '/\srounded-full\s/', $sc ) ) { return true; }
		return false;
	}

	/**
	 * The header's inner FLOATING nav surface — a rounded, chrome-bearing container that WRAPS THE NAV MENU
	 * and is inset from the header edges (a floating pill/card). Excludes a rounded logo badge / CTA (no
	 * menu) and a full-width flush bar (chrome sits on the header itself, edge to edge). Null when none.
	 * Shallow BFS (≤3) — the surface is always near the top of the header.
	 */
	private static function header_float_surface( $header ) {
		$queue = array( array( $header, 0 ) );
		while ( $queue ) {
			list( $el, $d ) = array_shift( $queue );
			if ( $el !== $header
				&& self::surface_wraps_nav( $el )
				&& self::surface_radius_px( $el ) >= 10.0
				&& self::surface_has_chrome( $el )
				&& self::surface_is_inset( $el, $header ) ) {
				return $el;
			}
			if ( $d >= 3 ) { continue; }
			foreach ( self::el_children( $el ) as $c ) { $queue[] = array( $c, $d + 1 ); }
		}
		return null;
	}

	/** A TRUE CAPSULE (fully-rounded ends) ⇒ Floating Pill; a rounded RECTANGLE ⇒ Elevated Card. Tailwind's
	 *  `rounded-full` compiles to a 9999px radius, so a real pill reads ≥100px (or a 50% radius); a deliberate
	 *  `rounded-[2rem]` (32px) wide glass bar is a card, not a pill. */
	private static function surface_reads_pill( $el ) {
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( preg_match( '/\srounded-full\s/', $cls ) ) { return true; }
		$rad = self::sc_css( $el, 'border-top-left-radius' );
		if ( '' === $rad ) { $rad = self::sc_css( $el, 'border-radius' ); }
		if ( strpos( (string) $rad, '50%' ) !== false || strpos( (string) $rad, '9999' ) !== false ) { return true; }
		return preg_match( '/([0-9.]+)px/', (string) $rad, $m ) ? ( (float) $m[1] >= 100.0 ) : false;
	}

	/**
	 * The 'centered' design — a header that STACKS a centred logo ABOVE a centred nav (a vertical, centre-
	 * aligned header), NOT the nav-logo-nav split (Classic + centred logo column). Signature: the header's
	 * primary content wrapper lays out as a flex COLUMN, centre-aligned, and holds a real <nav>/menu. Kept
	 * conservative so an ordinary horizontal bar is never mistaken for it.
	 */
	private static function header_is_stacked_centered( $header ) {
		if ( ! ( $header instanceof DOMElement ) ) { return false; }
		if ( $header->getElementsByTagName( 'nav' )->length < 1 && $header->getElementsByTagName( 'a' )->length < 3 ) { return false; }
		// A VERTICAL SIDE-RAIL (fixed, full-height, links stacked in a COLUMN — e.g. bespoke's `.header-rail`
		// + `.rail-nav{flex-direction:column}`) is NOT the theme's centered design (a centred logo above a
		// HORIZONTAL nav). Reject it: if the header's nav lays its links out vertically, fall back to classic.
		$nav = $header->getElementsByTagName( 'nav' )->item( 0 );
		if ( $nav instanceof DOMElement ) {
			$navfd = strtolower( (string) self::sc_css( $nav, 'flex-direction' ) );
			$navcl = ' ' . strtolower( self::cls( $nav ) ) . ' ';
			if ( 'column' === $navfd || preg_match( '/\sflex-col\s/', $navcl ) ) { return false; }
		}
		$scan = array( $header );
		foreach ( self::el_children( $header ) as $c ) { $scan[] = $c; }
		foreach ( $scan as $el ) {
			$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$fd  = strtolower( (string) self::sc_css( $el, 'flex-direction' ) );
			$ai  = strtolower( (string) self::sc_css( $el, 'align-items' ) );
			$col = ( 'column' === $fd ) || preg_match( '/\sflex-col\s/', $cls );
			$ctr = ( 'center' === $ai ) || preg_match( '/\sitems-center\s/', $cls ) || preg_match( '/\stext-center\s/', $cls );
			// The nav must sit BELOW the logo AND its links must be horizontal (a menu row, not a stacked rail).
			if ( $col && $ctr ) {
				$innav = $el->getElementsByTagName( 'nav' )->item( 0 );
				if ( $innav instanceof DOMElement ) {
					$ifd = strtolower( (string) self::sc_css( $innav, 'flex-direction' ) );
					$icl = ' ' . strtolower( self::cls( $innav ) ) . ' ';
					if ( 'column' === $ifd || preg_match( '/\sflex-col\s/', $icl ) ) { continue; }
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Sub-options for the detected Header Design, derived from the SOURCE surface so the design renders with
	 * the source's roundness / shadow / inset (not just the theme defaults). Returns the array to place under
	 * header_design[$design] (e.g. [ 'pill_radius' => 'large', 'pill_shadow' => 'strong' ]). Empty for classic.
	 */
	private static function header_design_sub( $html, $design, $hstyle ) {
		if ( 'classic' === $design ) { return array(); }
		$dom = self::load_dom( $html );
		$header = $dom ? self::header_root( $dom ) : null;
		$surface = ( $header instanceof DOMElement ) ? self::header_float_surface( $header ) : null;
		if ( 'centered' === $design ) { return array( 'centered_gap' => 'normal' ); }
		$rad = ( $surface instanceof DOMElement ) ? self::surface_radius_px( $surface ) : 0.0;
		$cls = ( $surface instanceof DOMElement ) ? ' ' . strtolower( self::cls( $surface ) ) . ' ' : ' ';
		// Shadow depth: read the surface box-shadow's largest blur/spread → soft / medium / strong.
		$shadow_tier = 'medium';
		if ( $surface instanceof DOMElement ) {
			$sh = (string) self::sc_css( $surface, 'box-shadow' );
			if ( preg_match_all( '/(-?[0-9.]+)px/', $sh, $sm ) && ! empty( $sm[1] ) ) {
				$max = 0.0; foreach ( $sm[1] as $v ) { $max = max( $max, abs( (float) $v ) ); }
				$shadow_tier = ( $max >= 40 ) ? 'strong' : ( ( $max >= 16 ) ? 'medium' : 'soft' );
			} elseif ( '' === $sh || 'none' === $sh ) {
				$shadow_tier = 'soft';
			}
		}
		if ( 'pill' === $design ) {
			$sub = array();
			// Width — from the chrome detector (a capped source pill → fixed, a shrink-to-fit pill → hug).
			if ( ! empty( $hstyle['pill_hug'] ) || isset( $hstyle['pill_fixed'] ) ) {
				$sub['pill_width'] = isset( $hstyle['pill_fixed'] ) ? 'fixed' : 'hug';
			}
			// Roundness — rounded-full / ≥ 9990 = full; ≥ 20px = large; else medium.
			$sub['pill_radius'] = ( preg_match( '/\srounded-full\s/', $cls ) || $rad >= 9990 ) ? 'full' : ( $rad >= 20 ? 'large' : 'medium' );
			// Side inset — the header's own horizontal inset (`inset-x-*` / `mx-*` / `left-*`) → small/large.
			$hc = ( $header instanceof DOMElement ) ? ' ' . strtolower( self::cls( $header ) ) . ' ' : ' ';
			$sub['pill_inset'] = preg_match( '/\s(?:inset-x-(?:8|10|12|16|20)|mx-(?:8|10|12|16|20)|px-(?:8|10|12|16|20))\b/', $hc ) ? 'large' : ( preg_match( '/\s(?:inset-x-[1-9]|mx-[1-9]|px-[4-8])\b/', $hc ) ? 'small' : 'none' );
			$sub['pill_shadow'] = $shadow_tier;
			return $sub;
		}
		if ( 'card' === $design ) {
			$sub = array(
				'card_radius' => ( $rad >= 20 ? 'large' : ( $rad >= 10 ? 'medium' : 'small' ) ),
				'card_shadow' => $shadow_tier,
			);
			// The card's OWN placement: the source bar's padding is the gap around the floating card — its top padding → the
			// native Top Offset, its side padding → a side inset on the card (no native field; a residual rule). Without it the
			// card sat flush against the viewport edges while the source floated it 40px in.
			if ( $header instanceof DOMElement ) {
				$hp = self::sc_padding_box( $header );
				if ( (float) $hp['top'] > 0 ) { $sub['card_offset'] = array( 'value' => (string) (int) round( (float) $hp['top'] ), 'unit' => 'px' ); }
				$side = min( (float) $hp['left'], (float) $hp['right'] );
				if ( $side > 0 ) {
					$cw = ( $surface instanceof DOMElement ) ? (float) ( preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/i', (string) $surface->getAttribute( 'data-sc-cs' ), $mwm ) ? $mwm[1] : 0 ) : 0;
					$spad2 = self::sc_padding_box( $surface ); $pad_css = ( (float) $spad2['top'] > 0 || (float) $spad2['left'] > 0 ) ? 'padding:' . (int) round( (float) $spad2['top'] ) . 'px ' . (int) round( (float) $spad2['right'] ) . 'px ' . (int) round( (float) $spad2['bottom'] ) . 'px ' . (int) round( (float) $spad2['left'] ) . 'px;' : ''; // the card's own inset (the theme's .5rem 1.5rem otherwise)
					self::$header_card_css = '.site-header--design-card .header-main > [class*="fw-container"]{margin-left:' . (int) round( $side ) . 'px;margin-right:' . (int) round( $side ) . 'px;width:auto;flex:1 1 auto;' . $pad_css . ( $cw >= 600 ? 'max-width:' . (int) round( $cw ) . 'px;' : '' ) . '}' . "
" . '@media (min-width:' . ( (int) round( $cw >= 600 ? $cw + 2 * $side : 0 ) ) . 'px){.site-header--design-card .header-main > [class*="fw-container"]{margin-left:auto;margin-right:auto;}}';
				}
			}
			return $sub;
		}
		return array();
	}

	/** The floating card header's side inset rule (header_design_sub), appended to the residual chrome CSS. */
	private static $header_card_css = '';

	/**
	 * The primary NAV MENU link styling, read from the header nav <a> computed styles. Returns any of:
	 *   link_color (the NORMAL link color = the most common), hover_color (a different/active link color),
	 *   font_size ({value,unit}), font_weight (string), uppercase (bool). Excludes the brand link (has an
	 *   svg/img) and CTA buttons, so only real nav links are sampled.
	 */
	/**
	 * H4 — Submenu / dropdown panel styling. Only fires when the source header genuinely has a dropdown:
	 * a nav item containing a nested `<ul>`/panel (role=menu / `.dropdown`/`.submenu` / a `<ul>` inside an
	 * `<li>`). Reads the panel's computed bg / link color / corner radius / min-width, and infers the
	 * Dropdown Design (bordered when it has a border + no shadow, elevated when a deep shadow, minimal when
	 * flat, else classic). Returns empty when no dropdown exists (most one-page sources). See header.md.
	 */
	/**
	 * H11 — the header's main flex row layout: vertical alignment (`align-items`) → header_valign, and the
	 * inter-element `gap` → header_element_gap. Reads the header's densest flex row (the logo·menu·CTA row).
	 * Only returns a key on a real, non-default signal (valign only when top/bottom; gap only when measured),
	 * so the theme's sensible defaults (center / auto gap) are never overwritten with redundant values.
	 */
	private static function detect_header_row_layout( $html ) {
		$out = array();
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return $out; }
		// The header's densest FLEX row = the element with the most element children whose cs says display:flex.
		$best = null; $best_n = 1;
		foreach ( $header->getElementsByTagName( 'div' ) as $d ) {
			$cs = (string) $d->getAttribute( 'data-sc-cs' );
			if ( strpos( $cs, 'display:flex' ) === false && strpos( $cs, 'display:inline-flex' ) === false ) { continue; }
			$n = 0; foreach ( self::el_children( $d ) as $k ) { $n++; }
			if ( $n > $best_n ) { $best_n = $n; $best = $d; }
		}
		if ( ! ( $best instanceof DOMElement ) ) { return $out; }
		$cs = (string) $best->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/align-items:\s*(flex-start|start|flex-end|end)/', $cs, $am ) ) {
			$out['valign'] = ( strpos( $am[1], 'end' ) !== false ) ? 'bottom' : 'top';
		}
		if ( preg_match( '/(?:^|;)\s*gap:\s*([0-9.]+)px/', $cs, $gm ) && (float) $gm[1] > 0 ) {
			$out['gap'] = array( 'value' => round( (float) $gm[1] / 16, 2 ), 'unit' => 'rem' );
		}
		return $out;
	}

	private static function detect_submenu_styles( $html ) {
		$out = array();
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return $out; }
		$panel = null;
		// A submenu panel = a <ul> nested inside a nav <li>, or an element whose class marks it a dropdown.
		foreach ( $header->getElementsByTagName( 'li' ) as $li ) {
			foreach ( self::el_children( $li ) as $k ) {
				if ( strtolower( $k->nodeName ) === 'ul' && $k->getElementsByTagName( 'a' )->length >= 1 ) { $panel = $k; break 2; }
			}
		}
		if ( ! $panel ) {
			foreach ( array( 'ul', 'div' ) as $tag ) {
				foreach ( $header->getElementsByTagName( $tag ) as $el ) {
					$c = ' ' . strtolower( self::cls( $el ) ) . ' ';
					if ( ( strpos( $c, 'dropdown' ) !== false || strpos( $c, 'submenu' ) !== false || strpos( $c, 'sub-menu' ) !== false ) && $el->getElementsByTagName( 'a' )->length >= 1 ) { $panel = $el; break 2; }
				}
			}
		}
		if ( ! ( $panel instanceof DOMElement ) ) { return $out; }
		$bg = self::sc_css( $panel, 'background-color' );
		if ( $bg !== '' ) { $out['menu_dropdown_bg'] = $bg; }
		$r = self::sc_css( $panel, 'border-radius' );
		if ( preg_match( '/([0-9.]+)px/', $r, $rm ) && (float) $rm[1] > 0 ) { $out['menu_dropdown_radius'] = array( 'value' => round( (float) $rm[1] ), 'unit' => 'px' ); }
		$w = self::sc_css( $panel, 'max-width' );
		if ( preg_match( '/([0-9.]+)px/', $w, $wm ) && (float) $wm[1] >= 120 ) { $out['menu_dropdown_width'] = array( 'value' => round( (float) $wm[1] ), 'unit' => 'px' ); }
		// A dropdown link colour (first anchor inside the panel).
		$a1 = $panel->getElementsByTagName( 'a' )->item( 0 );
		if ( $a1 instanceof DOMElement ) { $lc = self::sc_css( $a1, 'color' ); if ( $lc !== '' ) { $out['menu_dropdown_link'] = $lc; } }
		// Dropdown Design from border vs shadow.
		$bw = self::sc_css( $panel, 'border-top-width' ); $sh = self::sc_css( $panel, 'box-shadow' );
		$has_border = preg_match( '/([0-9.]+)px/', $bw, $bwm ) && (float) $bwm[1] > 0;
		$has_shadow = $sh !== '' && stripos( $sh, 'none' ) === false;
		if ( $has_border && ! $has_shadow )      { $out['menu_dropdown_style'] = 'bordered'; }
		elseif ( ! $has_border && ! $has_shadow ) { $out['menu_dropdown_style'] = 'minimal'; }
		// (a deep shadow → 'elevated' would need blur-radius parsing; classic default covers the shadowed case)
		return $out;
	}

	/** The <body>'s computed font-family stack ('' when unstamped). */
	private static function detect_body_font_stack( $dom ) {
		if ( ! ( $dom instanceof DOMDocument ) ) { return ''; }
		$body = $dom->getElementsByTagName( 'body' )->item( 0 );
		return $body instanceof DOMElement ? (string) self::sc_css( $body, 'font-family' ) : '';
	}

	private static function detect_menu_styles( $html ) {
		$out = array();
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! ( $header instanceof DOMElement ) ) { return $out; }
		$colors = array(); $fs = ''; $fw = ''; $tt = ''; $ls = '';
		// H3 — per-item chrome tallies (the MODE across the real nav links decides the item style).
		$bgs = array(); $rads = array(); $pads_x = array(); $pads_y = array(); $borders = 0; $underlines = 0; $items = 0;
		$fss = array(); $fws = array(); $tts = array(); $lss = array(); $ffs = array(); // typography tallies (the MODE across the nav links decides)
		foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
			if ( ( self::is_button( $a ) || self::cs_is_button( $a ) ) && ! self::nav_pill_sibling( $a ) ) { continue; }         // skip the CTA (a pill nav's items are all skinned — they ARE the menu)
			if ( self::nav_el_hidden( $a ) ) { continue; }                               // skip a hidden drawer's duplicate links
			if ( $a->getElementsByTagName( 'svg' )->length || $a->getElementsByTagName( 'img' )->length ) { continue; } // skip brand/icon links
			// Skip the BRAND wordmark — a LARGE home link (e.g. "Maison" at 30px, font-serif/tracking-tight)
			// is the logo, not a nav item; sampling it pollutes the menu style (font-size/letter-spacing/weight).
			// A normal-sized home link (a real "Home" nav item) is kept, so its colour still counts.
			$href = trim( (string) $a->getAttribute( 'href' ) );
			$is_home = ( $href === '' || $href === '#' || $href === '/' || preg_match( '~^https?://[^/]+/?$~', $href ) );
			if ( $is_home ) {
				$hfs = self::sc_css( $a, 'font-size' );
				if ( preg_match( '/([0-9.]+)px/', $hfs, $hm ) && (float) $hm[1] >= 20 ) { continue; }
			}
			$txt = trim( self::text_no_icons( $a ) );
			if ( $txt === '' || str_word_count( $txt ) > 4 ) { continue; }               // a nav label is short
			$c = self::sc_css( $a, 'color' );
			if ( $c !== '' ) { $colors[] = $c; }
			// The computed style can't see :hover, so read a `hover:text-<token>` utility from the class —
			// the source's real hover colour (modfii nav = `hover:text-foreground`, a quiet dark, NOT the
			// loud accent the fallback would use).
			if ( ! isset( $hvtok ) && preg_match( '/hover:text-([a-z][a-z0-9-]*)/', self::cls( $a ), $hvm ) ) { $hvtok = $hvm[1]; }
			// The capture's RESOLVED :hover (data-sc-hover `hover-self{color:…}`, stamped from the source's own
			// `a:hover{color}` rule) — the real hover colour on any framework, not only a Tailwind utility.
			if ( ! isset( $hvcs ) && preg_match( '/(?:^|[{;])\s*color:\s*(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', (string) $a->getAttribute( 'data-sc-hover' ), $hcm ) ) { $hvcs = $hcm[1]; }
			// Typography by MODE across the nav links (the first link sampled could be a "Sign in" beside the CTA or a
			// drawer item at another size — the tech probe's 14px/500 nav read as 16px/400).
			$v = self::sc_css( $a, 'font-size' ); if ( '' !== $v ) { $fss[] = $v; }
			$v = self::sc_css( $a, 'font-weight' ); if ( '' !== $v ) { $fws[] = $v; }
			$v = self::sc_css( $a, 'text-transform' ); if ( '' !== $v ) { $tts[] = $v; }
			$v = self::sc_css( $a, 'letter-spacing' ); if ( '' !== $v ) { $lss[] = $v; }
			$v = self::sc_css( $a, 'font-family' ); if ( '' !== $v ) { $ffs[] = $v; }
			$items++;
			// Capture drops transparent background-color, so a non-empty value is already a real fill.
			$bg  = self::sc_css( $a, 'background-color' );
			if ( $bg !== '' ) { $bgs[] = $bg; }
			$r = self::sc_css( $a, 'border-radius' ); if ( preg_match( '/([0-9.]+)px/', $r, $rm ) && (float) $rm[1] > 0 ) { $rads[] = (float) $rm[1]; }
			$bw = self::sc_css( $a, 'border-top-width' );
			if ( preg_match( '/([0-9.]+)px/', $bw, $bm ) && (float) $bm[1] > 0 ) { $borders++; }
			$td = self::sc_css( $a, 'text-decoration-line' );
			if ( stripos( $td, 'underline' ) !== false ) { $underlines++; }
			// `padding` is stamped as the shorthand (1–4 values); derive y=top, x=left.
			$pad = self::sc_css( $a, 'padding' );
			if ( $pad !== '' ) {
				$pp = preg_split( '/\s+/', trim( $pad ) ); $n = count( $pp );
				$top  = isset( $pp[0] ) && preg_match( '/([0-9.]+)px/', $pp[0], $tm ) ? (float) $tm[1] : 0;
				$leftv = ( $n >= 4 ? $pp[3] : ( $n >= 2 ? $pp[1] : ( $pp[0] ?? '' ) ) );
				$left = preg_match( '/([0-9.]+)px/', (string) $leftv, $lm ) ? (float) $lm[1] : 0;
				if ( $left > 0 ) { $pads_x[] = $left; }
				if ( $top > 0 )  { $pads_y[] = $top; }
			}
		}
		$mode = function ( array $vals ) { if ( ! $vals ) { return ''; } $f = array_count_values( $vals ); arsort( $f ); return (string) array_key_first( $f ); };
		$fs = $mode( $fss ); $fw = $mode( $fws ); $tt = $mode( $tts ); $ls = $mode( $lss );
		// the nav's FONT FAMILY (its first named face) when it is not the page body's — a display-face nav (`font-heading`)
		// had rendered in the body serif because the theme's Menu Font stayed empty (a real-site audit)
		$ffm = $mode( $ffs );
		if ( '' !== $ffm ) {
			$nav_fam = trim( trim( (string) preg_split( '/\s*,\s*/', $ffm )[0] ), "\"' " );
			$body_fam = trim( trim( (string) preg_split( '/\s*,\s*/', self::detect_body_font_stack( $dom ) )[0] ), "\"' " );
			if ( '' !== $nav_fam && ! in_array( strtolower( $nav_fam ), array( 'inherit', 'initial', 'sans-serif', 'serif', 'monospace', 'system-ui', '-apple-system', 'ui-sans-serif', 'ui-serif' ), true ) && strcasecmp( $nav_fam, $body_fam ) !== 0 ) { $out['font_family'] = $nav_fam; }
		}
		if ( $colors ) {
			$freq = array_count_values( $colors );
			arsort( $freq );
			$normal = (string) array_key_first( $freq );
			$out['link_color'] = $normal;
			// The odd colour = the active item ONLY when it is a real minority among several links (one of >= 3); a
			// two-link header, or a secondary "Sign in" beside the CTA, is not an active state.
			if ( count( $colors ) >= 3 ) { foreach ( $freq as $c => $n ) { if ( $c !== $normal && 1 === $n ) { $out['hover_color'] = (string) $c; break; } } }
		}
		// A captured :hover colour beats the "odd colour = active" guess.
		if ( ! empty( $hvcs ) ) { $out['hover_color'] = $hvcs; }
		// Class-derived hover colour (the :hover the computed style missed) — resolve the `hover:text-<token>`
		// token via the source's semantic palette so a `hover:text-foreground` maps to the real dark, not accent.
		if ( empty( $out['hover_color'] ) && ! empty( $hvtok ) ) {
			$sem = ( class_exists( 'FW_Site_Converter_Tailwind' ) && method_exists( 'FW_Site_Converter_Tailwind', 'extract_semantic_colors' ) )
				? (array) FW_Site_Converter_Tailwind::extract_semantic_colors( (string) $html ) : array();
			$hc = isset( $sem[ $hvtok ] ) ? (string) $sem[ $hvtok ] : '';
			if ( $hc !== '' ) { $out['hover_color'] = $hc; }
		}
		if ( $fs !== '' ) { $u = self::css_len_to_unit( $fs ); if ( $u ) { $out['font_size'] = $u; } }
		if ( preg_match( '/^(300|400|500|600|700|800)$/', trim( $fw ) ) ) { $out['font_weight'] = trim( $fw ); }
		if ( $tt !== '' ) { $out['uppercase'] = ( stripos( $tt, 'uppercase' ) !== false ); }
		if ( $ls !== '' && $ls !== 'normal' && $ls !== '0px' ) { $lsu = self::css_len_to_unit( $ls ); if ( $lsu ) { $out['letter_spacing'] = $lsu; } }

		/* --- H3 — Menu Item Style + item background + link padding, from the tallies above. A filled item
		   (most links carry a non-transparent bg) → 'pill' when its radius is large (>=16px, a rounded chip)
		   else 'box'; an item with a real border but no fill → 'outline'; underlined links → 'underline';
		   otherwise 'none'. Only decide on a real signal (>= half the items agree) so a lone styled link
		   never mislabels the whole nav. See header.md → menu_item_style. --- */
		if ( $items >= 2 ) {
			$half = $items / 2;
			$filled = count( $bgs ) >= $half;
			if ( $filled ) {
				$rad = $rads ? max( $rads ) : 0;
				$out['item_style'] = $rad >= 16 ? 'pill' : 'box';
				$bgfreq = array_count_values( $bgs ); arsort( $bgfreq );
				$out['item_bg'] = (string) array_key_first( $bgfreq );
			} elseif ( $borders >= $half ) {
				$out['item_style'] = 'outline';
			} elseif ( $underlines >= $half ) {
				$out['item_style'] = 'underline';
			} else {
				$out['item_style'] = 'none'; // plain links: written EXPLICITLY so a previous conversion's (or the install's) pill / box default never leaks onto square links
			}
			// Link padding — the median measured inset (rounded), so the converted item box matches the source.
			$mid = function ( $arr ) { if ( ! $arr ) { return 0; } sort( $arr ); return $arr[ intval( floor( ( count( $arr ) - 1 ) / 2 ) ) ]; };
			$px = $mid( $pads_x ); $py = $mid( $pads_y );
			if ( $px > 0 ) { $out['pad_x'] = array( 'value' => round( $px ), 'unit' => 'px' ); }
			if ( $py > 0 ) { $out['pad_y'] = array( 'value' => round( $py ), 'unit' => 'px' ); }
			// PADDING-LESS links — a flex row spaced by its `gap`, not by link padding. The theme's default link
			// inset (0.5rem × 1rem) then inflates every item box (a 15px source nav row rendered 36px tall and
			// the row's own gap doubled up). Pin both insets to 0 and carry the row's gap as the item spacing.
			if ( $items >= 2 && ! $pads_x && ! $pads_y ) {
				$out['pad_x'] = array( 'value' => 0, 'unit' => 'px' );
				$out['pad_y'] = array( 'value' => 0, 'unit' => 'px' );
				$grp = self::find_menu_group( $header );
				$gap = ( $grp instanceof DOMElement ) ? self::sc_css( $grp, 'gap' ) : '';
				if ( preg_match( '/^([0-9.]+)px/', $gap, $gm ) && (float) $gm[1] > 0 ) { $out['gap'] = (int) round( (float) $gm[1] ); }
			}
		}
		return $out;
	}

	/**
	 * FOOTER chrome styles from the <footer> computed `data-sc-cs`: pad_top/pad_bottom (lengths), border
	 * (top hairline {width,style,color} when present), radius (top border-radius when the footer is rounded,
	 * e.g. `rounded-t-[3rem]`). Only detected keys present.
	 */
	/**
	 * Shared Custom-Styling detector: read a section BAND element's computed BORDER (the one shared width /
	 * style / colour + the edges that carry it) and BACKGROUND fill → the `{prefix}_border` / `_border_sides`
	 * / `_border_extent` / `_background` fields for that band's Custom Styling block. Reusable for the footer
	 * copyright band, the top/main/bottom bars, etc. Returns array() when the band has no detectable chrome.
	 *
	 * @param DOMElement $el     The band element.
	 * @param string     $prefix The Custom-Styling field prefix (e.g. 'copyright', 'topbar', 'main_footer').
	 * @return array
	 */
	private static function detect_band_custom_fields( $el, $prefix ) {
		$out = array();
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		// BORDER — per-edge computed widths; emit the ONE shared border + the sides that actually carry it.
		$sides = array(); $bw = ''; $bstyle = 'solid'; $bcolor = '';
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $side ) {
			$w  = self::sc_css( $el, 'border-' . $side . '-width' );
			$st = self::sc_css( $el, 'border-' . $side . '-style' );
			if ( $w !== '' && (float) $w > 0 && $st !== '' && $st !== 'none' ) {
				$c = self::sc_css( $el, 'border-' . $side . '-color' );
				if ( $c !== '' && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $c ) ) {
					$sides[] = $side;
					if ( $bw === '' ) { $bw = $w; $bstyle = $st; $bcolor = $c; }
				}
			}
		}
		if ( $sides && $bw !== '' && $bcolor !== '' ) {
			$out[ $prefix . '_border' ] = array(
				'width' => array( 'value' => (string) max( 1, (int) round( (float) $bw ) ), 'unit' => 'px' ),
				'style' => $bstyle,
				'color' => array( 'predefined' => '', 'custom' => self::color_keep_alpha( $bcolor ) ),
			);
			$out[ $prefix . '_border_sides' ]  = $sides;
			$out[ $prefix . '_border_extent' ] = array( 'mode' => 'full' );
		}
		// BACKGROUND — an opaque fill on the band itself (skips transparent / inherited).
		$bg = self::sc_css( $el, 'background-color' );
		if ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) {
			$out[ $prefix . '_background' ] = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => self::color_keep_alpha( $bg ) ) ) );
		}
		return $out;
	}

	/** A colour for a custom colour field: opaque → #hex; translucent (alpha < 1) → the rgba() itself, so a
	 *  hairline rgba(255,255,255,.08) stays a hairline instead of flattening to solid white. */
	private static function color_keep_alpha( $color ) {
		$c = trim( (string) $color );
		if ( preg_match( '/^rgba?\(\s*[0-9.]+[,\s]+[0-9.]+[,\s]+[0-9.]+[,\s\/]+([0-9.]+%?)\s*\)$/i', $c, $m ) ) {
			$a = strpos( $m[1], '%' ) !== false ? (float) $m[1] / 100 : (float) $m[1];
			if ( $a < 0.99 ) { return preg_replace( '/\s+/', ' ', $c ); }
		}
		return self::color_to_hex( $c );
	}

	/**
	 * The footer's BOXED BODY: a single-child chain from <footer> reaches a PANEL — an element with ≥ 2 content
	 * rows that paints its own skin (a hairline border, a translucent / opaque fill, a gradient or a shadow) and
	 * carries an inset (padding). That panel is the theme's Footer → Layout → Boxed Body. Null when the footer's
	 * content sits directly on the footer (the common case).
	 */
	private static function detect_footer_shell( $footer ) {
		if ( ! ( $footer instanceof DOMElement ) ) { return null; }
		$node = $footer;
		for ( $d = 0; $d < 4; $d++ ) {
			$kids = self::el_children( $node );
			$content = array();
			foreach ( $kids as $k ) { if ( trim( $k->textContent ) !== '' || $k->getElementsByTagName( 'img' )->length || $k->getElementsByTagName( 'svg' )->length ) { $content[] = $k; } }
			if ( $node !== $footer && count( $content ) >= 2 && self::el_paints_panel( $node ) ) { return $node; }
			if ( count( $content ) !== 1 ) { return null; }
			$node = $content[0];
		}
		return null;
	}

	/** TRUE when an element paints a panel skin: a visible border on any edge, a non-transparent fill, a gradient
	 *  background-image, or a visible box-shadow — AND a non-zero padding (a skinned wrapper with no inset is a band). */
	private static function el_paints_panel( $el ) {
		$pad = self::sc_css( $el, 'padding' );
		if ( ! preg_match( '/[1-9]/', $pad ) ) { return false; }
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $side ) {
			$w = self::sc_css( $el, 'border-' . $side . '-width' ); $st = self::sc_css( $el, 'border-' . $side . '-style' ); $c = self::sc_css( $el, 'border-' . $side . '-color' );
			if ( $w !== '' && (float) $w > 0 && $st !== '' && $st !== 'none' && $c !== '' && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $c ) ) { return true; }
		}
		$bg = self::sc_css( $el, 'background-color' );
		if ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) { return true; }
		$bgi = self::sc_css( $el, 'background-image' );
		if ( $bgi !== '' && stripos( $bgi, 'gradient' ) !== false ) { return true; }
		$sh = self::sc_css( $el, 'box-shadow' );
		if ( $sh !== '' && $sh !== 'none' ) { return true; }
		return false;
	}

	/**
	 * Read a footer shell → { fields: footer_body_box.yes values, css: residual rules[], copyright_inside: bool }.
	 *  - Max Width from the WIDE (xl, 1920px) pass: a margin that GROWS with the viewport means the panel is
	 *    capped (width:min(1600px, 100% - 32px)) → 1920 − 2 × xl-margin; the base margin is the side gutter.
	 *  - Padding (y / x), fill (colour with alpha; ONE linear gradient → native, a multi-layer stack → verbatim
	 *    CSS), a uniform four-edge border, radius, the first box-shadow layer.
	 *  - Empty absolutely-positioned DECOR children (a gradient "roofline" strip) → the panel's ::before/::after.
	 */
	private static function footer_box_values( $shell ) {
		$f = array(); $css = array();
		$g = function ( $p ) use ( $shell ) { return trim( (string) self::sc_css( $shell, $p ) ); };
		$px = function ( $v ) { return preg_match( '/^(-?[0-9.]+)px$/', trim( (string) $v ), $m ) ? (float) $m[1] : null; };
		// Width cap + gutter.
		$m_base = preg_split( '/\s+/', $g( 'margin' ) ); $ml = isset( $m_base[1] ) ? $px( $m_base[1] ) : ( isset( $m_base[0] ) ? $px( $m_base[0] ) : null );
		$xl = (string) $shell->getAttribute( 'data-sc-cs-xl' ); $mxl = null;
		if ( preg_match( '/(?:^|;)\s*margin:\s*([^;]+)/i', $xl, $mm ) ) { $mp = preg_split( '/\s+/', trim( $mm[1] ) ); $mxl = isset( $mp[1] ) ? $px( $mp[1] ) : $px( $mp[0] ); }
		if ( null !== $mxl && null !== $ml && $mxl > $ml + 1 ) { $f['footer_box_max_width'] = array( 'value' => (string) (int) round( 1920 - 2 * $mxl ), 'unit' => 'px' ); }
		elseif ( preg_match( '/^([0-9.]+)px$/', $g( 'max-width' ), $mw ) ) { $f['footer_box_max_width'] = array( 'value' => (string) (int) round( (float) $mw[1] ), 'unit' => 'px' ); }
		if ( null !== $ml && $ml > 0 ) { $f['footer_box_gutter'] = array( 'value' => (string) (int) round( $ml ), 'unit' => 'px' ); }
		// Padding.
		$pp = preg_split( '/\s+/', $g( 'padding' ) );
		$pt = $px( $pp[0] ); $pr = isset( $pp[1] ) ? $px( $pp[1] ) : $pt;
		if ( null !== $pt ) { $f['footer_box_padding_y'] = array( 'value' => (string) (int) round( $pt ), 'unit' => 'px' ); }
		if ( null !== $pr ) { $f['footer_box_padding_x'] = array( 'value' => (string) (int) round( $pr ), 'unit' => 'px' ); }
		// Fill.
		$bg = $g( 'background-color' ); $bgi = $g( 'background-image' );
		$bgv = array( 'color' => array( 'value' => array( 'predefined' => '', 'custom' => '' ) ) );
		if ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) { $bgv['color']['value']['custom'] = self::color_keep_alpha( $bg ); }
		if ( $bgi !== '' && stripos( $bgi, 'gradient' ) !== false && stripos( $bgi, 'url(' ) === false ) {
			$gv = class_exists( 'FW_Site_Converter_Mapper' ) ? FW_Site_Converter_Mapper::parse_linear_gradient( $bgi ) : null;
			if ( is_array( $gv ) ) { $bgv['gradient'] = array( 'data' => $gv ); }
			else { $css[] = '.footer--boxed .footer__body{background-image:' . $bgi . ';}'; }
		}
		if ( $bgv['color']['value']['custom'] !== '' || isset( $bgv['gradient'] ) ) { $f['footer_box_background'] = $bgv; }
		// Border — uniform four edges → the native row; anything partial → residual per edge.
		$edges = array();
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $side ) {
			$w = $g( 'border-' . $side . '-width' ); $st = $g( 'border-' . $side . '-style' ); $c = $g( 'border-' . $side . '-color' );
			if ( $w !== '' && (float) $w > 0 && $st !== '' && $st !== 'none' && $c !== '' && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $c ) ) { $edges[ $side ] = array( $w, $st, $c ); }
		}
		if ( count( $edges ) === 4 && count( array_unique( array_map( 'json_encode', $edges ) ) ) === 1 ) {
			$e = reset( $edges );
			$f['footer_box_border'] = array( 'width' => array( 'value' => (string) max( 1, (int) round( (float) $e[0] ) ), 'unit' => 'px' ), 'style' => $e[1], 'color' => array( 'predefined' => '', 'custom' => self::color_keep_alpha( $e[2] ) ) );
		} elseif ( $edges ) {
			$d = array(); foreach ( $edges as $side => $e ) { $d[] = 'border-' . $side . ':' . $e[0] . ' ' . $e[1] . ' ' . $e[2]; }
			$css[] = '.footer--boxed .footer__body{' . implode( ';', $d ) . ';}';
		}
		$rad = $px( $g( 'border-radius' ) );
		if ( null !== $rad && $rad > 0 ) { $f['footer_box_radius'] = array( 'value' => (string) (int) round( $rad ), 'unit' => 'px' ); }
		// Shadow — the first layer: <color> x y blur spread (computed order) or x y blur spread <color>.
		$sh = $g( 'box-shadow' );
		if ( $sh !== '' && $sh !== 'none' ) {
			$first = trim( explode( '),', $sh . ',' )[0] ); if ( substr_count( $first, '(' ) > substr_count( $first, ')' ) ) { $first .= ')'; }
			$col = ''; if ( preg_match( '/(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', $first, $cm ) ) { $col = $cm[1]; $first = trim( str_replace( $cm[1], '', $first ) ); }
			$nums = preg_split( '/\s+/', trim( str_ireplace( 'inset', '', $first ) ) );
			$n = array(); foreach ( $nums as $v ) { $vv = $px( $v ); if ( null !== $vv ) { $n[] = $vv; } }
			if ( count( $n ) >= 2 ) { $f['footer_box_shadow'] = array( 'x' => (int) round( $n[0] ), 'y' => (int) round( $n[1] ), 'blur' => (int) round( isset( $n[2] ) ? $n[2] : 0 ), 'spread' => (int) round( isset( $n[3] ) ? $n[3] : 0 ), 'color' => $col, 'inset' => stripos( $first, 'inset' ) !== false ); }
		}
		// Decor children → ::before / ::after on the panel.
		$pseudo = array( '::before', '::after' ); $pi = 0;
		foreach ( self::el_children( $shell ) as $k ) {
			if ( $pi >= 2 ) { break; }
			if ( trim( $k->textContent ) !== '' || $k->getElementsByTagName( 'img' )->length || $k->getElementsByTagName( 'svg' )->length || $k->getElementsByTagName( '*' )->length ) { continue; }
			if ( stripos( self::sc_css( $k, 'position' ), 'absolute' ) === false ) { continue; }
			$kbg = self::sc_css( $k, 'background-image' ); $kbc = self::sc_css( $k, 'background-color' );
			$paint = ( $kbg !== '' && $kbg !== 'none' ) || ( $kbc !== '' && stripos( $kbc, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $kbc ) );
			if ( ! $paint ) { continue; }
			$d = array( 'content:""', 'position:absolute', 'pointer-events:none', 'z-index:0' );
			$top = self::sc_css( $k, 'top' ); $bot = self::sc_css( $k, 'bottom' ); $h = self::sc_css( $k, 'height' );
			// Anchor to the bottom when it sits at the panel's bottom edge (a strip along the floor), else the top.
			if ( '0px' === $bot && null !== $px( $h ) ) { $d[] = 'bottom:0'; } elseif ( null !== $px( $top ) ) { $d[] = 'top:' . $top; }
			foreach ( array( 'left', 'right' ) as $pr2 ) { $v = self::sc_css( $k, $pr2 ); if ( null !== $px( $v ) ) { $d[] = $pr2 . ':' . $v; } }
			if ( null !== $px( $h ) ) { $d[] = 'height:' . $h; }
			$w = self::sc_css( $k, 'width' ); if ( null !== $px( $w ) ) { $d[] = 'width:' . $w; }
			foreach ( array( 'background-image', 'background-color', 'background-size', 'background-position', 'background-repeat', 'opacity', 'clip-path', 'border-radius', 'filter', 'mix-blend-mode' ) as $pr2 ) {
				$v = self::sc_css( $k, $pr2 );
				if ( $v === '' || $v === 'none' || $v === 'normal' || ( $pr2 === 'opacity' && $v === '1' ) || ( $pr2 === 'border-radius' && $v === '0px' ) ) { continue; }
				$d[] = $pr2 . ':' . $v;
			}
			$css[] = '.footer--boxed .footer__body' . $pseudo[ $pi++ ] . '{' . implode( ';', $d ) . ';}';
		}
		return array( 'fields' => $f, 'css' => $css );
	}

	/** The vertical alignment of a band's MAIN row (the widest grid / flex row): 'end' | 'center' | '' (top). */
	private static function footer_row_valign( $scope ) {
		$best = self::footer_main_row_el( $scope );
		if ( ! $best ) { return ''; }
		$ai = strtolower( self::sc_css( $best, 'align-items' ) );
		if ( $ai === 'end' || $ai === 'flex-end' || $ai === 'last baseline' ) { return 'end'; }
		if ( $ai === 'center' ) { return 'center'; }
		return '';
	}

	/**
	 * Read a copyright element's OWN computed typography → a `copyright_typography` value (family / size /
	 * weight / colour / line-height / letter-spacing), each field opt-in. Family + colour are only carried
	 * when they read as a real, non-default value. Consumed by unysonplus_hf_typography_css().
	 */
	private static function detect_copyright_typography( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return array(); }
		$out = array();
		$fam = trim( (string) self::sc_css( $el, 'font-family' ) );
		if ( $fam !== '' && preg_match( '/^[a-z0-9"\',\s-]+$/i', $fam ) ) {
			// the WHOLE stack (`ui-monospace, SFMono-Regular, Menlo, monospace`), not its first token — a first-token-only
			// family fell to the browser's serif when that token wasn't installed (unysonplus_hf_typography_css quotes each)
			$out['family'] = str_replace( '"', "'", $fam );
		}
		$tt = strtolower( trim( (string) self::sc_css( $el, 'text-transform' ) ) );
		if ( in_array( $tt, array( 'uppercase', 'lowercase', 'capitalize' ), true ) ) { $out['text-transform'] = $tt; } // an uppercase copyright line
		$fs = trim( (string) self::sc_css( $el, 'font-size' ) );
		if ( preg_match( '/^([0-9.]+)px$/', $fs, $m ) ) { $out['size'] = array( 'value' => (string) round( (float) $m[1] ), 'unit' => 'px' ); }
		$fw = trim( (string) self::sc_css( $el, 'font-weight' ) );
		if ( preg_match( '/^\d{3}$/', $fw ) ) { $out['weight'] = $fw; }
		$col = trim( (string) self::sc_css( $el, 'color' ) );
		if ( $col !== '' && stripos( $col, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $col ) ) {
			$hex = self::color_keep_alpha( $col );
			// The `typography` option stores colour as a plain string (unysonplus_hf_typography_css passes it
			// straight through hf_css_val, which casts to string) — pass the hex (or the rgba() when translucent), not a {predefined,custom} array.
			if ( $hex !== '' ) { $out['color'] = $hex; }
		}
		$ls = trim( (string) self::sc_css( $el, 'letter-spacing' ) );
		if ( preg_match( '/^(-?[0-9.]+)px$/', $ls, $m ) && (float) $m[1] !== 0.0 ) { $out['letter-spacing'] = (float) $m[1]; }
		return $out;
	}

	private static function detect_footer_chrome_styles( $html ) {
		$out = array();
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return $out; }
		$cw = self::detect_chrome_container( $footer );
		if ( $cw !== '' ) { $out['container'] = $cw; }
		$pt = self::sc_pad( $footer, 'top' );    if ( $pt !== '' ) { $out['pad_top'] = $pt; }
		$pb = self::sc_pad( $footer, 'bottom' ); if ( $pb !== '' ) { $out['pad_bottom'] = $pb; }
		if ( self::css_len_present( self::sc_css( $footer, 'border-top-width' ) ) ) {
			$st = self::sc_css( $footer, 'border-top-style' );
			if ( $st !== '' && $st !== 'none' ) {
				$out['border'] = array(
					'width' => self::sc_css( $footer, 'border-top-width' ),
					'style' => $st,
					'color' => self::sc_css( $footer, 'border-top-color' ),
				);
			}
		}
		// Top border-radius (a rounded footer top) — no native footer option ⇒ callers emit scoped CSS.
		$br = self::sc_css( $footer, 'border-radius' );
		if ( $br !== '' && preg_match( '/(?:^|\s)([1-9][0-9.]*(?:px|rem|em))/', $br, $m ) ) { $out['radius'] = trim( $br ); }
		return $out;
	}

	/**
	 * A split-slider ratio value: a list of `{ w:int, name:'' }` segments summing to 100 (the twelfths
	 * split-slider snaps them to the 12-grid). EQUAL by default; when $wide, the first (brand) column gets
	 * 2 units and the rest 1 unit each (e.g. 4 cols → 2/5+1/5+1/5+1/5 ≈ 40/20/20/20). Mirrors the theme's
	 * unysonplus_footer_equal_split() shape so the footer builder resolves it to `fw-col-md-N` correctly.
	 */
	private static function footer_split_segments( $n, $wide = false ) {
		$n = max( 1, (int) $n );
		if ( $wide && $n >= 3 ) {
			$units = 2 + ( $n - 1 );          // brand = 2 units, others = 1 unit each
			$first = (int) round( 2 / $units * 100 );
			$rest  = (int) round( 1 / $units * 100 );
			$segs  = array( array( 'w' => $first, 'name' => '' ) );
			for ( $i = 1; $i < $n; $i++ ) { $segs[] = array( 'w' => $rest, 'name' => '' ); }
			$segs[0]['w'] += 100 - array_sum( wp_list_pluck( $segs, 'w' ) ); // absorb rounding into the brand col
			return $segs;
		}
		$each = (int) floor( 100 / $n );
		$segs = array();
		for ( $i = 0; $i < $n; $i++ ) { $segs[] = array( 'w' => $each, 'name' => '' ); }
		$segs[0]['w'] += 100 - ( $each * $n ); // first column absorbs the remainder → segments sum to 100
		return $segs;
	}

	/**
	 * Is the footer's FIRST (brand) column genuinely wider than the rest (~1.5-2x), so the ratio should
	 * weight it? Conservative — returns false (⇒ equal columns) unless there's a clear signal, so we NEVER
	 * default to a wide first column. Signals: the brand column carries a Tailwind `col-span-{2..}` (it spans
	 * multiple grid tracks), or the footer grid's captured `grid-template-columns` first track is ≥1.4x the
	 * median of the others. the golden fixture is `grid-cols-4` (equal, no span) ⇒ false ⇒ equal split.
	 */
	private static function detect_footer_wide_brand( $html, $count ) {
		if ( (int) $count < 3 ) { return false; }
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return false; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! ( $footer instanceof DOMElement ) ) { return false; }
		// Find the footer's primary column grid: a container whose class names a multi-column grid.
		$grid = null;
		foreach ( $footer->getElementsByTagName( 'div' ) as $d ) {
			$cls = self::cls( $d );
			if ( preg_match( '/\bgrid-cols-[2-9]\b|\bgrid-template-columns\b/', $cls ) || ( strpos( $cls, 'grid' ) !== false && preg_match( '/(?:sm|md|lg|xl):grid-cols-[2-9]/', $cls ) ) ) { $grid = $d; break; }
		}
		if ( ! ( $grid instanceof DOMElement ) ) { return false; }
		// 1) grid-template-columns tracks (from computed style): first ≥ 1.4x the median of the rest.
		$gtc = self::sc_css( $grid, 'grid-template-columns' );
		if ( $gtc !== '' && preg_match_all( '/([0-9.]+)px/', $gtc, $mm ) && count( $mm[1] ) >= 3 ) {
			$tracks = array_map( 'floatval', $mm[1] );
			$first  = $tracks[0];
			$others = array_slice( $tracks, 1 );
			sort( $others );
			$mid = $others[ (int) floor( count( $others ) / 2 ) ];
			if ( $mid > 0 && $first >= 1.4 * $mid ) { return true; }
		}
		// 2) The first column child carries a col-span-{2..} (spans multiple tracks).
		$kids = self::el_children( $grid );
		if ( ! empty( $kids ) ) {
			$fc = self::cls( $kids[0] );
			if ( preg_match( '/(?:^|\s|:)col-span-([2-9])/', $fc ) ) { return true; }
		}
		return false;
	}

	/** The footer brand description (a substantial <p> that is NOT the copyright line), or ''. */
	private static function detect_footer_tagline( $html ) {
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return ''; }
		$footer = $dom->getElementsByTagName( 'footer' )->item( 0 );
		if ( ! $footer ) { return ''; }
		foreach ( $footer->getElementsByTagName( 'p' ) as $p ) {
			$t = trim( preg_replace( '/\s+/', ' ', (string) $p->textContent ) );
			if ( $t !== '' && strlen( $t ) >= 40
				&& strpos( $t, '©' ) === false && stripos( $t, 'rights reserved' ) === false && stripos( $t, 'copyright' ) === false ) {
				return $t;
			}
		}
		return '';
	}

	/**
	 * The theme-design.json payload — the **design-config** the bundle's theme phase feeds to
	 * `FW_Site_Converter_Theme_Generator::install()` to generate a **child theme** (the plan's target).
	 * Maps the Stitch tokens + the screen's chrome to the generator's config shape: fonts, colors,
	 * header (pill/bar, CTA, nav), footer (links), and component CSS (cards) under `custom_css`. The
	 * generator bakes the palette/fonts into the child theme's own style.css, so the converted site
	 * loads ONE clean child stylesheet — no `misc_custom_css` on the active theme.
	 *
	 * @param array  $tokens
	 * @param string $html  the home screen markup (for header/footer detection)
	 * @param string $title page/theme name
	 * @return array design-config
	 */
	public static function tokens_to_design_config( array $tokens, $html, $title ) {
		list( $head_font, $body_font ) = self::pick_fonts_raw( $tokens );
		$google = '';
		foreach ( ( $tokens['fonts'] ?? array() ) as $href ) { $google = $href; break; }
		$gfonts = self::fonts_from_google( $google );
		// GROUND TRUTH: the source's REAL computed faces (h1..h3 → heading, body/p → body) — what actually
		// renders. Prefer these OVER the tailwind fontFamily token and the Google-Fonts URL order, both of
		// which can mislabel heading vs body (e.g. a wordmark/token or an Inter-first URL → heading=Inter over
		// the true display face Playfair Display, which then overrides the correct css-tokens heading var).
		list( $c_head, $c_body, $c_head_stack ) = self::detect_computed_fonts( (string) $html );
		$head_stack = '';
		if ( $c_head !== '' ) { $head_font = $c_head; }
		if ( $c_body !== '' ) { $body_font = $c_body; }
		if ( isset( $c_head_stack ) && $c_head_stack !== '' ) { $head_stack = (string) $c_head_stack; }
		// Fall back to the families named in the Google-Fonts URL only when a computed face is still missing.
		if ( $head_font === '' && isset( $gfonts[0] ) ) { $head_font = $gfonts[0]; }
		// (a measured SYSTEM body stack — `ui-sans-serif, system-ui` — keeps the sans default: the heading's single Google face is
		// never the body's; it landed on every paragraph and in the child theme's --font-body — a fixture from the feed)
		$body_system = (bool) preg_match( '/<body\b[^>]*data-sc-cs="[^"]*font-family:\s*(?:ui-sans-serif|system-ui|-apple-system|blinkmacsystemfont|sans-serif)/i', (string) $html )
			|| (bool) preg_match( '/<p\b[^>]*data-sc-cs="[^"]*font-family:\s*(?:ui-sans-serif|system-ui|-apple-system|blinkmacsystemfont|sans-serif)/i', (string) $html );
		if ( $body_font === '' ) { $body_font = isset( $gfonts[1] ) ? $gfonts[1] : ( ( isset( $gfonts[0] ) && ! $body_system ) ? $gfonts[0] : '' ); }
		// SYNTHESIZE the Google-Fonts css2 URL when the source shipped no googleapis <link> but uses a real
		// named family (self-hosted, e.g. Cormorant Garamond / Inter). This is what functions_php enqueues, so
		// the family in the carried CSS actually loads instead of falling back to a system serif.
		if ( $google === '' && ( $head_font !== '' || $body_font !== '' ) && class_exists( 'FW_Site_Converter_Theme_Generator' ) ) {
			$google = FW_Site_Converter_Theme_Generator::synth_google_fonts_url( array( $head_font, $body_font ) );
		}

		$ink    = self::token_color( $tokens, array( 'text', 'on-background', 'on-surface' ) );
		$bg     = self::token_color( $tokens, array( 'page-bg', 'background', 'surface', 'white-soft' ) );
		// The brand / ACTION color (the button fill, nav-hover, heading accent). Both Stitch and
		// Material-3 put it in `primary`; the `*-container` fills and the `error` red are NOT it.
		$accent = self::brand_accent_color( $html );
		if ( '' === $accent ) { $accent = self::accent_token_color( $tokens ); }
		// No explicit brand color? Look for a vivid one in the markup (Stitch sometimes hides the
		// accent in a gradient like `from-[#FF416C]`); failing that, fall to the design's own dark
		// tone. A MONOCHROME design (e.g. a neutral Material export with black CTAs) is valid — never
		// force a vivid accent onto it the way the old `#FF4B2B` fallback did.
		if ( $accent === '' ) {
			$accent = self::scan_accent( (string) $html );
			if ( $accent === '' ) { $accent = self::token_color( $tokens, array( 'tertiary', 'secondary', 'on-surface', 'on-background' ) ); }
			if ( $accent === '' ) { $accent = $ink !== '' ? $ink : '#141414'; }
		}
		$line   = self::token_color( $tokens, array( 'line', 'outline-variant', 'outline' ) );
		$dark   = self::token_color( $tokens, array( 'deep-black', 'black', 'surface-container-lowest' ) );
		if ( $dark === '' ) { $dark = '#141414'; }
		$ftext  = self::token_color( $tokens, array( 'page-bg', 'on-background', 'white-soft' ) );

		$hdr  = self::detect_header( (string) $html );
		// Theme NAME = the site's BRAND, not the page role. The URL flow passes the generic page title
		// 'Home', which produced a "Home (Child)" theme. When the passed title is empty or the 'Home'
		// default, derive the brand from the source <title> (the segment before a  |  –  —  ·  separator)
		// so the theme is named e.g. "the golden fixture" instead of "Home".
		$passed = trim( (string) $title );
		if ( $passed === '' || 0 === strcasecmp( $passed, 'Home' ) ) {
			$raw   = trim( (string) self::title_from_html( (string) $html, '' ) );
			$brand = $raw !== '' ? trim( (string) preg_split( '/\s*[|\x{2013}\x{2014}\x{00B7}]\s*/u', $raw, 2 )[0] ) : '';
			$name  = $brand !== '' ? $brand : ( $passed !== '' ? $passed : 'Converted Site' );
		} else {
			$name = $passed;
		}

		return array(
			'theme'  => array( 'name' => $name, 'slug' => sanitize_title( $name ), 'mode' => 'child' ),
			// The source site's favicon (best pick — apple-touch-icon > largest icon > .ico > /favicon.ico),
			// as an absolute URL. Bundled into the child theme at build time and used as the Site Icon /
			// <head> link. '' when none could be resolved.
			'favicon' => self::detect_favicon( (string) $html, '' ),
			// The source's design-token :root custom properties (--dark, --brand-*, --background, …) so
			// arbitrary `[hsl(var(--dark))]` + semantic `bg-background` classes resolve in the child theme.
			'css_vars' => self::design_root_vars( $tokens ),
			'fonts'  => array( 'heading' => $head_font, 'heading_stack' => $head_stack, 'body' => $body_font, 'google' => $google ),
			'colors' => array(
				'ink'          => $ink !== '' ? $ink : '#1a1a1a',
				'accent'       => $accent,
				'bg'           => $bg !== '' ? $bg : '#ffffff',
				'header_bg'    => $hdr['dark'] ? $dark : '',
				'header_border'=> $line !== '' ? $line : '#ececec',
				'footer_bg'    => $dark,
				'footer_text'  => $ftext !== '' ? $ftext : '#f5f5f5',
			),
			'header' => array(
				'style'         => $hdr['style'],
				'sticky'        => $hdr['sticky'],
				'menu_location' => 'primary',
				'menu'          => self::design_menu( (string) $html, 'primary' ),
				// The SECONDARY (right-cluster) menu of a split "luxury" header (empty on a single-nav source).
				// The generated theme's bootstrap creates a Secondary WP menu from it so the header_main main_right
				// menu_area (menu_location:secondary) has links to show.
				'menu_secondary' => self::design_menu( (string) $html, 'secondary' ),
				'cta'           => array(
					'enabled' => $hdr['cta']['label'] !== '',
					'label'   => $hdr['cta']['label'] !== '' ? $hdr['cta']['label'] : 'Get started',
					'href'    => $hdr['cta']['href'] !== '' ? $hdr['cta']['href'] : '#',
				),
			),
			'footer' => array(
				'brand'       => true,
				'widget_area' => false,
				'copyright'   => 'All rights reserved.',
				'menu'        => self::design_menu( (string) $html, 'footer' ),
			),
			'background' => array( 'dotted' => false, 'canvas' => $bg !== '' ? $bg : '#ffffff' ),
			'custom_css' => self::tokens_to_component_css( $tokens ),
		);
	}

	/**
	 * Best favicon URL from the source head, resolved absolute.
	 *
	 * Gathers every <link rel="icon" | "apple-touch-icon" | "shortcut icon"> href and PICKS THE BEST:
	 * (a) an apple-touch-icon (usually a clean square PNG), (b) the `icon` with the largest sizes=NxN,
	 * (c) any PNG/webp/jpg/gif/avif icon, (d) a .ico, (e) fall back to <origin>/favicon.ico. When
	 * $origin is empty it's derived from a <link rel=canonical> / og:url / <base href> in the head, so
	 * relative hrefs still resolve. Returns the absolute URL, or '' when nothing resolvable.
	 *
	 * @param string $html
	 * @param string $origin  scheme://host (optional — derived from the html when empty).
	 * @return string
	 */
	public static function detect_favicon( $html, $origin = '' ) {
		$html = (string) $html;

		// Derive an origin (for resolving relative icon hrefs) when one wasn't passed.
		if ( $origin === '' ) {
			$hint = '';
			if ( preg_match( '/<link\b[^>]*\brel\s*=\s*["\']canonical["\'][^>]*\bhref\s*=\s*["\']([^"\']+)["\']/i', $html, $m )
				|| preg_match( '/<meta\b[^>]*\bproperty\s*=\s*["\']og:url["\'][^>]*\bcontent\s*=\s*["\']([^"\']+)["\']/i', $html, $m )
				|| preg_match( '/<base\b[^>]*\bhref\s*=\s*["\']([^"\']+)["\']/i', $html, $m ) ) {
				$hint = $m[1];
			}
			if ( $hint !== '' && preg_match( '#^(https?://[^/]+)#i', $hint, $mm ) ) {
				$origin = $mm[1];
			}
		}

		// Collect every rel=icon/apple-touch-icon/shortcut-icon <link>.
		$cands = array(); // each: { href, apple:bool, size:int, raster:bool, ico:bool }
		if ( preg_match_all( '/<link\b[^>]*>/i', $html, $links ) ) {
			foreach ( $links[0] as $tag ) {
				if ( ! preg_match( '/\brel\s*=\s*["\']([^"\']+)["\']/i', $tag, $rm ) ) { continue; }
				$rel = strtolower( $rm[1] );
				$is_apple = ( strpos( $rel, 'apple-touch-icon' ) !== false );
				$is_icon  = ( strpos( $rel, 'icon' ) !== false ); // covers "icon" and "shortcut icon"
				if ( ! $is_apple && ! $is_icon ) { continue; }
				if ( ! preg_match( '/\bhref\s*=\s*["\']([^"\']+)["\']/i', $tag, $hm ) ) { continue; }
				$href = self::abs_favicon_url( trim( $hm[1] ), $origin );
				if ( $href === '' ) { continue; }
				$size = 0;
				if ( preg_match( '/\bsizes\s*=\s*["\']([^"\']+)["\']/i', $tag, $sm )
					&& preg_match( '/(\d+)\s*[x\xd7]\s*(\d+)/i', $sm[1], $nm ) ) {
					$size = (int) $nm[1];
				}
				$path   = (string) preg_replace( '/[?#].*$/', '', $href );
				$raster = (bool) preg_match( '/\.(png|jpe?g|webp|gif|avif)$/i', $path )
					|| ( ! preg_match( '/\.(ico|svg)$/i', $path ) && $is_apple ); // apple icons are raster even without an ext
				$ico    = (bool) preg_match( '/\.ico$/i', $path );
				$cands[] = array( 'href' => $href, 'apple' => $is_apple, 'size' => $size, 'raster' => $raster, 'ico' => $ico );
			}
		}

		// (a) apple-touch-icon — prefer the largest.
		$apples = array_filter( $cands, function ( $c ) { return $c['apple']; } );
		if ( $apples ) {
			usort( $apples, function ( $a, $b ) { return $b['size'] - $a['size']; } );
			return $apples[0]['href'];
		}
		// (b) an icon with the largest sizes=NxN.
		$sized = array_filter( $cands, function ( $c ) { return $c['size'] > 0; } );
		if ( $sized ) {
			usort( $sized, function ( $a, $b ) { return $b['size'] - $a['size']; } );
			return $sized[0]['href'];
		}
		// (c) any raster (png/webp/jpg/…) icon.
		foreach ( $cands as $c ) { if ( $c['raster'] ) { return $c['href']; } }
		// (d) a .ico icon.
		foreach ( $cands as $c ) { if ( $c['ico'] ) { return $c['href']; } }
		// (e) fall back to <origin>/favicon.ico.
		return $origin !== '' ? $origin . '/favicon.ico' : '';
	}

	/** Resolve a favicon href to an absolute http(s) URL (absolute / protocol-relative / origin-relative). '' if not resolvable. */
	private static function abs_favicon_url( $href, $origin ) {
		$href = trim( (string) $href );
		if ( $href === '' || stripos( $href, 'data:' ) === 0 ) { return ''; }
		if ( preg_match( '#^https?://#i', $href ) ) { return $href; }
		if ( strpos( $href, '//' ) === 0 ) { return 'https:' . $href; }
		if ( $origin === '' ) { return ''; }
		if ( $href[0] === '/' ) { return $origin . $href; }
		return $origin . '/' . ltrim( $href, '/' );
	}

	/** Detect the Stitch header's chrome: pill vs bar, sticky, dark fill, and the CTA button. */
	/**
	 * The header root element: a real <header>, or — for the many modern landing pages (Stitch
	 * outputs included) that use a bare top-level sticky/fixed <nav> as the site bar instead of a
	 * <header> — that <nav>. A <nav> nested inside <main>/<section>/<footer> is in-content, not the
	 * header, so it's skipped. Falls back to the first top-level <nav> when none is explicitly sticky.
	 *
	 * @param DOMDocument $dom
	 * @return DOMElement|null
	 */
	private static function header_root( $dom ) {
		$header = $dom->getElementsByTagName( 'header' )->item( 0 );
		$body   = $dom->getElementsByTagName( 'body' )->item( 0 );
		// A full-viewport <header> that holds the H1 + CTA (AI-page-style: `<header class="min-h-screen">`,
		// with the real nav in a SEPARATE <nav>) is a HERO band, not the masthead — don't let it become
		// chrome. When the first <header> is a hero, prefer a distinct top-level sticky/fixed <nav>. Mirrors
		// the capture service's isHeroHeader() split.
		$header_is_hero = self::is_hero_header( $header );
		// …or a <header> that is a CONTENT band by shape: inside the page's <main>, holding a heading but no link / nav at all (a
		// grid canvas's hero copy: h1 + p + a button) — a masthead always carries links. The fixed <nav> beside it is the masthead.
		if ( $header && ! $header_is_hero && $body && self::has_ancestor_tag( $header, 'main', $body ) && 0 === $header->getElementsByTagName( 'a' )->length && 0 === $header->getElementsByTagName( 'nav' )->length && ( $header->getElementsByTagName( 'h1' )->length || $header->getElementsByTagName( 'h2' )->length ) ) { $header_is_hero = true; }
		if ( $header && ! $header_is_hero ) { return $header; }
		if ( ! $body ) { return $header; }
		$first = null;
		foreach ( $body->getElementsByTagName( 'nav' ) as $nav ) {
			if ( self::has_ancestor_tag( $nav, 'main', $body )
				|| self::has_ancestor_tag( $nav, 'section', $body )
				|| self::has_ancestor_tag( $nav, 'footer', $body ) ) {
				continue;
			}
			if ( $header_is_hero && self::node_within( $nav, $header ) ) { continue; } // a nav INSIDE the hero isn't the masthead
			$c = self::cls( $nav );
			if ( strpos( $c, 'fixed' ) !== false || strpos( $c, 'sticky' ) !== false || strpos( $c, 'top-0' ) !== false ) {
				return $nav;
			}
			if ( $first === null ) { $first = $nav; }
		}
		if ( $first !== null ) { return $first; }
		// SECOND PASS — React/Next landing pages routinely wrap the WHOLE app (masthead included) in
		// <main>/<section>, so the top-level-nav pass above finds nothing: the real site nav then gets
		// dropped into the page BODY and the header keeps a PRIOR conversion's menu (the jiro/Payway leak).
		// Claim the FIRST masthead-SHAPED <nav> even when it's inside <main>/<section> — as long as it is NOT
		// inside a <footer> (a footer nav is legit in-content) and NOT inside the hero, and it reads as a
		// header row (horizontal flex justify-between / items-center, or ≥3 links). (P1 audit fix.)
		foreach ( $body->getElementsByTagName( 'nav' ) as $nav ) {
			if ( self::has_ancestor_tag( $nav, 'footer', $body ) ) { continue; }
			if ( $header_is_hero && self::node_within( $nav, $header ) ) { continue; }
			$c = ' ' . self::cls( $nav ) . ' ';
			$looks_masthead = ( strpos( $c, ' flex ' ) !== false && ( strpos( $c, 'justify-between' ) !== false || strpos( $c, 'items-center' ) !== false ) )
				|| $nav->getElementsByTagName( 'a' )->length >= 3;
			if ( $looks_masthead ) { return $nav; }
		}
		// No separate nav found. If the only <header> is a HERO (tall + a big heading), it is BODY content, not
		// the masthead — return null (no masthead → the theme's default header) so the hero flows into the body
		// sections and its headline renders (getty-images: a `min-h-screen` hero <header> with no separate nav
		// was being kept as chrome, so the page's first section had no hero). A non-hero header stays the masthead.
		return $header_is_hero ? null : $header;
	}

	/**
	 * Is this <header> actually a full-viewport HERO (not the site masthead)? A hero is tall
	 * (min-h-screen / h-screen / min-h-[NNvh], or a data-sc-cs min-height ≥ 60vh) AND leads with a big
	 * heading. A masthead is short and nav-like. Class-based (this path has no layout engine), with a
	 * computed-style fallback when the capture annotated data-sc-cs. Mirrors the JS isHeroHeader().
	 *
	 * @param DOMElement|null $el
	 * @return bool
	 */
	private static function is_hero_header( $el ) {
		if ( ! $el ) { return false; }
		// a STICKY / FIXED header, or one holding a <nav> of links, is the masthead whatever its height context: a sticky
		// `<header>` with a serif h1 wordmark under a `min-h-screen` app wrapper was read as a hero and became page section 1,
		// its nav duplicated (a fixture from the feed)
		$pcs0 = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*position:\s*(?:sticky|fixed)/i', $pcs0 ) || preg_match( '/(?:^|\s)(?:sticky|fixed)(?:\s|$)/', ' ' . self::cls( $el ) . ' ' ) ) { return false; }
		foreach ( $el->getElementsByTagName( 'nav' ) as $nv0 ) { if ( $nv0->getElementsByTagName( 'a' )->length >= 3 ) { return false; } }
		// a <header> INSIDE <main> is never the masthead: it is the page's intro band whatever its height (a 512px `max-w-5xl`
		// hero of label + h1 + copy + button was dropped for not being viewport-tall — a real-site audit)
		for ( $a0 = $el->parentNode; $a0 instanceof DOMElement; $a0 = $a0->parentNode ) { if ( 'main' === strtolower( $a0->tagName ) ) { return $el->getElementsByTagName( 'h1' )->length > 0 || $el->getElementsByTagName( 'h2' )->length > 0; } }
		$c    = ' ' . self::cls( $el ) . ' ';
		$tall = ( strpos( $c, ' min-h-screen ' ) !== false ) || ( strpos( $c, ' h-screen ' ) !== false )
			|| preg_match( '/\b(?:min-)?h-\[\s*(?:[6-9]\d|1\d\d)(?:vh|dvh|svh)/', $c );
		if ( ! $tall ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( $cs !== '' && preg_match( '/min-height:\s*([\d.]+)(px|vh|dvh|svh)/', $cs, $m ) ) {
				$v    = (float) $m[1];
				$tall = ( 'px' === $m[2] ) ? ( $v >= 480 ) : ( $v >= 60 ); // ~60% of an 800px viewport, or 60vh
			}
		}
		if ( ! $tall ) {
			// The full-viewport height often sits on a nearby ANCESTOR, not the element itself — getty-images'
			// hero `<header class="">` is nested inside `<div class="… min-h-screen">`, so the header's own
			// class/cs read short and it was mistaken for the masthead, swallowing the hero headline. Treat the
			// element as a hero when a near ancestor (up to 3 levels) establishes a full-viewport box. Guarded by
			// the h1/h2 requirement below, so a normal masthead inside a tall page wrapper isn't misread.
			$vpx = '/\b(?:min-)?h-\[\s*(?:[6-9]\d|1\d\d)(?:vh|dvh|svh)/';
			for ( $a = $el->parentNode, $up = 0; ( $a instanceof DOMElement ) && $up < 3; $a = $a->parentNode, $up++ ) {
				$ac = ' ' . self::cls( $a ) . ' ';
				if ( strpos( $ac, ' min-h-screen ' ) !== false || strpos( $ac, ' h-screen ' ) !== false || preg_match( $vpx, $ac ) ) { $tall = true; break; }
			}
		}
		if ( ! $tall ) { return false; }
		return $el->getElementsByTagName( 'h1' )->length > 0 || $el->getElementsByTagName( 'h2' )->length > 0;
	}

	/** True when $node is a descendant of $ancestor (node-path prefix — robust against PHP DOM wrapper identity). */
	private static function node_within( $node, $ancestor ) {
		if ( ! $node || ! $ancestor ) { return false; }
		$ap = $ancestor->getNodePath();
		return $ap !== '' && strpos( (string) $node->getNodePath(), $ap . '/' ) === 0;
	}

	private static function detect_header( $html ) {
		$out = array( 'style' => 'bar', 'sticky' => false, 'dark' => false, 'cta' => array( 'label' => '', 'href' => '', 'style' => '' ) );
		$dom = self::load_dom( $html );
		if ( ! $dom ) { return $out; }
		$header = self::header_root( $dom );
		if ( ! $header ) { return $out; }
		$hcls = self::cls( $header );
		if ( strpos( $hcls, 'sticky' ) !== false || strpos( $hcls, 'fixed' ) !== false ) { $out['sticky'] = true; }
		// Class-less fixed/sticky header (position set via a STYLESHEET rule, not a Tailwind class — e.g. kage's
		// `<header id="nav" class="nav">` + `.nav{position:fixed}`). The capture's data-sc-cs omits `position`,
		// so read the source sheet for the header's own tag / #id / .class rule.
		if ( ! $out['sticky'] ) {
			$inline = strtolower( (string) $header->getAttribute( 'style' ) );
			if ( preg_match( '/position\s*:\s*(?:fixed|sticky)/', $inline ) ) {
				$out['sticky'] = true;
			} else {
				$sels = array( preg_quote( strtolower( $header->tagName ), '/' ) );
				$hid  = trim( (string) $header->getAttribute( 'id' ) );
				if ( '' !== $hid ) { $sels[] = '#' . preg_quote( $hid, '/' ); }
				foreach ( preg_split( '/\s+/', $hcls ) as $c ) { $c = trim( $c ); if ( '' !== $c ) { $sels[] = '\.' . preg_quote( $c, '/' ); } }
				$re = '/(?:' . implode( '|', $sels ) . ')(?![\w-])[^{}]*\{[^}]*position\s*:\s*(?:fixed|sticky)/i';
				if ( preg_match( $re, self::all_style_css( $html ) ) ) { $out['sticky'] = true; }
			}
		}
		// A pill nav: a container with rounded-full. Dark fill if it carries a near-black bg.
		foreach ( $header->getElementsByTagName( 'div' ) as $d ) {
			$c = self::cls( $d );
			if ( strpos( $c, 'rounded-full' ) !== false ) {
				$out['style'] = 'pill';
				if ( preg_match( '/bg-(?:black|zinc-9|neutral-9|gray-9|slate-9|stone-9|\[#0|\[#1[0-9a-f]{2}\b)/', $c ) || strpos( $c, 'bg-deep' ) !== false || strpos( $c, 'bg-[#000' ) !== false ) {
					$out['dark'] = true;
				}
				break;
			}
		}
		// CTA = the header's button (or a button-styled link). Capture its FILL class too so the converted
		// CTA references the MATCHING button preset (a `bg-secondary` amber header button → btn-secondary, not
		// the hardcoded btn-primary), mirroring build_button_presets()' role → slug assignment.
		$cta_node = null;
		// A header phone link (tel:) is the primary action in many headers — PREFER it as the CTA so the phone
		// number is carried through, and a nav dropdown trigger (e.g. "Practice Areas") isn't mistaken for it.
		foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
			if ( stripos( trim( (string) $a->getAttribute( 'href' ) ), 'tel:' ) === 0 ) {
				$lbl = self::text_no_icons( $a );
				if ( $lbl !== '' ) { $out['cta']['label'] = $lbl; $out['cta']['href'] = trim( (string) $a->getAttribute( 'href' ) ); $cta_node = $a; break; }
			}
		}
		if ( $cta_node === null ) {
			// A real CTA sits OUTSIDE the nav. A <button> INSIDE the nav is a dropdown trigger ("More") and
			// the mobile menu toggle has no text - skip both so the actual button-styled CTA ("Get Started")
			// wins instead of the dropdown label.
			$in_nav = function ( $el ) {
				for ( $p = $el->parentNode; $p instanceof DOMElement; $p = $p->parentNode ) { if ( strtolower( $p->tagName ) === 'nav' ) { return true; } }
				return false;
			};
			foreach ( $header->getElementsByTagName( 'button' ) as $b ) {
				if ( $in_nav( $b ) ) { continue; }
				$lbl = trim( (string) self::text_no_icons( $b ) );
				// an ICON CONTROL whose only text is a count badge ("0" on a bag icon) or a bare glyph is never the CTA (three sites in the feed)
				if ( preg_match( '/^\d{1,2}$/', $lbl ) || ! preg_match( '/\p{L}/u', $lbl ) ) { continue; }
				if ( preg_match( '/(?:^|\s)(?:cart|bag|basket|account|user-menu|wishlist|search)(?:\s|$|-)/', ' ' . strtolower( self::cls( $b ) ) . ' ' ) ) { continue; }
				if ( $lbl !== '' ) { $out['cta']['label'] = $lbl; $cta_node = $b; break; }
			}
			if ( $out['cta']['label'] === '' ) {
				foreach ( $header->getElementsByTagName( 'a' ) as $a ) {
					// A button-STYLED link (fill/border + padding + rounded) is a real CTA even when it sits INSIDE
					// the <nav> — many headers place the "Book a Stay" pill alongside the menu links. Plain nav
					// links aren't button-styled, so is_button() already excludes them; only skip an in-nav link
					// that ISN'T a styled button (a dropdown-trigger anchor), not the CTA itself.
					if ( ! self::is_button( $a ) ) { continue; }
					if ( $in_nav( $a ) && trim( (string) $a->getAttribute( 'href' ) ) === '' ) { continue; }
					if ( $in_nav( $a ) && self::nav_pill_sibling( $a ) ) { continue; } // a pill among pills is a menu item (see nav_pill_sibling)
					$out['cta']['label'] = trim( (string) self::text_no_icons( $a ) ); $out['cta']['href'] = $a->getAttribute( 'href' ); $cta_node = $a; break;
				}
			}
		}
		// DECORATIVE header widgets (a progress/meter bar, a rule, a pip) reconstructed from the
		// capture's `data-sc-decor` stamp. They carry no text and no link, so every text-driven
		// extractor ignores them — and their geometry is NOT in data-sc-cs (no width/height, and the
		// fill child is not stamped at all), which is why the stamp exists. Emitted as self-contained
		// `custom_html` with inline styles, so nothing depends on the source stylesheet.
		$decor = array();
		foreach ( $header->getElementsByTagName( 'div' ) as $d ) {
			if ( count( $decor ) >= 2 ) { break; }
			$raw = ( $d instanceof DOMElement ) ? (string) $d->getAttribute( 'data-sc-decor' ) : '';
			if ( '' === $raw ) { continue; }
			$kv = array();
			foreach ( explode( ';', $raw ) as $pair ) {
				$cp = strpos( $pair, ':' );
				if ( false !== $cp ) { $kv[ trim( substr( $pair, 0, $cp ) ) ] = trim( substr( $pair, $cp + 1 ) ); }
			}
			if ( empty( $kv['w'] ) || empty( $kv['h'] ) ) { continue; }
			// Only BAR-shaped decor belongs in the action cluster. A square-ish box is the brand
			// mark's icon tile (38x38 here), which is part of the LOGO and is mapped there — emitting
			// it again as custom_html would duplicate it into the right-hand slot.
			$dw = (float) $kv['w']; $dh = (float) $kv['h'];
			if ( $dh <= 0 || $dw < $dh * 3 ) { continue; }
			$style = 'width:' . $kv['w'] . ';height:' . $kv['h'] . ';';
			if ( ! empty( $kv['bg'] ) )     { $style .= 'background-color:' . $kv['bg'] . ';'; }
			if ( ! empty( $kv['radius'] ) ) { $style .= 'border-radius:' . $kv['radius'] . ';'; }
			$style .= 'overflow:hidden;flex:none;';
			$inner = '';
			if ( ! empty( $kv['fill-w'] ) ) {
				$fs = 'display:block;height:100%;width:' . $kv['fill-w'] . ';';
				if ( ! empty( $kv['fill-img'] ) )     { $fs .= 'background-image:' . $kv['fill-img'] . ';'; }
				elseif ( ! empty( $kv['fill-bg'] ) )  { $fs .= 'background-color:' . $kv['fill-bg'] . ';'; }
				$inner = '<span style="' . esc_attr( $fs ) . '"></span>';
			}
			$decor[] = '<div class="sc-header-decor" style="' . esc_attr( $style ) . '">' . $inner . '</div>';
		}
		if ( $decor ) { $out['cta']['decor'] = $decor; }
		if ( $cta_node instanceof DOMElement ) {
			$cc = ' ' . strtolower( self::cls( $cta_node ) ) . ' ';
			if ( preg_match( '/\sbg-(primary|brand)\b/', $cc ) )   { $out['cta']['style'] = 'btn-primary'; }
			elseif ( preg_match( '/\sbg-(secondary|accent|cta)\b/', $cc ) ) { $out['cta']['style'] = 'btn-secondary'; }
			elseif ( ( strpos( $cc, ' border' ) !== false ) && ( strpos( $cc, ' bg-white' ) !== false || ! preg_match( '/\sbg-(?!transparent)/', $cc ) ) ) { $out['cta']['style'] = 'btn-outline'; }
		}
		// EVERY masthead action in DOM order — a header often carries TWO CTAs and the single-CTA read above
		// kept only one. Each carries its classes + computed style so the emit resolves it to the matching
		// button preset (style + size) the way body buttons are.
		$out['ctas'] = self::header_actions( $header );
		$out['textLinks'] = self::header_text_links( $header ); // "Sign in" beside the CTA → list_items before it
		// TWO-ROW masthead (a brand row stacked over / under a links-only nav row) → native Bottom / Top Bar.
		$rows = self::header_rows( $header );
		if ( $rows ) { $out['rows'] = $rows; }
		// Decorative TEXT CHIPS beside the brand (a pill label with a glowing dot) → native list_item elements.
		$out['chips'] = self::header_chips( $header, (string) $html );
		// MENU PLACEMENT — which header ZONE the primary menu sits in, so the converted menu lands in the same
		// column the source used (main_left / main_center / main_right), not a hardcoded centre. The theme's
		// 3-zone header is logo · menu · CTA. This must work even when the source has NO <nav> element — modern
		// React/Tailwind headers render the desktop menu as a bare `<div class="hidden md:flex gap-8">` of links
		// — so we locate the real MENU GROUP structurally (find_menu_group), then read its index among the
		// masthead ROW's desktop zones + explicit centering signals (mx-auto / justify-center / absolute-centre).
		$out['menu_pos'] = 'center';
		$menu_group = self::find_menu_group( $header );
		if ( $menu_group instanceof DOMElement ) {
			$mc  = ' ' . strtolower( self::cls( $menu_group ) ) . ' ';
			$mcs = (string) $menu_group->getAttribute( 'data-sc-cs' );
			// STRONG signal: the menu (or its own wrapper) is explicitly centred → centre regardless of index.
			$explicit_center = strpos( $mc, ' mx-auto ' ) !== false
				|| ( strpos( $mc, ' absolute ' ) !== false && ( strpos( $mc, ' left-1/2 ' ) !== false || strpos( $mc, ' inset-x-0 ' ) !== false ) );
			if ( $explicit_center ) {
				$out['menu_pos'] = 'center';
			} elseif ( $menu_group->parentNode instanceof DOMElement ) {
				// Position by the menu's index among the masthead ROW's DESKTOP-visible major zones.
				$row   = $menu_group->parentNode;
				$major = array();
				foreach ( self::el_children( $row ) as $k ) {
					$kc = ' ' . strtolower( self::cls( $k ) ) . ' ';
					// Skip zones hidden on desktop (mobile hamburger / mobile-only actions). `hidden md:flex`
					// is DESKTOP-visible (only the bare-breakpoint `md:hidden` etc. are desktop-hidden).
					if ( strpos( $kc, ' md:hidden ' ) !== false || strpos( $kc, ' lg:hidden ' ) !== false || strpos( $kc, ' sm:hidden ' ) !== false ) { continue; }
					$major[] = $k;
				}
				$idx = array_search( $menu_group, $major, true );
				$n   = count( $major );
				if ( $idx !== false && $n >= 2 ) {
					if ( $idx === $n - 1 ) { $out['menu_pos'] = 'right'; }   // menu is the LAST zone (logo-left, menu+CTA-right) → right
					elseif ( $idx === 0 ) { $out['menu_pos'] = 'left'; }     // menu FIRST (before the logo) → left
					else { $out['menu_pos'] = 'center'; }                    // menu BETWEEN logo and actions → centre
				}
			}
		}
		return $out;
	}

	/**
	 * The desktop primary MENU group inside a header: the INNERMOST `<nav>` / `<ul>` / flex-`<div>` that holds
	 * ≥2 short nav-link `<a>`s, excluding the whole masthead bar (which also carries the logo image and/or the
	 * CTA button). Modern React/Tailwind headers use a bare `<div class="hidden md:flex gap-8">` (no `<nav>`),
	 * so tag alone is unreliable — we score by "a tight cluster of short links, not the bar". Returns the
	 * element, or null when no link cluster is found (a logo-only / hamburger-only header).
	 */
	/** A <button> that is a nav DROPDOWN TRIGGER (aria-haspopup / aria-expanded / aria-controls, or a short unfilled
	 *  label with a chevron) rather than a CTA or the mobile toggle. */
	private static function is_menu_trigger_button( $bt ) {
		if ( ! ( $bt instanceof DOMElement ) ) { return false; }
		$t = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $bt ) ) );
		if ( '' === $t || mb_strlen( $t ) > 24 ) { return false; }
		if ( $bt->hasAttribute( 'aria-haspopup' ) || $bt->hasAttribute( 'aria-expanded' ) || $bt->hasAttribute( 'aria-controls' ) ) { return true; }
		$bg = strtolower( trim( self::sc_css( $bt, 'background-color' ) ) );
		$unfilled = ( '' === $bg || 'transparent' === $bg || preg_match( '/^rgba\([^)]*,\s*0\s*\)$/', $bg ) );
		return $unfilled && ( $bt->getElementsByTagName( 'svg' )->length > 0 || false !== stripos( self::cls( $bt ), 'chevron' ) );
	}

	private static function find_menu_group( $header ) {
		$consider = array();
		foreach ( array( 'nav', 'ul' ) as $tg ) {
			foreach ( $header->getElementsByTagName( $tg ) as $n ) { $consider[] = $n; }
		}
		foreach ( $header->getElementsByTagName( 'div' ) as $n ) {
			$c  = ' ' . strtolower( self::cls( $n ) ) . ' ';
			$cs = (string) $n->getAttribute( 'data-sc-cs' );
			if ( strpos( $c, ' flex ' ) !== false || strpos( $c, 'inline-flex' ) !== false
				|| strpos( $cs, 'display:flex' ) !== false || strpos( $cs, 'display:inline-flex' ) !== false ) { $consider[] = $n; }
		}
		// Qualify: a container with ≥2 short, non-CTA nav links and NO logo image / CTA <button> (those mark
		// the whole bar, not the menu). A CTA styled as a link or a tel: link is not counted as a nav item.
		$qual = array();
		foreach ( $consider as $cand ) {
			if ( $cand->getElementsByTagName( 'img' )->length > 0 ) { continue; }
			// a <button> marks the whole bar (a CTA, the mobile toggle) — but a DROPDOWN TRIGGER ("More ▾": aria-haspopup /
			// aria-expanded, a short label, no fill) is one of the nav's own items; disqualifying its <nav> lost the row's
			// `gap:32px` and the links rendered 4px apart (a real-site audit)
			$cta_btn = false;
			foreach ( $cand->getElementsByTagName( 'button' ) as $bt ) { if ( ! self::is_menu_trigger_button( $bt ) ) { $cta_btn = true; break; } }
			if ( $cta_btn ) { continue; }
			$links = 0;
			foreach ( $cand->getElementsByTagName( 'a' ) as $a ) {
				if ( self::is_button( $a ) || stripos( (string) $a->getAttribute( 'href' ), 'tel:' ) === 0 ) { continue; }
				$t = trim( self::text_no_icons( $a ) );
				if ( $t !== '' && mb_strlen( $t ) <= 24 ) { $links++; }
			}
			if ( $links >= 2 ) { $qual[] = array( 'el' => $cand, 'links' => $links ); }
		}
		if ( empty( $qual ) ) { return null; }
		// Keep only the INNERMOST qualifiers (drop any that contain another qualifier) so the tight link
		// cluster wins over an outer wrapper that also happens to hold ≥2 links.
		$contains = function ( $a, $b ) { $p = $b->parentNode; while ( $p instanceof DOMNode ) { if ( $p === $a ) { return true; } $p = $p->parentNode; } return false; };
		$inner = array();
		foreach ( $qual as $q ) {
			$is_ancestor = false;
			foreach ( $qual as $q2 ) { if ( $q2['el'] !== $q['el'] && $contains( $q['el'], $q2['el'] ) ) { $is_ancestor = true; break; } }
			if ( ! $is_ancestor ) { $inner[] = $q; }
		}
		// Most links wins among the innermost clusters (the primary menu over a small utility link group).
		usort( $inner, function ( $a, $b ) { return $b['links'] - $a['links']; } );
		return isset( $inner[0] ) ? $inner[0]['el'] : null;
	}

	/**
	 * EVERY action in the masthead, in DOM order. A masthead often carries TWO CTAs side by side and the
	 * single-CTA reader (detect_header → cta) kept only the first, silently dropping the other. An action is
	 * a <button> outside the nav with a text label (the mobile toggle has none; a dropdown trigger sits in
	 * the nav or carries aria-controls), a button-STYLED <a> (by class or by computed style), or a tel: link.
	 * Each carries its source classes + computed style (data-sc-cs) so the emit resolves it through the
	 * SHARED resolver (FW_Site_Converter_Mapper::button_preset_for) to the preset that matches its own skin.
	 *
	 * @return array[] [ { label, href, cls, cs, hov } … ] (≤ 4)
	 */
	/** A skinned link whose SIBLING links are skinned alike (a rounded-anchor PILL nav): a menu item, not the standout CTA. */
	private static function nav_pill_sibling( $el ) {
		if ( ! ( $el instanceof DOMElement ) || ! ( $el->parentNode instanceof DOMElement ) ) { return false; }
		$skin = function ( $x ) { return strtolower( trim( (string) self::sc_css( $x, 'background-color' ) ) ) . '|' . strtolower( trim( (string) self::sc_css( $x, 'border-top-color' ) ) ); };
		$own = $skin( $el ); $sib_btn = 0; $sib_n = 0; $alike = 0;
		foreach ( $el->parentNode->childNodes as $sb ) {
			if ( ! ( $sb instanceof DOMElement ) || $sb === $el ) { continue; }
			$sa = ( 'a' === strtolower( $sb->tagName ) ) ? $sb : $sb->getElementsByTagName( 'a' )->item( 0 );
			if ( ! ( $sa instanceof DOMElement ) || '' === trim( self::text_no_icons( $sa ) ) ) { continue; }
			$sib_n++;
			if ( self::is_button( $sa ) || self::cs_is_button( $sa ) ) { $sib_btn++; if ( $skin( $sa ) === $own ) { $alike++; } }
		}
		// ≥ 2 skinned siblings AND at least one wears the SAME skin: a pill among pills. A link skinned unlike every
		// sibling (the filled "Get started" beside the translucent items) is the standout — the CTA.
		return ( $sib_n >= 2 && $sib_btn >= 2 && $alike >= 1 );
	}

	/** An icon's wrapper IS a tile when its MEASURED style paints it (a fill, a border or a shadow) at a tile size (≤ 120px):
	 *  a `.icon-tile` styled by a sheet is the same tile a `bg-primary/10 rounded-full w-14 h-14` is (a RECURRING finding:
	 *  tinted circle tiles were dropped whenever the fill came from a class the utility scan could not see). */
	private static function el_is_icon_tile( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( '' === $cs ) { return false; }
		$w = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $cs, $wm ) ? (float) $wm[1] : 0.0;
		$h = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $hm ) ? (float) $hm[1] : 0.0;
		if ( $w <= 0 || $h <= 0 || $w > 120 || $h > 120 ) { return false; }
		$fill = preg_match( '/(?:^|;)\s*background-color:\s*([^;]+)/i', $cs, $bm ) && ! preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent|\/\s*0\s*\)/i', $bm[1] );
		$grad = (bool) preg_match( '/(?:^|;)\s*background-image:\s*(?:linear|radial|conic)-gradient/i', $cs );
		$bord = preg_match( '/(?:^|;)\s*border-top-width:\s*([0-9.]+)px/i', $cs, $bw ) && (float) $bw[1] > 0 && preg_match( '/(?:^|;)\s*border-top-style:\s*(?!none)/i', $cs ) && ! preg_match( '/(?:^|;)\s*border-top-color:\s*(?:rgba\([^)]*,\s*0\s*\)|transparent)/i', $cs );
		$shad = preg_match( '/(?:^|;)\s*box-shadow:\s*([^;]+)/i', $cs, $sm ) && 'none' !== strtolower( trim( $sm[1] ) );
		return $fill || $grad || $bord || $shad;
	}

	private static function header_actions( $header ) {
		$out = array();
		if ( ! ( $header instanceof DOMElement ) || ! $header->ownerDocument ) { return $out; }
		$in_nav = function ( $el ) use ( $header ) {
			for ( $p = $el->parentNode; $p instanceof DOMElement && $p !== $header; $p = $p->parentNode ) { if ( strtolower( $p->tagName ) === 'nav' ) { return true; } } // a nested <nav> only — a masthead that IS the <nav> holds its CTA button directly
			return false;
		};
		$xp = new DOMXPath( $header->ownerDocument );
		foreach ( $xp->query( './/a | .//button', $header ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			if ( self::nav_el_hidden( $el ) ) { continue; }
			$tag  = strtolower( $el->tagName );
			$href = trim( (string) $el->getAttribute( 'href' ) );
			$lbl  = trim( (string) self::text_no_icons( $el ) );
			if ( '' === $lbl || mb_strlen( $lbl ) > 40 ) { continue; }
			// an ICON CONTROL whose only text is a 1–2 char COUNT badge (a bag / cart icon with an absolute "0") is never a CTA —
			// it became a 'Get Started'-styled button labelled "0" (three sites in the feed); a bare glyph label is none either
			if ( preg_match( '/^\d{1,2}$/', $lbl ) || ! preg_match( '/\p{L}/u', $lbl ) ) { continue; }
			$lc = ' ' . strtolower( self::cls( $el ) ) . ' ';
			if ( preg_match( '/\b(toggle|toggler|hamburger|menu-?icon|navbar-toggler|search|cart|bag|basket|account|user-menu|wishlist)\b/', $lc ) ) { continue; }
			$is_tel = ( stripos( $href, 'tel:' ) === 0 );
			if ( 'button' === $tag ) {
				if ( $in_nav( $el ) ) { continue; }
				// The masthead IS the <nav>: a button directly in it counts only when it is a real skinned CTA (fill / border / pill), never a bare control.
				if ( 'nav' === strtolower( $header->tagName ) && ! self::is_button( $el ) && ! self::cs_is_button( $el ) ) { continue; }
				if ( '' !== $el->getAttribute( 'aria-controls' ) || '' !== $el->getAttribute( 'aria-haspopup' ) ) { continue; }
			} elseif ( ! $is_tel ) {
				if ( ! self::is_button( $el ) && ! self::cs_is_button( $el ) ) { continue; }
				if ( $in_nav( $el ) && '' === $href ) { continue; }
				// A CTA is the STANDOUT among the nav's links. When the menu's own items are pills too (a rounded-anchor
				// pill nav: every link skinned alike), a skinned anchor is a menu item — it was emitted as a menu item AND
				// a CTA button, three times over (a RECURRING finding). Only a link skinned unlike its siblings stands out.
				if ( $in_nav( $el ) && self::nav_pill_sibling( $el ) ) { continue; }
			}
			$out[] = array(
				'label' => $lbl,
				'href'  => $href,
				'cls'   => trim( self::cls( $el ) ),
				'cs'    => (string) $el->getAttribute( 'data-sc-cs' ),
				'hov'   => (string) $el->getAttribute( 'data-sc-hover' ),
			);
			if ( count( $out ) >= 4 ) { break; }
		}
		return $out;
	}

	/**
	 * SECONDARY TEXT LINKS in the masthead's ACTION CLUSTER — a plain `<a>` ("Sign in", "Log in", "Contact") that sits in the same
	 * parent as a button-styled CTA, is not itself a button, not in the menu's links row, not the brand. These were DROPPED
	 * (the menu takes the links row, header_actions takes only buttons). → native `list_item` elements before the CTA in the
	 * right zone, with the link's own colour / size / weight + hover. JS twin: capture-extract header.textLinks.
	 */
	private static function header_text_links( $header ) {
		$out = array();
		if ( ! ( $header instanceof DOMElement ) || ! $header->ownerDocument ) { return $out; }
		$xp = new DOMXPath( $header->ownerDocument );
		$is_btn = function ( $el ) { return ( 'button' === strtolower( $el->tagName ) ) || self::is_button( $el ) || self::cs_is_button( $el ); };
		$in_brand = function ( $el ) use ( $header ) {
			for ( $q = $el; $q instanceof DOMElement && $q !== $header; $q = $q->parentNode ) {
				if ( '' !== $q->getAttribute( 'data-sc-logo-svg' ) || $q->getElementsByTagName( 'img' )->length > 0 ) { return true; }
				if ( preg_match( '/(^|\s|-|_)(brand|logo)(\s|-|_|$)/', strtolower( self::cls( $q ) ) ) ) { return true; }
			}
			return false;
		};
		foreach ( $xp->query( './/a', $header ) as $a ) {
			if ( ! ( $a instanceof DOMElement ) || self::nav_el_hidden( $a ) ) { continue; }
			$lbl = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $a ) ) );
			$href = trim( (string) $a->getAttribute( 'href' ) );
			if ( '' === $lbl || mb_strlen( $lbl ) > 24 || '' === $href ) { continue; }
			if ( $is_btn( $a ) || $in_brand( $a ) || $a->getElementsByTagName( 'svg' )->length > 0 ) { continue; }
			// a HOME link (`/`, `#`, the origin) is the brand — the logo already carries it (it doubled as a list item beside the logo)
			if ( '/' === $href || preg_match( '~^https?://[^/]+/?$~', $href )  ) { continue; }
			// The action cluster: a sibling button-styled CTA in the SAME parent.
			$parent = $a->parentNode; if ( ! ( $parent instanceof DOMElement ) ) { continue; }
			// …and the anchor that LEADS the row ahead of the nav cluster (a sibling holding ≥ 3 links) is the brand, whatever its href
			$lead_brand = false; $seen_self = false;
			foreach ( self::el_children( $parent ) as $k ) { if ( $k === $a ) { $seen_self = true; continue; } if ( $seen_self && $k->getElementsByTagName( 'a' )->length >= 3 && '' !== trim( self::text_no_icons( $k ) ) ) { $lead_brand = true; break; } }
			if ( $lead_brand && self::el_children( $parent )[0] === $a ) { continue; }
			$has_cta = false; $links_here = 0;
			foreach ( self::el_children( $parent ) as $k ) {
				if ( in_array( strtolower( $k->tagName ), array( 'a', 'button' ), true ) && '' !== trim( self::text_no_icons( $k ) ) ) { if ( $is_btn( $k ) ) { $has_cta = true; } else { $links_here++; } }
			}
			if ( ! $has_cta || $links_here > 2 ) { continue; } // 3+ plain links beside a button = a nav row, not an action cluster
			$out[] = array( 'label' => $lbl, 'href' => $href, 'cs' => (string) $a->getAttribute( 'data-sc-cs' ), 'hov' => (string) $a->getAttribute( 'data-sc-hover' ) );
			if ( count( $out ) >= 2 ) { break; }
		}
		return $out;
	}

	/** A header ROW that is not shown on desktop (a mobile drawer / overflow menu): a bare Tailwind `hidden`
	 *  with no responsive reveal, a responsive `md:hidden`, sr-only, or an inline / computed display:none. */
	private static function header_row_hidden( $row ) {
		if ( self::nav_el_hidden( $row ) ) { return true; }
		$lc = ' ' . strtolower( self::cls( $row ) ) . ' ';
		// the MOBILE DRAWER: a `md:hidden` / `lg:hidden` panel, or a `fixed inset-0` full-screen overlay (the phone menu's own
		// markup, closed on desktop) is never a masthead row — it became a 900px-tall bottom bar holding the menu (a finding)
		if ( preg_match( '/\s(?:sm|md|lg|xl|2xl):hidden\s/', $lc ) ) { return true; }
		$rcs = (string) $row->getAttribute( 'data-sc-cs' );
		if ( ( strpos( $lc, ' fixed ' ) !== false || preg_match( '/(?:^|;)\s*position:\s*fixed/i', $rcs ) ) && ( strpos( $lc, ' inset-0 ' ) !== false || preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $rcs, $rh ) && (float) $rh[1] >= 500 ) ) { return true; }
		if ( strpos( $lc, ' hidden ' ) !== false && ! preg_match( '/\s(?:sm|md|lg|xl|2xl):(?:flex|block|grid|inline-flex|inline)\s/', $lc ) ) { return true; }
		return 'none' === strtolower( self::sc_css( $row, 'display' ) );
	}

	/**
	 * TWO-ROW masthead. Some headers stack a BRAND ROW (logo · chip · CTAs) over a NAV ROW that holds only
	 * the menu links (or the reverse). The theme's three-zone main row can't express that — the nav landed
	 * in the brand row's right zone and the second row vanished — but its native Top Bar / Bottom Bar can.
	 * Finds the header's direct-child row that is LINKS-ONLY (≥2 short nav links, no image, no button, no
	 * other text) beside a distinct BRAND row, and reads the nav row's rule / padding / alignment / gap /
	 * fill plus the brand row's own height (the header's at-rest min-height must be the BRAND row, not the
	 * two rows stacked — the theme lays the bottom bar out as its own row).
	 *
	 * @return array {} for a one-row header, else { nav_pos:'bottom'|'top', nav_cls, brand_height?, nav_height?,
	 *               border?:{width,style,color,side}, padding?, align:'left'|'center'|'right', gap?, bg? }
	 */
	private static function header_rows( $header ) {
		if ( ! ( $header instanceof DOMElement ) ) { return array(); }
		$children = self::el_children( $header );
		// `<header><div class="container">…rows…</div></header>` — descend single-child wrappers to the rows.
		$depth = 0;
		while ( count( $children ) === 1 && $depth < 3 ) { $children = self::el_children( $children[0] ); $depth++; }
		if ( count( $children ) < 2 ) { return array(); }
		$norm = function ( $s ) { return preg_replace( '/\s+/', '', strtolower( (string) $s ) ); };
		$links_only = function ( $row ) use ( $norm ) {
			if ( $row->getElementsByTagName( 'img' )->length > 0 || $row->getElementsByTagName( 'button' )->length > 0 ) { return false; }
			$links = 0; $link_txt = '';
			foreach ( $row->getElementsByTagName( 'a' ) as $a ) {
				if ( self::is_button( $a ) || self::cs_is_button( $a ) ) { return false; }
				$t = trim( self::text_no_icons( $a ) );
				if ( $t === '' || mb_strlen( $t ) > 24 ) { continue; }
				$links++; $link_txt .= ' ' . $t;
			}
			if ( $links < 2 ) { return false; }
			// The row's WHOLE text must be its links — no stray tagline / chip / heading beside them.
			return $norm( self::text_no_icons( $row ) ) === $norm( $link_txt );
		};
		$is_brand = function ( $row ) {
			if ( $row->getElementsByTagName( 'img' )->length > 0 ) { return true; }
			foreach ( $row->getElementsByTagName( '*' ) as $d ) {
				if ( ! ( $d instanceof DOMElement ) ) { continue; }
				if ( '' !== $d->getAttribute( 'data-sc-logo-svg' ) ) { return true; }
				if ( preg_match( '/(^|\s|-|_)(brand|logo)(\s|-|_|$)/', strtolower( self::cls( $d ) ) ) ) { return true; }
			}
			return false;
		};
		$nav_i = -1; $brand_i = -1;
		foreach ( $children as $i => $row ) {
			if ( ! ( $row instanceof DOMElement ) || self::header_row_hidden( $row ) ) { continue; }
			if ( $nav_i < 0 && $links_only( $row ) ) { $nav_i = $i; continue; }
			if ( $brand_i < 0 && $is_brand( $row ) ) { $brand_i = $i; }
		}
		if ( $nav_i < 0 || $brand_i < 0 ) { return array(); }
		$nav = $children[ $nav_i ]; $brand = $children[ $brand_i ];
		// STACKED, not side by side: a classic one-row masthead (a flex `justify-between` container holding logo · links · actions)
		// also has a links-only child and a brand child — DOM order alone read it as two rows and pushed the menu into a
		// Bottom Bar. Two rows means the nav's box lies below (or above) the brand's box: the zone stamp's y / h (capture
		// >= 1.11.0), else the container's own layout (a flex ROW / a multi-track grid lays its children side by side).
		$yh = function ( $el ) { $z = (string) $el->getAttribute( 'data-sc-zone' ); $y = preg_match( '/(?:^|;)y:\s*(-?[0-9.]+)px/', $z, $m ) ? (float) $m[1] : null; $h = preg_match( '/(?:^|;)h:\s*([0-9.]+)px/', $z, $m2 ) ? (float) $m2[1] : null; return array( $y, $h ); };
		list( $ny, $nh0 ) = $yh( $nav ); list( $by, $bh0 ) = $yh( $brand );
		if ( null !== $ny && null !== $by && null !== $nh0 && null !== $bh0 ) {
			if ( ! ( $ny >= $by + $bh0 - 2 || $ny + $nh0 <= $by + 2 ) ) { return array(); } // the boxes overlap vertically → one row
		} else {
			$pc = ( $nav->parentNode instanceof DOMElement ) ? (string) $nav->parentNode->getAttribute( 'data-sc-cs' ) : '';
			$side_by_side = ( preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex\b/i', $pc ) && ! preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $pc ) )
				|| ( preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?grid\b/i', $pc ) && preg_match( '/(?:^|;)\s*grid-template-columns:\s*[0-9.]+px\s+[0-9.]+px/i', $pc ) );
			if ( $side_by_side ) { return array(); }
		}
		$out = array( 'nav_pos' => ( $nav_i > $brand_i ) ? 'bottom' : 'top', 'nav_cls' => trim( self::cls( $nav ) ) );
		$zone = (string) $nav->getAttribute( 'data-sc-zone' );
		$h = self::sc_css( $brand, 'height' );
		if ( '' === $h && preg_match( '/(?:^|;)h:\s*([0-9.]+px)/', (string) $brand->getAttribute( 'data-sc-zone' ), $zh ) ) { $h = $zh[1]; }
		if ( preg_match( '/^([0-9.]+)px$/', $h, $m ) && (float) $m[1] >= 32 ) { $out['brand_height'] = (int) round( (float) $m[1] ); }
		$nh = self::sc_css( $nav, 'height' );
		if ( '' === $nh && preg_match( '/(?:^|;)h:\s*([0-9.]+px)/', $zone, $zh ) ) { $nh = $zh[1]; }
		if ( preg_match( '/^([0-9.]+)px$/', $nh, $m ) && (float) $m[1] >= 16 ) { $out['nav_height'] = (int) round( (float) $m[1] ); }
		// The rule line sits on the nav row's edge that FACES the brand row.
		$side = ( 'bottom' === $out['nav_pos'] ) ? 'top' : 'bottom';
		$bw = self::sc_css( $nav, 'border-' . $side . '-width' ); $bs = self::sc_css( $nav, 'border-' . $side . '-style' ); $bc = self::sc_css( $nav, 'border-' . $side . '-color' );
		if ( ( '' === $bw || (float) $bw <= 0 ) && preg_match( '/border:\s*([0-9.]+px)\s+([a-z]+)\s+(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', $zone, $zm ) ) { $bw = $zm[1]; $bs = $zm[2]; $bc = $zm[3]; }
		if ( '' !== $bw && (float) $bw > 0 && '' !== $bs && 'none' !== $bs && '' !== $bc && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bc ) ) {
			$out['border'] = array( 'width' => (int) max( 1, round( (float) $bw ) ), 'style' => $bs, 'color' => $bc, 'side' => $side );
		}
		$pad = trim( (string) self::sc_css( $nav, 'padding' ) );
		if ( '' === $pad && preg_match( '/(?:^|;)pad:\s*([^;]+)/', $zone, $zp ) ) { $pad = trim( $zp[1] ); }
		if ( '' !== $pad && preg_match( '/^[0-9.]+px(?:\s+[0-9.]+px){0,3}$/', $pad ) ) { $out['padding'] = $pad; }
		$just = self::sc_css( $nav, 'justify-content' );
		if ( ( '' === $just || 'normal' === $just ) && preg_match( '/(?:^|;)justify:\s*([a-z-]+)/i', $zone, $jm ) ) { $just = $jm[1]; }
		$out['align'] = ( strpos( $just, 'center' ) !== false ) ? 'center' : ( ( strpos( $just, 'end' ) !== false ) ? 'right' : 'left' );
		$gap = self::sc_css( $nav, 'gap' );
		if ( preg_match( '/^([0-9.]+)px/', $gap, $gm ) && (float) $gm[1] > 0 ) { $out['gap'] = (int) round( (float) $gm[1] ); }
		$bg = self::sc_css( $nav, 'background-color' );
		if ( '' !== $bg && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) { $out['bg'] = $bg; }
		// The links' own line-height — the row's height IS padding + this (the theme's menu list otherwise
		// applies its own 30px line box and a 44px row minimum, which nearly doubled a 38px source row).
		$a1 = $nav->getElementsByTagName( 'a' )->item( 0 );
		$lh = ( $a1 instanceof DOMElement ) ? self::sc_css( $a1, 'line-height' ) : '';
		if ( preg_match( '/^([0-9.]+)px$/', $lh, $lm ) && (float) $lm[1] > 0 ) { $out['link_lh'] = (int) round( (float) $lm[1] ); }
		return $out;
	}

	/**
	 * Decorative TEXT CHIPS in the masthead — a pill of short text beside the logo (a season label with a
	 * glowing dot). Not a link, not a button, not the brand, not a nav item: a plain styled label. Each
	 * becomes a native `list_item` element (text + an optional dot icon), hidden on the devices the source
	 * hides it on, with its pill skin carried as scoped CSS keyed by the element's CSS Class. A chip is an
	 * element with its OWN short text that is either pill-shaped (radius ≥ 40px) or a filled, padded box.
	 *
	 * @return array[] [ { text, cls, cs, dot:{size,color,shadow}|null, hide:[hide-xs…] } … ] (≤ 2)
	 */
	private static function header_chips( $header, $html ) {
		$out = array();
		if ( ! ( $header instanceof DOMElement ) ) { return $out; }
		$menu   = self::find_menu_group( $header );
		$inside = function ( $el, $anc ) { for ( $p = $el; $p instanceof DOMNode; $p = $p->parentNode ) { if ( $p === $anc ) { return true; } } return false; };
		$in_tag = function ( $el, $tags ) use ( $header ) {
			for ( $p = $el; $p instanceof DOMElement && $p !== $header; $p = $p->parentNode ) { if ( in_array( strtolower( $p->tagName ), $tags, true ) ) { return true; } }
			return false;
		};
		$in_brand = function ( $el ) use ( $header ) {
			for ( $p = $el; $p instanceof DOMElement && $p !== $header; $p = $p->parentNode ) {
				if ( '' !== $p->getAttribute( 'data-sc-logo-svg' ) || $p->getElementsByTagName( 'img' )->length > 0 ) { return true; }
				if ( preg_match( '/(^|\s|-|_)(brand|logo)(\s|-|_|$)/', strtolower( self::cls( $p ) ) ) ) { return true; }
			}
			return false;
		};
		foreach ( $header->getElementsByTagName( '*' ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$tag = strtolower( $el->tagName );
			if ( in_array( $tag, array( 'a', 'button', 'nav', 'ul', 'li', 'img', 'svg', 'script', 'style', 'input', 'select', 'form' ), true ) ) { continue; }
			if ( $in_tag( $el, array( 'a', 'button', 'nav', 'ul', 'form' ) ) ) { continue; }
			if ( $menu instanceof DOMElement && $inside( $el, $menu ) ) { continue; }
			if ( self::nav_el_hidden( $el ) ) { continue; }
			// Its OWN direct text — a wrapper around the chip is not the chip.
			$own = '';
			foreach ( $el->childNodes as $cn ) { if ( XML_TEXT_NODE === $cn->nodeType ) { $own .= $cn->nodeValue; } }
			$own = trim( preg_replace( '/\s+/', ' ', $own ) );
			if ( '' === $own || mb_strlen( $own ) > 80 ) { continue; }
			if ( $in_brand( $el ) ) { continue; }
			$radius = self::sc_css( $el, 'border-radius' ); $bg = self::sc_css( $el, 'background-color' ); $pad = self::sc_css( $el, 'padding' );
			$has_bg  = '' !== $bg && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg );
			$pill    = preg_match( '/^([0-9.]+)px/', $radius, $rm ) && (float) $rm[1] >= 40;
			$has_pad = preg_match( '/^([0-9.]+)px(?:\s+([0-9.]+)px)?/', $pad, $pm ) && ( (float) $pm[1] > 0 || ( isset( $pm[2] ) && (float) $pm[2] > 0 ) );
			if ( ! ( $pill || ( $has_bg && $has_pad ) ) ) { continue; }
			$chip = array( 'text' => $own, 'cls' => trim( self::cls( $el ) ), 'cs' => (string) $el->getAttribute( 'data-sc-cs' ), 'dot' => null, 'hide' => array() );
			// A dot / pip: a tiny EMPTY child (≤ 12px tall) with its own fill → carried as an SVG circle icon.
			foreach ( self::el_children( $el ) as $k ) {
				if ( '' !== trim( self::text_no_icons( $k ) ) ) { continue; }
				$kh = self::sc_css( $k, 'height' ); $kb = self::sc_css( $k, 'background-color' );
				if ( preg_match( '/^([0-9.]+)px$/', $kh, $hm ) && (float) $hm[1] <= 12 && '' !== $kb && stripos( $kb, 'transparent' ) === false ) {
					$chip['dot'] = array( 'size' => max( 4, (int) round( (float) $hm[1] ) ), 'color' => $kb, 'shadow' => self::sc_css( $k, 'box-shadow' ) );
					break;
				}
			}
			$chip['hide'] = self::css_hide_visibility( $html, $el );
			$out[] = $chip;
			if ( count( $out ) >= 2 ) { break; }
		}
		return $out;
	}

	/**
	 * The chip's pill skin as scoped CSS on the theme's own list_item markup, keyed by the element CSS Class
	 * the emit stamps on it. Only properties the source set are carried (no invented defaults).
	 */
	private static function header_chip_css( $chip, $cls ) {
		$cs = (string) ( $chip['cs'] ?? '' );
		if ( '' === $cs ) { return ''; }
		$get = function ( $prop ) use ( $cs ) { return preg_match( '/(?:^|;)\s*' . preg_quote( $prop, '/' ) . '\s*:\s*([^;]+)/i', $cs, $m ) ? trim( $m[1] ) : ''; };
		$d = array( 'display:inline-flex', 'align-items:center', 'white-space:nowrap' );
		foreach ( array( 'gap', 'padding', 'border-radius', 'background-color', 'color', 'font-size', 'font-weight', 'letter-spacing', 'text-transform', 'line-height', 'box-shadow' ) as $p ) {
			$v = $get( $p );
			if ( '' === $v || 'normal' === $v || 'none' === $v || '0px' === $v ) { continue; }
			if ( 'background-color' === $p && ( stripos( $v, 'transparent' ) !== false || preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $v ) ) ) { continue; }
			$d[] = $p . ':' . $v;
		}
		$bw = $get( 'border-top-width' ); $bs = $get( 'border-top-style' ); $bc = $get( 'border-top-color' );
		if ( '' !== $bw && (float) $bw > 0 && '' !== $bs && 'none' !== $bs && '' !== $bc ) { $d[] = 'border:' . $bw . ' ' . $bs . ' ' . $bc; }
		$sel = '.site-header .' . $cls;
		$css = "\n/* Source header chip */\n" . $sel . ' .list-item{' . implode( ';', $d ) . ';}';
		if ( ! empty( $chip['dot'] ) ) {
			$dot = $chip['dot']; $sz = (int) $dot['size'];
			$css .= $sel . ' .list-item__icon{width:' . $sz . 'px;height:' . $sz . 'px;border-radius:999px;' . ( ! empty( $dot['shadow'] ) && 'none' !== $dot['shadow'] ? 'box-shadow:' . $dot['shadow'] . ';' : '' ) . '}'
				. $sel . ' .list-item__icon svg{width:' . $sz . 'px;height:' . $sz . 'px;display:block;}';
		}
		return $css;
	}

	/**
	 * Which devices the source HIDES an element on, read from its stylesheet's `@media (max-width: Npx)`
	 * blocks that set the element's own class / id to `display:none` → the theme's per-element Hide On
	 * checkboxes. ≤ 767px → mobile only; a wider cut-off (a chip hidden under ~1100px) → mobile + tablet
	 * (`hide-md` would hide it on EVERY desktop, which a max-width rule never means).
	 */
	private static function css_hide_visibility( $html, $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return array(); }
		$sels = array();
		$id = trim( (string) $el->getAttribute( 'id' ) );
		if ( '' !== $id ) { $sels[] = '#' . preg_quote( $id, '/' ); }
		foreach ( preg_split( '/\s+/', trim( self::cls( $el ) ) ) as $c ) { if ( '' !== $c ) { $sels[] = '\.' . preg_quote( $c, '/' ); } }
		if ( ! $sels ) { return array(); }
		$css = self::all_style_css( $html );
		$bp  = 0;
		if ( preg_match_all( '/@media[^{]*max-width\s*:\s*([0-9.]+)px[^{]*\{/i', $css, $mm, PREG_OFFSET_CAPTURE ) ) {
			$len = strlen( $css );
			foreach ( $mm[0] as $i => $m ) {
				$start = $m[1] + strlen( $m[0] ); $depth = 1; $pos = $start;
				while ( $pos < $len && $depth > 0 ) { $ch = $css[ $pos ]; if ( '{' === $ch ) { $depth++; } elseif ( '}' === $ch ) { $depth--; } $pos++; }
				$block = substr( $css, $start, $pos - $start );
				if ( preg_match( '/(?:' . implode( '|', $sels ) . ')(?![\w-])[^{}]*\{[^}]*display\s*:\s*none/i', $block ) ) { $bp = max( $bp, (int) $mm[1][ $i ][0] ); }
			}
		}
		if ( $bp <= 0 ) { return array(); }
		return ( $bp <= 767 ) ? array( 'hide-xs' ) : array( 'hide-xs', 'hide-sm' );
	}

	/**
	 * A DECLARED value for $prop in the source stylesheet's rules that target $el by its own #id / .class
	 * as a lone simple selector. The capture's computed-style stamp omits some properties (border-bottom-*
	 * before capture 1.10.78), so a `.header-shell{border-bottom:1px solid …}` rule is the only place that
	 * hairline exists. Last declaration wins; returns '' when nothing declares it.
	 */
	/**
	 * For a FLUID-sized element: its line-height / letter-spacing expressed RELATIVE to the font (so they keep
	 * scaling). The sheet's own relative declaration wins (a unitless number, em, %); otherwise the computed
	 * px pair yields the ratio (72.576 ÷ 80.64 → .9 · -4.8384 ÷ 80.64 → -.06em). '' when nothing is known.
	 */
	private static function fluid_relative_decls( $el, $cs ) {
		$out = array( 'lh' => '', 'ls' => '' );
		$ratio = function ( $a, $b ) { return rtrim( rtrim( number_format( $a / $b, 3, '.', '' ), '0' ), '.' ); };
		$fs = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $cs, $m ) ? (float) $m[1] : 0.0;
		$lh = self::stylesheet_decl( null, $el, 'line-height' );
		if ( preg_match( '/^(?:\d*\.?\d+|[0-9.]+(?:em|%))$/i', $lh ) ) { $out['lh'] = $lh; }
		elseif ( $fs > 0 && preg_match( '/(?:^|;)\s*line-height:\s*([0-9.]+)px/i', (string) $cs, $m ) ) { $out['lh'] = $ratio( (float) $m[1], $fs ); }
		$ls = self::stylesheet_decl( null, $el, 'letter-spacing' );
		if ( preg_match( '/^-?[0-9.]+(?:em|%)$/i', $ls ) ) { $out['ls'] = $ls; }
		elseif ( $fs > 0 && preg_match( '/(?:^|;)\s*letter-spacing:\s*(-?[0-9.]+)px/i', (string) $cs, $m ) && 0.0 !== (float) $m[1] ) { $out['ls'] = $ratio( (float) $m[1], $fs ) . 'em'; }
		return $out;
	}

	/**
	 * The value the SOURCE STYLESHEET declares for $prop on $el — the last matching rule in sheet order (the
	 * computed style is one viewport's snapshot; this is the author's expression: a clamp(), a unitless
	 * line-height, an em tracking, a min() width). Matches the way a browser does, minus specificity: every
	 * rule's selector list is parsed into COMPOUNDS (tag / #id / .class, joined by descendant or child
	 * combinators) and the last compound must match the element, the earlier ones its ancestors — so a
	 * '.core-copy h2 { font-size: clamp(…) }' rule reaches the h2 (own-class-only matching missed every
	 * descendant rule). Pseudo selectors are skipped (their declarations don't apply to the element itself).
	 * No $html → the <style> blocks off the owner document. JS twin: sheetDecl() via el.matches().
	 */
	private static function stylesheet_decl( $html, $el, $prop ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		if ( null === $html && $el->ownerDocument ) {
			$html = '';
			foreach ( $el->ownerDocument->getElementsByTagName( 'style' ) as $st ) { $html .= '<style>' . $st->textContent . '</style>'; }
		}
		$rules = self::sheet_rules( (string) $html );
		$val   = ''; $best = -1;
		foreach ( $rules as $r ) {
			if ( ! preg_match( '/(?:^|;)\s*' . preg_quote( $prop, '/' ) . '\s*:\s*([^;]+)/i', $r['body'], $pm ) ) { continue; }
			// Highest SPECIFICITY wins, later sheet order breaks ties — the browser's cascade (a Tailwind preflight
			// 'h1,h2{font-size:inherit}' comes later in the sheet but must not beat '.core-copy h2').
			foreach ( $r['sels'] as $sel ) { if ( $sel['spec'] >= $best && self::sel_matches( $sel['chain'], $el ) ) { $val = trim( $pm[1] ); $best = $sel['spec']; break; } }
		}
		return $val;
	}

	/** Parse a stylesheet into [ { sels: [ [compound…] …], body } ] in sheet order (cached per sheet text). */
	private static function sheet_rules( $css ) {
		static $cache = array();
		$key = md5( $css );
		if ( isset( $cache[ $key ] ) ) { return $cache[ $key ]; }
		$css   = self::all_style_css( $css );
		$css   = preg_replace( '#/\*.*?\*/#s', '', $css );
		$css   = self::sheet_unwrap_at_rules( $css );
		$rules = array();
		if ( preg_match_all( '/([^{}]+)\{([^{}]*)\}/', $css, $mm, PREG_SET_ORDER ) ) {
			foreach ( $mm as $m ) {
				$sels = array();
				foreach ( explode( ',', $m[1] ) as $sel ) {
					$sel = trim( $sel );
					if ( '' === $sel || '@' === $sel[0] || false !== strpos( $sel, ':' ) || false !== strpos( $sel, '[' ) || preg_match( '/[+~]/', $sel ) ) { continue; }
					// Re-split keeping the combinator kind: a child combinator is recorded as a '>' token.
					$toks = preg_split( '/(\s*>\s*|\s+)/', $sel, -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_NO_EMPTY );
					$chain = array(); $child = false; $bad = false;
					foreach ( $toks as $t ) {
						if ( '' === trim( $t ) ) { continue; }
						if ( '>' === trim( $t ) ) { $child = true; continue; }
						if ( ! preg_match( '/^(\*|[a-z][a-z0-9-]*)?((?:[.#][\w-]+)*)$/i', $t, $cm ) ) { $bad = true; break; }
						$c = array( 'tag' => strtolower( (string) $cm[1] ), 'id' => '', 'cls' => array(), 'child' => $child );
						if ( preg_match_all( '/([.#])([\w-]+)/', (string) $cm[2], $am, PREG_SET_ORDER ) ) { foreach ( $am as $a ) { if ( '#' === $a[1] ) { $c['id'] = $a[2]; } else { $c['cls'][] = $a[2]; } } }
						$chain[] = $c; $child = false;
					}
					if ( $bad || ! $chain ) { continue; }
					$spec = 0;
					foreach ( $chain as $c ) { $spec += ( '' !== $c['id'] ? 10000 : 0 ) + 100 * count( $c['cls'] ) + ( ( '' !== $c['tag'] && '*' !== $c['tag'] ) ? 1 : 0 ); }
					$sels[] = array( 'chain' => $chain, 'spec' => $spec );
				}
				if ( $sels ) { $rules[] = array( 'sels' => $sels, 'body' => $m[2] ); }
			}
		}
		if ( count( $cache ) > 8 ) { $cache = array(); }
		$cache[ $key ] = $rules;
		return $rules;
	}

	/**
	 * MEDIA-AWARE: the capture is a desktop snapshot (SHEET_VW wide), so a rule inside `@media (max-width:768px)` does
	 * not apply to it — yet a flat scan read it as global and a mobile `.shell{width:min(100% - 32px,…)}` beat the
	 * desktop rule. Unwrap the at-rules the viewport satisfies (their inner rules become global, in place), blank the
	 * ones it doesn't (and @keyframes / @font-face, which hold no element rules). JS twin: window.matchMedia.
	 */
	const SHEET_VW = 1440;
	private static function sheet_unwrap_at_rules( $css ) {
		$out = ''; $i = 0; $n = strlen( $css );
		while ( $i < $n ) {
			$at = strpos( $css, '@', $i );
			if ( false === $at ) { $out .= substr( $css, $i ); break; }
			$out .= substr( $css, $i, $at - $i );
			$ob = strpos( $css, '{', $at );
			if ( false === $ob ) { $out .= substr( $css, $at ); break; }
			$head = substr( $css, $at, $ob - $at );
			if ( ';' !== substr( trim( $head ), -1 ) && false !== strpos( $head, ';' ) ) { $out .= substr( $css, $at, $ob - $at ); $i = $ob; continue; } // an @import/@charset line, not a block
			// Find the matching close brace.
			$depth = 0; $j = $ob;
			for ( ; $j < $n; $j++ ) { $c = $css[ $j ]; if ( '{' === $c ) { $depth++; } elseif ( '}' === $c ) { $depth--; if ( 0 === $depth ) { break; } } }
			$body = substr( $css, $ob + 1, max( 0, $j - $ob - 1 ) );
			$kind = strtolower( trim( preg_replace( '/^@([a-z-]+).*$/is', '$1', $head ) ) );
			$keep = false;
			if ( 'media' === $kind )    { $keep = self::media_query_matches( substr( trim( $head ), 6 ) ); }
			elseif ( 'supports' === $kind || 'layer' === $kind || 'container' === $kind ) { $keep = true; }
			if ( $keep ) { $out .= ' ' . self::sheet_unwrap_at_rules( $body ) . ' '; }
			else { $out .= str_repeat( ' ', $j - $at + 1 ); }
			$i = $j + 1;
		}
		return $out;
	}

	/** Does a media query list hold for the capture viewport? Only width features are evaluated (screen/all pass,
	 *  print fails; prefers-* / hover / pointer are assumed to hold). */
	private static function media_query_matches( $q ) {
		$q = strtolower( trim( (string) $q ) );
		if ( '' === $q ) { return true; }
		foreach ( explode( ',', $q ) as $one ) {
			$one = trim( $one );
			if ( preg_match( '/\bprint\b/', $one ) && ! preg_match( '/\bnot\s+print\b/', $one ) ) { continue; }
			$ok = true;
			if ( preg_match_all( '/\(\s*(min|max)-width\s*:\s*([0-9.]+)(px|em|rem)\s*\)/', $one, $mm, PREG_SET_ORDER ) ) {
				foreach ( $mm as $m ) {
					$px = (float) $m[2] * ( 'px' === $m[3] ? 1 : 16 );
					if ( 'min' === $m[1] && self::SHEET_VW < $px ) { $ok = false; }
					if ( 'max' === $m[1] && self::SHEET_VW > $px ) { $ok = false; }
				}
			}
			if ( preg_match_all( '/\(\s*width\s*(<=|>=|<|>)\s*([0-9.]+)(px|em|rem)\s*\)/', $one, $mm, PREG_SET_ORDER ) ) {
				foreach ( $mm as $m ) {
					$px = (float) $m[2] * ( 'px' === $m[3] ? 1 : 16 ); $v = self::SHEET_VW;
					if ( ( '<=' === $m[1] && ! ( $v <= $px ) ) || ( '<' === $m[1] && ! ( $v < $px ) ) || ( '>=' === $m[1] && ! ( $v >= $px ) ) || ( '>' === $m[1] && ! ( $v > $px ) ) ) { $ok = false; }
				}
			}
			if ( preg_match( '/^\s*not\b/', $one ) ) { $ok = ! $ok; }
			if ( $ok ) { return true; }
		}
		return false;
	}

	/** Does one parsed selector chain match $el (last compound on the element, earlier ones on its ancestors)? */
	private static function sel_matches( array $chain, $el ) {
		$compound_ok = function ( array $c, DOMElement $e ) {
			if ( '' !== $c['tag'] && '*' !== $c['tag'] && strtolower( $e->tagName ) !== $c['tag'] ) { return false; }
			if ( '' !== $c['id'] && (string) $e->getAttribute( 'id' ) !== $c['id'] ) { return false; }
			if ( $c['cls'] ) {
				$have = preg_split( '/\s+/', trim( self::cls( $e ) ) );
				foreach ( $c['cls'] as $need ) { if ( ! in_array( $need, $have, true ) ) { return false; } }
			}
			return true;
		};
		$i = count( $chain ) - 1;
		if ( ! $compound_ok( $chain[ $i ], $el ) ) { return false; }
		$node = $el;
		for ( $i--; $i >= 0; $i-- ) {
			$c = $chain[ $i ];
			$must_child = ! empty( $chain[ $i + 1 ]['child'] );
			$found = false;
			for ( $a = $node->parentNode; $a instanceof DOMElement; $a = $a->parentNode ) {
				if ( $compound_ok( $c, $a ) ) { $found = true; $node = $a; break; }
				if ( $must_child ) { break; }
			}
			if ( ! $found ) { return false; }
		}
		return true;
	}

	/**
	 * H5 — is the primary nav a ONE-PAGE anchor menu? True when there are ≥2 real nav items and EVERY
	 * one targets an in-page anchor (`#id` or `/#id` / `page#id`). Such a source is a single-page site
	 * whose menu highlights the active section as you scroll → the theme's Scroll Spy (nav_scrollspy).
	 * The target sections already inherit their source `id` (section_id from the source id attribute),
	 * so the anchors line up natively; we only flip the switch. Returns the list of target ids too.
	 */
	private static function nav_scrollspy_targets( $html ) {
		$m = self::extract_menus( (string) $html );
		$items = array();
		foreach ( $m['menus'] as $menu ) {
			if ( ( $menu['location'] ?? '' ) === 'primary' ) { $items = $menu['items']; break; }
		}
		if ( count( $items ) < 2 ) { return array(); }
		$ids = array();
		foreach ( $items as $it ) {
			$url = trim( (string) ( $it['url'] ?? '' ) );
			// Accept "#id", "/#id", "path#id" — but the fragment must be a REAL id, not a bare "#".
			if ( ! preg_match( '/#([A-Za-z][\w-]*)$/', $url, $mm ) ) { return array(); } // any non-anchor link disqualifies
			$ids[] = self::slug_from_id( $mm[1] );
		}
		return array_values( array_unique( array_filter( $ids ) ) );
	}

	/**
	 * H10 — per-element responsive VISIBILITY from Tailwind display-utility classes. Maps the source's
	 * `hidden` + `<bp>:block|flex|grid|inline*` (or `<bp>:hidden`) into the theme element's `visibility`
	 * shape ({ 'hide-xs':bool, 'hide-sm':bool, 'hide-md':bool } → hide-xs/sm/md classes). The three theme
	 * tiers approximate Tailwind's ladder: xs (<640) · sm (640–1024) · md (>=1024). Returns [] when the
	 * element carries no responsive display signal (the common case — visible everywhere).
	 */
	private static function responsive_hide_visibility( $cls ) {
		$c = ' ' . strtolower( (string) $cls ) . ' ';
		$hide = array();
		if ( strpos( $c, ' hidden ' ) !== false ) {
			// Base-hidden, then revealed at a breakpoint → hide every tier BELOW that breakpoint.
			if ( preg_match( '/\slg:(?:block|flex|grid|inline-flex|inline-block|inline|table)\s/', $c ) )      { $hide = array( 'hide-xs', 'hide-sm', 'hide-md' ); }
			elseif ( preg_match( '/\smd:(?:block|flex|grid|inline-flex|inline-block|inline|table)\s/', $c ) )  { $hide = array( 'hide-xs', 'hide-sm' ); }
			elseif ( preg_match( '/\ssm:(?:block|flex|grid|inline-flex|inline-block|inline|table)\s/', $c ) )  { $hide = array( 'hide-xs' ); }
			else { $hide = array( 'hide-xs', 'hide-sm', 'hide-md' ); } // `hidden` with no reveal = hidden everywhere
		} else {
			// Visible by default, hidden FROM a breakpoint up → hide that tier (and above, within our 3 tiers).
			if ( preg_match( '/\ssm:hidden\s/', $c ) )      { $hide = array( 'hide-sm', 'hide-md' ); }
			elseif ( preg_match( '/\s(?:md|lg):hidden\s/', $c ) ) { $hide = array( 'hide-md' ); }
		}
		if ( ! $hide ) { return array(); }
		$out = array(); foreach ( $hide as $h ) { $out[ $h ] = true; }
		return $out;
	}

	/**
	 * Detect MEGA MENUS from the `<script id="sc-mega-menus">` the capture stamps (each entry = a nav trigger
	 * whose dropdown panel was opened + serialized, because these panels are JS-mounted on hover and absent
	 * from a static snapshot). For each panel we read the grid column count and the link cells (label + url +
	 * description), distributing them into columns the way CSS grid fills (row-major: column j = items j, j+N,
	 * j+2N…). Returns [ { trigger, cols, columns:[ [ {label,url,desc} ] ] } ], empty when none — the input for
	 * the megamenu extension population at import.
	 *
	 * @param string $html
	 * @return array
	 */
	public static function detect_mega_menus( $html ) {
		$html = (string) $html;
		if ( strpos( $html, 'sc-mega-menus' ) === false ) { return array(); }
		if ( ! preg_match( '/<script[^>]*id="sc-mega-menus"[^>]*>(.*?)<\/script>/s', $html, $m ) ) { return array(); }
		$data = json_decode( html_entity_decode( trim( $m[1] ), ENT_QUOTES ), true );
		if ( ! is_array( $data ) ) { $data = json_decode( trim( $m[1] ), true ); }
		if ( ! is_array( $data ) ) { return array(); }
		$out = array();
		foreach ( $data as $panel ) {
			$trigger = trim( (string) ( $panel['label'] ?? '' ) );
			$phtml   = (string) ( $panel['html'] ?? '' );
			if ( $trigger === '' || $phtml === '' ) { continue; }
			$dom = self::load_dom( '<div>' . $phtml . '</div>' );
			if ( ! $dom ) { continue; }
			// Column count from a `grid-cols-N` utility (default 1 → a simple column list).
			$cols = 1;
			if ( preg_match( '/grid-cols-(\d+)/', $phtml, $gm ) ) { $cols = max( 1, min( 6, (int) $gm[1] ) ); }
			// Each link cell → { label, url, desc }: the first heading/strong/bold text is the label, a
			// following <p>/muted line is the description.
			$items = array();
			foreach ( $dom->getElementsByTagName( 'a' ) as $a ) {
				$href = trim( (string) $a->getAttribute( 'href' ) );
				$label = ''; $desc = '';
				foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6', 'strong', 'b', 'span', 'div' ) as $lt ) {
					foreach ( $a->getElementsByTagName( $lt ) as $el ) { $t = trim( preg_replace( '/\s+/', ' ', $el->textContent ) ); if ( $t !== '' ) { $label = $t; break 2; } }
				}
				$ps = $a->getElementsByTagName( 'p' );
				if ( $ps->length ) { $desc = trim( preg_replace( '/\s+/', ' ', $ps->item( $ps->length - 1 )->textContent ) ); }
				if ( $label === '' ) { $label = trim( preg_replace( '/\s+/', ' ', $a->textContent ) ); }
				if ( $desc !== '' && $desc === $label ) { $desc = ''; }
				if ( $label === '' ) { continue; }
				$items[] = array( 'label' => $label, 'url' => ( $href !== '' ? $href : '#' ), 'desc' => $desc );
			}
			if ( count( $items ) < 2 ) { continue; } // not a real mega panel
			// Distribute into columns the way the grid fills (row-major): column j = items j, j+cols, …
			$columns = array_fill( 0, $cols, array() );
			foreach ( $items as $i => $it ) { $columns[ $i % $cols ][] = $it; }
			$out[] = array( 'trigger' => $trigger, 'cols' => $cols, 'columns' => $columns );
		}
		return $out;
	}

	/** The design-config menu items (label/url list) for a location, from the page chrome. */
	private static function design_menu( $html, $location ) {
		$m = self::extract_menus( $html );
		foreach ( $m['menus'] as $menu ) {
			if ( ( $menu['location'] ?? '' ) === $location ) { return $menu['items']; }
		}
		return array();
	}

	/** Component CSS baked into the child theme (cards / image rounding) — palette/fonts the generator does. */
	private static function tokens_to_component_css( array $tokens ) {
		$surface = self::token_color( $tokens, array( 'white-card', 'soft-card-2', 'surface-container-low', 'panel-bg', 'surface-container' ) );
		$line    = self::token_color( $tokens, array( 'line', 'outline-variant' ) );
		$muted   = self::token_color( $tokens, array( 'muted', 'on-surface-variant' ) );
		$radius  = '';
		foreach ( array( '3xl', 'xl', 'lg', 'full' ) as $k ) { if ( ! empty( $tokens['rounded'][ $k ] ) && ! is_array( $tokens['rounded'][ $k ] ) ) { $radius = (string) $tokens['rounded'][ $k ]; break; } }
		if ( $radius === '' ) { $radius = '20px'; }
		$surface = $surface !== '' ? $surface : '#ffffff';
		$line    = $line !== '' ? $line : '#ececec';
		$muted   = $muted !== '' ? $muted : '#8a8a8a';
		$out = array();
		$out[] = ".icon-box{background:$surface;border:1px solid $line;border-radius:$radius;padding:32px;height:100%;box-shadow:0 16px 38px -26px rgba(20,20,20,.18);}";
		$out[] = ".icon-box__title{font-weight:700;margin-bottom:8px;}";
		$out[] = ".icon-box__content{color:$muted;line-height:1.6;}";
		// Content images render block + centered so a converted <img> never flows INLINE next to
		// inline-block buttons (which baseline-aligned them to the bottom of a tall hero image).
		$out[] = "section img,.fw-main-row img{border-radius:$radius;max-width:100%;display:block;margin-left:auto;margin-right:auto;height:auto;}";
		return implode( "\n", $out );
	}

	/**
	 * (heading, body) font families read from the source's COMPUTED font-family (data-sc-cs) — the fallback
	 * for self-hosted-font frameworks that expose no tailwind fontFamily token and no googleapis <link>.
	 * Heading = the modal first-family among h1/h2/h3; body = the <body> family (else the modal <p> family).
	 * Generic keywords (serif/sans-serif/system-ui/…) are skipped so only a real named family is returned.
	 *
	 * @param string $html
	 * @return array{0:string,1:string}
	 */
	private static function detect_computed_fonts( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return array( '', '' ); }
		$first_family = function ( $ff ) {
			$ff = trim( (string) $ff );
			if ( $ff === '' ) { return ''; }
			$parts = explode( ',', $ff );
			$first = trim( $parts[0], " \t\"'" );
			$lc = strtolower( $first );
			if ( in_array( $lc, array( 'serif', 'sans-serif', 'monospace', 'system-ui', 'ui-sans-serif', 'ui-serif', 'ui-monospace', 'inherit', 'initial', '-apple-system', 'blinkmacsystemfont' ), true ) ) { return ''; }
			return $first;
		};
		// The DISPLAY face lives on the PRIMARY headings (h1, then h2) — take the first one that carries a
		// real family. Do NOT pool h3+ into the vote: card/section titles (icon-box, article, "Quick Links")
		// are numerous and usually render in the BODY font, so tallying them lets the body font outvote the
		// true display face (e.g. 11 Inter h3s drowning the 5 Playfair Display h1/h2s → heading mis-set to Inter).
		$head = ''; $head_stack = '';
		foreach ( array( 'h1', 'h2' ) as $tag ) {
			foreach ( $dom->getElementsByTagName( $tag ) as $h ) {
				$raw = self::sc_css( $h, 'font-family' );
				$fam = $first_family( $raw );
				if ( $fam !== '' ) {
					$head = $fam;
					// Keep the FULL computed stack too (e.g. `Neutraface Condensed Titling, Alfa Slab One, cursive`)
					// so a licensed primary that we can't rehost still resolves to its web-safe NAMED fallback
					// instead of a system serif — used for the global `--font-heading` / `:is(h…)` stack.
					if ( class_exists( 'FW_Site_Converter_Theme_Generator' ) ) {
						$head_stack = FW_Site_Converter_Theme_Generator::heading_fallback_stack( $raw );
					}
					break 2;
				}
			}
		}
		if ( $head === '' ) { // no h1/h2 face → fall back to the most common h3 face
			$tally = array();
			foreach ( $dom->getElementsByTagName( 'h3' ) as $h ) { $fam = $first_family( self::sc_css( $h, 'font-family' ) ); if ( $fam !== '' ) { $tally[ $fam ] = ( $tally[ $fam ] ?? 0 ) + 1; } }
			if ( $tally ) { arsort( $tally ); $head = (string) array_key_first( $tally ); }
		}
		$body = '';
		$b = $dom->getElementsByTagName( 'body' )->item( 0 );
		if ( $b instanceof DOMElement ) { $body = $first_family( self::sc_css( $b, 'font-family' ) ); }
		if ( $body === '' ) {
			$bt = array();
			foreach ( $dom->getElementsByTagName( 'p' ) as $p ) { $fam = $first_family( self::sc_css( $p, 'font-family' ) ); if ( $fam !== '' ) { $bt[ $fam ] = ( $bt[ $fam ] ?? 0 ) + 1; } }
			if ( $bt ) { arsort( $bt ); $body = (string) array_key_first( $bt ); }
		}
		// If body ended up equal to the heading display face (headings dominate the <p> sample on a sparse
		// page), leave body empty rather than mislabel — the theme's default body stack is safer than a serif.
		// (a body face that EQUALS the heading face is the site's one family — Outfit for both — not a mislabel: keep it. Blanking it
		// handed the body to the Google-URL's SECOND font, the site's mono for labels and code.)
		return array( $head, $body, $head_stack );
	}

	/** (headline, body) RAW font family names from the fontFamily tokens (the generator wraps them). */
	private static function pick_fonts_raw( array $tokens ) {
		$ff = $tokens['fontFamily'] ?? array();
		$first = function ( $keys ) use ( $ff ) {
			foreach ( $keys as $k ) {
				if ( isset( $ff[ $k ] ) ) {
					$v = is_array( $ff[ $k ] ) ? reset( $ff[ $k ] ) : $ff[ $k ];
					$v = trim( (string) $v );
					if ( $v !== '' ) { return $v; }
				}
			}
			return '';
		};
		return array(
			$first( array( 'headline-xl', 'headline-lg', 'headline-md', 'display', 'h1', 'h2', 'heading' ) ),
			$first( array( 'body-md', 'body-lg', 'body', 'label', 'label-sm' ) ),
		);
	}

	/* ---------------------------------------------------------------------- *
	 * Media
	 * ---------------------------------------------------------------------- */

	/** Collect raster image URLs from the Stitch HTML (reuses the media engine's scanner). */
	/**
	 * Derive the source ORIGIN (scheme://host) from a captured page's <head> — canonical link, og:url, or
	 * <base href>. Lets a same-origin root-relative asset (e.g. a Vite-bundled logo `/assets/dvele-*.png`)
	 * be absolutized so the media pipeline can DOWNLOAD it (an empty base makes absolutize() drop every
	 * root-relative ref, so those logos never reach media.json and 404 on the imported site).
	 *
	 * @param string $html
	 * @return string scheme://host, or '' if none can be derived.
	 */
	public static function derive_origin( $html ) {
		$html = (string) $html;
		$hint = '';
		if ( preg_match( '/<link\b[^>]*\brel\s*=\s*["\']canonical["\'][^>]*\bhref\s*=\s*["\']([^"\']+)["\']/i', $html, $m )
			|| preg_match( '/<meta\b[^>]*\bproperty\s*=\s*["\']og:url["\'][^>]*\bcontent\s*=\s*["\']([^"\']+)["\']/i', $html, $m )
			|| preg_match( '/<base\b[^>]*\bhref\s*=\s*["\']([^"\']+)["\']/i', $html, $m ) ) {
			$hint = $m[1];
		}
		if ( $hint !== '' && preg_match( '#^(https?://[^/]+)#i', $hint, $mm ) ) {
			return $mm[1];
		}
		return '';
	}

	public static function scan_images( $html ) {
		if ( class_exists( 'FW_Site_Converter_Media' ) && method_exists( 'FW_Site_Converter_Media', 'scan_html' ) ) {
			$urls = FW_Site_Converter_Media::scan_html( (string) $html, self::derive_origin( $html ) );
			return is_array( $urls ) ? array_values( array_unique( $urls ) ) : array();
		}
		// Minimal fallback: <img src> only.
		$out = array();
		if ( preg_match_all( '/<img[^>]+src=["\']([^"\']+)["\']/i', (string) $html, $m ) ) {
			foreach ( $m[1] as $u ) { if ( strpos( $u, 'data:' ) !== 0 ) { $out[] = $u; } }
		}
		return array_values( array_unique( $out ) );
	}

	/* ---------------------------------------------------------------------- *
	 * HTML → Mapper mapping (the section/block tree the Mapper builds pages from)
	 * ---------------------------------------------------------------------- */

	/**
	 * Parse a Stitch `code.html` body into the Mapper's role-annotated mapping
	 * (`{ pages: [ { title, slug, front_page, sections: [ { sectionClass, css_id, blocks:[…role] } ] } ] }`),
	 * which `FW_Site_Converter_Mapper::build_pages()` turns into a page-builder tree.
	 *
	 * @param string $html
	 * @param string $title page title
	 * @param string $slug  page slug ('' → derived)
	 * @param bool   $front front page?
	 * @return array mapping with exactly one page
	 */
	/** Parsed `<style>` rules that set max-width: [ { selector, value }, … ] — for non-Tailwind sources. */
	private static $mw_rules = array();

	/** Section skip flags — mirror the capture service's --skip-sections / --only-sections. 0-based
	 *  s_index (the section number shown in the conversion report). Set by the Convert handler. */
	public static $skip_sections = array();
	public static $only_sections = array();

	/**
	 * STRUCTURAL-DROP LOG — the coverage instrument. Every content node the recognizer walker did NOT
	 * claim (and whose subtree produced no blocks) is recorded here as { tag, class, kind, text }, where
	 * kind is 'salvaged-text' / 'salvaged-image' (rescued by the safety net) or 'decorative' (no content,
	 * intentionally not emitted). Surfaced as conversion-drops.json so each conversion tells us EXACTLY
	 * what pattern to teach the converter next, ranked by frequency — instead of finding gaps by hand.
	 * Reset at the start of every html_to_mapping().
	 */
	public static $drop_log = array();

	/** Read + reset the accumulated drop log (called once the page tree is built). */
	public static function get_drop_log() { return self::$drop_log; }

	/** Collect `selector { … max-width:VAL … }` rules from the source's <style> blocks. */
	private static function parse_style_max_width( $html ) {
		$out = array();
		if ( ! preg_match_all( '/<style[^>]*>(.*?)<\/style>/is', (string) $html, $sm ) ) { return $out; }
		$css = implode( "\n", $sm[1] );
		$css = preg_replace( '#/\*.*?\*/#s', '', $css ); // strip comments
		if ( preg_match_all( '/([^{}]+)\{([^{}]*)\}/s', $css, $rm, PREG_SET_ORDER ) ) {
			foreach ( $rm as $r ) {
				if ( ! preg_match( '/(?:^|;|\s)max-width\s*:\s*([0-9.]+(?:px|rem|em|%|ch|vw))/i', $r[2], $mw ) ) { continue; }
				foreach ( explode( ',', $r[1] ) as $sel ) {
					$sel = trim( $sel );
					if ( $sel !== '' && strpos( $sel, '@' ) === false ) { $out[] = array( 'selector' => $sel, 'value' => $mw[1] ); }
				}
			}
		}
		return $out;
	}

	/** Tailwind named max-w-* → its CSS length (so max-w-2xl etc. resolve like an arbitrary value). */
	private static function tw_max_w_named( $name ) {
		static $scale = array( 'xs' => '20rem', 'sm' => '24rem', 'md' => '28rem', 'lg' => '32rem', 'xl' => '36rem', '2xl' => '42rem', '3xl' => '48rem', '4xl' => '56rem', '5xl' => '64rem', '6xl' => '72rem', '7xl' => '80rem', 'prose' => '65ch' );
		return isset( $scale[ $name ] ) ? $scale[ $name ] : '';
	}

	/**
	 * The max-width applied to an element, from ANY source (not just a Tailwind class): an inline
	 * `style="max-width:…"`, a Tailwind `max-w-[…]` / `max-w-2xl`, or a matching `<style>` rule. Returns
	 * a CSS length ("620px", "42rem") or '' when none.
	 *
	 * @param DOMElement $el
	 */
	private static function element_max_width( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		// 1. Inline style.
		$style = $el->getAttribute( 'style' );
		if ( $style !== '' && preg_match( '/(?:^|;|\s)max-width\s*:\s*([0-9.]+(?:px|rem|em|%|ch|vw))/i', $style, $m ) ) { return $m[1]; }
		// 2. Tailwind class (arbitrary, then named).
		$cls = self::cls( $el );
		if ( preg_match( '/(?:^|\s)max-w-\[(\d+(?:\.\d+)?(?:px|rem|em|%|ch|vw))\]/', $cls, $m ) ) { return $m[1]; }
		if ( preg_match( '/(?:^|\s)max-w-([a-z0-9]+)(?:\s|$)/', $cls, $m ) ) { $v = self::tw_max_w_named( $m[1] ); if ( $v !== '' ) { return $v; } }
		// 3. The captured computed value, else the sheet's own declaration read with the cascade (a '.slider-head p{max-width:
		//    400px}' descendant rule) — BEFORE the legacy rightmost-compound scan, which matched any 'X p{max-width}' rule.
		$v = self::css_or_decl( $el, 'max-width' );
		if ( preg_match( '/^[0-9.]+(?:px|rem|em|%|ch|vw)$/i', $v ) ) { return $v; }
		// 4. A <style> rule whose rightmost compound matches this element (legacy fallback).
		foreach ( self::$mw_rules as $rule ) {
			if ( self::selector_matches_el( (string) $rule['selector'], $el, $cls ) ) { return (string) $rule['value']; }
		}
		return '';
	}

	/** Does a CSS selector's RIGHTMOST compound (tag / .class / #id) match this element? (No ancestors.) */
	private static function selector_matches_el( $selector, $el, $cls ) {
		$parts = preg_split( '/\s*[>+~]\s*|\s+/', trim( $selector ) );
		$last  = end( $parts );
		if ( $last === '' || strpos( $last, ':' ) !== false ) { return false; } // skip pseudo-classes
		$classes = array_filter( preg_split( '/\s+/', strtolower( (string) $cls ) ) );
		$id      = $el->getAttribute( 'id' );
		$tag     = strtolower( $el->tagName );
		if ( ! preg_match_all( '/[.#]?[\w-]+/', $last, $tok ) ) { return false; }
		foreach ( $tok[0] as $t ) {
			if ( $t[0] === '.' ) { if ( ! in_array( strtolower( substr( $t, 1 ) ), $classes, true ) ) { return false; } }
			elseif ( $t[0] === '#' ) { if ( $id !== substr( $t, 1 ) ) { return false; } }
			else { if ( $t !== '*' && $tag !== strtolower( $t ) ) { return false; } }
		}
		return true;
	}

	public static function html_to_mapping( $html, $title = 'Home', $slug = '', $front = true ) {
		$rules = self::rules_get();
		$dom   = self::load_dom( (string) $html );
		$sections = array();
		$main_cls = '';
		$main_cs  = '';
		// Parse any `<style>` rules that set max-width (a non-Tailwind source may set it in CSS, not a
		// class) so element_max_width() can match an element against them.
		self::$mw_rules = self::parse_style_max_width( (string) $html );
		// Stash the raw HTML so per-node effect readers (media_shape_css → bg_video_effect_css) can reach the
		// source <style> sheet — a framed clip's mask/mix-blend often lives in a custom class rule (`.radial-portal`),
		// not in the curated data-sc-cs. Overwritten on each conversion (never read outside one).
		self::$cur_html = (string) $html;

		if ( $dom ) {
			$body = $dom->getElementsByTagName( 'body' )->item( 0 );
			// PRE-PASS: de-animate word/char SPLIT-TEXT. AI/animation builders shatter a heading or eyebrow into
			// per-word <span>s (AI-page `.breeze-word`; GSAP/Framer SplitText `.word`/`.char`) so each word can be
			// tweened. To the converter those inline-block spans read as SEPARATE blocks and stack vertically (or
			// lose the inter-word spacing). Unwrap them back to plain text so the line is one heading/overline again;
			// the whitespace + separator glyphs between the spans are already text nodes, so they survive intact.
			if ( $body instanceof DOMElement ) { self::collapse_word_split_spans( $dom, $body ); }
			$roots = $body ? self::section_roots( $body ) : array();
			// The masthead nav is now CHROME (header_main). When it's a bare <nav> wrapped INSIDE a body
			// section (React/Next apps nest the nav in <main>/<section>), it would ALSO be collected as that
			// section's content — a DUPLICATE nav rendered mid-hero. It's claimed as the header, so remove it
			// from the DOM before block collection so it renders only once, as the header. (P1 follow-up.)
			$mh = self::header_root( $dom );
			$overlay_px = 0;
			$inflow_hdr_clear = false; // source reserved first-section top padding to clear an OUT-OF-FLOW SOLID header we render IN-FLOW
			if ( $mh instanceof DOMElement ) {
				// OVERLAY HEADER: a fixed/absolute (usually transparent) masthead sits ON TOP of the hero, so the
				// hero content must clear it — otherwise the heading renders UNDER the nav (the 'hero top spacing'
				// bug). Carry the header height as the hero's top padding.
				$hcls = ' ' . self::cls( $mh ) . ' ';
				$hcs  = (string) $mh->getAttribute( 'data-sc-cs' );
				if ( strpos( $hcls, ' fixed ' ) !== false || strpos( $hcls, ' absolute ' ) !== false || preg_match( '/position:\s*(?:fixed|absolute)/i', $hcs ) ) {
					$hpx = preg_match( '/(?:^|;)\s*height:\s*([\d.]+)px/i', $hcs, $hm ) ? (float) $hm[1] : 0;
					$overlay_px = $hpx > 0 ? (int) round( $hpx ) : 80;
				}
				// SOLID FIXED CHROME (the the burger source pattern): the semantic <header> is often class-less while its
				// BARS (a `fixed top-0` ticker + a `fixed top-12` nav) are the position:fixed, TOP-pinned, OPAQUE
				// elements. Being out of flow, the source reserves top padding on the FIRST section to clear them.
				// We reproduce that chrome as an IN-FLOW static/sticky header (it occupies its own height), so the
				// reserved clearance becomes a redundant white gap between header and hero. Detect a solid top-pinned
				// fixed bar → flag the first section to DROP that clearance. A TRANSPARENT overlay nav is excluded:
				// it is reproduced as an overlay header that genuinely needs the clearance (kept via heroTopPad).
				$fx = self::fixed_top_chrome( $mh );
				if ( ! empty( $fx['found'] ) && ! empty( $fx['solid'] ) ) {
					$inflow_hdr_clear = true;
					$overlay_px       = 0; // header is in-flow — do NOT also add an overlay hero offset
				}
				// The masthead nav is chrome — remove it from the body so it isn't ALSO a body band (dup nav).
				if ( 'nav' === strtolower( $mh->nodeName ) && $mh->parentNode instanceof DOMElement ) {
					$mh->parentNode->removeChild( $mh );
				}
			}
			// Section skip flags (parity with the capture service): drop skipped body bands / keep only
			// the chosen ones, by 0-based position (= the s_index in the conversion report), so a
			// re-convert preserves the bands already accepted.
			if ( $roots && ( self::$skip_sections || self::$only_sections ) ) {
				$kept = array();
				foreach ( $roots as $ri => $node ) {
					if ( self::$only_sections ) {
						if ( in_array( $ri, self::$only_sections, true ) ) { $kept[] = $node; }
					} elseif ( ! in_array( $ri, self::$skip_sections, true ) ) {
						$kept[] = $node;
					}
				}
				$roots = $kept;
			}
			$main_top_pad = 0.0; // the source <main>'s OWN top padding utility (`pt-48`) — the mapper carries it to #main, so it is clearance the first band already has
			if ( $body ) { foreach ( $body->getElementsByTagName( 'main' ) as $mm ) { $main_cls = self::cls( $mm ); $main_cs = (string) $mm->getAttribute( 'data-sc-cs' ); if ( preg_match( '/(?:^|\s)p[ty]-(?:\d{1,3}|\[[0-9.]+px\])(?:\s|$)/', ' ' . $main_cls . ' ' ) ) { $main_top_pad = self::sc_pad_top_px( $mm ); } break; } }
			// PAGE-LEVEL fixed backdrop <video> (a body-level sibling of the content, behind the hero) →
			// the FIRST section's background video. Detected + removed from the DOM here so it isn't left
			// as an orphan layer; attached to $sections[0] after the loop (mapper → apply_bg_video).
			$page_bg_video = $body ? self::detect_page_bg_video( $body, $roots ) : array();
			$idx = 0;
			foreach ( $roots as $node ) {
				$blocks = array();
				// HERO full-bleed background <img> → the section's Background image. Detect it FIRST and REMOVE
				// it from the DOM before collecting blocks, so the same photo is never ALSO emitted as a content
				// media_image (the duplicate). The detected value is reused for sectionBgImage below.
				$section_bg = self::section_bg_image( $node );
				if ( $section_bg && ! empty( $section_bg['src'] ) ) {
					foreach ( iterator_to_array( $node->getElementsByTagName( 'img' ) ) as $bimg ) {
						$isrc = trim( (string) $bimg->getAttribute( 'src' ) );
						if ( $isrc === '' ) { $isrc = trim( (string) $bimg->getAttribute( 'data-src' ) ); }
						if ( $isrc !== '' && $isrc === $section_bg['src'] && $bimg->parentNode instanceof DOMElement ) {
							$bimg->parentNode->removeChild( $bimg );
							break;
						}
					}
				}
				// HERO full-bleed background <video> inside an `absolute inset-0` layer → the section's
				// Background video. Detect + REMOVE it before collecting blocks (the empty positioned layer
				// would otherwise be dropped as decor, losing the video entirely — the-seed, biophilic,
				// colosseum, nox-liquid all shipped their hero with no backdrop).
				$section_bg_video = self::detect_section_bg_video( $node, (string) $html );
				// A section root that is ITSELF a desktop row (a `flex flex-col lg:flex-row` hero, a
				// `grid lg:grid-cols-2` band) must be split into COLUMNS here. collect_blocks() only ever
				// tests a node's CHILDREN against the recognizers, so the root's own row-ness was never
				// examined and its cells were emitted as full-width stacked blocks — a text|image hero
				// rendered as a text block with the photo full-bleed underneath at natural size.
				$root_row = self::section_root_row( $node, $rules );
				if ( is_array( $root_row ) ) { $rd = $root_row['rootDecor'] ?? array(); unset( $root_row['rootDecor'] ); $blocks[] = $root_row; foreach ( (array) $rd as $rdb ) { $blocks[] = $rdb; } }
				else { self::collect_blocks( $node, $blocks, $rules ); }
				$blocks = array_values( array_filter( $blocks ) );
				if ( ! $blocks ) { continue; }
				// NOTE on fidelity / verbatim sections: the capture-service (JS) path keeps media-bearing
				// sections VERBATIM because it CARRIES the page's real used CSS, so the source markup
				// renders pixel-faithfully. This upload path instead REPRODUCES Tailwind offline (under
				// .sc-tw), which is incomplete (missing h-*/object-fit/aspect/arbitrary values), so a
				// whole-section verbatim would render wrong (giant un-sized images, ballooned height).
				// Here, DECOMPOSING into shortcodes (which render reliably without the reproducer) is the
				// safer choice — so we deliberately do NOT mirror the JS `preferVerbatim` guard. The
				// existing per-element recognizers (image_overlay / logo_strip) cover the critical media.
				// For high-fidelity design-heavy conversions, the capture service is the recommended path.
				// Section centered (flex items-center / text-center) → center its heading/text/buttons.
				$align = self::section_center( $node ) ? 'center' : '';
				if ( $align === 'center' ) {
					// Carry the band's centering to ALL text-bearing blocks — headings, the sub-text
					// paragraph AND the button row — so a centered source band renders fully centered
					// (previously only the heading family was centered, leaving the subtext left-aligned).
					foreach ( $blocks as &$bk ) {
						if ( in_array( $bk['role'] ?? '', array( 'title', 'heading', 'overline', 'subtitle', 'badge', 'text', 'button' ), true ) && empty( $bk['align'] ) ) {
							$bk['align'] = 'center';
						}
					}
					unset( $bk );
				}
				$sections[] = array(
					'sectionClass' => '',
					'sectionRawClass' => self::cls( $node ), // the section's RAW classes (mt/mb/py …) → vertical-spacing carry, without polluting css_class
					'sectionCs'    => (string) $node->getAttribute( 'data-sc-cs' ), // the section's COMPUTED style → faithful full-width band background (mapper reproduces bg the class parse misses)
					'sectionCsSm'  => (string) $node->getAttribute( 'data-sc-cs-sm' ), // the PHONE-pass diff (capture >= 1.10.96: padding / margin at 390px when they differ) → Pass #5 base tier
					'sectionCsMd'  => (string) $node->getAttribute( 'data-sc-cs-md' ), // the TABLET-pass diff (capture >= 1.10.97: 820px) → Pass #5 md tier
					'sectionCsXl'  => (string) $node->getAttribute( 'data-sc-cs-xl' ), // the WIDE-pass diff (capture >= 1.10.99: 1920px → the >= 1536px tier) → Pass #5 min-width:1536px rule
					'bandPlace'    => self::band_placement_of( $node ), // a grid-canvas band's column placement { frac, x, w } (stamp_band_placement) → the mapper keeps it at its column
					'phonePass'    => (bool) preg_match( '/<html\b[^>]*\bdata-sc-phone-pass\s*=\s*["\']?1/i', (string) $html ), // the capture measured 390px too → "no diff" means "same as desktop" (no clamp)
					'sectionLayers' => self::section_layers( $node ), // direct-child "full-bleed" layers (class/style/computed) → mapper hoists a solid band fill that lives on an INNER layer, not the section root
					'sectionBgImage' => $section_bg, // a HERO full-bleed background <img> → the section's Background image (detected + removed from content above)
					'sectionBgVideo' => $section_bg_video, // a HERO full-bleed background <video> in an inset-0 layer → the section's Background video (detected + removed above)
					// TWO levels of width: the section's OUTER container (~1400, incl. the hero which has NO inner
					// grid cap) → the section's own container_width; and the GRID band cap (a max-w-5xl/6xl card
					// grid = 1024/1152) → pushed onto that band's flexbox content_width so it stays narrower than
					// the container. The mapper falls back to the container when a section has no narrower band.
					'sectionContainerW' => self::section_container_width_pref( $node ), // OUTER container (full-bleed hero → 100%; else mapped cap)
					'sectionFullBleed' => self::is_fullbleed_split_hero( $node ), // full-viewport multicol hero → is_fullwidth (span the viewport, not the global container)
					'sectionHeroHeight' => self::fullbleed_hero_height( $node ), // min-h-screen/100vh → section min_height (else the tall hero collapses to content height)
					'sectionValign'     => self::fullbleed_hero_valign( $node ), // column `justify-center` (flex-col) → column_valign:center (else content top-aligns)
					'sectionBandW'      => self::map_container_width( self::section_content_max_width( $node, 1300.0 ) ), // inner GRID band cap
					'sectionLeftCap'    => self::section_left_cap( $node ), // a left-anchored root cap → a left-aligned content width on the band's flexbox

					'css_id'       => self::section_id( $node, $idx ),
					'sectionId'    => ( $node instanceof DOMElement && $node->hasAttribute( 'id' ) ) ? self::slug_from_id( $node->getAttribute( 'id' ) ) : '', // raw source id (anchor target) → Mapper::auto_id fallback agrees with section_id()
					// Overlay-header offset for the FIRST section: the detected masthead height, OR — when the
					// header's position/height wasn't captured (a hand-authored source often omits them) — the
					// hero's OWN top clearance (`.hero-top{padding-top:107px}`), which wrapper-flattening drops,
					// leaving the hero riding under the nav. Carry whichever is larger so the hero clears the header.
					// (…but when the source <main> itself pads the page top past the overlay (`<main class="pt-48">` under a
					// 92px fixed nav) that padding — carried to #main — IS the clearance: adding the header height again
					// pushed the first band 92px down — a real-site audit)
					'heroTopPad'   => ( 0 === $idx && ! $inflow_hdr_clear && $main_top_pad < (float) $overlay_px ) ? max( (int) $overlay_px, ( $mh instanceof DOMElement ? self::hero_top_clearance( $node ) : 0 ) ) : 0,
					'heroInFlowClear' => ( 0 === $idx && $inflow_hdr_clear ), // drop the first section's redundant fixed-header clearance (in-flow static header supplies that height)
					'omit'         => false,
					'verbatim'     => false,
					'align'        => $align,
					'bgPattern'    => self::detect_section_pattern( $node ), // decorative SVG/gradient tile → mapper overlay
					'bgEffects'    => self::detect_section_bg_effects( $node ), // named ambient particle layers (leaves/petals/grain…) → stacked bg_effect slots
					'divider'      => self::detect_section_divider( $node ), // edge shape divider (wave/tilt/…) → native section divider option
					'blocks'       => $blocks,
				);
				$idx++;
			}
			// A FLOATING DOCK — a page-level `position:fixed` pill of icon links anchored to the bottom (a four-icon glass dock at
			// bottom:24px, left:50%, translated back by half its width) → ONE fixed-positioned row of icon tiles, appended to the
			// first section (a single page-level element; its fixed position lifts it out of flow). It was dropped: fixed body-level
			// elements are neither sections nor chrome (measured on a real conversion).
			if ( $sections && $body instanceof DOMElement ) {
				$dock = self::detect_floating_dock( $body );
				if ( $dock ) { $sections[0]['blocks'][] = $dock; }
			}
			if ( ! empty( $page_bg_video ) && $sections ) {
				if ( ! empty( $page_bg_video['floating'] ) ) {
					// A fixed FLOATING video portal → a fixed-positioned media_video CONTENT block. Prepended to
					// the first section's blocks; its `position:fixed` Custom CSS lifts it out of flow, so it
					// renders at the source portal's exact place/size behind/over the scrolling content without
					// consuming section layout. Rendered once (a single page-level element).
					array_unshift( $sections[0]['blocks'], $page_bg_video );
				} elseif ( empty( $sections[0]['sectionBgVideo'] ) ) {
					$sections[0]['sectionBgVideo'] = $page_bg_video;
				}
			}
		}

		return array(
			'include_animations' => false,
			'pages' => array(
				array(
					'title'      => (string) $title,
					'slug'       => (string) $slug,
					'front_page' => (bool) $front,
					'sections'   => $sections,
					'mainClass'  => $main_cls, // the source <main>'s padding (pt-32 …) → carried onto #main
					'mainCs'     => $main_cs,  // the source <main>'s computed style (max-width / padding) → #main container
					// CHROME PRESENCE — a source with no <footer> (its last band carries the brand line itself) must not grow a
					// theme footer; same for a header-less landing. The page importer flips the native per-page Hide switches.
					'chrome'     => self::source_chrome( (string) $html ),
				),
			),
		);
	}

	/**
	 * The top-level "section" nodes to convert: every <section>. The <header> AND <footer> are site
	 * CHROME — reproduced by the generated child theme (header/footer template parts + the menus from
	 * the design-config), NOT page content — so they are deliberately excluded here. (Putting the
	 * footer in the page body duplicated it with the theme footer and looked wrong inside the builder.)
	 *
	 * @param DOMElement $body
	 * @return DOMElement[]
	 */
	/**
	 * Does this section center its content? True when the section root (or an immediate content wrapper)
	 * uses `text-center` or `flex … items-center` — the source's way of centering a hero / centered band.
	 *
	 * @param DOMElement $node
	 */
	private static function section_center( $node ) {
		$c = self::cls( $node );
		if ( strpos( $c, 'text-center' ) !== false ) { return true; }
		// `items-center` is HORIZONTAL centering only on a flex-COLUMN (its cross axis). On a flex-ROW (the
		// default) it is VERTICAL centering — e.g. a `min-h-screen flex items-center` hero band that vertically
		// centers its two-column grid — which must NOT be read as a centered/text-center band (that was
		// wrongly centering left-aligned heroes). So require `flex-col` for items-center to count.
		// …and only when the column is STILL a column at desktop: `flex flex-col lg:flex-row items-center` is a row at 1440 (the
		// stamp says flex-direction:row) and its items-center is vertical — it centred a left-aligned hero (a fixture from the feed)
		$col_at_desktop = function ( $el ) { $cs = (string) $el->getAttribute( 'data-sc-cs' ); return ! preg_match( '/(?:^|;)\s*flex-direction:\s*row/i', $cs ); };
		if ( strpos( $c, 'items-center' ) !== false && strpos( $c, 'flex-col' ) !== false && $col_at_desktop( $node ) ) { return true; }
		// COMPUTED text-align:center on the section root (data-sc-cs) — a source that centres its band via
		// CSS rather than a `text-center` class. Guard against the inherited `text-align:start` default.
		if ( $node instanceof DOMElement && preg_match( '/text-align:\s*center/i', (string) $node->getAttribute( 'data-sc-cs' ) ) ) { return true; }
		// one level down (a content wrapper inside the section) — class OR computed text-align:center
		foreach ( $node->childNodes as $ch ) {
			if ( $ch->nodeType !== XML_ELEMENT_NODE ) { continue; }
			$cc = self::cls( $ch );
			if ( strpos( $cc, 'text-center' ) !== false || ( strpos( $cc, 'items-center' ) !== false && strpos( $cc, 'flex-col' ) !== false && $col_at_desktop( $ch ) ) ) { return true; }
			// (a computed centre counts only on a WRAPPER that holds children — a <button> centres its own label by UA default,
			// a lone centred leaf centres itself; neither centres the band)
			if ( $ch instanceof DOMElement && ! in_array( strtolower( $ch->tagName ), array( 'button', 'a', 'input', 'select', 'textarea' ), true ) && $ch->getElementsByTagName( '*' )->length > 0 && preg_match( '/text-align:\s*center/i', (string) $ch->getAttribute( 'data-sc-cs' ) ) ) { return true; }
		}
		return false;
	}

	/**
	 * A grouping wrapper's OWN explicit horizontal text-alignment → 'center' | 'right' | '' (left/inherit).
	 * Reads a Tailwind `text-center`/`text-right`/`text-left` class first, else the computed `text-align`
	 * from data-sc-cs. 'left'/'start'/'justify' → '' (the inherited default; nothing to force). Used to
	 * propagate an intermediate wrapper's alignment onto the blocks it flattens (#1).
	 */
	private static function wrapper_align( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$c = ' ' . self::cls( $el ) . ' ';
		if ( strpos( $c, ' text-center ' ) !== false ) { return 'center'; }
		if ( strpos( $c, ' text-right ' ) !== false )  { return 'right'; }
		if ( strpos( $c, ' text-left ' ) !== false )   { return ''; } // explicit left = inherited default.
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/text-align:\s*(center|right)\b/i', $cs, $m ) ) { return strtolower( $m[1] ); }
		return '';
	}

	/**
	 * A grouping wrapper's constrained measure when it is a CENTERED constrained box (`max-w-* mx-auto`),
	 * returned as e.g. '42rem' / '640px' — else ''. Only a centered box (mx-auto) qualifies, so a plain
	 * left column's max-width isn't mistaken for a heading measure. Tailwind max-w-* → rem, arbitrary
	 * max-w-[Npx] → the literal length. Used to carry a heading intro's width onto its block (#1).
	 */
	/** Stamp a wrapper / element content cap onto a WIDGET block (a columns row, an accordion, a list, a table, tabs, steps,
	 *  a timeline, pricing, a gallery, testimonials, a logo strip, a panel): `capW` (a CSS length) + `capCenter`. A block that
	 *  already carries a narrower cap keeps it; leaf text / headings have their own measures (maxWidth / wrapMaxW). */
	private static function stamp_cap( array &$b, $w, $centered ) {
		$t = (string) ( $b['t'] ?? '' ); $role = (string) ( $b['role'] ?? '' );
		$widget = in_array( $t, array( 'accordion', 'feature_list', 'table', 'tabs', 'steps', 'timeline', 'pricing', 'gallery', 'testimonials', 'logo_grid', 'panel', 'stack', 'contact_form', 'newsletter', 'progress', 'image_grid', 'icon_grid' ), true ) || ( 'row' === $t && 'columns' === $role );
		if ( ! $widget || ! empty( $b['capW'] ) ) { return; }
		// a PAGE container's width (`max-w-[1600px] px-12`, `max-w-screen-2xl`) is the section's content width, never a content
		// cap — stamping it overrode the theme's gutters (`min(1504px, 100% - 32px)`) and a 4-up product row ran edge to edge
		$wpx = preg_match( '/^([0-9.]+)(px|rem)$/', trim( (string) $w ), $wm ) ? ( 'rem' === $wm[2] ? (float) $wm[1] * 16 : (float) $wm[1] ) : 0.0;
		if ( $wpx >= 1400 ) { return; }
		$b['capW'] = (string) $w; $b['capCenter'] = (bool) $centered;
	}

	/** Whether a capped wrapper is horizontally CENTERED (`mx-auto`, or symmetric non-zero computed side margins). */
	private static function wrapper_centered( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$c = ' ' . self::cls( $el ) . ' ';
		if ( preg_match( '/\smx-auto\s/', $c ) ) { return true; }
		$m = self::el_margin( $el );
		$l = (float) ( $m['left'] ?? 0 ); $r = (float) ( $m['right'] ?? 0 );
		return $l > 0 && abs( $l - $r ) <= 2;
	}

	private static function wrapper_maxw( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$c = ' ' . self::cls( $el ) . ' ';
		// A LEFT-aligned capped wrapper (`max-w-4xl` with no mx-auto, or a computed max-width) caps its heading just
		// the same — the measure decides where the title wraps. (Was: centered boxes only, so a left cap was dropped
		// and the title ran the full section width on one line.)
		$cmw = trim( (string) self::sc_css( $el, 'max-width' ) );
		if ( preg_match( '/^([0-9.]+)px$/', $cmw, $cm ) && (float) $cm[1] >= 320 && (float) $cm[1] <= 1600 && count( self::el_children( $el ) ) >= 1 ) { return $cmw; }
		static $tw = array( 'sm' => '24rem', 'md' => '28rem', 'lg' => '32rem', 'xl' => '36rem', '2xl' => '42rem', '3xl' => '48rem', '4xl' => '56rem', '5xl' => '64rem', '6xl' => '72rem', '7xl' => '80rem' );
		if ( preg_match( '/\bmax-w-\[(\d*\.?\d+(?:px|rem|em|%|vw|ch))\]/', $c, $m ) ) { return $m[1]; }
		if ( preg_match( '/\bmax-w-(sm|md|lg|xl|[2-7]xl)\b/', $c, $m ) && isset( $tw[ $m[1] ] ) ) { return $tw[ $m[1] ]; }
		return '';
	}

	/**
	 * Direct-child "full-bleed layer" candidates of a section — the absolutely-positioned inset-0 /
	 * w-full h-full overlays (and the section's immediate wrapper child). AI page builders paint a
	 * section's solid band colour on such an inner layer, NOT on the section root, so the root's own
	 * computed background reads transparent. The mapper inspects these to HOIST the dominant solid
	 * fill to the section element (skipping decorative gradient/opacity overlays). We pass the raw
	 * class + inline style + computed style for each; discrimination lives in the mapper.
	 *
	 * @param DOMElement $node
	 * @return array<int,array{cls:string,style:string,cs:string}>
	 */
	/**
	 * A HERO-style full-bleed BACKGROUND image behind a section: an <img> inside a `absolute inset-0`
	 * layer that covers the band (`object-cover`), with real content (heading/text) in a sibling layer.
	 * Returns { src, hero, valign } — `hero` true when the section is viewport-tall (`h-screen` /
	 * `min-h-screen` / `h-[100svh]`), `valign` from the content layer's flex justify (bottom/middle) — or
	 * array() when there's no such background. Without this the bg photo is mis-mapped as a tiny inline
	 * media_image and the overlaid (usually white) heading sits on a blank band, invisible.
	 *
	 * @param DOMElement $node
	 * @return array
	 */
	/**
	 * PAGE-LEVEL fixed/absolute full-bleed background VIDEO hoist. Some hand-authored sources pin a
	 * `position:fixed` (or `absolute inset-0`) <video> as a SIBLING of the content — a page-wide backdrop
	 * that shows behind the hero (national-geographic's oval portal reel, the automotive car loop, the
	 * payment-operations backdrop). Because it lives OUTSIDE every <section>, the per-section video-bg
	 * recognizer never sees it and the hero shipped with no background. Detect that page-level backdrop,
	 * pull its <source>/poster/scrim, REMOVE it from the DOM, and return a bg-video descriptor to wire
	 * onto the FIRST section's Background → Video (apply_bg_video). Videos only (the concrete pattern);
	 * returns array() when none.
	 *
	 * @param DOMElement   $body
	 * @param DOMElement[] $roots
	 * @return array
	 */
	/**
	 * Read a set of CSS properties for an element from BOTH its captured `data-sc-cs` AND the source
	 * <style> sheet rules matching its id/classes (the geometry of a positioned element — top/right/width/
	 * height/transform/border-radius/mask — often lives in a custom class rule like `.video-portal`, not in
	 * the curated data-sc-cs). Nearest source wins per prop; `none`/empty are skipped. Returns { prop => val }.
	 */
	private static function el_style_props( $el, array $props ) {
		if ( ! ( $el instanceof DOMElement ) ) { return array(); }
		$bodies = array( (string) $el->getAttribute( 'data-sc-cs' ) );
		$sheet  = self::all_style_css( self::$cur_html );
		if ( '' !== $sheet ) {
			$sels = array();
			$id   = trim( (string) $el->getAttribute( 'id' ) );
			if ( '' !== $id ) { $sels[] = '#' . preg_quote( $id, '/' ); }
			foreach ( preg_split( '/\s+/', (string) self::cls( $el ) ) as $c ) { $c = trim( $c ); if ( '' !== $c ) { $sels[] = '\.' . preg_quote( $c, '/' ); } }
			if ( $sels ) {
				$re = '/(?:' . implode( '|', $sels ) . ')(?![\w-])[^{}]*\{([^}]*)\}/i';
				if ( preg_match_all( $re, $sheet, $mm ) ) { foreach ( $mm[1] as $b ) { $bodies[] = $b; } }
			}
		}
		$found = array();
		foreach ( $props as $p ) {
			foreach ( $bodies as $body ) {
				if ( preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . '\s*:\s*([^;]+)/i', $body, $m ) ) {
					$v = trim( $m[1] );
					if ( '' !== $v && 'none' !== strtolower( $v ) ) { $found[ $p ] = $v; break; }
				}
			}
		}
		return $found;
	}

	/**
	 * Is a fixed-position layer a FLOATING portal (positioned/sized panel — lumina-arctic's `.video-portal`:
	 * `top:50%; right:5%; width:clamp(…); height:clamp(…); border-radius; mask`) rather than a FULL-BLEED
	 * backdrop (inset-0 / w-full h-full / 100vw×100vh)? Returns [ floating(bool), scopedCss(string) ] where
	 * scopedCss is a `selector{position:fixed; …geometry… …shape…}` rule the mapper hands to `media_video`
	 * so a masked fixed video keeps its exact place/size/radius/mask instead of becoming a full-screen bg.
	 */
	private static function fixed_layer_geometry( $el ) {
		$g = self::el_style_props( $el, array(
			'position', 'top', 'right', 'bottom', 'left', 'transform', 'width', 'height', 'max-width',
			'border-radius', 'z-index', 'aspect-ratio', 'mask-image', '-webkit-mask-image', 'clip-path', 'filter',
		) );
		$has_offset = false;
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $o ) {
			if ( isset( $g[ $o ] ) && ! preg_match( '/^0(px|%|rem|em)?$/', trim( $g[ $o ] ) ) ) { $has_offset = true; }
		}
		$w = isset( $g['width'] ) ? $g['width'] : '';
		$h = isset( $g['height'] ) ? $g['height'] : '';
		$full_w = ( '' === $w || (bool) preg_match( '/\b100(%|vw)\b/', $w ) );
		$full_h = ( '' === $h || (bool) preg_match( '/\b100(%|vh)\b/', $h ) );
		$floating = $has_offset || ! $full_w || ! $full_h;
		// FRAMED PORTAL vs SOFT BACKDROP. A floating video is a case-B PORTAL only when it is a DEFINED CARD —
		// it carries a real `border-radius` (lumina-arctic's `.video-portal`: rounded 28px card, z-index:2). A
		// large, UNFRAMED, softly-masked decorative layer (autonomous-supply-chain's `.visual-breach`: 55vw×80vh,
		// z-index:0, pointer-events:none, radial fade, NO radius) is a background glow, not a portal — leave it on
		// the full-bleed section-bg path (where the hero reads as a media-hero) instead of pinning it as content.
		$framed = isset( $g['border-radius'] ) && ! preg_match( '/^0(px|%|rem|em)?(\s|$)/', trim( (string) $g['border-radius'] ) );
		if ( ! $floating || ! $framed ) { return array( false, '' ); }
		$decls = array( 'position:fixed' );
		foreach ( array( 'top', 'right', 'bottom', 'left', 'transform', 'width', 'height', 'max-width', 'z-index', 'aspect-ratio' ) as $p ) {
			if ( isset( $g[ $p ] ) ) { $decls[] = $p . ':' . $g[ $p ]; }
		}
		if ( isset( $g['border-radius'] ) ) { $decls[] = 'border-radius:' . $g['border-radius']; $decls[] = 'overflow:hidden'; }
		$mask = isset( $g['mask-image'] ) ? $g['mask-image'] : ( isset( $g['-webkit-mask-image'] ) ? $g['-webkit-mask-image'] : '' );
		if ( '' !== $mask ) { $decls[] = '-webkit-mask-image:' . $mask; $decls[] = 'mask-image:' . $mask; $decls[] = '-webkit-mask-repeat:no-repeat'; $decls[] = 'mask-repeat:no-repeat'; }
		if ( isset( $g['clip-path'] ) ) { $decls[] = 'clip-path:' . $g['clip-path']; }
		if ( isset( $g['filter'] ) )    { $decls[] = 'filter:' . $g['filter']; }
		return array( true, 'selector{' . implode( ';', $decls ) . ';}' );
	}

	private static function detect_page_bg_video( $body, array $roots ) {
		if ( ! ( $body instanceof DOMElement ) || ! $roots ) { return array(); }
		// Is $el a section root, INSIDE one, or a WRAPPER of one? Such an element is content, not a page bg.
		$part_of_section = function ( $el ) use ( $roots ) {
			foreach ( $roots as $r ) {
				if ( $el === $r ) { return true; }
				$p = $el->parentNode; while ( $p instanceof DOMElement ) { if ( $p === $r ) { return true; } $p = $p->parentNode; }
				$q = $r->parentNode;  while ( $q instanceof DOMElement ) { if ( $q === $el ) { return true; } $q = $q->parentNode; }
			}
			return false;
		};
		$best = null;
		foreach ( iterator_to_array( $body->getElementsByTagName( '*' ) ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			if ( $part_of_section( $el ) ) { continue; } // part of a section → the normal per-section path handles it
			$pos = self::sc_css( $el, 'position' );
			$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$is_fixed = ( 'fixed' === $pos || strpos( $cls, ' fixed ' ) !== false );
			$bleed    = ( strpos( $cls, 'inset-0' ) !== false || ( strpos( $cls, 'w-full' ) !== false && strpos( $cls, 'h-full' ) !== false ) );
			$is_abs_bleed = ( ( 'absolute' === $pos || strpos( $cls, ' absolute ' ) !== false ) && $bleed );
			if ( ! $is_fixed && ! $is_abs_bleed ) { continue; }
			// Must carry a <video> and be essentially text-free (a decorative backdrop, not a content band).
			if ( 0 === $el->getElementsByTagName( 'video' )->length && 'video' !== strtolower( $el->nodeName ) ) { continue; }
			if ( mb_strlen( trim( self::text( $el ) ) ) > 40 ) { continue; }
			$best = $el; break;
		}
		if ( null === $best ) { return array(); }
		$vid = ( 'video' === strtolower( $best->nodeName ) ) ? $best : $best->getElementsByTagName( 'video' )->item( 0 );
		if ( ! ( $vid instanceof DOMElement ) ) { return array(); }
		$src  = (string) $vid->getAttribute( 'src' );
		$webm = '';
		foreach ( $vid->getElementsByTagName( 'source' ) as $s ) {
			$ssrc = (string) $s->getAttribute( 'src' ); if ( '' === $ssrc ) { continue; }
			$stype = strtolower( (string) $s->getAttribute( 'type' ) );
			if ( '' === $webm && ( 'video/webm' === $stype || preg_match( '/\.webm(\?|$)/i', $ssrc ) ) ) { $webm = $ssrc; }
			if ( '' === $src  && ( 'video/mp4'  === $stype || preg_match( '/\.mp4(\?|$)/i',  $ssrc ) ) ) { $src  = $ssrc; }
		}
		if ( '' === $src && '' === $webm ) { return array(); }
		$poster = (string) $vid->getAttribute( 'poster' );
		// SCRIM: a gradient / semi-transparent full-bleed layer over the video → the section Background Overlay.
		$overlay = '';
		foreach ( $best->getElementsByTagName( '*' ) as $ov ) {
			if ( ! ( $ov instanceof DOMElement ) || $ov === $vid ) { continue; }
			$bgi = self::sc_css( $ov, 'background-image' );
			if ( '' !== $bgi && false !== stripos( $bgi, 'gradient' ) && false === stripos( $bgi, 'url(' ) ) { $overlay = $bgi; break; }
			$bgc = self::sc_css( $ov, 'background-color' );
			if ( '' !== $bgc && preg_match( '/rgba\([^)]*,\s*0?\.\d+\s*\)/i', $bgc ) ) { $overlay = $bgc; break; }
		}
		// No scrim ELEMENT → the tint may be a `::before` / `::after` pseudo-layer (`.hero::after{inset:0;
		// background:…}`), which the DOM never carries; the capture stamps it as data-sc-scrim on the band.
		if ( '' === $overlay ) { $overlay = self::pseudo_scrim_of( $best ); }
		// FLOATING FIXED PORTAL vs FULL-BLEED BACKDROP. A `position:fixed` video that is a POSITIONED, SIZED,
		// masked panel (lumina-arctic's `.video-portal`: right:5%, ~35vw×55vh, rounded, radial mask) is NOT a
		// full-screen background — promoting it to a 100vh section bg blows it up full-bleed and drops the
		// mask/geometry. Detect that shape and emit it as a fixed-positioned `media_video` CONTENT element that
		// keeps its exact place/size/radius/mask (scoped `position:fixed` Custom CSS) instead of a section bg.
		list( $is_floating, $float_css ) = self::fixed_layer_geometry( $best );
		// A full-viewport FIXED backdrop the whole page scrolls over is the SITE background's fixed video layer (Theme Settings →
		// General → Layout → Site Background; detect_page_fixed_video routes it there) — not the first section's background.
		// Attaching it here too painted the video twice (a scrolling section copy over the fixed one) and forced a hero height.
		// The layer is still removed from the DOM below so it never lands as an orphan band.
		// (a framed portal BEHIND the page — z-index < 0 — is the site backdrop even though it is sized and rounded: page_backdrop_layer_of
		// claims it; the floating-content path is for a portal that sits OVER the page)
		if ( ( ! $is_floating && self::el_is_page_fixed_layer( $vid ) ) || self::page_backdrop_layer_of( $vid ) ) {
			if ( $best->parentNode instanceof DOMElement ) { $best->parentNode->removeChild( $best ); }
			return array();
		}
		// Remove the page-level layer from the DOM (handled here, not left as an orphan band).
		if ( $best->parentNode instanceof DOMElement ) { $best->parentNode->removeChild( $best ); }
		if ( $is_floating && '' !== $float_css ) {
			return array(
				't' => 'video', 'role' => 'video', 'mode' => 'self_hosted', 'bg' => false, 'floating' => true,
				'src' => $src, 'webm' => $webm, 'poster' => $poster, 'cover' => true, 'card_css' => $float_css,
				'autoplay' => 'yes', 'muted' => 'yes', 'loop' => 'yes', 'controls' => 'no', 'playsinline' => 'yes',
			);
		}
		// The band the backdrop lands on decides the height: its own full-viewport signal (min-h-screen / min-h-[Nvh]) wins;
		// a band cut out of a segmented container (data-sc-band-of) is content-tall — its container's 120vh spanned EVERY
		// band, so forcing 100vh here pushed the next band 270px down. Only an un-segmented hero keeps the 100vh default.
		$first = ( isset( $roots[0] ) && $roots[0] instanceof DOMElement ) ? $roots[0] : null;
		$hh0 = $first ? self::fullbleed_hero_height( $first ) : '';
		if ( '' === $hh0 ) { $hh0 = ( $first && $first->hasAttribute( 'data-sc-band-of' ) ) ? 'auto' : '100vh'; }
		return array(
			't' => 'video', 'role' => 'video', 'mode' => 'self_hosted', 'bg' => true,
			'src' => $src, 'webm' => $webm, 'poster' => $poster, 'overlay' => $overlay,
			'valign' => 'middle', 'hero_height' => $hh0,
		);
	}

	/**
	 * SECTION-LEVEL full-bleed background VIDEO. A hero video that lives inside an `absolute/fixed inset-0`
	 * (or `w-full h-full`) layer WITHIN a section is a decorative backdrop — but that empty positioned layer
	 * gets dropped as decor before the per-element video recognizer ever runs, so the video vanished and the
	 * hero shipped with no background (the-seed, biophilic, colosseum, nox-liquid — bg_media misses). Detect
	 * the layer here, pull its <source>/poster/scrim, REMOVE it from the DOM, and return a bg-video descriptor
	 * for the section's Background → Video (mapper → apply_bg_video). Requires the background-video hallmarks
	 * (muted + autoplay) so a small inline clip isn't mistaken for a full-bleed backdrop. '' when none.
	 *
	 * @param DOMElement $node
	 * @return array
	 */
	/**
	 * Is this element a MULTI-COLUMN CSS GRID (≥2 columns)? Reads the DESKTOP track count from either the
	 * computed `grid-template-columns` (now captured — a resolved N-track list or `repeat(N,…)`) OR the
	 * Tailwind `grid-cols-N` / responsive `lg:grid-cols-N` class. This is the deterministic "read the section's
	 * real layout structure" primitive — a section whose children lay out as 2+ grid columns.
	 */
	private static function section_is_multicol_grid( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		foreach ( array( '2xl', 'xl', 'lg', 'md', 'sm' ) as $bp ) {
			if ( preg_match( '/\b' . $bp . ':grid-cols-([2-9])\b/', $cls ) ) { return true; }
		}
		if ( preg_match( '/(?:^|\s)grid-cols-([2-9])\b/', $cls ) ) { return true; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( '' !== $cs && stripos( $cs, 'display:grid' ) !== false ) {
			if ( preg_match( '/grid-template-columns:\s*repeat\(\s*([2-9])/i', $cs ) ) { return true; }
			if ( preg_match( '/grid-template-columns:\s*([^;]+)/i', $cs, $m ) && stripos( $m[1], 'none' ) === false ) {
				$tc = 0; foreach ( preg_split( '/\s+/', trim( $m[1] ) ) as $t ) { if ( '' !== $t && 'none' !== $t ) { $tc++; } }
				if ( $tc >= 2 ) { return true; }
			}
		}
		return false;
	}

	/**
	 * Classify an element's OWN layout role — the deterministic "is this child a grid, a flexbox, a
	 * block, or a leaf?" primitive the structure detector asks at each node. Reads the CAPTURED computed
	 * `display` / `grid-template-columns` / `flex-direction` FIRST (authoritative — it survives whatever
	 * class soup produced it), then falls back to Tailwind class tokens (`grid`, `grid-cols-N`, `flex`,
	 * `flex-col`, responsive `md:flex-row`). Returns one of:
	 *   'leaf'      — no element children (a content atom / text terminal → hand to the recognizers)
	 *   'grid'      — a ≥2-track CSS grid (a regular row of cells)
	 *   'flex-row'  — a horizontal flex container (desktop row)
	 *   'flex-col'  — a vertical flex stack
	 *   'block'     — a plain block container (no flex/grid)
	 * `$meta` (by-ref) carries extra signal for the caller: cols (int track/child count), regular (bool —
	 * a grid with template-areas / spans / dense auto-flow is IRREGULAR and must NOT be forced into a 1-D
	 * row), gap (px). This is a pure read — it changes nothing; callers decide what structure to emit.
	 */
	private static function classify_display( $el, &$meta = null ) {
		$meta = array( 'cols' => 0, 'regular' => true, 'gap' => 0 );
		if ( ! ( $el instanceof DOMElement ) ) { return 'leaf'; }
		$kids = self::el_children( $el );
		if ( count( $kids ) === 0 ) { return 'leaf'; }

		$cls  = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$cs   = (string) $el->getAttribute( 'data-sc-cs' );
		$disp = strtolower( trim( (string) self::sc_css( $el, 'display' ) ) );

		// GRID — computed display:grid (authoritative) OR a Tailwind grid / grid-cols-N class.
		$is_grid = ( 'grid' === $disp || 'inline-grid' === $disp )
			|| ( '' === $disp && preg_match( '/(?:^|\s)grid(?:\s|$)/', $cls ) )
			|| self::section_is_multicol_grid( $el );
		if ( $is_grid ) {
			$gc = self::grid_col_count( $el );
			$meta['cols']    = $gc >= 2 ? $gc : count( $kids );
			$meta['gap']     = self::grid_gap_px( $el );
			// IRREGULAR grid → not a clean row of cells: template-areas, an explicit multi-cell span
			// (`col-span-[2-9]` / computed `grid-column: span N`), or dense auto-flow. The caller must
			// route these to the collage recognizer / verbatim, never to an even N-column row.
			$meta['regular'] = ! ( preg_match( '/grid-template-areas\s*:/i', $cs )
				|| preg_match( '/grid-auto-flow\s*:[^;]*dense/i', $cs )
				|| preg_match( '/(?:^|\s)(?:(?:sm|md|lg|xl|2xl):)?col-span-([2-9])\b/', $cls )
				|| preg_match( '/grid-column\s*:[^;]*span\s*([2-9])/i', $cs ) );
			return 'grid';
		}

		// FLEX — computed display:flex (authoritative) OR a Tailwind flex token (whole class, not the
		// substring inside `flex-col`/`flex-wrap`).
		$is_flex = ( 'flex' === $disp || 'inline-flex' === $disp )
			|| (bool) preg_match( '/(?:^|\s)(?:inline-)?flex(?:\s|$)/', $cls );
		if ( $is_flex ) {
			$dir      = strtolower( trim( (string) self::sc_css( $el, 'flex-direction' ) ) );
			$is_col   = ( 'column' === $dir || 'column-reverse' === $dir )
				|| ( '' === $dir && (bool) preg_match( '/(?:^|\s)(?:(?:sm|md|lg|xl|2xl):)?flex-col(?:\s|$)/', $cls ) );
			$resp_row = (bool) preg_match( '/(?:^|\s)(?:sm|md|lg|xl|2xl):flex-row(?:\s|$)/', $cls ); // desktop override wins
			$meta['cols'] = count( $kids );
			$meta['gap']  = self::grid_gap_px( $el );
			return ( $is_col && ! $resp_row ) ? 'flex-col' : 'flex-row';
		}

		return 'block';
	}

	/**
	 * Walk DOWN a chain of transparent grouping wrappers to the first element that actually carries
	 * meaning — a container with ≥2 substantial children (a real grid/flex/block band), or a content
	 * leaf. A wrapper is "transparent" when it has exactly ONE element child AND no visual box of its
	 * own (no background, border, ring, shadow, or its own grid/flex layout across multiple children).
	 * This is the div-soup collapser: it lets the caller reason about the REAL structure instead of the
	 * meaningless single-child `<div>`s that AI builders emit. Returns the deepest meaningful node
	 * (never null; returns $el itself if it isn't transparent). CONSERVATIVE: it only descends through
	 * genuinely styling-free single-child wrappers, so it can never skip past a card or a layout row.
	 */
	private static function collapse_transparent_wrappers( $el ) {
		$node  = $el;
		$guard = 0;
		while ( $node instanceof DOMElement && $guard++ < 8 ) {
			$kids = self::el_children( $node );
			if ( count( $kids ) !== 1 ) { break; }           // ≥2 children = a real band; 0 = a leaf
			if ( self::wrapper_has_own_box( $node ) ) { break; } // carries a visual box → not transparent
			$only = $kids[0];
			if ( ! ( $only instanceof DOMElement ) ) { break; }
			$node = $only;
		}
		return $node instanceof DOMElement ? $node : $el;
	}

	/** Does this wrapper carry a visual box of its OWN (a fill / border / ring / shadow / backdrop, or a
	 *  grid|flex layout) that would be LOST if we collapsed it into its child? Read from computed style
	 *  first, then Tailwind tokens. Used by collapse_transparent_wrappers to decide "safe to skip". */
	private static function wrapper_has_own_box( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		if ( '' !== $cs ) {
			if ( preg_match( '/(?:^|;)\s*background(?:-color|-image)?\s*:\s*(?!none|transparent|rgba\(0,\s*0,\s*0,\s*0\)|initial)/i', $cs ) ) { return true; }
			if ( preg_match( '/(?:^|;)\s*border(?:-\w+)?-width\s*:\s*(?!0)/i', $cs ) ) { return true; }
			if ( preg_match( '/(?:^|;)\s*(?:box-shadow|backdrop-filter)\s*:\s*(?!none)/i', $cs ) ) { return true; }
			if ( preg_match( '/(?:^|;)\s*display\s*:\s*(?:grid|flex|inline-flex|inline-grid)/i', $cs ) ) { return true; }
		}
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( preg_match( '/(?:^|\s)(?:bg-(?!transparent|none)|border(?:\s|-)|ring-|shadow(?:\s|-)|backdrop-|grid(?:\s|$)|(?:inline-)?flex(?:\s|$)|rounded)/', $cls ) ) { return true; }
		return false;
	}

	/**
	 * Is this element (or a wrapper up to a few levels above it) a `position:fixed`, FULL-VIEWPORT layer —
	 * a page-wide fixed backdrop the whole page scrolls over (lumina-arctic's `div.video-portal`)? Reads the
	 * captured computed `position` first, then Tailwind `fixed`, and requires a full-viewport signal
	 * (inset-0 / w-full+h-full / w-screen+h-screen, or a computed 100vw/100vh box). Distinct from `absolute`
	 * (a section-local bleed) — a FIXED full-viewport layer is a SITE-level backdrop, not a section one.
	 */
	/**
	 * The page's FIXED decorative PATTERN layer: an element inside a body-level fixed inset-0 wrapper (or that wrapper itself)
	 * with no text and no media, whose computed background-image is a gradient / data-URI TILE (a repeating grid), not a
	 * photo. Returns { image, opacity, extra } (extra = the tile's background-size / -repeat) or null. Glow blobs (a
	 * blurred rounded box) are skipped: they are a fill, not a pattern.
	 */
	/**
	 * The stylesheet rules the source <main> wears by its own classes / id (+ the @keyframes they animate), re-targeted at the
	 * theme's `main.site-main`. Layout the theme's wrapper owns (display / position / size / spacing / overflow) is dropped from the
	 * copied bodies; everything else (a background animation, a blend, a filter, a colour) is kept. '' when <main> has none.
	 */
	/** The page-level decor layers (see the caller): up to two, as `main.site-main::before` / `::after`. '' when none. */
	private static function page_decor_layers_css( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$layers = array();
		foreach ( array( 'main', 'body' ) as $tag ) {
			$el = $dom->getElementsByTagName( $tag )->item( 0 );
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			foreach ( self::el_children( $el ) as $kid ) {
				$kt = strtolower( $kid->tagName );
				if ( self::is_decor_layer_block( $kid, $kt ) ) { $blk = self::decor_layer_block( $kid ); }
				else {
					// …a FIXED layer too (`position:fixed`), the same shape
					$kcs = (string) $kid->getAttribute( 'data-sc-cs' );
					if ( ! preg_match( '/(?:^|;)\s*position:\s*fixed/i', $kcs ) || '' !== trim( self::text( $kid ) ) || $kid->getElementsByTagName( '*' )->length ) { continue; }
					$fake = $kid->cloneNode( false ); $fake->setAttribute( 'data-sc-cs', preg_replace( '/position:\s*fixed/i', 'position:absolute', $kcs ) );
					if ( ! self::is_decor_layer_block( $fake, $kt ) ) { continue; }
					$blk = self::decor_layer_block( $fake ); $blk['css'] = preg_replace( '/^position:absolute/', 'position:fixed', (string) $blk['css'] );
				}
				if ( empty( $blk['css'] ) ) { continue; }
				$layers[] = (string) $blk['css'];
				if ( count( $layers ) >= 2 ) { break 2; }
			}
		}
		if ( ! $layers ) { return ''; }
		$out = 'main.site-main{position:relative;}';
		foreach ( $layers as $i => $css ) { $out .= "\n" . 'main.site-main::' . ( 0 === $i ? 'before' : 'after' ) . '{content:"";' . $css . ';}'; }
		return $out;
	}

	private static function page_shell_css( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return ''; }
		$all_css = self::all_style_css( (string) $html );
		$out_all = '';
		// the two shells: the source <body> → the theme's body; the source <main> → the theme's main.site-main
		// (the body's rules are scoped to the FRONT END: Misc Custom CSS also loads in the builder's admin page, where a page-wide
		// ground / a fixed pattern layer bled over the editor)
		foreach ( array( array( 'body', 'body:not(.wp-admin)' ), array( 'main', 'main.site-main' ) ) as $pair ) {
			list( $tag, $target ) = $pair;
			$el = $dom->getElementsByTagName( $tag )->item( 0 );
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$tokens = array();
			$id = trim( (string) $el->getAttribute( 'id' ) ); if ( '' !== $id ) { $tokens[] = '#' . $id; }
			foreach ( preg_split( '/\s+/', trim( (string) $el->getAttribute( 'class' ) ) ) as $c ) {
				if ( '' === $c || ! preg_match( '/^[A-Za-z_][\w-]*$/', $c ) ) { continue; }
				// a resolvable utility (text-white, font-sans, antialiased) is the design's token, carried natively — only the source's
				// OWN classes (.ascending-bg, .noise) are looked up in its sheets
				if ( class_exists( 'FW_Site_Converter_Tailwind' ) ) { $cm = FW_Site_Converter_Tailwind::compile_class_set( $c ); if ( ! empty( $cm['base'] ) ) { continue; } }
				$tokens[] = '.' . $c;
			}
			// …plus the ELEMENT's own bare rules (`body{background:…}` — a layered gradient ground, `body::before{…}` — a fixed grid
			// pattern): a source that styles the shell by tag, not by class, carries just as much design.
			$bare = self::bare_element_css( $all_css, $tag );
			if ( ! $tokens && '' === trim( $bare ) ) { continue; }
			$css = ( $tokens ? self::extract_scoped_css( $all_css, $tokens ) : '' ) . "
" . $bare;
			if ( '' === trim( $css ) ) { continue; }
			$tokens[] = $tag;
			// re-target: every selector that names the shell → the theme's element; drop the wrapper-owned layout props from the bodies
			$out = preg_replace_callback( '/([^{}]+)\{([^{}]*)\}/', function ( $m ) use ( $tokens, $tag, $target ) {
				$sel = trim( $m[1] );
				if ( 0 === strpos( $sel, '@' ) || preg_match( '/^\d|^from$|^to$/i', $sel ) ) { return $m[0]; } // an at-rule prelude / a keyframe step: verbatim
				$sels = array();
				foreach ( explode( ',', $sel ) as $one ) {
					$one = trim( $one ); $hit = false;
					foreach ( $tokens as $t ) { if ( false !== stripos( $one, $t ) ) { $hit = true; $one = preg_replace( '/(?:' . $tag . ')?' . preg_quote( $t, '/' ) . '(?![\w-])/i', $target, $one ); } }
					if ( $hit ) { $sels[] = $one; }
				}
				if ( ! $sels ) { return ''; }
				// declaration by declaration (a regex over the joined body eats the boundary of the next one)
				$keep = array();
				$pseudo = (bool) preg_match( '/::?(?:before|after)(?![a-z-])/i', $sel ); // a pseudo LAYER's placement (fixed, inset:0, z-index:-1) is its design, not the wrapper's layout
				foreach ( explode( ';', $m[2] ) as $decl ) {
					$decl = trim( $decl ); if ( '' === $decl || false === strpos( $decl, ':' ) ) { continue; }
					$prop = strtolower( trim( substr( $decl, 0, strpos( $decl, ':' ) ) ) );
					if ( ! $pseudo && preg_match( '/^(?:display|position|top|right|bottom|left|width|min-width|max-width|height|min-height|margin[a-z-]*|padding[a-z-]*|overflow[a-z-]*|flex[a-z-]*|grid[a-z-]*|z-index)$/', $prop ) ) { continue; } // the theme's wrapper owns its layout
					if ( 'body' === $tag && preg_match( '/^(?:font[a-z-]*|color|line-height|letter-spacing|-webkit-font-smoothing|-moz-osx-font-smoothing|text-rendering)$/', $prop ) ) { continue; } // the body's TYPE is Theme Settings → Typography
					$keep[] = $decl;
				}
				$body = implode( ';', $keep );
				if ( '' === trim( $body, "; \t\r\n" ) ) { return ''; }
				return implode( ',', array_unique( $sels ) ) . '{' . trim( $body, "; \t\r\n" ) . ';}';
			}, $css );
			$out = trim( preg_replace( '/\s+/', ' ', (string) $out ) );
			if ( '' !== $out && ( false !== strpos( $out, $target . '{' ) || false !== strpos( $out, $target . ':' ) ) ) { $out_all .= ( '' !== $out_all ? "\n" : '' ) . $out; }
		}
		return $out_all;
	}

	/** The rules whose every selector IS the bare element (`body`, `body::before`, `html, body`) — the shell's own tag-level design. */
	private static function bare_element_css( $all_css, $tag ) {
		$out = '';
		if ( ! preg_match_all( '/([^{}]+)\{([^{}]*)\}/', (string) $all_css, $mm, PREG_SET_ORDER ) ) { return ''; }
		foreach ( $mm as $m ) {
			$sel = trim( $m[1] );
			if ( 0 === strpos( $sel, '@' ) || '' === trim( $m[2] ) ) { continue; }
			$keep = array();
			foreach ( explode( ',', $sel ) as $one ) { $one = trim( $one ); if ( preg_match( '/^' . $tag . '(::?[a-z-]+)?$/i', $one ) ) { $keep[] = $one; } }
			if ( $keep ) { $out .= implode( ',', $keep ) . '{' . trim( $m[2] ) . '}' . "
"; }
		}
		return $out;
	}

	private static function detect_page_fixed_pattern( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return null; }
		$body = $dom->getElementsByTagName( 'body' )->item( 0 );
		if ( ! $body ) { return null; }
		foreach ( self::el_children( $body ) as $wrap ) {
			if ( ! self::el_is_page_fixed_layer( $wrap ) || '' !== trim( self::text( $wrap ) ) ) { continue; }
			foreach ( array( 'img', 'video', 'svg', 'iframe', 'canvas' ) as $mt ) { if ( $wrap->getElementsByTagName( $mt )->length ) { continue 2; } }
			$cands = array_merge( array( $wrap ), iterator_to_array( $wrap->getElementsByTagName( '*' ) ) );
			foreach ( $cands as $c ) {
				if ( ! ( $c instanceof DOMElement ) ) { continue; }
				$cs = (string) $c->getAttribute( 'data-sc-cs' );
				if ( ! preg_match( '/(?:^|;)\s*background-image:\s*([^;]+)/i', $cs, $m ) ) { continue; }
				$img = trim( $m[1] );
				if ( 'none' === strtolower( $img ) || preg_match( '/url\((?!"?data:image\/svg)/i', $img ) || strlen( $img ) > 3000 ) { continue; } // a photo is not a pattern
				if ( ! preg_match( '/gradient\(|data:image\/svg/i', $img ) ) { continue; }
				$sz = preg_match( '/(?:^|;)\s*background-size:\s*([^;]+)/i', $cs, $sm ) ? trim( $sm[1] ) : '';
				$blur = preg_match( '/(?:^|;)\s*filter:\s*blur\(/i', $cs );
				// a TILE: a repeating gradient, an svg tile, or a gradient with a px tile size; a single soft gradient blob is not one
				if ( $blur || ( ! preg_match( '/repeating-|data:image\/svg/i', $img ) && ! preg_match( '/^[0-9.]+px/', $sz ) ) ) { continue; }
				$op = preg_match( '/(?:^|;)\s*opacity:\s*([0-9.]+)/i', $cs, $om ) ? min( 1.0, (float) $om[1] ) : 1.0;
				$extra = '';
				if ( '' !== $sz && preg_match( '/^[a-z0-9.%,\s-]+$/i', $sz ) ) { $extra .= 'background-size:' . $sz . ';'; }
				$rp = preg_match( '/(?:^|;)\s*background-repeat:\s*([^;]+)/i', $cs, $rm ) ? trim( $rm[1] ) : '';
				if ( '' !== $rp && preg_match( '/^[a-z\s-]+$/i', $rp ) && 'repeat' !== strtolower( $rp ) ) { $extra .= 'background-repeat:' . $rp . ';'; }
				return array( 'image' => $img, 'opacity' => $op, 'extra' => $extra );
			}
		}
		return null;
	}

	private static function el_is_page_fixed_layer( $el ) {
		$node = $el; $guard = 0;
		while ( $node instanceof DOMElement && $guard++ < 6 ) {
			$tag = strtolower( $node->tagName );
			if ( in_array( $tag, array( 'body', 'html' ), true ) ) { break; }
			$cls = ' ' . strtolower( self::cls( $node ) ) . ' ';
			$cs  = (string) $node->getAttribute( 'data-sc-cs' );
			$pos = strtolower( (string) self::sc_css( $node, 'position' ) );
			$is_fixed = ( 'fixed' === $pos ) || (bool) preg_match( '/(?:^|\s)fixed(?:\s|$)/', $cls );
			if ( $is_fixed ) {
				$full = (bool) preg_match( '/inset-0|w-screen|h-screen/', $cls )
					|| ( strpos( $cls, 'w-full' ) !== false && strpos( $cls, 'h-full' ) !== false )
					|| (bool) preg_match( '/\b100vw\b|\b100vh\b|width:\s*100vw|height:\s*100vh/i', $cs )
					// the computed stamp of a stylesheet `inset:0` (no utility class): all four offsets at 0
					|| ( preg_match( '/(?:^|;)\s*top:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*bottom:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*left:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*right:\s*0px/i', $cs ) );
				if ( $full ) { return true; }
			}
			$node = $node->parentNode instanceof DOMElement ? $node->parentNode : null;
		}
		return false;
	}

	/**
	 * Detect a PAGE-WIDE fixed-video backdrop — a single <video> pinned behind ALL content by a
	 * `position:fixed` full-viewport wrapper (lumina-arctic's `div.video-portal`), which the whole page
	 * scrolls over. This is NOT a section background (UnysonPlus sections are per-section and CSS can't pin a
	 * <video>): it maps to the SITE background's video layer in FIXED mode, rendered once behind everything by
	 * the theme (unysonplus_render_site_bg_video). Returns { mp4, webm, poster } or array() when there is none.
	 */
	/** Misc Custom CSS for the page backdrop video layer, set by the site-background pass and appended with the shell css. */
	private static $page_backdrop_css = '';

	private static function detect_page_fixed_video( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return array(); }
		$body = $dom->getElementsByTagName( 'body' )->item( 0 );
		if ( ! ( $body instanceof DOMElement ) ) { return array(); }
		foreach ( $body->getElementsByTagName( 'video' ) as $vid ) {
			$backdrop = self::page_backdrop_layer_of( $vid ); // a fixed, viewport-tall, unframed layer the page scrolls over (full-bleed OR a partial-width anchor)
			if ( ! self::el_is_page_fixed_layer( $vid ) && ! $backdrop ) { continue; }
			$src = (string) $vid->getAttribute( 'src' ); $webm = '';
			foreach ( $vid->getElementsByTagName( 'source' ) as $s ) {
				$ss = (string) $s->getAttribute( 'src' ); $st = strtolower( (string) $s->getAttribute( 'type' ) );
				if ( '' === $ss ) { continue; }
				if ( '' === $webm && ( 'video/webm' === $st || preg_match( '/\.webm(\?|$)/i', $ss ) ) ) { $webm = $ss; }
				if ( '' === $src  && ( 'video/mp4'  === $st || preg_match( '/\.mp4(\?|$)/i',  $ss ) ) ) { $src  = $ss; }
			}
			if ( '' === $src && '' === $webm ) { continue; }
			return array( 'mp4' => $src, 'webm' => $webm, 'poster' => (string) $vid->getAttribute( 'poster' ), 'css' => $backdrop ? self::page_backdrop_css( $backdrop, $vid ) : '' );
		}
		return array();
	}

	/**
	 * The PAGE BACKDROP layer a <video> sits in: a `position:fixed` wrapper (or the video itself) that is viewport-TALL
	 * (100vh), UNFRAMED (no radius — a framed one is a floating portal), sits behind the content (z-index ≤ 1 or
