			$ax = isset( $g['left'] ) && preg_match( '/^-?[0-9.]+px$/', trim( $g['left'] ) ) ? 'left' : ( isset( $g['right'] ) && preg_match( '/^-?[0-9.]+px$/', trim( $g['right'] ) ) ? 'right' : '' );
