		if ( isset( $g['opacity'] ) && '' !== $g['opacity'] && '1' !== trim( $g['opacity'] ) ) { $d[] = 'opacity:' . $g['opacity']; }
		if ( isset( $g['mix-blend-mode'] ) && 'normal' !== strtolower( trim( $g['mix-blend-mode'] ) ) ) { $d[] = 'mix-blend-mode:' . $g['mix-blend-mode']; }
