		if ( ! empty( $vf['opacity'] ) && '1' !== trim( $vf['opacity'] ) ) { $vd[] = 'opacity:' . $vf['opacity']; }
		if ( $vd ) { $out[] = '.site-bg-video video{' . implode( ';', $vd ) . ';}'; }
