			$sh = preg_match( '/^([0-9.]+)px$/', (string) self::sc_css( $node, 'height' ), $shm ) ? (float) $shm[1] : 0.0;
			if ( $lh > 0 && $sh > 0 && $lh < $sh * 0.7 ) { continue; }
