			if ( ! ( $vid0 instanceof DOMElement ) || ! $vid0->hasAttribute( 'autoplay' ) || ! $vid0->hasAttribute( 'muted' ) ) { continue; }
			$best = $el; $vid = $vid0; break;
		}
		// PASS 2 — no bleed wrapper: the <video> is ITSELF the full-bleed backdrop — either it carries a
		// background class (`video-bg`/`bg-video`) or it is self-positioned absolute/fixed and NOT a rounded
		// content panel inside a grid column (biophilic's hero video-bg vs nox-liquid's `video-portal` card).
		if ( null === $best ) {
			foreach ( $node->getElementsByTagName( 'video' ) as $v ) {
				if ( ! ( $v instanceof DOMElement ) || ! $v->hasAttribute( 'autoplay' ) || ! $v->hasAttribute( 'muted' ) ) { continue; }
				$vcls    = ' ' . strtolower( self::cls( $v ) ) . ' ';
				$bgclass = ( strpos( $vcls, 'video-bg' ) !== false || strpos( $vcls, 'bg-video' ) !== false || strpos( $vcls, 'video-background' ) !== false );
				$vpos    = self::sc_css( $v, 'position' );
				$selfabs = ( 'absolute' === $vpos || 'fixed' === $vpos );
				if ( ! ( $bgclass || $selfabs ) ) { continue; }
				// Reject a rounded card / a grid-column-scoped panel (that's CONTENT, not a backdrop) unless
				// it explicitly carries a bg class.
				$incol = false; $rounded = false;
				for ( $a = $v; ( $a instanceof DOMElement ) && $a !== $node; $a = $a->parentNode ) {
					if ( $a->hasAttribute( 'data-sc-col' ) ) { $incol = true; }
					$arad = self::sc_css( $a, 'border-radius' );
					if ( '' !== $arad && preg_match( '/^([0-9.]+)px/', $arad, $rm ) && (float) $rm[1] >= 24 ) { $rounded = true; }
				}
				if ( ! $bgclass && ( $incol || $rounded ) ) { continue; }
				$best = $v; $vid = $v; break;
			}
		}
		if ( null === $best || ! ( $vid instanceof DOMElement ) ) { return array(); }
		$src  = (string) $vid->getAttribute( 'src' );
		$webm = '';
		foreach ( $vid->getElementsByTagName( 'source' ) as $s ) {
			$ssrc = (string) $s->getAttribute( 'src' ); if ( '' === $ssrc ) { continue; }
			$stype = strtolower( (string) $s->getAttribute( 'type' ) );
			if ( '' === $webm && ( 'video/webm' === $stype || preg_match( '/\.webm(\?|$)/i', $ssrc ) ) ) { $webm = $ssrc; }
			if ( '' === $src  && ( 'video/mp4'  === $stype || preg_match( '/\.mp4(\?|$)/i',  $ssrc ) ) ) { $src  = $ssrc; }
		}
		if ( '' === $src && '' === $webm ) { return array(); }
		$poster = (string) $vid->getAttribute( 'poster' );
		$overlay = '';
		foreach ( $best->getElementsByTagName( '*' ) as $ov ) {
			if ( ! ( $ov instanceof DOMElement ) || $ov === $vid ) { continue; }
			$bgi = self::sc_css( $ov, 'background-image' );
			if ( '' !== $bgi && false !== stripos( $bgi, 'gradient' ) && false === stripos( $bgi, 'url(' ) ) { $overlay = $bgi; break; }
			$bgc = self::sc_css( $ov, 'background-color' );
			if ( '' !== $bgc && preg_match( '/rgba\([^)]*,\s*0?\.\d+\s*\)/i', $bgc ) ) { $overlay = $bgc; break; }
		}
		// No scrim ELEMENT → a `::before` / `::after` pseudo-layer tint stamped by the capture (data-sc-scrim).
		if ( '' === $overlay ) { $overlay = self::pseudo_scrim_of( $best ); }
		if ( '' === $overlay ) { $overlay = self::pseudo_scrim_of( $node ); }
		// EFFECT WRAPPER — a wrapper between the bleed layer and the <video> carrying a visual effect that
		// Background-Pro CANNOT reproduce (mask-image / filter / mix-blend-mode / clip-path — an AI page's
		// `.kinetic-breach` radial mask + saturate/brightness that fades the headset into black). Read it
		// from the SOURCE STYLESHEET (custom classes define these there, not in the curated data-sc-cs).
		// When present, the mapper renders the bg video as a media_video in Section-Background mode with the
		// effect carried as vanilla CSS, instead of flattening to a Background-Pro video (which drops it).
		$effect_css = self::bg_video_effect_css( (string) $html, $best, $vid );
		// The source <video>'s own paint under its frames: a transparent backdrop shows the page / section ground while the
		// clip loads (or where a frame can't decode) — the media_video's default black under-paint would otherwise turn
		// that hero black. Carried only when the stamp says transparent. JS twin: bgVideoBlock (videoBg).
		$video_bg = '';
		if ( $vid instanceof DOMElement && preg_match( '/(?:^|;)\s*background-color:\s*([^;]+)/i', (string) $vid->getAttribute( 'data-sc-cs' ), $vbm ) ) {
			$vbc = strtolower( trim( $vbm[1] ) );
			if ( 'transparent' === $vbc || preg_match( '/^rgba\([^)]*,\s*0\s*\)$/', $vbc ) ) { $video_bg = 'transparent'; }
		} elseif ( $vid instanceof DOMElement && '' !== (string) $vid->getAttribute( 'data-sc-cs' ) ) { $video_bg = 'transparent'; } // (a stamp that carries no fill = no fill of its own)
		if ( $best->parentNode instanceof DOMElement ) { $best->parentNode->removeChild( $best ); } // now the section bg
			// DUPLICATE PARALLAX COPY — some generators (AI-page) stamp the backdrop video TWICE: the true bleed
			// layer PLUS a second offset copy for a parallax/lens effect, both playing the SAME `.mp4`. The first is
			// now the section background; a leftover same-src absolute lone-video layer would otherwise render as a
			// stray inline tile beside the hero. Drop any remaining absolute/fixed lone-video wrapper in this section
			// that plays the same clip — a general rule (a de-duplicated bg video), not an AI-page special case.
			$same_src = function ( $v ) use ( $src, $webm ) {
				if ( ! ( $v instanceof DOMElement ) ) { return false; }
				$cand = array( (string) $v->getAttribute( 'src' ) );
				foreach ( $v->getElementsByTagName( 'source' ) as $s ) { $cand[] = (string) $s->getAttribute( 'src' ); }
				foreach ( $cand as $c ) { if ( '' !== $c && ( $c === $src || ( '' !== $webm && $c === $webm ) ) ) { return true; } }
				return false;
			};
			foreach ( iterator_to_array( $node->getElementsByTagName( 'video' ) ) as $dv ) {
				if ( ! $same_src( $dv ) ) { continue; }
				$drop = $dv; // fall back to the <video> itself if no positioned wrapper is found
				for ( $a = $dv->parentNode; ( $a instanceof DOMElement ) && $a !== $node; $a = $a->parentNode ) {
					$ap   = self::sc_css( $a, 'position' );
					$acls = ' ' . strtolower( self::cls( $a ) ) . ' ';
					$aabs = ( 'absolute' === $ap || 'fixed' === $ap || strpos( $acls, ' absolute ' ) !== false || strpos( $acls, ' fixed ' ) !== false );
					if ( $aabs && 1 === $a->getElementsByTagName( 'video' )->length && mb_strlen( trim( self::text( $a ) ) ) <= 40 ) { $drop = $a; break; }
				}
				if ( $drop->parentNode instanceof DOMElement ) { $drop->parentNode->removeChild( $drop ); }
			}
		// REAL hero height from the SECTION's own `min-h-[Nvh]` / computed min-height (parity with
		// section_bg_image), instead of a hardcoded 100vh — a `min-h-[70vh]` video hero was being framed at
		// 100vh (too tall).
		$scls = ' ' . strtolower( self::cls( $node ) ) . ' ';
		$scs2 = (string) $node->getAttribute( 'data-sc-cs' );
		$hh   = '100vh';
		if ( preg_match( '/\b(?:min-)?h-\[([0-9.]+)(?:s|d)?vh\]/', $scls, $hm ) ) { $hh = $hm[1] . 'vh'; }
		elseif ( preg_match( '/(?:^|;)\s*min-height:\s*([0-9.]+)(?:vh|dvh|svh)/', $scs2, $hm ) && (float) $hm[1] >= 40 ) { $hh = $hm[1] . 'vh'; }
		// The SECTION's own BOX CAP: a `max-w-* mx-auto` section is a CENTERED capped box (apple-vision-pro's
		// `max-w-6xl mx-auto` = 1152px), so its full-bleed background video must be capped to it — else the
		// video spans the whole viewport. `container_width` only constrains inner CONTENT, not the section box
		// or its background, so carry the computed/utility max-width; the mapper caps the section box + centers.
		$box_mw = '';
		if ( preg_match( '/\bmx-auto\b/', $scls ) || preg_match( '/margin(?:-left|-right)?:\s*auto/', $scs2 ) ) {
			if ( preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/i', $scs2, $mm ) && (float) $mm[1] >= 400 && (float) $mm[1] <= 1600 ) {
				$box_mw = (string) (int) round( (float) $mm[1] );
			} else { // class fallback — the Tailwind max-w-* scale in px
				$mw_scale = array( '2xl' => 672, '3xl' => 768, '4xl' => 896, '5xl' => 1024, '6xl' => 1152, '7xl' => 1280 );
				if ( preg_match( '/\bmax-w-(2xl|3xl|4xl|5xl|6xl|7xl)\b/', $scls, $mk ) ) { $box_mw = (string) $mw_scale[ $mk[1] ]; }
			}
		}
		return array(
			't' => 'video', 'role' => 'video', 'mode' => 'self_hosted', 'bg' => true,
			'src' => $src, 'webm' => $webm, 'poster' => $poster, 'overlay' => $overlay,
			'valign' => 'middle', 'hero_height' => $hh, 'boxMaxW' => $box_mw, 'effectCss' => $effect_css, 'videoBg' => $video_bg,
		);
	}

	/**
	 * The visual effect a bg-video WRAPPER carries that Background-Pro can't reproduce (mask-image / filter /
	 * mix-blend-mode / clip-path), as a vanilla CSS declaration string — read from the SOURCE STYLESHEET rules
	 * matching each wrapper's classes/id (custom classes like `.kinetic-breach` define these there, not in the
	 * curated data-sc-cs). Walks from the <video> up to (not incl.) the bleed layer; nearest-to-video wins.
	 * Empty when the wrapper is plain (→ the caller keeps the simple Background-Pro video).
	 */
	private static function bg_video_effect_css( $html, $best, $vid ) {
		if ( ! ( $vid instanceof DOMElement ) || ! ( $best instanceof DOMElement ) ) { return ''; }
		$sheet = self::all_style_css( (string) $html );
		$props = array( 'mask-image', '-webkit-mask-image', 'filter', 'mix-blend-mode', 'clip-path' );
		$collect = function ( $el ) use ( $sheet, $props ) {
			$bodies = array( (string) $el->getAttribute( 'data-sc-cs' ) );
			$sels   = array();
			$id     = trim( (string) $el->getAttribute( 'id' ) );
			if ( '' !== $id ) { $sels[] = '#' . preg_quote( $id, '/' ); }
			foreach ( preg_split( '/\s+/', (string) self::cls( $el ) ) as $c ) { $c = trim( $c ); if ( '' !== $c ) { $sels[] = '\.' . preg_quote( $c, '/' ); } }
			if ( $sels ) {
				$re = '/(?:' . implode( '|', $sels ) . ')(?![\w-])[^{}]*\{([^}]*)\}/i';
				if ( preg_match_all( $re, $sheet, $mm ) ) { foreach ( $mm[1] as $b ) { $bodies[] = $b; } }
			}
			$found = array();
			foreach ( $props as $p ) {
				foreach ( $bodies as $body ) {
					if ( preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', $body, $m ) ) {
						$v = trim( $m[1] );
						if ( '' !== $v && stripos( $v, 'none' ) === false && ( 'mix-blend-mode' !== $p || stripos( $v, 'normal' ) === false ) ) { $found[ $p ] = $v; }
					}
				}
			}
			// Tailwind ARBITRARY-value classes directly on the element carry the value IN THE CLASS NAME (with
			// `_` for spaces) — `[mask-image:linear-gradient(to_bottom,rgba(0,0,0,1)_60%,rgba(0,0,0,0)_100%)]`
			// (anime-environment-engine's fade-to-black mask on the <video> itself). data-sc-cs omits these
			// (curated) and the compiled selector is escaped, so parse the class token. Fills props not already
			// found from the computed style / stylesheet.
			$cls_raw = (string) self::cls( $el );
			if ( '' !== $cls_raw && false !== strpos( $cls_raw, '[' ) && preg_match_all( '/\[(-?(?:webkit-)?mask-image|filter|mix-blend-mode|clip-path)\s*:\s*([^\]]+)\]/i', $cls_raw, $am, PREG_SET_ORDER ) ) {
				foreach ( $am as $a ) {
					$p = strtolower( $a[1] );
					if ( 'webkit-mask-image' === $p ) { $p = '-webkit-mask-image'; }
					$v = trim( str_replace( '_', ' ', $a[2] ) );
					if ( '' !== $v && stripos( $v, 'none' ) === false && ! isset( $found[ $p ] ) && ( 'mix-blend-mode' !== $p || stripos( $v, 'normal' ) === false ) ) { $found[ $p ] = $v; }
				}
			}
			return $found;
		};
		// Walk the <video> and each wrapper UP TO AND INCLUDING the bleed layer $best (nearest-to-video wins).
		// Inclusive of $vid itself: in the PASS-2 case the video IS the backdrop ($best === $vid) and carries
		// the effect directly (anime-environment-engine's `[mask-image:…]` on the <video>), so it must be read.
		$decls = array();
		for ( $w = $vid; $w instanceof DOMElement; $w = $w->parentNode ) {
			foreach ( $collect( $w ) as $p => $v ) { if ( ! isset( $decls[ $p ] ) ) { $decls[ $p ] = $v; } }
			if ( $w === $best ) { break; }
		}
		if ( ! $decls ) { return ''; }
		$out  = array();
		$mask = isset( $decls['mask-image'] ) ? $decls['mask-image'] : ( isset( $decls['-webkit-mask-image'] ) ? $decls['-webkit-mask-image'] : '' );
		if ( '' !== $mask ) { $out[] = '-webkit-mask-image:' . $mask; $out[] = 'mask-image:' . $mask; $out[] = '-webkit-mask-repeat:no-repeat'; $out[] = 'mask-repeat:no-repeat'; }
		if ( isset( $decls['filter'] ) )         { $out[] = 'filter:' . $decls['filter']; }
		if ( isset( $decls['mix-blend-mode'] ) ) { $out[] = 'mix-blend-mode:' . $decls['mix-blend-mode']; }
		if ( isset( $decls['clip-path'] ) )      { $out[] = 'clip-path:' . $decls['clip-path']; }
		return $out ? implode( ';', $out ) . ';' : '';
	}

	private static function section_bg_image( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return array(); }
		$scls   = ' ' . strtolower( self::cls( $node ) ) . ' ';
		$hero   = (bool) preg_match( '/\b(h-screen|min-h-screen)\b|\bh-\[[0-9]+s?vh\]|\bmin-h-\[[0-9]+s?vh\]/', $scls );
		// The hero's ACTUAL viewport height (so `h-screen` → 100vh, `h-[80vh]` → 80vh, a computed vh height →
		// itself), instead of a hardcoded 80vh. Falls back to '' (→ the 80vh default) when only a boolean signal.
		$hero_height = '';
		$scs = (string) $node->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/\b(?:min-)?h-\[([0-9.]+)(?:s|d)?vh\]/', $scls, $hm ) )       { $hero_height = $hm[1] . 'vh'; }
		elseif ( preg_match( '/\b(?:min-)?h-screen\b/', $scls ) )                       { $hero_height = '100vh'; }
		elseif ( $scs !== '' && preg_match( '/(?:^|;)\s*(?:min-)?height:\s*([0-9.]+)(?:vh|dvh|svh)/', $scs, $hm ) && (float) $hm[1] >= 60 ) { $hero_height = $hm[1] . 'vh'; }
		// Vertical placement of the content = the content layer's flex alignment (justify-end → bottom).
		$valign = 'middle';
		$whole  = strtolower( $node->ownerDocument ? (string) $node->ownerDocument->saveHTML( $node ) : '' );
		if ( strpos( $whole, 'justify-end' ) !== false )      { $valign = 'bottom'; }
		elseif ( strpos( $whole, 'justify-start' ) !== false ) { $valign = 'top'; }
		// OVERLAY / SCRIM — a full-bleed layer whose fill is a GRADIENT (`bg-gradient-to-b from-background/80
		// via-background/50 to-background`) or a SEMI-TRANSPARENT colour, sitting OVER the photo to darken it
		// / fade it into the canvas. Carry the real one so the section's Background → Overlay matches the
		// source, instead of a hardcoded flat 35% black. Skips the image layer (its fill is a url()).
		$overlay = '';
		foreach ( $node->getElementsByTagName( '*' ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$ecls  = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$bleed = ( ( strpos( $ecls, ' absolute ' ) !== false || strpos( $ecls, ' fixed ' ) !== false ) && strpos( $ecls, 'inset-0' ) !== false );
			if ( ! $bleed ) {
				$pos = self::sc_css( $el, 'position' );
				if ( $pos !== 'absolute' && $pos !== 'fixed' ) { continue; }
			}
			$bgi = self::sc_css( $el, 'background-image' );
			if ( $bgi !== '' && stripos( $bgi, 'gradient' ) !== false && stripos( $bgi, 'url(' ) === false ) { $overlay = $bgi; break; }
			$bgc = self::sc_css( $el, 'background-color' );
			// a semi-transparent colour scrim (rgba with a fractional alpha, not fully opaque or fully clear)
			if ( $bgc !== '' && preg_match( '/rgba\([^)]*,\s*0?\.\d+\s*\)/i', $bgc ) ) { $overlay = $bgc; break; }
		}
		// No scrim ELEMENT → a `::before` / `::after` pseudo-layer tint stamped by the capture (data-sc-scrim).
		if ( '' === $overlay ) { $overlay = self::pseudo_scrim_of( $node ); }
		$centred_cap = self::band_has_centred_cap( $node );
		$ret = function ( $src ) use ( $hero, $valign, $hero_height, $overlay, $centred_cap ) { return array( 'src' => $src, 'contentCentred' => $centred_cap, 'hero' => $hero, 'valign' => $valign, 'hero_height' => $hero_height, 'overlay' => $overlay ); };

		// A real image URL out of a computed `background-image` layer list (skips gradients + data:svg).
		$url_of = function ( $bg ) {
			if ( ! is_string( $bg ) || stripos( $bg, 'url(' ) === false ) { return ''; }
			if ( preg_match( '/url\(\s*(["\']?)([^"\')]+)\1\s*\)/i', $bg, $m ) ) {
				$u = trim( $m[2] );
				return ( $u === '' || stripos( $u, 'data:image/svg' ) === 0 || stripos( $u, 'data:image/gif' ) === 0 ) ? '' : $u;
			}
			return '';
		};

		// (1) CSS `background-image:url()` on the SECTION ITSELF (computed, from data-sc-cs) — the most
		// common hero pattern (`<section style="background-image:url(…)">` / a `bg-[url(…)]` utility). The
		// old code only found <img> tags, so a CSS-background hero was missed and rendered as a blank band.
		$own = $url_of( self::sc_css( $node, 'background-image' ) );
		if ( $own !== '' ) { return $ret( $own ); }

		// (2) A FULL-BLEED layer (absolute/fixed inset-0, by class OR computed position) whose computed
		// `background-image` is a url() — the `<div class="absolute inset-0" style="background-image:url(…)">`
		// bg-layer pattern. Bounded to descendants that actually cover the band.
		foreach ( $node->getElementsByTagName( '*' ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$ecls  = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$bleed = ( ( strpos( $ecls, ' absolute ' ) !== false || strpos( $ecls, ' fixed ' ) !== false ) && strpos( $ecls, 'inset-0' ) !== false );
			if ( ! $bleed ) {
				$pos = self::sc_css( $el, 'position' );
				if ( $pos !== 'absolute' && $pos !== 'fixed' ) { continue; }
			}
			$bg = $url_of( self::sc_css( $el, 'background-image' ) );
			if ( $bg !== '' ) { return $ret( $bg ); }
		}

		// (3) An <img object-cover/object-fill> inside a full-bleed background LAYER (absolute/fixed inset-0),
		// not the content — the original detection path.
		foreach ( $node->getElementsByTagName( 'img' ) as $img ) {
			$icls = ' ' . strtolower( self::cls( $img ) ) . ' ';
			if ( strpos( $icls, 'object-cover' ) === false && strpos( $icls, 'object-fill' ) === false ) { continue; }
			// The full-bleed flag can be on the IMG ITSELF (`<img class="absolute inset-0 object-cover">`, the
				// jiro/React hero pattern) OR on an ancestor layer. The old code only checked ancestors, so a
				// self-inset-0 bg image was mis-mapped as a small inline media_image and the hero collapsed.
				$img_bleed = ( ( strpos( $icls, ' absolute ' ) !== false || strpos( $icls, ' fixed ' ) !== false ) && strpos( $icls, 'inset-0' ) !== false );
				$anc = $img->parentNode instanceof DOMElement ? $img->parentNode : null; $is_bg = $img_bleed; $depth = 0;
			while ( $anc instanceof DOMElement && $anc !== $node && $depth < 4 ) {
				$acls = ' ' . strtolower( self::cls( $anc ) ) . ' ';
				if ( ( strpos( $acls, ' absolute ' ) !== false || strpos( $acls, ' fixed ' ) !== false ) && strpos( $acls, 'inset-0' ) !== false ) { $is_bg = true; break; }
				$anc = $anc->parentNode; $depth++;
			}
			if ( ! $is_bg ) { continue; }
			// …but only when the layer COVERS THE BAND: an `absolute inset-0 object-cover` image filling a HALF-WIDTH cell of a
			// split band (`md:w-1/2 relative > img.absolute.inset-0`, 720 px of a 1440 band) is that cell's picture, not the
			// section backdrop — lifting it emptied the image half (a fixture from the feed). Measured: the image's stamped
			// width against the band's (the capture viewport when the band carries none).
			$iw = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', (string) $img->getAttribute( 'data-sc-cs' ), $iwm ) ? (float) $iwm[1] : 0.0;
			$bw = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $scs, $bwm ) ? (float) $bwm[1] : 1440.0;
			if ( $iw > 0 && $iw < $bw * 0.7 ) { continue; }
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( $src === '' ) { $src = trim( (string) $img->getAttribute( 'data-src' ) ); }
			if ( $src === '' || strpos( $src, 'data:image/svg' ) === 0 ) { continue; }
			return $ret( $src );
		}
		// (3b) HERO ASPECT-BOX — an `<img w-full h-full object-cover>` FILLING a `relative aspect-[…]` container
		// whose `absolute inset-0` overlay carries a HEADING (h1–h6). The Tailwind hero-banner pattern (the burger source:
		// `<div class="relative aspect-[2/1]"><img object-cover><div class="absolute inset-0 …"><h2>…</h2><a>…`).
		// The image isn't in a full-bleed inset-0 LAYER (paths above missed it), so the whole hero collapsed to a
		// verbatim code_block. A HEADING in the overlay is the gate that distinguishes a hero from an image-tile
		// GRID (whose tiles carry only a `<p>` caption, no heading) — so this NEVER fires on the food-grid tiles.
		// The image → the section Background, so the overlaid heading/text/button decompose onto the band; the
		// scrim rides as the overlay and the DESKTOP aspect ratio sets a hero min-height.
		foreach ( $node->getElementsByTagName( 'img' ) as $img ) {
			$icls = ' ' . strtolower( self::cls( $img ) ) . ' ';
			if ( ( strpos( $icls, 'object-cover' ) === false && strpos( $icls, 'object-fill' ) === false )
				|| strpos( $icls, 'w-full' ) === false || strpos( $icls, 'h-full' ) === false ) { continue; }
			$box = ( $img->parentNode instanceof DOMElement ) ? $img->parentNode : null;
			if ( ! ( $box instanceof DOMElement ) ) { continue; }
			$bcls = ' ' . strtolower( self::cls( $box ) ) . ' ';
			if ( ! preg_match( '/\baspect-(?:\[|video|square)/', $bcls )
				&& ! preg_match( '/(?:^|;)\s*aspect-ratio:/', (string) $box->getAttribute( 'data-sc-cs' ) ) ) { continue; }
			// The overlay content layer must carry a heading (a hero has one; a tile caption doesn't).
			$has_head = false;
			foreach ( $box->getElementsByTagName( '*' ) as $ov ) {
				$ocls = ' ' . strtolower( self::cls( $ov ) ) . ' ';
				if ( ( strpos( $ocls, ' absolute ' ) === false && strpos( $ocls, ' fixed ' ) === false ) || strpos( $ocls, 'inset-0' ) === false ) { continue; }
				foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { if ( $ov->getElementsByTagName( $h )->length > 0 ) { $has_head = true; break 2; } }
			}
			if ( ! $has_head ) { continue; }
			// …and the box must BE the band: a collection TILE (an `aspect-[16/9]` photo with an overlaid h3 in a 7-of-12 grid
			// cell, one of six) is a card, not the hero — hoisting it painted one tile's photo behind the whole section and
			// stripped every tile of its image (a real-site audit). Measured width against the band's, and never one of several.
			$bxw = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', (string) $box->getAttribute( 'data-sc-cs' ), $bxwm ) ? (float) $bxwm[1] : ( preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', (string) $img->getAttribute( 'data-sc-cs' ), $bxim ) ? (float) $bxim[1] : 0.0 );
			$bndw = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $scs, $bndm ) ? (float) $bndm[1] : 1440.0;
			if ( $bxw > 0 && $bxw < $bndw * 0.7 ) { continue; }
			$sibling_boxes = 0; foreach ( $node->getElementsByTagName( 'img' ) as $oi ) { $ob = $oi->parentNode; if ( $ob instanceof DOMElement && ( preg_match( '/aspect-(?:\[|video|square)/', ' ' . strtolower( self::cls( $ob ) ) . ' ' ) || preg_match( '/(?:^|;)\s*aspect-ratio:/', (string) $ob->getAttribute( 'data-sc-cs' ) ) ) ) { $sibling_boxes++; } }
			if ( $sibling_boxes >= 2 ) { continue; }
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( $src === '' ) { $src = trim( (string) $img->getAttribute( 'data-src' ) ); }
			if ( $src === '' || strpos( $src, 'data:image/svg' ) === 0 ) { continue; }
			// Min-height from the DESKTOP (widest) aspect ratio × a nominal 1440px content width (aspect-[2/1] →
			// 720px). Falls back to the hero default (80vh) when only a named/computed aspect is present.
			$ah = '';
			if ( preg_match_all( '/(?:^|\s)(?:[a-z]{2}:)?aspect-\[([0-9.]+)\/([0-9.]+)\]/', $bcls, $am, PREG_SET_ORDER ) ) {
				$best_r = 0.0;
				foreach ( $am as $a ) { $w = (float) $a[1]; $h2 = (float) $a[2]; if ( $w > 0 && $h2 > 0 ) { $r = $w / $h2; if ( $r > $best_r ) { $best_r = $r; } } }
				if ( $best_r > 0 ) { $ah = (int) round( 1440 / $best_r ) . 'px'; }
			}
			return array( 'src' => $src, 'hero' => true, 'contentCentred' => self::band_has_centred_cap( $node ), 'valign' => $valign, 'hero_height' => $ah, 'overlay' => $overlay );
		}
		return array();
	}

	/**
	 * A section's content-band max-width in px — the computed max-width of its centered content container
	 * (`container`/`max-w-*`/`mx-auto`, e.g. Lovable's `container-narrow` = 64rem). Returns the OUTERMOST
	 * such cap (the section's own content width, not a nested prose block), or 0 when the band is full-width.
	 * Feeds map_container_width() → the section's Container Width preset.
	 *
	 * @param DOMElement $node
	 * @return float px, or 0
	 */
	/** A capped wrapper is the CENTRED band only when it centres itself (`mx-auto` / `container` / a computed auto margin) or its
	 *  parent centres it (a column flex with justify-center; an inline box in a text-center parent). A bare `max-w-*` is NOT centred —
	 *  a hero's `max-w-3xl` text column sits at the band's LEFT edge (margin 0); reading it as the band cap centred the whole hero
	 *  and shrank its container to 768px (measured on a real conversion). */
	/** The band (the section holding $el, or $el itself) has a CENTRED capped content wrapper (`max-w-7xl mx-auto`, ≥ 480px, not a
	 *  text leaf): its copy is centred by design — a left-flush container would drag it to the viewport edge (measured: a hero's
	 *  `max-w-7xl mx-auto` grid pinned left at 24px instead of centred at 80px). */
	private static function band_has_centred_cap( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$band = $el;
		for ( $p = $el; $p instanceof DOMElement; $p = $p->parentNode ) { if ( in_array( strtolower( $p->tagName ), array( 'section', 'header', 'main', 'body' ), true ) ) { $band = $p; break; } }
		foreach ( $band->getElementsByTagName( '*' ) as $w ) {
			if ( in_array( strtolower( $w->tagName ), array( 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'span', 'a', 'li', 'img', 'svg', 'video', 'button' ), true ) ) { continue; }
			$wcs = (string) $w->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/', $wcs, $mm ) || (float) $mm[1] < 480 ) { continue; }
			if ( self::cap_is_centred( $w, ' ' . strtolower( self::cls( $w ) ) . ' ', $wcs ) ) { return true; }
		}
		return false;
	}

	private static function cap_is_centred( $el, $cls, $cs ) {
		if ( strpos( $cls, 'mx-auto' ) !== false || strpos( $cls, 'container' ) !== false ) { return true; }
		if ( preg_match( '/margin(?:-left|-right)?:\s*auto|(?:^|;)\s*margin:\s*[^;]*\bauto\b/', $cs ) ) { return true; }
		if ( strpos( $cls, 'max-w-' ) === false || ! ( $el instanceof DOMElement ) || ! ( $el->parentNode instanceof DOMElement ) ) { return false; }
		$par = $el->parentNode;
		$pjc = (string) self::sc_css( $par, 'justify-content' ); $pai = (string) self::sc_css( $par, 'align-items' ); $pfd = (string) self::sc_css( $par, 'flex-direction' ); $pd = (string) self::sc_css( $par, 'display' );
		if ( false !== strpos( $pd, 'flex' ) && ( ( 'column' === $pfd && 'center' === $pai ) || ( 'column' !== $pfd && 'center' === $pjc ) ) ) { return true; }
		if ( false !== strpos( $pd, 'grid' ) && 'center' === (string) self::sc_css( $par, 'justify-items' ) ) { return true; }
		return false;
	}

	/** A band whose ROOT is a left-anchored cap (`<header class="max-w-5xl">`: a max-width, no auto margins, no centring parent):
	 *  the cap's content px, or 0. The mapper puts it on the band's content flexbox as a LEFT-aligned content width. */
	private static function section_left_cap( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return 0.0; }
		$rcs = (string) $node->getAttribute( 'data-sc-cs' ); $rcls = ' ' . strtolower( (string) $node->getAttribute( 'class' ) ) . ' ';
		if ( ! preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/', $rcs, $rm ) || (float) $rm[1] < 480 || (float) $rm[1] > 1300 ) { return 0.0; }
		if ( strpos( $rcls, ' max-w-' ) === false && strpos( $rcls, ' max-w-[' ) === false ) { return 0.0; }
		if ( self::cap_is_centred( $node, $rcls, $rcs ) ) { return 0.0; }
		return self::cap_content_px( $node, (float) $rm[1] );
	}

	/** A capped box's CONTENT measure: its max-width less its own equal side padding (`max-w-7xl px-12` → 1280 − 96 = 1184).
	 *  The theme's Container Width / a flexbox's Content Width are content widths, so the box's inset must come off — every band
	 *  rendered 96px wider than the source, its copy 48px off the source's left edge (a real-site audit). Desktop tier of the
	 *  padding utilities, else the stamped shorthand. */
	private static function cap_content_px( $el, $px ) {
		if ( ! ( $el instanceof DOMElement ) || $px <= 0 ) { return $px; }
		$pl = 0.0; $pr = 0.0; $pad = self::el_padding( $el );
		if ( is_array( $pad ) ) { foreach ( array( 'lg', 'md', 'base' ) as $tier ) { if ( null !== ( $pad[ $tier ]['left'] ?? null ) ) { $pl = (float) $pad[ $tier ]['left']; $pr = (float) ( $pad[ $tier ]['right'] ?? $pl ); break; } } }
		$cpd = self::cs_decls_pad( (string) $el->getAttribute( 'data-sc-cs' ) );
		if ( null !== $cpd && $cpd['left'] > 0 && abs( $cpd['left'] - $cpd['right'] ) < 1 ) { $pl = $cpd['left']; $pr = $cpd['right']; }
		if ( $pl > 0 && $pl <= 200 && abs( $pl - $pr ) < 1 && 2 * $pl < $px / 2 ) { return $px - 2 * $pl; }
		return $px;
	}

	private static function section_content_max_width( $node, $max_px = 1300.0 ) {
		if ( ! ( $node instanceof DOMElement ) ) { return 0.0; }
		$best = 0.0;
		// The section ROOT can BE the capped box (a segmented band = the `max-w-4xl mx-auto` hero copy wrapper itself): its own
		// max-width is the band's measure. Only when the root is a non-leaf, centred, in-range cap (the leaf / column guards below
		// apply to descendants; a root is never inside its own grid).
		{ $rcs = (string) $node->getAttribute( 'data-sc-cs' ); $rcls = ' ' . strtolower( (string) $node->getAttribute( 'class' ) ) . ' ';
			// (…a LEFT-ANCHORED root cap — `max-w-5xl` with no auto margins, a hero intro hugging the page's left edge — is the
			// band's content MEASURE, not its centred container: as the container it centred the intro at (1440 − 1024) / 2;
			// section_left_cap() carries it to the mapper as a left-aligned content width — a real-site audit)
			if ( preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/', $rcs, $rm ) && (float) $rm[1] >= 480 && (float) $rm[1] <= $max_px && self::cap_is_centred( $node, $rcls, $rcs ) ) { $best = self::cap_content_px( $node, (float) $rm[1] ); } }
		foreach ( $node->getElementsByTagName( '*' ) as $el ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( $cs === '' || ! preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/', $cs, $m ) ) { continue; }
			$px = self::cap_content_px( $el, (float) $m[1] );
			// A max-width on a TEXT LEAF (paragraph, heading, span, link, list item) is a typographic READING-
			// MEASURE cap (`max-w-xl`/`max-w-prose` on a `<p>` description), NOT the section's content band — the
			// band WRAPS the blocks (heading + copy + button). the burger source's hero puts `max-w-xl` (576px) on its
			// description `<p>` while its `<h2>` title is full-width; treating the `<p>`'s cap as the section
			// container pinned the whole hero to 576px and wrapped the 2-line title to 4 lines. The leaf keeps its
			// own measure via its block/subtitle CSS; the section container must not inherit it.
			if ( in_array( strtolower( (string) $el->tagName ), array( 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'span', 'a', 'li', 'blockquote', 'figcaption', 'label' ), true ) ) { continue; }
			// The section's real CONTENT-BAND cap is the widest CENTERED content wrapper that is NARROWER than
			// the page's outer container — a `max-w-5xl` card grid (1024), a `max-w-6xl` grid (1152), etc. The
			// outer full-width container (~1400px, `max-w-[1400px]`/`max-w-7xl`) is NOT the content band — the
			// bands INSIDE it are narrower and vary per section, and THAT is what a converted section/flexbox
			// must reproduce (else every grid renders 1400px = too wide). Two callers: $max_px=1300 (default)
			// finds the GRID band cap (the outer ~1400 wrapper is excluded, the 5xl/6xl grid wins); $max_px=1600
			// finds the section's OUTER CONTAINER (the ~1400 wrapper) for the section's own container_width.
			if ( $px < 480 || $px > $max_px ) { continue; }
			$cls = ' ' . strtolower( (string) $el->getAttribute( 'class' ) ) . ' ';
			$centered = self::cap_is_centred( $el, $cls, $cs );
			if ( ! $centered ) { continue; }
			// Skip a cap that lives INSIDE a multi-column grid/flex row — that's a COLUMN width (e.g. the
			// hero's `max-w-xl` text column inside `grid lg:grid-cols-2`), NOT the section's content band.
			// The real content band WRAPS the grid (`max-w-5xl mx-auto` around it). Pinning the section to a
			// column's 576px cramped the whole hero — the "container max-width not fixed" bug.
			$in_col = false;
			// (the section ROOT itself may be the grid — a `<section class="grid lg:grid-cols-[.46fr_.54fr]">` hero — so it is checked too)
			for ( $p = $el->parentNode; $p instanceof DOMElement; $p = ( $p === $node ) ? null : $p->parentNode ) {
				$pc = ' ' . strtolower( self::cls( $p ) ) . ' ';
				$pcs = (string) $p->getAttribute( 'data-sc-cs' );
				if ( preg_match( '/(?:^|\s)(?:sm:|md:|lg:|xl:|2xl:)?grid-cols-(?:[2-9]|\[)/', $pc )
					|| preg_match( '/grid-template-columns:\s*(?:[^;]*(?:\d+px|\dfr|minmax)[^;]*){2,}/i', $pcs )
					|| preg_match( '/grid-template-columns:\s*[0-9.]+px\s+[0-9.]+px/i', $pcs )
					|| ( ( strpos( $pc, ' flex ' ) !== false || strpos( $pc, ':flex-row ' ) !== false ) && strpos( $pc, 'flex-col' ) === false && count( self::el_children( $p ) ) >= 2 ) ) {
					$in_col = true; break;
				}
			}
			if ( $in_col ) { continue; }
			// A capped block that has CONTENT SIBLINGS is that block's OWN measure (a `max-w-4xl` heading group
			// beside a full-width card stack), not the section's band — the band is the wrapper that holds ALL the
			// section's content. Promoting the sibling cap pinned a 1392px section to 896 and squeezed its cards.
			$has_content_sibling = false;
			if ( $el->parentNode instanceof DOMElement ) {
				foreach ( self::el_children( $el->parentNode ) as $sib ) {
					if ( $sib === $el ) { continue; }
					if ( '' !== trim( self::text( $sib ) ) || $sib->getElementsByTagName( 'img' )->length || $sib->getElementsByTagName( 'video' )->length || $sib->getElementsByTagName( 'svg' )->length ) { $has_content_sibling = true; break; }
				}
			}
			if ( $has_content_sibling ) { continue; }
			// Take the WIDEST content cap in the section — the section's container must hold its widest band
			// (e.g. a `max-w-5xl` grid), NOT its narrowest one (a `max-w-3xl` centered heading/intro). Picking
			// the shallowest cap grabbed the heading's narrow intro width, so a 5xl/6xl content grid was pinned
			// to Narrow (768) and rendered cramped. The heading keeps its own narrower cap via its block_max_width.
			if ( $px > $best ) { $best = $px; }
		}
		// $best is now the section's OUTERMOST/widest content container (the source's real per-section
		// container — e.g. modfii's consistent 1400px), NOT an inner text cap. Every section pins to it, so the
		// converted site reproduces the source's ONE consistent container instead of a jumble of per-section
		// widths (768/896/1024/…). A section genuinely narrower than the site container pins its own (narrower)
		// width; the inner text caps a heading keeps via block_max_width. (map_container_width turns a
		// non-standard width like 1400 into a shared "Content 1400" preset via build_container_width_presets.)
		return $best;
	}

	/**
	 * The section's Container Width preference — normally the mapped content cap, BUT a full-bleed SPLIT HERO
	 * gets a FULL-WIDTH (100%) content band instead of Inherit.
	 *
	 * A full-VIEWPORT section (`min-h-screen`/`h-screen`/`min-height:100vh`) laid out as a MULTI-COLUMN grid with
	 * NO inner content cap is meant to span the viewport — its columns are true viewport fractions (a 2-column
	 * hero = ~50vw text + ~50vw media). Left on Inherit it falls back to the theme's global container (~1280),
	 * which shrinks each column so a large fluid heading overflows its column into the media column (the hero
	 * title-overlaps-image bug). Gated on min-h-screen + multicol + no inner cap so a normal `w-full` content
	 * section (almost every Tailwind section is `w-full`) or a single-column centred hero is NOT widened.
	 */
	private static function section_container_width_pref( $node ) {
		if ( self::is_fullbleed_split_hero( $node ) ) {
			return array( 'preset' => 'custom', 'custom' => array( 'custom_width' => array( 'value' => '100', 'unit' => '%' ) ) );
		}
		return self::map_container_width( self::section_content_max_width( $node, 1600.0 ) );
	}

	/**
	 * A FULL-BLEED SPLIT HERO: a full-VIEWPORT section (`min-h-screen`/`h-screen`/`min-height:100vh`) laid out as
	 * a MULTI-COLUMN grid with NO inner content cap. The source made it span the viewport (`w-full grid-cols-2`),
	 * so its columns are true viewport fractions (~50vw text + ~50vw media). It must NOT be boxed to the theme's
	 * global container — that shrinks each column, so a large fluid heading overflows into the media column (the
	 * hero title-overlaps-image bug). The mapper turns this into `is_fullwidth=true` + a 100% content band.
	 * Gated on min-h-screen + multicol + no inner cap so a normal `w-full` content section (nearly every Tailwind
	 * section is `w-full`) or a single-column centred hero is left alone.
	 */
	private static function is_fullbleed_split_hero( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return false; }
		$cls = ' ' . strtolower( self::cls( $node ) ) . ' ';
		$scs = (string) $node->getAttribute( 'data-sc-cs' );
		$full_vh = ( strpos( $cls, ' min-h-screen ' ) !== false || strpos( $cls, ' h-screen ' ) !== false
			|| preg_match( '/\bmin-h-\[100(?:v|d|s)h\]/', $cls )
			|| preg_match( '/(?:^|;)\s*min-height:\s*100(?:vh|dvh|svh)/', $scs ) );
		// …or a section that IS the grid and whose measured tracks span the viewport (`720px 720px` at 1440 — a split band with a
		// CSS-painted photo half): boxed to the container, its halves lost 48px each (a fixture from the feed)
		$edge = false;
		if ( ! $full_vh && preg_match( '/(?:^|;)\s*grid-template-columns:\s*([^;]+)/i', $scs, $gm ) ) {
			$sum = 0.0; $n = 0; foreach ( preg_split( '/\s+/', trim( $gm[1] ) ) as $t ) { if ( preg_match( '/^([0-9.]+)px$/', $t, $tm ) ) { $sum += (float) $tm[1]; $n++; } }
			$edge = ( $n >= 2 && $sum >= 1400 && ! preg_match( '/(?:^|;)\s*padding(?:-left)?:\s*[1-9]/i', $scs ) );
		}
		return ( $full_vh || $edge ) && self::section_is_multicol_grid( $node ) && self::section_content_max_width( $node, 1600.0 ) < 480;
	}

	/** The full-viewport hero's height for the section min_height — `min-h-screen`/`h-screen`/`min-height:100vh`
	 *  → '100vh'; `min-h-[NNvh]`/`h-[NNvh]`/computed `min-height:NNvh` → 'NNvh'. '' when none. */
	private static function fullbleed_hero_height( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return ''; }
		$cls = ' ' . strtolower( self::cls( $node ) ) . ' ';
		$scs = (string) $node->getAttribute( 'data-sc-cs' );
		if ( strpos( $cls, ' min-h-screen ' ) !== false || strpos( $cls, ' h-screen ' ) !== false ) { return '100vh'; }
		if ( preg_match( '/\b(?:min-)?h-\[([0-9.]+)(?:d|s)?vh\]/', $cls, $m ) ) { return $m[1] . 'vh'; }
		if ( preg_match( '/(?:^|;)\s*min-height:\s*([0-9.]+)(?:vh|dvh|svh)/', $scs, $m ) ) { return $m[1] . 'vh'; }
		return '';
	}

	/** The full-viewport hero's vertical alignment from its column's main-axis justification — a `flex-col`
	 *  column with `justify-center` centres its content vertically (the AI-page split-hero pattern). Maps to the
	 *  section's column_valign. Defaults to 'middle' (a full-viewport split hero is centred by convention). */
	private static function fullbleed_hero_valign( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return 'middle'; }
		foreach ( $node->getElementsByTagName( '*' ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$c = ' ' . strtolower( self::cls( $el ) ) . ' ';
			$col = ( strpos( $c, ' flex-col ' ) !== false ) || preg_match( '/flex-direction:\s*column/', (string) $el->getAttribute( 'data-sc-cs' ) );
			if ( ! $col ) { continue; }
			if ( strpos( $c, ' justify-start ' ) !== false || strpos( $c, ' justify-top ' ) !== false ) { return 'top'; }
			if ( strpos( $c, ' justify-end ' ) !== false ) { return 'bottom'; }
			if ( strpos( $c, ' justify-center ' ) !== false ) { return 'middle'; }
		}
		return 'middle';
	}

	private static function section_layers( $node ) {
		$out = array();
		foreach ( $node->childNodes as $ch ) {
			if ( $ch->nodeType !== XML_ELEMENT_NODE ) { continue; }
			$out[] = array(
				'cls'   => self::cls( $ch ),
				'style' => (string) $ch->getAttribute( 'style' ),
				'cs'    => (string) $ch->getAttribute( 'data-sc-cs' ),
			);
			if ( count( $out ) >= 8 ) { break; } // a section's band layers are the first few children; cap the scan
		}
		return $out;
	}

	/**
	 * Ambient-background detection (deterministic, high-precision). Scans a section's subtree for DECORATIVE
	 * particle/ambient LAYERS that a source names descriptively — `fg-leaves`, `fg-sakura`, `#grain`, a
	 * `.snow`/`.rain` overlay, etc. — and maps each to the NEAREST built-in Background Effect. The mapper
	 * turns the returned list into stacked `bg_effect` slots (petals + embers + grain …) on the section.
	 *
	 * This only fires on OBVIOUS, well-named layers (the 80% case): the element must both read as decorative
	 * (a <canvas>, aria-hidden, a layer-marker class like `fg`/`particle`/`layer`, or absolute/fixed position)
	 * AND carry an effect keyword. A bespoke WebGL scene with no naming hint (kage's three.js `#gl` garden,
	 * whose "embers" live only in JS) is deliberately NOT guessed here — that ambiguous long tail is where the
	 * AI tiers (local model / Claude) pick the closest effect or skip. Never forces a wrong guess.
	 */
	private static function detect_section_bg_effects( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return array(); }
		// keyword (word-boundary within a class/id token) → [ effect, variant ]. Order = specificity; the
		// `snow` engine renders petals/embers/ash/snow via its `variant` sub-option, so those share an effect.
		$map = array(
			'leaf|leaves|sakura|petal|petals|blossom|cherry' => array( 'snow', 'petals' ),
			'ember|embers|cinder|cinders'                    => array( 'snow', 'embers' ),
			'\bash\b|ashes'                                  => array( 'snow', 'ash' ),
			'snow|snowflake|flake|flakes'                    => array( 'snow', 'snow' ),
			'rain|rainfall|drizzle|droplet|droplets'         => array( 'rain', '' ),
			'starfield|stars'                                => array( 'starfield', '' ),
			'constellation'                                  => array( 'constellation', '' ),
			'confetti'                                       => array( 'confetti', '' ),
			'bubble|bubbles'                                 => array( 'bubbles', '' ),
			'firefly|fireflies'                              => array( 'fireflies', '' ),
			'meteor|meteors|shooting-?stars?'                => array( 'meteors', '' ),
			'particle|particles'                             => array( 'particles', '' ),
			'grain|film-?grain|noise'                        => array( 'noise', '' ),
			'matrix'                                         => array( 'matrix', '' ),
			'aurora'                                         => array( 'aurora', '' ),
			'borealis'                                       => array( 'borealis', '' ),
		);
		$layer_marker = '/(?:^|\s)(?:fg|fg-el|particles?|layers?|decor|backdrop|bg-scene|art-layers?|overlay|ambient)(?:-[a-z0-9]+)?(?:\s|$)/';
		$out  = array();
		$seen = array();
		$scanned = 0;
		foreach ( $node->getElementsByTagName( '*' ) as $el ) {
			if ( ++$scanned > 600 ) { break; } // bound the walk on huge sections
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$hay = ' ' . strtolower( trim( self::cls( $el ) . ' ' . (string) $el->getAttribute( 'id' ) ) ) . ' ';
			if ( ' ' === $hay ) { continue; }
			// Decorative gate — cheap checks first.
			$tag = strtolower( $el->tagName );
			$decor = ( 'canvas' === $tag )
				|| 'true' === strtolower( trim( (string) $el->getAttribute( 'aria-hidden' ) ) )
				|| (bool) preg_match( $layer_marker, $hay )
				|| in_array( self::sc_css( $el, 'position' ), array( 'absolute', 'fixed' ), true );
			if ( ! $decor ) { continue; }
			// A genuine ambient LAYER carries NO real content — it's an empty <canvas> or a particle-holder div.
			// An absolutely-positioned CONTENT element (a floating stat card `<article class="canopy leaf">`, a
			// glass badge) also clears the decor gate via its position, but its `leaf`/`petal`/`ember` token is a
			// card-VARIANT name, not an effect layer — injecting a petals/embers backdrop from it is wrong
			// (cloud-forest-sanctuaries sprayed pink petals out of its "canopy leaf" stat cards). Require the
			// element be content-LESS: no heading, no paragraph, and almost no text.
			if ( $el->getElementsByTagName( 'h1' )->length || $el->getElementsByTagName( 'h2' )->length
				|| $el->getElementsByTagName( 'h3' )->length || $el->getElementsByTagName( 'h4' )->length
				|| $el->getElementsByTagName( 'p' )->length ) { continue; }
			if ( mb_strlen( trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) ) ) > 24 ) { continue; }
			foreach ( $map as $pat => $spec ) {
				if ( preg_match( '/(?:^|[\s_-])(?:' . $pat . ')(?:[\s_-]|$)/', $hay ) ) {
					$key = $spec[0] . ':' . $spec[1];
					if ( isset( $seen[ $key ] ) ) { break; }         // de-dupe identical layers (leaves + sakura → one petals)
					$seen[ $key ] = true;
					$out[] = array( 'effect' => $spec[0], 'variant' => $spec[1] );
					break; // first (most specific) keyword wins for this element
				}
			}
			if ( count( $out ) >= 4 ) { break; } // auto-detection cap (users can add more by hand)
		}
		return $out;
	}

	/**
	 * AI-STRUCTURE PROTOTYPE — extractor half. Produce a COMPACT per-section signal summary for the AI
	 * structure classifier (to-ai.mjs → classify-structure.mjs). Deliberately tiny + DOM-derived so a small
	 * local model can reason about it: for each section root (SAME identity `section_roots` uses, so the
	 * verdicts align on the build pass) emit a stable `sig` (first heading text) plus the exact signals the
	 * three ambiguous calls turn on — dollar tokens (pricing-vs-stats), a period/feature-list (real plan
	 * pricing), and each video's framing (rounded card / column / cover → background-vs-content). The AI
	 * NEVER sees styles/values it must reproduce; only these signals. `structure_sig()` computes the SAME
	 * key on the build pass so a verdict can be looked up. Public so a standalone runner can call it.
	 *
	 * @param string $html rendered.html
	 * @return array { sections: [ { index, sig, heading, dollars:[], hasPeriod, hasFeatureList, videos:[{rounded,inColumn,cover}], bands } ] }
	 */
	public static function structure_summary( $html ) {
		$dom = self::load_dom( (string) $html );
		if ( ! $dom ) { return array( 'sections' => array() ); }
		$body = $dom->getElementsByTagName( 'body' )->item( 0 );
		if ( ! $body ) { return array( 'sections' => array() ); }
		$roots = self::section_roots( $body );
		$out = array();
		$i = 0;
		foreach ( $roots as $node ) {
			if ( ! ( $node instanceof DOMElement ) ) { continue; }
			$txt = (string) $node->textContent;
			$dollars = array();
			if ( preg_match_all( '/[$€£¥₹]\s?[\d][\d.,]*\s*(?:b|m|k|bn|mn|billion|million|thousand)?/ui', $txt, $dm ) ) {
				$dollars = array_slice( array_values( array_unique( array_map( 'trim', $dm[0] ) ) ), 0, 8 );
			}
			$has_period = (bool) preg_match( '#/\s*(?:mo|month|yr|year|wk|week)\b#i', $txt );
			$has_list   = ( $node->getElementsByTagName( 'ul' )->length + $node->getElementsByTagName( 'ol' )->length ) > 0;
			$videos = array();
			foreach ( $node->getElementsByTagName( 'video' ) as $v ) {
				if ( ! ( $v instanceof DOMElement ) ) { continue; }
				$vcls = ' ' . strtolower( self::cls( $v ) ) . ' ';
				$vcs   = (string) $v->getAttribute( 'data-sc-cs' );
				// COVER — object-cover / w-full+h-full class, OR the COMPUTED object-fit:cover (the fill is often
				// styled on the video via CSS, not a utility class — the class-only check under-reported it).
				$cover = ( strpos( $vcls, 'object-cover' ) !== false ) || ( strpos( $vcls, 'w-full' ) !== false && strpos( $vcls, 'h-full' ) !== false )
					|| (bool) preg_match( '/object-fit:\s*cover/i', $vcs );
				// BLEED — a full-viewport BACKDROP layer (the strong "background" signal): an inset-0 / w-full+h-full
				// / fullscreen-named box that is absolutely/fixed positioned, on the video OR a positioned ancestor.
				$brx       = '/\b(?:fullscreen|video-bg|bg-video|video-background|video-cover)\b/';
				$vpos      = self::sc_css( $v, 'position' );
				$self_abs  = ( 'absolute' === $vpos || 'fixed' === $vpos || strpos( $vcls, ' absolute ' ) !== false || strpos( $vcls, ' fixed ' ) !== false );
				$self_full = ( strpos( $vcls, 'inset-0' ) !== false ) || ( strpos( $vcls, 'w-full' ) !== false && strpos( $vcls, 'h-full' ) !== false ) || (bool) preg_match( $brx, $vcls );
				$bleed     = ( $self_abs && $self_full );
				$rounded = false; $in_col = false;
				for ( $a = $v->parentNode; ( $a instanceof DOMElement ); $a = $a->parentNode ) {
					if ( in_array( strtolower( $a->tagName ), array( 'section', 'main', 'body' ), true ) ) { break; }
					if ( $a->hasAttribute( 'data-sc-col' ) ) { $in_col = true; }
					$arad = self::sc_css( $a, 'border-radius' );
					if ( '' !== $arad && preg_match( '/^([0-9.]+)px/', $arad, $rm ) && (float) $rm[1] >= 24 ) { $rounded = true; }
					$ac    = ' ' . strtolower( self::cls( $a ) ) . ' ';
					$afull = ( strpos( $ac, 'inset-0' ) !== false ) || ( strpos( $ac, 'w-full' ) !== false && strpos( $ac, 'h-full' ) !== false ) || (bool) preg_match( $brx, $ac );
					$apos  = self::sc_css( $a, 'position' );
					if ( $afull && ( 'absolute' === $apos || 'fixed' === $apos || strpos( $ac, ' absolute ' ) !== false || strpos( $ac, ' fixed ' ) !== false ) ) { $bleed = true; }
				}
				$videos[] = array( 'rounded' => $rounded, 'inColumn' => $in_col, 'cover' => (bool) $cover, 'bleed' => (bool) $bleed );
			}
			// direct content-band count (the mega-section signal)
			$bands = 0;
			foreach ( $node->childNodes as $ch ) {
				if ( XML_ELEMENT_NODE === $ch->nodeType && self::is_content_band( $ch ) && ! self::is_decor_layer( $ch ) ) { $bands++; }
			}
			$out[] = array(
				'index'          => $i,
				'sig'            => self::structure_sig( $node ),
				'heading'        => self::structure_heading( $node ),
				'dollars'        => $dollars,
				'hasPeriod'      => $has_period,
				'hasFeatureList' => $has_list,
				'videos'         => $videos,
				'bands'          => $bands,
			);
			$i++;
		}
		return array( 'sections' => $out );
	}

	/** First heading text of a section (≤80 chars) — the human-readable label in the summary. */
	private static function structure_heading( $node ) {
		foreach ( array( 'h1', 'h2', 'h3' ) as $h ) {
			$n = ( $node instanceof DOMElement ) ? $node->getElementsByTagName( $h )->item( 0 ) : null;
			if ( $n ) { $t = trim( preg_replace( '/\s+/', ' ', (string) $n->textContent ) ); if ( '' !== $t ) { return mb_substr( $t, 0, 80 ); } }
		}
		return '';
	}

	/** AI-STRUCTURE PROTOTYPE — consumer half. Verdicts (sig → {pricing, video_role, kind}) from the classifier,
	 *  loaded by the bundle importer from `ai-structure.json` when the AI-assist flag is on. ADVISORY: used only
	 *  to correct the two ambiguous recognizer calls (pricing-vs-stats, video background-vs-content); the
	 *  heuristics stay the fallback + validator. Empty = off (default), so the deterministic path is unchanged. */
	private static $ai_structure = array();

	/** Raw source HTML of the conversion in flight — stashed by html_to_mapping so per-node readers can reach
	 *  the <style> sheet (e.g. a framed clip's mask defined in a custom class rule). Empty outside a conversion. */
	private static $cur_html = '';

	/** Install the classifier's verdicts (called by the bundle importer). `$verdicts` = the decoded
	 *  ai-structure.json `sections` array. Keyed by `sig` for O(1) lookup during the walk. */
	public static function set_ai_structure( $verdicts ) {
		self::$ai_structure = array();
		if ( ! is_array( $verdicts ) ) { return; }
		foreach ( $verdicts as $v ) {
			if ( is_array( $v ) && ! empty( $v['sig'] ) ) { self::$ai_structure[ (string) $v['sig'] ] = $v; }
		}
	}

	/** The AI verdict for the section an element sits in — walk up to the nearest `<section>` (the common
	 *  section-root shape) and match its `structure_sig`. array() when no verdict (→ heuristics decide). */
	private static function ai_verdict_for( $el ) {
		if ( ! self::$ai_structure || ! ( $el instanceof DOMElement ) ) { return array(); }
		for ( $p = $el; $p instanceof DOMElement; $p = $p->parentNode ) {
			if ( 'section' === strtolower( $p->tagName ) ) {
				$sig = self::structure_sig( $p );
				return isset( self::$ai_structure[ $sig ] ) ? self::$ai_structure[ $sig ] : array();
			}
		}
		return array();
	}

	/** A STABLE per-section key for aligning an AI verdict back to the section on the build pass: the first
	 *  heading slug, else a short hash of the section's text. Same on extract + build (same node identity). */
	public static function structure_sig( $node ) {
		$h = self::structure_heading( $node );
		if ( '' !== $h ) { return substr( preg_replace( '/[^a-z0-9]+/', '-', strtolower( $h ) ), 0, 40 ); }
		$t = trim( preg_replace( '/\s+/', ' ', ( $node instanceof DOMElement ) ? (string) $node->textContent : '' ) );
		return 't-' . substr( md5( mb_substr( $t, 0, 200 ) ), 0, 12 );
	}

	private static function section_roots( $body ) {
		// Scan from <body>, not <main>. walk_section_roots() dives THROUGH <main> as a transparent
		// wrapper (it only claims <section> + hero <header> and skips nav/footer), so a body scope still
		// finds every in-<main> section AND catches a hero <header> that sits OUTSIDE <main> — the common
		// AI-page shape `body > nav, header(hero + full-bleed bg video/image), main > sections…`. Scoping
		// to <main> silently dropped that hero band (and its background video) whenever a <main> existed.
		$scope = $body;
		// The masthead header (so a hero <header> that ISN'T the masthead can be folded in as a body band).
		$masthead      = $body->ownerDocument ? self::header_root( $body->ownerDocument ) : null;
		$masthead_path = $masthead ? (string) $masthead->getNodePath() : '';
		$out = array();
		self::walk_section_roots( $scope, $masthead_path, $out );
		return self::dedupe_repeated_app( $out );
	}

	/**
	 * Guard against a capture that serialized the app MORE THAN ONCE.
	 *
	 * Some JS sources (React/Vite SPAs — measured on a second AI-page generator) end up with the whole app rendered several
	 * times inside a single `#root` by the time `rendered.html` is serialized: the live DOM has one
	 * `<main>`, the captured file has 4 (and one source had 10). The JS extractor reads the LIVE DOM so
	 * it never saw this; the PHP engine reads `rendered.html` and faithfully converted the corruption —
	 * a 6-section page became 24 sections and rendered 25,000px tall against a 6,589px source.
	 * Measured: 7 of 120 sites in the a second AI-page generator corpus, 3x-10x.
	 *
	 * Fixing the capture is the real fix, but the converter must not emit a 4x page whatever it is
	 * handed. This detects only the exact corruption signature — the ENTIRE root list repeating as a
	 * contiguous block with byte-identical markup — and keeps the first period. A page that merely
	 * repeats one band (two identical CTAs, say) is NOT periodic overall, so it is left alone.
	 *
	 * @param array $roots section roots in document order
	 * @return array
	 */
	private static function dedupe_repeated_app( array $roots ) {
		$n = count( $roots );
		if ( $n < 4 ) { return $roots; }  // need at least 2 full periods to call it a repeat

		// Signature per root. INLINE STYLE IS STRIPPED before hashing: JS sources stamp an animation
		// END-STATE inline (`style="opacity: 1; transform: none;"`) and the copies are serialized at
		// different points in that animation, so byte-identical comparison missed real duplicates —
		// one source repeated a 10-section block 5 times and only matched once styles were normalized.
		$sig = array();
		foreach ( $roots as $node ) {
			$doc   = $node->ownerDocument;
			$html  = $doc ? (string) $doc->saveHTML( $node ) : '';
			$html  = preg_replace( '/\s+style="[^"]*"/i', '', $html );
			$sig[] = md5( preg_replace( '/\s+/', ' ', $html ) );
		}
		// Smallest period p (a proper divisor of n) for which the list is p-periodic.
		for ( $p = 1; $p <= intdiv( $n, 2 ); $p++ ) {
			if ( 0 !== $n % $p ) { continue; }
			$periodic = true;
			for ( $i = $p; $i < $n; $i++ ) {
				if ( $sig[ $i ] !== $sig[ $i - $p ] ) { $periodic = false; break; }
			}
			if ( $periodic ) {
				return array_slice( $roots, 0, $p );
			}
		}
		return $roots;
	}

	/**
	 * Pre-order DFS (= document order) that claims each top-level <section> AND each hero <header>
	 * (a full-viewport <header> that is NOT the masthead — AI-page-style), diving through plain
	 * wrappers but never into a claimed band or chrome (nav/footer/masthead). Mirrors the capture
	 * service folding hero headers into its section list.
	 *
	 * @param DOMNode $node
	 * @param string  $masthead_path node-path of the masthead header (skip it), '' if none
	 * @param array   $out
	 */
	private static function walk_section_roots( $node, $masthead_path, array &$out ) {
		foreach ( $node->childNodes as $ch ) {
			if ( XML_ELEMENT_NODE !== $ch->nodeType ) { continue; }
			$tag = strtolower( $ch->tagName );
			if ( 'section' === $tag ) { $out[] = $ch; continue; }                 // claim; don't descend (nested sections ignored)
			if ( 'header' === $tag ) {
				if ( ( '' === $masthead_path || (string) $ch->getNodePath() !== $masthead_path ) && self::is_hero_header( $ch ) ) {
					$out[] = $ch;                                                  // a hero header = body content
				}
				continue;                                                          // never descend into a <header>
			}
			if ( 'footer' === $tag || 'nav' === $tag ) { continue; }              // chrome — never a body band
			// A full-viewport <main>/<div> HERO built WITHOUT a <section> tag (an AI page's `<main class="min-h-[120vh]
			// flex-col items-center">` hero, or a `<div class="min-h-screen">` hero) → claim it as a band. Guarded:
			// must be full-viewport-tall AND lead with a heading (is_hero_header), AND contain NO nested <section>
			// (else it's a page-wrapper <main> holding real sections — dive in for those instead).
			// SECTION-LESS content container → SEGMENT into bands. Two triggers: (a) a semantic <main> with no
			// <section> tags is the page's content wrapper — its bands are plain divs (the-global-destination's
			// `<main class="fractal-container pt-32">` holds the WHOLE page and isn't viewport-tall, so gating on a
			// hero yielded ZERO sections); (b) a full-viewport <div>/<main> hero that also holds feature/CTA/gallery
			// bands (payment-operations lost its 3-card grid). When it splits into >=2 content bands, claim EACH; a
			// genuine single hero (no inner bands) stays whole; a non-hero <main> that didn't segment is dived into.
			if ( 0 === $ch->getElementsByTagName( 'section' )->length
				&& ( 'main' === $tag || ( in_array( $tag, array( 'main', 'div' ), true ) && self::is_hero_header( $ch ) ) ) ) {
				$bands = self::segment_bands( $ch );
				if ( count( $bands ) >= 2 ) {
					// The CONTAINER's own vertical padding (a `pt-[25vh]` on the <main> = 225px above the hero copy) belongs to
					// the bands it wraps: top → the first band, bottom → the last. Without this the first band's section only
					// got the overlay-header minimum (82px) and the hero sat 143px too high. Stamped into the band's own
					// computed padding so every later reader (Pass #5 rhythm, heroTopPad minimum) sees one value.
					self::band_inherit_padding( $bands[0], $ch, 'top' );
					self::band_inherit_padding( $bands[ count( $bands ) - 1 ], $ch, 'bottom' );
					self::band_padding_handed_over( $ch ); // …and the container itself no longer carries it (main_style would pad #main a second time)
					self::stamp_band_placement( $bands, $ch ); // a GRID container's bands keep their column placement (col-start / col-span)
					$bands = self::group_canvas_rows( $bands, $ch ); // …and bands that share a grid ROW become one flex-row band (side by side)
					foreach ( $bands as $band ) { $band->setAttribute( 'data-sc-band-of', strtolower( $ch->tagName ) ); $out[] = $band; }
					continue;
				}
				if ( 1 === count( $bands ) ) { $out[] = $bands[0]; continue; }   // single content band -> claim it
				if ( self::is_hero_header( $ch ) ) { $out[] = $ch; continue; }
				// A <main> with NO detectable bands still holds the page content -> claim it whole rather than dive-
				// and-find-nothing (which left the-global-destination-style pages at ZERO sections). A <div> falls
				// through to dive (it may be a wrapper on the way to real content).
				// (…a <main> holding nothing but page-level decor layers — no text, no media — is no band: its glow rides as the
				// theme main's pseudo-layer, page_decor_layers_css)
				if ( 'main' === $tag && ( '' !== trim( self::text( $ch ) ) || $ch->getElementsByTagName( 'img' )->length || $ch->getElementsByTagName( 'video' )->length || $ch->getElementsByTagName( 'svg' )->length ) ) { $out[] = $ch; continue; }
			}
			self::walk_section_roots( $ch, $masthead_path, $out );                // dive through wrappers to reach sections
		}
	}

	/**
	 * A section-less page whose content container is a GRID (a 12-track "fractal" canvas: the hero copy on tracks 1–7, a card
	 * on 8–11, the next on 2–6 …) places each band by COLUMN, not only by row. Stamp every band with its measured placement
	 * inside the container's content box — `data-sc-band-place="frac:F;x:X;w:W"` (F = the band's width fraction, X = its left
	 * offset in px, W = the content width = the tracks + gaps) — so the mapper can keep the band at its column (width + left
	 * offset) instead of stretching every band across the page. Only a grid container with px tracks; a flow container stamps
	 * nothing. JS twin: bandPlacementOf.
	 */
	/**
	 * A GRID canvas places bands SIDE BY SIDE: the hero copy on tracks 1–7 and a card on 8–11 share the first grid row, the
	 * next two cards the second. Claimed one by one they stacked into four full-width sections. Group the bands that share a
	 * row (their measured track-y / track-h spans overlap, as bento_split does) into ONE synthetic flex-row wrapper — the
	 * container's gap, the cells' own top margins kept (a `mt-40` card sits lower than the hero beside it), each cell's
	 * column offset beyond the previous cell (a col-start gap) as its own margin-left — so the section machinery builds a
	 * row of two placed columns. A row of one band stays as it was. JS twin: groupCanvasRows.
	 */
	private static function group_canvas_rows( array $bands, $container ) {
		if ( count( $bands ) < 2 || ! ( $container instanceof DOMElement ) || ! $container->ownerDocument ) { return $bands; }
		$ccs = (string) $container->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?grid/i', $ccs ) ) { return $bands; }
		$geo = array();
		foreach ( $bands as $i => $b ) {
			$st = (string) $b->getAttribute( 'data-sc-band-place' ); $bcs = (string) $b->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/frac:([0-9.]+);x:(-?[0-9.]+);w:([0-9.]+)/', $st, $m ) ) { return $bands; } // every band must be placed
			$y = preg_match( '/(?:^|;)\s*track-y:\s*(-?[0-9.]+)/', $bcs, $ym ) ? (float) $ym[1] : 0.0;
			$h = preg_match( '/(?:^|;)\s*track-h:\s*([0-9.]+)/', $bcs, $hm ) ? (float) $hm[1] : 0.0;
			$mt = (float) ( self::el_margin( $b )['top'] ?? 0 );
			$geo[ $i ] = array( 'frac' => (float) $m[1], 'x' => (float) $m[2], 'w' => (float) $m[3], 'y' => $y - $mt, 'h' => $h + $mt ); // the grid ROW starts above the band's own top margin
		}
		$gap = (float) self::grid_gap_px( $container );
		$rows = array();
		foreach ( $bands as $i => $b ) {
			$placed = false;
			foreach ( $rows as &$r ) {
				$ov = min( $r['y'] + $r['h'], $geo[ $i ]['y'] + $geo[ $i ]['h'] ) - max( $r['y'], $geo[ $i ]['y'] );
				$x_ok = true; foreach ( $r['i'] as $j ) { $a0 = $geo[ $j ]['x']; $a1 = $a0 + $geo[ $j ]['frac'] * $geo[ $j ]['w']; $b0 = $geo[ $i ]['x']; $b1 = $b0 + $geo[ $i ]['frac'] * $geo[ $i ]['w']; if ( min( $a1, $b1 ) - max( $a0, $b0 ) > 8 ) { $x_ok = false; } } // side by side, never overlapping columns
				if ( $x_ok && ( abs( $r['y'] - $geo[ $i ]['y'] ) <= 8 || ( $geo[ $i ]['h'] > 0 && $r['h'] > 0 && $ov >= 0.5 * min( $r['h'], $geo[ $i ]['h'] ) ) ) ) { $r['i'][] = $i; $r['y'] = min( $r['y'], $geo[ $i ]['y'] ); $r['h'] = max( $r['h'], $geo[ $i ]['h'] ); $placed = true; break; }
			}
			unset( $r );
			if ( ! $placed ) { $rows[] = array( 'y' => $geo[ $i ]['y'], 'h' => $geo[ $i ]['h'], 'i' => array( $i ) ); }
		}
		if ( count( $rows ) === count( $bands ) ) { return $bands; } // every band its own row: nothing to group
		$doc = $container->ownerDocument; $out = array();
		foreach ( $rows as $r ) {
			if ( 1 === count( $r['i'] ) ) { $out[] = $bands[ $r['i'][0] ]; continue; }
			usort( $r['i'], function ( $a, $b ) use ( $geo ) { return $geo[ $a ]['x'] <=> $geo[ $b ]['x']; } );
			$first = $bands[ $r['i'][0] ];
			$wrap = $doc->createElement( 'div' );
			$wrap->setAttribute( 'class', 'sc-canvas-row' );
			$wrap->setAttribute( 'data-sc-cs', 'display:flex;flex-direction:row;align-items:flex-start;gap:' . round( $gap ) . 'px;padding:' . round( (float) ( self::sc_padding_box( $first )['top'] ?? 0 ) ) . 'px 0px 0px 0px' );
			// the source stacked its bands on phones (col-span-12) and kept them side by side on tablets: one / N measured tracks
			// (tracks_count_at reads a grid-template-columns stamp, whichever display the wrapper has)
			$wrap->setAttribute( 'data-sc-cs-sm', 'flex-direction:column;grid-template-columns:1fr' );
			$wrap->setAttribute( 'data-sc-cs-md', 'grid-template-columns:' . implode( ' ', array_fill( 0, count( $r['i'] ), '1fr' ) ) );
			$first->parentNode->insertBefore( $wrap, $first );
			$prev_end = null;
			foreach ( $r['i'] as $j ) {
				$b = $bands[ $j ]; $g = $geo[ $j ];
				$bcs = (string) $b->getAttribute( 'data-sc-cs' );
				$bcs = preg_replace( '/(?:^|;)\s*padding(?:-(?:top|right|bottom|left))?:[^;]*/i', '', $bcs ); // the container's inherited padding rides the row wrapper
				// a column offset beyond the previous cell's edge (+ the grid gap) → the cell's own left margin
				$off = ( null === $prev_end ) ? $g['x'] : ( $g['x'] - $prev_end - $gap );
				if ( $off > 4 ) { $bcs = trim( $bcs, '; ' ) . ';margin-left:' . round( $off / $g['w'] * 100, 2 ) . '%'; } // as a share of the canvas width, so the offset scales with the container
				$prev_end = $g['x'] + $g['frac'] * $g['w'];
				$b->setAttribute( 'data-sc-cs', ltrim( $bcs, ';' ) );
				$b->removeAttribute( 'data-sc-band-place' );
				$wrap->appendChild( $b );
			}
			$out[] = $wrap;
		}
		return $out;
	}

	/** The stamped `data-sc-band-place` → { frac, x, w } or array() (a full-width band, or no grid canvas). */
	private static function band_placement_of( $node ) {
		if ( ! ( $node instanceof DOMElement ) ) { return array(); }
		$st = (string) $node->getAttribute( 'data-sc-band-place' );
		if ( '' === $st || ! preg_match( '/frac:([0-9.]+);x:(-?[0-9.]+);w:([0-9.]+)/', $st, $m ) ) { return array(); }
		$frac = (float) $m[1]; $x = (float) $m[2]; $w = (float) $m[3];
		if ( $w <= 0 || $frac <= 0 || ( $frac >= 0.97 && $x <= 4 ) ) { return array(); } // full-width = nothing to place
		return array( 'frac' => $frac, 'x' => $x, 'w' => $w );
	}

	private static function stamp_band_placement( array $bands, $container ) {
		if ( ! ( $container instanceof DOMElement ) ) { return; }
		$ccs = (string) $container->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?grid/i', $ccs ) ) { return; }
		$tpl = trim( (string) self::sc_css( $container, 'grid-template-columns' ) ); $toks = ( '' !== $tpl ) ? preg_split( '/\s+/', $tpl ) : array();
		$w = 0.0; $n = 0; foreach ( $toks as $t ) { if ( preg_match( '/^([0-9.]+)px$/', $t, $tm ) ) { $w += (float) $tm[1]; $n++; } }
		if ( $n < 2 ) { return; }
		$w += (float) self::grid_gap_px( $container ) * ( $n - 1 );
		if ( $w <= 0 ) { return; }
		foreach ( $bands as $band ) {
			if ( ! ( $band instanceof DOMElement ) ) { continue; }
			$bcs = (string) $band->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/(?:^|;)\s*track-frac:\s*([0-9.]+)/', $bcs, $fm ) ) { continue; }
			$x = preg_match( '/(?:^|;)\s*track-x:\s*(-?[0-9.]+)/', $bcs, $xm ) ? (float) $xm[1] : 0.0;
			$band->setAttribute( 'data-sc-band-place', 'frac:' . round( (float) $fm[1], 3 ) . ';x:' . round( $x ) . ';w:' . round( $w ) );
		}
	}

	/** The container handed its vertical padding to its first / last band: zero it on the container's own stamp + utility classes,
	 *  so the #main carry (main_style reads the source <main>'s pt / pb) does not pad the page a second time. */
	private static function band_padding_handed_over( $container ) {
		if ( ! ( $container instanceof DOMElement ) ) { return; }
		$bp = self::sc_padding_box( $container );
		$cs = (string) $container->getAttribute( 'data-sc-cs' );
		$cs = preg_replace( '/(?:^|;)\s*padding(?:-(?:top|right|bottom|left))?:[^;]*/i', '', $cs );
		$cs = trim( $cs, '; ' ) . ';padding:0px ' . round( (float) $bp['right'] ) . 'px 0px ' . round( (float) $bp['left'] ) . 'px';
		$container->setAttribute( 'data-sc-cs', ltrim( $cs, ';' ) );
		$cls = preg_replace( '/(?:^|\s)(?:[a-z0-9]+:)?p[ty]-(?:\[[^\]]+\]|[0-9.]+)(?=\s|$)/', ' ', ' ' . self::cls( $container ) . ' ' );
		$container->setAttribute( 'class', trim( preg_replace( '/\s+/', ' ', $cls ) ) );
	}

	/** Add the container's padding-$side to a band's own computed padding (data-sc-cs), so a segmented band carries the
	 *  space its wrapper gave it. Only a positive container padding; the band's other three sides are kept. */
	private static function band_inherit_padding( $band, $container, $side ) {
		if ( ! ( $band instanceof DOMElement ) || ! ( $container instanceof DOMElement ) ) { return; }
		$cp = self::sc_padding_box( $container ); $add = (float) ( $cp[ $side ] ?? 0 );
		if ( $add <= 0 ) { return; }
		$bp = self::sc_padding_box( $band ); $bp[ $side ] = (float) ( $bp[ $side ] ?? 0 ) + $add;
		$cs = (string) $band->getAttribute( 'data-sc-cs' );
		$cs = preg_replace( '/(?:^|;)\s*padding(?:-(?:top|right|bottom|left))?:[^;]*/i', '', $cs );
		$cs = trim( $cs, '; ' ) . ';padding:' . round( $bp['top'] ) . 'px ' . round( $bp['right'] ) . 'px ' . round( $bp['bottom'] ) . 'px ' . round( $bp['left'] ) . 'px';
		$band->setAttribute( 'data-sc-cs', ltrim( $cs, ';' ) );
	}

	/** An element's computed padding box { top, right, bottom, left } in px from its data-sc-cs (shorthand or per side). */
	private static function sc_padding_box( $el ) {
		$out = array( 'top' => 0.0, 'right' => 0.0, 'bottom' => 0.0, 'left' => 0.0 );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*padding:\s*([^;]+)/i', $cs, $m ) ) {
			$v = array_map( 'floatval', preg_split( '/\s+/', trim( $m[1] ) ) );
			$t = $v[0] ?? 0; $r = $v[1] ?? $t; $b = $v[2] ?? $t; $l = $v[3] ?? $r;
			$out = array( 'top' => $t, 'right' => $r, 'bottom' => $b, 'left' => $l );
		}
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $sd ) { if ( preg_match( '/(?:^|;)\s*padding-' . $sd . ':\s*([\d.]+)px/i', $cs, $m ) ) { $out[ $sd ] = (float) $m[1]; } }
		return $out;
	}

	/**
	 * Segment a section-less full-viewport container (a <main>/<div> hero that ALSO holds feature / CTA /
	 * gallery bands as sibling divs) into its content BANDS, so claiming the whole thing as one section no
	 * longer drops everything after the first screen. Returns the direct-child content bands when there are
	 * >=2, else array() (caller then claims the container whole = a genuine single hero). Decorative full-
	 * bleed bg / glow / scrim layers + empty spacers are skipped; a lone wrapper is descended once.
	 *
	 * @param DOMElement $el
	 * @param int        $depth
	 * @return array
	 */
	private static function segment_bands( $el, $depth = 0 ) {
		if ( ! ( $el instanceof DOMElement ) || $depth > 2 ) { return array(); }
		$content = array();
		foreach ( $el->childNodes as $ch ) {
			if ( XML_ELEMENT_NODE !== $ch->nodeType ) { continue; }
			$tag = strtolower( $ch->tagName );
			if ( ! in_array( $tag, array( 'div', 'section', 'article', 'main', 'header', 'figure', 'ul', 'ol' ), true ) ) { continue; }
			if ( self::is_decor_layer( $ch ) ) { continue; }
			if ( self::is_content_band( $ch ) ) { $content[] = $ch; }
		}
		if ( count( $content ) >= 2 ) { return $content; }
		if ( count( $content ) === 1 ) {
			$inner = self::segment_bands( $content[0], $depth + 1 );
			return count( $inner ) >= 2 ? $inner : array();
		}
		return array();
	}

	/** A DECORATIVE full-bleed layer (absolute/fixed bg image / gradient glow / scrim) — no heading and
	 *  almost no text — NOT a content band (it rides as the section background instead). */
	private static function is_decor_layer( $el ) {
		$c = ' ' . strtolower( self::cls( $el ) ) . ' ';
		// the utility, or the COMPUTED position (a plain-CSS `.optical-flare{position:absolute}` glow — a feed finding)
		if ( strpos( $c, ' absolute ' ) === false && strpos( $c, ' fixed ' ) === false && ! preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', (string) $el->getAttribute( 'data-sc-cs' ) ) ) { return false; }
		foreach ( array( 'h1', 'h2', 'h3', 'h4' ) as $h ) { if ( $el->getElementsByTagName( $h )->length ) { return false; } }
		$txt = trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) );
		return mb_strlen( $txt ) < 30;
	}

	/** A real CONTENT band? — carries a heading, OR is a grid / multi-card structure, OR holds substantial
	 *  content (>=3 media/paragraphs, or >=120 chars of text). Used by segment_bands. */
	private static function is_content_band( $el ) {
		foreach ( array( 'h1', 'h2', 'h3', 'h4' ) as $h ) { if ( $el->getElementsByTagName( $h )->length ) { return true; } }
		// A <figure> (semantic self-contained media) or a band holding a PROMINENT object-fit image is real
		// CONTENT — a hero product screenshot is very often a lone `<figure><img object-cover>` with no heading
		// or copy, which the ">=3 media/para" rule below would drop (plausible.io's dashboard hero vanished this
		// way). is_decor_layer already removed absolute/fixed background layers before this, so an <img> that
		// survives to here is foreground content, not a backdrop.
		if ( 'figure' === strtolower( $el->tagName ) || $el->getElementsByTagName( 'figure' )->length ) { return true; }
		foreach ( $el->getElementsByTagName( 'img' ) as $im ) {
			$ic = ' ' . strtolower( self::cls( $im ) ) . ' ';
			if ( strpos( $ic, ' object-cover ' ) !== false || strpos( $ic, ' object-contain ' ) !== false ) { return true; }
		}
		$c  = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/\bgrid-cols-[2-9]\b/', $c ) || strpos( $cs, 'display:grid' ) !== false ) { return true; }
		$media = $el->getElementsByTagName( 'img' )->length + $el->getElementsByTagName( 'video' )->length;
		$paras = $el->getElementsByTagName( 'p' )->length;
		if ( ( $media + $paras ) >= 3 ) { return true; }
		$txt = trim( preg_replace( '/\s+/', ' ', (string) $el->textContent ) );
		if ( mb_strlen( $txt ) >= 120 ) { return true; }
		// A BOXED CARD with any text (a sculpted tile holding a label + a caption, no heading) is content too — on a grid canvas
		// it is a whole band, and dropping it lost a tile of the composition. The skin may sit on the band or its single wrapper.
		if ( '' !== $txt ) {
			$cands = array( $el ); $kids = self::el_children( $el ); if ( 1 === count( $kids ) ) { $cands[] = $kids[0]; }
			foreach ( $cands as $cand ) {
				$ccs = (string) $cand->getAttribute( 'data-sc-cs' );
				$fill = preg_match( '/(?:^|;)\s*background-color:\s*([^;]+)/i', $ccs, $bm ) && ! preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent|\/\s*0\s*\)/i', $bm[1] );
				$shadow = preg_match( '/(?:^|;)\s*box-shadow:\s*(?!none)[^;]+/i', $ccs );
				$radius = preg_match( '/(?:^|;)\s*border-radius:\s*([0-9.]+)px/i', $ccs, $rm ) && (float) $rm[1] >= 8;
				if ( ( $fill && $radius ) || $shadow ) { return true; }
			}
		}
		return false;
	}

	/**
	 * Element-recognizer REGISTRY — the expandable heart of the converter. Each recognizer CLAIMS a DOM
	 * element (so the walker won't descend into it) and turns it into a block. Built-ins cover headings,
	 * paragraphs, buttons, images, card grids and custom widgets; teach the converter a NEW UnysonPlus
	 * shortcode by calling register_recognizer() with a `match` + `build` callable — no core edits. Highest
	 * priority runs first; build() may return one block, a list of blocks, or null (claimed, nothing emitted).
	 *
	 *   match( DOMElement $el, string $tag, array $rules ) : bool
	 *   build( DOMElement $el, string $tag, array $rules ) : array|null   // a {t,role,…} block, a list, or null
	 */
	private static $recognizers        = array();
	private static $recognizers_sorted = false;

	/** Register an element recognizer (priority: higher runs first; the built-ins span 25–90). */
	public static function register_recognizer( $id, $priority, $match, $build ) {
		self::$recognizers[ $id ]   = array( 'id' => $id, 'priority' => (int) $priority, 'match' => $match, 'build' => $build );
		self::$recognizers_sorted   = false;
	}

	/** The recognizer set, highest-priority first (registers the built-ins on first use). */
	private static function recognizers() {
		if ( ! self::$recognizers ) { self::register_builtin_recognizers(); }
		if ( ! self::$recognizers_sorted ) {
			uasort( self::$recognizers, function ( $a, $b ) { return $b['priority'] - $a['priority']; } );
			self::$recognizers_sorted = true;
		}
		return self::$recognizers;
	}

	/** The built-in recognizers (the original hardcoded chain, now table-driven + extensible). */
	/**
	 * A free-form ABSOLUTE-POSITIONED collage stage: a `<div>` that establishes a positioning context
	 * (position:relative, or a min-height stage) whose direct children are ≥2 absolutely-positioned
	 * CONTENT cards. The absolutes must DOMINATE the stage (≥60% of children) so a hero with a single
	 * floating badge over flow content is NOT misread as a collage.
	 */
	private static function is_absolute_collage( $el, $tag ) {
		if ( ! ( $el instanceof DOMElement ) || 'div' !== $tag ) { return false; }
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$is_stage = ( false !== stripos( $cs, 'position: relative' ) ) || ( false !== stripos( $cs, 'position:relative' ) )
			|| (bool) preg_match( '/\brelative\b/', $cls )
			|| (bool) preg_match( '/\bmin-h-\[/', $cls )
			|| ( (bool) preg_match( '/(?:^|;)\s*min-height:\s*[1-9]/i', $cs ) );
		if ( ! $is_stage ) { return false; }
		$abs = 0; $content = 0; $kids = 0;
		foreach ( self::el_children( $el ) as $k ) {
			$kids++;
			$kcs  = (string) $k->getAttribute( 'data-sc-cs' );
			$kcls = ' ' . strtolower( self::cls( $k ) ) . ' ';
			$is_abs = ( false !== stripos( $kcs, 'position: absolute' ) ) || ( false !== stripos( $kcs, 'position:absolute' ) ) || (bool) preg_match( '/\babsolute\b/', $kcls );
			if ( ! $is_abs ) { continue; }
			$abs++;
			$has_head = false;
			for ( $i = 1; $i <= 6; $i++ ) { if ( $k->getElementsByTagName( 'h' . $i )->length ) { $has_head = true; break; } }
			$txt = trim( preg_replace( '/\s+/', ' ', self::text( $k ) ) );
			if ( $has_head || $k->getElementsByTagName( 'p' )->length || mb_strlen( $txt ) >= 12 ) { $content++; }
		}
		return ( $abs >= 2 && $content >= 2 && $abs >= max( 2, (int) ceil( $kids * 0.6 ) ) );
	}

	/**
	 * Read a card's absolute OFFSETS (top/right/bottom/left) → a map of side => CSS length. Tailwind
	 * position utilities: arbitrary `left-[4%]` / `top-[14rem]`, scale `top-4` (N×0.25rem), zero `bottom-0`,
	 * negatives `-top-4`. Falls back to the data-sc-cs longhand (`left:64px`) for any side the classes omit.
	 */
	private static function collage_offsets( $el ) {
		$out = array();
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $side ) {
			if ( preg_match( '/(?:^|\s)(-)?' . $side . '-\[([^\]]+)\]/', $cls, $m ) ) {
				$v = trim( $m[2] );
				if ( '' !== $v ) { $out[ $side ] = ( $m[1] ? '-' : '' ) . $v; continue; }
			}
			if ( preg_match( '/(?:^|\s)(-)?' . $side . '-(\d+(?:\.\d+)?)(?:\s|$)/', $cls, $m ) ) {
				$px = (float) $m[2] * 4;
				$out[ $side ] = ( $m[1] && $px > 0 ? '-' : '' ) . ( 0.0 === $px ? '0' : ( rtrim( rtrim( sprintf( '%.2f', $px ), '0' ), '.' ) ) . 'px' );
				continue;
			}
		}
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $side ) {
			if ( isset( $out[ $side ] ) ) { continue; }
			if ( preg_match( '/(?:^|;)\s*' . $side . ':\s*(-?[0-9.]+(?:px|%|rem|em|vh|vw))/i', $cs, $m ) ) { $out[ $side ] = $m[1]; }
		}
		return $out;
	}

	/**
	 * Build the `stage` block for an absolute-positioned collage: the min-height stage + one entry per
	 * absolutely-positioned card carrying its native inner BLOCKS (collected independently — no cross-card
	 * merge), its glass SKIN (blob radius / backdrop / shadow / fill / padding, via read_card_skin), its
	 * OFFSETS, and its width. The mapper's `stage` builder renders these as absolutely-placed glass cards.
	 */
	private static function absolute_collage_build( $el, $tag, $rules ) {
		$minh = 0.0;
		$cls  = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( preg_match( '/\bmin-h-\[([0-9.]+)px\]/', $cls, $m ) ) { $minh = (float) $m[1]; }
		elseif ( preg_match( '/\bmin-h-\[([0-9.]+)rem\]/', $cls, $m ) ) { $minh = (float) $m[1] * 16; }
		if ( $minh <= 0 ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( preg_match( '/(?:^|;)\s*min-height:\s*([0-9.]+)px/i', $cs, $mm ) ) { $minh = (float) $mm[1]; }
		}
		$cards = array();
		foreach ( self::el_children( $el ) as $k ) {
			$kcs  = (string) $k->getAttribute( 'data-sc-cs' );
			$kcls = ' ' . strtolower( self::cls( $k ) ) . ' ';
			$is_abs = ( false !== stripos( $kcs, 'position: absolute' ) ) || ( false !== stripos( $kcs, 'position:absolute' ) ) || (bool) preg_match( '/\babsolute\b/', $kcls );
			if ( ! $is_abs ) { continue; }
			$blocks = array();
			self::collect_blocks( $k, $blocks, $rules );
			if ( ! $blocks ) { continue; }
			$width = '';
			if ( preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+px)/i', $kcs, $wm ) ) { $width = $wm[1]; }
			elseif ( preg_match( '/\bw-\[([0-9.]+px)\]/', $kcls, $wm ) ) { $width = $wm[1]; }
			$cards[] = array(
				'blocks' => $blocks,
				'skin'   => self::read_card_skin( $k ),
				'pos'    => self::collage_offsets( $k ),
				'width'  => $width,
			);
		}
		if ( count( $cards ) < 2 ) { return null; }
		return array( 't' => 'stage', 'role' => 'stage', 'minH' => $minh, 'cards' => $cards );
	}

	/** A STAT-number lockup: a `flex items-baseline`/`items-end` div/p of spans with a short digit-bearing
	 *  value (`4.9 star`, `$76M+`, `+120%`) and NO block children. Detected so the number isn't dropped. */
	private static function is_stat_number( $el, $tag ) {
		if ( ! ( $el instanceof DOMElement ) || ! in_array( $tag, array( 'div', 'p' ), true ) ) { return false; }
		// A leaf lockup — no block children (only inline spans/text).
		foreach ( self::el_children( $el ) as $k ) {
			if ( in_array( strtolower( $k->tagName ), array( 'div','p','h1','h2','h3','h4','h5','h6','ul','ol','a','button','table','section' ), true ) ) { return false; }
		}
		$t = trim( preg_replace( '/\s+/', ' ', self::text( $el ) ) );
		if ( $t === '' || str_word_count( $t ) > 3 || strlen( $t ) > 20 ) { return false; }
		$has_digit = (bool) preg_match( '/\d/', $t );
		if ( ! $has_digit && ( str_word_count( $t ) > 2 || strlen( $t ) > 12 ) ) { return false; } // a WORD value ('High' / 'Stable') only as a big-display leaf (below)
		$c = ' ' . self::cls( $el ) . ' ';
		// (a) a baseline/end-aligned flex lockup of number+unit spans (`<span>4.9</span><span>star</span>`).
		if ( strpos( $c, 'items-baseline' ) !== false || strpos( $c, 'items-end' ) !== false ) { return $has_digit; }
		// (b) a STANDALONE BIG-DISPLAY number — a large-font leaf whose text is a short statistic
		//     (`<div class="text-6xl font-semibold">84%</div>`, AI-page cloud-forest's carbon-sink stat).
		//     collect_blocks otherwise emits NOTHING for it (a letter-less number is treated as decorative by
		//     the salvage net) → the stat vanished. Gated on a LARGE font (a text-{3..9}xl utility, or computed
		//     font-size ≥ 36px) so a small inline "3" isn't promoted, AND on the value reading as a real stat
		//     (a %/currency/multiplier symbol, or ≥2 digits) so a lone step "3" isn't swept up.
		$big = (bool) preg_match( '/\btext-[3-9]xl\b/', $c );
		if ( ! $big ) {
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', $cs, $fm ) && (float) $fm[1] >= 36 ) { $big = true; }
		}
		$is_stat_val = (bool) preg_match( '/[%$€£+×xX]/u', $t ) || (bool) preg_match( '/\d[\d.,]*\d/', $t );
		// A big-display WORD ('High' beside '84%' in a pair of stat cards) is a stat value too — the same lockup, no digit.
		// Only via branch (b): the baseline-lockup branch (a) still needs a number.
