		// BELOW testimonials (92) but ABOVE card_grid (90) so a stat band is claimed as counters before a
		// generic card grid can turn it into icon_boxes. TIGHT match (is_counter_grid): >=2 cells AND every
		// substantial cell parses to a numeric stat with <=80 chars of text — so a feature/prose grid (long
		// cell text) or a mixed band never qualifies.
		self::register_recognizer( 'counter_grid', 91,
			function ( $el ) { return self::is_counter_grid( $el ); },
			function ( $el ) { return self::counter_grid_build( $el ); }
		);

		// A real data `<table>` (>=1 row with cells) → the native `table` shortcode (tabular render mode),
		// headers derived from leading all-`<th>` rows. Priority 88: the match is tag-scoped (`table`), the
		// tightest possible signal, so it can't over-claim; it just needs to beat descent so the table isn't
		// flattened into loose cell text.
		self::register_recognizer( 'table', 88,
			function ( $el, $tag ) { return 'table' === $tag && self::table_has_rows( $el ); },
			function ( $el ) { return self::table_block( $el ); }
		);

		// An ACCORDION / FAQ — a container holding >=2 `<details><summary>` items, or >=2 `[aria-expanded]`
		// toggles each with a panel → the native `accordion` shortcode (items = title + content). Priority 89
		// (below card_grid 90). TIGHT match (is_accordion_group): requires >=2 genuine toggle/detail pairs, so
		// a lone <details> or a plain content stack never qualifies.
		self::register_recognizer( 'accordion', 89,
			function ( $el ) { return self::is_accordion_group( $el ); },
			function ( $el ) { return self::accordion_block( $el ); }
		);

		// A standalone `<ul>`/`<ol>` of >=2 text items (NOT a nav / menu / pagination / breadcrumb / tab list)
		// → the native `feature_list` shortcode (checklist for <ul>, numbered for <ol>). Priority 79 sits just
		// below headings (80): a plain list carries no grid/flex signal so it never trips card_grid (90/85) or
		// layout_row (82); this claims it before descent flattens it into loose text. TIGHT match
		// (is_text_list): real ul/ol, >=2 non-empty <li>, and role/class/ancestor excludes navigation lists.
		self::register_recognizer( 'text_list', 79,
			function ( $el ) { return self::is_text_list( $el ); },
			function ( $el ) { return self::text_list_block( $el ); }
		);

		// --- Interactive / structured native widgets (all TIGHT, so a high priority is safe: each claims
		//     ONLY its exact structural pattern and never a generic card/feature grid). They sit ABOVE
		//     card_grid(90)/counter_grid(91)/testimonials(92) so a real pricing/steps/timeline/progress/tabs
		//     band wins over the generic grid recognizers that would otherwise flatten it. ---

		// A PRICING TABLE — >=2 plan columns each carrying a price token (currency + number) + a plan name,
		// usually a feature list + CTA → the native `pricing_table` shortcode. TIGHT: the price token must
		// appear in MOST columns, so a plain feature card grid (no currency) stays icon_box.
		self::register_recognizer( 'pricing_table', 99,
			function ( $el ) { return self::is_pricing_table( $el ); },
			function ( $el ) { return self::pricing_table_block( $el ); }
		);

		// A numbered STEPS / PROCESS flow (Step 1 → 2 → 3, numbered markers, `.steps`/`.process`) → `steps`.
		self::register_recognizer( 'steps', 98,
			function ( $el ) { return self::is_steps_flow( $el ); },
			function ( $el ) { return self::steps_block( $el ); }
		);

		// A dated TIMELINE — chronological entries (date + title + body) along a line → `timeline`.
		self::register_recognizer( 'timeline', 97,
			function ( $el ) { return self::is_timeline( $el ); },
			function ( $el ) { return self::timeline_block( $el ); }
		);

		// PROGRESS / SKILL bars — >=2 labelled bars each with a percent (role=progressbar, width:%, or "NN%")
		// → the native `progress` shortcode. Above counter_grid(91) so "Design 80%" reads as a bar, not a stat.
		self::register_recognizer( 'progress', 96,
			function ( $el ) { return self::is_progress_bars( $el ); },
			function ( $el ) { return self::progress_block( $el ); }
		);

		// A TABS widget — a tablist (role=tablist/[role=tab], or `.tabs`/`.nav-tabs` with [data-tab]/aria-controls
		// panels) bound to switchable panels → the native `tabs` shortcode. TIGHT: >=2 tabs each resolving to a
		// panel; a plain <ul> nav (no tabs/panels) never qualifies.
		self::register_recognizer( 'tabs', 95,
			function ( $el ) { return self::is_tabs_widget( $el ); },
			function ( $el ) { return self::tabs_block( $el ); }
		);


		// A LOTTIE embed — <lottie-player>/<dotlottie-player>, or a container with a `.json`/`.lottie` src /
		// bodymovin init → the native `lottie` shortcode (carries the animation src).
		self::register_recognizer( 'lottie', 94,
			function ( $el ) { return self::is_lottie_embed( $el ); },
			function ( $el ) { return self::lottie_block( $el ); }
		);

		// A self-drawing SVG — an inline <svg> whose paths are stroke-animated (stroke-dasharray/dashoffset)
		// or explicitly marked for draw-on-scroll → the native `svg_draw` shortcode. TIGHT: a real draw signal,
		// never a plain decorative icon <svg>.
		self::register_recognizer( 'svg_draw', 93,
			function ( $el, $tag ) { return self::is_svg_draw( $el, $tag ); },
			function ( $el ) { return self::svg_draw_block( $el ); }
		);
	}

	/* --------------------------------------------------------------------- *
	 * Source-animation INTENT — detect a reveal/scroll animation on a source
	 * element (AOS, animate.css/WOW, generic reveal hooks) and map it to a
	 * native animate.css effect string for the node's Animations tab. Absent a
	 * clear signal, returns '' (no false motion — the node stays un-animated).
	 * --------------------------------------------------------------------- */
	/**
	 * The capture's CSS-class reveal stamp (data-sc-reveal="dir:up;distance:30;scale:1;duration:1.2;delay:0.2;ease:…") →
	 * { dir, distance, scale, duration, delay, ease } or null. A reveal class sits on the animated element itself. JS twin: revealOf.
	 */
	/**
	 * The element's OWN running class animation (capture data-sc-anim: a pulsing dot, a swaying word, a drifting shell, a
	 * scroll-grown card) + its @keyframes (data-sc-keyframes) → { css, kf } or null. Carried on the block's own Custom CSS
	 * by the mapper (apply_block_anim / carry_cell_geometry / the mirror). JS twin: loopAnimOf.
	 */
	private static function loop_anim_of( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return null; }
		$a = trim( (string) $el->getAttribute( 'data-sc-anim' ) );
		if ( '' === $a || ! preg_match( '/^animation:[a-z0-9_ .,()%-]+(?:;animation-(?:timeline|range):[a-z0-9 ().%-]+)*$/i', $a ) ) { return null; }
		// An unbalanced paren (a `cubic-bezier(0.4` cut at a comma by an older capture) would swallow the rest of the
		// stylesheet — the declaration is never carried as-is: the broken function falls back to `ease`.
		if ( substr_count( $a, '(' ) !== substr_count( $a, ')' ) ) { $a = preg_replace( '/[a-z-]+\([^)]*$/i', 'ease', $a ); if ( substr_count( $a, '(' ) !== substr_count( $a, ')' ) ) { return null; } }
		$kf = trim( (string) $el->getAttribute( 'data-sc-keyframes' ) );
		if ( '' !== $kf && ! preg_match( '/^@keyframes\s+[\w-]+\s*\{[^<>]*\}\s*$/s', $kf ) ) { $kf = ''; }
		return array( 'css' => $a, 'kf' => $kf );
	}

	private static function reveal_of( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return null; }
		$v = trim( (string) $el->getAttribute( 'data-sc-reveal' ) );
		if ( '' === $v ) { return null; }
		$o = array();
		foreach ( explode( ';', $v ) as $part ) { $i = strpos( $part, ':' ); if ( $i > 0 ) { $o[ substr( $part, 0, $i ) ] = substr( $part, $i + 1 ); } }
		return array(
			'dir'      => isset( $o['dir'] ) ? (string) $o['dir'] : 'none',
			'distance' => (float) ( $o['distance'] ?? 0 ),
			'scale'    => isset( $o['scale'] ) && '' !== $o['scale'] ? (float) $o['scale'] : 1.0,
			'duration' => (float) ( $o['duration'] ?? 0 ),
			'delay'    => (float) ( $o['delay'] ?? 0 ),
			'ease'     => isset( $o['ease'] ) ? (string) $o['ease'] : '',
		);
	}

	private static function anim_intent( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$dir = array( 'up' => 'animate__fadeInUp', 'down' => 'animate__fadeInDown', 'left' => 'animate__fadeInLeft', 'right' => 'animate__fadeInRight' );
		// AOS: data-aos="fade-up" / "zoom-in" / "slide-left" / "flip-up" / "fade".
		$aos = strtolower( trim( (string) $el->getAttribute( 'data-aos' ) ) );
		if ( '' !== $aos ) {
			if ( preg_match( '/(up|down|left|right)/', $aos, $m ) && strpos( $aos, 'zoom' ) === false ) { return $dir[ $m[1] ]; }
			if ( strpos( $aos, 'zoom-out' ) === 0 ) { return 'animate__zoomOut'; }
			if ( strpos( $aos, 'zoom' ) === 0 )     { return 'animate__zoomIn'; }
			if ( strpos( $aos, 'flip' ) === 0 )     { return 'animate__flipInX'; }
			return 'animate__fadeIn';
		}
		// animate.css v4 (`animate__fadeInUp`) or WOW v3 (`wow fadeInUp`).
		$class = (string) $el->getAttribute( 'class' );
		if ( preg_match( '/\banimate__([A-Za-z]+)\b/', $class, $m ) ) { return 'animate__' . $m[1]; }
		if ( preg_match( '/\bwow\b/i', $class ) && preg_match( '/\b(fadeIn[A-Za-z]*|zoomIn|zoomOut|slideIn[A-Za-z]*|bounceIn[A-Za-z]*|flipIn[A-Za-z]*)\b/', $class, $m ) ) { return 'animate__' . $m[1]; }
		// Generic reveal hooks (Framer/GSAP/custom) carrying a direction.
		foreach ( array( 'data-animate', 'data-scroll', 'data-reveal', 'data-motion' ) as $at ) {
			if ( $el->hasAttribute( $at ) ) {
				$v = strtolower( (string) $el->getAttribute( $at ) );
				foreach ( $dir as $k => $eff ) { if ( strpos( $v, $k ) !== false ) { return $eff; } }
				return 'animate__fadeInUp';
			}
		}
		return '';
	}

	/**
	 * Text-SPLIT reveal intent — a word/line/char split-reveal on a source text element (kage's `.word-reveal`
	 * / `.mask-line`, a SplitText/Splitting.js lockup, per-word/char span lockups) → the split_by the Text
	 * Effects `split_reveal` should use. Returns 'words' | 'lines' | 'chars' | '' (no split). This is RICHER
	 * than anim_intent (a whole-element entrance) — it animates the text piece-by-piece, so the mapper prefers
	 * it over the plain entrance when present.
	 */
	private static function text_split_intent( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$attr_names = '';
		if ( $el->hasAttributes() ) { foreach ( $el->attributes as $a ) { $attr_names .= ' ' . $a->nodeName; } }
		$hay = ' ' . strtolower( (string) $el->getAttribute( 'class' ) . ' ' . $attr_names ) . ' ';
		if ( preg_match( '/(?:char|letter)[\s_-]*(?:reveal|split|anim|in|mask)|split[\s_-]*chars|chars?[\s_-]*reveal/', $hay ) ) { return 'chars'; }
		if ( preg_match( '/(?:line)[\s_-]*(?:reveal|mask|split|clip)|mask[\s_-]*line|line[\s_-]*mask/', $hay ) ) { return 'lines'; }
		if ( preg_match( '/(?:word)[\s_-]*(?:reveal|split|anim|in|mask)|split[\s_-]*words|words?[\s_-]*reveal/', $hay ) ) { return 'words'; }
		// Structural: a run of per-word/char child spans (a split-text signature).
		if ( $el->getElementsByTagName( 'span' )->length >= 4 ) {
			$wordish = 0; $charish = 0; $seen = 0;
			foreach ( $el->getElementsByTagName( 'span' ) as $s ) {
				$sc = ' ' . strtolower( self::cls( $s ) ) . ' ';
				if ( preg_match( '/(?:^|[\s_-])(?:word|w)(?:[\s_-]|$)/', $sc ) ) { $wordish++; }
				if ( preg_match( '/(?:^|[\s_-])(?:char|letter|c)(?:[\s_-]|$)/', $sc ) ) { $charish++; }
				if ( ++$seen > 40 ) { break; }
			}
			if ( $charish >= 4 ) { return 'chars'; }
			if ( $wordish >= 3 ) { return 'words'; }
		}
		if ( preg_match( '/(?:^|[\s_-])(?:splittext|split-text|splitting|data-splitting)(?:[\s_-]|$)/', $hay ) ) { return 'words'; }
		return '';
	}

	/* --------------------------------------------------------------------- *
	 * Counter / stat-grid recognizer helpers
	 * --------------------------------------------------------------------- */

	/**
	 * Parse ONE stat cell into a counter payload `{ number, prefix, suffix, decimals, label }`, or null if the
	 * cell isn't a numeric stat. A stat cell is short (<=80 chars) and dominated by a number, optionally with a
	 * leading currency/`+`/`~` symbol and a trailing `%`/`+`/`k`/`m`/`b`/`x` unit; the leftover text is the label.
	 */
	private static function counter_cell_parse( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return null; }
		$txt = self::text( $cell );
		if ( '' === $txt || mb_strlen( $txt ) > 80 ) { return null; }
		if ( ! preg_match( '/(\d[\d,]*(?:\.\d+)?)/', $txt, $m, PREG_OFFSET_CAPTURE ) ) { return null; }
		$num_raw = $m[1][0];
		$pos     = (int) $m[1][1];
		$len     = strlen( $num_raw );
		$before  = substr( $txt, 0, $pos );
		$after   = substr( $txt, $pos + $len );
		// A number GLUED into a word (a filename "kernel_v4.sh", a code "A4", "MK2") is not a statistic.
		if ( preg_match( '/[A-Za-z_]$/', $before ) || preg_match( '/^[_]/', $after ) ) { return null; }
		// A zero-padded 1–2 digit value ("01", "02") is a step / row MARKER, never a statistic.
		if ( preg_match( '/^0\d$/', $num_raw ) ) { return null; }
		// A TIME or a RANGE ("4–10 PM", "11:30 AM–10 PM", "9:00 - 17:00", "Mon–Fri") is opening hours, not a statistic — the
		// hours tiles had become counter sub-cards (a real-site audit)
		if ( preg_match( '/^\s*(?::\d{2}|\s*[–—-]\s*\d|\s*(?:am|pm))/iu', $after ) || preg_match( '/[–—-]\s*$/u', $before ) ) { return null; }
		$prefix  = '';
		// a comparison / approximation sign reads as the stat's prefix too ("< 1.2ms", "> 99%", "≈ 40", "~ 3x")
		if ( preg_match( '/([$€£¥+~<>≈≤≥])\s*$/u', $before, $pm ) ) { $prefix = $pm[1]; $before = preg_replace( '/([$€£¥+~<>≈≤≥])\s*$/u', '', $before ); }
		$suffix  = '';
		// A unit suffix is TERMINAL ("12K", "5M", "3x", "500+", "94%") -- it is never the first letter of a
		// following WORD. Without the trailing-letter guard, "3 Beds" parsed as number 3 + suffix "B" +
		// label "eds", and a property card's spec row rendered as garbage counters (urban_living_ams).
		if ( preg_match( '/^\s*(%|\+|×|°|\/\d{1,3})/u', $after, $sm ) // (× U+00D7 is the multiplication sign — "3.2×" reads like "3.2x"; a "/7" tail is the stat's own — "24/7" spilled "/7" into the label; both from the feed)
			|| preg_match( '/^\s*(k|K|m|M|b|B|x|X)(?![A-Za-z])/u', $after, $sm ) ) {
			$suffix = $sm[1];
			$after  = preg_replace( '/^\s*' . preg_quote( $sm[1], '/' ) . '/u', '', $after, 1 );
			// a COMPOUND unit ("20k+", "1.5M+", "99.9%+"): the sign after the letter unit belongs to the value, not the label
			if ( preg_match( '/^[kKmMbBxX]$/', $suffix ) && preg_match( '/^\s*(%|\+)/u', $after, $s2 ) ) { $suffix .= $s2[1]; $after = preg_replace( '/^\s*' . preg_quote( $s2[1], '/' ) . '/u', '', $after, 1 ); }
		}
		// The number's OWN LEAF: a unit written onto the digits inside it ("1.2ms", "24h", "7 Days" in the same leaf) is the
		// suffix (≤ 4 letters, then the leaf ends), and a leaf that MIXES the digits with words at a SMALL size ("TTY // 1",
		// "5 min read", a caption with a number) is a label, not a statistic — a real stat isolates its number, or sets it big.
		$num_leaf = null;
		foreach ( $cell->getElementsByTagName( '*' ) as $e ) {
			if ( $e->getElementsByTagName( '*' )->length > 0 ) { continue; }
			if ( false !== strpos( self::text( $e ), $num_raw ) ) { $num_leaf = $e; break; }
		}
		if ( ! ( $num_leaf instanceof DOMElement ) && false !== strpos( $txt, $num_raw ) ) { $num_leaf = $cell; }
		if ( $num_leaf instanceof DOMElement ) {
			$lt = trim( preg_replace( '/\s+/', ' ', self::text( $num_leaf ) ) );
			$lp = strpos( $lt, $num_raw );
			$lb = trim( substr( $lt, 0, (int) $lp ) ); $la = trim( substr( $lt, (int) $lp + $len ) );
			if ( '' !== $suffix && 0 === strpos( $la, $suffix ) ) { $la = trim( substr( $la, strlen( $suffix ) ) ); } // the unit already read above
			if ( '' === $suffix && preg_match( '/^([A-Za-z]{1,4}|%|\+|×|°)$/u', $la ) ) { $suffix = $la; $after = preg_replace( '/^\s*' . preg_quote( $la, '/' ) . '/u', '', $after, 1 ); $la = ''; }
			$lb_rest = trim( preg_replace( '/[$€£¥+~<>≈≤≥]\s*$/u', '', $lb ) );
			if ( '' !== $lb_rest || '' !== $la ) {
				$lfs = trim( (string) self::sc_css( $num_leaf, 'font-size' ) ); $lbig = preg_match( '/^([0-9.]+)px$/', $lfs, $lfm ) && (float) $lfm[1] >= 24;
				if ( ! $lbig && ! preg_match( '/\btext-[2-9]xl\b/', ' ' . self::cls( $num_leaf ) . ' ' ) ) { return null; }
			}
		}
		$label   = trim( preg_replace( '/\s+/', ' ', $before . ' ' . $after ) );
		$label_first = '' !== trim( $before ) && '' === trim( $after ); // the caption sits ABOVE the number ("ENERGY STATE" over "98%") — keep that order
		// A STAT cell is DOMINATED by its number: the leftover label is a short caption ("Happy pets",
		// "Satisfaction"), NOT prose. Reject a long remainder so a paragraph that merely contains a number
		// (e.g. an FAQ answer "…within 30 days…") never reads as a counter.
		if ( mb_strlen( $label ) > 32 ) { return null; }
		// A self-describing STAT carries a caption (label) OR a unit (prefix/suffix): "$12K", "94%", "500+",
		// "7 Days". A bare, context-less number — a lone "4"/"11" split out of an hours block, a list index —
		// is NOT a stat. Reject it so an address / opening-hours card's digits don't animate as counters.
		if ( '' === $label && '' === $prefix && '' === $suffix ) { return null; }
		// TIME / OPENING-HOURS — "11:30 AM", "10 PM", "9:00", "4h", "24 h". An opening-hours card decomposes
		// into these, and the leftover (":30 AM", " PM", "h") is a non-empty label that would sneak past the
		// guard above. None of these are stats (the the burger source "14 phantom counters from the hours" bug).
		if ( preg_match( '/\b\d{1,2}\s*:\s*\d{2}\b/', $txt )                     // 11:30 / 9:00
			|| preg_match( '/\b\d{1,2}\s*(?:am|pm)\b/i', $txt )                  // 10 PM / 4 AM
			|| preg_match( '/^\s*\d{1,3}\s*h\s*$/i', $txt ) ) { return null; }   // 4h / 24 h (hours)
		$decimals = 0;
		if ( strpos( $num_raw, '.' ) !== false ) { $decimals = strlen( substr( strrchr( $num_raw, '.' ), 1 ) ); }
		$number = str_replace( ',', '', $num_raw );
		// Capture the NUMBER's colour (the leaf element that renders the digits) so a stat on a DARK panel
		// keeps its light / accent tone (e.g. modfii's `$12K` in accent-orange, `7`/`94%` in white on the
		// glass hero card) instead of collapsing to the default dark foreground = invisible on dark.
		$num_color = ''; $label_color = ''; $num_size = ''; $label_size = ''; $num_cs = ''; $label_cs = '';
		foreach ( $cell->getElementsByTagName( '*' ) as $e ) {
			if ( $e->getElementsByTagName( '*' )->length > 0 ) { continue; } // leaf only
			$et = trim( self::text( $e ) );
			if ( $et === '' ) { continue; }
			$cc = trim( (string) self::sc_css( $e, 'color' ) );
			if ( $num_color === '' && ( strpos( $et, $num_raw ) !== false || strpos( $et, $number ) !== false ) ) {
				if ( '' === $num_cs ) { $num_cs = (string) $e->getAttribute( 'data-sc-cs' ); } // the digits' whole treatment (weight / family / tracking)
				if ( $cc !== '' && stripos( $cc, 'inherit' ) === false ) { $num_color = self::color_to_hex( $cc ); }
				// The stat NUMBER's font-SIZE (e.g. modfii's `$12K` = 30px). Without it the counter falls to its
				// 44px default — bigger than the source and mis-scaled. Carried → n_counter number/prefix/suffix.
				$fs = trim( (string) self::sc_css( $e, 'font-size' ) );
				if ( $num_size === '' && preg_match( '/^([0-9.]+)px$/', $fs, $fm ) ) { $num_size = $fm[1]; }
			} elseif ( $label_color === '' && $label !== '' && $cc !== '' && stripos( $cc, 'inherit' ) === false && strpos( $et, substr( $label, 0, 6 ) ) !== false ) {
				$label_color = self::color_to_hex( $cc );
				if ( '' === $label_cs ) { $label_cs = (string) $e->getAttribute( 'data-sc-cs' ); } // the caption's whole treatment → a Text Style match
				if ( $label_size === '' ) { $lfs = trim( (string) self::sc_css( $e, 'font-size' ) ); if ( preg_match( '/^([0-9.]+)px$/', $lfs, $lm ) ) { $label_size = $lm[1]; } }
			}
		}
		// The stat cell's text-ALIGN (source hero stats are centered) → the counter + its label centre to match.
		$ta = trim( (string) self::sc_css( $cell, 'text-align' ) );
		$align = in_array( $ta, array( 'center', 'right' ), true ) ? $ta : '';
		return array( 'number' => $number, 'prefix' => $prefix, 'suffix' => $suffix, 'decimals' => (string) $decimals, 'label' => $label, 'numberColor' => $num_color, 'suffixColor' => $num_color, 'prefixColor' => $num_color, 'labelColor' => $label_color, 'labelSize' => $label_size, 'numberSize' => $num_size, 'suffixSize' => $num_size, 'prefixSize' => $num_size, 'align' => $align, 'numberCs' => $num_cs, 'labelCs' => $label_cs, 'labelFirst' => $label_first );
	}

	/**
	 * Is this cell an icon+text META CHIP rather than a statistic? A real stat cell ISOLATES its number in
	 * its own element ("127" over "Homes Sold", "2,400+" over "Graduates"), so at least one of its text
	 * nodes is digits WITHOUT a word. A meta chip writes the number and its word in ONE run beside an icon
	 * ("3 Beds", "5 min read", "30-Day Guarantee"), so no such node exists. True only when BOTH hold: the
	 * cell carries an `<svg>` glyph AND no text node isolates the digits. Measured on the corpus: this
	 * de-claims 8 containers (property specs, blog post-meta, feature chips, an address card) and leaves
	 * every genuine stat band claimed, including icon-bearing ones like real_estate_realtor's 36px "12 Years".
	 */
	private static function cell_is_icon_meta_chip( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return false; }
		if ( ! $cell->getElementsByTagName( 'svg' )->length ) { return false; }
		$doc = $cell->ownerDocument;
		if ( ! $doc ) { return false; }
		// A displayed STATISTIC is typographically large (the corpus's stat numbers render at 30-48px);
		// a meta chip is body copy (14px). Measure the biggest digit-bearing element in the cell and bail
		// out above the threshold, so real_estate_realtor's 36px "12 Years" stays a counter while
		// urban_living's 14px "3 Beds" does not.
		$big = 0.0;
		foreach ( $cell->getElementsByTagName( '*' ) as $e ) {
			if ( ! preg_match( '/\d/', self::text( $e ) ) ) { continue; }
			$fs = trim( (string) self::sc_css( $e, 'font-size' ) );
			if ( preg_match( '/^([0-9.]+)px$/', $fs, $fm ) ) { $big = max( $big, (float) $fm[1] ); }
		}
		if ( $big >= 20.0 ) { return false; }

		$xp = new DOMXPath( $doc );
		$saw_digits = false;
		foreach ( $xp->query( './/text()', $cell ) as $t ) {
			$v = trim( preg_replace( '/\s+/', ' ', (string) $t->nodeValue ) );
			if ( '' === $v || ! preg_match( '/\d/', $v ) ) { continue; }
			$saw_digits = true;
			if ( ! preg_match( '/[A-Za-z]{3,}/', $v ) ) { return false; } // digits isolated -> a real stat
		}
		return $saw_digits;
	}

	/** TIGHT: a grid/row of >=2 cells where EVERY substantial cell is a numeric stat (counter_cell_parse). */
	private static function is_counter_grid( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'table', 'thead', 'tbody', 'tr', 'ul', 'ol', 'nav', 'dl' ), true ) ) { return false; }
		// Never claim a structural toggle/list/table band as a stat grid (accordion/list/table own those).
		if ( $el->getElementsByTagName( 'details' )->length || $el->getElementsByTagName( 'summary' )->length
			|| $el->getElementsByTagName( 'table' )->length || $el->getElementsByTagName( 'ul' )->length
			|| $el->getElementsByTagName( 'ol' )->length ) { return false; }
		$cells = 0; $numeric = 0; $wordish = 0;
		foreach ( self::el_children( $el ) as $k ) {
			$kt = strtolower( $k->tagName );
			if ( in_array( $kt, array( 'script', 'style', 'br', 'hr' ), true ) ) { continue; }
			if ( '' === self::text( $k ) && ! $k->getElementsByTagName( 'img' )->length ) { continue; } // skip empty/decorative
			// A cell carrying a PHOTO is not a statistic. A product row (`<img> + name + $5.95 + Add`)
			// parses as "a number with a short label" and was claimed here, which discarded the thumbnail
			// entirely: counter_grid_build() keeps only the parsed number/label, so the <img> never reaches
			// the builder tree (measured on bakeiiiiry_artisan: 3 of 5 captured images lost this way).
			// Corpus check before adding this gate: is_counter_grid claimed 138 containers, only 10 of which
			// had image-bearing cells — and every one of those is a product/menu list ("$245.00 ADD TO CART",
			// "Add to Cart"), never a stat band. A genuine counter uses an SVG/icon-font glyph, not an <img>.
			if ( $k->getElementsByTagName( 'img' )->length ) { return false; }
			// An icon+text META CHIP is not a statistic. A property/spec row renders each fact as an inline
			// `<span class="flex items-center gap-2"><svg .../> 3 Beds</span>` -- an SVG glyph beside a number
			// and its word IN THE SAME TEXT RUN. A genuine counter puts the digits in their OWN element (the
			// big number above a separate label), which is what counter_cell_parse's colour/size probe relies
			// on. Claiming the chip row produced garbage counters ("3B" + label "eds") AND, because the panel
			// branch in grid_cols() then bypassed card_from_cell(), silently dropped the card's photo.
			if ( self::cell_is_icon_meta_chip( $k ) ) { return false; }
			$cells++;
			if ( self::counter_cell_parse( $k ) !== null ) { $numeric++; }
			elseif ( self::stat_word_cell( $k ) ) { $wordish++; } // a big-display WORD / glyph value ("∞" over "Creativity") in a stat band
		}
		return $cells >= 2 && $numeric >= 2 && $numeric + $wordish === $cells;
	}

	/**
	 * A stat cell whose VALUE is a word or a glyph, not a number ("∞" over "Creativity", "High" over "Water reserve"): a big
	 * (≥ 24px, or a text-2xl+ class) short leaf (≤ 12 chars, no digit) followed by a small caption leaf. Returns
	 * { value, value_el, label, label_el, align } or null. JS twin: statWordCell.
	 */
	private static function stat_word_cell( $k ) {
		if ( ! ( $k instanceof DOMElement ) ) { return null; }
		$leaves = array();
		foreach ( $k->getElementsByTagName( '*' ) as $e ) { if ( 0 === $e->getElementsByTagName( '*' )->length && '' !== trim( self::text( $e ) ) ) { $leaves[] = $e; } }
		if ( 2 !== count( $leaves ) ) { return null; }
		$v = trim( preg_replace( '/\s+/', ' ', self::text( $leaves[0] ) ) ); $l = trim( preg_replace( '/\s+/', ' ', self::text( $leaves[1] ) ) );
		if ( '' === $v || mb_strlen( $v ) > 12 || preg_match( '/\d/', $v ) || '' === $l || mb_strlen( $l ) > 40 ) { return null; }
		$vfs = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $leaves[0]->getAttribute( 'data-sc-cs' ), $fm ) ? (float) $fm[1] : 0;
		$lfs = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $leaves[1]->getAttribute( 'data-sc-cs' ), $lm ) ? (float) $lm[1] : 16;
		$big = $vfs >= 24 || preg_match( '/\btext-[2-9]xl\b/', ' ' . self::cls( $leaves[0] ) . ' ' );
		if ( ! $big || $vfs <= $lfs ) { return null; }
		$ta = trim( (string) self::sc_css( $k, 'text-align' ) );
		return array( 'value' => $v, 'value_el' => $leaves[0], 'label' => $l, 'label_el' => $leaves[1], 'align' => in_array( $ta, array( 'center', 'right' ), true ) ? $ta : '' );
	}

	/** A flex ROW (not column) of 2–3 direct children: ≥ 1 button (a <button> / a button-shaped link) and the rest short text
	 *  leaves (≤ 40 chars, no link inside) — never a nav / a header / a form. */
	private static function is_label_cta_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $cs ) || preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $cs ) ) { return false; }
		$kids = self::el_children( $el ); $n = count( $kids );
		if ( $n < 2 || $n > 3 ) { return false; }
		$btn = 0; $lbl = 0;
		foreach ( $kids as $k ) {
			$kt = strtolower( $k->tagName );
			if ( 'button' === $kt || ( 'a' === $kt && self::is_button( $k ) ) ) { $btn++; continue; }
			if ( in_array( $kt, array( 'span', 'div', 'p', 'strong', 'em', 'b' ), true ) && ! $k->getElementsByTagName( 'a' )->length && ! $k->getElementsByTagName( 'img' )->length && ! $k->getElementsByTagName( 'svg' )->length ) {
				$t = trim( self::text( $k ) ); if ( '' !== $t && mb_strlen( $t ) <= 40 ) { $lbl++; continue; }
			}
			return false;
		}
		return $btn >= 1 && $lbl >= 1;
	}

	/** The label + button row: each child claimed as its own block (the text builder / the button recognizer), one content-sized
	 *  cell each, the row's raw justify-content + vertical alignment, its own margins. */
	private static function label_cta_row_build( $el, array $rules ) {
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		$row = array( 't' => 'row', 'role' => 'columns', 'valign' => self::row_valign( $el ), 'gap' => (int) self::grid_gap_px( $el ), 'mt' => 0, 'mb' => 0, 'nowrap' => true, 'cols' => array() );
		$jc = preg_match( '/(?:^|;)\s*justify-content:\s*([a-z-]+)/i', $cs, $jm ) ? strtolower( $jm[1] ) : '';
		if ( preg_match( '/^(space-between|space-around|space-evenly|center|flex-end|end)$/', $jc ) ) { $row['justify'] = $jc; }
		$rfx = self::row_fx_css( $el ); if ( '' !== $rfx ) { $row['fx'] = $rfx; }
		$m = self::el_margin( $el ); $row['mt'] = (float) ( $m['top'] ?? 0 ); $row['mb'] = (float) ( $m['bottom'] ?? 0 );
		foreach ( self::el_children( $el ) as $k ) {
			$hb = array(); self::collect_blocks_of( $k, $hb, $rules );
			$hb = array_values( array_filter( $hb, function ( $b ) { return is_array( $b ) && isset( $b['t'] ); } ) );
			if ( ! $hb ) {
				// a leaf label no recognizer claims (a <span> price) → a text block on its own stamp
				$t = trim( self::text( $k ) ); if ( '' === $t ) { continue; }
				$hb = array( array( 't' => 'text', 'role' => 'text', 'cls' => self::cls( $k ), 'cs' => (string) $k->getAttribute( 'data-sc-cs' ), 'csSm' => (string) $k->getAttribute( 'data-sc-cs-sm' ), 'maxWidth' => '', 'text' => $t, 'html' => '<p>' . esc_html( $t ) . '</p>', 'contentSized' => true ) );
			}
			foreach ( $hb as &$b ) { if ( 'text' === ( $b['t'] ?? '' ) ) { $b['contentSized'] = true; } } unset( $b );
			$row['cols'][] = array( 'cls' => '', 'blocks' => $hb );
		}
		return count( $row['cols'] ) >= 2 ? $row : null;
	}

	/** An in-flow element with no text / media of its own (decor-only descendants allowed) that PAINTS: a fill, a gradient or a
	 *  border, at a measured height ≥ 40px. Never an absolute / fixed layer (a backdrop), never a tiny dot (mirror_dot_css). */
	private static function is_paint_block( $el, $tag ) {
		if ( ! ( $el instanceof DOMElement ) || ! in_array( $tag, array( 'div', 'span', 'figure', 'section' ), true ) ) { return false; }
		if ( '' !== trim( self::text( $el ) ) || $el->getElementsByTagName( 'img' )->length || $el->getElementsByTagName( 'svg' )->length || $el->getElementsByTagName( 'video' )->length || $el->getElementsByTagName( 'iframe' )->length || $el->getElementsByTagName( 'a' )->length ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $cs ) ) { return false; }
		$h = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $hm ) ? (float) $hm[1] : 0.0;
		$fill = preg_match( '/(?:^|;)\s*background-color:\s*([^;]+)/i', $cs, $bm ) && ! preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent|\/\s*0\s*\)/i', $bm[1] );
		$grad = (bool) preg_match( '/(?:^|;)\s*background-image:\s*(?:linear|radial|conic)-gradient/i', $cs );
		// A HAIRLINE (≤ 4px tall, painted, with a measured width — a `w-16 h-px bg-accent` accent bar, a gradient rule)
		// is a paint block too: it kept its colour but lost its width (a RECURRING finding) when it fell to the generic path.
		if ( $h > 0 && $h <= 4 && ( $fill || $grad ) && preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $cs, $wm ) && (float) $wm[1] > 0 ) { return true; }
		if ( $h < 40 ) { return false; }
		$border = preg_match( '/(?:^|;)\s*border-top-width:\s*([0-9.]+)px/i', $cs, $bw ) && (float) $bw[1] > 0 && preg_match( '/(?:^|;)\s*border-top-style:\s*(?!none)/i', $cs );
		return $fill || $grad || $border;
	}

	/** An absolute / fixed child with no text / media that paints: a gradient / fill / blur with a measured size (a glow blob, a
	 *  gradient hairline). Never a full-bleed cover (that is the section's own background / scrim, read elsewhere). */
	private static function is_decor_layer_block( $el, $tag ) {
		if ( ! ( $el instanceof DOMElement ) || ! in_array( $tag, array( 'div', 'span' ), true ) ) { return false; }
		if ( $el->hasAttribute( 'data-sc-pattern-layer' ) ) { return false; } // the section's pattern (already its Background Pattern preset)
		if ( '' !== trim( self::text( $el ) ) || $el->getElementsByTagName( '*' )->length ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/(?:^|;)\s*position:\s*absolute/i', $cs ) ) { return false; }
		$h = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $hm ) ? (float) $hm[1] : 0.0;
		$w = preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $cs, $wm ) ? (float) $wm[1] : 0.0;
		if ( $h <= 0 ) { return false; }
		// a full-bleed cover (inset:0 with no own size) is a scrim / backdrop — not a placed decor layer
		if ( preg_match( '/(?:^|;)\s*top:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*bottom:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*left:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*right:\s*0px/i', $cs ) && $h > 200 ) { return false; }
		$paint = ( preg_match( '/(?:^|;)\s*background-image:\s*(?:linear|radial|conic)-gradient/i', $cs ) ) || ( preg_match( '/(?:^|;)\s*background-color:\s*([^;]+)/i', $cs, $bm ) && ! preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent|\/\s*0\s*\)/i', $bm[1] ) );
		return $paint;
	}

	/** The decor layer block: the paint + blur + radius, its measured size, its placement (the declared sides: a `left-[20%]` as the
	 *  computed left in px, `bottom-0` as bottom:0), the stacking; pointer-events none. Built by the `paint` builder. */
	private static function decor_layer_block( $el ) {
		$cs = (string) $el->getAttribute( 'data-sc-cs' ); $cls = ' ' . self::cls( $el ) . ' ';
		$get = function ( $p ) use ( $cs ) { return preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', $cs, $m ) ? trim( $m[1] ) : ''; };
		$d = array( 'position:absolute', 'pointer-events:none' );
		$bi = $get( 'background-image' ); if ( '' !== $bi && 'none' !== strtolower( $bi ) ) { $d[] = 'background-image:' . $bi; }
		$bc = $get( 'background-color' ); if ( '' !== $bc && ! preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent|\/\s*0\s*\)/i', $bc ) ) { $d[] = 'background-color:' . $bc; }
		$br = $get( 'border-radius' ); if ( '' !== $br && '0px' !== $br ) { $d[] = 'border-radius:' . $br; }
		$f = $get( 'filter' ); if ( '' !== $f && 'none' !== strtolower( $f ) ) { $d[] = 'filter:' . $f; }
		$op = $get( 'opacity' ); if ( '' !== $op && '1' !== $op ) { $d[] = 'opacity:' . $op; }
		$z = $get( 'z-index' ); if ( '' !== $z && 'auto' !== $z ) { $d[] = 'z-index:' . $z; }
		// the layer's blend (a `mix-blend-screen` glow) and its TRANSFORM — the utility first (`-translate-x-1/2` → translateX(-50%),
		// a percentage the stamp resolved to px), else a non-identity 2-D matrix as stamped (a feed finding: a `w-[200%] h-[200%]
		// left-1/2 -translate-x-1/2` overlay collapsed to 0 × auto — no box, no transform)
		$mb = $get( 'mix-blend-mode' ); if ( '' !== $mb && 'normal' !== strtolower( $mb ) ) { $d[] = 'mix-blend-mode:' . $mb; }
		$tfs = array();
		if ( preg_match( '/(?:^|\s)(-?)translate-x-(1\/2|1\/3|2\/3|1\/4|3\/4|full)(?:\s|$)/', $cls, $tx ) ) { $tfs[] = 'translateX(' . ( '' !== $tx[1] ? '-' : '' ) . self::frac_pct( $tx[2] ) . ')'; }
		if ( preg_match( '/(?:^|\s)(-?)translate-y-(1\/2|1\/3|2\/3|1\/4|3\/4|full)(?:\s|$)/', $cls, $ty ) ) { $tfs[] = 'translateY(' . ( '' !== $ty[1] ? '-' : '' ) . self::frac_pct( $ty[2] ) . ')'; }
		if ( preg_match( '/(?:^|\s)(-?)rotate-(\d{1,3})(?:\s|$)/', $cls, $rt ) ) { $tfs[] = 'rotate(' . ( '' !== $rt[1] ? '-' : '' ) . $rt[2] . 'deg)'; }
		if ( $tfs ) { $d[] = 'transform:' . implode( ' ', $tfs ); }
		else { $tf = $get( 'transform' ); if ( preg_match( '/^matrix\(([^)]+)\)$/', $tf, $tm ) && preg_replace( '/\s+/', '', $tm[1] ) !== '1,0,0,1,0,0' ) { $d[] = 'transform:' . $tf; } }
		$h = $get( 'height' ); $w = $get( 'width' );
		// a PERCENT size utility (`w-[200%]` / `h-full`) is the layer's box relative to its parent — the stamp's px is one screen's
		if ( preg_match( '/(?:^|\s)h-(?:\[([0-9.]+)%\]|(full))(?:\s|$)/', $cls, $hp ) ) { $h = ( '' !== ( $hp[1] ?? '' ) ? $hp[1] : '100' ) . '%'; }
		if ( preg_match( '/(?:^|\s)w-(?:\[([0-9.]+)%\]|(full))(?:\s|$)/', $cls, $wp ) ) { $w = ( '' !== ( $wp[1] ?? '' ) ? $wp[1] : '100' ) . '%'; }
		if ( preg_match( '/^[0-9.]+(?:px|%)$/', $h ) ) { $d[] = 'height:' . $h; }
		// width: the declared size (`w-72` = 288px), else a horizontal stretch (`inset-x-0` / left+right 0) → left:0;right:0
		$stretch = preg_match( '/(?:^|;)\s*left:\s*0px/i', $cs ) && preg_match( '/(?:^|;)\s*right:\s*0px/i', $cs ) && ( '' === $w || ! preg_match( '/(?:^|\s)w-(?:\d+|\[[^\]]+\])(?:\s|$)/', $cls ) );
		if ( $stretch ) { $d[] = 'left:0'; $d[] = 'right:0'; }
		else {
			// the width: the stamp, else the utility (`w-72` = 288px, `w-[30rem]`), else a round blob is as wide as it is tall
			if ( ! preg_match( '/^[0-9.]+px$/', $w ) ) {
				if ( preg_match( '/(?:^|\s)w-(\d+)(?:\s|$)/', $cls, $wc ) ) { $w = ( (int) $wc[1] * 4 ) . 'px'; }
				elseif ( preg_match( '/(?:^|\s)w-\[([0-9.]+)(px|rem)\]/', $cls, $wc ) ) { $w = round( (float) $wc[1] * ( 'px' === $wc[2] ? 1 : 16 ) ) . 'px'; }
				elseif ( preg_match( '/^[0-9.]+px$/', $h ) && ( false !== strpos( $cls, 'rounded-full' ) || preg_match( '/(?:^|;)\s*border-radius:\s*(?:9999px|50%)/i', $cs ) ) ) { $w = $h; }
			}
			if ( preg_match( '/^[0-9.]+(?:px|%)$/', $w ) ) { $d[] = 'width:' . $w; }
			// the side the source DECLARED (a Tailwind top-*/left-*/right-*/bottom-* utility): a FRACTION (`left-1/2`) as its
			// percentage, else the computed px
			foreach ( array( 'top', 'left', 'right', 'bottom' ) as $sd ) {
				if ( preg_match( '/(?:^|\s)-?' . $sd . '-(1\/2|1\/3|2\/3|1\/4|3\/4)(?:\s|$)/', $cls, $fr ) ) { $d[] = $sd . ':' . self::frac_pct( $fr[1] ); continue; }
				if ( preg_match( '/(?:^|\s)-?' . $sd . '-(?:\d+|\[[^\]]+\]|auto|px|full)(?:\s|$)/', $cls ) ) { $v = $get( $sd ); if ( preg_match( '/^-?[0-9.]+px$/', $v ) ) { $d[] = $sd . ':' . $v; } }
			}
			if ( ! preg_match( '/(?:^|;)(?:top|bottom):/', implode( ';', $d ) ) ) { $v = $get( 'top' ); if ( preg_match( '/^-?[0-9.]+px$/', $v ) ) { $d[] = 'top:' . $v; } }
			if ( ! preg_match( '/(?:^|;)(?:left|right):/', implode( ';', $d ) ) ) { $v = $get( 'left' ); if ( preg_match( '/^-?[0-9.]+px$/', $v ) ) { $d[] = 'left:' . $v; } }
			// NO width at all (a plain-CSS `.flare{top:-30vh;left:-40vw;right:-40vw}` glow): the box is its two horizontal offsets
			if ( ! preg_match( '/(?:^|;)width:/', implode( ';', $d ) ) && ! preg_match( '/(?:^|;)right:/', implode( ';', $d ) ) ) { $v = $get( 'right' ); if ( preg_match( '/^-?[0-9.]+px$/', $v ) && preg_match( '/(?:^|;)left:/', implode( ';', $d ) ) ) { $d[] = 'right:' . $v; } }
		}
		if ( ! preg_match( '/(?:^|;)(?:top|bottom):/', implode( ';', $d ) ) ) { $v = $get( 'bottom' ); if ( preg_match( '/^-?[0-9.]+px$/', $v ) ) { $d[] = 'bottom:' . $v; } }
		return array( 't' => 'paint', 'role' => 'paint', 'css' => implode( ';', $d ), 'mt' => 0, 'mb' => 0, 'decorLayer' => true );
	}

	/** A ROW's own visual effect — a resting `opacity` below 1 and / or a `filter` (a `opacity-70 grayscale` logo strip; its
	 *  `hover:grayscale-0` restores the colour) — as a `;`-joined declaration list for the row's scoped CSS, '' when none.
	 *  (A real-site report: the strip's mute + greyscale were dropped, the marks drew in full colour.) */
	private static function row_fx_css( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' ); $d = array();
		if ( preg_match( '/(?:^|;)\s*opacity:\s*([0-9.]+)/i', $cs, $om ) && (float) $om[1] < 1 && (float) $om[1] > 0 ) { $d[] = 'opacity:' . (float) $om[1]; }
		if ( preg_match( '/(?:^|;)\s*filter:\s*([^;]+)/i', $cs, $fm ) && 'none' !== strtolower( trim( $fm[1] ) ) && preg_match( '/^[a-z0-9()%.,\s#\/+-]+$/i', trim( $fm[1] ) ) ) { $d[] = 'filter:' . trim( $fm[1] ); }
		if ( ! $d ) { return ''; }
		$out = 'selector{' . implode( ';', $d ) . ';}';
		$cls = ' ' . self::cls( $el ) . ' ';
		if ( preg_match( '/(?:^|\s)hover:grayscale-0(?:\s|$)/', $cls ) ) { $out .= 'selector:hover{filter:none;}'; }
		if ( preg_match( '/(?:^|\s)hover:opacity-100(?:\s|$)/', $cls ) ) { $out .= 'selector:hover{opacity:1;}'; }
		if ( preg_match( '/(?:^|;)\s*transition:\s*([^;]+)/i', $cs, $tm ) && ! preg_match( '/^(?:all\s+)?0s\b|^none/i', trim( $tm[1] ) ) && preg_match( '/^[a-z0-9()%.,\s-]+$/i', trim( $tm[1] ) ) ) { $out .= 'selector{transition:' . trim( $tm[1] ) . ';}'; }
		return $out;
	}

	/** A Tailwind fraction token → its percentage (`1/2` → 50%, `full` → 100%). */
	private static function frac_pct( $tok ) {
		$map = array( '1/2' => '50%', '1/3' => '33.333%', '2/3' => '66.667%', '1/4' => '25%', '3/4' => '75%', 'full' => '100%' );
		return isset( $map[ $tok ] ) ? $map[ $tok ] : '0';
	}

	/** The paint block: the element's fill / gradient / border / radius / shadow, its height (a flex-grown one carries `grow`), margins. */
	private static function paint_block( $el ) {
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		$get = function ( $p ) use ( $cs ) { return preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', $cs, $m ) ? trim( $m[1] ) : ''; };
		$d = array();
		$bc = $get( 'background-color' ); if ( '' !== $bc && ! preg_match( '/rgba\([^)]*,\s*0\s*\)|transparent|\/\s*0\s*\)/i', $bc ) ) { $d[] = 'background-color:' . $bc; }
		$bi = $get( 'background-image' ); if ( '' !== $bi && 'none' !== strtolower( $bi ) ) { $d[] = 'background-image:' . $bi; }
		$br = $get( 'border-radius' ); if ( '' !== $br && '0px' !== $br ) { $d[] = 'border-radius:' . $br; }
		$bw = $get( 'border-top-width' ); $bs = $get( 'border-top-style' ); $bcol = $get( 'border-top-color' );
		if ( '' !== $bw && (float) $bw > 0 && '' !== $bs && 'none' !== $bs && '' !== $bcol ) { $d[] = 'border:' . $bw . ' ' . $bs . ' ' . $bcol; }
		$sh = $get( 'box-shadow' ); if ( '' !== $sh && 'none' !== $sh ) { $d[] = 'box-shadow:' . $sh; }
		$h = (float) $get( 'height' );
		// a `h-full` / flex-1 block inside a flex column grows to the space the neighbours leave — keep the growth, with the measured height as the minimum
		$grow = (bool) preg_match( '/(?:^|\s)(?:h-full|flex-1|grow)(?:\s|$)/', ' ' . self::cls( $el ) . ' ' ) || (bool) preg_match( '/(?:^|;)\s*flex-grow:\s*[1-9]/i', $cs );
		if ( $grow ) { $d[] = 'flex:1 1 auto'; $d[] = 'min-height:' . round( $h ) . 'px'; } else { $d[] = 'height:' . round( $h ) . 'px'; }
		// A hairline / short bar narrower than its parent keeps its MEASURED width (+ its auto centring); a block that
		// spans its parent stays fluid.
		$w  = (float) $get( 'width' );
		$pw = ( $el->parentNode instanceof DOMElement ) ? (float) self::sc_css( $el->parentNode, 'width' ) : 0.0;
		$ecls = ' ' . self::cls( $el ) . ' ';
		if ( $h <= 4 && $w > 0 && ( $pw <= 0 || $w < $pw - 2 ) && false === strpos( $ecls, ' w-full ' ) ) {
			$d[] = 'width:' . round( $w ) . 'px';
			if ( false !== strpos( $ecls, ' mx-auto ' ) || 'auto' === strtolower( trim( $get( 'margin-left' ) ) ) ) { $d[] = 'margin-left:auto'; $d[] = 'margin-right:auto'; }
		} else { $d[] = 'width:100%'; }
		// a decor child (a blurred overlay) inside the paint → a backdrop filter on the block itself
		foreach ( self::el_children( $el ) as $k ) { $kf = (string) self::sc_css( $k, 'backdrop-filter' ); if ( '' !== $kf && 'none' !== $kf ) { $d[] = 'backdrop-filter:' . $kf; break; } }
		$m = self::el_margin( $el );
		return array( 't' => 'paint', 'role' => 'paint', 'css' => implode( ';', $d ), 'mt' => (float) ( $m['top'] ?? 0 ), 'mb' => (float) ( $m['bottom'] ?? 0 ) );
	}

	/** A glyph element standing on its own as a block (not inside a link / button / heading / label lockup): an <iconify-icon>, an
	 *  inline <svg> or an icon-font <i>/<span> with no text. */
	private static function is_pinned_icon_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' ); $cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( ! preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $cs ) && strpos( $cls, ' absolute ' ) === false && strpos( $cls, ' fixed ' ) === false ) { return false; }
		if ( '' !== trim( self::text_no_icons( $el ) ) ) { return false; }
		$links = 0;
		foreach ( $el->getElementsByTagName( 'a' ) as $a ) { if ( $a->getElementsByTagName( 'svg' )->length || $a->getElementsByTagName( 'i' )->length || $a->getElementsByTagName( 'iconify-icon' )->length ) { $links++; } }
		if ( $links < 2 || $links > 8 ) { return false; }
		foreach ( array( 'img', 'video', 'input', 'button', 'h1', 'h2', 'h3', 'p' ) as $t ) { if ( $el->getElementsByTagName( $t )->length ) { return false; } }
		return true;
	}

	private static function pinned_icon_row_build( $el ) {
		$icons = array(); $row_el = $el;
		foreach ( $el->getElementsByTagName( 'a' ) as $a ) { $b = self::lone_icon_block( $a ); if ( is_array( $b ) ) { unset( $b['pinned'], $b['pinCls'], $b['pinCs'] ); $b['link'] = trim( (string) $a->getAttribute( 'href' ) ); $icons[] = $b; } }
		if ( count( $icons ) < 2 ) { return null; }
		// the gap: the innermost flex wrapper's (`flex gap-4`), else the wrapper's
		$gap = 0.0; foreach ( $el->getElementsByTagName( 'div' ) as $d ) { $g = self::sc_css( $d, 'gap' ); if ( preg_match( '/^([0-9.]+)px/', $g, $gm ) ) { $gap = (float) $gm[1]; break; } }
		if ( $gap <= 0 && preg_match( '/^([0-9.]+)px/', (string) self::sc_css( $el, 'gap' ), $gm ) ) { $gap = (float) $gm[1]; }
		return array( 't' => 'pinned_icon_row', 'role' => 'pinned_icon_row', 'icons' => $icons, 'gap' => $gap, 'pinCls' => self::cls( $el ), 'pinCs' => (string) $el->getAttribute( 'data-sc-cs' ) );
	}

	private static function is_lone_icon( $el, $tag ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$is_icon = ( 'iconify-icon' === $tag ) || ( 'svg' === $tag ) || ( in_array( $tag, array( 'i', 'span' ), true ) && preg_match( '/\b(?:fa|fas|far|fab|bi|ri|material-symbols|material-icons|icon-|lucide)/i', self::cls( $el ) ) && '' === trim( self::text_no_icons( $el ) ) );
		if ( ! $is_icon ) { return false; }
		if ( '' !== trim( self::text_no_icons( $el ) ) ) { return false; }
		for ( $a = $el->parentNode; $a instanceof DOMElement; $a = $a->parentNode ) {
			$at = strtolower( $a->tagName );
			// an ICON-ONLY LINK TILE (a `<a class="w-12 h-12 rounded-full border …">` scroll cue holding just the glyph) is a lone icon
			// with a link + tile, not a text link — only when the <a> holds nothing but this glyph
			if ( 'a' === $at && $a === $el->parentNode && '' === trim( self::text_no_icons( $a ) ) && 1 === count( self::el_children( $a ) ) ) { continue; }
			if ( in_array( $at, array( 'a', 'button', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'li', 'label', 'body' ), true ) ) { return 'body' === $at; }
			if ( '' !== trim( self::text( $a ) ) && $a->getElementsByTagName( '*' )->length <= 3 ) {
				// an icon + text LOCKUP (a chip "★ 4.9", a meta row) owns its glyph — but a sibling that is its OWN box (a "SCAN_01"
				// chip with a fill / border beside a bare mark in a justify-between header) is a separate element: the mark stands alone
				$boxed = false;
				foreach ( self::el_children( $a ) as $sib ) { if ( $sib === $el || '' === trim( self::text( $sib ) ) ) { continue; } $scs = (string) $sib->getAttribute( 'data-sc-cs' ); if ( preg_match( '/background-color:\s*(?!rgba\([^)]*,\s*0\s*\))(?!transparent)/i', $scs ) || preg_match( '/(?:^|;)\s*border-top-width:\s*[1-9]/i', $scs ) ) { $boxed = true; } }
				if ( ! $boxed ) { return false; }
			}
		}
		return true;
	}

	/** The lone icon's block: its inline svg markup (an iconify host's inlined svg), measured size and ink, own margins. */
	/** A page-level fixed DOCK: `position:fixed`, anchored to the bottom (≤ 120px) or top, ≤ 120px tall, at most half the
	 *  viewport wide, no copy (≤ 30 chars), ≥ 2 icon-only links / buttons. Returns a `dock` block (its icon tiles as lone_icon
	 *  blocks + the pill's measured skin + the anchor geometry), or null. JS twin: to be added (capture-extract dockOf). */
	private static function detect_floating_dock( $body ) {
		$xp = new DOMXPath( $body->ownerDocument );
		foreach ( $xp->query( '//*[@data-sc-cs]', $body ) as $el ) {
			if ( ! ( $el instanceof DOMElement ) ) { continue; }
			$cs = (string) $el->getAttribute( 'data-sc-cs' );
			if ( ! preg_match( '/(?:^|;)\s*position:\s*fixed/i', $cs ) ) { continue; }
			$h = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $hm ) ? (float) $hm[1] : 0.0;
			if ( $h <= 0 || $h > 120 ) { continue; }
			if ( mb_strlen( trim( self::text( $el ) ) ) > 30 ) { continue; }
			$bottom = preg_match( '/(?:^|;)\s*bottom:\s*([0-9.]+)px/i', $cs, $bm ) ? (float) $bm[1] : -1.0;
			$top    = preg_match( '/(?:^|;)\s*top:\s*([0-9.]+)px/i', $cs, $tm ) ? (float) $tm[1] : -1.0;
			$edge   = ( $bottom >= 0 && $bottom <= 120 ) ? 'bottom' : ( ( $top >= 0 && $top <= 120 ) ? 'top' : '' );
			if ( '' === $edge ) { continue; }
			// the icon links: each an <a> / <button> whose only content is an svg / iconify glyph
			$links = array();
			foreach ( $xp->query( './/a | .//button', $el ) as $a ) {
				if ( ! ( $a instanceof DOMElement ) ) { continue; }
				if ( '' !== trim( self::text_no_icons( $a ) ) ) { $links = array(); break; }
				if ( ! $a->getElementsByTagName( 'svg' )->length && ! $a->getElementsByTagName( 'iconify-icon' )->length && ! $a->getElementsByTagName( 'i' )->length ) { $links = array(); break; }
				$links[] = $a;
			}
			if ( count( $links ) < 2 || count( $links ) > 8 ) { continue; }
			// the pill: the links' common parent (its skin is the dock's)
			$pill = $links[0]->parentNode instanceof DOMElement ? $links[0]->parentNode : $el;
			$pcs  = (string) $pill->getAttribute( 'data-sc-cs' );
			$pd   = FW_Site_Converter_Mapper::cs_decls( $pcs, array( 'background-color', 'background-image', 'border-top-width', 'border-top-color', 'border-radius', 'padding', 'gap', 'backdrop-filter', 'box-shadow' ) );
			$blocks = array();
			foreach ( $links as $a ) {
				// the GLYPH is the block; its <a> is the tile (skin + size + link — lone_icon_block reads the parent as the tile)
				$glyph = null; foreach ( array( 'iconify-icon', 'svg', 'i' ) as $gt ) { $g = $a->getElementsByTagName( $gt )->item( 0 ); if ( $g instanceof DOMElement ) { $glyph = $g; break; } }
				if ( ! $glyph ) { continue; }
				$lb = self::lone_icon_block( $glyph ); if ( is_array( $lb ) ) { $lb['mt'] = 0; $lb['mb'] = 0; $blocks[] = $lb; }
			}
			if ( count( $blocks ) < 2 ) { continue; }
			$vw = 0.0; $root = $body->ownerDocument->documentElement;
			if ( $root instanceof DOMElement && preg_match( '/^\d+$/', (string) $root->getAttribute( 'data-sc-content-width' ) ) ) { $vw = 1440.0; }
			$left = preg_match( '/(?:^|;)\s*left:\s*([0-9.]+)px/i', $cs, $lm ) ? (float) $lm[1] : -1.0;
			$tx   = preg_match( '/transform:\s*matrix\(\s*1,\s*0,\s*0,\s*1,\s*(-?[0-9.]+),\s*(-?[0-9.]+)\s*\)/i', $cs, $mm ) ? (float) $mm[1] : 0.0;
			$centred = ( $left >= 0 && abs( $left - 720 ) <= 2 ); // the source's `left:50%` at the 1440 capture viewport
			return array(
				't' => 'dock', 'role' => 'dock', 'blocks' => $blocks, 'edge' => $edge, 'offset' => ( 'bottom' === $edge ? $bottom : $top ),
				'left' => $left, 'centred' => $centred, 'tx' => $tx, 'pillCs' => $pd, 'gap' => (string) ( $pd['gap'] ?? '' ),
				'z' => ( preg_match( '/(?:^|;)\s*z-index:\s*(\d+)/i', $cs, $zm ) ? (int) $zm[1] : 60 ), 'mt' => 0, 'mb' => 0,
			);
		}
		return null;
	}

	private static function lone_icon_block( $el ) {
		$svg = ( 'svg' === strtolower( $el->tagName ) ) ? $el : null;
		if ( ! $svg ) { foreach ( $el->getElementsByTagName( 'svg' ) as $sv ) { $svg = $sv; break; } }
		$markup = ( $svg && $el->ownerDocument ) ? self::strip_cs( (string) $el->ownerDocument->saveHTML( $svg ) ) : '';
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		// an <svg>'s box (its `w-7 h-7`) is its size; the inherited font-size (16px) is not — the arrow rendered at 16 (a finding from the feed)
		$sz = 0; foreach ( ( $svg === $el ? array( 'height', 'width', 'font-size' ) : array( 'font-size', 'height', 'width' ) ) as $pr ) { if ( preg_match( '/(?:^|;)\s*' . $pr . ':\s*([0-9.]+)px/i', $cs, $m ) && (float) $m[1] > 0 ) { $sz = (float) $m[1]; break; } }
		$col = self::color_keep_alpha( (string) self::sc_css( $el, 'color' ) );
		$cls = self::cls( $el ); $fa = '';
		// the capture does not stamp an <svg> (the sanitizer keeps only its class): its size is its `w-N h-N` / `size-N` utility and
		// its ink is the nearest stamped ancestor's colour — both were empty, so a row of 20px amber stars rendered at the default
		// size in the default ink (a finding from the feed)
		if ( $sz <= 0 ) { if ( preg_match( '/(?:^|\s)(?:w|h|size)-(\d+)(?:\s|$)/', $cls, $um ) ) { $sz = (int) $um[1] * 4; } elseif ( preg_match( '/(?:^|\s)(?:w|h|size)-\[(\d+)px\]/', $cls, $um ) ) { $sz = (int) $um[1]; } }
		if ( '' === $col ) { for ( $anc = $el->parentNode, $ai = 0; $anc instanceof DOMElement && $ai < 4; $anc = $anc->parentNode, $ai++ ) { $ac = self::color_keep_alpha( (string) self::sc_css( $anc, 'color' ) ); if ( '' !== $ac ) { $col = $ac; break; } } }
		if ( '' === $markup && preg_match( '/\b((?:fa[srb]?|bi|ri)\s+[a-z0-9-]+|[a-z]+-[a-z0-9-]+)\b/i', $cls, $fm ) ) { $fa = trim( $fm[1] ); }
		if ( '' === $markup && '' === $fa ) { return null; }
		$m = self::el_margin( $el );
		// a Lucide glyph (`<svg class="lucide lucide-star">`) whose geometry the capture dropped (`<path></path>`) → its library id;
		// the mapper draws it from the icon library instead of an empty inline svg
		$lucide = ( $svg && preg_match( '/(?:^|\s)lucide-([a-z0-9-]+)(?:\s|$)/', self::cls( $svg ), $lm ) && 'lucide' !== $lm[1] ) ? 'lucide/' . $lm[1] : (string) self::detect_lucide_in( $el );
		$out = array( 't' => 'lone_icon', 'role' => 'lone_icon', 'svg' => $markup, 'fa' => $fa, 'lucide' => $lucide, 'size' => (int) round( $sz ), 'color' => $col, 'cls' => $cls, 'cs' => $cs, 'mt' => (float) ( $m['top'] ?? 0 ), 'mb' => (float) ( $m['bottom'] ?? 0 ) );
		// The icon's TILE — a wrapper holding only this glyph, painted (a fill / a border / a shadow) and sized like a badge
		// (≤ 200px): a ring emblem over a CTA, a square chip. Its skin rides as an Icon Badge Preset (the same preset an
		// icon_box's chip gets); its own margins / centring stand for the glyph's. JS twin: loneIconOf tile.
		$tile = ( $el->parentNode instanceof DOMElement && 'body' !== strtolower( $el->parentNode->tagName ) ) ? $el->parentNode : null;
		if ( $tile && count( self::el_children( $tile ) ) === 1 && '' === trim( self::text_no_icons( $tile ) ) ) {
			$tcs  = (string) $tile->getAttribute( 'data-sc-cs' ); $tcls = self::cls( $tile );
			$painted = preg_match( '/background-color:\s*(?!rgba\([^)]*,\s*0\s*\))(?!transparent)/i', $tcs ) || preg_match( '/(?:^|;)\s*border-top-width:\s*[1-9]/i', $tcs ) || preg_match( '/(?:^|;)\s*box-shadow:\s*(?!none)/i', $tcs );
			$tw = 0; if ( preg_match( '/(?:^|;)\s*width:\s*([0-9.]+)px/i', $tcs, $wm ) ) { $tw = (float) $wm[1]; } elseif ( preg_match( '/(?:^|\s)(?:w|size)-(\d+)(?:\s|$)/', $tcls, $wm ) ) { $tw = (int) $wm[1] * 4; } elseif ( preg_match( '/(?:^|\s)w-\[(\d+)px\]/', $tcls, $wm ) ) { $tw = (int) $wm[1]; }
			if ( $tw <= 0 && preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $tcs, $hm ) && (float) $hm[1] <= 200 ) { $tw = (float) $hm[1]; } // a square tile: its height stands for its width
			if ( $painted && $tw > 0 && $tw <= 200 ) {
				$tm = self::el_margin( $tile );
				$out['tileCs'] = $tcs; $out['tileCls'] = $tcls; $out['tileSize'] = (int) round( $tw );
				$out['mt'] = (float) ( $tm['top'] ?? 0 ); $out['mb'] = (float) ( $tm['bottom'] ?? 0 );
				if ( 'a' === strtolower( $tile->tagName ) ) { $out['link'] = trim( (string) $tile->getAttribute( 'href' ) ); }
				// a PINNED tile (`absolute bottom-12 left-1/2 -translate-x-1/2`: a scroll cue) keeps its placement: the mapper's native
				// Position option + the centring transform (a RECURRING finding: the cue fell into the flow under the buttons)
				// the pin may sit on the tile itself or on a SOLE-CHILD wrapper around it (`<div class="absolute bottom-12 left-1/2"><a class="w-12 …">`)
				for ( $pin = $tile, $k = 0; $pin instanceof DOMElement && $k < 3 && 'body' !== strtolower( $pin->tagName ); $pin = $pin->parentNode, $k++ ) {
					if ( $pin !== $tile && ( count( self::el_children( $pin ) ) !== 1 || '' !== trim( self::text_no_icons( $pin ) ) ) ) { break; }
					$pcs = (string) $pin->getAttribute( 'data-sc-cs' );
					if ( preg_match( '/(?:^|;)\s*position:\s*(absolute|fixed)/i', $pcs ) ) {
						$out['pinned'] = true; $out['pinCls'] = self::cls( $pin ); $out['pinCs'] = $pcs;
						$tf = trim( (string) self::sc_css( $pin, 'transform' ) ); if ( '' !== $tf && 'none' !== $tf ) { $out['tileTransform'] = $tf; }
						break;
					}
				}
				if ( preg_match( '/(?:^|\s)mx-auto(?:\s|$)/', $tcls ) || ( preg_match( '/(?:^|;)\s*margin-left:\s*auto/i', $tcs ) && preg_match( '/(?:^|;)\s*margin-right:\s*auto/i', $tcs ) ) ) { $out['center'] = true; }
			}
		}
		return $out;
	}

	/** A container with ≥ 2 direct `<code>` children (each a line), or one whose only code child is a `<pre>`. */
	private static function is_code_listing( $el, $tag ) {
		if ( ! ( $el instanceof DOMElement ) || in_array( $tag, array( 'code', 'pre', 'a', 'button' ), true ) ) { return false; }
		$codes = 0; $others = 0;
		foreach ( self::el_children( $el ) as $k ) { $kt = strtolower( $k->tagName ); if ( 'code' === $kt || 'pre' === $kt ) { $codes++; } elseif ( '' !== trim( self::text( $k ) ) || $k->getElementsByTagName( '*' )->length ) { $others++; } }
		return $codes >= 2 && $codes >= $others;
	}

	/**
	 * The listing block: the code lines as `<pre>` markup (each `<code>` a line, its token spans keeping their measured colour
	 * inline via the scrub, non-breaking spaces → spaces), the container's mono family / size / leading / ink / inset; the
	 * NON-code children (a footer row of chips) follow as their own blocks. Returns a LIST of blocks.
	 */
	private static function code_listing_build( $el, array $rules ) {
		$lines = array(); $rest = array();
		foreach ( self::el_children( $el ) as $k ) {
			$kt = strtolower( $k->tagName );
			if ( 'code' === $kt || 'pre' === $kt ) {
				$inner = self::clean_inline_html_pre( $k );
				$lines[] = $inner;
			} else {
				$rest[] = $k;
			}
		}
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		$m  = self::el_margin( $el );
		$out = array( array( 't' => 'code_listing', 'role' => 'code_listing', 'lines' => $lines, 'cs' => $cs, 'mt' => (float) ( $m['top'] ?? 0 ), 'mb' => (float) ( $m['bottom'] ?? 0 ) ) );
		foreach ( $rest as $k ) {
			$sub = array(); self::collect_blocks_of( $k, $sub, $rules );
			foreach ( $sub as $b ) { if ( is_array( $b ) ) { $out[] = $b; } }
		}
		return $out;
	}

	/** Inline HTML of a code line: the scrub keeps each token span's own colour; the whitespace is PRESERVED (a `<pre>` line). */
	private static function clean_inline_html_pre( $el ) {
		if ( ! $el->ownerDocument ) { return self::text( $el ); }
		$clone = $el->cloneNode( true );
		self::scrub( $clone, (string) $el->getAttribute( 'data-sc-cs' ) );
		$h = '';
		foreach ( $clone->childNodes as $c ) { $h .= $clone->ownerDocument->saveHTML( $c ); }
		$h = self::strip_cs( $h );
		$h = str_replace( array( '&nbsp;', "\xC2\xA0" ), ' ', $h );
		return trim( $h, "\r\n" );
	}

	/** collect_blocks over ONE element (the element itself is offered to the recognizers first, then its children). */
	private static function collect_blocks_of( $el, array &$blocks, array $rules ) {
		$claimed = self::claim_element( $el, $rules );
		if ( is_array( $claimed ) ) { if ( isset( $claimed['t'] ) ) { $blocks[] = $claimed; } else { foreach ( $claimed as $b ) { $blocks[] = $b; } } return; }
		$tag = strtolower( $el->tagName );
		foreach ( self::recognizers() as $r ) {
			if ( ! call_user_func( $r['match'], $el, $tag, $rules ) ) { continue; }
			$o = call_user_func( $r['build'], $el, $tag, $rules );
			if ( is_array( $o ) ) { if ( isset( $o['t'] ) ) { $blocks[] = $o; } else { foreach ( $o as $b ) { if ( is_array( $b ) && isset( $b['t'] ) ) { $blocks[] = $b; } } } return; }
		}
		self::collect_blocks( $el, $blocks, $rules );
	}

	/** Build a `row` block whose cells are counter payloads (reuses the mapper's columns→counter cell path). */
	private static function counter_grid_build( $el ) {
		$kids = array();
		foreach ( self::el_children( $el ) as $k ) {
			if ( in_array( strtolower( $k->tagName ), array( 'script', 'style', 'br', 'hr' ), true ) ) { continue; }
			if ( '' === self::text( $k ) && ! $k->getElementsByTagName( 'img' )->length ) { continue; }
			$kids[] = $k;
		}
		$n    = count( $kids );
		// the cells take the SOURCE grid's column count (`grid-cols-2` with four stats = a 2×2 that wraps), not 12/n — four white
		// stat cards were squeezed into one row of 60px cells (a finding from the feed)
		$gcn  = self::grid_col_count( $el );
		$per  = ( $gcn >= 2 && $gcn < $n ) ? $gcn : $n;
		$desk = $per > 0 ? max( 1, min( 12, (int) round( 12 / $per ) ) ) : 4;
		$cols = array();
		foreach ( $kids as $k ) {
			$p = self::counter_cell_parse( $k );
			if ( null === $p ) {
				// a WORD / glyph stat ("∞" over "Creativity"): the value as a heading over its caption, in the same cell shape
				$sw = self::stat_word_cell( $k );
				if ( ! $sw ) { continue; }
				$col = array_merge( array( 'wResp' => array( 'desktop' => $desk ), 'blocks' => array(
					array( 't' => 'heading', 'role' => 'heading', 'level' => 3, 'cls' => self::cls( $sw['value_el'] ), 'cs' => (string) $sw['value_el']->getAttribute( 'data-sc-cs' ), 'csSm' => '', 'align' => $sw['align'], 'text' => $sw['value'], 'html' => esc_html( $sw['value'] ) ),
					array( 't' => 'text', 'role' => 'text', 'cls' => self::cls( $sw['label_el'] ), 'cs' => (string) $sw['label_el']->getAttribute( 'data-sc-cs' ), 'csSm' => '', 'maxWidth' => '', 'text' => $sw['label'], 'html' => '<p>' . esc_html( $sw['label'] ) . '</p>', 'linkCs' => '' ),
				) ), self::cell_geometry( $k ) );
				$box = self::read_card_skin( $k ); if ( $box ) { $col['cardBox'] = $box; }
				$cols[] = $col;
				continue;
			}
			// Each stat cell is often its OWN sub-card (source `text-center p-4 bg-white/10 rounded-xl`) —
			// carry its box skin so the converted counters sit in matching sub-boxes, not bare on the panel.
			$col = array_merge( array( 'counter' => $p, 'wResp' => array( 'desktop' => $desk ) ), self::cell_geometry( $k ) ); // + the cell's own placement / edge rule
			$box = self::read_card_skin( $k );
			if ( $box ) { $col['cardBox'] = $box; }
			$cols[] = $col;
		}
		return count( $cols ) >= 2 ? array( 't' => 'row', 'role' => 'columns', 'valign' => self::row_valign( $el ), 'stackBp' => self::grid_stack_bp( $el ), 'gap' => self::grid_gap_px( $el ), 'mb' => self::el_margin( $el )['bottom'], 'mt' => self::el_margin( $el )['top'], 'cols' => $cols ) : null;
	}

	/* --------------------------------------------------------------------- *
	 * Table recognizer helpers
	 * --------------------------------------------------------------------- */

	/** A `<table>` that has at least one row. */
	private static function table_has_rows( $el ) {
		return ( $el instanceof DOMElement ) && $el->getElementsByTagName( 'tr' )->length >= 1;
	}

	/**
	 * Extract a `<table>` into a `{ t:'table', rows:[[ {html,header}, … ], …], caption }` block. Each `<tr>`
	 * becomes a row of cells; a `<th>` cell is flagged `header` so the mapper can derive `<thead>`.
	 */
	private static function table_block( $el ) {
		// The table's MEASURED skin first (the mode of every body / header cell's computed style = what the
		// Table Preset owns), so each cell can carry only what DIFFERS from that base as its own inline style.
		$ev   = self::table_style_evidence( $el );
		$rows = array();
		foreach ( $el->getElementsByTagName( 'tr' ) as $tr ) {
			$cells = array();
			foreach ( self::el_children( $tr ) as $c ) {
				$ct = strtolower( $c->tagName );
				if ( 'td' !== $ct && 'th' !== $ct ) { continue; }
				$is_th   = ( 'th' === $ct );
				$cells[] = array(
					'html'   => self::table_cell_html( $c, $is_th ? $ev['th_base'] : $ev['td_base'] ),
					'header' => $is_th,
					'align'  => self::table_cell_align( $c ),
				);
			}
			if ( $cells ) { $rows[] = $cells; }
		}
		if ( ! $rows ) { return null; }
		$caption = '';
		$cap = $el->getElementsByTagName( 'caption' )->item( 0 );
		if ( $cap ) { $caption = self::text( $cap ); }
		// The table's styling evidence (the computed styles the capture stamps as data-sc-cs): the legacy keys
		// (first header cell / table / zebra) the name-matching pick reads, plus the MEASURED skin the mapper
		// registers as a real Table Preset (register_table_preset → build_table_presets).
		$th = $el->getElementsByTagName( 'th' )->item( 0 );
		$style = array_merge( array(
			'header_cs' => $th ? (string) $th->getAttribute( 'data-sc-cs' ) : '',
			'table_cs'  => (string) $el->getAttribute( 'data-sc-cs' ),
			'striped'   => self::table_is_striped( $el ),
		), $ev['style'] );
		return array( 't' => 'table', 'rows' => $rows, 'caption' => $caption, 'style' => $style );
	}

	/**
	 * The MEASURED skin of a `<table>` from the capture's computed-style stamps — what a Table Preset owns
	 * (cell padding, grid lines, the header / body / footer faces, the row hover, zebra fill, the frame, the
	 * caption) — plus the per-cell BASE (the mode of every body cell / header cell for the text props) that
	 * table_cell_html() diffs each cell against. General: nothing here reads a class name; a `divide-y`
	 * source and a `td{border-bottom}` source both land as "horizontal grid lines". JS twin: tableEvidence.
	 *
	 * @return array { style:[…], td_base:[prop=>val], th_base:[prop=>val] }
	 */
	private static function table_style_evidence( $el ) {
		$cs    = function ( $n ) { return ( $n instanceof DOMElement ) ? (string) $n->getAttribute( 'data-sc-cs' ) : ''; };
		$decls = function ( $str, array $allow ) { return class_exists( 'FW_Site_Converter_Mapper' ) ? FW_Site_Converter_Mapper::cs_decls( (string) $str, $allow ) : array(); };
		$EDGES = array();
		foreach ( array( 'top', 'right', 'bottom', 'left' ) as $e ) { $EDGES[] = "border-$e-width"; $EDGES[] = "border-$e-style"; $EDGES[] = "border-$e-color"; }
		$TEXT  = array( 'color', 'font-family', 'font-size', 'font-weight', 'letter-spacing', 'text-transform', 'line-height' );
		$PADS  = array( 'padding-top', 'padding-right', 'padding-bottom', 'padding-left' );

		// Rows by section: <thead> / <tfoot> rows, else a LEADING all-<th> row is a header row.
		$head_rows = array(); $body_rows = array(); $foot_rows = array();
		foreach ( $el->getElementsByTagName( 'tr' ) as $tr ) {
			$pt = ( $tr->parentNode instanceof DOMElement ) ? strtolower( $tr->parentNode->tagName ) : '';
			if ( 'thead' === $pt ) { $head_rows[] = $tr; continue; }
			if ( 'tfoot' === $pt ) { $foot_rows[] = $tr; continue; }
			$all_th = true; $any = false;
			foreach ( self::el_children( $tr ) as $c ) { $t = strtolower( $c->tagName ); if ( 'td' === $t || 'th' === $t ) { $any = true; if ( 'th' !== $t ) { $all_th = false; } } }
			if ( $any && $all_th && ! $body_rows ) { $head_rows[] = $tr; } else { $body_rows[] = $tr; }
		}
		$cells_of = function ( array $rows ) {
			$out = array();
			foreach ( $rows as $tr ) { foreach ( self::el_children( $tr ) as $c ) { $t = strtolower( $c->tagName ); if ( 'td' === $t || 'th' === $t ) { $out[] = $c; } } }
			return $out;
		};
		$head_cells = $cells_of( $head_rows ); $body_cells = $cells_of( $body_rows ); $foot_cells = $cells_of( $foot_rows );

		// The MODE of each prop across a cell set = the base the preset owns; a cell that differs carries its own diff.
		// A prop the stamp OMITS at its default (letter-spacing normal, text-transform none, no fill) still votes —
		// as '' — so four uppercase cells never out-vote sixteen plain ones; a '' winner is left unset.
		$mode = function ( array $cells, array $props ) use ( $decls, $cs ) {
			$votes = array();
			foreach ( $cells as $c ) {
				$d = $decls( $cs( $c ), $props );
				foreach ( $props as $p ) { $v = isset( $d[ $p ] ) ? trim( (string) $d[ $p ] ) : ''; $votes[ $p ][ $v ] = ( $votes[ $p ][ $v ] ?? 0 ) + 1; }
			}
			$out = array();
			foreach ( $votes as $p => $vs ) { arsort( $vs ); $w = (string) key( $vs ); if ( '' !== $w ) { $out[ $p ] = $w; } }
			return $out;
		};
		$td_base = $mode( $body_cells, array_merge( $TEXT, $PADS, array( 'background-color', 'text-align' ) ) );
		$th_base = $mode( $head_cells, array_merge( $TEXT, $PADS, array( 'background-color', 'text-align' ) ) );
		$tf_base = $mode( $foot_cells, array_merge( $TEXT, $PADS, array( 'background-color' ) ) );
		// The body's TEXT base is what the cells INHERIT — the `<tbody>` (or the first body row) stamp — when the
		// source styles the group (`tbody.text-sm.font-light`); the cells' mode only fills what the group leaves
		// unset. A bold first column and a mono value column then diff against the real base, not against each other.
		$tbody = null;
		foreach ( $el->getElementsByTagName( 'tbody' ) as $n ) { $tbody = $n; break; }
		$group = $decls( $cs( $tbody ?: ( $body_rows ? $body_rows[0] : null ) ), $TEXT );
		foreach ( $TEXT as $p ) {
			$v = isset( $group[ $p ] ) ? trim( (string) $group[ $p ] ) : '';
			if ( '' === $v ) { if ( 'letter-spacing' === $p || 'text-transform' === $p ) { unset( $td_base[ $p ] ); } continue; }
			if ( 'letter-spacing' === $p && 'normal' === strtolower( $v ) ) { unset( $td_base[ $p ] ); continue; }
			if ( 'text-transform' === $p && 'none' === strtolower( $v ) ) { unset( $td_base[ $p ] ); continue; }
			$td_base[ $p ] = $v;
		}

		// A rule on one edge → "width|style|color" ('' when none / 0).
		$rule = function ( array $d, $edge ) {
			$w = trim( (string) ( $d[ "border-$edge-width" ] ?? '' ) );
			if ( '' === $w || '0px' === $w || '0' === $w ) { return ''; }
			$st = trim( (string) ( $d[ "border-$edge-style" ] ?? 'solid' ) );
			if ( '' === $st || 'none' === $st || 'hidden' === $st ) { return ''; }
			$col = trim( (string) ( $d[ "border-$edge-color" ] ?? '' ) );
			if ( '' === $col || preg_match( '/^rgba\([^)]*,\s*0\s*\)\s*$/i', $col ) || 'transparent' === $col ) { return ''; }
			return $w . '|' . $st . '|' . $col;
		};
		// Grid lines: the second body row's top rule (a `divide-y` source), else a body cell's bottom / top rule;
		// vertical: a body cell's right / left rule.
		$hline = ''; $vline = '';
		if ( count( $body_rows ) >= 2 ) { $d = $decls( $cs( $body_rows[1] ), $EDGES ); $hline = $rule( $d, 'top' ); if ( '' === $hline ) { $hline = $rule( $d, 'bottom' ); } }
		if ( '' === $hline && $body_cells ) { $d = $decls( $cs( $body_cells[0] ), $EDGES ); $hline = $rule( $d, 'bottom' ); if ( '' === $hline ) { $hline = $rule( $d, 'top' ); } }
		if ( $body_cells ) { $d = $decls( $cs( $body_cells[ count( $body_cells ) > 1 ? 1 : 0 ] ), $EDGES ); $vline = $rule( $d, 'right' ); if ( '' === $vline ) { $vline = $rule( $d, 'left' ); } }
		// The header's rule: the header row's bottom, else the first header cell's bottom.
		$hdline = '';
		if ( $head_rows ) { $hdline = $rule( $decls( $cs( $head_rows[0] ), $EDGES ), 'bottom' ); }
		if ( '' === $hdline && $head_cells ) { $hdline = $rule( $decls( $cs( $head_cells[0] ), $EDGES ), 'bottom' ); }
		// The footer's rule: the footer row's top, else its first cell's top.
		$ftline = '';
		if ( $foot_rows ) { $ftline = $rule( $decls( $cs( $foot_rows[0] ), $EDGES ), 'top' ); }
		if ( '' === $ftline && $foot_cells ) { $ftline = $rule( $decls( $cs( $foot_cells[0] ), $EDGES ), 'top' ); }

		// The frame: the table's own border / radius / shadow / fill, else the wrapper that holds ONLY the table.
		$FR = array( 'border', 'border-radius', 'box-shadow', 'background-color' );
		$is_frame = function ( array $d ) {
			return ! empty( $d['border'] ) || ( ! empty( $d['border-radius'] ) && '0px' !== $d['border-radius'] ) || ( ! empty( $d['box-shadow'] ) && 'none' !== $d['box-shadow'] );
		};
		$fd = $decls( $cs( $el ), $FR );
		if ( ! $is_frame( $fd ) && $el->parentNode instanceof DOMElement && count( self::el_children( $el->parentNode ) ) === 1 ) {
			$pd = $decls( $cs( $el->parentNode ), $FR );
			if ( $is_frame( $pd ) ) { $fd = $pd; }
		}
		$frame = array();
		if ( ! empty( $fd['border'] ) )                                                       { $frame['border'] = trim( (string) $fd['border'] ); }
		if ( ! empty( $fd['border-radius'] ) && '0px' !== $fd['border-radius'] )              { $frame['radius'] = trim( (string) $fd['border-radius'] ); }
		if ( ! empty( $fd['box-shadow'] ) && 'none' !== strtolower( (string) $fd['box-shadow'] ) ) { $frame['shadow'] = trim( (string) $fd['box-shadow'] ); }

		// The row hover (the capture's `hover-self{…}` stamp on a body row, else on a body cell).
		$hover = '';
		foreach ( array_merge( $body_rows, $body_cells ) as $n ) {
			$h = (string) $n->getAttribute( 'data-sc-hover' );
			if ( '' !== $h && preg_match( '/hover-self\{([^}]*)\}/', $h, $m ) ) { $hover = trim( $m[1] ); break; }
		}
		// Row fills: a uniform row fill is the body fill; two alternating fills are zebra stripes.
		$fills = array();
		foreach ( $body_rows as $tr ) {
			$d = $decls( $cs( $tr ), array( 'background-color' ) );
			$bg = trim( (string) ( $d['background-color'] ?? '' ) );
			if ( '' === $bg && self::el_children( $tr ) ) { $d = $decls( $cs( self::el_children( $tr )[0] ), array( 'background-color' ) ); $bg = trim( (string) ( $d['background-color'] ?? '' ) ); }
			$fills[] = ( '' === $bg || 'transparent' === $bg || preg_match( '/^rgba\([^)]*,\s*0\s*\)\s*$/i', $bg ) ) ? '' : $bg;
		}
		$distinct = array_values( array_unique( array_filter( $fills ) ) );
		$stripe = ( count( $distinct ) >= 2 ) ? (string) $distinct[1] : '';
		$row_bg = ( count( $distinct ) >= 1 ) ? (string) $distinct[0] : '';
		if ( '' === $row_bg && ! empty( $td_base['background-color'] ) && 'transparent' !== $td_base['background-color'] && ! preg_match( '/^rgba\([^)]*,\s*0\s*\)\s*$/i', $td_base['background-color'] ) ) { $row_bg = (string) $td_base['background-color']; }

		// The caption's face.
		$capd = array();
		$cap = $el->getElementsByTagName( 'caption' )->item( 0 );
		if ( $cap ) { $capd = $decls( $cs( $cap ), array( 'color', 'font-size', 'font-style', 'text-align' ) ); }

		// The row's transition (ms) when the stamp carries a duration.
		$transition = '';
		if ( $body_rows ) { $d = $decls( $cs( $body_rows[0] ), array( 'transition-duration' ) ); if ( ! empty( $d['transition-duration'] ) && preg_match( '/^([0-9.]+)(m?s)$/', trim( $d['transition-duration'] ), $m ) ) { $transition = (string) round( 'ms' === $m[2] ? (float) $m[1] : (float) $m[1] * 1000 ); } }

		$style = array(
			'td'         => $td_base,
			'th'         => $th_base,
			'tf'         => $tf_base,
			'hline'      => $hline,
			'vline'      => $vline,
			'hdline'     => $hdline,
			'ftline'     => $ftline,
			'frame'      => $frame,
			'hover'      => $hover,
			'stripe_bg'  => $stripe,
			'row_bg'     => $row_bg,
			'caption'    => $capd,
			'transition' => $transition,
			'has_head'   => ! empty( $head_cells ),
			'has_foot'   => ! empty( $foot_cells ),
		);
		return array( 'style' => $style, 'td_base' => $td_base, 'th_base' => $th_base );
	}

	/**
	 * A cell's content for the native table: the inner markup with every descendant's OWN computed diff (vs its
	 * parent's stamp) as an inline style — a badge span keeps its fill / padding / face — and the cell's own diff
	 * vs the table base (colour / face / weight / size / tracking / case) as a wrapping `<span style>`, so a bold
	 * first column or a mono value column survives editing without a class the site never compiles. Source
	 * classes and capture stamps are dropped (the Table editor allows `span[style]`, not classes). JS twin: tableCellHtml.
	 */
	/** Every rgb()/rgba() in a value → hex (8-digit when translucent): wp_kses drops function colours in inline styles. */
	private static function hexify_colors( $v ) {
		return preg_replace_callback( '/rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)\s*(?:,\s*([0-9.]+)\s*)?\)/i', function ( $m ) {
			$h = sprintf( '#%02x%02x%02x', min( 255, (int) round( (float) $m[1] ) ), min( 255, (int) round( (float) $m[2] ) ), min( 255, (int) round( (float) $m[3] ) ) );
			if ( isset( $m[4] ) && '' !== $m[4] && (float) $m[4] < 1 ) { $h .= sprintf( '%02x', (int) round( (float) $m[4] * 255 ) ); }
			return $h;
		}, (string) $v );
	}

	private static function table_cell_html( $c, array $base ) {
		if ( ! ( $c instanceof DOMElement ) ) { return ''; }
		$CELL  = array( 'color', 'font-family', 'font-size', 'font-weight', 'letter-spacing', 'text-transform' );
		$INNER = array( 'background-color', 'color', 'font-family', 'font-size', 'font-weight', 'letter-spacing', 'text-transform', 'padding', 'border', 'border-radius', 'display' );
		$decls = function ( $str, array $allow ) { return class_exists( 'FW_Site_Converter_Mapper' ) ? FW_Site_Converter_Mapper::cs_decls( (string) $str, $allow ) : array(); };
		$inert = function ( $p, $v ) {
			$v = strtolower( trim( (string) $v ) );
			if ( '' === $v || 'inherit' === $v || 'initial' === $v ) { return true; }
			if ( 'letter-spacing' === $p && 'normal' === $v ) { return true; }
			if ( 'text-transform' === $p && 'none' === $v ) { return true; }
			if ( 'background-color' === $p && ( 'transparent' === $v || preg_match( '/^rgba\([^)]*,\s*0\s*\)\s*$/i', $v ) ) ) { return true; }
			if ( 'border-radius' === $p && ( '0px' === $v || '0' === $v ) ) { return true; }
			if ( 'padding' === $p && preg_match( '/^(0px\s*)+$/', $v ) ) { return true; }
			if ( 'display' === $p && ! in_array( $v, array( 'inline-block', 'block', 'inline-flex', 'flex' ), true ) ) { return true; }
			return false;
		};
		// Colours as HEX (#rrggbb / #rrggbbaa): the cell is sanitised by wp_kses, whose style filter drops rgb()/rgba()
		// function values but passes hex — a translucent badge fill survives as 8-digit hex.
		$hex = function ( $v ) { return self::hexify_colors( $v ); };
		$diff = function ( array $d, array $ref, array $props ) use ( $inert, $hex ) {
			$out = array();
			foreach ( $props as $p ) {
				if ( ! isset( $d[ $p ] ) ) { continue; }
				$v = trim( (string) $d[ $p ] );
				if ( $inert( $p, $v ) ) { continue; }
				if ( isset( $ref[ $p ] ) && 0 === strcasecmp( trim( (string) $ref[ $p ] ), $v ) ) { continue; }
				$out[ $p ] = $hex( str_replace( '"', "'", $v ) );
			}
			return $out;
		};
		$clone = $c->cloneNode( true );
		$nodes = array();
		foreach ( $clone->getElementsByTagName( '*' ) as $n ) { $nodes[] = $n; }
		foreach ( $nodes as $n ) {
			if ( ! ( $n instanceof DOMElement ) ) { continue; }
			$own = $decls( (string) $n->getAttribute( 'data-sc-cs' ), $INNER );
			$par = ( $n->parentNode instanceof DOMElement ) ? $decls( (string) $n->parentNode->getAttribute( 'data-sc-cs' ), $INNER ) : array();
			$d   = $diff( $own, $par, $INNER );
			// padding / display only matter on a PAINTED or FRAMED chip (a bare inline span's padding is layout noise)
			$painted = isset( $d['background-color'] ) || isset( $d['border'] );
			if ( ! $painted ) { unset( $d['padding'], $d['display'], $d['border-radius'] ); } // (an inline chip keeps its inline display — its padding paints without growing the line)
			$attrs = array();
			foreach ( $n->attributes as $a ) { $attrs[] = $a->nodeName; }
			foreach ( $attrs as $an ) { if ( 'class' === $an || 'id' === $an || 'style' === $an || 0 === strpos( $an, 'data-sc-' ) ) { $n->removeAttribute( $an ); } }
			if ( $d ) { $st = array(); foreach ( $d as $p => $v ) { $st[] = $p . ':' . $v; } $n->setAttribute( 'style', implode( ';', $st ) ); }
		}
		$html = trim( self::inner_html( $clone ) );
		if ( '' === $html ) { return ''; }
		$own = $decls( (string) $c->getAttribute( 'data-sc-cs' ), $CELL );
		$d   = $diff( $own, $base, $CELL );
		if ( $d ) {
			$st = array(); foreach ( $d as $p => $v ) { $st[] = $p . ':' . $v; }
			$html = '<span style="' . htmlspecialchars( implode( ';', $st ), ENT_QUOTES, 'UTF-8' ) . '">' . $html . '</span>';
		}
		return $html;
	}

	/** A cell's horizontal alignment from its stamp: 'right' / 'center', else '' (the column default). */
	private static function table_cell_align( $c ) {
		$ta = strtolower( trim( (string) self::sc_css( $c, 'text-align' ) ) );
		if ( 'right' === $ta || 'end' === $ta ) { return 'right'; }
		if ( 'center' === $ta ) { return 'center'; }
		return '';
	}

	/** Are the body rows zebra-striped? True when the `<tr>` computed backgrounds show >=2 distinct fills. */
	private static function table_is_striped( $el ) {
		$bgs = array();
		foreach ( $el->getElementsByTagName( 'tr' ) as $tr ) {
			$cs = (string) $tr->getAttribute( 'data-sc-cs' );
			if ( '' === $cs ) { continue; }
			if ( preg_match( '/background-color\s*:\s*([^;]+)/i', $cs, $m ) ) {
				$v = trim( $m[1] );
				if ( '' !== $v && 'transparent' !== $v && ! preg_match( '/^rgba\([^)]*,\s*0\s*\)\s*$/i', $v ) ) { $bgs[ $v ] = true; }
			}
		}
		return count( $bgs ) >= 2;
	}

	/* --------------------------------------------------------------------- *
	 * Accordion / FAQ recognizer helpers
	 * --------------------------------------------------------------------- */

	/** TIGHT: a container with >=2 `<details><summary>` items, or >=2 `[aria-expanded]` toggles. */
	private static function is_accordion_group( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( 'details' === $tag || 'summary' === $tag ) { return false; } // claim the GROUP, not one item
		// A wrapper that ALSO holds a SECTION heading (an h1-h3 that isn't part of a toggle/summary) is the
		// section BAND, not the tight accordion group — reject it so the heading decomposes as its own
		// special_heading and only the toggle group is claimed. (Without this the FAQ band's "Questions? We've
		// Got Answers" heading was absorbed + dropped when the accordion recognizer claimed the whole band.)
		foreach ( array( 'h1', 'h2', 'h3' ) as $htag ) {
			foreach ( $el->getElementsByTagName( $htag ) as $h ) {
				// An ITEM TITLE either IS or CONTAINS a toggle (common: `<h3><button aria-expanded>Q</button></h3>`),
				// or sits INSIDE one. A SECTION heading does neither → its presence means this is the band wrapper.
				$is_item = $h->hasAttribute( 'aria-expanded' ) || $h->getElementsByTagName( 'button' )->length > 0;
				if ( ! $is_item ) {
					foreach ( $h->getElementsByTagName( '*' ) as $c ) { if ( $c->hasAttribute( 'aria-expanded' ) || $c->hasAttribute( 'aria-controls' ) ) { $is_item = true; break; } }
				}
				if ( ! $is_item ) {
					for ( $p = $h->parentNode; $p instanceof DOMElement && $p !== $el; $p = $p->parentNode ) {
						$pt = strtolower( $p->tagName );
						if ( 'summary' === $pt || 'button' === $pt || $p->hasAttribute( 'aria-expanded' ) || $p->hasAttribute( 'aria-controls' ) ) { $is_item = true; break; }
					}
				}
				if ( ! $is_item ) { return false; } // a real section heading → this is the band, not the group
			}
		}
		$details = 0;
		foreach ( $el->getElementsByTagName( 'details' ) as $d ) {
			if ( $d->getElementsByTagName( 'summary' )->length > 0 ) { $details++; }
		}
		if ( $details >= 2 ) { return true; }
		// aria toggles: >=2 elements carrying aria-expanded, each with a panel (aria-controls or a sibling).
		$toggles = 0;
		foreach ( $el->getElementsByTagName( '*' ) as $t ) {
			if ( $t->hasAttribute( 'aria-expanded' ) && self::text( $t ) !== '' ) { $toggles++; }
		}
		if ( $toggles >= 2 ) { return true; }
		// UNANNOTATED toggles (a React FAQ with no aria): ≥ 2 same-shaped items, each a <button> carrying text + a chevron / plus
		// svg FOLLOWED by a sibling panel with text — six such Q/A rows fell to code blocks (a fixture from the feed)
		return count( self::plain_toggle_items( $el ) ) >= 2;
	}

	/** The `[button, panel]` pairs of an unannotated accordion: a text button with a chevron/plus/arrow svg whose next element sibling is a text panel. */
	private static function plain_toggle_items( $el ) {
		$out = array();
		foreach ( $el->getElementsByTagName( 'button' ) as $b ) {
			if ( '' === trim( self::text( $b ) ) ) { continue; }
			$chev = false; foreach ( $b->getElementsByTagName( 'svg' ) as $sv ) { if ( preg_match( '/chevron|plus|minus|arrow|caret|angle/i', self::cls( $sv ) ) ) { $chev = true; break; } }
			if ( ! $chev && ! preg_match( '/^[^\p{L}]*[+−–-]\s*$|[+−]$/u', trim( self::text( $b ) ) ) ) { continue; }
			$sib = $b->nextSibling; while ( $sib && XML_ELEMENT_NODE !== $sib->nodeType ) { $sib = $sib->nextSibling; }
			// a React accordion UNMOUNTS its closed panels — the button stands alone in its card; the item is still a toggle
			// (its answer comes from the FAQ JSON-LD fallback when the page carries one, else stays empty for the editor)
			if ( $sib instanceof DOMElement && ( 'button' === strtolower( $sib->tagName ) || '' === trim( self::text( $sib ) ) ) ) { $sib = null; }
			$out[] = array( $b, $sib );
		}
		return $out;
	}

	/** Extract accordion items `{ title, content }` from a `<details>` group or an aria-toggle group. */
	private static function accordion_block( $el ) {
		$items = array();
		$dets  = $el->getElementsByTagName( 'details' );
		if ( $dets->length > 0 ) {
			foreach ( $dets as $d ) {
				$sum = $d->getElementsByTagName( 'summary' )->item( 0 );
				if ( ! $sum ) { continue; }
				$title = self::text( $sum );
				// Content = the details' inner HTML minus the summary.
				$clone = $d->cloneNode( true );
				foreach ( iterator_to_array( $clone->getElementsByTagName( 'summary' ) ) as $s ) { $s->parentNode->removeChild( $s ); }
				$content = self::strip_cs( trim( self::inner_html( $clone ) ) );
				if ( '' === $content ) { $content = ''; }
				if ( '' !== $title ) { $items[] = array( 'title' => $title, 'content' => $content, 'open' => $d->hasAttribute( 'open' ) ); }
			}
		} elseif ( ! count( self::el_all_with_aria( $el ) ) && count( self::plain_toggle_items( $el ) ) >= 2 ) {
			// unannotated toggles (see plain_toggle_items): title = the button's text without its glyph; content = the sibling panel
			foreach ( self::plain_toggle_items( $el ) as $pair ) {
				$title = trim( preg_replace( '/\s*[+−–]\s*$/u', '', self::text_no_icons( $pair[0] ) ) );
				if ( '' === $title ) { continue; }
				$items[] = array( 'title' => $title, 'content' => ( $pair[1] instanceof DOMElement ) ? self::strip_cs( trim( self::inner_html( $pair[1] ) ) ) : '', 'open' => false );
			}
		} else {
			// aria-expanded toggles: title = toggle text; content = aria-controls target or next sibling.
			$doc = $el->ownerDocument;
			foreach ( self::el_all_with_aria( $el ) as $t ) {
				$title = self::text( $t );
				if ( '' === $title ) { continue; }
				$panel_html = '';
				$ctrl = trim( (string) $t->getAttribute( 'aria-controls' ) );
				if ( '' !== $ctrl && $doc ) {
					$p = $doc->getElementById( $ctrl );
					if ( $p ) { $panel_html = self::strip_cs( trim( self::inner_html( $p ) ) ); }
				}
				if ( '' === $panel_html ) {
					$sib = $t->nextSibling;
					while ( $sib && $sib->nodeType !== XML_ELEMENT_NODE ) { $sib = $sib->nextSibling; }
					if ( $sib instanceof DOMElement ) { $panel_html = self::strip_cs( trim( self::inner_html( $sib ) ) ); }
				}
				$items[] = array( 'title' => $title, 'content' => $panel_html, 'open' => ( 'true' === strtolower( (string) $t->getAttribute( 'aria-expanded' ) ) ) );
			}
		}
		// FAQ JSON-LD FALLBACK — a Radix/Headless accordion UNMOUNTS its closed panels, so the answer content is
		// absent from the captured DOM (each `<div role="region">` is empty) and every item came out title-only.
		// The answers, however, live in the page's `schema.org/FAQPage` structured data — fill any empty content
		// by matching the item's title to a Question's `name` → `acceptedAnswer.text`.
		// FAQ JSON-LD — recover answers a Radix/Headless accordion unmounts from closed panels, AND flag
		// $faq_present when the page's schema.org/FAQPage structured data covers these questions, so the
		// rebuilt accordion re-emits the FAQ schema (native `faq_schema`).
		$faq_matched = 0;
		$faq = self::faq_jsonld_map( $el->ownerDocument );
		if ( $faq ) {
			foreach ( $items as &$it ) {
				$k = self::faq_key( (string) $it['title'] );
				if ( ! isset( $faq[ $k ] ) ) { continue; }
				$faq_matched++;
				if ( '' === trim( (string) ( $it['content'] ?? '' ) ) ) {
					$ans = trim( $faq[ $k ] );
					$it['content'] = ( strpos( $ans, '<' ) !== false ) ? $ans : '<p>' . esc_html( $ans ) . '</p>';
				}
			}
			unset( $it );
		}
		if ( count( $items ) < 2 ) { return null; }
		$block = array( 't' => 'accordion', 'items' => $items );
		$design = self::accordion_design( $el );
		if ( $design ) { $block['design'] = $design; }
		// FAQ schema present when the structured data covers at least half the questions.
		if ( $faq_matched >= max( 1, (int) floor( count( $items ) / 2 ) ) ) { $block['faq'] = true; }
		return $block;
	}

	/** A `schema.org/FAQPage` question→answer map from the document's JSON-LD (`<script type="application/ld+json">`),
	 *  keyed by normalized question text. Handles a bare object, a `@graph` array, and a single-or-list `mainEntity`.
	 *  Used to recover accordion answers that a JS accordion (Radix/Headless) unmounted from the closed-panel DOM. */
	private static function faq_jsonld_map( $doc ) {
		$map = array();
		if ( ! ( $doc instanceof DOMDocument ) ) { return $map; }
		foreach ( $doc->getElementsByTagName( 'script' ) as $s ) {
			if ( 'application/ld+json' !== strtolower( trim( (string) $s->getAttribute( 'type' ) ) ) ) { continue; }
			$json = trim( (string) $s->textContent );
			if ( '' === $json ) { continue; }
			$data = json_decode( $json, true );
			if ( ! is_array( $data ) ) { continue; }
			$nodes = ( isset( $data['@graph'] ) && is_array( $data['@graph'] ) ) ? $data['@graph'] : array( $data );
			foreach ( $nodes as $node ) {
				if ( ! is_array( $node ) ) { continue; }
				$t = isset( $node['@type'] ) ? $node['@type'] : '';
				$is_faq = ( is_string( $t ) && 'faqpage' === strtolower( $t ) ) || ( is_array( $t ) && in_array( 'FAQPage', $t, true ) );
				if ( ! $is_faq || empty( $node['mainEntity'] ) ) { continue; }
				$ents = is_array( $node['mainEntity'] ) ? $node['mainEntity'] : array();
				if ( isset( $ents['@type'] ) || isset( $ents['name'] ) ) { $ents = array( $ents ); } // single Question
				foreach ( $ents as $q ) {
					if ( ! is_array( $q ) ) { continue; }
					$name = trim( (string) ( $q['name'] ?? '' ) );
					$ans  = ( isset( $q['acceptedAnswer'] ) && is_array( $q['acceptedAnswer'] ) ) ? (string) ( $q['acceptedAnswer']['text'] ?? '' ) : '';
					if ( '' !== $name && '' !== trim( $ans ) ) { $map[ self::faq_key( $name ) ] = $ans; }
				}
			}
		}
		return $map;
	}

	/** Normalize a question/title for FAQ matching: strip tags, lowercase, collapse whitespace. */
	private static function faq_key( $s ) {
		return preg_replace( '/\s+/', ' ', strtolower( trim( wp_strip_all_tags( (string) $s ) ) ) );
	}

	/**
	 * Read the SOURCE accordion's visual design from computed styles (data-sc-cs) + classes so the native
	 * `accordion` shortcode can match it instead of falling back to defaults. Returns a partial atts map:
	 * accordion_style (bordered|separated|flush|filled|ghost), icon_style, icon_position, title_alignment,
	 * corner_radius, item_spacing (mb-[Npx]), elevation, title_bg_color. Every key is best-effort — a key is
	 * omitted (leaving the shortcode default) when the source gives no clear signal. See accordion.md.
	 */
	private static function accordion_design( $el ) {
		$d = array();
		if ( ! ( $el instanceof DOMElement ) ) { return $d; }

		// Per-item WRAPPER elements (where bg/border/radius live): each <details>, else — for a div/aria
		// accordion — climb each toggle to the ancestor whose PARENT holds >=2 toggle-bearing children (the real
		// accordion TRACK). This stops an intermediate single wrapper (`max-w-3xl > space-y-4 > cards`) from
		// over-climbing to `space-y-4` and missing each card's own `bg-card rounded-xl border` classes — the
		// "recognizer matched the outer wrapper, so the item read as the bare track → flush" bug.
		$items = array();
		foreach ( $el->getElementsByTagName( 'details' ) as $det ) { $items[] = $det; }
		if ( ! $items ) {
			$has_toggle = function ( $n ) {
				if ( ! ( $n instanceof DOMElement ) ) { return false; }
				if ( $n->hasAttribute( 'aria-expanded' ) ) { return true; }
				foreach ( $n->getElementsByTagName( '*' ) as $c ) { if ( $c->hasAttribute( 'aria-expanded' ) ) { return true; } }
				return false;
			};
			$seen = array();
			foreach ( self::el_all_with_aria( $el ) as $t ) {
				$w = $t; $found = null;
				while ( $w instanceof DOMElement && $w !== $el ) {
					$p = $w->parentNode;
					if ( ! ( $p instanceof DOMElement ) ) { break; }
					$sibs = 0;
					foreach ( self::el_children( $p ) as $ch ) { if ( $has_toggle( $ch ) ) { $sibs++; } }
					if ( $sibs >= 2 || $p === $el ) { $found = $w; break; } // $w = the item card, $p = the track
					$w = $p;
				}
				if ( $found instanceof DOMElement ) {
					$dup = false;
					foreach ( $seen as $s ) { if ( $s === $found ) { $dup = true; break; } }
					if ( ! $dup ) { $items[] = $found; $seen[] = $found; }
				}
			}
		}
		if ( count( $items ) < 1 ) { return $d; }
		$first = $items[0];
		// The real accordion TRACK = the items' shared parent (the `space-y-4` container). Container-level reads
		// (the inter-item gap via `space-y-*`/`gap-*`, the outer border) come from HERE — NOT the matched $el,
		// which the recognizer may have set to an outer wrapper (`max-w-3xl`).
		$track = ( $first->parentNode instanceof DOMElement ) ? $first->parentNode : $el;
		// The item card's + container's utility CLASSES — the style signal often lives ONLY in Tailwind
		// classes (a class-based / raw-HTML source with no computed `data-sc-cs`), so every measurement below
		// falls back to these. Without this the detector saw nothing and defaulted to `flush` even for an
		// obviously SEPARATED card list (`bg-card rounded-xl border` items in a `space-y-4` container).
		$icls = ' ' . strtolower( self::cls( $first ) ) . ' ';
		$ocls = ' ' . strtolower( self::cls( $track ) ) . ' ';
		$has_bg_cls = (bool) preg_match( '/\sbg-(?!transparent|none)[a-z][a-z0-9\/-]*/', $icls );
		$has_bd_cls = preg_match( '/\sborder(?:-[trbl])?\b/', $icls ) && ! preg_match( '/\sborder-0\b|\sborder-none\b/', $icls );
		$radius_cls = preg_match( '/\srounded-(?:2xl|3xl|full)\b/', $icls ) ? 20
			: ( preg_match( '/\srounded-xl\b/', $icls ) ? 12
			: ( preg_match( '/\srounded-lg\b/', $icls ) ? 8
			: ( preg_match( '/\srounded(?:-md|-sm)?\b/', $icls ) ? 4 : 0 ) ) );
		// space-y-N / gap-N on the container, or mb-N on the item = the inter-item gap (space-y uses margin-TOP,
		// which the computed `gap`/`margin-bottom` reads below can't see).
		$gap_cls = preg_match( '/\s(?:space-y|gap(?:-y)?)-(\d+(?:\.\d+)?)\b/', $ocls, $gcm ) ? (float) $gcm[1] * 4
			: ( preg_match( '/\smb-(\d+(?:\.\d+)?)\b/', $icls, $gcm ) ? (float) $gcm[1] * 4 : 0 );
		$divide_cls = (bool) preg_match( '/\sdivide-y\b/', $ocls ); // dividers between items = a flush list

		// --- Title BAR (the clickable row): the <summary>, the aria-expanded toggle, or the item's own box. ---
		$bar = ( 'details' === strtolower( $first->tagName ) ) ? $first->getElementsByTagName( 'summary' )->item( 0 ) : null;
		if ( ! $bar ) {
			foreach ( $first->getElementsByTagName( '*' ) as $c ) { if ( $c->hasAttribute( 'aria-expanded' ) ) { $bar = $c; break; } }
		}
		if ( ! $bar ) { $bar = $first; }

		// --- Icon style + position ---
		$icon_el = null;
		foreach ( $bar->getElementsByTagName( '*' ) as $c ) {
			$ct = strtolower( $c->tagName );
			$cc = self::cls( $c );
			if ( 'svg' === $ct || 'i' === $ct || $c->hasAttribute( 'data-lucide' )
				|| preg_match( '/\b(icon|chevron|arrow|plus|minus|caret|toggle|expand|indicator)\b/i', $cc ) ) { $icon_el = $c; }
		}
		$bar_txt = self::text( $bar );
		$blob    = $icon_el ? ( self::cls( $icon_el ) . ' ' . (string) $icon_el->getAttribute( 'data-lucide' ) . ' ' . (string) $icon_el->getAttribute( 'icon' ) . ' ' . self::inner_html( $icon_el ) ) : '';
		$probe   = $blob . ' ' . $bar_txt;
		if ( $icon_el || preg_match( '/[+\x{2212}\x{00D7}\x{203A}\x{25B6}\x{2304}\x{25BC}\x{25BE}\x{2C5}]/u', $bar_txt ) ) {
			if ( preg_match( '/chevron|caret|\x{2304}|\x{25BE}|\x{25BC}|\x{203A}|\x{2C5}/u', $probe ) )        { $d['icon_style'] = 'chevron'; }
			elseif ( preg_match( '/arrow|triangle|\x{25B6}|\x{25B8}/u', $probe ) )                            { $d['icon_style'] = 'arrow'; }
			elseif ( preg_match( '/\btimes\b|\bclose\b|\bx-|\bxmark|\x{00D7}/u', $probe ) )                    { $d['icon_style'] = 'plus-x'; }
			elseif ( preg_match( '/plus|minus|[+\x{2212}]/u', $probe ) )                                       { $d['icon_style'] = 'plus-minus'; }
			elseif ( $icon_el && 'svg' === strtolower( $icon_el->tagName ) )                                   { $d['icon_style'] = 'chevron'; } // an unlabelled svg toggle is almost always a chevron
		} else {
			$d['icon_style'] = 'none';
		}

		// Position: justify-between/end on the bar, an icon pushed right (margin-left:auto), or the icon as the
		// LAST element child of the bar → right; otherwise left.
		$pos = 'left';
		$jc  = self::sc_css( $bar, 'justify-content' );
		if ( false !== stripos( $jc, 'between' ) || false !== stripos( $jc, 'end' ) || false !== stripos( $jc, 'right' ) ) { $pos = 'right'; }
		if ( $icon_el ) {
			$last = null;
			foreach ( self::el_children( $bar ) as $ch ) { $last = $ch; }
			$ml = self::sc_css( $icon_el, 'margin-left' );
			if ( $last === $icon_el || false !== stripos( $ml, 'auto' ) ) { $pos = 'right'; }
		}
		if ( isset( $d['icon_style'] ) && 'none' !== $d['icon_style'] ) { $d['icon_position'] = $pos; }

		// --- Title alignment ---
		$ta = strtolower( self::sc_css( $bar, 'text-align' ) );
		if ( 'center' === $ta ) { $d['title_alignment'] = 'center'; }
		elseif ( 'right' === $ta ) { $d['title_alignment'] = 'right'; }

		// --- Title tag --- the header is often wrapped in a real heading (`<h3><button aria-expanded>`);
		// carry that level so the rebuilt accordion keeps the source's heading semantics.
		$htag = '';
		for ( $hn = $bar; $hn instanceof DOMElement && $hn !== $first; $hn = ( $hn->parentNode instanceof DOMElement ? $hn->parentNode : null ) ) {
			if ( preg_match( '/^h[2-6]$/', strtolower( $hn->tagName ) ) ) { $htag = strtolower( $hn->tagName ); break; }
		}
		if ( '' !== $htag ) { $d['title_tag'] = $htag; }

		// --- Corner radius (from the item box) ---
		$radius_raw = self::sc_css( $first, 'border-radius' );
		$radius     = (float) $radius_raw;
		if ( $radius <= 0 && $radius_cls > 0 ) { $radius = $radius_cls; } // class fallback (rounded-xl → 12px)
		if ( $radius > 0 )                 { $d['corner_radius'] = $radius >= 16 ? 'lg' : ( $radius >= 8 ? 'md' : 'sm' ); }
		elseif ( '0px' === $radius_raw || $divide_cls ) { $d['corner_radius'] = 'none'; }

		// --- Gap between items (item_spacing) --- computed flex-gap / margin-bottom, else the class fallback
		// (space-y-N uses margin-TOP, invisible to both computed reads, so $gap_cls is the real signal here).
		$gap = max( (float) self::sc_css( $track, 'gap' ), (float) self::sc_css( $first, 'margin-bottom' ), (float) self::sc_css( $first, 'margin-top' ) );
		if ( $gap < 4 && $gap_cls >= 4 ) { $gap = $gap_cls; }
		if ( $gap >= 4 ) {
			// The accordion Item Spacing option renders a `.mb-{slug}` utility, and the view runs the value
			// through sanitize_html_class — which STRIPS the brackets off an arbitrary `mb-[16px]`, leaving
			// `mb-16px` that matches NO CSS rule (so the gap silently vanished and Separated items touched).
			// Snap the measured gap to the nearest INTEGER spacing-scale slug so it actually renders (16px → mb-3).
			$scale = array( 0 => 0, 1 => 4, 2 => 8, 3 => 16, 4 => 24, 5 => 48, 6 => 56, 7 => 64, 8 => 72, 9 => 80, 10 => 96, 11 => 112, 12 => 128 );
			$best = 3; $bd = PHP_INT_MAX;
			foreach ( $scale as $slug => $spx ) { $dd = abs( $spx - $gap ); if ( $dd < $bd ) { $bd = $dd; $best = $slug; } }
			$d['item_spacing'] = 'mb-' . $best;
		}

		// --- Style FAMILY (bordered / separated / flush / filled / ghost) ---
		$item_bg  = self::sc_css( $first, 'background-color' );
		$has_bg   = ( '' !== $item_bg && 'rgba(0, 0, 0, 0)' !== $item_bg && 'transparent' !== $item_bg ) || $has_bg_cls;
		$item_bw  = (float) self::sc_css( $first, 'border-top-width' );
		if ( $item_bw < 1 && $has_bd_cls ) { $item_bw = 1; } // class fallback (`border` / `border-border`)
		$outer_bw = (float) self::sc_css( $track, 'border-top-width' );
		$has_edge = $item_bw >= 1 || $radius > 0;
		if ( $gap >= 4 && ( $has_edge || $has_bg ) ) {
			$d['accordion_style'] = ( $has_bg && $item_bw < 1 && $radius <= 4 ) ? 'filled' : 'separated';
		} elseif ( $gap < 4 && $outer_bw >= 1 ) {
			$d['accordion_style'] = 'bordered';
		} elseif ( $gap < 4 && ! $has_bg && ! $has_edge ) {
			$d['accordion_style'] = 'flush';
		}

		// --- Title background color (only when the item carries a real fill) ---
		if ( $has_bg && preg_match( '/rgba?\(\s*(\d+)\D+(\d+)\D+(\d+)/', $item_bg, $m ) ) {
			$d['title_bg_color'] = array( 'predefined' => '', 'custom' => sprintf( '#%02x%02x%02x', (int) $m[1], (int) $m[2], (int) $m[3] ) );
		}

		// --- Elevation (shadow) ---
		$sh = self::sc_css( $first, 'box-shadow' );
		if ( '' !== $sh && 'none' !== $sh ) {
			$d['elevation'] = ( preg_match( '/(\d+(?:\.\d+)?)px/', $sh, $sm ) && (float) $sm[1] >= 12 ) ? 'raised' : 'subtle';
		}

		// --- Panel (content) element: for <details> the first non-summary child; else the aria-controls
		// target or the bar's next element sibling. Used for the content background + text colour. ---
		$panel = null;
		if ( 'details' === strtolower( $first->tagName ) ) {
			foreach ( self::el_children( $first ) as $ch ) { if ( 'summary' !== strtolower( $ch->tagName ) ) { $panel = $ch; break; } }
		} else {
			$ctrl = trim( (string) $bar->getAttribute( 'aria-controls' ) );
			if ( '' !== $ctrl && $el->ownerDocument ) { $panel = $el->ownerDocument->getElementById( $ctrl ); }
			if ( ! $panel ) { $sib = $bar->nextSibling; while ( $sib && $sib->nodeType !== XML_ELEMENT_NODE ) { $sib = $sib->nextSibling; } if ( $sib instanceof DOMElement ) { $panel = $sib; } }
		}

		// Colour helpers: rgb(a) → #hex, and "is this the default near-black text?" (skip those to avoid noise).
		$rgb_hex = function ( $css ) { return preg_match( '/rgba?\(\s*(\d+)\D+(\d+)\D+(\d+)/', (string) $css, $m ) ? sprintf( '#%02x%02x%02x', (int) $m[1], (int) $m[2], (int) $m[3] ) : ''; };
		$near_black = function ( $css ) { return preg_match( '/rgba?\(\s*(\d+)\D+(\d+)\D+(\d+)/', (string) $css, $m ) && (int) $m[1] < 70 && (int) $m[2] < 70 && (int) $m[3] < 70; };
		$col = function ( $hex ) { return array( 'predefined' => '', 'custom' => $hex ); };

		// --- Content background (panel fill, when it carries a real, non-transparent fill) ---
		if ( $panel instanceof DOMElement ) {
			$pbg = self::sc_css( $panel, 'background-color' );
			if ( '' !== $pbg && 'transparent' !== $pbg && 'rgba(0, 0, 0, 0)' !== $pbg ) {
				$h = $rgb_hex( $pbg ); if ( '' !== $h ) { $d['content_bg_color'] = $col( $h ); }
			}
			// --- Content text colour (only when it isn't the default near-black) ---
			$pc = self::sc_css( $panel, 'color' );
			if ( '' !== $pc && ! $near_black( $pc ) ) { $h = $rgb_hex( $pc ); if ( '' !== $h ) { $d['tab_content_color'] = $col( $h ); } }
		}

		// --- Title (header) text colour (only when it isn't the default near-black) ---
		$bc = self::sc_css( $bar, 'color' );
		if ( '' !== $bc && ! $near_black( $bc ) ) { $h = $rgb_hex( $bc ); if ( '' !== $h ) { $d['tab_title_color'] = $col( $h ); } }

		// --- Icon (closed-state) colour ---
		if ( $icon_el instanceof DOMElement ) {
			$ic = self::sc_css( $icon_el, 'color' );
			if ( '' !== $ic && ! $near_black( $ic ) ) { $h = $rgb_hex( $ic ); if ( '' !== $h ) { $d['icon_closed_color'] = $col( $h ); } }
		}

		// --- Multiple open --- a <details> group opens panels independently; a Bootstrap collapse group
		// with `data-bs-parent` opens only one at a time.
		if ( 'details' === strtolower( $first->tagName ) ) {
			$d['multiple_open'] = 'yes';
		} else {
			$has_parent = false;
			foreach ( $el->getElementsByTagName( '*' ) as $n ) { if ( $n instanceof DOMElement && $n->hasAttribute( 'data-bs-parent' ) ) { $has_parent = true; break; } }
			$d['multiple_open'] = $has_parent ? 'no' : 'yes';
		}

		return $d;
	}

	/** All descendant elements carrying a non-empty `aria-expanded` toggle (helper for accordion_block). */
	private static function el_all_with_aria( $el ) {
		$out = array();
		foreach ( $el->getElementsByTagName( '*' ) as $t ) {
			if ( $t->hasAttribute( 'aria-expanded' ) && self::text( $t ) !== '' ) { $out[] = $t; }
		}
		return $out;
	}

	/* --------------------------------------------------------------------- *
	 * List (ul/ol) recognizer helpers
	 * --------------------------------------------------------------------- */

	/** TIGHT: a real `<ul>`/`<ol>` with >=2 non-empty `<li>`, that is NOT a navigation/menu/tab/pagination list. */
	private static function is_text_list( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( 'ul' !== $tag && 'ol' !== $tag ) { return false; }
		$cls  = self::cls( $el );
		$role = strtolower( (string) $el->getAttribute( 'role' ) );
		if ( preg_match( '/\b(menu|nav|navbar|pagination|breadcrumb|tabs?|tab-list|tablist|social|slider|carousel|steps|dropdown)\b/', $cls ) ) { return false; }
		if ( in_array( $role, array( 'menu', 'menubar', 'tablist', 'navigation' ), true ) ) { return false; }
		if ( self::has_ancestor_tag( $el, 'nav', null ) ) { return false; }
		$lis = 0;
		foreach ( self::el_children( $el ) as $li ) {
			if ( 'li' === strtolower( $li->tagName ) && self::text( $li ) !== '' ) { $lis++; }
		}
		return $lis >= 2;
	}

	/** Extract a `<ul>`/`<ol>` into a `{ t:'feature_list', ordered, items:[{text,html},…] }` block. */
	private static function text_list_block( $el ) {
		$ordered = ( 'ol' === strtolower( $el->tagName ) );
		$rows = array();
		foreach ( self::el_children( $el ) as $li ) {
			if ( 'li' !== strtolower( $li->tagName ) ) { continue; }
			$t = self::text( $li );
			if ( '' === $t ) { continue; }
			$rows[] = array( 'text' => $t, 'html' => self::clean_inline_html( $li ) );
		}
		return count( $rows ) >= 2 ? array( 't' => 'feature_list', 'ordered' => $ordered, 'items' => $rows ) : null;
	}

	/**
	 * A single ICON+TEXT ROW: a `<div>`/`<span>` that holds an inline icon (an `<svg>`, or a lucide/iconify
	 * element) AND a SHORT text label — the modfii hero's `<div class="flex items-center gap-2"><svg
	 * class="lucide lucide-circle-check"/><span>No credit impact</span></div>`. NOT a heading, a real
	 * button/link CTA, an image card, or a long prose block. This is the atom the DIV-based feature list is
	 * built from (the `<ul>/<li>` path can't see it, so such lists were dumped as code_blocks).
	 */
	private static function is_icon_text_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'a', 'button', 'ul', 'ol', 'li', 'svg', 'img', 'input', 'select' ), true ) ) { return false; }
		// Must carry an ICON (inline <svg> or a lucide/iconify element).
		$has_icon = ( $el->getElementsByTagName( 'svg' )->length > 0 ) || ( self::lucide_icon_el( $el ) !== null )
			|| ( $el->getElementsByTagName( 'i' )->length > 0 );
		if ( ! $has_icon ) { return false; }
		// AND a short text label (a feature blurb, not prose): non-empty, <= 60 chars.
		$txt = trim( self::text( $el ) );
		if ( '' === $txt || mb_strlen( $txt ) > 60 ) { return false; }
		// Not a heading, not an image card, not a nested CTA button.
		for ( $i = 1; $i <= 6; $i++ ) { if ( $el->getElementsByTagName( 'h' . $i )->length > 0 ) { return false; } }
		if ( $el->getElementsByTagName( 'img' )->length > 0 ) { return false; }
		if ( $el->getElementsByTagName( 'button' )->length > 0 ) { return false; }
		foreach ( $el->getElementsByTagName( 'a' ) as $a ) { if ( self::is_button( $a ) || self::cs_is_button( $a ) ) { return false; } }
		return true;
	}

	/**
	 * A CONTAINER whose EVERY substantial child is an icon+text row (>=2 of them) → a DIV-based feature list
	 * (`No credit impact` · `0.5% closing fee` · `Green mortgage options`). Excludes nav / menu / tab / social
	 * strips. Higher-priority recognizers (testimonials 92, counter_grid 91, card_grid 90/85) claim their
	 * shapes first, so by the time this runs a match is genuinely a plain icon-labelled list.
	 */
	private static function is_icon_text_list( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'a', 'button', 'nav', 'ul', 'ol', 'form' ), true ) ) { return false; }
		if ( self::has_ancestor_tag( $el, 'nav', null ) ) { return false; }
		$cls = self::cls( $el );
		if ( preg_match( '/\b(menu|nav|navbar|pagination|breadcrumb|tabs?|tablist|social|slider|carousel|dropdown|toolbar)\b/', $cls ) ) { return false; }
		// DEFER a BRAND "trusted by" logo row to the logo_strip recognizer (priority 25): its items are brand
		// marks (iconify simple-icons/logos, or fa-brands/si-/cib- classes), not benefit rows. Without this the
		// icon_text_list recognizer (priority 84, which runs first) claimed the row and stripped the logos to a
		// feature_list. Gated on >=2 BRAND icons so a real checkmark feature list (lucide/generic) is untouched.
		if ( self::logo_strip_brand_icons( $el ) >= 2 ) { return false; }
		$kids = self::widget_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		foreach ( $kids as $k ) { if ( ! self::is_icon_text_row( $k ) ) { return false; } }
		return true;
	}

	/**
	 * Count a row's children that carry a BRAND icon — an iconify web-component with a brand set
	 * (`simple-icons:`, `logos:`, `fa-brands:`, `cib:`, `brandico:`) or a brand icon-font class
	 * (`fa-brands`/`fab`, `si-`, `simple-icons-`, `cib-`). The signal that a flex icon+label row is a
	 * "trusted by" LOGO strip (→ logo_grid) rather than a benefit feature list (→ feature_list).
	 */
	private static function logo_strip_brand_icons( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return 0; }
		$n = 0;
		foreach ( $el->childNodes as $ch ) {
			if ( XML_ELEMENT_NODE !== $ch->nodeType ) { continue; }
			if ( ! in_array( strtolower( $ch->tagName ), array( 'span', 'div', 'a', 'li' ), true ) ) { continue; }
			$brand = false;
			foreach ( $ch->getElementsByTagName( 'iconify-icon' ) as $ii ) {
				$ic = strtolower( (string) $ii->getAttribute( 'icon' ) );
				if ( preg_match( '#^(simple-icons|logos|fa-brands|cib|brandico)[:\-]#', $ic ) ) { $brand = true; break; }
			}
			if ( ! $brand ) {
				foreach ( array( 'svg', 'i', 'span' ) as $t ) {
					foreach ( $ch->getElementsByTagName( $t ) as $e ) {
						$cl = ' ' . strtolower( self::cls( $e ) ) . ' ';
						if ( preg_match( '/(?:^|\s)(fa-brands|fab|si-|simple-icons-|cib-)/', $cl ) ) { $brand = true; break 2; }
					}
				}
			}
			if ( $brand ) { $n++; }
		}
		return $n;
	}

	/**
	 * Extract a DIV-based icon+text list into a rich `feature_list` block — mapping the FULL option surface,
	 * not just the labels. Per item: text + the exact inline SVG icon (+ its class/computed colour). List-level:
	 * orientation (a `flex-wrap`/`flex-row` inline strip → HORIZONTAL; a `flex-col`/grid stack → VERTICAL),
	 * the wrapping gap, and the label span's class/computed style (→ the list text colour + size). The mapper
	 * (n_feature_list) resolves the Tailwind classes to the shortcode's marker_color / text_color / marker_size
	 * / font-size / spacing_size options.
	 */
	private static function icon_text_list_block( $el ) {
		$rows = array();
		$span_cls = ''; $span_cs = '';
		foreach ( self::widget_children( $el ) as $k ) {
			$t = trim( self::text( $k ) );
			if ( '' === $t ) { continue; }
			$row = array( 'text' => $t, 'html' => self::clean_inline_html( $k ) );
			// A STAT row — the text holder is two stacked leaves, a VALUE (larger, ≥ 1.3× the label's size) over a LABEL
			// ("20k+" / "Teams worldwide"): the value is the item text, the label its sub-line. Read as one line before
			// ("20k+ Teams worldwide" inline), while the source stacks them (measured on a stats strip).
			$leaves = array();
			foreach ( $k->getElementsByTagName( '*' ) as $lf ) { if ( in_array( strtolower( $lf->tagName ), array( 'svg', 'path', 'i', 'iconify-icon' ), true ) ) { continue; } if ( '' !== trim( self::text( $lf ) ) && 0 === count( self::el_children( $lf ) ) && preg_match( '/(?:^|;)\s*display:\s*block/i', (string) $lf->getAttribute( 'data-sc-cs' ) ) ) { $leaves[] = $lf; } }
			if ( 2 === count( $leaves ) ) {
				$f0 = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $leaves[0]->getAttribute( 'data-sc-cs' ), $m0 ) ? (float) $m0[1] : 0.0;
				$f1 = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $leaves[1]->getAttribute( 'data-sc-cs' ), $m1 ) ? (float) $m1[1] : 0.0;
				if ( $f0 > 0 && $f1 > 0 && $f0 >= 1.3 * $f1 ) {
					$row['text'] = trim( self::text( $leaves[0] ) ); $row['sub'] = trim( self::text( $leaves[1] ) );
					$row['value_cs'] = (string) $leaves[0]->getAttribute( 'data-sc-cs' ); $row['sub_cs'] = (string) $leaves[1]->getAttribute( 'data-sc-cs' );
					if ( '' === $span_cls && '' === $span_cs ) { $span_cls = self::cls( $leaves[0] ); $span_cs = $row['value_cs']; }
				}
			}
			// Per-item ICON — the exact inline <svg> (or lucide/iconify element), reproduced verbatim as the
			// item's Icon option, plus its class + computed style so the mapper can resolve the marker colour.
			$svg = $k->getElementsByTagName( 'svg' )->item( 0 );
			$icon_el = self::lucide_icon_el( $k );
			if ( ! ( $icon_el instanceof DOMElement ) ) { $icon_el = $svg; }
			if ( $svg instanceof DOMElement && $k->ownerDocument ) { $row['icon_svg'] = (string) $k->ownerDocument->saveHTML( $svg ); }
			$lc = self::detect_lucide_in( $k ); if ( '' !== $lc ) { $row['icon_lucide'] = $lc; }
			if ( $icon_el instanceof DOMElement ) {
				$row['icon_cls'] = self::cls( $icon_el );
				$row['icon_cs']  = (string) $icon_el->getAttribute( 'data-sc-cs' );
			}
			// The label element (the <span>/text node holder) → the list-level text colour + size (from the
			// FIRST row that has one; feature lists are visually uniform).
			if ( '' === $span_cls && '' === $span_cs ) {
				foreach ( array( 'span', 'p' ) as $lt ) {
					$le = $k->getElementsByTagName( $lt )->item( 0 );
					if ( $le instanceof DOMElement && trim( self::text( $le ) ) !== '' ) { $span_cls = self::cls( $le ); $span_cs = (string) $le->getAttribute( 'data-sc-cs' ); break; }
				}
			}
			$rows[] = $row;
		}
		if ( count( $rows ) < 2 ) { return null; }
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		// Orientation: an inline flex/inline-flex strip that ISN'T a column stack = horizontal (the modfii
		// trust strip `flex flex-wrap items-center`); a `flex-col` or a `grid` is vertical.
		$orientation = 'vertical';
		if ( ( strpos( $cls, ' flex ' ) !== false || strpos( $cls, ' inline-flex ' ) !== false )
			&& strpos( $cls, ' flex-col ' ) === false && strpos( $cls, ' grid ' ) === false ) { $orientation = 'horizontal'; }
		// the MEASURED direction decides: a `flex flex-col sm:flex-row` list is a ROW at the capture width (the base class is
		// the phone value) — a centred phone + website row had stacked left-aligned (a real-site audit)
		$lcs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $lcs ) ) { $orientation = preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $lcs ) ? 'vertical' : 'horizontal'; }
		// Per-item icon↔label gap (each row's own `flex items-center gap-2` = 8px) → carried so the marker
		// sits the SOURCE distance from the text, not the theme default .75rem. Read from the first row
		// (rows are visually uniform); computed style first, else a Tailwind `gap-N` (N×4px).
		$item_gap = 0.0;
		$kids0 = self::widget_children( $el );
		if ( ! empty( $kids0 ) ) {
			$k0cs = (string) $kids0[0]->getAttribute( 'data-sc-cs' );
			if ( preg_match( '/(?:^|;)\s*gap:\s*([0-9.]+)px/', $k0cs, $gm ) ) { $item_gap = (float) $gm[1]; }
			else { $k0cls = self::cls( $kids0[0] ); if ( preg_match( '/\bgap-(\d+(?:\.\d+)?)\b/', $k0cls, $gm ) ) { $item_gap = (float) $gm[1] * 4.0; } }
		}
		return array(
			't' => 'feature_list', 'ordered' => false, 'items' => $rows,
			'orientation' => $orientation,
			'list_cls'    => self::cls( $el ),                       // for gap-* → spacing_size
			'list_cs'     => (string) $el->getAttribute( 'data-sc-cs' ),
			'label_cls'   => $span_cls,                              // text-white/80 text-sm → text_color + size
			'label_cs'    => $span_cs,
			'item_gap'    => $item_gap,                              // icon↔label gap (gap-2 = 8px)
		);
	}

	/**
	 * An INLINE LINK STRIP — a flex/inline-flex row whose substantial children are ALL short inline links
	 * (`<a>` <=40 chars, not button-styled) and short text separators (`•` / `|` / `/` / `·`), e.g. a footer
	 * policy-links line (`Editorial Policy • About • Corrections`). Must be claimed as ONE block (a single
	 * centered inline text_block) — else a card-grid/layout-row splits each `<a>` into its own 1/1 column
	 * text_block, dropping the separators and the inline flow. Excludes nav / menu / social / tab strips.
	 */
	private static function is_inline_link_strip( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'a', 'button', 'nav', 'ul', 'ol', 'form', 'header' ), true ) ) { return false; }
		if ( self::has_ancestor_tag( $el, 'nav', null ) ) { return false; }
		$cls = self::cls( $el );
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$is_flex = ( strpos( $cls, 'flex' ) !== false || strpos( $cls, 'inline-flex' ) !== false || preg_match( '/display:\s*(?:inline-)?flex/', $cs ) );
		if ( ! $is_flex ) { return false; }
		if ( preg_match( '/\b(menu|nav|navbar|pagination|breadcrumb|tabs?|tablist|social|slider|carousel|dropdown|toolbar)\b/', $cls ) ) { return false; }
		$kids  = self::widget_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		$links = 0;
		foreach ( $kids as $k ) {
			$kt  = strtolower( $k->tagName );
			$txt = trim( self::text( $k ) );
			if ( 'a' === $kt ) {
				if ( '' === $txt || mb_strlen( $txt ) > 40 ) { return false; }
				if ( self::is_button( $k ) || self::cs_is_button( $k ) ) { return false; } // a styled CTA is not a link-strip item
				foreach ( array( 'img', 'svg', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'div', 'button' ) as $bt ) { if ( $k->getElementsByTagName( $bt )->length ) { return false; } }
				$links++;
			} else {
				// A short text SEPARATOR (•, |, /, ·, —) — <=3 chars, no link/media of its own.
				if ( mb_strlen( $txt ) > 3 ) { return false; }
				if ( $k->getElementsByTagName( 'a' )->length || $k->getElementsByTagName( 'img' )->length || $k->getElementsByTagName( 'svg' )->length ) { return false; }
			}
		}
		return $links >= 2;
	}

	/** Build the inline-link-strip block: the links + separators as ONE centered inline `<p>`, each link
	 *  cleaned (href kept, source classes/computed style stripped so it inherits the theme link colour). */
	private static function inline_link_strip_block( $el ) {
		$parts = array();
		foreach ( self::el_children( $el ) as $k ) {
			$kt  = strtolower( $k->tagName );
			$txt = trim( preg_replace( '/\s+/', ' ', self::text( $k ) ) );
			if ( '' === $txt ) { continue; }
			if ( 'a' === $kt ) {
				// Preserve the LINK (href + text); source classes / computed style are dropped so it inherits
				// the theme link colour rather than a dead Tailwind class.
				$href    = trim( (string) $k->getAttribute( 'href' ) );
				$target  = trim( (string) $k->getAttribute( 'target' ) );
				$parts[] = '<a href="' . esc_attr( $href !== '' ? $href : '#' ) . '"'
					. ( '_blank' === $target ? ' target="_blank" rel="noopener"' : '' ) . '>' . esc_html( $txt ) . '</a>';
			} else {
				$parts[] = esc_html( $txt ); // a short separator (•, |, /) between links
			}
		}
		if ( count( $parts ) < 2 ) { return null; }
		$inner = implode( ' ', $parts );
		$cls   = self::cls( $el );
		$cs    = (string) $el->getAttribute( 'data-sc-cs' );
		$center = ( strpos( $cls, 'justify-center' ) !== false || strpos( $cls, 'text-center' ) !== false || strpos( $cls, 'mx-auto' ) !== false || preg_match( '/justify-content:\s*center|text-align:\s*center/', $cs ) );
		return array(
			't' => 'text', 'role' => 'text', 'cls' => 'sc-link-strip',
			'align' => $center ? 'center' : '', 'cs' => $cs,
			'text' => self::text( $el ),
			'html' => '<p class="sc-link-strip">' . $inner . '</p>',
		);
	}

	/* --------------------------------------------------------------------- *
	 * Shared helpers for the interactive/structured recognizers below.
	 * --------------------------------------------------------------------- */

	/** Substantial (non-empty, non-decorative) direct element children of $el. */
	private static function widget_children( $el ) {
		$out = array();
		foreach ( self::el_children( $el ) as $k ) {
			$kt = strtolower( $k->tagName );
			if ( in_array( $kt, array( 'script', 'style', 'br', 'hr', 'template' ), true ) ) { continue; }
			if ( '' === self::text( $k ) && ! $k->getElementsByTagName( 'img' )->length && ! $k->getElementsByTagName( 'svg' )->length ) { continue; }
			$out[] = $k;
		}
		return $out;
	}

	/** The first heading / strong / `.title`-ish label text inside $el (the item's title), or ''. */
	private static function item_title_text( $el ) {
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) {
			$n = $el->getElementsByTagName( $h )->item( 0 );
			if ( $n && self::text( $n ) !== '' ) { return self::text( $n ); }
		}
		foreach ( $el->getElementsByTagName( '*' ) as $c ) {
			$cc = strtolower( (string) $c->getAttribute( 'class' ) );
			if ( preg_match( '/\b(title|name|heading|plan-?name|step-?title)\b/', $cc ) && self::text( $c ) !== '' ) { return self::text( $c ); }
		}
		// A bold LABEL used as the item title — <strong> or its presentational twin <b> (a hand-authored
		// "chapters"/"chip" card titles with a styled <b>, not a semantic heading). Treated identically.
		foreach ( array( 'strong', 'b' ) as $bt ) {
			$bn = $el->getElementsByTagName( $bt )->item( 0 );
			if ( $bn && self::text( $bn ) !== '' ) { return self::text( $bn ); }
		}
		return '';
	}

	/** The item's body text = full text minus a leading title, first `<p>` preferred. */
	private static function item_body_text( $el, $title ) {
		$p = $el->getElementsByTagName( 'p' )->item( 0 );
		if ( $p && self::text( $p ) !== '' ) { return self::text( $p ); }
		$all = self::text( $el );
		if ( $title !== '' && strpos( $all, $title ) === 0 ) { $all = trim( substr( $all, strlen( $title ) ) ); }
		return $all;
	}

	/* --------------------------------------------------------------------- *
	 * Pricing-table recognizer
	 * --------------------------------------------------------------------- */

	/** A currency+number price token inside a cell's text (e.g. `$29`, `€ 19`, `£9/mo`). */
	private static function cell_price_parts( $el ) {
		$txt = self::text( $el );
		if ( '' === $txt ) { return null; }
		// A magnitude suffix immediately on the number ($4.2B, $18M, $9K) marks a STAT/METRIC, not a plan
		// price — capture it so a headline number isn't mistaken for pricing (build-products-that-move-money's
		// "$4.2B" processed-volume + "$18,240,000.00" stats were mangled into a fake pricing table with a
		// fabricated "/mo"). Real plan prices are small ($9–$999) with no suffix.
		if ( ! preg_match( '/([$€£¥₹])\s?([\d][\d.,]*)(b|m|k|bn|mn)?\b/ui', $txt, $m ) ) { return null; }
		if ( '' !== ( $m[3] ?? '' ) ) { return null; }                 // $4.2B / $18M / $9K = a stat, not a price
		$cur   = $m[1];
		$num   = str_replace( ',', '', $m[2] );
		if ( (float) $num >= 10000 ) { return null; }                  // $18,240,000 = a stat/metric, not a plan price
		$period = '';
		if ( preg_match( '#/\s*(mo|month|yr|year|wk|week|day|user|seat)s?\b#i', $txt, $pm ) ) { $period = '/' . strtolower( $pm[1] ); }
		// …or the source's OWN period phrase, verbatim ("/ per program", "/ one-time") — it was read as "/mo" (a finding from the feed)
		elseif ( preg_match( '#' . preg_quote( $m[0], '#' ) . '\s*(/\s*(?:[Pp]er\s+)?[a-z]+(?:[ -][a-z]+)?)#u', $txt, $pm2 ) ) { $period = trim( preg_replace( '/\s+/', ' ', $pm2[1] ) ); }
		// the price keeps its thousands separator as the source wrote it ("2,400" — it rendered "2400")
		return array( 'currency' => $cur, 'price' => ( false !== strpos( $m[2], ',' ) ? $m[2] : $num ), 'period' => $period );
	}

	/** TIGHT: >=2 plan columns and a price token in MOST columns (so a plain feature grid is not claimed). */
	private static function is_pricing_table( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		// AI-assist (advisory): the classifier judged this section stats-not-pricing → don't build a pricing
		// table (a headline metric like "$4.2B" isn't a plan price). Heuristics still decide when there's no verdict.
		$av = self::ai_verdict_for( $el );
		if ( isset( $av['pricing'] ) && false === $av['pricing'] ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'table', 'thead', 'tbody', 'tr', 'ul', 'ol', 'nav', 'dl', 'details', 'summary' ), true ) ) { return false; }
		if ( $el->getElementsByTagName( 'details' )->length || $el->getElementsByTagName( 'table' )->length ) { return false; }
		$kids = self::widget_children( $el );
		$n    = count( $kids );
		if ( $n < 2 ) { return false; }
		$priced = 0; $with_list = 0; $with_img = 0; $with_shop = 0; $with_banner = 0;
		foreach ( $kids as $k ) {
			if ( self::cell_price_parts( $k ) !== null ) { $priced++; }
			if ( $k->getElementsByTagName( 'ul' )->length || $k->getElementsByTagName( 'ol' )->length ) { $with_list++; }
			if ( $k->getElementsByTagName( 'img' )->length ) { $with_img++; }
			// A plan may carry a small ICON; a card carrying a BANNER photo (h-40+, an aspect box, or a
			// computed height >= 120px) is a service/product card, not a pricing plan. The pricing block has
			// only an `icon` field, so a banner is DROPPED outright — measured on my_website_yanynmdj, where
			// all three card photos vanished (5 unique source images -> 0 on the page).
			foreach ( $k->getElementsByTagName( 'img' ) as $im ) {
				$icls = (string) $im->getAttribute( 'class' );
				$wcls = ( $im->parentNode instanceof DOMElement ) ? (string) $im->parentNode->getAttribute( 'class' ) : '';
				$ics  = (string) $im->getAttribute( 'data-sc-cs' )
					. ' ' . ( ( $im->parentNode instanceof DOMElement ) ? (string) $im->parentNode->getAttribute( 'data-sc-cs' ) : '' );
				$big  = ( preg_match( '/\b(?:[a-z]{2}:)?h-(\d{2,3})\b/', $icls . ' ' . $wcls, $hm ) && (int) $hm[1] >= 40 )
					|| preg_match( '/\baspect-(?:\[|square|video)/', $icls . ' ' . $wcls )
					|| ( preg_match( '/(?:^|;)\s*height:\s*(\d+(?:\.\d+)?)px/', $ics, $cm ) && (float) $cm[1] >= 120 );
				if ( $big ) { $with_banner++; break; }
			}
			$cta = '';
			foreach ( array( 'a', 'button' ) as $bt ) { foreach ( $k->getElementsByTagName( $bt ) as $bb ) { $cta .= ' ' . self::text( $bb ); } }
			if ( preg_match( '/\b(add to (cart|basket|bag)|buy now|shop now|order now)\b/i', $cta ) ) { $with_shop++; }
		}
		if ( $priced < max( 2, (int) ceil( $n * 0.6 ) ) ) { return false; }
		// A PRODUCT-card grid (a shop) also carries prices, but it is NOT a pricing table: pricing plans are
		// defined by a FEATURE LIST per column, while product cards have a product IMAGE and/or an "Add to
		// cart/basket" CTA and no feature list. Reject those so they fall through to the card → icon_box path
		// (keeps image/title/description/button) instead of a pricing_table with a bogus "/mo". Parity in JS.
		$maj = (int) ceil( $n * 0.6 );
		if ( $with_list < $maj && ( $with_img >= $maj || $with_shop >= $maj ) ) { return false; }
		// BANNER images beat the feature-list signal: a card grid whose cells each carry a photo is a
		// service/product grid even when the cells also list bullet points (which the guard above lets
		// through). Corpus check before adding this: is_pricing_table claimed 29 containers, only 3 of which
		// have banner-bearing cards -- manhattan_barber_shop, my_website_yanynmdj and urban_living_ams, all
		// service/product grids, and two of them already flagged for losing most of their images.
		if ( $with_banner >= $maj ) { return false; }
		return true;
	}

	/** Build a `{ t:'pricing', plans:[…] }` block from a pricing grid. */
	private static function pricing_table_block( $el ) {
		$plans = array();
		foreach ( self::widget_children( $el ) as $k ) {
			$price = self::cell_price_parts( $k );
			$title = self::item_title_text( $k );
			// no heading / titled class: the plan NAME is the first SHORT text leaf of the card head (a `p.uppercase` "Essential"
			// before the price) — every plan was titled "Plan" (a finding from the feed)
			$subtitle = '';
			if ( '' === $title || null !== $price ) {
				$seen_price = false;
				foreach ( $k->getElementsByTagName( '*' ) as $lf ) {
					if ( $lf->getElementsByTagName( '*' )->length > 1 || in_array( strtolower( $lf->tagName ), array( 'li', 'ul', 'ol', 'a', 'button', 'svg' ), true ) ) { continue; }
					if ( preg_match( '/(?:^|;)\s*position:\s*absolute/i', (string) $lf->getAttribute( 'data-sc-cs' ) ) || false !== strpos( ' ' . self::cls( $lf ) . ' ', ' absolute ' ) ) { continue; } // the "Most Popular" badge is not the name
					$lt = trim( preg_replace( '/\s+/', ' ', self::text( $lf ) ) ); if ( '' === $lt ) { continue; }
					$is_price = null !== $price && false !== strpos( $lt, $price['currency'] . ( false !== strpos( $lt, ',' ) ? $price['price'] : $price['price'] ) );
					if ( $is_price ) { $seen_price = true; continue; }
					if ( ! $seen_price && '' === $title && mb_strlen( $lt ) <= 24 && ! preg_match( '/[.!?]$/', $lt ) ) { $title = $lt; continue; }
					// the paragraph between the price and the feature list is the plan's SUBTITLE (its description)
					if ( $seen_price && '' === $subtitle && 'p' === strtolower( $lf->tagName ) && mb_strlen( $lt ) >= 20 && mb_strlen( $lt ) <= 200 ) { $subtitle = $lt; }
				}
			}
			if ( '' === $title && null === $price ) { continue; }
			$features = array();
			$ul = $k->getElementsByTagName( 'ul' )->item( 0 );
			if ( ! $ul ) { $ul = $k->getElementsByTagName( 'ol' )->item( 0 ); }
			if ( $ul ) {
				foreach ( $ul->getElementsByTagName( 'li' ) as $li ) { $t = self::text( $li ); if ( '' !== $t ) { $features[] = $t; } }
			}
			$btn_label = ''; $btn_url = '';
			foreach ( array( 'a', 'button' ) as $bt ) {
				$b = $k->getElementsByTagName( $bt )->item( 0 );
				if ( $b && self::text( $b ) !== '' ) { $btn_label = self::text( $b ); $btn_url = (string) $b->getAttribute( 'href' ); break; }
			}
			$kcls     = strtolower( (string) $k->getAttribute( 'class' ) );
			// FEATURED signals — beyond a class keyword: a "Most Popular"/"Recommended" BADGE child (the
			// canonical marker), OR a visually-elevated card (lifted `-translate-y`, scaled/ringed, or an
			// ACCENT/brand-coloured border while the neutral plans use slate/gray). The badge also gives the
			// ribbon text. Without this the source's mid plan (badge + brand border + `-translate-y-4`) was
			// never marked featured, losing the whole highlighted-plan treatment.
			$featured = preg_match( '/\b(featured|popular|recommended|highlight(ed)?|best|pro)\b/', $kcls ) ? 'yes' : 'no';
			$ribbon   = '';
			foreach ( $k->getElementsByTagName( '*' ) as $c ) {
				$ct = trim( preg_replace( '/\s+/', ' ', (string) self::text( $c ) ) );
				if ( '' === $ct || mb_strlen( $ct ) > 24 ) { continue; }
				if ( preg_match( '/^(most popular|popular|recommended|best(?: value| seller)?|featured)\b/i', $ct ) ) {
					$cc = strtolower( (string) $c->getAttribute( 'class' ) );
					if ( preg_match( '/(?:^|\s)(?:absolute|rounded-full|uppercase|badge|ribbon|tag)\b|\bbg-/', $cc ) ) { $ribbon = $ct; $featured = 'yes'; break; }
				}
			}
			if ( 'no' === $featured && preg_match( '/-translate-y-|(?:^|\s)scale-1[01]|\bring-\d|border-(?:brand|primary|accent|emerald|green|blue|indigo|purple)/', $kcls ) ) { $featured = 'yes'; }
			$plans[] = array(
				'title'    => $title,
				'subtitle' => $subtitle,
				'currency' => $price ? $price['currency'] : '$',
				'price'    => $price ? $price['price'] : '',
				'period'   => $price ? $price['period'] : '',
				'features' => implode( "\n", $features ),
				'featured' => $featured,
				'ribbon'   => $ribbon,
				'btn_label' => $btn_label,
				'btn_url'   => $btn_url,
			);
		}
		// The plan cards' BOX skin (glass-card: dark fill + radius + border) → box_style on the pricing_table,
		// so every plan keeps the source card look instead of the shortcode's default. Read from the first
		// plan card (they share the skin). The brand ACCENT (check-mark / featured colour) rides along too.
		$card_box = null;
		foreach ( self::widget_children( $el ) as $k ) { $card_box = self::read_card_skin( $k ); if ( $card_box ) { break; } }
		$accent = self::pricing_accent_color( $el );
		$btn_outline_css = self::pricing_outline_button_css( $el );
		$feat = self::pricing_feature_style( $el );
		return count( $plans ) >= 2 ? array( 't' => 'pricing', 'plans' => $plans, 'design' => self::detect_pricing_design( $el ), 'cardBox' => $card_box, 'accent' => $accent, 'btnOutlineCss' => $btn_outline_css, 'feat' => $feat ) : null;
	}

	/** The FEATURE-LIST presentation read from the source's first feature `<li>`: text alignment
	 *  (left/center/right), muted text colour, whether the list uses divider lines vs pure spacing, and the
	 *  feature font-size. The shortcode defaults to centered + divider lines + `.94rem`; most sources are
	 *  left-aligned, divider-less (Tailwind `space-y-*`), and a specific muted colour — so without this the
	 *  converted list mis-matches on all three. Returns array( align, color, dividers, fontSize ). */
	private static function pricing_feature_style( $el ) {
		$out = array( 'align' => '', 'color' => '', 'dividers' => '', 'fontSize' => '' );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$li = null; $ul = null;
		foreach ( self::widget_children( $el ) as $k ) {
			$u = $k->getElementsByTagName( 'ul' )->item( 0 );
			if ( ! $u ) { $u = $k->getElementsByTagName( 'ol' )->item( 0 ); }
			if ( $u ) {
				$ul = $u;
				foreach ( $u->getElementsByTagName( 'li' ) as $l ) { if ( '' !== self::text( $l ) ) { $li = $l; break; } }
			}
			if ( $li ) { break; }
		}
		if ( ! ( $li instanceof DOMElement ) ) { return $out; }
		// Alignment — from the li's flex justification (Tailwind `justify-*`) or text-align. `normal`/`start`
		// = flex-start = left; `center` = center; `flex-end`/`end`/`right` = right.
		$jc = strtolower( self::sc_css( $li, 'justify-content' ) );
		$ta = strtolower( self::sc_css( $li, 'text-align' ) );
		if ( strpos( $jc, 'center' ) !== false || strpos( $ta, 'center' ) !== false ) {
			$out['align'] = 'center';
		} elseif ( strpos( $jc, 'end' ) !== false || $ta === 'right' || strpos( $ta, 'end' ) !== false ) {
			$out['align'] = 'right';
		} else {
			$out['align'] = 'left';
		}
		// Muted feature colour + size come from the li's own computed style (its checkmark icon carries its
		// own accent colour, so the li colour is the text colour).
		$col = trim( self::sc_css( $li, 'color' ) );
		if ( '' !== $col && stripos( $col, 'transparent' ) === false ) { $out['color'] = $col; }
		$fs = trim( self::sc_css( $li, 'font-size' ) );
		if ( '' !== $fs && preg_match( '/^\d/', $fs ) ) { $out['fontSize'] = $fs; }
		// Dividers — `divide-y` on the ul or a `border-b/border-t` on the li means real divider lines;
		// a `space-y-*`/`gap-*` list spaces via margins with NO line. Default '' (unknown) leaves the
		// shortcode's own default in place.
		$ulcls = strtolower( self::cls( $ul ) );
		$licls = strtolower( self::cls( $li ) );
		if ( preg_match( '/\bdivide-y\b/', $ulcls ) || preg_match( '/\bborder-[bt]\b/', $licls ) ) {
			$out['dividers'] = 'yes';
		} elseif ( preg_match( '/\bspace-y-\d/', $ulcls ) || preg_match( '/\bgap-\d/', $ulcls ) ) {
			$out['dividers'] = 'no';
		}
		return $out;
	}

	/** When the NON-featured plan CTAs are OUTLINE buttons (bordered, unfilled — the source's common "outline
	 *  base + a filled accent button on the featured plan"), return scoped custom_css that renders the
	 *  non-featured plan buttons outline (`.fw-pt__plan:not(.is-featured) .fw-pt__btn`), carrying the source
	 *  border colour + hover fill; the featured plan's own filled-accent button stays (featured_style
	 *  accent_button). '' when the buttons aren't outline. */
	private static function pricing_outline_button_css( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$outline = 0; $solid = 0; $border = ''; $bw = '1px'; $hover_bg = '';
		foreach ( self::widget_children( $el ) as $k ) {
			$b = $k->getElementsByTagName( 'a' )->item( 0 );
			if ( ! $b ) { $b = $k->getElementsByTagName( 'button' )->item( 0 ); }
			if ( ! ( $b instanceof DOMElement ) ) { continue; }
			$bcls = ' ' . strtolower( self::cls( $b ) ) . ' ';
			$bg   = self::sc_css( $b, 'background-color' );
			$bdw  = self::sc_css( $b, 'border-top-width' );
			$filled   = ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/', $bg ) );
			$bordered = ( strpos( $bcls, 'border' ) !== false ) || ( $bdw !== '' && $bdw !== '0px' && $bdw !== '0' );
			if ( $filled ) { $solid++; continue; }
			if ( $bordered ) {
				$outline++;
				if ( '' === $border ) {
					$bc = self::sc_css( $b, 'border-top-color' );
					if ( $bc !== '' && stripos( $bc, 'transparent' ) === false ) { $border = $bc; }
					if ( $bdw !== '' && $bdw !== '0px' ) { $bw = $bdw; }
					if ( class_exists( 'FW_Site_Converter_Tailwind' ) && strpos( $bcls, 'hover:' ) !== false ) {
						$c = FW_Site_Converter_Tailwind::compile_class_set( self::cls( $b ) );
						if ( ! empty( $c['hover']['background-color'] ) ) { $hover_bg = trim( preg_replace( '#\s*/\s*var\([^)]*\)#', '', (string) $c['hover']['background-color'] ) ); }
					}
				}
			}
		}
		if ( $outline <= $solid || '' === $border ) { return ''; }
		$css = 'selector .fw-pt__plan:not(.is-featured) .fw-pt__btn{background:transparent;border:' . $bw . ' solid ' . $border . ';}';
		if ( '' !== $hover_bg && stripos( $hover_bg, 'transparent' ) === false ) {
			$css .= 'selector .fw-pt__plan:not(.is-featured) .fw-pt__btn:hover{background:' . $hover_bg . ';border-color:' . $hover_bg . ';}';
		}
		return $css;
	}

	/** The plan CTA button style — 'outline' when the NON-featured plans use bordered, unfilled buttons (the
	 *  source's common "outline base + a filled accent button on the featured plan" pattern), else 'solid'.
	 *  The featured plan's own accent-fill is handled by the featured_style `accent_button`. '' = leave default. */
	private static function pricing_button_style( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$outline = 0; $solid = 0;
		foreach ( self::widget_children( $el ) as $k ) {
			$b = $k->getElementsByTagName( 'a' )->item( 0 );
			if ( ! $b ) { $b = $k->getElementsByTagName( 'button' )->item( 0 ); }
			if ( ! ( $b instanceof DOMElement ) ) { continue; }
			$bcls = ' ' . strtolower( self::cls( $b ) ) . ' ';
			$bg   = self::sc_css( $b, 'background-color' );
			$bw   = self::sc_css( $b, 'border-top-width' );
			$filled   = ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/rgba\([^)]*,\s*0\s*\)/', $bg ) );
			$bordered = ( strpos( $bcls, 'border' ) !== false ) || ( $bw !== '' && $bw !== '0px' && $bw !== '0' );
			if ( $filled ) { $solid++; } elseif ( $bordered ) { $outline++; }
		}
		return ( $outline > $solid ) ? 'outline' : ( $solid > 0 ? 'solid' : '' );
	}

	/** The pricing table's brand ACCENT colour — the check-mark / `text-brand` glyph colour, else a filled
	 *  CTA button's saturated background. '' when none. Feeds the pricing_table accent_color option. */
	private static function pricing_accent_color( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		foreach ( $el->getElementsByTagName( '*' ) as $c ) {
			$cl = ' ' . strtolower( self::cls( $c ) ) . ' ';
			if ( strpos( $cl, 'text-brand' ) !== false || strpos( $cl, 'text-primary' ) !== false || strpos( $cl, 'text-accent' ) !== false ) {
				$col = self::sc_css( $c, 'color' );
				if ( $col !== '' && preg_match( '/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/', $col, $m ) && ( max( $m[1], $m[2], $m[3] ) - min( $m[1], $m[2], $m[3] ) ) > 40 ) { return $col; }
			}
		}
		foreach ( $el->getElementsByTagName( 'a' ) as $a ) {
			$bg = self::sc_css( $a, 'background-color' );
			if ( $bg !== '' && preg_match( '/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/', $bg, $m ) && ( max( $m[1], $m[2], $m[3] ) - min( $m[1], $m[2], $m[3] ) ) > 40 && max( $m[1], $m[2], $m[3] ) < 245 ) { return $bg; }
		}
		return '';
	}

	/**
	 * The pricing-table `design` (card fill) inferred from the plan cards' styling: a gradient fill →
	 * `gradient`; a dark fill → `dark`; a bordered card with NO fill → `outline`; else the `classic` default.
	 * (`modern`/`minimal` overlap too much with classic to pick deterministically.) Conservative — the
	 * DOMINANT treatment across the plan cards wins, else classic. featured plan + columns stay on n_pricing.
	 */
	private static function detect_pricing_design( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return 'classic'; }
		$grad = 0; $dark = 0; $outline = 0; $n = 0;
		foreach ( self::widget_children( $el ) as $k ) {
			if ( ! ( $k instanceof DOMElement ) ) { continue; }
			$n++;
			$c   = ' ' . strtolower( self::cls( $k ) ) . ' ';
			$cs  = (string) $k->getAttribute( 'data-sc-cs' );
			$bg  = self::sc_css( $k, 'background-color' );
			$bgi = self::sc_css( $k, 'background-image' );
			$has_fill   = ( $bg !== '' && stripos( $bg, 'transparent' ) === false && ! preg_match( '/,\s*0(?:\.0+)?\s*\)/', $bg ) ) || preg_match( '/\bbg-(?!transparent|white\b)[a-z]/', $c );
			$has_border = (bool) ( preg_match( '/(?:^|\s)border(?:-[0-9]|\s)/', $c ) || preg_match( '/border(?:-top)?-width:\s*[1-9]/', $cs ) );
			if ( strpos( $c, 'bg-gradient' ) !== false || stripos( $bgi, 'gradient' ) !== false ) { $grad++; continue; }
			if ( preg_match( '/\bbg-(?:black|zinc-9|neutral-9|gray-9|slate-9|stone-9|\[#0)/', $c ) || self::color_is_dark( $bg ) ) { $dark++; continue; }
			if ( $has_border && ! $has_fill ) { $outline++; }
		}
		if ( $n < 1 ) { return 'classic'; }
		$half = (int) ceil( $n / 2 );
		if ( $grad >= $half )    { return 'gradient'; }
		if ( $dark >= $half )    { return 'dark'; }
		if ( $outline >= $half ) { return 'outline'; }
		return 'classic';
	}

	/** A CSS color (rgb/rgba/#hex) whose luminance is clearly dark (near-black card fill). '' → false. */
	private static function color_is_dark( $color ) {
		$hex = self::color_to_hex( (string) $color );
		if ( ! preg_match( '/^#([0-9a-f]{6})$/i', $hex, $m ) ) { return false; }
		$r = hexdec( substr( $m[1], 0, 2 ) ); $g = hexdec( substr( $m[1], 2, 2 ) ); $b = hexdec( substr( $m[1], 4, 2 ) );
		return ( 0.2126 * $r + 0.7152 * $g + 0.0722 * $b ) < 60; // ~dark
	}

	/* --------------------------------------------------------------------- *
	 * Steps / process recognizer
	 * --------------------------------------------------------------------- */

	/** Does this child carry a numeric step marker (leading "Step N"/"N", or a `.step-number`/`.circle`)? */
	private static function step_marker( $el ) {
		$t = self::text( $el );
		if ( preg_match( '/^\s*(?:step\s*)?(\d{1,2})\b/i', $t ) ) { return true; }
		foreach ( $el->getElementsByTagName( '*' ) as $c ) {
			// A distinct element whose ENTIRE text is a 1-2 digit number (optionally zero-padded: 01, 02)
			// is a step-number badge — the common "big number + title + copy" step card, where the number
			// span abuts the title with no separator ("01Tell Us…") so the leading-digit test above can't
			// fire (no word boundary between "1" and "T").
			if ( preg_match( '/^0*\d{1,2}$/', trim( self::text( $c ) ) ) ) { return true; }
			$cc = strtolower( (string) $c->getAttribute( 'class' ) );
			if ( preg_match( '/step-?(number|index|num|count)|\b(number|circle|marker|count)\b/', $cc ) && preg_match( '/\d/', self::text( $c ) ) ) { return true; }
		}
		return false;
	}

	/**
	 * The ICON of one step (not its number badge): a lucide/iconify icon → `array('lucide'=>'lucide/name')`,
	 * an inline decorative `<svg>` → `array('svg'=>markup)`, or an `<img>` → `array('img'=>src)`. Skips the
	 * numeric marker (a tiny svg that is really the number chip is ignored — we want the glyph). Null if none.
	 */
	private static function step_icon( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return null; }
		$lucide = self::detect_lucide_in( $el );
		if ( '' !== $lucide ) { return array( 'lucide' => $lucide ); }
		foreach ( $el->getElementsByTagName( 'svg' ) as $svg ) {
			// An inline Lucide svg carries its name in its own class (`lucide lucide-search`) → prefer the
			// library reference over raw markup so it maps to a named icon (recolourable, crisp).
			if ( preg_match( '/\blucide-([a-z0-9-]+)/', self::cls( $svg ), $lm ) && 'lucide' !== $lm[1] ) { return array( 'lucide' => 'lucide/' . $lm[1] ); }
			// Skip an svg whose siblings/self is purely the number chip (rare); otherwise the first real svg.
			$html = self::inner_html( $svg );
			if ( '' === trim( $html ) ) { continue; }
			$outer = $svg->ownerDocument ? $svg->ownerDocument->saveHTML( $svg ) : '';
			if ( '' !== trim( (string) $outer ) ) { return array( 'svg' => (string) $outer ); }
		}
		foreach ( $el->getElementsByTagName( 'img' ) as $img ) {
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( '' !== $src ) { return array( 'img' => $src ); }
		}
		return null;
	}

	/** TIGHT: a `.steps`/`.process` flow OR >=2 numbered step cards, each with a title. */
	/**
	 * Do MOST of this container's cells carry a real content PHOTO? A widget whose shortcode has no image
	 * surface -- steps, progress, counters -- must not claim a grid of photo cards, because the build then
	 * keeps only the parsed number/label/percent and every <img> is silently discarded. This is the same
	 * rule is_counter_grid() already applies per cell; steps (98) and progress (96) sit ABOVE card_grid (90),
	 * so when they mis-fire nothing lower ever gets to reproduce the photos. Measured: spectrum_house_hub
	 * and personal_blog_writer lost event/article cards to `steps`, radiant_smile_studio to `progress`.
	 * SVG / data-URI glyphs do not count -- those are legitimately icons.
	 */
	private static function cells_are_photo_cards( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cells = 0; $with = 0;
		foreach ( self::el_children( $el ) as $k ) {
			if ( in_array( strtolower( $k->nodeName ), array( 'script', 'style', 'br', 'hr' ), true ) ) { continue; }
			$cells++;
			foreach ( $k->getElementsByTagName( 'img' ) as $im ) {
				$src = trim( (string) $im->getAttribute( 'src' ) );
				if ( '' === $src ) { $src = trim( (string) $im->getAttribute( 'data-src' ) ); }
				if ( '' === $src || 0 === strpos( $src, 'data:image/svg' ) || preg_match( '/\.svg(?:$|\?)/i', $src ) ) { continue; }
				$with++;
				break;
			}
		}
		return $cells >= 2 && $with * 2 > $cells;
	}

	private static function is_steps_flow( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'table', 'thead', 'tbody', 'tr', 'nav', 'dl', 'details', 'summary' ), true ) ) { return false; }
		if ( $el->getElementsByTagName( 'details' )->length ) { return false; }
		// A TAB-PANEL container is not a steps flow. Each panel holds a whole page section, so when the
		// panels happen to share a heading and carry a leading number they satisfy titled/numbered and the
		// entire page is claimed as a 5-step flow -- measured on cms_plat_2qkh5h6b, where `sc-tabs__panels`
		// was claimed while holding 55 images, and on expert_community_hub (48). Panels belong to the tabs
		// recognizer, not this one.
		if ( preg_match( '/\b(tabs?__panels|tab-content|tab-panes|tabpanels)\b/', self::cls( $el ) ) ) { return false; }
		$panelish = 0;
		foreach ( self::el_children( $el ) as $pc ) {
			if ( 'tabpanel' === strtolower( (string) $pc->getAttribute( 'role' ) ) ) { $panelish++; }
		}
		if ( $panelish >= 2 ) { return false; }
		// A grid of PHOTO cards is not a steps flow -- `steps` renders a marker + title + text and would
		// drop every image (see cells_are_photo_cards).
		if ( self::cells_are_photo_cards( $el ) ) { return false; }

		$kids = self::widget_children( $el );
		$n    = count( $kids );
		if ( $n < 2 ) { return false; }
		// The class signal must come from the CONTAINER's own class, not from a child's. A page wrapper
		// whose children include one `process` / `how-it-works` section otherwise qualifies, and because
		// class_signal alone bypasses the numbered-marker test, the whole page is claimed as a steps flow.
		// Measured: is_steps_flow claimed 44 containers, the two largest holding 55 and 48 images -- entire
		// pages. A child-only signal now still has to satisfy the marker requirement. See 8.45/8.48.
		$own_cls   = self::cls( $el );
		$kids_cls  = '';
		foreach ( $kids as $k ) { $kids_cls .= ' ' . strtolower( (string) $k->getAttribute( 'class' ) ); }
		$sig_re       = '/\b(steps?|process|how-?it-?works|process-?flow)\b/';
		$class_signal = (bool) preg_match( $sig_re, $own_cls );
		$kid_signal   = (bool) preg_match( $sig_re, $kids_cls );
		$titled = 0; $numbered = 0;
		foreach ( $kids as $k ) {
			if ( self::item_title_text( $k ) !== '' ) { $titled++; }
			if ( self::step_marker( $k ) ) { $numbered++; }
		}
		if ( $titled < 2 ) { return false; }
		if ( $class_signal ) { return true; }
		// The steps shortcode renders marker + title + copy and nothing else: a card carrying MORE text leaves (a "01 / NODE"
		// label, a "Status: …" footer line) would lose them — such a grid stays a card grid (every leaf kept).
		foreach ( $kids as $k ) { if ( ! self::step_card_is_lean( $k ) ) { return false; } }
		if ( $kid_signal && $numbered >= max( 2, (int) ceil( $n * 0.6 ) ) ) { return true; }
		return $numbered >= $n;
	}

	/** Every text leaf of a step card is its marker (a bare 1–2 digit number / "Step N"), its title, or body copy — nothing the
	 *  steps shortcode would drop. */
	private static function step_card_is_lean( $k ) {
		if ( ! ( $k instanceof DOMElement ) ) { return false; }
		$title = trim( preg_replace( '/\s+/', ' ', self::item_title_text( $k ) ) );
		$extra = 0;
		foreach ( $k->getElementsByTagName( '*' ) as $c ) {
			if ( $c->getElementsByTagName( '*' )->length > 0 ) { continue; } // leaves only
			$t = trim( preg_replace( '/\s+/', ' ', self::text( $c ) ) );
			if ( '' === $t ) { continue; }
			$tag = strtolower( $c->tagName );
			if ( preg_match( '/^(?:step\s*)?0*\d{1,2}$/i', $t ) ) { continue; }                 // the marker
			if ( '' !== $title && ( $t === $title || false !== strpos( $title, $t ) ) ) { continue; } // the title (or a part of it)
			if ( 'p' === $tag || mb_strlen( $t ) >= 60 ) { continue; }                                 // body copy
			$extra++;
		}
		return 0 === $extra;
	}

	/** Build a `{ t:'steps', items:[{title,content,number}] }` block. */
	private static function steps_block( $el ) {
		$items = array();
		foreach ( self::widget_children( $el ) as $k ) {
			$title = self::item_title_text( $k );
			if ( '' === $title ) { continue; }
			$num = ''; $num_el = null;
			// the numeral's OWN element first (a `text-6xl text-primary/10 absolute top-4 right-4` watermark) — its
			// typography and corner placement are the card's signature; a 60px faded "01" had rendered as a 14px chip
			foreach ( $k->getElementsByTagName( '*' ) as $c ) {
				if ( $c->getElementsByTagName( '*' )->length > 0 ) { continue; }
				$ct = trim( self::text( $c ) );
				if ( preg_match( '/^(?:step\s*)?0*\d{1,2}$/i', $ct ) ) { $num_el = $c; $num = preg_replace( '/^step\s*/i', '', $ct ); break; }
			}
			if ( '' === $num && preg_match( '/^\s*(?:step\s*)?(\d{1,2})\b/i', self::text( $k ), $m ) ) { $num = $m[1]; }
			$item = array( 'title' => $title, 'content' => self::item_body_text( $k, $title ), 'number' => $num, 'icon' => self::step_icon( $k ) );
			// the title's / body's own typography (a 20px semibold display title, 16px muted copy) — the shortcode's defaults re-sized them
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $ht ) { $hx = $k->getElementsByTagName( $ht )->item( 0 ); if ( $hx instanceof DOMElement ) { $item['titleCs'] = self::cs_text_decls( (string) $hx->getAttribute( 'data-sc-cs' ) ); $tm = self::el_margin( $hx ); if ( ! empty( $tm['bottom'] ) ) { $item['titleMb'] = (int) round( (float) $tm['bottom'] ); } break; } }
			foreach ( $k->getElementsByTagName( 'p' ) as $px ) { if ( trim( self::text( $px ) ) !== '' ) { $item['textCs'] = self::cs_text_decls( (string) $px->getAttribute( 'data-sc-cs' ) ); break; } }
			if ( $num_el instanceof DOMElement ) {
				$ncs = (string) $num_el->getAttribute( 'data-sc-cs' );
				$item['numCs'] = $ncs;
				if ( preg_match( '/(?:^|;)\s*position:\s*absolute/i', $ncs ) ) {
					// only the sides the source DECLARES (`top-4 right-4`): the capture stamps all four computed offsets, and
					// pinning bottom + left too would freeze the numeral's box
					$pos = array(); $kc = ' ' . self::cls( $num_el ) . ' '; $declared = array();
					foreach ( array( 'top', 'right', 'bottom', 'left' ) as $side ) { if ( preg_match( '/\s-?' . $side . '-(\d+(?:\.\d+)?|\[[^\]]+\])\s/', $kc ) || preg_match( '/\sinset-/', $kc ) ) { $declared[] = $side; } }
					if ( ! $declared ) { $declared = array( 'top', 'right' ); }
					foreach ( $declared as $side ) {
						if ( preg_match( '/(?:^|;)\s*' . $side . ':\s*(-?[0-9.]+px)/i', $ncs, $pm ) ) { $pos[ $side ] = $pm[1]; }
						elseif ( preg_match( '/\s(-?)' . $side . '-(\d+(?:\.\d+)?)\s/', $kc, $tm ) ) { $pos[ $side ] = ( ( '-' === $tm[1] ? -1 : 1 ) * (float) $tm[2] * 4 ) . 'px'; }
					}
					if ( $pos ) { $item['numPos'] = $pos; }
				}
			}
			$items[] = $item;
		}
		return count( $items ) >= 2 ? array( 't' => 'steps', 'items' => $items, 'design' => self::detect_steps_design( $el, $items ) ) : null;
	}

	/* --------------------------------------------------------------------- *
	 * Timeline recognizer
	 * --------------------------------------------------------------------- */

	/** A date token from a child: a `<time>` element or a year / "Mon YYYY" / "MM/YYYY" in its text. */
	private static function timeline_date( $el ) {
		$time = $el->getElementsByTagName( 'time' )->item( 0 );
		if ( $time && self::text( $time ) !== '' ) { return self::text( $time ); }
		$t = self::text( $el );
		if ( preg_match( '/\b((?:19|20)\d{2})\b/', $t, $m ) ) { return $m[1]; }
		if ( preg_match( '/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4}\b/i', $t, $m ) ) { return $m[0]; }
		if ( preg_match( '#\b\d{1,2}/\d{4}\b#', $t, $m ) ) { return $m[0]; }
		return '';
	}

	/** TIGHT: a `.timeline` container OR >=2 dated entries, each with a title. */
	private static function is_timeline( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'table', 'thead', 'tbody', 'tr', 'nav', 'dl', 'details', 'summary' ), true ) ) { return false; }
		if ( $el->getElementsByTagName( 'details' )->length ) { return false; }
		$kids = self::widget_children( $el );
		$n    = count( $kids );
		if ( $n < 2 ) { return false; }
		$cls = self::cls( $el );
		foreach ( $kids as $k ) { $cls .= ' ' . strtolower( (string) $k->getAttribute( 'class' ) ); }
		$class_signal = (bool) preg_match( '/\btimeline\b/', $cls );
		$dated = 0; $titled = 0;
		foreach ( $kids as $k ) {
			if ( self::timeline_date( $k ) !== '' ) { $dated++; }
			if ( self::item_title_text( $k ) !== '' ) { $titled++; }
		}
		if ( $titled < 2 ) { return false; }
		return $class_signal ? ( $dated >= 1 ) : ( $dated >= $n );
	}

	/** Build a `{ t:'timeline', items:[{date,title,text}] }` block. */
	private static function timeline_block( $el ) {
		$items = array();
		foreach ( self::widget_children( $el ) as $k ) {
			$title = self::item_title_text( $k );
			$date  = self::timeline_date( $k );
			if ( '' === $title && '' === $date ) { continue; }
			$body  = self::item_body_text( $k, $title );
			if ( $date !== '' && strpos( $body, $date ) === 0 ) { $body = trim( substr( $body, strlen( $date ) ) ); }
			$items[] = array( 'date' => $date, 'title' => $title, 'text' => $body );
		}
		return count( $items ) >= 2 ? array( 't' => 'timeline', 'items' => $items, 'design' => self::detect_timeline_design( $el ) ) : null;
	}

	/* --------------------------------------------------------------------- *
	 * Progress / skill-bars recognizer
	 * --------------------------------------------------------------------- */

	/** A STRUCTURAL percent for a bar item (role=progressbar[aria-valuenow] or an inner `width:NN%`), or null. */
	private static function bar_percent( $el ) {
		// role=progressbar + aria-valuenow (self or descendant)
		$cands = array();
		if ( 'progressbar' === strtolower( (string) $el->getAttribute( 'role' ) ) ) { $cands[] = $el; }
		foreach ( $el->getElementsByTagName( '*' ) as $c ) { if ( 'progressbar' === strtolower( (string) $c->getAttribute( 'role' ) ) ) { $cands[] = $c; } }
		foreach ( $cands as $c ) {
			$v = $c->getAttribute( 'aria-valuenow' );
			if ( $v !== '' && is_numeric( $v ) ) { return max( 0, min( 100, (int) round( (float) $v ) ) ); }
		}
		// An inner element with inline style width:NN%
		$nodes = array( $el );
		foreach ( $el->getElementsByTagName( '*' ) as $c ) { $nodes[] = $c; }
		foreach ( $nodes as $c ) {
			$st = (string) $c->getAttribute( 'style' );
			if ( $st !== '' && preg_match( '/width\s*:\s*([\d.]+)\s*%/i', $st, $m ) ) {
				$cc = strtolower( (string) $c->getAttribute( 'class' ) );
				$pc = ( $c->parentNode instanceof DOMElement ) ? strtolower( (string) $c->parentNode->getAttribute( 'class' ) ) : '';
				// Only a bar fill if the element OR its parent READS like a bar. The old `|| $c !== $el` treated
				// ANY descendant with an inline width:% as a bar, so a scroll-progress indicator / a %-width layout
				// element turned a whole content section into a fake `progress` widget (its cards' text merged).
				if ( preg_match( '/\b(bar|fill|progress|meter|gauge|track|slider|skill|level|value)\b/', $cc . ' ' . $pc ) ) { return max( 0, min( 100, (int) round( (float) $m[1] ) ) ); }
			}
			// A utility-class fill (`w-[96%]` / `w-3/4`) inside a TRACK: a short (<= 16px), rounded / clipped parent whose only child it is
			// (a `h-2 overflow-hidden rounded-full bg-white/10` track holding a `h-full w-[96%] bg-accent` fill).
			$ccls = ' ' . strtolower( (string) $c->getAttribute( 'class' ) ) . ' ';
			$pct = null;
			if ( preg_match( '/(?:^|\s)w-\[([0-9.]+)%\]/', $ccls, $wm ) ) { $pct = (float) $wm[1]; }
			elseif ( preg_match( '/(?:^|\s)w-([1-9][0-9]?)\/([1-9][0-9]?)(?:\s|$)/', $ccls, $wm ) && (int) $wm[2] > 0 ) { $pct = (float) $wm[1] / (float) $wm[2] * 100; }
			if ( null !== $pct && $c->parentNode instanceof DOMElement ) {
				$pp = $c->parentNode; $pcs = (string) $pp->getAttribute( 'data-sc-cs' );
				$ph = preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $pcs, $hm ) ? (float) $hm[1] : 0.0;
				$track = $ph > 0 && $ph <= 16 && 1 === count( self::el_children( $pp ) ) && ( preg_match( '/(?:^|;)\s*overflow:\s*hidden/i', $pcs ) || preg_match( '/(?:^|;)\s*border-radius:\s*[1-9]/i', $pcs ) );
				if ( $track ) { return max( 0, min( 100, (int) round( $pct ) ) ); }
			}
		}
		return null;
	}

	/** TIGHT: >=2 items, EVERY item a structural bar (progressbar / width:%). Text-only "%" (a stat) is excluded. */
	private static function is_progress_bars( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'table', 'thead', 'tbody', 'tr', 'nav', 'dl', 'details', 'summary' ), true ) ) { return false; }
		if ( $el->getElementsByTagName( 'details' )->length ) { return false; }
		// A grid of PHOTO cards is not a bank of progress bars -- `progress` keeps only label + percent.
		if ( self::cells_are_photo_cards( $el ) ) { return false; }
		$kids = self::widget_children( $el );
		$n    = count( $kids );
		if ( $n < 2 ) { return false; }
		$bars = 0;
		foreach ( $kids as $k ) { if ( self::bar_percent( $k ) !== null ) { $bars++; } }
		return $bars >= 2 && $bars === $n;
	}

	/** Build a `{ t:'progress', bars:[{label,percent}] }` block. */
	private static function progress_block( $el ) {
		$bars = array();
		foreach ( self::widget_children( $el ) as $k ) {
			$pct = self::bar_percent( $k );
			if ( null === $pct ) { continue; }
			// Label = a dedicated label element, else the item text with the percent stripped.
			$label = '';
			foreach ( $k->getElementsByTagName( '*' ) as $c ) {
				$cc = strtolower( (string) $c->getAttribute( 'class' ) );
				if ( preg_match( '/\b(label|skill-?name|title|name)\b/', $cc ) && self::text( $c ) !== '' ) { $label = self::text( $c ); break; }
			}
			if ( '' === $label ) { $label = trim( preg_replace( '/\b\d{1,3}\s*%/', '', self::text( $k ) ) ); }
			$bars[] = array( 'label' => $label, 'percent' => $pct );
		}
		return count( $bars ) >= 2 ? array( 't' => 'progress', 'bars' => $bars, 'design' => self::detect_progress_design( $el ) ) : null;
	}

	/* --------------------------------------------------------------------- *
	 * Tabs recognizer
	 * --------------------------------------------------------------------- */

	/** All descendants (optionally including $el) with a given role. */
	private static function els_with_role( $el, $role ) {
		$out = array();
		foreach ( $el->getElementsByTagName( '*' ) as $c ) { if ( $role === strtolower( (string) $c->getAttribute( 'role' ) ) ) { $out[] = $c; } }
		return $out;
	}

	/** TIGHT: a real tab widget — >=2 tabs each resolving to a panel. A plain <ul> nav never qualifies. */
	private static function is_tabs_widget( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( in_array( $tag, array( 'table', 'nav', 'details', 'summary' ), true ) ) { return false; }
		// An accordion (>=2 <details>) is not a tabs widget.
		$dets = 0;
		foreach ( $el->getElementsByTagName( 'details' ) as $d ) { if ( $d->getElementsByTagName( 'summary' )->length ) { $dets++; } }
		if ( $dets >= 2 ) { return false; }
		// ARIA tabs. GATE FIRST: $el must BE the widget, not merely CONTAIN one. els_with_role() searches
		// the whole subtree, so without this every ancestor of a tabs widget matches -- up to the page
		// wrapper. Measured: the predicate fired on 36 sites, every time on an element holding 100% of the
		// page text, and on nurish_petfood it claimed a `max-w-7xl grid` content band and dropped its
		// photos. (Those page-level matches were mostly harmless only because collect_blocks() never tests
		// a node against the recognizers -- see 08-render-audit.md 8.45; that containment must not be
		// relied on.) A real tabs widget keeps its tablist NEAR the top: as $el itself, or within two
		// levels of it.
		$near_tablist = ( 'tablist' === strtolower( (string) $el->getAttribute( 'role' ) ) );
		if ( ! $near_tablist ) {
			foreach ( self::el_children( $el ) as $c1 ) {
				if ( 'tablist' === strtolower( (string) $c1->getAttribute( 'role' ) ) ) { $near_tablist = true; break; }
				foreach ( self::el_children( $c1 ) as $c2 ) {
					if ( 'tablist' === strtolower( (string) $c2->getAttribute( 'role' ) ) ) { $near_tablist = true; break 2; }
				}
			}
		}

		// ARIA tabs.
		$tabs   = self::els_with_role( $el, 'tab' );
		$panels = self::els_with_role( $el, 'tabpanel' );
		if ( $near_tablist && count( $tabs ) >= 2 ) {
			if ( count( $panels ) >= 2 ) { return true; }
			$resolved = 0; $doc = $el->ownerDocument;
			foreach ( $tabs as $t ) { $id = trim( (string) $t->getAttribute( 'aria-controls' ) ); if ( $id !== '' && $doc && $doc->getElementById( $id ) ) { $resolved++; } }
			if ( $resolved >= 2 ) { return true; }
		}
		// Class-based (`.tabs`/`.nav-tabs` + [data-tab]/aria-controls labels + `.tab-pane`/[data-tab-content] panels).
		$cls = self::cls( $el );
		if ( preg_match( '/\b(tabs|nav-tabs|tab-group|tabbed|tabset)\b/', $cls ) ) {
			$doc       = $el->ownerDocument;
			$labels    = 0;
			$resolved2 = 0; // labels whose aria-controls / data-tab points at a real panel element
			foreach ( $el->getElementsByTagName( '*' ) as $c ) {
				$ct = strtolower( $c->tagName );
				if ( ! in_array( $ct, array( 'a', 'button', 'li', 'span' ), true ) ) { continue; }
				$cc = strtolower( (string) $c->getAttribute( 'class' ) );
				if ( $c->hasAttribute( 'data-tab' ) || $c->hasAttribute( 'aria-controls' ) || preg_match( '/\b(tab-link|nav-link|tab-title|tab-btn)\b/', $cc ) ) {
					$labels++;
					// A label whose aria-controls / data-tab id resolves to an element in the doc IS a working
					// tab — this is how a BEM tabs component (`sc-tabs` → `sc-tabs__list` buttons + a
					// `sc-tabs__panels` container of id'd panels, no `tab-pane` class) is recognized.
					$tgt = trim( (string) $c->getAttribute( 'aria-controls' ) );
					if ( '' === $tgt ) { $tgt = trim( (string) $c->getAttribute( 'data-tab' ) ); }
					if ( '' !== $tgt && $doc && $doc->getElementById( $tgt ) ) { $resolved2++; }
				}
			}
			$panels2 = 0;
			foreach ( $el->getElementsByTagName( '*' ) as $c ) {
				$cc = strtolower( (string) $c->getAttribute( 'class' ) );
				if ( $c->hasAttribute( 'data-tab-content' ) || preg_match( '/\b(tab-pane|tab-panel|tab-content-item)\b/', $cc ) ) { $panels2++; }
			}
			if ( $labels >= 2 && ( $panels2 >= 2 || $resolved2 >= 2 ) ) { return true; }
		}
		return false;
	}

	/** Build a `{ t:'tabs', items:[{title,content,active}] }` block. */
	private static function tabs_block( $el ) {
		$doc    = $el->ownerDocument;
		$labels = self::els_with_role( $el, 'tab' );
		$panels = self::els_with_role( $el, 'tabpanel' );
		if ( count( $labels ) < 2 ) {
			// Class-based fallback.
			$labels = array(); $panels = array();
			foreach ( $el->getElementsByTagName( '*' ) as $c ) {
				$ct = strtolower( $c->tagName );
				$cc = strtolower( (string) $c->getAttribute( 'class' ) );
				if ( in_array( $ct, array( 'a', 'button', 'li', 'span' ), true ) && ( $c->hasAttribute( 'data-tab' ) || $c->hasAttribute( 'aria-controls' ) || preg_match( '/\b(tab-link|nav-link|tab-title|tab-btn)\b/', $cc ) ) ) { $labels[] = $c; }
				if ( $c->hasAttribute( 'data-tab-content' ) || preg_match( '/\b(tab-pane|tab-panel|tab-content-item)\b/', $cc ) ) { $panels[] = $c; }
			}
		}
		$items = array();
		foreach ( $labels as $i => $lab ) {
			$title = self::text( $lab );
			if ( '' === $title ) { continue; }
			$panel = null;
			$ctrl  = trim( (string) $lab->getAttribute( 'aria-controls' ) );
			if ( '' === $ctrl ) { $ctrl = trim( (string) $lab->getAttribute( 'data-tab' ) ); }
			if ( '' !== $ctrl && $doc ) {
				$p = $doc->getElementById( $ctrl );
				if ( ! $p ) {
					foreach ( $panels as $pp ) { if ( trim( (string) $pp->getAttribute( 'data-tab-content' ) ) === $ctrl || trim( (string) $pp->getAttribute( 'id' ) ) === $ctrl ) { $p = $pp; break; } }
				}
				$panel = $p;
			}
			if ( ! $panel && isset( $panels[ $i ] ) ) { $panel = $panels[ $i ]; }
			// RAW (data-sc-cs kept) so the catalog decomposer can read the computed colours a class can't resolve
			// (the `bg-primary` / `text-primary-foreground` red bands). The code-block fallback tolerates the inert
			// data-sc-cs attributes.
			$content = $panel ? trim( self::inner_html( $panel ) ) : '';
			$active  = ( 'true' === strtolower( (string) $lab->getAttribute( 'aria-selected' ) ) || preg_match( '/\bactive\b/', strtolower( (string) $lab->getAttribute( 'class' ) ) ) ) ? 'yes' : 'no';
			// A RICH panel (a big verbatim layout — the burger source's menu tab: a catalog of colour-banded category
			// grids) is routed to a SNIPPET: the mapper creates a `snippet` CPT holding this HTML verbatim inside
			// `.sc-tw` and sets the tab content to `[snippet id="…"]`. A page-builder tab panel (a wp-editor field)
			// would otherwise mangle 30 KB of grid markup through wpautop/kses and drop the Tailwind classes. A
			// SMALL panel (a short FAQ answer) stays inline. Signal: long content, or block structure (a grid / ≥2
			// sub-headings) that reads as a full layout rather than a sentence.
			$is_rich = ( strlen( $content ) > 600 )
				|| ( preg_match_all( '/<h[1-6]\b/i', $content ) >= 2 )
				|| ( false !== stripos( $content, 'grid-cols' ) );
			$items[] = array( 'title' => $title, 'content' => $content, 'active' => $active, 'snippet' => (bool) $is_rich );
		}
		if ( count( $items ) < 2 ) { return null; }
		// Hoist a SHARED SECTION HEADING repeated at the top of EVERY panel (the burger source's "OUR MENU" title + rule)
		// OUT of the tabs, so it renders ONCE above them as the section heading — not duplicated inside each tab
		// (and, since each panel is a snippet, not baked into every snippet).
		$section_heading = self::extract_shared_tab_heading( $items );
		$out = array( 't' => 'tabs', 'items' => $items, 'design' => self::detect_tabs_design( $el ) );
		if ( is_array( $section_heading ) ) { $out['section_heading'] = $section_heading; }
		return $out;
	}

	/**
	 * If every tab panel begins with the SAME heading block (a `text-center` intro wrapping an h1–h3 + an
	 * optional decorative rule — no grid/cards), that's the SECTION heading duplicated into each panel. Strip it
	 * from each panel's content (mutating $items by reference) and return it as a heading block `{ level, text,
	 * html, cs, align }` to render once above the tabs. Returns null when the panels don't share a lead heading.
	 *
	 * @param array $items tab items (each { title, content, … }), modified in place
	 * @return array|null
	 */
	private static function extract_shared_tab_heading( array &$items ) {
		$lead_of = function ( $html ) {
			$doc = self::load_dom( '<div id="sc-w">' . (string) $html . '</div>' );
			if ( ! $doc ) { return null; }
			$w = $doc->getElementById( 'sc-w' );
			if ( ! ( $w instanceof DOMElement ) ) { return null; }
			$first = null;
			foreach ( $w->childNodes as $n ) { if ( XML_ELEMENT_NODE === $n->nodeType ) { $first = $n; break; } }
			if ( ! ( $first instanceof DOMElement ) ) { return null; }
			// The lead block must be a HEADING intro: contains an h1–h3, and NO grid/card/list content.
			$h = null;
			foreach ( array( 'h1', 'h2', 'h3' ) as $ht ) { $x = $first->getElementsByTagName( $ht )->item( 0 ); if ( $x ) { $h = $x; break; } }
			if ( $first->nodeName === 'h1' || $first->nodeName === 'h2' || $first->nodeName === 'h3' ) { $h = $first; }
			if ( ! ( $h instanceof DOMElement ) ) { return null; }
			if ( $first->getElementsByTagName( 'img' )->length || $first->getElementsByTagName( 'ul' )->length ) { return null; }
			if ( false !== stripos( self::cls( $first ), 'grid' ) ) { return null; }
			$txt = trim( preg_replace( '/\s+/', ' ', (string) $h->textContent ) );
			if ( '' === $txt ) { return null; }
			$doc2 = $first->ownerDocument;
			return array( 'el' => $first, 'h' => $h, 'text' => $txt, 'html' => $doc2 ? (string) $doc2->saveHTML( $first ) : '' );
		};
		// Read each panel's lead heading; bail unless they all share the same heading text.
		$leads = array(); $ref = null;
		foreach ( $items as $it ) {
			$L = $lead_of( (string) ( $it['content'] ?? '' ) );
			if ( null === $L ) { return null; }
			if ( null === $ref ) { $ref = $L['text']; }
			elseif ( strcasecmp( $L['text'], (string) $ref ) !== 0 ) { return null; }
			$leads[] = $L;
		}
		if ( empty( $leads ) ) { return null; }
		// Strip the lead block from each panel's content (first occurrence of its serialized HTML).
		foreach ( $items as $k => &$it ) {
			$frag = (string) ( $leads[ $k ]['html'] ?? '' );
			$c    = (string) ( $it['content'] ?? '' );
			if ( '' !== $frag && false !== strpos( $c, $frag ) ) {
				$it['content'] = trim( self::str_replace_first( $frag, '', $c ) );
			}
		}
		unset( $it );
		// Return the WHOLE intro block (heading + its decorative rule) verbatim, so the hoisted section heading
		// keeps its exact look (the centred "OUR MENU" + red underline) above the tabs.
		return array( 'html' => trim( (string) ( $leads[0]['html'] ?? '' ) ), 'text' => (string) $ref );
	}

	/** Replace only the FIRST occurrence of $needle in $haystack. */
	private static function str_replace_first( $needle, $replace, $haystack ) {
		$pos = strpos( $haystack, $needle );
		return ( false === $pos ) ? $haystack : substr_replace( $haystack, $replace, $pos, strlen( $needle ) );
	}

	/**
	 * SOURCE tabs layout → `{ orientation, tab_style }`. orientation = vertical when the tablist is a side
	 * COLUMN (its own flex-col / `aria-orientation="vertical"`); tab_style from the nav-item treatment —
	 * `rounded-full` = pills, a 2–3 option rounded pill-container = segmented, bordered rounded tabs = boxed —
	 * else the editorial `underline` default. Conservative: unclear styling stays underline.
	 */
	private static function detect_tabs_design( $el ) {
		$out = array( 'orientation' => 'horizontal', 'tab_style' => 'underline' );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$doc = $el->ownerDocument;
		$hay = strtolower( (string) ( $doc ? $doc->saveHTML( $el ) : '' ) );
		// ORIENTATION — a vertical tablist renders as a side column beside the panels.
		$tablist = null;
		foreach ( $el->getElementsByTagName( '*' ) as $n ) {
			$role = strtolower( (string) $n->getAttribute( 'role' ) );
			$nc   = ' ' . strtolower( self::cls( $n ) ) . ' ';
			if ( $role === 'tablist' || strpos( $nc, ' nav-tabs ' ) !== false || strpos( $nc, 'tab-list' ) !== false || strpos( $nc, 'tablist' ) !== false ) { $tablist = $n; break; }
		}
		if ( strpos( $hay, 'aria-orientation="vertical"' ) !== false ) { $out['orientation'] = 'vertical'; }
		elseif ( $tablist instanceof DOMElement ) {
			$tc = ' ' . strtolower( self::cls( $tablist ) ) . ' ';
			if ( strpos( $tc, 'flex-col' ) !== false || preg_match( '/flex-direction:\s*column/', (string) $tablist->getAttribute( 'data-sc-cs' ) ) ) { $out['orientation'] = 'vertical'; }
		}
		// STYLE — read the TAB NAV treatment ONLY (the tablist + its buttons), never the panels: scanning the
		// whole subtree false-matched `boxed` off the PANEL content (the menu cards' `border rounded-lg`), so a
		// segmented toggle rendered as folder tabs. The capture service also NORMALIZES a source's own tab
		// component to generic `sc-tabs` markup with unstyled buttons — so when the nav carries no styling signal,
		// fall back on structure: a compact 2–4-button switcher (Main Menu / Dessert Menu, Monthly / Yearly) is a
		// SEGMENTED control; more items read as the editorial underline default.
		$nav      = ( $tablist instanceof DOMElement ) ? $tablist : $el;
		$nav_hay  = strtolower( (string) ( $doc ? $doc->saveHTML( $nav ) : '' ) );
		$nav_hay  = preg_replace( '/<(?:div|section)\b[^>]*\brole="tabpanel".*$/is', '', $nav_hay ); // drop any panel that shares the scope
		$btn_count = 0;
		foreach ( $nav->getElementsByTagName( '*' ) as $c ) {
			$ct = strtolower( $c->tagName );
			if ( in_array( $ct, array( 'a', 'button' ), true ) || strtolower( (string) $c->getAttribute( 'role' ) ) === 'tab' ) { $btn_count++; }
		}
		// PREFER the captured COMPUTED styling (the enhanced capture service stamps the source tab-nav look as
		// data-sc-cs on the normalized sc-tabs). This is faithful to the source, not a structural guess: a filled
		// + rounded TRACK (the tablist has its own opaque bg + radius) = SEGMENTED; a very-round active tab =
		// PILLS; a per-tab full border + radius = BOXED; a bottom-border-only active tab = UNDERLINE.
		$decl = function ( $cs, $prop ) {
			return preg_match( '/(?:^|;)\s*' . preg_quote( $prop, '/' ) . '\s*:\s*([^;]+)/i', (string) $cs, $m ) ? trim( $m[1] ) : '';
		};
		$opaque = function ( $c ) {
			$c = trim( (string) $c );
			if ( '' === $c || stripos( $c, 'transparent' ) !== false || preg_match( '/rgba?\([^)]*[,\/]\s*0(?:\.0+)?\s*\)/i', $c ) ) { return false; }
			return (bool) preg_match( '/rgba?\(|#[0-9a-f]/i', $c );
		};
		$rpx = function ( $c ) { return preg_match( '/^([0-9.]+)px/', trim( (string) $c ), $m ) ? (float) $m[1] : 0.0; };
		$list_cs   = ( $tablist instanceof DOMElement ) ? (string) $tablist->getAttribute( 'data-sc-cs' ) : '';
		$active_cs = '';
		foreach ( $nav->getElementsByTagName( 'button' ) as $btn ) {
			if ( strtolower( (string) $btn->getAttribute( 'aria-selected' ) ) === 'true' ) { $active_cs = (string) $btn->getAttribute( 'data-sc-cs' ); break; }
		}
		if ( '' === $active_cs ) { $b0 = $nav->getElementsByTagName( 'button' )->item( 0 ); if ( $b0 ) { $active_cs = (string) $b0->getAttribute( 'data-sc-cs' ); } }
		// ALIGNMENT + PILL SKIN — captured HERE (before the tab_style classification's early returns) so they ride
		// out on $out regardless of which style branch returns. ALIGNMENT: the nav wrapper's horizontal placement
		// (source `<div class="flex justify-center">` around the pill) → the native Tab Alignment option.
		$align = 'start';
		if ( preg_match( '/\bjustify-center\b/', $hay ) || false !== strpos( $hay, 'justify-content:center' ) ) { $align = 'center'; }
		elseif ( preg_match( '/\bjustify-end\b/', $hay ) ) { $align = 'end'; }
		if ( 'start' === $align && $tablist instanceof DOMElement && $tablist->parentNode instanceof DOMElement ) {
			$tp = ' ' . strtolower( self::cls( $tablist->parentNode ) ) . ' ';
			if ( false !== strpos( $tp, ' mx-auto ' ) || false !== strpos( $tp, ' justify-center ' ) ) { $align = 'center'; }
		}
		if ( 'start' !== $align ) { $out['alignment'] = $align; }
		// PILL SKIN — a FILLED segmented control (an opaque track fill, an opaque active pill, or a large active
		// radius = a brand pill toggle, not the editorial underline) → capture its exact look so the mapper repaints
		// the tabs to match: the TRACK's fill / border / radius, the ACTIVE pill's fill + text + radius, and the
		// button typography (uppercase, tracking). Raw computed values; the mapper hex-normalises + assembles.
		if ( $opaque( $decl( $list_cs, 'background-color' ) ) || $opaque( $decl( $active_cs, 'background-color' ) ) || $rpx( $decl( $active_cs, 'border-radius' ) ) >= 8 ) {
			$pill = array();
			$set  = function ( &$arr, $k, $v ) { $v = trim( (string) $v ); if ( '' !== $v && 'none' !== strtolower( $v ) && '0px' !== $v ) { $arr[ $k ] = $v; } };
			$set( $pill, 'track_bg',       $decl( $list_cs, 'background-color' ) );
			$set( $pill, 'track_bw',       $decl( $list_cs, 'border-top-width' ) );
			$set( $pill, 'track_bc',       $decl( $list_cs, 'border-top-color' ) );
			$set( $pill, 'track_radius',   $decl( $list_cs, 'border-radius' ) );
			$set( $pill, 'active_bg',      $decl( $active_cs, 'background-color' ) );
			$set( $pill, 'active_color',   $decl( $active_cs, 'color' ) );
			$set( $pill, 'active_radius',  $decl( $active_cs, 'border-radius' ) );
			$set( $pill, 'text_transform', $decl( $active_cs, 'text-transform' ) );
			$set( $pill, 'letter_spacing', $decl( $active_cs, 'letter-spacing' ) );
			if ( $pill ) { $out['pill'] = $pill; }
		}
		// CONTENT FRAME — the source panel's box. Most Tailwind / React tab panels are FRAMELESS (the content
		// brings its own cards / layout); the tabs shortcode otherwise draws a bordered, rounded, padded white box
		// the source never had. Read the first tabpanel's computed style: a real border or an opaque fill = framed;
		// neither = frameless. Only set it when a panel is actually found (else the shortcode's framed default stands).
		$panel = null;
		foreach ( $el->getElementsByTagName( '*' ) as $n ) {
			$prole = strtolower( (string) $n->getAttribute( 'role' ) );
			$pcls  = ' ' . strtolower( self::cls( $n ) ) . ' ';
			if ( $prole === 'tabpanel' || strpos( $pcls, ' tab-pane ' ) !== false || strpos( $pcls, 'sc-tp' ) !== false ) { $panel = $n; break; }
		}
		if ( $panel instanceof DOMElement ) {
			$pcs = (string) $panel->getAttribute( 'data-sc-cs' );
			$pbw = $decl( $pcs, 'border-top-width' );
			$has_frame = ( '' !== $pbw && '0px' !== $pbw ) || $opaque( $decl( $pcs, 'background-color' ) );
			$out['content_frame'] = $has_frame ? 'framed' : 'frameless';
		}
		if ( '' !== $list_cs || '' !== $active_cs ) {
			$list_r = $rpx( $decl( $list_cs, 'border-radius' ) );
			$act_r  = $rpx( $decl( $active_cs, 'border-radius' ) );
			$act_bw = $decl( $active_cs, 'border-top-width' );
			$act_bb = $decl( $active_cs, 'border-bottom-width' );
			if ( $opaque( $decl( $list_cs, 'background-color' ) ) && $list_r >= 4 ) { $out['tab_style'] = 'segmented'; return $out; }
			if ( $act_r >= 20 ) { $out['tab_style'] = 'pills'; return $out; }
			if ( '' !== $act_bw && '0px' !== $act_bw && $act_r >= 2 ) { $out['tab_style'] = 'boxed'; return $out; }
			if ( '' !== $act_bb && '0px' !== $act_bb ) { $out['tab_style'] = 'underline'; return $out; }
		}
		if ( preg_match( '/\brounded-full\b/', $nav_hay ) && preg_match( '/\bbg-(?:gray|slate|zinc|neutral|muted|secondary|primary)-?\d?\d?\b/', $nav_hay ) && $btn_count <= 4 ) {
			$out['tab_style'] = 'segmented';
		} elseif ( preg_match( '/\brounded-full\b/', $nav_hay ) ) {
			$out['tab_style'] = 'pills';
		} elseif ( preg_match( '/\bborder\b(?!-b)/', $nav_hay ) && preg_match( '/\brounded(?:-[a-z]+)?\b/', $nav_hay ) ) {
			$out['tab_style'] = 'boxed';
		} elseif ( $btn_count >= 2 && $btn_count <= 4 ) {
			// No styling captured (normalized `sc-tabs`) — a compact toggle → segmented.
			$out['tab_style'] = 'segmented';
		}
		return $out;
	}

	/**
	 * Does this strip carry a REAL auto-scroll LOOP (as opposed to a plain `overflow-x` swipe strip)? Only an
	 * animated loop should become the Animation Engine Marquee effect — adding motion to a manual-scroll
	 * carousel would misrepresent the source. Signal: an `animate-scroll/marquee` class (on the element or its
	 * lone child — the track often sits one level in), or a computed `animation:… infinite`.
	 */
	private static function marquee_is_animated( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$sig = function ( $node ) {
			if ( ! ( $node instanceof DOMElement ) ) { return false; }
			$c = ' ' . strtolower( self::cls( $node ) ) . ' ';
			// (whole class only: `\b` after `animate-scroll` matched `animate-scroll-fade-up` — a scroll-REVEAL utility — and turned a
			// section's centred heading block into a full-bleed marquee on three sites in the feed)
			if ( preg_match( '/(?:^|\s)(animate-scroll(?:-left|-right|-x)?|animate-marquee|marquee|ticker)(?=\s|$)/', $c ) ) { return true; }
			$cs = (string) $node->getAttribute( 'data-sc-cs' ) . ';' . (string) $node->getAttribute( 'data-sc-anim' ); // a running animation is stamped as data-sc-anim
			return (bool) preg_match( '/animation[^;"\']*\binfinite\b/i', $cs );
		};
		if ( $sig( $el ) ) { return true; }
		// The animated TRACK is often the single child of the detected wrapper.
		foreach ( $el->childNodes as $k ) { if ( $k instanceof DOMElement && $sig( $k ) ) { return true; } }
		return false;
	}

	/** The animated marquee TRACK element (the one carrying the scroll animation) — `$el` or its lone child. */
	private static function marquee_track_el( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return $el; }
		$sig = function ( $node ) {
			if ( ! ( $node instanceof DOMElement ) ) { return false; }
			$c = ' ' . strtolower( self::cls( $node ) ) . ' ';
			return (bool) preg_match( '/(?:^|\s)(animate-scroll(?:-left|-right|-x)?|animate-marquee|marquee|ticker)(?=\s|$)/', $c )
				|| (bool) preg_match( '/animation[^;"\']*\binfinite\b/i', (string) $node->getAttribute( 'data-sc-cs' ) . ';' . (string) $node->getAttribute( 'data-sc-anim' ) );
		};
		if ( $sig( $el ) ) { return $el; }
		foreach ( $el->childNodes as $k ) { if ( $k instanceof DOMElement && $sig( $k ) ) { return $k; } }
		return $el;
	}

	/**
	 * Build a `{ t:'marquee', direction, gap, speed, pause, html }` block from a marquee track. Reads the
	 * source direction, the flex gap, the loop duration (→ a speed preset) and pause-on-hover, and returns the
	 * items as ONE deduplicated set (seamless marquees duplicate their items 2×; the Animation Engine's marquee
	 * runtime re-duplicates for the loop, so a 2× source would otherwise scroll a 4× track). The mapper wraps
	 * the set in a native container carrying the Marquee effect.
	 */
	private static function marquee_block( $el ) {
		// Operate on the animated TRACK (the element carrying the scroll animation + the item children) — it's
		// `$el` or its lone child.
		$el  = self::marquee_track_el( $el );
		$cls = self::cls( $el );
		$dir = preg_match( '/animate-scroll-right/', $cls ) ? 'right' : 'left';
		// gap: a Tailwind `gap-N` (N × 4px), else the computed column-gap, else the module default.
		$gap = 0.0;
		if ( preg_match( '/\bgap-(\d+(?:\.\d+)?)\b/', $cls, $gm ) ) { $gap = (float) $gm[1] * 4; }
		if ( 0.0 === $gap ) { $cg = self::sc_css( $el, 'column-gap' ); if ( '' === $cg ) { $cg = self::sc_css( $el, 'gap' ); } if ( preg_match( '/^([0-9.]+)px/', (string) $cg, $cm ) ) { $gap = (float) $cm[1]; } }
		if ( 0.0 === $gap ) { $gap = 40.0; }
		// loop duration → speed preset (a longer loop reads slower). From the computed animation shorthand.
		$cs  = (string) $el->getAttribute( 'data-sc-cs' ) . ';' . (string) $el->getAttribute( 'data-sc-anim' );
		$dur = 0.0;
		if ( preg_match( '/animation[^;"\']*?([0-9.]+)s/i', $cs, $dm ) ) { $dur = (float) $dm[1]; }
		$speed = $dur > 0 ? ( $dur >= 40 ? 'slow' : ( $dur >= 20 ? 'normal' : 'fast' ) ) : 'normal';
		// pause on hover — default yes (the natural ticker feel; the source uses `hover:[…paused]`). Only a
		// source that explicitly keeps running on hover would turn it off, which is rare.
		$pause = 'yes';
		// items — ONE deduplicated set.
		$doc  = $el->ownerDocument;
		$kids = array();
		foreach ( $el->childNodes as $c ) { if ( XML_ELEMENT_NODE === $c->nodeType ) { $kids[] = $c; } }
		$n = count( $kids );
		if ( $n >= 2 && 0 === $n % 2 ) {
			$sig = function ( $k ) {
				$v = $k->getElementsByTagName( 'video' )->item( 0 );
				if ( $v ) {
					$s = $v->getElementsByTagName( 'source' )->item( 0 );
					$src = $s ? $s->getAttribute( 'src' ) : $v->getAttribute( 'src' );
					if ( '' !== trim( (string) $src ) ) { return basename( (string) $src ); }
				}
				$img = $k->getElementsByTagName( 'img' )->item( 0 );
				if ( $img && '' !== trim( (string) $img->getAttribute( 'src' ) ) ) { return basename( (string) $img->getAttribute( 'src' ) ); }
				return trim( preg_replace( '/\s+/', ' ', (string) $k->textContent ) );
			};
			$half = intdiv( $n, 2 ); $match = true;
			for ( $i = 0; $i < $half; $i++ ) { if ( $sig( $kids[ $i ] ) !== $sig( $kids[ $i + $half ] ) ) { $match = false; break; } }
			if ( $match ) { $kids = array_slice( $kids, 0, $half ); }
		}
		// Card HTMLs kept RAW (data-sc-cs intact) for the faithful DECOMPOSER; a strip_cs'd row html is the
		// verbatim fallback the mapper uses if decomposition can't build native cards.
		$cards = array();
		foreach ( $kids as $k ) { $cards[] = $doc ? (string) $doc->saveHTML( $k ) : ''; }
		$inner = self::strip_cs( trim( implode( '', $cards ) ) );
		$html  = '<div style="display:flex;gap:' . rtrim( rtrim( number_format( $gap, 2, '.', '' ), '0' ), '.' ) . 'px;width:max-content;">' . $inner . '</div>';
		return array( 't' => 'marquee', 'role' => 'marquee', 'direction' => $dir, 'gap' => $gap, 'speed' => $speed, 'duration' => $dur, 'pause' => $pause, 'html' => $html, 'cards' => $cards );
	}

	/**
	 * SOURCE timeline layout → `{ design }` (alternating | left | right | horizontal). Horizontal when the
	 * milestones run in a ROW (flex-row / horizontal scroll); else the vertical alternating default (the two
	 * one-sided variants aren't reliably distinguishable from alternating without rendering, so we keep the
	 * shortcode default). Conservative.
	 */
	private static function detect_timeline_design( $el ) {
		$out = array( 'design' => 'alternating' );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$doc = $el->ownerDocument;
		$hay = strtolower( (string) ( $doc ? $doc->saveHTML( $el ) : '' ) );
		if ( ( strpos( $cls, ' flex-row ' ) !== false && strpos( $cls, 'flex-col' ) === false )
			|| preg_match( '/flex-direction:\s*row/', $cs )
			|| preg_match( '/overflow-x-(?:auto|scroll)|\bsnap-x\b/', $hay ) ) {
			$out['design'] = 'horizontal';
		}
		// CARD COLOURS — a dark-themed source (AI-page `.project-card` = a DARK oklch(0.15) fill + near-white
		// title) renders a DARK card. The timeline shortcode defaults to a LIGHT card, so on the converted
		// dark-theme site the near-white heading colour lands on a white card → the title is invisible
		// (white-on-white; the-line's "Selected Works" cards). When the source entry card carries its OWN dark
		// solid fill, carry that fill + the entry's title/text colours so the converted card matches the source
		// and stays legible. Gated on a DARK card fill, so a normal light-card timeline is untouched (no default
		// change). Colours are emitted by n_timeline into the timeline Styling group (card_bg/title_color/text_color).
		$first = null;
		foreach ( self::widget_children( $el ) as $k ) { if ( $k instanceof DOMElement ) { $first = $k; break; } }
		if ( $first instanceof DOMElement ) {
			$card = $first;
			$cbg  = self::sc_css( $card, 'background-color' );
			// The fill may sit on a boxed child, not the entry wrapper — descend one boxed level if the entry is bare.
			if ( ( '' === $cbg || false !== stripos( $cbg, 'transparent' ) ) ) {
				foreach ( $card->childNodes as $ch ) {
					if ( $ch instanceof DOMElement && self::wrapper_has_own_box( $ch ) ) {
						$c2 = self::sc_css( $ch, 'background-color' );
						if ( '' !== $c2 && false === stripos( $c2, 'transparent' ) ) { $card = $ch; $cbg = $c2; break; }
					}
				}
			}
			$cbg_hex = ( '' !== $cbg && false === stripos( $cbg, 'transparent' ) && ! preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $cbg ) ) ? self::color_to_hex( $cbg ) : '';
			if ( '' !== $cbg_hex && self::color_is_dark( $cbg_hex ) ) {
				$out['card_bg'] = $cbg_hex;
				// Title colour — the entry's first heading; Text colour — its first paragraph. Fall back to the
				// card's own computed `color`. Only carry LIGHT ones (readable on the dark card we just set).
				$own_col = self::color_to_hex( (string) self::sc_css( $card, 'color' ) );
				$title_el = null; foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $hh ) { $n = $card->getElementsByTagName( $hh ); if ( $n->length ) { $title_el = $n->item( 0 ); break; } }
				$p_el = $card->getElementsByTagName( 'p' );
				$title_col = ( $title_el instanceof DOMElement ) ? self::color_to_hex( (string) self::sc_css( $title_el, 'color' ) ) : $own_col;
				$text_col  = ( $p_el->length ) ? self::color_to_hex( (string) self::sc_css( $p_el->item( 0 ), 'color' ) ) : $own_col;
				if ( '' !== $title_col && ! self::color_is_dark( $title_col ) ) { $out['title_color'] = $title_col; }
				if ( '' !== $text_col  && ! self::color_is_dark( $text_col ) )  { $out['text_color']  = $text_col; }
			}
		}
		return $out;
	}

	/**
	 * SOURCE steps layout → `{ design }` (horizontal | vertical | alternating | cards | circles). Horizontal
	 * when the steps sit in a ROW, vertical when STACKED; `cards` when each step is a bordered/elevated box.
	 * Defaults to the shortcode's `horizontal`.
	 */
	private static function detect_steps_design( $el, array $items = array() ) {
		$out = array( 'design' => 'horizontal' );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$vertical = ( strpos( $cls, ' flex-col ' ) !== false && strpos( $cls, 'md:flex-row' ) === false ) || preg_match( '/flex-direction:\s*column/', $cs ) || strpos( $cls, ' grid-cols-1 ' ) !== false;
		if ( $vertical ) { $out['design'] = 'vertical'; }
		// A boxed/elevated card per step → the `cards` design. Detect from Tailwind classes AND the child's
		// MEASURED computed style (data-sc-cs: real border / shadow / radius / fill) — a boxed step whose look
		// came from a stylesheet (no utility class) was being missed, so a clearly boxed source rendered flat.
		// The step CARD may be the child itself OR a NESTED wrapper (source pattern: `<div class="relative">` →
		// connector + `<div class="… bg … border rounded">card</div>`). Resolve the actual boxed element so a
		// clearly-boxed source isn't read as flat just because the outer flow wrapper is unstyled.
		$boxed = 0; $n = 0; $first_card = null;
		foreach ( self::el_children( $el ) as $k ) {
			if ( ! ( $k instanceof DOMElement ) ) { continue; }
			$n++;
			$card = self::step_card_of( $k );
			if ( null === $first_card ) { $first_card = $card; }
			if ( self::is_boxed_el( $card ) ) { $boxed++; }
		}
		if ( ! $vertical && $n >= 2 && $boxed >= $n - 1 ) { $out['design'] = 'cards'; }

		// STEP-CARD BOX SKIN — so the Cards design can carry a matching Box Preset (box_style). Read the first
		// step card's measured fill / radius / border in the cardBox shape box_preset_slug() expects.
		if ( 'cards' === $out['design'] && $first_card ) {
			$cbg = self::sc_css( $first_card, 'background-color' );
			$crad = self::sc_css( $first_card, 'border-radius' );
			$cbw = self::sc_css( $first_card, 'border-top-width' );
			$cbd = self::sc_css( $first_card, 'border-top-color' );
			$skin = array();
			if ( '' !== $cbg && 'rgba(0, 0, 0, 0)' !== $cbg && 'transparent' !== $cbg ) { $skin['bg'] = $cbg; }
			if ( '' !== $crad && '0px' !== $crad ) { $skin['radius'] = $crad; }
			if ( '' !== $cbw && '0px' !== $cbw ) { $skin['bw'] = $cbw; $skin['bd'] = $cbd; }
			// + the card's own inset and shadow (a `p-8` card had rendered at the preset's 1.6rem / 1.4rem default)
			$cpad = self::sc_css( $first_card, 'padding' ); if ( preg_match( '/^[0-9.]+px(?:\s+[0-9.]+px){0,3}$/', $cpad ) && '0px' !== $cpad ) { $skin['padding'] = $cpad; }
			$csh = self::sc_css( $first_card, 'box-shadow' ); if ( '' !== $csh && 'none' !== $csh ) { $skin['shadow'] = $csh; }
			if ( $skin ) { $out['box'] = $skin; }
		}

		// MARKER — shape (from the ICON BADGE's radius, else the number chip) + accent fill, so markers match.
		$marker = self::step_marker_el( $el );
		if ( $marker ) {
			$mrad_raw = self::sc_css( $marker, 'border-radius' );
			$mrad     = (float) $mrad_raw;
			if ( $mrad >= 999 || false !== strpos( $mrad_raw, '50%' ) ) { $out['marker_shape'] = 'circle'; }
			elseif ( $mrad >= 4 ) { $out['marker_shape'] = 'rounded'; }
			elseif ( '0px' === $mrad_raw ) { $out['marker_shape'] = 'square'; }
			$mbg = self::sc_css( $marker, 'background-color' );
			if ( '' !== $mbg && 'rgba(0, 0, 0, 0)' !== $mbg && 'transparent' !== $mbg && preg_match( '/rgba?\(\s*(\d+)\D+(\d+)\D+(\d+)(?:\D+([\d.]+))?/', $mbg, $m ) ) {
				// Preserve a translucent tint (source badges are often `bg-primary/10`) — keep the rgba so the
				// converted marker reads light, not a flat solid; a fully-opaque fill collapses to clean hex.
				$out['accent'] = ( isset( $m[4] ) && (float) $m[4] < 1 )
					? 'rgba(' . (int) $m[1] . ', ' . (int) $m[2] . ', ' . (int) $m[3] . ', ' . $m[4] . ')'
					: sprintf( '#%02x%02x%02x', (int) $m[1], (int) $m[2], (int) $m[3] );
			}
		}

		// …the badge's SIZE (`w-14 h-14` = 56px, not the shortcode's default) and its GLYPH's ink (a green icon on a
		// 10% tint — the default white marker text vanished on the tint; a real-site audit)
		if ( $marker ) {
			$mw = self::sc_css( $marker, 'width' ); if ( '' === $mw ) { $mw = self::sc_css( $marker, 'height' ); } // the stamp drops an unremarkable width — the height is the same square
			if ( preg_match( '/^([0-9.]+)px$/', $mw, $mwm ) && (float) $mwm[1] >= 20 && (float) $mwm[1] <= 120 ) { $out['markerSize'] = (int) round( (float) $mwm[1] ); }
			$glyph = null; foreach ( array( 'svg', 'i', 'span', 'img' ) as $gt ) { $g = $marker->getElementsByTagName( $gt )->item( 0 ); if ( $g instanceof DOMElement ) { $glyph = $g; break; } }
			$mtc = $glyph instanceof DOMElement ? self::sc_css( $glyph, 'color' ) : '';
			// an inline <svg> carries no stamp of its own — its first stamped child (a <path> / <circle>) has the glyph's ink
			if ( '' === $mtc && $glyph instanceof DOMElement ) { foreach ( $glyph->getElementsByTagName( '*' ) as $gc ) { $mtc = self::sc_css( $gc, 'color' ); if ( '' !== $mtc ) { break; } } }
			if ( '' === $mtc ) { $mtc = self::sc_css( $marker, 'color' ); }
			if ( '' !== $mtc && preg_match( '/^(?:rgba?\([^)]*\)|#[0-9a-f]{3,8})$/i', $mtc ) ) { $out['markerText'] = $mtc; }
		}

		// MARKER MODE — if the steps carry ICON glyphs (not just numbers), the marker should render the icon.
		$with_icon = 0;
		foreach ( $items as $it ) { if ( ! empty( $it['icon'] ) ) { $with_icon++; } }
		if ( $with_icon >= max( 1, (int) floor( count( $items ) / 2 ) ) ) { $out['marker'] = 'icon'; }

		// CONNECTOR — a thin line element between steps (a `h-px`/`h-0.5` bar, or a gradient/`bg-` divider)
		// → keep the connecting line; otherwise turn it OFF so a boxed source with no line doesn't get one.
		$has_conn = false;
		foreach ( self::el_children( $el ) as $k ) {
			if ( ! ( $k instanceof DOMElement ) ) { continue; }
			foreach ( $k->getElementsByTagName( '*' ) as $c ) {
				$cc = ' ' . strtolower( self::cls( $c ) ) . ' ';
				if ( preg_match( '/\b(?:connector|step-line|divider-line)\b/', $cc )
					|| ( preg_match( '/\bh-(?:px|0\.5|\[1px\]|\[2px\])\b/', $cc ) && preg_match( '/\b(?:bg-|gradient)/', $cc ) ) ) { $has_conn = true; break 2; }
			}
		}
		$out['connector'] = $has_conn ? 'solid' : 'none';

		return $out;
	}

	/** Is $elm a "box" (Tailwind border/shadow/rounded/bg utility, or a measured border/radius/shadow/fill)? */
	private static function is_boxed_el( $elm ) {
		if ( ! ( $elm instanceof DOMElement ) ) { return false; }
		$c = ' ' . strtolower( self::cls( $elm ) ) . ' ';
		if ( preg_match( '/\b(?:border|shadow|rounded|bg-white|bg-card)\b/', $c ) ) { return true; }
		$bg = self::sc_css( $elm, 'background-color' );
		$has_bg = '' !== $bg && 'rgba(0, 0, 0, 0)' !== $bg && 'transparent' !== $bg;
		$sh = self::sc_css( $elm, 'box-shadow' );
		return (float) self::sc_css( $elm, 'border-top-width' ) >= 1 || (float) self::sc_css( $elm, 'border-radius' ) >= 4 || ( '' !== $sh && 'none' !== $sh ) || $has_bg;
	}

	/** The step CARD: the child itself when boxed, else its most prominent boxed `<div>` descendant (the
	 *  common `<div class="relative">wrapper` → `<div class="… bg border rounded">card</div>` pattern). */
	private static function step_card_of( $child ) {
		if ( ! ( $child instanceof DOMElement ) ) { return $child; }
		if ( self::is_boxed_el( $child ) ) { return $child; }
		foreach ( $child->getElementsByTagName( 'div' ) as $d ) { if ( self::is_boxed_el( $d ) ) { return $d; } }
		return $child;
	}

	/** The step MARKER element (for reading shape + fill): prefer the ICON BADGE — the element wrapping the
	 *  step's icon that carries a fill/radius (e.g. `w-14 h-14 rounded-2xl bg-primary/10`) — else the number
	 *  chip (a descendant whose entire text is a 1-2 digit number, or a marker-ish class). */
	private static function step_marker_el( $el ) {
		$kids = self::el_children( $el );
		if ( ! $kids ) { return null; }
		$first = null;
		foreach ( $kids as $k ) { if ( $k instanceof DOMElement ) { $first = $k; break; } }
		if ( ! $first ) { return null; }
		// Icon badge: the nearest ancestor of the step's icon (within the step) that has a fill or radius.
		$icon = null;
		foreach ( $first->getElementsByTagName( '*' ) as $c ) {
			$ct = strtolower( $c->tagName );
			if ( 'svg' === $ct || 'img' === $ct || 'i' === $ct || $c->hasAttribute( 'data-lucide' ) ) { $icon = $c; break; }
		}
		if ( $icon ) {
			for ( $p = $icon->parentNode; $p instanceof DOMElement && $p !== $first->parentNode && $p !== $first; $p = $p->parentNode ) {
				$pbg = self::sc_css( $p, 'background-color' );
				$has_bg = '' !== $pbg && 'rgba(0, 0, 0, 0)' !== $pbg && 'transparent' !== $pbg;
				if ( $has_bg || (float) self::sc_css( $p, 'border-radius' ) > 0 ) { return $p; }
			}
		}
		// Number / marker chip fallback.
		foreach ( $first->getElementsByTagName( '*' ) as $c ) {
			if ( preg_match( '/^0*\d{1,2}$/', trim( self::text( $c ) ) ) ) { return $c; }
			$cc = strtolower( (string) $c->getAttribute( 'class' ) );
			if ( preg_match( '/step-?(number|index|num|count)|\b(marker|badge|circle|count|number)\b/', $cc ) ) { return $c; }
		}
		return null;
	}

	/**
	 * SOURCE progress display → `{ type }` (bar | circle | gauge). Circle when the source uses an SVG ring
	 * (`<circle>` + stroke-dash) or a conic-gradient / rounded-full radial; else the horizontal `bar` default.
	 */
	private static function detect_progress_design( $el ) {
		$out = array( 'type' => 'bar' );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$doc = $el->ownerDocument;
		$hay = strtolower( (string) ( $doc ? $doc->saveHTML( $el ) : '' ) );
		$has_ring = false;
		foreach ( $el->getElementsByTagName( 'circle' ) as $c ) {
			if ( $c->hasAttribute( 'stroke-dasharray' ) || $c->hasAttribute( 'stroke-dashoffset' ) || stripos( (string) $c->getAttribute( 'class' ), 'progress' ) !== false ) { $has_ring = true; break; }
		}
		if ( $has_ring || strpos( $hay, 'conic-gradient' ) !== false || preg_match( '/\bradial-progress\b|\bprogress-(?:circle|ring)\b/', $hay ) ) {
			$out['type'] = 'circle';
		}
		return $out;
	}

	/* --------------------------------------------------------------------- *
	 * Lottie / SVG-draw recognizers
	 * --------------------------------------------------------------------- */

	/** A Lottie src (`.json`/`.lottie`) carried on an element's known src attributes, or ''. */
	private static function lottie_src_of( $el ) {
		foreach ( array( 'src', 'data-src', 'data-animation-path', 'data-lottie', 'data-json', 'href' ) as $a ) {
			$v = trim( (string) $el->getAttribute( $a ) );
			if ( $v !== '' && preg_match( '/\.(json|lottie)(\?|#|$)/i', $v ) ) { return $v; }
		}
		return '';
	}

	/** A Lottie/Bodymovin embed: <lottie-player>/<dotlottie-player>, or a container carrying a `.json`/`.lottie` src. */
	private static function is_lottie_embed( $el, $tag = '' ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = $tag !== '' ? strtolower( $tag ) : strtolower( $el->tagName );
		if ( 'lottie-player' === $tag || 'dotlottie-player' === $tag ) { return true; }
		if ( $el->getElementsByTagName( 'lottie-player' )->length || $el->getElementsByTagName( 'dotlottie-player' )->length ) { return true; }
		if ( self::lottie_src_of( $el ) !== '' ) {
			$cls = self::cls( $el );
			if ( preg_match( '/\b(lottie|bodymovin|dotlottie)\b/', $cls ) || $el->hasAttribute( 'data-animation-path' ) || $el->hasAttribute( 'data-lottie' ) ) { return true; }
		}
		return false;
	}

	/** Build a `{ t:'lottie', src }` block (src from the player element or the container). */
	private static function lottie_block( $el ) {
		$src = self::lottie_src_of( $el );
		if ( '' === $src ) {
			foreach ( array( 'lottie-player', 'dotlottie-player' ) as $pt ) {
				$p = $el->getElementsByTagName( $pt )->item( 0 );
				if ( $p ) { $src = self::lottie_src_of( $p ); if ( $src !== '' ) { break; } }
			}
		}
		if ( '' === $src ) { return null; }
		return array( 't' => 'lottie', 'src' => $src );
	}

	/** An inline <svg> whose strokes are draw-animated (dasharray/dashoffset) or explicitly flagged for drawing. */
	private static function is_svg_draw( $el, $tag = '' ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = $tag !== '' ? strtolower( $tag ) : strtolower( $el->tagName );
		if ( 'svg' !== $tag ) { return false; }
		$cls = strtolower( (string) $el->getAttribute( 'class' ) );
		if ( preg_match( '/\b(svg-?draw|line-?draw|draw-?svg|animate-?draw|self-?draw)\b/', $cls ) ) { return true; }
		if ( $el->hasAttribute( 'data-draw' ) || $el->hasAttribute( 'data-svg-draw' ) ) { return true; }
		// A path/line/polyline carrying stroke-dasharray or stroke-dashoffset (the draw-on technique).
		foreach ( array( 'path', 'line', 'polyline', 'circle', 'rect' ) as $st ) {
			foreach ( $el->getElementsByTagName( $st ) as $p ) {
				if ( $p->hasAttribute( 'stroke-dasharray' ) || $p->hasAttribute( 'stroke-dashoffset' ) ) { return true; }
				$style = strtolower( (string) $p->getAttribute( 'style' ) );
				if ( strpos( $style, 'stroke-dasharray' ) !== false || strpos( $style, 'stroke-dashoffset' ) !== false ) { return true; }
			}
		}
		return false;
	}

	/** Build a `{ t:'svg_draw', code }` block carrying the outer SVG markup (scripts/handlers stripped). */
	private static function svg_draw_block( $el ) {
		$doc = $el->ownerDocument;
		if ( ! $doc ) { return null; }
		$markup = (string) $doc->saveHTML( $el );
		$markup = preg_replace( '#<script\b[^>]*>.*?</script>#is', '', $markup );
		$markup = preg_replace( '/\son[a-z]+\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/i', '', $markup );
		$markup = self::strip_cs( trim( $markup ) );
		return '' !== $markup ? array( 't' => 'svg_draw', 'code' => $markup ) : null;
	}

	/**
	 * A grid child that carries real, sizeable content (a heading, paragraph, image/media, list, or >=20 chars
	 * of text) — as opposed to a bare button, link, spacer, or empty decorative div. Used to tell a genuine
	 * multi-column layout band from a button/pill row (whose children are NOT substantial).
	 */
	/** A flex ROW (computed) of 2–5 children that are each a SHORT label (≤ 40 chars, no heading / media / prose) or a
	 *  cluster of EMPTY painted dots, spread by justify-content (space-between / space-around) or with a gap — a title
	 *  bar / meta strip, never a content band (is_layout_row owns those). */
	private static function is_toolbar_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( self::is_badge( $el ) ) { return false; } // a status PILL (a pulsing dot + a label in a rounded, padded inline-flex) is a badge → the heading's overline, not a toolbar
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $cs ) || preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $cs ) ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 || count( $kids ) > 5 ) { return false; }
		$labels = 0; $dots = 0;
		foreach ( $kids as $k ) {
			if ( in_array( strtolower( $k->tagName ), array( 'a', 'button', 'input', 'ul', 'ol' ), true ) || self::is_painted_panel( $k ) || self::is_panel( $k ) ) { return false; }
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'img', 'svg', 'a', 'button', 'i', 'iconify-icon' ) as $t ) { if ( $k->getElementsByTagName( $t )->length > 0 ) { return false; } }
			foreach ( $k->getElementsByTagName( '*' ) as $d ) { if ( false !== strpos( $d->tagName, '-' ) ) { return false; } } // a web-component icon (a brand strip) is not a label
			$txt = trim( preg_replace( '/\s+/', ' ', self::text( $k ) ) );
			if ( '' !== $txt ) {
				if ( mb_strlen( $txt ) > 40 ) { return false; }
				if ( 0 !== $k->getElementsByTagName( '*' )->length ) {
					// a MIXED CLUSTER: a flex row of empty painted dots + ONE leaf label (a terminal title bar's three window dots
					// beside the filename) counts as a label; a cell of tag spans (a chip row) does not
					$kcs2 = (string) $k->getAttribute( 'data-sc-cs' );
					if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $kcs2 ) ) { return false; }
					$cl = 0; $cd = 0;
					foreach ( self::el_children( $k ) as $d ) {
						if ( 0 !== $d->getElementsByTagName( '*' )->length ) { return false; }
						$dt = trim( self::text( $d ) ); $dcs = (string) $d->getAttribute( 'data-sc-cs' );
						if ( '' !== $dt ) { $cl++; continue; }
						if ( preg_match( '/background-color:\s*(?!rgba\([^)]*,\s*0\s*\))(?!transparent)/i', $dcs ) && preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $dcs, $hm ) && (float) $hm[1] <= 24 ) { $cd++; continue; }
						return false;
					}
					if ( 1 !== $cl || $cd < 1 ) { return false; }
					$labels++; $dots++; continue;
				}
				$labels++; continue; // a LEAF label only — a cell of tag spans is a chip row
			}
			// an empty cluster: every element child is an empty painted box ≤ 24px (a window dot)
			$sub = self::el_children( $k );
			if ( ! $sub ) { // a LEAF dot: the kid itself is a small painted box (a `w-1 h-1 rounded-full` separator between labels)
				$kcs = (string) $k->getAttribute( 'data-sc-cs' );
				if ( preg_match( '/background-color:\s*(?!rgba\([^)]*,\s*0\s*\))(?!transparent)/i', $kcs ) && preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $kcs, $hm ) && (float) $hm[1] <= 24 ) { $dots++; continue; }
				return false;
			}
			foreach ( $sub as $d ) {
				$dcs = (string) $d->getAttribute( 'data-sc-cs' );
				if ( '' !== trim( self::text( $d ) ) || ! preg_match( '/background-color:\s*(?!rgba\([^)]*,\s*0\s*\))(?!transparent)/i', $dcs ) || ! preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $dcs, $hm ) || (float) $hm[1] > 24 ) { return false; }
			}
			$dots++;
		}
		if ( $labels < 1 ) { return false; }
		$spread = preg_match( '/(?:^|;)\s*justify-content:\s*(?:space-between|space-around|space-evenly)/i', $cs ) || preg_match( '/(?:^|;)\s*gap:\s*([1-9][0-9.]*)px/i', $cs );
		return (bool) $spread;
	}

	private static function is_substantial_cell( $k ) {
		if ( ! ( $k instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $k->tagName );
		if ( in_array( $tag, array( 'button', 'a', 'input', 'br', 'hr', 'script', 'style' ), true ) ) { return false; }
		if ( preg_match( '/^h[1-6]$/', $tag ) && '' !== trim( self::text( $k ) ) ) { return true; } // the cell IS a heading (a short `h3` beside an arrow in an accordion-style row)
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'img', 'svg', 'video', 'iframe', 'picture', 'ul', 'ol' ) as $t ) {
			if ( $k->getElementsByTagName( $t )->length > 0 ) { return true; }
		}
		if ( mb_strlen( self::text( $k ) ) >= 20 ) { return true; }
		if ( '' !== self::bg_photo_url( $k ) ) { return true; } // a CSS-painted photo half (`bg-cover` + url) is content — it was dropped (a fixture from the feed)
		return self::is_painted_panel( $k ) || self::is_panel( $k );
	}

	/**
	 * A PAINTED EMPTY PANEL — a cell with NO text and NO media that the source paints on its own (a gradient
	 * "visual" half of a band card, a colour swatch): computed background-image gradient(s) or a background
	 * colour, and a real box (height / min-height >= 80px). It is content (the design's left half), not a
	 * decorative wrapper to drop. Returns false for anything with text / img / svg / video / iframe.
	 */
	private static function is_painted_panel( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( '' !== trim( self::text( $el ) ) ) { return false; }
		foreach ( array( 'img', 'svg', 'video', 'iframe', 'picture', 'canvas', 'a', 'button', 'input' ) as $t ) { if ( $el->getElementsByTagName( $t )->length > 0 ) { return false; } }
		$p = self::panel_paint( $el );
		if ( '' === $p['bgi'] && '' === $p['bg'] ) { return false; }
		$h = self::sc_css( $el, 'height' ); if ( '' === $h ) { $h = self::sc_css( $el, 'min-height' ); }
		return preg_match( '/^([0-9.]+)px$/', $h, $m ) && (float) $m[1] >= 80;
	}

	/** A PHOTO CELL painted with CSS (`bg-cover bg-center` + `background-image:url(…)`, no <img>, no text): the photo's url, or ''.
	 *  A data: / gradient / svg-pattern background is not a photo. The cell needs a real box (height ≥ 120). */
	private static function bg_photo_url( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		if ( '' !== trim( self::text( $el ) ) ) { return ''; }
		foreach ( array( 'img', 'video', 'iframe', 'picture', 'canvas' ) as $t ) { if ( $el->getElementsByTagName( $t )->length > 0 ) { return ''; } }
		$bgi = html_entity_decode( trim( (string) self::sc_css( $el, 'background-image' ) ) );
		if ( '' === $bgi || ! preg_match( '/url\(\s*["\']?([^"\')\s]+)["\']?\s*\)/i', $bgi, $um ) ) { return ''; }
		$u = trim( $um[1] );
		if ( '' === $u || 0 === stripos( $u, 'data:' ) || preg_match( '/\.svg(?:$|\?)/i', $u ) || preg_match( '/gradient\(/i', $bgi ) ) { return ''; }
		$h = self::sc_css( $el, 'height' ); if ( '' === $h ) { $h = self::sc_css( $el, 'min-height' ); }
		if ( ! preg_match( '/^([0-9.]+)px$/', $h, $hm ) || (float) $hm[1] < 120 ) { return ''; }
		return $u;
	}

	/** The photo cell's block: a native media_image covering the cell's measured box (the source's background-position kept). */
	private static function bg_photo_block( $el, $url ) {
		$h = self::sc_css( $el, 'height' ); if ( '' === $h ) { $h = self::sc_css( $el, 'min-height' ); }
		$pos = trim( (string) self::sc_css( $el, 'background-position' ) ); if ( '' === $pos || ! preg_match( '/^[a-z0-9.%\s-]+$/i', $pos ) ) { $pos = 'center'; }
		$hpx = preg_match( '/^([0-9.]+)px$/', $h, $hm ) ? (float) $hm[1] : 0.0;
		$skin = 'selector{height:100%;min-height:' . ( $hpx > 0 ? $hpx : 240 ) . 'px;}selector .image,selector figure{height:100%;margin:0;}selector img{width:100%;height:100%;object-fit:cover;object-position:' . $pos . ';display:block;}';
		return array( 't' => 'image', 'role' => 'image', 'html' => '<img src="' . esc_url( $url ) . '" alt="">', 'skinCss' => $skin, 'bgPhoto' => true );
	}

	/** The panel's own paint: { bgi: gradient layers (no url()), bg: solid colour } — '' when none. */
	private static function panel_paint( $el ) {
		$bgi = trim( (string) self::sc_css( $el, 'background-image' ) );
		if ( '' !== $bgi && ( stripos( $bgi, 'gradient' ) === false || stripos( $bgi, 'url(' ) !== false || strlen( $bgi ) > 1500 ) ) { $bgi = ''; }
		$bg = trim( (string) self::sc_css( $el, 'background-color' ) );
		if ( '' !== $bg && ( stripos( $bg, 'transparent' ) !== false || preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $bg ) ) ) { $bg = ''; }
		return array( 'bgi' => $bgi, 'bg' => $bg );
	}

	/**
	 * Does this element read as a genuine horizontal MULTI-COLUMN band at desktop (NOT a card grid, which is
	 * claimed earlier)? True when it's a `grid-cols-N` (N>=2, incl. responsive `lg:grid-cols-N`), a computed
	 * `grid-template-columns` with >=2 real tracks, or a desktop flex-ROW — AND it has >=2 substantial cells
	 * (so a button/pill row, whose children aren't substantial, never qualifies). Mobile stacking is fine — we
	 * key off the DESKTOP layout only.
	 */
	/**
	 * A SECTION ROOT that is itself a horizontal row -> the row block, else null.
	 *
	 * `collect_blocks()` walks a node's CHILDREN and matches each against the recognizers; the node
	 * itself is never tested. When the section root IS the row (very common in Tailwind heroes, where
	 * the `<section>` carries `flex flex-col lg:flex-row` or `grid lg:grid-cols-2` directly), its two
	 * cells were therefore emitted as separate full-width blocks and stacked.
	 *
	 * Tightly gated so an ordinary centered band is never turned into columns:
	 *   - >= 2 SUBSTANTIAL children (not absolutely-positioned decor, not responsive-hidden, each
	 *     carrying real text or media) — a hero with one centered child plus a blur overlay does NOT qualify;
	 *   - the root passes is_layout_row() (an explicit desktop row / multi-track grid);
	 *   - layout_cols() yields >= 2 columns.
	 *
	 * @return array|null the `row` block, or null to fall through to the normal child walk.
	 */
	/**
	 * Translate a wrapper's utility classes into the box declaration that CONSTRAINED the image inside
	 * it, honouring BREAKPOINTS: `md:h-80` beats a base `h-64`, because the capture is a DESKTOP render.
	 * Returns '' when the classes carry no box.
	 */
	private static function box_decl_from_classes( $classes ) {
		$cls = ' ' . preg_replace( '/\s+/', ' ', (string) $classes ) . ' ';
		// Widest breakpoint first; '' = the un-prefixed base utility.
		foreach ( array( '2xl:', 'xl:', 'lg:', 'md:', 'sm:', '' ) as $bp ) {
			$b = preg_quote( $bp, '/' );
			if ( preg_match( '/\s' . $b . 'aspect-\[([0-9.]+)\s*\/\s*([0-9.]+)\]/', $cls, $m ) ) {
				return 'aspect-ratio:' . $m[1] . ' / ' . $m[2] . ';';
			}
			if ( preg_match( '/\s' . $b . 'aspect-square\s/', $cls ) ) { return 'aspect-ratio:1 / 1;'; }
			if ( preg_match( '/\s' . $b . 'aspect-video\s/', $cls ) )  { return 'aspect-ratio:16 / 9;'; }
			if ( preg_match( '/\s' . $b . 'h-\[([0-9.]+)(px|rem|vh|vw|em|%)\]/', $cls, $m ) ) { return 'height:' . $m[1] . $m[2] . ';'; }
			if ( preg_match( '/\s' . $b . 'h-(\d{1,3})\s/', $cls, $m ) ) {
				return 'height:' . ( (float) $m[1] * 0.25 ) . 'rem;'; // Tailwind spacing scale: 1 = 0.25rem
			}
		}
		return '';
	}

	/**
	 * The crop box an <img> was rendered into, recovered from its ANCESTORS -> scoped skin CSS, or ''.
	 *
	 * A a second AI-page generator image is almost never sized by its own attributes: the `<img>` carries
	 * `w-full h-full object-cover` and the frame lives on a wrapper (`aspect-[4/3] overflow-hidden`,
	 * `h-64`). The `image` recognizer serialises the <img> alone, so without this the photo renders at
	 * natural size and inflates the section several-fold.
	 *
	 * Only a CROPPING image (`object-cover`) qualifies: a contained image is already sized by its own
	 * ratio and must not be forced into a box.
	 */
	/**
	 * NOTE — deliberately NOT wired into the `image_wrapper` recognizer or the card-grid block emitter.
	 * Doing so was tried and REVERTED (08-render-audit.md 8.31): those paths feed images that often sit
	 * in a column whose width is itself wrong, and forcing the source's aspect onto a wrong-width column
	 * is worse than leaving the photo at natural size — `bakeiiiiry_artisan` rendered a 1200x1200 image
	 * where the source shows 219x219. Wire this in only once the column width is trustworthy.
	 */
	/**
	 * An <img> that declares its OWN fixed size (`w-16 h-16`, `w-[64px] h-[64px]`) -> scoped skin CSS.
	 *
	 * This is deliberately NARROWER than media_box_from_ancestors() (which is unwired -- see the note
	 * there and 08-render-audit.md 8.31). The failure mode there was inferring a box from an ANCESTOR
	 * whose own width was wrong. Here the size is stated on the image itself and is unambiguous: a
	 * `w-16 h-16` thumbnail is 64x64 whatever its column does. Without this a restored product-row
	 * thumbnail renders ~600px wide (measured on bakeiiiiry_artisan) instead of 64px.
	 *
	 * Only a SQUARE-ish explicit pair qualifies (both w- and h- present); a lone `w-full` / `h-auto`
	 * is a fluid image and must not be pinned.
	 */
	private static function img_own_box( $img ) {
		if ( ! ( $img instanceof DOMElement ) ) { return ''; }
		$cls = ' ' . preg_replace( '/\s+/', ' ', strtolower( (string) $img->getAttribute( 'class' ) ) ) . ' ';

		$px = function ( $token ) use ( $cls ) {
			// arbitrary value first: w-[64px] / h-[4rem]
			if ( preg_match( '/\s' . $token . '-\[([0-9.]+)(px|rem)\]/', $cls, $m ) ) {
				return ( 'rem' === $m[2] ) ? ( (float) $m[1] * 16 ) : (float) $m[1];
			}
			// Tailwind spacing step: w-16 = 4rem = 64px. Cap at 24 (96px) -- beyond that it is not a chip.
			if ( preg_match( '/\s' . $token . '-(\d{1,2})\s/', $cls, $m ) ) {
				$n = (int) $m[1];
				if ( $n >= 1 && $n <= 24 ) { return $n * 4.0; }
			}
			return 0.0;
		};

		$w = $px( 'w' );
		$h = $px( 'h' );
		$fit = ( strpos( $cls, 'object-cover' ) !== false ) ? 'cover'
			: ( ( strpos( $cls, 'object-contain' ) !== false ) ? 'contain' : '' );
		// A FULL-WIDTH BANNER crop (`w-full h-64 object-cover`: a card's photo strip) — the width is the container's, the
		// height fixed (the MEASURED height, `md:h-64` = 256 at the capture width, over the phone class value): the
		// media_image had rendered at its natural size, inset in the card (a real-site audit)
		if ( $w <= 0 && preg_match( '/\sw-full\s/', $cls ) ) {
			$mh = self::sc_css( $img, 'height' );
			if ( preg_match( '/^([0-9.]+)px$/', $mh, $mhm ) && (float) $mhm[1] >= 40 ) { $h = (float) $mhm[1]; }
			if ( $h > 0 ) { return 'selector{width:100%;align-self:stretch;}selector img{width:100%;height:' . rtrim( rtrim( number_format( $h, 2, '.', '' ), '0' ), '.' ) . 'px;object-fit:' . ( '' !== $fit ? $fit : 'cover' ) . ';display:block;}'; }
		}
		if ( $w <= 0 || $h <= 0 ) { return ''; }
		$css = 'selector img{width:' . rtrim( rtrim( number_format( $w, 2, '.', '' ), '0' ), '.' ) . 'px;'
			. 'height:' . rtrim( rtrim( number_format( $h, 2, '.', '' ), '0' ), '.' ) . 'px;'
			. ( '' !== $fit ? 'object-fit:' . $fit . ';' : '' ) . 'display:block;flex:0 0 auto;}';
		return $css;
	}

	private static function media_box_from_ancestors( $img ) {
		if ( ! ( $img instanceof DOMElement ) ) { return ''; }
		$icls = ' ' . preg_replace( '/\s+/', ' ', strtolower( (string) $img->getAttribute( 'class' ) ) ) . ' ';
		if ( strpos( $icls, 'object-cover' ) === false ) { return ''; }

		$box = '';
		$p   = $img->parentNode;
		for ( $i = 0; $i < 3 && $p instanceof DOMElement; $i++ ) {
			$box = self::box_decl_from_classes( (string) $p->getAttribute( 'class' ) );
			if ( '' !== $box ) { break; }
			$p = $p->parentNode;
		}
		if ( '' === $box ) { return ''; }

		return 'selector{' . $box . 'overflow:hidden;}'
			. 'selector img{width:100%;height:100%;object-fit:cover;display:block;}';
	}

	private static function section_root_row( $node, $rules ) {
		if ( ! ( $node instanceof DOMElement ) ) { return null; }

		$subs = 0;
		foreach ( self::el_children( $node ) as $c ) {
			$cc = ' ' . strtolower( self::cls( $c ) ) . ' ';
			// Decor / overlays are positioned out of flow and must not count towards "two columns".
			if ( strpos( $cc, ' absolute ' ) !== false || strpos( $cc, ' fixed ' ) !== false ) { continue; }
			if ( strpos( $cc, ' hidden ' ) !== false ) { continue; }
			$txt   = trim( preg_replace( '/\s+/', ' ', self::text( $c ) ) );
			$media = $c->getElementsByTagName( 'img' )->length
				+ $c->getElementsByTagName( 'video' )->length
				+ $c->getElementsByTagName( 'svg' )->length
				+ ( '' !== self::bg_photo_url( $c ) ? 1 : 0 ); // a CSS-painted photo half
			if ( mb_strlen( $txt ) >= 25 || $media > 0 ) { $subs++; }
		}
		if ( $subs < 2 ) { return null; }
		if ( ! self::is_layout_row( $node ) ) { return null; }
		// The root IS a CARD GRID (a segmented band = the `grid md:grid-cols-3` of feature cards itself): build it exactly as
		// the card_grid recognizer would (cells → cards → icon_boxes wearing Box Presets), not as generic layout columns
		// whose cells then fell to the panel path (a nested flexbox with the skin as inline CSS and the icon dropped).
		// The root's own margin is the SECTION's rhythm (Pass #5 folds it into the native padding), not the row's.
		$root_disp = strtolower( self::sc_css( $node, 'display' ) ); $root_dir = strtolower( self::sc_css( $node, 'flex-direction' ) );
		$root_grid = ( 'grid' === $root_disp ) || ( false !== strpos( $root_disp, 'flex' ) && 0 !== strpos( $root_dir, 'column' ) ); // a horizontal grid / flex ROW of cells — never a flex column (a shell stacking its rows)
		if ( $root_grid && self::is_card_grid( $node ) ) { $recs = self::recognizers(); if ( isset( $recs['card_grid']['build'] ) ) { $cg = call_user_func( $recs['card_grid']['build'], $node ); if ( is_array( $cg ) ) { $cg['mt'] = 0.0; $cg['mb'] = 0.0; return $cg; } } }

		self::$row_decor = array();
		$cols = self::layout_cols( $node );
		$root_decor = self::$row_decor; self::$row_decor = array();
		if ( ! is_array( $cols ) || count( $cols ) < 2 ) { return null; }

		return array(
			'rootDecor' => $root_decor, // the root grid's absolute decor cells (a bottom-edge hairline) — emitted beside the row by the caller
			't'       => 'row',
			'role'    => 'columns',
			'valign'  => self::row_valign( $node ),
			'gap'     => self::grid_gap_px( $node ),
			'gapResp' => self::grid_gap_responsive( $node ),
			'stackBp' => self::grid_stack_bp( $node ),
			'tracksMd' => self::tracks_count_at( $node, 'data-sc-cs-md' ), // TABLET / PHONE PASS: the measured track counts (mapper: col_resp)
			'tracksSm' => self::tracks_count_at( $node, 'data-sc-cs-sm' ),
			'mb'      => 0.0,
			'mt'      => 0.0, // the root's own margin is the SECTION's rhythm (Pass #5 folds it into the native padding) — not the row's
			'cols'    => $cols,
		);
	}

	/**
	 * A CHIP ROW: a flex container (computed `display:flex`, or a `flex` / `inline-flex` utility) with >=2
	 * element children, EVERY one a short text leaf (own text 1–40 chars, only inline / empty decorative
	 * children, no media / link / button) that is BOXED — a fill, gradient, border or shadow of its own (the
	 * mapper's text_is_box) — or pill-shaped (radius >= 40px). A tag row, a metric row, a skills list.
	 */
	private static function is_chip_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( ! preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/', $cs ) && ! preg_match( '/\s(?:inline-)?flex\s/', $cls ) ) { return false; }
		if ( preg_match( '/(?:^|;)\s*flex-direction:\s*column/', $cs ) ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 || count( $kids ) > 12 ) { return false; }
		$plain = 0;
		foreach ( $kids as $k ) {
			$tag = strtolower( $k->tagName );
			if ( in_array( $tag, array( 'a', 'button', 'img', 'svg', 'video', 'ul', 'ol', 'nav', 'form', 'input' ), true ) ) { return false; }
			foreach ( array( 'a', 'button', 'img', 'video', 'iframe', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'ul', 'div' ) as $t ) {
				foreach ( $k->getElementsByTagName( $t ) as $d ) { if ( 'div' === $t && '' === trim( self::text( $d ) ) ) { continue; } return false; } // a dot/pip div is fine; content is not
			}
			$txt = trim( preg_replace( '/\s+/', ' ', self::text_no_icons( $k ) ) );
			if ( '' === $txt || mb_strlen( $txt ) > 40 ) { return false; }
			$kcs = (string) $k->getAttribute( 'data-sc-cs' );
			$boxed = class_exists( 'FW_Site_Converter_Mapper' ) && method_exists( 'FW_Site_Converter_Mapper', 'text_is_box' ) && FW_Site_Converter_Mapper::text_is_box( $kcs );
			$pill  = preg_match( '/(?:^|;)\s*border-radius:\s*([0-9.]+)px/', $kcs, $rm ) && (float) $rm[1] >= 40;
			if ( ! $boxed && ! $pill ) { $plain++; }
		}
		// Every chip boxed → a pill row. ALL plain → a tag row (a footer's 'Harvest · Water · Equilibrium' spans spaced by
		// the row's gap): still ONE flex row of text leaves, each keeping its typography, no Box Preset. A mix is neither.
		if ( $plain > 0 && $plain < count( $kids ) ) { return false; }
		if ( $plain === count( $kids ) ) {
			if ( ! preg_match( '/(?:^|;)\s*gap:\s*([0-9.]+)px/', $cs, $gm ) || (float) $gm[1] <= 0 ) { return false; }
			if ( preg_match( '/(?:^|;)\s*justify-content:\s*space-/', $cs ) ) { return false; } // a SPREAD row (brand left, tags right) is a layout row
			foreach ( $kids as $k ) {
				if ( ! in_array( strtolower( $k->tagName ), array( 'span', 'div', 'li' ), true ) ) { return false; }
				foreach ( self::el_children( $k ) as $kk ) { if ( ! in_array( strtolower( $kk->tagName ), array( 'svg', 'i', 'em', 'strong', 'b' ), true ) ) { return false; } } // a leaf label (an icon is fine), not a container
			}
		}
		return true;
	}

	/**
