		}
		if ( 1 === count( $rows ) ) { return $rows[0]; } // one row, unequal cells (a 2/3 + 1/3 pair) — widths from the measure
		return array( 't' => 'stack', 'role' => 'stack', 'gap' => (int) ( $row['gap'] ?? 0 ), 'mt' => (float) ( $row['mt'] ?? 0 ), 'mb' => (float) ( $row['mb'] ?? 0 ), 'items' => $rows, 'bento' => true );
	}

	/** The number of grid tracks in a pass stamp's `grid-template-columns` (0 when the pass recorded no change / not a grid). */
	private static function tracks_count_at( $el, $attr ) {
		if ( ! ( $el instanceof DOMElement ) || ! preg_match( '/(?:^|;)\s*grid-template-columns:\s*([^;]+)/i', (string) $el->getAttribute( $attr ), $m ) ) { return 0; }
		$v = trim( $m[1] ); if ( '' === $v || 'none' === strtolower( $v ) ) { return 0; }
		return count( preg_split( '/\s+/', $v ) );
	}

	/** An absolutely / fixed-positioned element with no text, image, svg, video or iframe — a painted backdrop layer. */
	private static function is_empty_positioned_layer( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' ); $cl = ' ' . self::cls( $el ) . ' ';
		if ( ! preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $cs ) && false === strpos( $cl, ' absolute ' ) && false === strpos( $cl, ' fixed ' ) ) { return false; }
		if ( '' !== trim( self::text( $el ) ) ) { return false; }
		foreach ( array( 'img', 'svg', 'video', 'iframe', 'canvas', 'picture' ) as $t ) { if ( $el->getElementsByTagName( $t )->length > 0 ) { return false; } }
		return true;
	}

	private static function is_layout_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( self::is_toolbar_row( $el ) ) { return false; } // a flex row of short labels (+ dot separators) is a toolbar line, not columns — a 24-char label counted as a "substantial cell"
		if ( self::is_badge( $el ) ) { return false; }       // a PILL (an icon + a short label in a rounded, bordered inline-flex) is the heading's eyebrow, never two columns (measured: a hero badge split into an icon cell + a text cell)
		$kids = self::el_children( $el );
		// an EMPTY, absolutely-positioned child (a gradient / glow / pattern layer over the band) is a DECOR layer, never a
		// column: a hero whose first child was such a layer became a 3-column row (a fixture from the feed)
		$kids = array_values( array_filter( $kids, function ( $k ) { return ! self::is_empty_positioned_layer( $k ); } ) );
		if ( count( $kids ) < 2 ) { return false; }
		$cls = self::cls( $el );
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		// A MEASURED grid (≥ 2 px tracks in the computed grid-template-columns) declares its columns itself: any cell with
		// visible text, a control, or media is a column — a label + value stat cell (15 chars, no <p>) or a lone-button
		// cell used to fail the "substantial" test, so the 3-up stats and the quote + orb bands lost their row wrapper
		// and stacked (a RECURRING finding: "stats grid emitted without its row wrapper").
		$measured_tracks = 0;
		if ( preg_match( '/grid-template-columns:\s*([^;]+)/i', $cs, $gm ) ) { foreach ( preg_split( '/\s+/', trim( $gm[1] ) ) as $tk ) { if ( preg_match( '/^[0-9.]+px$/', $tk ) && (float) $tk >= 40 ) { $measured_tracks++; } } }
		$subs = 0;
		foreach ( $kids as $k ) {
			if ( self::is_substantial_cell( $k ) ) { $subs++; continue; }
			if ( $measured_tracks >= 2 && ( '' !== trim( self::text( $k ) ) || $k->getElementsByTagName( 'a' )->length || $k->getElementsByTagName( 'button' )->length || $k->getElementsByTagName( 'img' )->length || $k->getElementsByTagName( 'svg' )->length ) ) { $subs++; }
		}
		// A MARKER ROW: a horizontal flex pair whose FIRST cell is a marker (a short ordinal "01", a lone icon) beside a
		// substantial text cell (a benefits / steps list's `span.01 + div(h3 + p)`, `svg + div(h4 + p)`) is a 2-column row —
		// the marker cell never counted as substantial, so the row lost its wrapper and its parts stacked as siblings
		// (RECURS in the feed: "icon, title, text arrive as three siblings"). The mapper keeps the marker's measured track.
		// (…the marker may also TRAIL the text: an accordion-style row `h3 + svg.chevron` with `justify-between` — its arrow dropped
		// under the title as a stacked sibling and the row's hairline went with it; a finding from the feed)
		if ( $subs === 1 && 2 === count( $kids ) && preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $cs ) && ! preg_match( '/flex-direction:\s*column/i', $cs ) && ( self::is_substantial_cell( $kids[1] ) || self::is_substantial_cell( $kids[0] ) ) ) {
			$mk = self::is_substantial_cell( $kids[1] ) ? $kids[0] : $kids[1]; $mt = trim( preg_replace( '/\s+/u', ' ', self::text( $mk ) ) );
			$is_marker = (bool) preg_match( '/^(?:\d{1,3}\.?|[①-⑳])$/u', $mt )
				|| ( '' === $mt && ( $mk->getElementsByTagName( 'svg' )->length > 0 || 'svg' === strtolower( $mk->tagName ) || $mk->getElementsByTagName( 'i' )->length > 0 ) );
			if ( $is_marker ) { $subs = 2; }
		}
		// A FILLED HEADER ROW: a horizontal flex with its OWN fill and a fixed height (a card's `h-24 bg-teal flex justify-between`
		// band holding a tag pill and an icon disc) is a row whatever its cells hold — flattened, its fill vanished and its pill
		// and disc stacked (a fixture from the feed). The row's skin rides as its rowBox.
		if ( $subs < 2 && count( $kids ) >= 2 && preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $cs ) && ! preg_match( '/flex-direction:\s*column/i', $cs )
			&& preg_match( '/(?:^|;)\s*background-color:\s*(?!rgba\([^)]*,\s*0\s*\)|transparent)[^;]+/i', $cs ) && preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $fhm ) && (float) $fhm[1] >= 40 && (float) $fhm[1] <= 200 ) {
			$filled = 0; foreach ( $kids as $k ) { if ( '' !== trim( self::text( $k ) ) || $k->getElementsByTagName( 'svg' )->length || $k->getElementsByTagName( 'img' )->length || self::is_painted_panel( $k ) || preg_match( '/(?:^|;)\s*background-color:\s*(?!rgba\([^)]*,\s*0\s*\)|transparent)[^;]+/i', (string) $k->getAttribute( 'data-sc-cs' ) ) ) { $filled++; } } // (+ a painted disc / tile)
			if ( $filled >= 2 ) { $subs = 2; }
		}
		if ( $subs < 2 ) { return false; }

		$pad = ' ' . $cls . ' ';

		// (A) Tailwind grid. A DESKTOP column count >=2 (explicit `grid-cols-N` or a responsive
		//     `lg:grid-cols-N`) is a genuine multi-column band. HARDENING: an explicit single-column
		//     `grid-cols-1` with NO wider responsive override is a vertical STACK, not a row — reject it
		//     outright instead of letting grid_col_count() fall through to its card-cell fallback (which would
		//     mis-count stacked card-like children as columns and over-claim a single-column heading/content band).
		$has_grid = ( strpos( $cls, 'grid' ) !== false ) || (bool) preg_match( '/display:\s*grid/i', $cs );
		if ( $has_grid ) {
			$multi_bp = false;
			foreach ( array( '2xl', 'xl', 'lg', 'md', 'sm' ) as $bp ) {
				if ( preg_match( '/' . $bp . ':grid-cols-(\d{1,2})/', $cls, $mm ) && (int) $mm[1] >= 2 ) { $multi_bp = true; break; }
			}
			if ( $multi_bp ) { return true; }
			$base_cols = preg_match( '/(?:^|\s)grid-cols-(\d{1,2})/', $cls, $bm ) ? (int) $bm[1] : -1;
			if ( $base_cols >= 2 ) { return true; }
			if ( 1 === $base_cols ) { return false; } // explicit single column, not widened responsively → stack
			// A grid with NO explicit grid-cols (pure computed grid or auto-flow): fall through to (B)/(C).
		}

		// (B) Computed grid-template-columns with >=2 non-trivial tracks (non-Tailwind / plain CSS grid).
		if ( preg_match( '/grid-template-columns:\s*([^;]+)/i', $cs, $m ) ) {
			$tracks = array_values( array_filter( preg_split( '/\s+/', trim( $m[1] ) ), function ( $t ) { return '' !== $t && 'none' !== strtolower( $t ); } ) );
			if ( count( $tracks ) >= 2 ) { return true; }
		}

		// (C) Desktop flex-ROW. HARDENING: require a REAL flex-container token (`flex` / `inline-flex` as a
		//     whole class, NOT the substring inside `flex-col` / `flex-wrap`) AND a row direction AT DESKTOP. A
		//     base `flex-col` that ISN'T overridden by a responsive `*:flex-row` is a vertical stack → reject.
		//     A bare `flex` with no direction class is NOT claimed here (matching the original strict intent):
		//     an explicit row signal is required so a centered single-column flex band never becomes a row.
		$is_flex = (bool) preg_match( '/(?:^|\s)(?:inline-)?flex(?:\s|$)/', $pad ) || (bool) preg_match( '/display:\s*(?:inline-)?flex/i', $cs );
		if ( $is_flex ) {
			$has_col   = (bool) preg_match( '/(?:^|\s)(?:(?:sm|md|lg|xl|2xl):)?flex-col(?:\s|$)/', $pad );
			$resp_row  = (bool) preg_match( '/(?:^|\s)(?:sm|md|lg|xl|2xl):flex-row(?:\s|$)/', $pad );
			$base_row  = (bool) preg_match( '/(?:^|\s)flex-row(?:\s|$)/', $pad );
			if ( $resp_row ) { return true; }                          // desktop override to row wins
			if ( $base_row && ! $has_col ) { return true; }            // explicit row, not also declared column
			if ( ! $has_col && preg_match( '/flex-direction:\s*row/i', $cs ) ) { return true; } // computed row, no col class
		}

		return false;
	}

	/** A row's desktop vertical alignment (source `items-center` / computed `align-items:center`) → start|center|end. */
	private static function row_valign( $el ) {
		$cls = self::cls( $el );
		$cs  = (string) ( $el instanceof DOMElement ? $el->getAttribute( 'data-sc-cs' ) : '' );
		if ( strpos( $cls, 'items-center' ) !== false || preg_match( '/align-items:\s*center/i', $cs ) ) { return 'center'; }
		if ( strpos( $cls, 'items-end' ) !== false || preg_match( '/align-items:\s*(?:flex-)?end/i', $cs ) ) { return 'end'; }
		if ( strpos( $cls, 'items-start' ) !== false || preg_match( '/align-items:\s*(?:flex-)?start/i', $cs ) ) { return 'start'; }
		return '';
	}

	/**
	 * Build the Mapper "cols" array for a LAYOUT row (is_layout_row). Unlike grid_cols (which maps card cells
	 * to icon_boxes), a layout band's cells hold mixed content (a hero's text+CTA column, an image column),
	 * so each cell is kept VERBATIM with its classes inside a `.sc-tw` wrapper — the Tailwind compiler then
	 * styles it, matching the source. Widths come from an explicit `col-span-N`, else even division across the
	 * band. Empty / purely-decorative cells are dropped. Returns null if fewer than 2 real cells survive.
	 */
	/**
	 * Proportional 12-column widths for a flex row whose children use ARBITRARY px widths (`w-[Npx]`) and/or
	 * `flex-1`. Returns [childIndex => desk(1-12)] or [] when no px width is present (then even division runs).
	 * px-only rows are normalised to sum 12; a px + flex mix gives the flex column(s) the remainder. (P3 fix.)
	 */
	/**
	 * Is this flex row CONTENT-SIZED — no cell declares a width (`w-*` / `basis-*` / `flex-1` / `grow` / `col-span-*`),
	 * the row is a flex row (not a declared grid), and the cells' measured tracks (`track-frac`) sum to well under
	 * the row (≤ .75)? Then the source laid its cells out at their content width with a gap, and the converter must
	 * not split the row into equal 12-grid spans. Needs the desktop geometry stamp on every content cell.
	 */
	private static function row_is_content_sized( $grid, array $children ) {
		if ( ! ( $grid instanceof DOMElement ) ) { return false; }
		if ( self::grid_col_count( $grid ) >= 2 ) { return false; }
		$disp = strtolower( (string) self::sc_css( $grid, 'display' ) );
		$dir  = strtolower( (string) self::sc_css( $grid, 'flex-direction' ) );
		if ( false === strpos( $disp, 'flex' ) || 0 === strpos( $dir, 'column' ) ) { return false; }
		$sum = 0.0; $n = 0;
		foreach ( $children as $cell ) {
			if ( ! ( $cell instanceof DOMElement ) ) { continue; }
			$cls = ' ' . self::cls( $cell ) . ' ';
			if ( preg_match( '/(?:\s|:)(?:w-(?!px\s)[\w\[\]\/.%-]+|basis-[\w\[\]\/.%-]+|flex-1|flex-auto|grow|col-span-\d+|min-w-(?!0\s)[\w\[\]-]+)\s/', $cls ) ) { return false; }
			if ( '' === self::text( $cell ) && ! $cell->getElementsByTagName( 'img' )->length && ! $cell->getElementsByTagName( 'svg' )->length ) { continue; } // a divider takes no share
			if ( ! preg_match( '/(?:^|;)\s*track-frac:\s*([0-9.]+)/', (string) $cell->getAttribute( 'data-sc-cs' ), $m ) ) { return false; }
			$sum += (float) $m[1]; $n++;
		}
		return $n >= 1 && $sum > 0 && $sum <= 0.75;
	}

	/** A divider cell's fixed size ({ w, h } px) — an empty painted cell at most 4px on one axis — or null. */
	private static function divider_cell_size( $cell ) {
		$p = self::panel_paint( $cell );
		if ( '' === $p['bg'] && '' === $p['bgi'] ) { return null; }
		$w = self::sc_css( $cell, 'width' ); $h = self::sc_css( $cell, 'height' );
		if ( ! preg_match( '/^([0-9.]+)px$/', $w, $mw ) || ! preg_match( '/^([0-9.]+)px$/', $h, $mh ) ) { return null; }
		$w = (float) $mw[1]; $h = (float) $mh[1];
		if ( $w <= 0 || $h <= 0 || ( $w > 4 && $h > 4 ) || max( $w, $h ) > 400 ) { return null; }
		return array( 'w' => round( $w, 2 ), 'h' => round( $h, 2 ) );
	}

	private static function layout_px_fractions( $children ) {
		$px = array(); $flex = array(); $has_px = false;
		foreach ( $children as $i => $cell ) {
			if ( ! ( $cell instanceof DOMElement ) ) { continue; }
			$cls = ' ' . self::cls( $cell ) . ' ';
			if ( self::col_span( $cls ) >= 1 ) { continue; }
			if ( preg_match( '/(?:\s|:)w-\[(\d+(?:\.\d+)?)(px|rem|em)\]/', $cls, $m ) ) { $px[ $i ] = (float) $m[1] * ( 'px' === $m[2] ? 1 : 16 ); $has_px = true; } // an arbitrary px / rem width (`md:w-[32rem]`)
			elseif ( preg_match( '/\s(?:flex-1|flex-auto|grow)\s/', $cls ) ) { $flex[ $i ] = true; }
		}
		if ( ! $has_px ) { return array(); }
		// The MEASURED fractions (the capture's track-frac on every cell) beat any estimate of the row width: a `flex-1` card
		// beside a `w-[32rem]` one measured .62 / .36 — the 12-grid spans follow that (8 / 4), not a 1200px guess.
		$fr_all = true; $fr = array();
		foreach ( $children as $i => $cell ) { if ( ! ( $cell instanceof DOMElement ) ) { continue; } if ( preg_match( '/(?:^|;)\s*track-frac:\s*([0-9.]+)/', (string) $cell->getAttribute( 'data-sc-cs' ), $fm ) && (float) $fm[1] > 0 ) { $fr[ $i ] = (float) $fm[1]; } else { $fr_all = false; } }
		if ( $fr_all && count( $fr ) >= 2 && array_sum( $fr ) <= 1.05 ) {
			$out = array(); $acc = 0; $keys = array_keys( $fr ); $last = end( $keys );
			foreach ( $fr as $i => $f ) { $out[ $i ] = ( $i === $last ) ? max( 1, 12 - $acc ) : max( 1, min( 11, (int) round( $f * 12 ) ) ); $acc += $out[ $i ]; }
			return $out;
		}
		$sumpx = array_sum( $px );
		if ( $sumpx <= 0 ) { return array(); }
		$ref = $flex ? max( 1200.0, $sumpx * 1.3 ) : $sumpx;
		$out = array(); $used = 0;
		foreach ( $px as $i => $w ) { $fr = max( 1, min( 11, (int) round( ( $w / $ref ) * 12 ) ) ); $out[ $i ] = $fr; $used += $fr; }
		if ( $flex ) {
			$rem = 12 - $used; if ( $rem < count( $flex ) ) { $rem = count( $flex ); }
			$each = intdiv( $rem, count( $flex ) ); $ex = $rem - $each * count( $flex ); $first = true;
			foreach ( $flex as $i => $_u ) { $out[ $i ] = max( 1, $each + ( $first ? $ex : 0 ) ); $first = false; }
		} elseif ( $used > 0 && $used !== 12 ) {
			$scale = 12.0 / $used; $acc = 0; $keys = array_keys( $out ); $last = end( $keys );
			foreach ( $out as $i => $fr ) { if ( $i === $last ) { $out[ $i ] = max( 1, 12 - $acc ); } else { $out[ $i ] = max( 1, (int) round( $fr * $scale ) ); $acc += $out[ $i ]; } }
		}
		return $out;
	}

	/**
	 * The parent grid's COMPUTED px tracks (`grid-template-columns: 736.547px 627.453px`), one per child, or
	 * [] when the tracks aren't a plain px list matching the child count. An unequal split (`1.08fr .92fr`)
	 * can't be expressed by the 12-column span model (it rounds to 6/6); the mapper renders it as a native
	 * Grid with the exact track ratio instead.
	 */
	private static function grid_px_tracks( $grid, $n_children ) {
		if ( ! ( $grid instanceof DOMElement ) ) { return array(); }
		$tpl = trim( (string) self::sc_css( $grid, 'grid-template-columns' ) );
		if ( '' === $tpl || 'none' === $tpl ) { return array(); }
		$toks = preg_split( '/\s+/', $tpl );
		$out  = array();
		foreach ( $toks as $t ) { if ( ! preg_match( '/^([0-9.]+)px$/', $t, $m ) ) { return array(); } if ( (float) $m[1] <= 0 ) { continue; } $out[] = (float) $m[1]; } // (a 0px track = a collapsed auto-fit slot)
		if ( count( $out ) < 2 ) { return array(); }
		if ( count( $out ) !== (int) $n_children ) {
			// an out-of-flow decor child (an absolute hairline "light river" under the hero) takes no track: count the IN-FLOW children
			$flow = 0; foreach ( self::el_children( $grid ) as $k ) { if ( ! preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', (string) $k->getAttribute( 'data-sc-cs' ) ) ) { $flow++; } }
			if ( count( $out ) !== $flow ) { return array(); }
		}
		return $out;
	}

	/**
	 * A grid cell's OWN geometry the column must keep: a fixed `min-height` (a 640px card) and a flex-column
	 * with vertically CENTRED content (`display:flex; flex-direction:column; justify-content:center`). Both
	 * were dropped, so a source card collapsed to its content height with the copy top-aligned.
	 * @return array { minh?: int, vcenter?: true }
	 */
	/** The box that lays a cell's content out as a FLEX COLUMN: the cell itself when it is one; else its ONE in-flow child
	 *  when that child is a full-height flex column (`relative z-10 h-full flex flex-col justify-between` over an absolute
	 *  glow — its height ≥ 90% of the cell's content box); else null. */
	private static function cell_flex_column_box( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return null; }
		if ( false !== strpos( (string) self::sc_css( $cell, 'display' ), 'flex' ) ) { return 0 === strpos( (string) self::sc_css( $cell, 'flex-direction' ), 'column' ) ? $cell : null; }
		$flow = array();
		foreach ( self::el_children( $cell ) as $kid ) { $kcs = (string) $kid->getAttribute( 'data-sc-cs' ); if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $kcs ) || preg_match( '/(?:^|;)\s*display:\s*none/i', $kcs ) ) { continue; } $flow[] = $kid; }
		if ( 1 !== count( $flow ) ) { return null; }
		$wd = (string) self::sc_css( $flow[0], 'display' ); $wdir = (string) self::sc_css( $flow[0], 'flex-direction' );
		$ch = (float) self::sc_css( $cell, 'height' ); $wh = (float) self::sc_css( $flow[0], 'height' );
		$pads = self::cs_decls_pad( (string) $cell->getAttribute( 'data-sc-cs' ) ); // (the stamp's `padding` shorthand)
		$cpad = is_array( $pads ) ? $pads['top'] + $pads['bottom'] : self::sc_pad_top_px( $cell ) + (float) self::sc_css( $cell, 'padding-bottom' );
		return ( false !== strpos( $wd, 'flex' ) && 0 === strpos( $wdir, 'column' ) && $ch > 0 && $wh >= 0.9 * ( $ch - $cpad ) ) ? $flow[0] : null;
	}

	/** In a cell DISTRIBUTED as a flex column (justify space-between / -around / -evenly / end), a leading label that is its
	 *  own flex item (a `<span class="micro-label">` before a `<div class="mt-12">` holding the h3 + p) is set APART from the
	 *  title by the distribution: mark the first block `apart` so the mapper keeps it a standalone kicker instead of folding
	 *  it into the title's heading (the label then sat on the title, not at the card's top — a real-site audit). */
	private static function mark_apart_label( $cell, array $blocks, array $geo ) {
		if ( count( $blocks ) < 2 || empty( $geo['vjustify'] ) ) { return $blocks; }
		$bi = 0; while ( $bi < count( $blocks ) - 1 && 'paint' === (string) ( $blocks[ $bi ]['t'] ?? '' ) ) { $bi++; } // (a decor blob ahead of the label is out of flow)
		if ( 'text' !== (string) ( $blocks[ $bi ]['t'] ?? '' ) ) { return $blocks; }
		$box = self::cell_flex_column_box( $cell );
		if ( ! ( $box instanceof DOMElement ) ) { return $blocks; }
		$flow = array();
		foreach ( self::el_children( $box ) as $kid ) { $kcs = (string) $kid->getAttribute( 'data-sc-cs' ); if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $kcs ) || preg_match( '/(?:^|;)\s*display:\s*none/i', $kcs ) ) { continue; } $flow[] = $kid; }
		if ( count( $flow ) < 2 ) { return $blocks; }
		$first = $flow[0];
		if ( preg_match( '/^h[1-6]$/', strtolower( $first->tagName ) ) ) { return $blocks; }
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $tg ) { if ( $first->getElementsByTagName( $tg )->length ) { return $blocks; } }
		$ft = trim( preg_replace( '/\s+/u', ' ', self::text( $first ) ) ); $bt = trim( preg_replace( '/\s+/u', ' ', (string) ( $blocks[ $bi ]['text'] ?? '' ) ) );
		if ( '' === $ft || $ft !== $bt ) { return $blocks; }
		$blocks[ $bi ]['apart'] = true;
		return $blocks;
	}

	private static function cell_geometry( $cell ) {
		$out = array();
		if ( ! ( $cell instanceof DOMElement ) ) { return $out; }
		// The cell's OWN vertical margin (a `text-center mb-20` heading wrapper that became a stacked row's cell): the source's gap
		// below / above the cell, carried onto the column's Spacing (a flattened wrapper carries it as mbAdd — a cell had no path).
		$cm = self::el_margin( $cell );
		// the cell's OWN text alignment (`text-center` / a computed text-align) — a padded hours tile with no class list on the
		// cell record rendered its two lines left-aligned (the mapper read only the cell's classes; a real-site audit)
		$cta = strtolower( trim( self::sc_css( $cell, 'text-align' ) ) ); $ccl = ' ' . self::cls( $cell ) . ' ';
		if ( preg_match( '/\stext-center\s/', $ccl ) || 'center' === $cta ) { $out['align'] = 'center'; }
