	private static function cell_is_decomposable( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return false; }
		for ( $i = 1; $i <= 6; $i++ ) { if ( $cell->getElementsByTagName( 'h' . $i )->length > 0 ) { return true; } }
