	 * @param DOMNode $el
	 * @return bool
	 */
	/**
	 * In a verbatim (`.sc-tw`) content card, re-assert each heading's OWN computed colour as an inline
	 * `color:… !important` (read from data-sc-cs, before it's stripped). A card heading typically carries a
	 * custom colour class (`text-primary`) with no `!important`, which loses to the section's `!important`
	 * white heading rule (set because the section band is coloured) — so on the white card it would render
	 * white-on-white. Inline !important beats the stylesheet rule and keeps the heading its real colour.
	 */
	private static function inject_verbatim_heading_colors( $html ) {
		return preg_replace_callback( '/<(h[1-6])\b([^>]*)>/i', function ( $m ) {
			$attrs = $m[2];
			// Match BOTH quote styles — saveHTML() serialises data-sc-cs with SINGLE quotes when its value holds a
			// double quote (a font-family like "Neutraface Condensed Titling"), which a double-quote-only pattern skips.
			if ( ! preg_match( '/data-sc-cs=(?:"[^"]*|\'[^\']*)(?<![\w-])color:\s*(rgba?\([^)]*\)|#[0-9a-f]{3,8})/i', $attrs, $cm ) ) { return $m[0]; }
			$c = trim( $cm[1] );
			if ( preg_match( '/rgba?\([^)]*[,\/]\s*0\s*\)/i', $c ) ) { return $m[0]; } // fully transparent → skip
			if ( preg_match( '/\bstyle="[^"]*"/i', $attrs ) ) {
				$attrs = preg_replace_callback( '/\bstyle="([^"]*)"/i', function ( $sm ) use ( $c ) { $ex = rtrim( trim( $sm[1] ), ';' ); return 'style="' . ( '' !== $ex ? $ex . ';' : '' ) . 'color:' . $c . ' !important"'; }, $attrs, 1 );
			} else {
				$attrs .= ' style="color:' . $c . ' !important"';
			}
			return '<' . $m[1] . $attrs . '>';
		}, (string) $html );
	}

	/**
	 * A DECORATIVE RULE / bar — an EMPTY div (no text, no media, no element children) with a real background
	 * fill AND a thin height (a heading underline `w-24 h-1 bg-*`, a divider). Reproduced verbatim so the exact
	 * width / colour / centring survive, instead of being dropped as an empty element.
	 *
	 * @param DOMNode $el
	 * @return bool
	 */
	private static function is_decorative_bar( $el ) {
		if ( ! ( $el instanceof DOMElement ) || 'div' !== strtolower( $el->nodeName ) ) { return false; }
		if ( '' !== trim( (string) self::text( $el ) ) ) { return false; }
		foreach ( array( 'img', 'svg', 'video', 'iframe', 'a', 'button' ) as $t ) { if ( $el->getElementsByTagName( $t )->length ) { return false; } }
		foreach ( $el->childNodes as $c ) { if ( XML_ELEMENT_NODE === $c->nodeType ) { return false; } }
		$cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$has_fill = preg_match( '/(?<![\w-])background-color:\s*(?:rgb\([^)]*\)|#[0-9a-f]{3,8}|rgba\([^)]*[,\/]\s*(?:0?\.[5-9]\d*|1)\s*\))/i', $cs )
			|| preg_match( '/\bbg-(?!transparent|none)[a-z0-9\[]/', $cls )
			|| '' !== trim( (string) $el->getAttribute( 'style' ) ) && preg_match( '/background/i', (string) $el->getAttribute( 'style' ) );
		if ( ! $has_fill ) { return false; }
		// A THIN bar: an h-0.5…h-3 / h-px / arbitrary small-h class, or a computed height ≤ 10px.
		$thin = (bool) preg_match( '/\bh-(?:0\.5|1|1\.5|2|2\.5|3|px|\[[0-9](?:\.\d+)?(?:px)?\])(?:\s|$)/', $cls );
		if ( ! $thin && preg_match( '/(?<![\w-])height:\s*([0-9.]+)px/', $cs, $hm ) && (float) $hm[1] > 0 && (float) $hm[1] <= 10 ) { $thin = true; }
		return $thin;
	}

	/** A flex ROW (or any wrapper) whose element children are ALL decorative bars, ≥ 2 of them, no text. */
	private static function is_decorative_bar_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) || 'div' !== strtolower( $el->nodeName ) ) { return false; }
		if ( '' !== trim( (string) self::text( $el ) ) ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		foreach ( $kids as $k ) { if ( ! self::is_decorative_bar( $k ) ) { return false; } }
		return true;
	}

	/** A skinned wrapper that HOLDS content (see the 'panel' recognizer). */
	private static function is_panel( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( ! in_array( strtolower( $el->tagName ), array( 'div', 'article', 'aside', 'section', 'figure' ), true ) ) { return false; }
		$kids = self::el_children( $el );
		if ( ! $kids ) { return false; }
		$skin = self::read_card_skin( $el );
		if ( ! is_array( $skin ) || ( '' === (string) $skin['bg'] && '' === (string) $skin['gradient'] && '' === (string) $skin['borderW'] && '' === (string) $skin['shadow'] ) ) { return false; }
		// Holds BLOCK content: a heading / paragraph / list / picture somewhere inside, or a real run of text. A pill or
		// badge (inline children only — a span + an icon svg) is not a panel, whatever its skin.
		$inline_only = true;
		foreach ( $kids as $k ) { if ( ! in_array( strtolower( $k->tagName ), array( 'span', 'svg', 'i', 'em', 'strong', 'b', 'a', 'small', 'br' ), true ) ) { $inline_only = false; break; } }
		if ( $inline_only ) { return false; }
		$content = false;
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'img', 'video', 'iframe', 'picture', 'ul', 'ol', 'form', 'textarea', 'table' ) as $t ) { if ( $el->getElementsByTagName( $t )->length > 0 ) { $content = true; break; } } // (+ a FORM card: a white rounded contact-form card lost its skin — a fixture from the feed)
		if ( ! $content ) {
			// No prose tags: BLOCK children that carry text (a stat card's label div + value div) still make content.
			$txt_blocks = 0;
			foreach ( $kids as $k ) { if ( ! in_array( strtolower( $k->tagName ), array( 'span', 'svg', 'i', 'em', 'strong', 'b', 'a', 'small', 'br' ), true ) && '' !== trim( self::text( $k ) ) ) { $txt_blocks++; } }
			if ( $txt_blocks < 2 && mb_strlen( trim( self::text( $el ) ) ) < 80 ) { return false; }
		}
		// Not a shape another path already owns: a skinned ROW (layout_row carries rowBox), a chip row, the legacy
		// opaque content card (verbatim), an absolutely-placed collage card (absolute_collage owns its parent).
		if ( self::is_layout_row( $el ) || self::is_chip_row( $el ) || self::is_content_card( $el ) || self::is_toolbar_row( $el ) ) { return false; } // (a filled, padded TITLE BAR of dots + labels is a toolbar row, not a panel)
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $cs ) ) { return false; }
		return true;
	}

	/** Build the panel block: its skin, padding, declared measure, centring, decor layers and inner blocks. */
	private static function panel_build( $el, $tag, $rules ) {
		$blocks = array();
		self::collect_blocks( $el, $blocks, $rules );
		$blocks = array_values( array_filter( $blocks ) );
		if ( ! $blocks ) { return null; }
		$cs   = (string) $el->getAttribute( 'data-sc-cs' );
		$skin = self::read_card_skin( $el );
		$skin['padding'] = ''; // the panel's inset is carried as its own padding (apply_cell_pad), not in the preset
		$decl = function ( $prop ) use ( $el ) { $v = self::stylesheet_decl( null, $el, $prop ); return preg_match( '/^[a-z0-9()%.,\s+*\/-]+$/i', $v ) ? $v : ''; };
		$width = $decl( 'width' ); $maxw = $decl( 'max-width' ); $aspect = $decl( 'aspect-ratio' );
		// A DESIGNED height: the sheet declares one (`.data-monolith{height:720px}`), or the panel's sole wrapper is a
		// `h-full flex-col justify-between` column (its content is pinned to the top and bottom of a box taller than it) —
		// the measured height is then the design, carried as min-height, with the space-between as the column's justify.
		// Without it a 720px telemetry panel collapsed to its content (measured: 880 → 561 section height).
		$height = $decl( 'height' ); $between = false;
		$pk1 = self::el_children( $el ); $pk_content = array(); foreach ( $pk1 as $pk ) { if ( ! preg_match( '/(?:^|;)\s*position:\s*absolute/i', (string) $pk->getAttribute( 'data-sc-cs' ) ) ) { $pk_content[] = $pk; } }
		if ( 1 === count( $pk_content ) ) {
			$wcs = (string) $pk_content[0]->getAttribute( 'data-sc-cs' );
			if ( preg_match( '/(?:^|;)\s*display:\s*flex/i', $wcs ) && preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $wcs ) && preg_match( '/(?:^|;)\s*justify-content:\s*space-between/i', $wcs ) ) {
				$between = true;
				if ( '' === $height && preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', $cs, $phm ) && (float) $phm[1] >= 200 ) { $height = round( (float) $phm[1] ) . 'px'; }
			}
		}
		if ( '' !== $height && ! preg_match( '/^[0-9.]+(?:px|vh|rem|em|svh|dvh)$/', $height ) ) { $height = ''; }
		if ( '' === $width && preg_match( '/(?:^|;)\s*width:\s*([0-9.]+px)/i', $cs, $wm ) ) { $width = $wm[1]; }
		if ( '' === $maxw && '' === $width && preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+px)/i', $cs, $wm ) ) { $maxw = $wm[1]; }
		if ( 'auto' === $width || 'none' === $maxw ) { $width = ( 'auto' === $width ) ? '' : $width; $maxw = ( 'none' === $maxw ) ? '' : $maxw; }
		if ( 'auto' === $aspect ) { $aspect = ''; }
		// A SHELL expression — the site's own container cap (min(1440px, calc(100% - 48px)) / min(100% - 32px, 1440px)) —
		// means the panel IS the section's container: the section already provides that measure, so the panel fills it
		// (a nested cap would subtract the gutter twice → 1344 instead of 1392).
		$self_center_cap = false;
		$shell = (bool) preg_match( '/^min\(\s*(?:\d+px\s*,\s*calc\(100%\s*-\s*\d+px\)|100%\s*-\s*\d+px\s*,\s*\d+px|calc\(100%\s*-\s*\d+px\)\s*,\s*\d+px)\s*\)$/i', $width );
		// …but only when the cap IS the site's container measure. A NARROWER min() cap inside the container (a code window's
		// `width: min(1080px, 100% - 32px); margin: 0 auto` under a 1600px .wrap) is the panel's own centred measure — wiping it
		// stretched the window edge to edge. The cap counts as the shell only when it reaches the captured content width.
		if ( $shell ) {
			$cap_px = preg_match( '/(\d+)px\s*,|,\s*(\d+)px/', $width, $cm ) ? (float) ( '' !== ( $cm[1] ?? '' ) ? $cm[1] : ( $cm[2] ?? 0 ) ) : 0.0;
			$doc_w  = 0.0;
			$root   = $el->ownerDocument ? $el->ownerDocument->documentElement : null;
			if ( $root instanceof DOMElement && preg_match( '/^\d+$/', (string) $root->getAttribute( 'data-sc-content-width' ) ) ) { $doc_w = (float) $root->getAttribute( 'data-sc-content-width' ); }
			if ( $cap_px > 0 && $doc_w > 0 && $cap_px < 0.9 * $doc_w ) { $shell = false; $self_center_cap = true; }
		}
		if ( $shell ) { $width = ''; $maxw = ''; }
		// Self-centred: the parent centres its items (grid justify-items / place-items, a flex row justify-content, a flex
		// column align-items) or the panel carries auto side margins.
		$par  = $el->parentNode instanceof DOMElement ? $el->parentNode : null;
		$pcs  = $par ? (string) $par->getAttribute( 'data-sc-cs' ) : '';
		$self_center = (bool) preg_match( '/(?:^|;)\s*margin(?:-left)?:\s*(?:[0-9.]+px\s+)?auto/i', $cs ) || ! empty( $self_center_cap )
			// the computed stamp resolves `margin: 0 auto` to equal px side margins — symmetric non-zero side margins on a capped block are auto
			|| ( ( '' !== $width || '' !== $maxw ) && preg_match( '/(?:^|;)\s*margin:\s*[0-9.]+px\s+([0-9.]+)px(?:\s+[0-9.]+px\s+\1px)?\s*(?:;|$)/i', $cs, $mm ) && (float) $mm[1] > 0 );
		if ( ! $self_center && '' !== $pcs ) {
			$pdisp = self::css_or_decl( $par, 'display' );
			$pji   = self::css_or_decl( $par, 'justify-items' ); $ppi = self::css_or_decl( $par, 'place-items' );
			$pjc   = self::css_or_decl( $par, 'justify-content' ); $pai = self::css_or_decl( $par, 'align-items' );
			$pdir  = self::css_or_decl( $par, 'flex-direction' );
			if ( false !== strpos( $pdisp, 'grid' ) && ( 'center' === $pji || false !== strpos( $ppi, 'center' ) ) ) { $self_center = true; }
			elseif ( false !== strpos( $pdisp, 'flex' ) && ( ( 'column' === $pdir && 'center' === $pai ) || ( 'column' !== $pdir && 'center' === $pjc ) ) ) { $self_center = true; }
		}
		// Content centring INSIDE the panel (grid place-items / a centred flex).
		$disp = self::css_or_decl( $el, 'display' );
		$ch = false; $cv = false;
		if ( false !== strpos( $disp, 'grid' ) ) {
			$pi = self::css_or_decl( $el, 'place-items' ); $ji = self::css_or_decl( $el, 'justify-items' ); $ai = self::css_or_decl( $el, 'align-items' );
			$ch = ( 'center' === $ji || false !== strpos( $pi, 'center' ) ); $cv = ( 'center' === $ai || false !== strpos( $pi, 'center' ) );
		} elseif ( false !== strpos( $disp, 'flex' ) ) {
			$dir = self::css_or_decl( $el, 'flex-direction' ); $jc = self::css_or_decl( $el, 'justify-content' ); $ai = self::css_or_decl( $el, 'align-items' );
			if ( 'column' === $dir ) { $ch = ( 'center' === $ai ); $cv = ( 'center' === $jc ); } else { $ch = ( 'center' === $jc ); $cv = ( 'center' === $ai ); }
		}
		$align = ( 'center' === self::sc_css( $el, 'text-align' ) ) ? 'center' : '';
		if ( 'center' === $align ) {
			foreach ( $blocks as &$bk ) { if ( in_array( $bk['role'] ?? '', array( 'title', 'heading', 'overline', 'subtitle', 'badge', 'text', 'button' ), true ) && empty( $bk['align'] ) ) { $bk['align'] = 'center'; } }
			unset( $bk );
		}
		$m = self::el_margin( $el );
		// The panel's inset = its own padding + that of a SOLE unskinned wrapper child (the flattened '.inner' of a
		// '.shell > .inner' chain, whose padding collect_blocks would otherwise drop with the wrapper).
		$pad  = self::el_padding( $el );
		$kids = self::el_children( $el );
		if ( 1 === count( $kids ) && ! self::read_card_skin( $kids[0] ) && ! self::read_edge_skin( $kids[0] ) ) {
			$ipad = self::el_padding( $kids[0] );
			if ( $ipad ) {
				if ( ! $pad ) { $pad = $ipad; }
				else { foreach ( array( 'base', 'md', 'lg' ) as $tier ) { foreach ( array( 'top', 'right', 'bottom', 'left' ) as $sd ) { $a = $pad[ $tier ][ $sd ] ?? null; $b2 = $ipad[ $tier ][ $sd ] ?? null; if ( null !== $b2 ) { $pad[ $tier ][ $sd ] = (float) $a + (float) $b2; } } } }
			}
		}
		return array(
			't' => 'panel', 'role' => 'panel', 'box' => $skin, 'pad' => $pad,
			'width' => $width, 'maxw' => $maxw, 'aspect' => $aspect, 'align' => $align, 'height' => $height, 'between' => $between,
			'self_center' => $self_center, 'center_h' => $ch, 'center_v' => $cv, 'shell' => $shell,
			'decor' => self::parse_decor_pseudos( (string) $el->getAttribute( 'data-sc-decor-pseudo' ), (string) $el->getAttribute( 'data-sc-keyframes' ) ),
			'mt' => $m['top'], 'mb' => $m['bottom'], 'blocks' => $blocks,
		);
	}

	/** A computed value when the capture stamped it, else the sheet's own declaration (place-items / justify-items are
	 *  not in the captured property set, but decide a panel's centring). */
	private static function css_or_decl( $el, $prop ) {
		$v = trim( (string) self::sc_css( $el, $prop ) );
		return ( '' !== $v && 'normal' !== $v ) ? $v : trim( (string) self::stylesheet_decl( null, $el, $prop ) );
	}

	/** True when any block (recursively: blocks / cols / items) is a verbatim `code` / `html` block. */
	private static function blocks_have_code( array $blocks ) {
		foreach ( $blocks as $b ) {
			if ( ! is_array( $b ) ) { continue; }
			if ( in_array( (string) ( $b['t'] ?? '' ), array( 'code', 'html' ), true ) ) { return true; }
			if ( ! empty( $b['blocks'] ) && is_array( $b['blocks'] ) && self::blocks_have_code( $b['blocks'] ) ) { return true; }
			if ( ! empty( $b['cols'] ) && is_array( $b['cols'] ) ) { foreach ( $b['cols'] as $c ) { if ( isset( $c['html'] ) ) { return true; } if ( ! empty( $c['blocks'] ) && self::blocks_have_code( $c['blocks'] ) ) { return true; } } }
		}
		return false;
	}
	/** True when a heading / title / text block sits anywhere in the tree (the card holds real copy). */
	private static function blocks_have_text( array $blocks ) {
		foreach ( $blocks as $b ) {
			if ( ! is_array( $b ) ) { continue; }
			if ( in_array( (string) ( $b['t'] ?? '' ), array( 'heading', 'text' ), true ) ) { return true; }
			if ( ! empty( $b['blocks'] ) && is_array( $b['blocks'] ) && self::blocks_have_text( $b['blocks'] ) ) { return true; }
		}
		return false;
	}

	private static function is_content_card( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( '' === $cs ) { return false; }
		// OPAQUE fill (a real panel colour, alpha ≥ .8) — never transparent / low-alpha.
		if ( ! preg_match( '/(?<![\w-])background-color:\s*(?:rgb\([^)]*\)|#[0-9a-f]{3,8}|rgba\([^)]*[,\/]\s*(?:0?\.[89]\d*|1)\s*\))/i', $cs ) ) { return false; }
		if ( preg_match( '/(?<![\w-])background-color:\s*(?:transparent|rgba?\([^)]*[,\/]\s*(?:0|0?\.[0-7]\d*)\s*\))/i', $cs ) ) { return false; }
		// ROUNDING ≥ 8px.
		if ( ! preg_match( '/(?<![\w-])border-radius:\s*([0-9.]+)px/', $cs, $rm ) || (float) $rm[1] < 8 ) { return false; }
		// BORDER or SHADOW — a PAINTED one: a `border-4 border-transparent` (a hover-only ring) and an all-zero shadow
		// (`rgba(0, 0, 0, 0) 0px 0px`) are not a skin (a feature card with only a fill + radius fell to the verbatim card path
		// and rendered as a code_block — a fixture from the findings feed).
		$has_border = preg_match( '/(?<![\w-])border-top-width:\s*([1-9])/', $cs ) && ! preg_match( '/(?<![\w-])border-top-color:\s*(?:rgba\([^)]*,\s*0\s*\)|transparent)/i', $cs );
		$has_shadow = preg_match( '/(?<![\w-])box-shadow:\s*(?!none)([^;"]+)/', $cs, $shm ) && ! preg_match( '/^rgba\([^)]*,\s*0\s*\)\s+0px\s+0px(?:\s+0px)*\s*$/', trim( $shm[1] ) );
		if ( ! $has_border && ! $has_shadow ) { return false; }
		// Contains a HEADING (a content card, not a bare decorative box / image tile).
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { if ( $el->getElementsByTagName( $h )->length > 0 ) { return true; } }
		return false;
	}

	/** Run the CONTENT-ROW recognizers on ONE element (not its children): the first match's block(s), or null. */
	private static function claim_element( $el, array $rules ) {
		if ( ! ( $el instanceof DOMElement ) ) { return null; }
		$tag = strtolower( $el->tagName );
		foreach ( self::recognizers() as $r ) {
			// Only the CONTENT-ROW shapes: a stack, a chip / tag row, a counter grid, an icon-text list, a link strip, a text list.
			// The media / collage / card recognizers keep their own cell paths (verbatim or fill) — claiming them here salvaged strays.
			// (+ a CARD GRID: a cell that IS a grid of icon / title / copy cards — a 7-col half holding a 2×2 of console tiles — was
			// otherwise claimed by layout_row and decomposed to heading + text per cell, its icons and box skins lost)
			// (+ the MARQUEE strip, ahead of chip_row / toolbar_row: a sliding nowrap track of short labels is a chip row by shape)
			if ( ! in_array( $r['id'] ?? '', array( 'marquee_strip', 'scroller', 'card_grid', 'layout_row', 'stack', 'chip_row', 'counter_grid', 'icon_text_list', 'inline_links', 'text_list', 'newsletter', 'contact_form', 'avatar_group' ), true ) ) { continue; } // (+ an avatar stack as a row cell)
			if ( ! call_user_func( $r['match'], $el, $tag, $rules ) ) { continue; }
			$out = call_user_func( $r['build'], $el, $tag, $rules );
			return is_array( $out ) ? $out : null;
		}
		return null;
	}

	private static function collect_blocks( $node, array &$blocks, array $rules ) {
		$recognizers = self::recognizers();
		foreach ( $node->childNodes as $child ) {
			if ( XML_ELEMENT_NODE !== $child->nodeType ) { continue; }
			$tag     = strtolower( $child->tagName );
			// SKIP a RESPONSIVE-HIDDEN twin — a child that is `display:none` at the capture (desktop) viewport AND
			// carries a Tailwind breakpoint-hide class (`sm:hidden` / `md:hidden` / `lg:hidden` …). It's the MOBILE
			// version of a block whose DESKTOP twin lives elsewhere in the DOM (the burger source's stacked hours LIST vs the
			// desktop hours GRID, a mobile reel vs the desktop marquee) — decomposing it DUPLICATES the content.
			// JS-revealed panels (tabs/accordions) are un-hidden by the capture before this, so only genuine
			// responsive duplicates are dropped.
			if ( $child instanceof DOMElement ) {
				$cc = ' ' . strtolower( self::cls( $child ) ) . ' ';
				if ( preg_match( '/\b(?:sm|md|lg|xl|2xl|max-[a-z]+):hidden\b/', $cc )
					&& 'none' === strtolower( (string) self::sc_css( $child, 'display' ) ) ) { continue; }
			}
			$claimed = false;
			// PHONE PASS: the element is display:none at 390px (a decorative chip the source hides on phones) → every block it
			// produces is hidden on phones (native Responsive Hide: hide-xs + hide-sm). The desktop stamp keeps it visible.
			$hide_sm = ( $child instanceof DOMElement ) && (bool) preg_match( '/(?:^|;)\s*display:\s*none\b/i', (string) $child->getAttribute( 'data-sc-cs-sm' ) );
			$before_hide = count( $blocks );
			foreach ( $recognizers as $r ) {
				if ( ! call_user_func( $r['match'], $child, $tag, $rules ) ) { continue; }
				$out = call_user_func( $r['build'], $child, $tag, $rules );
				// a recognizer that MATCHED but built NOTHING (a row whose cells all fell away) has not claimed the element: the next
				// recognizer — or the descent into its children — gets it, instead of the subtree vanishing (an accordion-style band of
				// five `h3 + arrow` rows disappeared whole)
				if ( ! is_array( $out ) || ( ! isset( $out['t'] ) && ! count( $out ) ) ) { continue; }
				$ai  = self::anim_intent( $child ); // source reveal/scroll-animation intent (AOS / animate.css / hooks)
				$rvl = self::reveal_of( $child );   // a measured CSS-class reveal (capture data-sc-reveal) → Scroll Motion
				$lpa = self::loop_anim_of( $child ); // the element's own running class animation (a pulse, a drift) → the block's CSS
				$tfx = self::text_split_intent( $child ); // word/line/char split-reveal → Text Effects split_reveal
				// the element's OWN content cap (a `max-w-5xl mx-auto` grid, a capped accordion list) → the widget block(s) it
				// produced (capW / capCenter): the row / FAQ otherwise spanned the whole container — the recurring
				// "section container width" report
				$ecap = self::wrapper_maxw( $child );
				if ( '' !== $ecap && is_array( $out ) ) { $ecc = self::wrapper_centered( $child ); if ( isset( $out['t'] ) ) { self::stamp_cap( $out, $ecap, $ecc ); } else { foreach ( $out as &$ob ) { if ( is_array( $ob ) ) { self::stamp_cap( $ob, $ecap, $ecc ); } } unset( $ob ); } }
				if ( is_array( $out ) ) {
					if ( isset( $out['t'] ) ) { if ( '' !== $ai && empty( $out['anim'] ) ) { $out['anim'] = $ai; } if ( $rvl && empty( $out['reveal'] ) ) { $out['reveal'] = $rvl; } if ( $lpa && empty( $out['loopAnim'] ) ) { $out['loopAnim'] = $lpa; } if ( '' !== $tfx && empty( $out['text_fx'] ) ) { $out['text_fx'] = $tfx; } $blocks[] = $out; } // one block
					else { foreach ( $out as $blk ) { if ( is_array( $blk ) && isset( $blk['t'] ) ) { if ( '' !== $ai && empty( $blk['anim'] ) ) { $blk['anim'] = $ai; } if ( $rvl && empty( $blk['reveal'] ) ) { $blk['reveal'] = $rvl; } if ( '' !== $tfx && empty( $blk['text_fx'] ) ) { $blk['text_fx'] = $tfx; } $blocks[] = $blk; } } } // a list
				}
				$claimed = true;
				break;
			}
			if ( ! $claimed && 'svg' === $tag ) {
				// An unclaimed <svg> is an icon / decoration (a real drawing is claimed by svg_draw above).
				// Don't walk its internals — else its <title>/<path>/<g> get salvaged as stray text. Treat it
				// as one leaf so the safety net records it (decorative) and the VISIBLE label on its parent
				// span is what gets rescued, not the svg's accessibility title.
				self::salvage_dropped( $child, $tag, $blocks );
				continue;
			}
			// STYLED CONTENT CARD — an opaque rounded panel (border/shadow) wrapping a heading + content (the
			// the burger source location card `rounded-2xl border bg-background shadow`). Decomposing its children flat
			// drops the white panel, so the content reads faintly on the section band. Emit it as a `code` block
			// → the mapper's structural mirror rebuilds it as a NESTED FLEXBOX carrying the card's box skin (an
			// editable panel). Tightly gated (opaque fill + rounding + border/shadow + a heading) so it fires
			// only on a genuine card, never a plain layout wrapper or an image tile.
			if ( ! $claimed && self::is_content_card( $child ) ) {
				// NATIVE FIRST: when the card's content decomposes cleanly (a heading / text / icon tile / button — no block that
				// would itself fall to code), emit it as a PANEL (a flexbox wearing the card's Box Preset, editable blocks inside)
				// instead of the verbatim mirror — a single feature card rendered as a code_block (a fixture from the feed).
				$pb = self::panel_build( $child, $tag, $rules );
				if ( is_array( $pb ) && ! empty( $pb['blocks'] ) && ! self::blocks_have_code( $pb['blocks'] ) && self::blocks_have_text( $pb['blocks'] ) ) { $blocks[] = $pb; continue; }
				$doc  = $child->ownerDocument;
				// If the card sits in a bare MAX-WIDTH cap wrapper (`max-w-3xl mx-auto`), emit THAT wrapper so the
				// card keeps its measure + centering (else it fills the section band — the source card is capped
				// narrower than the section). Only when the wrapper's sole element child is the card.
				$target = $child;
				$par    = $child->parentNode;
				if ( $par instanceof DOMElement ) {
					$pc = ' ' . strtolower( self::cls( $par ) ) . ' ';
					if ( strpos( $pc, ' max-w-' ) !== false && strpos( $pc, ' mx-auto ' ) !== false ) {
						$pec = 0; foreach ( $par->childNodes as $pn ) { if ( XML_ELEMENT_NODE === $pn->nodeType ) { $pec++; } }
						if ( 1 === $pec ) { $target = $par; }
					}
				}
				$chtml = $doc ? trim( (string) $doc->saveHTML( $target ) ) : '';
				// Re-assert each heading's OWN computed colour inline (!important) BEFORE stripping data-sc-cs, so a
				// `text-primary` red business name survives the section's white heading-colour rule once it sits on
				// the white card (else it renders white-on-white and vanishes).
				$chtml = self::inject_verbatim_heading_colors( $chtml );
				$chtml = self::strip_cs( $chtml );
				// Keep the card VERBATIM inside the `.sc-tw` Tailwind reproducer (like the food grid / reels), so
				// ALL its classes survive — spacing, alignment, the pill button, max-widths, image aspect — instead
				// of the structural mirror decomposing it and dropping most styling. `verbatim` tells the mapper's
				// code builder to skip the nested-flexbox mirror and emit the faithful code block.
				if ( '' !== $chtml ) { $blocks[] = array( 't' => 'code', 'role' => 'code', 'verbatim' => true, 'html' => '<div class="sc-tw">' . $chtml . '</div>' ); $claimed = true; }
			}
			// DECORATIVE RULE / UNDERLINE BAR — a small EMPTY div with a fill + a thin height (a heading's
			// `w-24 h-1 bg-primary-foreground mx-auto` underline). collect_blocks drops empty elements, so the
			// bar vanished. Emit it verbatim (`.sc-tw`) so the exact width/height/colour/centring survive.
			// …and a ROW of such bars (`<div class="flex gap-4"><div class="h-1 w-1/2 …"></div><div class="h-1 w-1/4 …"></div></div>`,
			// a spectrum meter under a title) is ONE verbatim block — walked apart, its bars stacked as two blocks, then each
			// fell to the mapper's content-less drop (a real-site audit). The mapper keeps a bar block that paints.
			if ( ! $claimed && self::is_decorative_bar_row( $child ) ) {
				$doc   = $child->ownerDocument;
				$bhtml = $doc ? preg_replace( '/>\s+</', '><', self::strip_cs( trim( (string) $doc->saveHTML( $child ) ) ) ) : ''; // (no inter-tag whitespace: wpautop would seed <br>s between the bars)
				if ( '' !== $bhtml ) { $blocks[] = array( 't' => 'code', 'role' => 'code', 'verbatim' => true, 'decorBar' => true, 'html' => '<div class="sc-tw">' . $bhtml . '</div>' ); $claimed = true; }
			}
			if ( ! $claimed && self::is_decorative_bar( $child ) ) {
				$doc   = $child->ownerDocument;
				$bhtml = $doc ? preg_replace( '/>\s+</', '><', self::strip_cs( trim( (string) $doc->saveHTML( $child ) ) ) ) : ''; // (no inter-tag whitespace: wpautop would seed <br>s between the bars)
				if ( '' !== $bhtml ) { $blocks[] = array( 't' => 'code', 'role' => 'code', 'verbatim' => true, 'decorBar' => true, 'html' => '<div class="sc-tw">' . $bhtml . '</div>' ); $claimed = true; }
			}
			if ( $hide_sm && count( $blocks ) > $before_hide ) { for ( $hi = $before_hide, $hn = count( $blocks ); $hi < $hn; $hi++ ) { if ( is_array( $blocks[ $hi ] ) ) { $blocks[ $hi ]['hideSm'] = true; } } }
			if ( ! $claimed ) {
				$before = count( $blocks );
				self::collect_blocks( $child, $blocks, $rules );
				if ( $hide_sm && count( $blocks ) > $before ) { for ( $hi = $before, $hn = count( $blocks ); $hi < $hn; $hi++ ) { if ( is_array( $blocks[ $hi ] ) ) { $blocks[ $hi ]['hideSm'] = true; } } }
				// A plain grouping wrapper (e.g. <div class="text-center mb-16">) is flattened; carry its OWN
				// vertical margin onto the boundary blocks it produced so the group's spacing survives.
				if ( count( $blocks ) > $before ) {
					$wm = self::el_margin( $child );
					// …plus its own vertical PADDING (a `mt-auto pt-24 pb-12` strip wrapper): the space the source keeps above / below
					// the group is margin + padding of the flattened wrapper. The DESKTOP tier (lg when a phone diff moved desktop
					// there, else base). Horizontal padding already rides el_inset_x. JS: the decompose dive's wmt / wmb.
					$wp = self::el_padding( $child );
					if ( is_array( $wp ) ) { $wpd = ( isset( $wp['lg']['top'] ) && null !== $wp['lg']['top'] ) ? $wp['lg'] : $wp['base']; $wm['top'] += (float) ( $wpd['top'] ?? 0 ); $wm['bottom'] += (float) ( $wpd['bottom'] ?? 0 ); }
					if ( $wm['bottom'] > 0 ) { $li = count( $blocks ) - 1; $blocks[ $li ]['mbAdd'] = max( (float) ( isset( $blocks[ $li ]['mbAdd'] ) ? $blocks[ $li ]['mbAdd'] : 0 ), $wm['bottom'] ); }
					// an `mt-auto` wrapper (a card's bottom group under a flex column) pushes itself to the END of its column: carry
					// the AUTO margin, not its computed px (166px on one screen, another elsewhere — a real-site audit). JS: mtAuto.
					if ( preg_match( '/(?:^|\s)mt-auto(?:\s|$)/', ' ' . self::cls( $child ) . ' ' ) ) { $blocks[ $before ]['mtAuto'] = true; $mtap = is_array( $wp ) ? (float) ( $wpd['top'] ?? 0 ) : 0.0; if ( $mtap > 0 ) { $blocks[ $before ]['mtAutoPad'] = $mtap; } } // (its own padding-top rides along)
					elseif ( $wm['top'] > 0 ) { $blocks[ $before ]['mtAdd'] = max( (float) ( isset( $blocks[ $before ]['mtAdd'] ) ? $blocks[ $before ]['mtAdd'] : 0 ), $wm['top'] ); }
					// …and its HORIZONTAL inset (a plain-CSS `.shell{margin:0 24px}` / `px-6` band wrapper between the section and
					// its content) onto EVERY block it produced. The section shortcode renders a flexbox child directly
					// (no .fw-container), so a wrapper's side margin/padding is the ONLY thing keeping the band off the
					// viewport edge — dropping it let the converted bands run edge-to-edge while the source sat 24px in.
					// Nested wrappers ADD up (each is a real inset); centred caps (mx-auto / max-w-*) are excluded —
					// their measure rides maxWidth / content_width, not a margin.
					$wx = self::el_inset_x( $child );
					if ( $wx['left'] > 0 || $wx['right'] > 0 ) {
						// …and the same inset at 390 / 820 (the tier stamps), so the band's inset follows the source's tiers.
						$wsm = self::el_inset_x_tier( $child, 'data-sc-cs-sm', $wx ); $wmd = self::el_inset_x_tier( $child, 'data-sc-cs-md', $wx );
						for ( $bi = $before, $bn = count( $blocks ); $bi < $bn; $bi++ ) {
							$cur = ( isset( $blocks[ $bi ]['mxAdd'] ) && is_array( $blocks[ $bi ]['mxAdd'] ) ) ? $blocks[ $bi ]['mxAdd'] : array( 'l' => 0.0, 'r' => 0.0, 'lSm' => 0.0, 'rSm' => 0.0, 'lMd' => 0.0, 'rMd' => 0.0 );
							$blocks[ $bi ]['mxAdd'] = array( 'l' => (float) $cur['l'] + $wx['left'], 'r' => (float) $cur['r'] + $wx['right'], 'lSm' => (float) ( $cur['lSm'] ?? $cur['l'] ) + $wsm['left'], 'rSm' => (float) ( $cur['rSm'] ?? $cur['r'] ) + $wsm['right'], 'lMd' => (float) ( $cur['lMd'] ?? $cur['l'] ) + $wmd['left'], 'rMd' => (float) ( $cur['rMd'] ?? $cur['r'] ) + $wmd['right'] );
						}
					}
					// Heading-group SUBTITLE fold: a wrapper that produced ONLY a heading (title/heading) plus
					// overline/text — and NO button, media, or columns — is a tight heading group (source
					// `<div class="heading"><span>overline</span><h1>…</h1><p>…</p></div>`). Its first paragraph
					// after the title is the heading's SUBTITLE, so retag it 'subtitle' — the mapper then folds
					// it INTO the special_heading instead of emitting a stray text_block. Mirrors the hand-built
					// demo (hero + features fold the subtitle into the special_heading; a CTA whose descriptive
					// text sits in the same wrapper as its button stays a separate text_block — button present →
					// not a pure heading group → no fold).
					self::fold_group_subtitle( $blocks, $before );
					// #1 HEADING WRAPPER-INHERITANCE — carry the wrapper's OWN horizontal alignment onto the
					// blocks it produced. `text-align` is an INHERITED property, so `<div class="text-center
					// max-w-2xl mx-auto">` centers every descendant; but the heading/text recognizers only read
					// the h2/p's OWN classes, so a wrapper-level `text-center` was dropped (the heading rendered
					// left-aligned). Per-wrapper twin of the section-centering pass: stamp an explicit
					// center/right onto the heading-family + text blocks that don't already carry their own
					// align (left = the inherited default → left as inherit). The wrapper's constrained width
					// (`max-w-* mx-auto`) rides onto the title/heading block as wrapMaxW so a centered intro
					// keeps its measure.
					$wal = self::wrapper_align( $child );
					$wmw = self::wrapper_maxw( $child );
					if ( '' !== $wal || '' !== $wmw ) {
						for ( $wi = $before, $wt = count( $blocks ); $wi < $wt; $wi++ ) {
							$wr = $blocks[ $wi ]['role'] ?? '';
							if ( in_array( $wr, array( 'title', 'heading', 'overline', 'subtitle', 'badge', 'text' ), true ) ) {
								if ( '' !== $wal && empty( $blocks[ $wi ]['align'] ) ) { $blocks[ $wi ]['align'] = $wal; }
								if ( '' !== $wmw && in_array( $wr, array( 'title', 'heading' ), true ) && empty( $blocks[ $wi ]['wrapMaxW'] ) ) {
									$blocks[ $wi ]['wrapMaxW'] = $wmw;
								}
							}
							// …and onto the WIDGET blocks under it (a FAQ list, a card grid, a feature list inside a `max-w-3xl
							// mx-auto` wrapper): the cap is the wrapper's, every child lays out inside it
							if ( '' !== $wmw ) { self::stamp_cap( $blocks[ $wi ], $wmw, self::wrapper_centered( $child ) ); }
						}
					}
					// A reveal-animated WRAPPER (`<div data-aos="fade-up">…`) that flattened into leaf blocks →
					// carry its animation intent onto the produced blocks that don't already carry their own.
					$wai = self::anim_intent( $child );
					if ( '' !== $wai ) { for ( $wi = $before, $wt = count( $blocks ); $wi < $wt; $wi++ ) { if ( empty( $blocks[ $wi ]['anim'] ) ) { $blocks[ $wi ]['anim'] = $wai; } } }
				} else {
					// SAFETY NET — this unclaimed node's whole subtree produced NO blocks, so it would be
					// SILENTLY DROPPED here (the "elements went missing" class of bug). Record the miss for the
					// drop report, and rescue any real content it carries as an editable block so nothing
					// user-visible vanishes. Purely-decorative nodes (no text, no media) are recorded but NOT
					// emitted, so blur blobs / spacers / empty overlays still fall away.
					$before_salv = count( $blocks );
					self::salvage_dropped( $child, $tag, $blocks );
					if ( $hide_sm && count( $blocks ) > $before_salv ) { for ( $hi = $before_salv, $hn = count( $blocks ); $hi < $hn; $hi++ ) { if ( is_array( $blocks[ $hi ] ) ) { $blocks[ $hi ]['hideSm'] = true; } } } // PHONE PASS: a salvaged leaf (a lone chip) is hidden on phones too
				}
			}
		}
	}

	/**
	 * Safety net for an unclaimed content node whose subtree produced nothing (called from collect_blocks).
	 * RESCUE any real content it carries as an editable block — a content <img> → media_image, substantial
	 * visible text → text_block — so nothing user-visible is silently dropped; and RECORD the miss in the
	 * drop log (always, incl. purely-decorative nodes) so the coverage report can rank the next detector to
	 * build. Decorative nodes (no text, no media — blur blobs, spacers, empty overlays) are recorded but NOT
	 * emitted. Conservative on text (needs a real word) so the output isn't polluted with stray glyphs.
	 *
	 * @param DOMNode $child
	 * @param string  $tag
	 * @param array   $blocks by-ref
	 */
	/** The FIRST element child of a horizontal flex row whose other children carry a heading — a numbered row's marker slot. */
	private static function is_row_marker( $el ) {
		$p = $el->parentNode; if ( ! ( $p instanceof DOMElement ) ) { return false; }
		$pcs = (string) $p->getAttribute( 'data-sc-cs' ); $pcl = ' ' . self::cls( $p ) . ' ';
		$row = ( preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $pcs ) && ! preg_match( '/flex-direction:\s*column/i', $pcs ) ) || ( false !== strpos( $pcl, ' flex ' ) && false === strpos( $pcl, ' flex-col ' ) );
		if ( ! $row ) { return false; }
		$kids = self::el_children( $p ); if ( count( $kids ) < 2 || $kids[0] !== $el ) { return false; }
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { if ( $p->getElementsByTagName( $h )->length > 0 ) { return true; } }
		return false;
	}

	private static function salvage_dropped( $child, $tag, array &$blocks ) {
		if ( ! ( $child instanceof DOMElement ) ) { return; }

		// A real content image anywhere in the subtree (skip data-URIs + tracking pixels).
		$img = null;
		foreach ( $child->getElementsByTagName( 'img' ) as $im ) {
			$src = trim( (string) $im->getAttribute( 'src' ) );
			if ( $src === '' ) { $src = trim( (string) $im->getAttribute( 'data-src' ) ); }
			if ( $src !== '' && stripos( $src, 'data:' ) !== 0 ) { $img = $im; break; }
		}

		// The node's OWN DIRECT text (immediate text-node children only) — NOT flattened descendant text.
		// This is the key to not double-capturing: a container like `<div class="grid"><div>A</div>…` has
		// no direct text (its text lives in children, which the walker already visited), so we don't emit a
		// concatenated "ABC" blob for it; but a genuine leaf like `<span><svg/>Unity</span>` still yields
		// its direct label "Unity". "Real" = a 2+ letter word (skips lone glyphs ×/→/• and digit spacers).
		$direct = '';
		foreach ( $child->childNodes as $cn ) {
			if ( XML_TEXT_NODE === $cn->nodeType ) { $direct .= $cn->nodeValue; }
		}
		$txt     = trim( preg_replace( '/\s+/', ' ', $direct ) );
		$hasWord = (bool) preg_match( '/[\p{L}]{2,}/u', $txt )
			|| ( (bool) preg_match( '/\d/', $txt ) && mb_strlen( $txt ) <= 24 && (bool) preg_match( '/[$€£¥%°+×]|\d\s*\p{L}{1,3}$/u', $txt ) ) // a priced / unit-bearing value ("$2,450", "94%", "20°C", "500+") — never a bare number / index
			// …except a GHOST NUMERAL: a bare index ("01", "02") set DISPLAY-SIZE (≥ 40px) is a design element (a "how it works" step
			// number at 96px / 8 % ink) — it was dropped as a bare number (a fixture from the findings feed)
			|| ( (bool) preg_match( '/^\d{1,3}$/', $txt ) && preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $child->getAttribute( 'data-sc-cs' ), $nfs ) && (float) $nfs[1] >= 40 )
			// …or a ROW MARKER: a short ordinal ("01", "02.", "①") that LEADS a flex row beside a heading (a benefits / steps list's
			// `span.01 + div(h3 + p)`) is the row's number, not decoration — every row lost its number (a fixture from the feed)
			|| ( (bool) preg_match( '/^(?:\d{1,3}\.?|[①-⑳])$/u', $txt ) && self::is_row_marker( $child ) );

		$kind = 'decorative';
		if ( $img ) {
			$blocks[] = array( 't' => 'image', 'role' => 'image', 'html' => self::img_html( $img ) );
			$kind = 'salvaged-image';
			if ( $hasWord ) { // a captioned image → keep the caption as a text block too
				$blocks[] = array( 't' => 'text', 'role' => 'text', 'cls' => self::cls( $child ), 'text' => $txt, 'html' => '<p>' . esc_html( $txt ) . '</p>' );
			}
		} elseif ( $hasWord ) {
			$blocks[] = array( 't' => 'text', 'role' => 'text', 'cls' => self::cls( $child ), 'cs' => (string) $child->getAttribute( 'data-sc-cs' ), 'text' => $txt, 'html' => self::leaf_text_html( $child, $txt ), 'linkCs' => self::leaf_link_cs( $child ) );
			$kind = 'salvaged-text';
		}

		if ( count( self::$drop_log ) < 800 ) {
			self::$drop_log[] = array(
				'tag'   => $tag,
				'class' => mb_substr( (string) self::cls( $child ), 0, 160 ),
				'kind'  => $kind,
				'text'  => mb_substr( $txt, 0, 80 ),
			);
		}
	}

	/**
	 * Summarize the drop log into a coverage report ranked by frequency: totals split by kind (how much
	 * content the safety net had to rescue vs. decorative noise) and the top recurring dropped patterns
	 * (tag + class signature + a text sample) so the next detector to build is obvious and data-driven.
	 *
	 * @return array
	 */
	private static function build_drop_report() {
		$log      = self::$drop_log;
		$by_kind  = array();
		$patterns = array();
		foreach ( $log as $d ) {
			$k = isset( $d['kind'] ) ? $d['kind'] : 'decorative';
			$by_kind[ $k ] = ( isset( $by_kind[ $k ] ) ? $by_kind[ $k ] : 0 ) + 1;
			// Signature = tag + first few class tokens, so near-identical drops (e.g. every brand <span> in
			// a logo strip) collapse into one ranked pattern.
			$cls  = preg_split( '/\s+/', (string) ( isset( $d['class'] ) ? $d['class'] : '' ) );
			$sig  = $d['tag'] . '|' . implode( ' ', array_slice( array_filter( $cls ), 0, 4 ) );
			if ( ! isset( $patterns[ $sig ] ) ) {
				$patterns[ $sig ] = array( 'count' => 0, 'tag' => $d['tag'], 'class' => $d['class'], 'kind' => $k, 'sample' => $d['text'] );
			}
			$patterns[ $sig ]['count']++;
		}
		uasort( $patterns, function ( $a, $b ) { return $b['count'] - $a['count']; } );
		return array(
			'total'        => count( $log ),
			'rescued'      => ( isset( $by_kind['salvaged-text'] ) ? $by_kind['salvaged-text'] : 0 ) + ( isset( $by_kind['salvaged-image'] ) ? $by_kind['salvaged-image'] : 0 ),
			'decorative'   => isset( $by_kind['decorative'] ) ? $by_kind['decorative'] : 0,
			'by_kind'      => $by_kind,
			'top_patterns' => array_slice( array_values( $patterns ), 0, 40 ),
			'items'        => array_slice( $log, 0, 200 ),
		);
	}

	/**
	 * CLASS-COVERAGE audit — is a source class SIGNIFICANT (carries a visual look), vs INERT (layout/structure
	 * the builder owns, motion, or a non-visual utility)? Used to filter the raw dropped-class collector down
	 * to the classes that a missing translation would actually make the page LOOK wrong — so a genuine drop
	 * (like `h-screen` / `max-w-sm`) surfaces, while `flex` / `relative` / `group` / `transition` don't.
	 */
	private static function class_is_significant( $cls ) {
		$base = preg_replace( '/^(?:[a-z0-9.]+:)+/', '', trim( (string) $cls ) ); // strip md:/hover:/group-hover: … prefixes
		if ( $base === '' ) { return false; }
		// GLOBALLY handled (would be a false positive per-element): the font FAMILY comes from the Typography
		// preset, not a per-element option; text-wrap niceties carry no layout.
		if ( preg_match( '/^font-(?:sans|serif|mono|display)$/', $base ) || in_array( $base, array( 'text-balance', 'text-pretty', 'text-wrap', 'text-nowrap' ), true ) ) { return false; }
		// INERT — structure the builder owns, motion, stacking, or non-visual utilities.
		if ( preg_match( '/^(?:flex|grid|block|inline|inline-block|inline-flex|contents|hidden|relative|absolute|fixed|sticky|static|container|group|isolate|transform|antialiased|subpixel-antialiased|select-\w+|pointer-events-\w+|cursor-\w+|sr-only|not-sr-only)$/', $base ) ) { return false; }
		if ( preg_match( '/^(?:flex-|grid-|order-|col-|row-|auto-cols-|auto-rows-|gap-|justify-|items-|content-|self-|place-|space-[xy]-|divide-|z-|duration-|delay-|ease-|animate-|transition|origin-|scale-|rotate-|translate-|skew-|will-|backdrop-(?!blur)|snap-|scroll-|touch-|overflow-|overscroll-|float-|clear-|box-|table-|list-|whitespace-|break-|hyphens-|align-|basis-|grow|shrink)/', $base ) ) { return false; }
		// SIGNIFICANT — a measure / spacing / typography / decoration / viewport-height look.
		if ( preg_match( '/^-?(?:max-w-|min-w-|max-h-|min-h-|h-screen|h-\[|leading-|tracking-|text-|font-|rounded|shadow|drop-shadow|border(?![-\s]?$)|border-|bg-|from-|via-|to-|bg-gradient|opacity-|aspect-|object-|ring|outline|decoration-|underline|line-through|no-underline|uppercase|lowercase|capitalize|normal-case|italic|not-italic|blur|brightness|contrast|grayscale|invert|saturate|sepia|hue-rotate|filter|backdrop-blur|m[trblxye]?-|p[trblxye]?-)/', $base ) ) { return true; }
		if ( strpos( $base, '[' ) !== false ) { return true; } // an arbitrary value (`w-[400px]`, `text-[#abc]`) usually carries a look
		return false;
	}

	/**
	 * CLASS-COVERAGE REPORT (the "final checking pass") → class-coverage.json. Aggregates the per-element
	 * drop collector (FW_Site_Converter_Mapper::$conv_debug — source classes that became NO native option
	 * NOR scoped CSS), keeps only the SIGNIFICANT ones (class_is_significant), and ranks them by frequency —
	 * so each conversion tells you EXACTLY which look-carrying classes are still being dropped and how often,
	 * instead of finding gaps like `h-screen` by eye. Each entry is a candidate for a new class→value rule.
	 */
	private static function build_class_coverage_report() {
		$recs = ( class_exists( 'FW_Site_Converter_Mapper' ) && isset( FW_Site_Converter_Mapper::$conv_debug ) && is_array( FW_Site_Converter_Mapper::$conv_debug ) ) ? FW_Site_Converter_Mapper::$conv_debug : array();
		$agg = array(); $elements = 0; $flagged = 0;
		foreach ( $recs as $r ) {
			if ( ! is_array( $r ) ) { continue; }
			$elements++;
			$dropped = ( isset( $r['dropped'] ) && is_array( $r['dropped'] ) ) ? $r['dropped'] : array();
			$sample  = substr( (string) ( $r['src_cls'] ?? '' ), 0, 90 );
			$hit = false;
			foreach ( $dropped as $c ) {
				if ( ! self::class_is_significant( $c ) ) { continue; }
				$hit = true;
				if ( ! isset( $agg[ $c ] ) ) { $agg[ $c ] = array( 'class' => $c, 'count' => 0, 'sample_element_classes' => $sample ); }
				$agg[ $c ]['count']++;
			}
			if ( $hit ) { $flagged++; }
		}
		uasort( $agg, function ( $a, $b ) { return $b['count'] - $a['count']; } );
		return array(
			'schema'                      => 'unysonplus-class-coverage/1',
			'elements_audited'            => $elements,
			'elements_with_untranslated'  => $flagged,
			'untranslated_significant'    => array_slice( array_values( $agg ), 0, 60 ),
			'note'                        => 'Significant (look-carrying) SOURCE classes that became NO native option and NO scoped CSS — ranked by how many elements dropped each. Each is a candidate for a new deterministic class→value translation rule (fix the rule in BOTH the PHP + JS paths, then re-prove). Coverage spans elements that pass through the class-drop collector (headings / text / cards); whole-element structural drops live in conversion-drops.json.',
		);
	}

	/**
	 * Fold a tight heading group's first paragraph into the heading SUBTITLE. Given the run of blocks a
	 * single wrapper just produced (indices $before..end of $blocks), if that run is a PURE heading group
	 * — exactly one title/heading block, the rest only overline/subtitle/text, and NO button / image /
	 * video / columns / card — retag the first `text` block AFTER the title as role 'subtitle'. The mapper
	 * merges overline+title+subtitle into ONE special_heading, so the subtitle stops rendering as a
	 * separate text_block. No-op when the run mixes in interactive/media/grid content (not a heading group).
	 *
	 * @param array $blocks  by-ref flat block list
	 * @param int   $before  index of the first block this wrapper produced
	 */
	private static function fold_group_subtitle( array &$blocks, $before ) {
		$total = count( $blocks );
		$added = $total - $before;
		if ( $added < 2 ) { return; }
		$title_at = -1; $n_titles = 0;
		for ( $i = $before; $i < $total; $i++ ) {
			$role = isset( $blocks[ $i ]['role'] ) ? (string) $blocks[ $i ]['role'] : '';
			$t    = isset( $blocks[ $i ]['t'] ) ? (string) $blocks[ $i ]['t'] : '';
			if ( 'title' === $role || 'heading' === $role ) { $n_titles++; if ( $title_at < 0 ) { $title_at = $i; } }
			elseif ( 'overline' === $role || 'subtitle' === $role || 'badge' === $role ) { continue; } // heading parts (incl. eyebrow pill) — allowed
			elseif ( 'text' === $t || 'pill' === $t ) { continue; }               // a paragraph / eyebrow pill — allowed
			else { return; }                                                      // button / image / columns / card → not a pure heading group
		}
		if ( 1 !== $n_titles || $title_at < 0 ) { return; }
		for ( $j = $title_at + 1; $j < $total; $j++ ) {
			if ( 'text' === ( isset( $blocks[ $j ]['t'] ) ? $blocks[ $j ]['t'] : '' )
				&& 'subtitle' !== ( isset( $blocks[ $j ]['role'] ) ? $blocks[ $j ]['role'] : '' ) ) {
				// Never fold a LINK into the heading's subtitle — a "View All →" style CTA link beside a
				// section heading (`flex justify-between`) is a button, NOT descriptive subtitle copy. Folding
				// it produced a stray empty-title special_heading (its subtitle = the link text) alongside the
				// real link. Only a plain paragraph becomes the subtitle.
				$bh = (string) ( $blocks[ $j ]['html'] ?? $blocks[ $j ]['text'] ?? '' );
				if ( preg_match( '/^\s*<a\b/i', $bh ) || ! empty( $blocks[ $j ]['href'] ) ) { continue; }
				// Nor a paragraph that is ALSO a box (a glass callout: fill / border / shadow) — a subtitle can't carry a box,
				// so it stays its own text block wearing a Box Preset (the mapper's 'text' builder).
				if ( class_exists( 'FW_Site_Converter_Mapper' ) && FW_Site_Converter_Mapper::text_is_box( (string) ( $blocks[ $j ]['cs'] ?? '' ) ) ) { continue; }
				$blocks[ $j ]['role'] = 'subtitle';
				return;
			}
		}
	}

	/** ≥2 grid children that read as PRODUCT cards (an image PLUS a decimal price, a WooCommerce price element,
	 *  a `.product` class, or an add-to-cart control). Used to route a product grid to the [wc_products] path
	 *  when "Map to WooCommerce" is on. */
	private static function grid_is_product_grid( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$n = 0;
		foreach ( self::el_children( $el ) as $c ) {
			if ( ! ( $c instanceof DOMElement ) ) { continue; }
			if ( $c->getElementsByTagName( 'img' )->length === 0 ) { continue; }
			$ccls  = ' ' . strtolower( self::cls( $c ) ) . ' ';
			$inner = $c->ownerDocument ? (string) $c->ownerDocument->saveHTML( $c ) : '';
			$has_price = (bool) preg_match( '/(?:\$|\x{00A3}|\x{20AC})\s?\d+[.,]\d{2}|woocommerce-price-amount/iu', $inner );
			$is_prod   = ( strpos( $ccls, ' product ' ) !== false || stripos( $inner, 'add_to_cart' ) !== false || stripos( $inner, 'add-to-cart' ) !== false );
			if ( $has_price || $is_prod ) { $n++; }
		}
		return $n >= 2;
	}

	/** Is this element a grid whose children are cards (→ a columns row)? */
	private static function cell_has_display_heading( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return false; }
		if ( $cell->getElementsByTagName( 'h1' )->length > 0 ) { return true; }
		foreach ( array( 'h1', 'h2', 'h3' ) as $h ) {
			foreach ( $cell->getElementsByTagName( $h ) as $hd ) {
				if ( preg_match( '/(?:^|\s)(?:sm:|md:|lg:|xl:|2xl:)?text-(?:4xl|5xl|6xl|7xl|8xl|9xl)(?:\s|$)/', self::cls( $hd ) ) ) { return true; }
				if ( 'h3' !== $h && preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $hd->getAttribute( 'data-sc-cs' ), $fm ) && (float) $fm[1] >= 36 ) { return true; } // measured, not named: a 36px+ h1 / h2 is a display heading whatever its classes (a tile's big h3 stat is not)
			}
		}
		return false;
	}

	private static function is_card_grid( $el ) {
		$cls = self::cls( $el );
		// A hand-authored (non-Tailwind) source declares its grid via COMPUTED style, not a `grid`/`flex`
		// class — e.g. `.chapters{display:grid}`. Consult data-sc-cs `display:grid` too, so a semantic-class
		// grid (`.chapters`, `.features`) isn't bailed on here and flattened into a vertical stack.
		if ( strpos( $cls, 'grid' ) === false && strpos( $cls, 'flex' ) === false && self::sc_css( $el, 'display' ) !== 'grid' ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		// A grid of CAPTION TILES (a photo + an absolute caption each) is not a card grid: its cells are the image box's overlay
		// family (caption_tile_block via the image_overlay recognizer, cell by cell in the layout row) — as cards they became
		// stacked image boxes with the caption UNDER the photo (a fixture from the feed)
		$n_ct = 0; foreach ( $kids as $k ) { if ( self::caption_tile_block( $k ) ) { $n_ct++; } }
		if ( $n_ct >= (int) ceil( count( $kids ) / 2 ) ) { return false; }
		// …nor a grid of cards whose PHOTO carries a floating BADGE (an event card's two-line date chip pinned over the image): the
		// image box has no layer for it — the chip was dropped; the cells decompose (photo + pinned badge, then the body leaves)
		$n_bd = 0; foreach ( $kids as $k ) { if ( self::card_photo_badge( $k ) ) { $n_bd++; } }
		if ( $n_bd >= (int) ceil( count( $kids ) / 2 ) ) { return false; }
		// A SINGLE-TRACK grid (`grid-template-columns: 1fr` → one computed px track) is a vertical STACK of cards,
		// not a card GRID: the children sit one under another, full width. Claiming it here split three full-width
		// band cards into 278px thirds. The `stack` recognizer (below) carries the gap; each child converts alone.
		if ( self::is_single_track_stack( $el, true ) ) { return false; } // grid-only: a flex-column card container keeps its historic claim
		// A fixed-width ASYMMETRIC layout (a visual + body two-column: `lg:w-[506px]` + `flex-1`, arbitrary
		// px widths) is a LAYOUT row, NOT a uniform card grid — defer to is_layout_row so the columns keep
		// their real proportional widths AND full content. (Otherwise card_grid claims it first at prio 85/90,
		// even-splits the columns to 1_2/1_2 and drops the non-card content, e.g. the 'Download Now' CTA.)
		if ( self::layout_px_fractions( $kids ) ) { return false; }
		// A vertical flex-col STACK is not a card GRID (cards lay out horizontally / wrapped, never stacked
		// vertically). Reject a pure `flex-col` with no responsive `*:flex-row` override and no `grid`, so a
		// vertical content stack (badge + heading + a two-column row) isn't mis-claimed as a card grid at the
		// WRONG level (which claims the whole stack and even-splits/ drops its real inner layout). (P3 fix.)
		$pad = ' ' . $cls . ' ';
		if ( strpos( $cls, 'grid' ) === false && preg_match( '/(?:^|\s)flex-col(?:\s|$)/', $pad )
			&& ! preg_match( '/(?:sm|md|lg|xl|2xl):flex-row(?:\s|$)/', $pad ) ) { return false; }
		// A cell carrying a DISPLAY-sized heading (an <h1>, or an h1-h3 at text-4xl+) is a HERO / section
		// CONTENT column (big headline + prose + CTA), NOT a uniform card. Defer the whole band to
		// is_layout_row (82) so each cell DECOMPOSES to special_heading + text + button (and a stats panel
		// to its counter grid) instead of card_grid collapsing the headline column into one icon_box.
		foreach ( $kids as $k ) { if ( self::cell_has_display_heading( $k ) ) { return false; } }
		$cards = 0;
		foreach ( $kids as $k ) {
			if ( self::is_card_cell( $k ) ) { $cards++; }
		}
		// h-tag-only card counting misses a hand-authored content grid whose cell TITLE is a styled <b>/<span>
		// rather than a semantic heading (a "chapters"/"features" nav: <b>Label</b> + <p>desc</p>). Accept it
		// as a real columns row when it is a strict UNIFORM content grid, so the N cells become N columns
		// instead of 2N stacked text blocks.
		if ( $cards < 2 && self::is_uniform_content_grid( $el, $kids ) ) { return true; }
		return $cards >= 2;
	}

	/**
	 * A hand-authored (non-Tailwind) GRID of uniform CONTENT cells that the h-tag-only card test misses —
	 * e.g. a 4-up "chapters" nav where each cell is `<b>Label</b><p>desc</p>` (a styled <b>, not a semantic
	 * heading). Strict on purpose: a REAL computed grid (display:grid, or a `grid` class), 2..6 children that
	 * are STRUCTURALLY UNIFORM (identical tag + semantic-class signature) and each carrying substantive text.
	 * Grid-only (never a bare flex strip) + capped + uniform, so a big multi-row gallery or a random inline
	 * flex row is NOT mis-claimed as a columns row.
	 */
	/** The first hero section's OWN top clearance in px — the largest `padding-top` on a near-top content
	 *  wrapper (e.g. `.hero-top{padding-top:107px}`) that the source uses to clear a transparent overlay
	 *  masthead. Wrapper-flattening drops this inner padding, so the hero rides under the nav; carrying it as
	 *  the section's overlay offset restores the source clearance. Only the first two descendant levels are
	 *  considered (the hero's own content wrapper, not deep nested padding), and the value is gated to a
	 *  header-sized band (60..200px) so ordinary section padding isn't mistaken for a clearance. */
	private static function hero_top_clearance( $section ) {
		if ( ! ( $section instanceof DOMElement ) ) { return 0; }
		$max = 0.0;
		// Only the FIRST in-flow child at each level is top clearance — a later child's padding-top (a bottom-pinned
		// "trusted by" strip's `pt-24`) is its own spacing, not the hero's header offset. JS: heroTopClearance.
		$first_flow = function ( $el ) {
			foreach ( self::el_children( $el ) as $k ) {
				$kcs = (string) $k->getAttribute( 'data-sc-cs' );
				if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', $kcs ) || preg_match( '/(?:^|;)\s*display:\s*none/i', $kcs ) ) { continue; }
				return $k;
			}
			return null;
		};
		$c1 = $first_flow( $section );
		if ( $c1 instanceof DOMElement ) {
			$max = max( $max, self::sc_pad_top_px( $c1 ) );
			$c2 = $first_flow( $c1 );
			if ( $c2 instanceof DOMElement ) { $max = max( $max, self::sc_pad_top_px( $c2 ) ); }
		}
		$max = (int) round( $max );
		return ( $max >= 60 && $max <= 200 ) ? $max : 0;
	}

	/**
	 * A TOP-PINNED, OUT-OF-FLOW header chrome (a `position:fixed`/`absolute` bar pinned to the top of the
	 * viewport), scanning the <header> AND its descendants — because the fixed bars are frequently inner
	 * wrappers (a `fixed top-0` ticker, a `fixed top-12` nav) while the semantic <header> itself is a
	 * class-less, zero-height flow box. Returns whether such a bar exists and whether it is SOLID (an opaque
	 * background), which distinguishes a solid fixed masthead (reproduced as an in-flow static/sticky header —
	 * its source clearance is then redundant) from a transparent overlay nav (reproduced as an overlay that
	 * still needs the clearance). A `bottom-`/`bottom:0` pinned element (a floating FAB) is NOT header chrome.
	 *
	 * @param DOMElement $header the masthead root
	 * @return array{found:bool,solid:bool}
	 */
	private static function fixed_top_chrome( $header ) {
		$res = array( 'found' => false, 'solid' => false );
		if ( ! ( $header instanceof DOMElement ) ) { return $res; }
		$scan = array( $header );
		foreach ( $header->getElementsByTagName( '*' ) as $d ) { $scan[] = $d; }
		foreach ( $scan as $d ) {
			if ( ! ( $d instanceof DOMElement ) ) { continue; }
			$dc  = ' ' . self::cls( $d ) . ' ';
			$dcs = (string) $d->getAttribute( 'data-sc-cs' );
			$dst = strtolower( (string) $d->getAttribute( 'style' ) );
			$is_fixed = ( false !== strpos( $dc, ' fixed ' ) || false !== strpos( $dc, ' absolute ' )
				|| preg_match( '/position:\s*(?:fixed|absolute)/i', $dcs . ';' . $dst ) );
			if ( ! $is_fixed ) { continue; }
			// Must be pinned to the TOP (top-0 / top-N / top:0), not a floating bottom/side element.
			$top_pinned = ( preg_match( '/\btop-(?:0|\[0|\d)/', $dc ) || preg_match( '/(?:^|;)\s*top:\s*0(?:px|%|rem|em)?/i', $dcs . ';' . $dst ) );
			$bottom     = ( false !== strpos( $dc, ' bottom-' ) || preg_match( '/(?:^|;)\s*bottom:\s*0/i', $dcs . ';' . $dst ) );
			if ( ! $top_pinned || $bottom ) { continue; }
			$res['found'] = true;
			// SOLID = a genuinely OPAQUE background — a bar reproduced IN-FLOW, whose reserved clearance is then
			// redundant. A GLASS / TRANSLUCENT overlay is NOT solid: it carries a `backdrop-blur` and/or a sub-opaque
			// fill, is reproduced as an OVERLAY header (position:absolute), and so the hero STILL needs its top
			// clearance — dropping it renders the heading UNDER the nav (the modfii `bg-background/80 backdrop-blur-lg`
			// case: the first heading line clipped behind the frosted nav).
			$has_blur = ( false !== strpos( $dc, ' backdrop-blur' ) || preg_match( '/backdrop-filter:\s*[^;]*blur/i', $dcs . ';' . $dst ) );
			if ( $has_blur ) { continue; }
			// Computed alpha from rgba() OR a `color(srgb … / A)` (near-opaque ≥ .95 = solid; else a translucent overlay).
			$alpha = null;
			if ( preg_match( '/background-color:\s*rgba?\(([^)]*)\)/i', $dcs, $bm ) ) {
				$parts = array_map( 'trim', explode( ',', $bm[1] ) );
				$alpha = isset( $parts[3] ) ? (float) $parts[3] : 1.0;
			} elseif ( preg_match( '~background-color:\s*color\([^)]*/\s*([0-9.]+)\s*\)~i', $dcs, $cm2 ) ) {
				$alpha = (float) $cm2[1];
			} elseif ( preg_match( '~background-color:\s*(?:color\(|#|rgb\(|hsl\()~i', $dcs ) ) {
				$alpha = 1.0; // a colour with no alpha channel = opaque
			}
			if ( null !== $alpha ) {
				if ( $alpha >= 0.95 ) { $res['solid'] = true; }
			} elseif ( preg_match( '/\bbg-(?!transparent|none)(?:primary|secondary|accent|white|black|background|foreground|dark|light|neutral|zinc|gray|grey|slate|stone|red|orange|amber|yellow|green|blue|\[#[0-9a-f]{3,8}\b)(?!\/\d)/i', $dc ) ) {
				// an OPAQUE bg-* token — NOT a `bg-*/NN` translucent one (that is a glass overlay).
				$res['solid'] = true;
			}
			if ( $res['solid'] ) { break; }
		}
		return $res;
	}

	/** The computed top padding (px) of an element from data-sc-cs — reads a `padding-top:` or the top value
	 *  of a `padding:` shorthand (the first length). 0 when none. */
	private static function sc_pad_top_px( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return 0.0; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*padding-top:\s*([\d.]+)px/i', $cs, $m ) ) { return (float) $m[1]; }
		if ( preg_match( '/(?:^|;)\s*padding:\s*([\d.]+)px/i', $cs, $m ) ) { return (float) $m[1]; }
		return 0.0;
	}

	private static function is_uniform_content_grid( $el, $kids = null ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		// ONLY the case the class-driven path misses: a HAND-AUTHORED grid declared purely in CSS
		// (`display:grid` computed) with NO `grid`/`flex` utility class. A Tailwind `grid grid-cols-*`
		// container already has an established mapping (card_grid / layout-row decomposition) — never
		// override it, so this can't regress utility-class layouts.
		$cls = self::cls( $el );
		if ( strpos( $cls, 'grid' ) !== false || strpos( $cls, 'flex' ) !== false ) { return false; }
		if ( self::sc_css( $el, 'display' ) !== 'grid' ) { return false; }
		if ( $kids === null ) { $kids = self::el_children( $el ); }
		$n = count( $kids );
		if ( $n < 2 || $n > 6 ) { return false; }
		$sig = null;
		foreach ( $kids as $k ) {
			if ( ! ( $k instanceof DOMElement ) ) { return false; }
			$tag = strtolower( $k->tagName );
			if ( in_array( $tag, array( 'button', 'input', 'img', 'br', 'hr', 'a' ), true ) ) { return false; }
			// A cell that carries a SEMANTIC heading (h1-h6) is handled by the richer card / layout-row
			// decomposition (which preserves the special_heading + text pairing) — this helper is ONLY for
			// heading-LESS cells (a styled <b>/<span> title), so defer those and don't collapse them to text.
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) {
				if ( $k->getElementsByTagName( $h )->length > 0 ) { return false; }
			}
			$s = self::el_signature( $k );
			if ( $sig === null ) { $sig = $s; } elseif ( $s !== $sig ) { return false; }
			if ( mb_strlen( trim( self::text( $k ) ) ) < 4 ) { return false; }
		}
		return true;
	}

	/**
	 * Is this element an Instagram FEED (a grid of posts) — as opposed to a lone social LINK/icon?
	 * Strong signals: the official post-embed (`blockquote.instagram-media` / `data-instgrm-permalink`),
	 * a feed-widget marker class/id (`instagram-feed`, `sb_instagram`, `instagram-gallery`, …) over a
	 * >=3-image grid, >=3 images served from an Instagram CDN, or an "Instagram"/@handle heading + an
	 * instagram.com profile link over a >=3-image grid. A single Instagram link with no image grid is NOT
	 * a feed (that's a footer/social icon, handled elsewhere).
	 */
	private static function is_instagram_feed( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		// (a) Official embed (this element or a descendant blockquote).
		if ( 'blockquote' === strtolower( $el->tagName ) && false !== strpos( self::cls( $el ), 'instagram-media' ) ) { return true; }
		foreach ( $el->getElementsByTagName( 'blockquote' ) as $bq ) {
			if ( false !== strpos( self::cls( $bq ), 'instagram-media' ) || '' !== (string) $bq->getAttribute( 'data-instgrm-permalink' ) ) { return true; }
		}
		// Image census (+ Instagram-CDN count).
		$imgs  = $el->getElementsByTagName( 'img' );
		$img_n = $imgs->length;
		$cdn_n = 0;
		foreach ( $imgs as $img ) {
			$src = (string) ( $img->getAttribute( 'src' ) ?: $img->getAttribute( 'data-src' ) );
			if ( preg_match( '#(?:cdninstagram\.com|scontent[^/]*\.(?:cdninstagram|fbcdn)\.net|instagram\.f[a-z0-9-]+\.fna)#i', $src ) ) { $cdn_n++; }
		}
		// (b) A feed-widget marker on the element or a descendant, over a >=3-image grid.
		$marker = '/\b(instagram-feed|insta-?feed|sb_instagram|instagram-gallery|instagram-widget|ig-feed|instagram-grid|elfsight-app-instagram)\b/i';
		if ( $img_n >= 3 ) {
			$blob = self::cls( $el ) . ' ' . (string) $el->getAttribute( 'id' );
			foreach ( $el->getElementsByTagName( 'div' ) as $d ) { $blob .= ' ' . self::cls( $d ) . ' ' . (string) $d->getAttribute( 'id' ); if ( strlen( $blob ) > 6000 ) { break; } }
			if ( preg_match( $marker, $blob ) ) { return true; }
		}
		// (c) >=3 Instagram-CDN images = a feed regardless of markup.
		if ( $cdn_n >= 3 ) { return true; }
		// (d) an "Instagram"/@handle heading + a profile link over a >=3-image grid.
		if ( $img_n >= 3 ) {
			$txt    = strtolower( self::text( $el ) );
			$has_kw = ( false !== strpos( $txt, 'instagram' ) || (bool) preg_match( '/@[a-z0-9._]{2,}/', $txt ) );
			$has_ln = false;
			foreach ( $el->getElementsByTagName( 'a' ) as $a ) {
				if ( preg_match( '#instagram\.com/#i', (string) $a->getAttribute( 'href' ) ) ) { $has_ln = true; break; }
			}
			if ( $has_kw && $has_ln ) { return true; }
		}
		return false;
	}

	/** Build the instagram-feed block: detected @handle, column count (from a grid-cols-N class), post count. */
	private static function instagram_feed_of( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return null; }
		// username — an instagram.com/<handle> PROFILE link (not /p/, /reel/, /explore/, /accounts/…), else an
		// @handle in the text. The handle usually lives on the element itself; but it often sits in a heading
		// ABOVE the grid ("Follow us on Instagram @handle"), so fall back to scanning up to 3 ancestors.
		$find_handle = function ( $scope ) {
			if ( ! ( $scope instanceof DOMElement ) ) { return ''; }
			foreach ( $scope->getElementsByTagName( 'a' ) as $a ) {
				if ( preg_match( '~instagram\.com/([A-Za-z0-9._]+)/?(?:[?#]|$)~i', (string) $a->getAttribute( 'href' ), $m ) ) {
					$h = strtolower( $m[1] );
					if ( ! in_array( $h, array( 'p', 'reel', 'reels', 'explore', 'accounts', 'stories', 'tv', 'about', 'legal' ), true ) ) { return $m[1]; }
				}
			}
			return preg_match( '/@([a-z0-9._]{2,30})/i', self::text( $scope ), $mm ) ? $mm[1] : '';
		};
		$user = $find_handle( $el );
		for ( $p = $el->parentNode, $up = 0; '' === $user && $p instanceof DOMElement && $up < 3; $p = $p->parentNode, $up++ ) {
			$user = $find_handle( $p );
		}
		// post count — number of image tiles, clamped 3..18.
		$count = min( 18, max( 3, $el->getElementsByTagName( 'img' )->length ) );
		// columns — from a grid-cols-N (widest breakpoint) on the element or a descendant; else infer from count.
		$cols = 0;
		$blob = self::cls( $el );
		foreach ( $el->getElementsByTagName( 'div' ) as $d ) { $blob .= ' ' . self::cls( $d ); if ( strlen( $blob ) > 6000 ) { break; } }
		foreach ( array( '2xl', 'xl', 'lg', 'md', 'sm' ) as $bp ) {
			if ( preg_match( '/' . $bp . ':grid-cols-(\d)/', $blob, $cm ) ) { $cols = (int) $cm[1]; break; }
		}
		if ( 0 === $cols && preg_match( '/(?:^|\s)grid-cols-(\d)/', $blob, $cm ) ) { $cols = (int) $cm[1]; }
		if ( 0 === $cols ) { $cols = min( 4, max( 2, (int) $count ) ); }
		$cols = max( 1, min( 6, $cols ) );
		return array( 't' => 'instagram', 'role' => 'instagram', 'username' => $user, 'count' => $count, 'columns' => $cols );
	}

	/** Computed-style card-grid test — framework-agnostic (data-sc-cs): a flex/grid container with >=2 card
	 *  cells (each carrying a heading). Catches plain-CSS / Bootstrap card rows that have no Tailwind class. */
	private static function cs_is_card_grid( $el ) {
		$cs = $el->getAttribute( 'data-sc-cs' );
		if ( strpos( $cs, 'display:flex' ) === false && strpos( $cs, 'display:grid' ) === false && strpos( $cs, 'display:inline-flex' ) === false ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		// Same guards as is_card_grid (computed-style twin): a fixed-width ASYMMETRIC layout (arbitrary px
		// widths) defers to is_layout_row, and a VERTICAL stack (computed flex-direction:column) is never a
		// card grid. Without these, a `flex flex-col` content stack was mis-claimed as a card grid at the wrong
		// level and its inner two-column layout was even-split + partly dropped. (P3 grid-detection fix.)
		if ( self::layout_px_fractions( $kids ) ) { return false; }
		if ( preg_match( '/flex-direction:\s*column/i', $cs ) ) { return false; }
		// A DISPLAY-heading cell (hero/section content band) defers to is_layout_row — same guard as
		// is_card_grid, so the computed-style twin doesn't claim a hero headline column as a card either.
		foreach ( $kids as $k ) { if ( self::cell_has_display_heading( $k ) ) { return false; } }
		$cards = 0;
		foreach ( $kids as $k ) { if ( self::is_card_cell( $k ) ) { $cards++; } }
		return $cards >= 2;
	}

	/** A container that's just a strip of images (≥2 imgs, no headings/cards) — a logo / "trusted by" row. */
	/** A container's direct-child IMAGE TILES: each a wrapper (div/a/figure/li) around a real <img>. */
	/**
	 * Does $el hold a section-intro HEADING + a single trailing CTA LINK laid out `flex justify-between`?
	 * (heading-group on one side, a lone `<a>` on the other). Tight: exactly two element children, exactly
	 * one side carries an hN, the other is/wraps ONE `<a>` (no heading, no image, no second link). So a real
	 * "Our Services … View All →" row is caught, but a normal content row never is.
	 */
	private static function is_heading_cta_row( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$c = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$is_flex = strpos( $c, ' flex ' ) !== false || strpos( $c, ':flex-row' ) !== false || 'flex' === self::sc_css( $el, 'display' );
		$between = strpos( $c, 'justify-between' ) !== false || false !== strpos( (string) self::sc_css( $el, 'justify-content' ), 'space-between' );
		if ( ! $is_flex || ! $between ) { return false; }
		// a flex COLUMN (`flex-col justify-between`: a card body whose meta row is pushed to the bottom) is a stack, not a
		// heading | link row — claimed as one, its build came back null and the whole body vanished (a fixture from the feed)
		$fd0 = (string) self::sc_css( $el, 'flex-direction' );
		if ( '' !== $fd0 ? (bool) preg_match( '/^column/i', $fd0 ) : ( strpos( $c, ' flex-col ' ) !== false && ! preg_match( '/(?:sm|md|lg|xl):flex-row/', $c ) ) ) { return false; }
		// A heading beside a "View All ->" link is TEXT. A card that pairs a photo with a title and a
		// "Read more" link is not this widget -- and heading_cta_row_build() emits only the heading + link,
		// so claiming it drops the photo (personal_blog_writer's article cards). Same no-image-surface rule
		// as the steps / progress / counter gates.
		foreach ( $el->getElementsByTagName( 'img' ) as $im ) {
			$src = trim( (string) $im->getAttribute( 'src' ) );
			if ( '' === $src ) { $src = trim( (string) $im->getAttribute( 'data-src' ) ); }
			if ( '' === $src || 0 === strpos( $src, 'data:image/svg' ) || preg_match( '/\.svg(?:$|\?)/i', $src ) ) { continue; }
			return false;
		}
		$kids = array();
		foreach ( $el->childNodes as $ch ) { if ( XML_ELEMENT_NODE === $ch->nodeType ) { $kids[] = $ch; } }
		if ( count( $kids ) !== 2 ) { return false; }
		$has_h = function ( $n ) {
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { if ( $n->getElementsByTagName( $h )->length > 0 ) { return true; } }
			return false;
		};
		$h0 = $has_h( $kids[0] ); $h1 = $has_h( $kids[1] );
		if ( $h0 === $h1 ) { return false; }                                     // need EXACTLY one heading side
		$link_el = $h0 ? $kids[1] : $kids[0];
		if ( $has_h( $link_el ) ) { return false; }
		$link_is_a = ( 'a' === strtolower( $link_el->tagName ) );
		$a = $link_is_a ? $link_el : $link_el->getElementsByTagName( 'a' )->item( 0 );
		if ( ! $a ) { return false; }
		// Exactly ONE link total. getElementsByTagName excludes the element itself, so add 1 when link_el IS
		// the <a> (else a bare `<a>` side counts 0 and is wrongly rejected).
		$a_count = ( $link_is_a ? 1 : 0 ) + $link_el->getElementsByTagName( 'a' )->length;
		if ( $a_count !== 1 ) { return false; }
		if ( $link_el->getElementsByTagName( 'img' )->length > 0 ) { return false; }   // not an image tile
		if ( trim( self::text( $a ) ) === '' ) { return false; }
		return true;
	}

	/** Build the { t:'heading_cta', heading, link } block from a heading+CTA-link justify-between row. */
	private static function heading_cta_row_build( $el ) {
		$kids = array();
		foreach ( $el->childNodes as $ch ) { if ( XML_ELEMENT_NODE === $ch->nodeType ) { $kids[] = $ch; } }
		$has_h = function ( $n ) {
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { if ( $n->getElementsByTagName( $h )->length > 0 ) { return true; } }
			return false;
		};
		$head_el = $has_h( $kids[0] ) ? $kids[0] : $kids[1];
		$link_el = ( $head_el === $kids[0] ) ? $kids[1] : $kids[0];
		$a = ( 'a' === strtolower( $link_el->tagName ) ) ? $link_el : $link_el->getElementsByTagName( 'a' )->item( 0 );

		$h  = array( 'overline' => '', 'title' => '', 'subtitle' => '', 'overline_class' => '', 'title_class' => '', 'subtitle_class' => '', 'css_class' => '', 'level' => 2, 'align' => '', 'wrapMaxW' => '' );
		$hn = null;
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $tg ) { $e = $head_el->getElementsByTagName( $tg )->item( 0 ); if ( $e ) { $hn = $e; $h['level'] = (int) substr( $tg, 1 ); break; } }
		if ( $hn instanceof DOMElement ) {
			$h['title']       = self::clean_inline_html( $hn );
			$h['title_class'] = self::cls( $hn );
			$h['title_cs']    = (string) $hn->getAttribute( 'data-sc-cs' );
			// a KICKER right before the heading (a short uppercase / small block span — `text-xs uppercase tracking-widest
			// block mb-2`) is the heading's overline; the heading+link row kept only the h2 (a fixture from the feed)
			for ( $pv = $hn->previousSibling; $pv instanceof DOMNode; $pv = $pv->previousSibling ) {
				if ( XML_TEXT_NODE === $pv->nodeType && '' === trim( $pv->nodeValue ) ) { continue; }
				if ( ! ( $pv instanceof DOMElement ) ) { break; }
				$kt = trim( preg_replace( '/\s+/u', ' ', self::text( $pv ) ) ); $kcs = (string) $pv->getAttribute( 'data-sc-cs' );
				$small = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', $kcs, $kf ) && (float) $kf[1] <= 16;
				$upper = (bool) preg_match( '/text-transform:\s*uppercase/i', $kcs ) || (bool) preg_match( '/\buppercase\b/', self::cls( $pv ) );
				if ( '' !== $kt && mb_strlen( $kt ) <= 60 && in_array( strtolower( $pv->tagName ), array( 'span', 'p', 'div', 'small' ), true ) && ( $small || $upper ) && 0 === $pv->getElementsByTagName( 'img' )->length ) {
					$h['overline'] = $kt; $h['overline_class'] = self::cls( $pv ); $h['overline_cs'] = $kcs;
				}
				break;
			}
		}
		$p = $head_el->getElementsByTagName( 'p' )->item( 0 );
		// the FIRST <p> is the subtitle only when it is not the kicker already taken as the overline (a `<p>` eyebrow before the
		// h2 rendered twice: as the overline AND as the subtitle — a real-site audit) and it FOLLOWS the heading
		if ( $p instanceof DOMElement && ( ( isset( $pv ) && $p === $pv ) || ( isset( $h['overline'] ) && trim( preg_replace( '/\s+/u', ' ', self::text( $p ) ) ) === (string) $h['overline'] ) || ( $hn instanceof DOMElement && self::dom_precedes( $p, $hn, $head_el ) ) ) ) { $p = null; }
		if ( $p instanceof DOMElement ) {
			$h['subtitle']       = self::clean_inline_html( $p );
			$h['subtitle_class'] = self::cls( $p );
			$h['subtitle_cs']    = (string) $p->getAttribute( 'data-sc-cs' );
		}

		$link = array(
			'label' => self::text( $a ),
			'href'  => (string) $a->getAttribute( 'href' ),
			'cls'   => self::cls( $a ),
			'cs'    => (string) $a->getAttribute( 'data-sc-cs' ),
			'hover' => (string) $a->getAttribute( 'data-sc-hover' ),
		);
		$svg = $a->getElementsByTagName( 'svg' )->item( 0 );
		if ( $svg instanceof DOMElement && $a->ownerDocument ) { $link['icon_svg'] = (string) $a->ownerDocument->saveHTML( $svg ); }

		// the row's OWN bottom margin (`mb-14` above a product grid) — the grid had sat 20px under the heading, not 56
		$hcm = self::el_margin( $el );
		return array( 't' => 'heading_cta', 'role' => 'heading_cta', 'heading' => $h, 'link' => $link, 'mb' => (float) ( $hcm['bottom'] ?? 0 ), 'mt' => (float) ( $hcm['top'] ?? 0 ) );
	}

	private static function image_grid_tiles( $el ) {
		$tiles = array();
		if ( ! ( $el instanceof DOMElement ) ) { return $tiles; }
		// Collect EVERY real gallery image in the container, FLATTENING nested columns/grids — a metro layout
		// like `grid[ tall-img , flex-col[ img , img ] ]` carries 3 images across only 2 direct children, and
		// the old direct-child-only scan saw just 2 tiles (grabbing one img per child) → the grid failed the
		// ≥3 gallery test and one image was dropped. Walk every <img>, keyed to its nearest block wrapper (for
		// col-span / aspect classes). Parity in JS capture-extract imageGridTiles.
		foreach ( $el->getElementsByTagName( 'img' ) as $img ) {
			if ( ! ( $img instanceof DOMElement ) ) { continue; }
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( '' === $src ) { $src = trim( (string) $img->getAttribute( 'data-src' ) ); }
			if ( '' === $src || stripos( $src, 'data:' ) === 0 ) { continue; }
			// Nearest block-wrapper ancestor inside $el (the tile element); fall back to the img itself.
			$wrap = $img->parentNode;
			while ( $wrap instanceof DOMElement && $wrap !== $el
				&& ! in_array( strtolower( $wrap->tagName ), array( 'div', 'a', 'figure', 'li' ), true ) ) {
				$wrap = $wrap->parentNode;
			}
			if ( ! ( $wrap instanceof DOMElement ) || $wrap === $el ) { $wrap = $img; }
			$tiles[] = array( 'el' => $wrap, 'img' => $img, 'src' => $src );
		}
		return $tiles;
	}

	/**
	 * Is $el a GALLERY grid — a grid/flex container whose children are ≥3 uniform image tiles (each a
	 * wrapper around an <img>), with no headings? Tight so a content card grid (icon+heading+text) never
	 * qualifies. The tiles must be the clear majority of the container's element children (a real photo
	 * grid), not one stray image among text blocks.
	 */
	/**
	 * A DECORATIVE image-layer SCENE — a purely-decorative container (marked `aria-hidden="true"`, or a
	 * layer/parallax/foreground/scene class) holding 2+ stacked images and NO real content (no headings, no
	 * meaningful copy). This is the cinematic parallax collage art-directed landing pages layer BEHIND the
	 * copy; the layers are positioned by the source's own CSS classes (`.fg-el`, `.fg-wall{position:absolute}`)
	 * which the section's carried CSS already reproduces. Rather than dropping the images as "decorative", keep
	 * the scene VERBATIM (a code_block) so the collage renders with that carried CSS. Purely additive — nothing
	 * claimed this container before (its images were filtered), so no existing mapping changes.
	 */
	private static function is_decorative_scene( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( $el->getElementsByTagName( 'img' )->length < 2 ) { return false; }
		$aria  = 'true' === strtolower( trim( (string) $el->getAttribute( 'aria-hidden' ) ) );
		$cls   = ' ' . strtolower( self::cls( $el ) ) . ' ';
		$layer = (bool) preg_match( '/\s(fg|parallax|layers?|scene|foreground|backdrop-layers?|decor|bg-scene|art-layers?)\s/', $cls );
		if ( ! $aria && ! $layer ) { return false; }
		// A PURE decorative layer stack only — never a real content section that happens to be aria-hidden:
		// no headings, and no substantial copy.
		for ( $i = 1; $i <= 6; $i++ ) { if ( $el->getElementsByTagName( 'h' . $i )->length ) { return false; } }
		if ( mb_strlen( trim( (string) self::text( $el ) ) ) > 40 ) { return false; }
		return true;
	}

	/** Emit a decorative image-layer scene VERBATIM as a code_block: the container's markup (source classes
	 *  intact, so the carried `.fg`/`.fg-el` CSS positions the layers), with the capture's computed-style +
	 *  data attrs stripped. Relative image srcs are absolutised by n_code() on the mapper side. */
	private static function decorative_scene_build( $el ) {
		// PREFER an editable Parallax Scene: if the scene decomposes into clean IMAGE layers, emit the native
		// parallax_scene shortcode (mapper n_parallax_scene) instead of a frozen code_block.
		$layers = self::scene_image_layers( $el );
		if ( count( $layers ) >= 2 ) {
			return array( 't' => 'parallax_scene', 'layers' => $layers );
		}
		$doc  = $el->ownerDocument;
		$html = $doc ? (string) $doc->saveHTML( $el ) : '';
		if ( '' === trim( $html ) ) { return null; }
		$html = preg_replace( '/\s(?:data-sc-cs|data-sc-[a-z-]+)="[^"]*"/i', '', $html );
		// The source reveals these layers via JS on scroll (they START at `opacity:0` + an offset transform,
		// keyed by data-attrs like `data-fg-in`/`data-rv` or `.is-in`-style classes). We keep the COMPOSITION
		// but not that JS, so force the layers to their REVEALED state (opacity:1, no offset) — otherwise the
		// whole scene renders invisible. Scoped to `.sc-scene`, so it only affects this decorative block.
		$reveal = '<style>.sc-scene [data-fg-in],.sc-scene [data-rv],.sc-scene [data-reveal],.sc-scene [data-aos],.sc-scene [data-animate],.sc-scene [data-inview],.sc-scene [data-scroll],'
			. '.sc-scene [class*="reveal"],.sc-scene [class*="rv-"],.sc-scene [style*="opacity:0"],.sc-scene [style*="opacity: 0"]'
			. '{opacity:1 !important;transform:none !important;}</style>';
		return array( 't' => 'html', 'role' => 'code', 'html' => '<div class="sc-tw sc-scene">' . $reveal . $html . '</div>' );
	}

	/**
	 * Extract a decorative scene's IMAGE LAYERS for the parallax_scene shortcode. Each <img> in the scene
	 * becomes a layer, reading its wrapper for the entrance direction (data-fg-in), sway (a `sway` class),
	 * and flip (a `flip` class); z-order + a staggered delay come from DOM order. The capture doesn't record
	 * layer POSITION, so the anchor is inferred (entrance direction → side; a wall/hill/backdrop → full-width),
	 * with the mapper filling depth/width defaults. Returns [] when there aren't real image layers.
	 */
	private static function scene_image_layers( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return array(); }
		$layers = array(); $i = 0; $seen = array();
		foreach ( $el->getElementsByTagName( 'img' ) as $img ) {
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( '' === $src || 0 === strpos( $src, 'data:' ) || isset( $seen[ $src ] ) ) { continue; }
			$seen[ $src ] = true;
			$w  = ( $img->parentNode instanceof DOMElement ) ? $img->parentNode : $img;
			$wc = ' ' . strtolower( self::cls( $w ) . ' ' . self::cls( $img ) ) . ' ';
			$fgin = strtolower( trim( (string) $w->getAttribute( 'data-fg-in' ) . ' ' . (string) $img->getAttribute( 'data-fg-in' ) ) );
			$entrance = ( preg_match( '/\b(left|right|up|down)\b/', $fgin, $m ) ) ? $m[1] : 'up';
			$h = ( 'left' === $entrance ) ? 'left' : ( ( 'right' === $entrance ) ? 'right' : 'center' );
			if ( preg_match( '/(?:^|[\s_-])(?:wall|hill|backdrop|sky|bg|ground|horizon)(?:[\s_-]|$)/', $wc ) ) { $h = 'stretch'; }
			$layers[] = array(
				'src'      => $src,
				'h'        => $h,
				'v'        => 'bottom',
				'entrance' => $entrance,
				'sway'     => ( strpos( $wc, 'sway' ) !== false ) ? 'sway' : 'none',
				'flip'     => ( strpos( $wc, 'flip' ) !== false ),
				'i'        => $i,
			);
			if ( ++$i >= 24 ) { break; }
		}
		return $layers;
	}

	private static function is_image_grid( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$c = ' ' . self::cls( $el ) . ' ';
		$is_grid = strpos( $c, ' grid ' ) !== false || strpos( $c, 'grid-cols' ) !== false
			|| preg_match( '/\bflex\b/', $c ) || in_array( self::sc_css( $el, 'display' ), array( 'grid', 'flex' ), true )
			// a CSS multi-column WALL (`columns-3` / computed column-count ≥ 2): a masonry of tiles is an image grid too
			// (detect_gallery_design reads it as the masonry design) — it fell to per-tile code blocks (a fixture from the feed)
			|| (bool) preg_match( '/(?:^|\s)(?:sm:|md:|lg:|xl:)?columns-[2-6](?:\s|$)/', $c ) || (bool) preg_match( '/(?:^|;)\s*column-count:\s*[2-6]/i', (string) $el->getAttribute( 'data-sc-cs' ) );
		if ( ! $is_grid ) { return false; }
		$tiles = self::image_grid_tiles( $el );
		if ( count( $tiles ) < 3 ) { return false; }
		// When "Map to WooCommerce" is on, a PRODUCT grid (tiles with a price / add-to-cart) is NOT a gallery —
		// bow out so it routes through card_grid → the mapper's columns→[wc_products] path instead of becoming
		// static image tiles. Only active on the gated build (map_woocommerce_on), so a normal gallery is safe.
		if ( class_exists( 'FW_Site_Converter_Mapper' ) && FW_Site_Converter_Mapper::map_woocommerce_on() && self::grid_is_product_grid( $el ) ) { return false; }
		// DEFER to the more-specific recognizers: a logo/"trusted-by" strip → `logo_grid`, an avatar stack →
		// `avatar`. image_grid is a HIGHER priority (91) than logo_strip (25) / avatar_group (84), and now
		// that tile-flattening catches nested images it would otherwise greedily claim those first — so bow
		// out when they match, letting each land on its correct shortcode. (Regression guard.)
		if ( self::is_logo_strip( $el ) || self::is_avatar_group( $el ) ) { return false; }
		// IMAGE-LED CARDS are not a gallery: a product / article tile carries IN-FLOW text leaves beside its image (a category
		// line, a name link, a price — none of them headings, so the heading gate below never saw them) and a gallery of them
		// lost every name and price (RECURS: three shops in the feed). A tile whose card (the container's child holding the
		// image) has ≥ 2 in-flow text leaves — outside any absolute overlay, not a figcaption — or a priced leaf, is a card;
		// when half the tiles are cards the grid routes to card_grid → image_box per card. A hover caption inside an
		// `absolute` layer, or one figcaption under the photo, keeps the gallery. Parity in JS isImageGrid.
		$n_cards = 0; $n_cells = 0;
		foreach ( self::el_children( $el ) as $cell ) {
			if ( 0 === $cell->getElementsByTagName( 'img' )->length ) { continue; }
			$n_cells++;
			$leaves = 0; $priced = false;
			foreach ( $cell->getElementsByTagName( '*' ) as $leaf ) {
				if ( ! ( $leaf instanceof DOMElement ) ) { continue; }
				$lt = strtolower( $leaf->tagName );
				if ( in_array( $lt, array( 'img', 'svg', 'path', 'figcaption', 'picture', 'source', 'br' ), true ) ) { continue; }
				$own = ''; foreach ( $leaf->childNodes as $tn ) { if ( XML_TEXT_NODE === $tn->nodeType ) { $own .= $tn->nodeValue; } }
				$own = trim( preg_replace( '/\s+/u', ' ', $own ) );
				if ( '' === $own ) { continue; }
				$abs = false;
				for ( $an = $leaf; $an instanceof DOMElement && $an !== $cell; $an = $an->parentNode ) {
					if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', (string) $an->getAttribute( 'data-sc-cs' ) ) || preg_match( '/(?:^|\s)(?:absolute|fixed)(?:\s|$)/', self::cls( $an ) ) ) { $abs = true; break; }
				}
				if ( $abs ) { continue; }
				$leaves++;
				if ( preg_match( '/[$€£¥]\s?\d|\d\s?(?:€|USD|EUR|GBP)\b/u', $own ) ) { $priced = true; }
			}
			if ( $leaves >= 2 || $priced ) { $n_cards++; }
		}
		if ( $n_cells >= 3 && $n_cards >= (int) ceil( $n_cells * 0.5 ) ) { return false; }
		// A grid with headings is USUALLY a content-card grid (icon/heading/text) — NOT a gallery, so reject
		// it. The ONE exception is a captioned PHOTO gallery, where each caption is a HOVER-REVEALED overlay
		// (`absolute inset-0 … opacity-0 group-hover:opacity-100`) sitting over a cover image — a signature a
		// content card never has (its heading is in normal, always-visible flow). Allow the grid only when
		// EVERY heading is such a hover caption AND the tiles are cover-image-dominant with no body <p>.
		// Parity in JS isImageGrid.
		$n = count( $tiles );
		$headings = 0;
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { $headings += $el->getElementsByTagName( $h )->length; }
		if ( $headings > 0 ) {
			$cover = 0; $with_body = 0;
			foreach ( $tiles as $t ) {
				$ic = ' ' . strtolower( self::cls( $t['img'] ) ) . ' ';
				$wc = ' ' . strtolower( self::cls( $t['el'] ) ) . ' ';
				if ( strpos( $ic, 'object-cover' ) !== false || strpos( $ic, 'object-fill' ) !== false
					|| ( strpos( $ic, 'w-full' ) !== false && strpos( $ic, 'h-full' ) !== false )
					|| preg_match( '/\b(?:[a-z]{2}:)?aspect-/', $wc ) || preg_match( '/\b(?:[a-z]{2}:)?h-\[?[0-9]/', $wc ) ) { $cover++; }
				if ( $t['el'] instanceof DOMElement && $t['el']->getElementsByTagName( 'p' )->length > 0 ) { $with_body++; }
			}
			// Every heading must sit inside an OVERLAY on the tile — an `absolute`/`fixed` layer over the cover
			// image. This covers BOTH a hover-revealed caption (`opacity-0 group-hover:opacity-100`) AND an
			// always-visible gradient caption (`absolute inset-0 bg-gradient-to-t …`, the AI-page "Discovered
			// Worlds" pattern). A content card never absolute-positions its heading over the image, and the
			// cover-dominant + no-body guards below keep a real card grid out — so the overlay signal alone is
			// enough (the earlier opacity-0/group-hover requirement wrongly rejected always-on captions).
			$all_overlay_caption = true;
			foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) {
				foreach ( $el->getElementsByTagName( $h ) as $hn ) {
					$anc = $hn->parentNode; $is_overlay = false;
					while ( $anc instanceof DOMElement && $anc !== $el ) {
						$ac = ' ' . strtolower( self::cls( $anc ) ) . ' ';
						if ( strpos( $ac, ' absolute ' ) !== false || strpos( $ac, ' fixed ' ) !== false ) { $is_overlay = true; break; }
						$anc = $anc->parentNode;
					}
					if ( ! $is_overlay ) { $all_overlay_caption = false; break 2; }
				}
			}
			$photo_gallery = $all_overlay_caption && ( $cover >= (int) ceil( $n * 0.7 ) ) && ( $with_body < (int) ceil( $n * 0.5 ) );
			if ( ! $photo_gallery ) { return false; }
		}
		$child_els = 0;
		foreach ( $el->childNodes as $ch ) { if ( XML_ELEMENT_NODE === $ch->nodeType ) { $child_els++; } }
		return count( $tiles ) >= max( 3, (int) ceil( $child_els * 0.7 ) );
	}

	/**
	 * The gallery Image-Ratio slug ('1-1' | '4-3' | '3-2' | '16-9' | '3-4' | '') best matching a source tile's
	 * crop. Reads an `aspect-[W/H]` / `aspect-square` / `aspect-video` utility (on the tile or its media
	 * wrapper), else the <img>'s intrinsic width/height. Returns '' when nothing usable is found or the ratio
	 * isn't close to a named choice (the gallery then keeps its 'original' default). Fixes tall (3:4) tiles
	 * being squashed into the Landscape 4:3 default.
	 */
	private static function image_tile_ratio_slug( $tile, $img ) {
		$rw = 0.0; $rh = 0.0;
		foreach ( array( $tile, $img ) as $node ) {
			if ( ! ( $node instanceof DOMElement ) ) { continue; }
			$c = ' ' . strtolower( self::cls( $node ) ) . ' ';
			if ( preg_match( '/\baspect-\[(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\]/', $c, $m ) && (float) $m[2] > 0 ) { $rw = (float) $m[1]; $rh = (float) $m[2]; break; }
			if ( strpos( $c, ' aspect-square ' ) !== false ) { $rw = 1; $rh = 1; break; }
			if ( strpos( $c, ' aspect-video ' )  !== false ) { $rw = 16; $rh = 9; break; }
		}
		if ( $rw <= 0 || $rh <= 0 ) {
			if ( $img instanceof DOMElement ) {
				$w = (float) $img->getAttribute( 'width' ); $h = (float) $img->getAttribute( 'height' );
				if ( $w > 0 && $h > 0 ) { $rw = $w; $rh = $h; }
			}
		}
		if ( $rw <= 0 || $rh <= 0 ) { return ''; }
		$r = $rw / $rh;
		$choices = array( '1-1' => 1.0, '4-3' => 4 / 3, '3-2' => 3 / 2, '16-9' => 16 / 9, '3-4' => 3 / 4 );
		$best = ''; $bestd = 1e9;
		foreach ( $choices as $slug => $v ) { $d = abs( $r - $v ); if ( $d < $bestd ) { $bestd = $d; $best = $slug; } }
		return ( $bestd <= 0.12 ) ? $best : ''; // only snap when genuinely close; else keep the gallery default
	}

	/** Build the gallery block from an image-tile grid: { images:[{url,alt,span}], html } (span = the
	 *  tile's col-span so a `md:col-span-2` tile keeps a wider slot in the mapped grid). */
	private static function image_grid_build( $el ) {
		$out      = array();
		$cap_mode = '';
		$cap_cs = ''; $cap_pad = ''; // the first captioned tile's caption typography + its inset // how the tile captions sat: 'overlay' (always-visible over a scrim) | 'hover' | '' (none)
		foreach ( self::image_grid_tiles( $el ) as $t ) {
			$span = 1; $rspan = 1;
			$tc   = ' ' . self::cls( $t['el'] ) . ' ';
			$span = self::tile_span( $tc, 'col' ); $rspan = self::tile_span( $tc, 'row' ); // the DESKTOP tier (`col-span-12 md:col-span-8` → 8), up to 12
			// PER-TILE CAPTION: an image tile's only text IS its caption (a title overlaid on the photo). Read
			// the tile's text and note HOW it sat — a HOVER-revealed overlay (opacity-0 + group-hover) vs an
			// ALWAYS-visible one (a bottom gradient caption). Fed to the gallery's overlay caption mode so the
			// title renders over the photo instead of being dropped.
			$cap = '';
			if ( $t['el'] instanceof DOMElement ) {
				$cap = trim( preg_replace( '/\s+/', ' ', (string) $t['el']->textContent ) );
				if ( ( function_exists( 'mb_strlen' ) ? mb_strlen( $cap ) : strlen( $cap ) ) > 120 ) { $cap = ''; } // too long → not a tile caption
			}
			if ( '' !== $cap && '' === $cap_mode ) {
				$hover = false;
				foreach ( $t['el']->getElementsByTagName( '*' ) as $lay ) {
					$lc = ' ' . strtolower( self::cls( $lay ) ) . ' ';
					if ( ( strpos( $lc, ' absolute ' ) !== false || strpos( $lc, ' fixed ' ) !== false )
						&& preg_match( '/opacity-0|group-hover:opacity/', $lc ) ) { $hover = true; break; }
				}
				$cap_mode = $hover ? 'hover' : 'overlay';
			}
			$row = array(
				'url'  => $t['src'],
				'alt'  => trim( (string) $t['img']->getAttribute( 'alt' ) ),
				'span' => $span, 'rspan' => $rspan,
			);
			if ( '' !== $cap ) {
				$row['caption'] = $cap;
				// the caption's OWN typography (a display-face uppercase tracked title over the photo) — the gallery's overlay text
				// had rendered in the body serif at .875rem (a real-site audit); the mapper scopes the FIRST tile's stamp
				if ( '' === $cap_cs ) { foreach ( $t['el']->getElementsByTagName( '*' ) as $ce ) { if ( $ce->getElementsByTagName( '*' )->length ) { continue; } if ( trim( preg_replace( '/\s+/', ' ', (string) $ce->textContent ) ) === $cap ) { $cap_cs = self::cs_text_decls( (string) $ce->getAttribute( 'data-sc-cs' ) ); $cpad = self::sc_css( $ce->parentNode instanceof DOMElement ? $ce->parentNode : $ce, 'padding' ); if ( preg_match( '/^[0-9.]+px(?:\s+[0-9.]+px){0,3}$/', $cpad ) ) { $cap_pad = $cpad; } break; } } }
			}
			$out[] = $row;
		}
		if ( count( $out ) < 3 ) { return null; } // let it fall through / be salvaged
		// the grid's MEASURED row height (`auto-rows-[300px]`) and gap — a bento's geometry is exact, not the design's pattern
		$gcs = (string) $el->getAttribute( 'data-sc-cs' ); $grid_geo = array();
		if ( preg_match( '/(?:^|\s)auto-rows-\[([0-9.]+)px\]/', self::cls( $el ), $arm ) ) { $grid_geo['rowH'] = (float) $arm[1]; }
		elseif ( preg_match( '/(?:^|;)\s*grid-auto-rows:\s*([0-9.]+)px/i', $gcs, $arm ) ) { $grid_geo['rowH'] = (float) $arm[1]; }
		if ( preg_match( '/(?:^|;)\s*(?:gap|row-gap):\s*([0-9.]+)px/i', $gcs, $gm ) ) { $grid_geo['gap'] = (float) $gm[1]; } elseif ( preg_match( '/(?:^|\s)gap-0(?:\s|$)/', self::cls( $el ) ) ) { $grid_geo['gap'] = 0.0; }
		// TILE ASPECT RATIO — the source crops each tile to a fixed ratio (`aspect-[3/4]` = tall portrait, the
		// the burger source food grid). Read it so the gallery reproduces the crop instead of defaulting to Landscape 4:3
		// (which squashed the tall photos). Sampled from the first tile (a uniform grid shares one ratio).
		$ratio_slug = '';
		$tiles0 = self::image_grid_tiles( $el );
		if ( $tiles0 ) { $ratio_slug = self::image_tile_ratio_slug( $tiles0[0]['el'], $tiles0[0]['img'] ); }
		// TILE CORNERS — the first tile's MEASURED border-radius (the tile, its clipping wrapper, or the img itself),
		// so a square-cornered source grid stays square and a rounded one keeps its radius; '' = not measured.
		$tile_radius = '';
		if ( $tiles0 ) {
			$cands = array( $tiles0[0]['el'] );
			foreach ( $tiles0[0]['el']->getElementsByTagName( '*' ) as $rn ) { $cands[] = $rn; if ( count( $cands ) > 12 ) { break; } }
			foreach ( $cands as $rn ) {
				if ( ! $rn instanceof DOMElement ) { continue; }
				$rv = self::sc_css( $rn, 'border-radius' );
				if ( preg_match( '/^([0-9.]+)px/', $rv, $rm ) ) { $tile_radius = (string) round( (float) $rm[1], 1 ); if ( (float) $rm[1] > 0 ) { break; } }
			}
		}
		$doc  = $el->ownerDocument;
		$html = $doc ? self::strip_cs( trim( (string) $doc->saveHTML( $el ) ) ) : '';
		return array( 't' => 'gallery', 'role' => 'gallery', 'images' => $out, 'html' => $html, 'captions' => $cap_mode, 'captionCs' => $cap_cs, 'captionPad' => $cap_pad, 'ratio' => $ratio_slug, 'tileRadius' => $tile_radius, 'design' => self::detect_gallery_design( $el, count( $out ) ), 'gridGeo' => $grid_geo );
	}

	/**
	 * The DESKTOP column count of a CSS multi-column wall. A responsive ladder (`columns-1 md:columns-2
	 * lg:columns-3`) lists the phone tier FIRST, so the first `columns-N` match is the narrowest — the
	 * largest tier (the measured `column-count` when stamped) is the one the desktop wall renders.
	 */
	private static function wall_columns( $el, $fallback ) {
		if ( $el instanceof DOMElement ) {
			if ( preg_match( '/(?:^|;)\s*column-count:\s*([1-6])\b/i', (string) $el->getAttribute( 'data-sc-cs' ), $cc ) ) { return (string) $cc[1]; }
			if ( preg_match_all( '/(?:^|\s)(?:(sm|md|lg|xl|2xl):)?columns-([1-6])(?=\s|$)/', self::cls( $el ), $all, PREG_SET_ORDER ) ) {
				$rank = array( '' => 0, 'sm' => 1, 'md' => 2, 'lg' => 3, 'xl' => 4, '2xl' => 5 ); $best = -1; $n = $fallback;
				foreach ( $all as $m ) { $r = $rank[ $m[1] ] ?? 0; if ( $r > $best ) { $best = $r; $n = $m[2]; } }
				return (string) $n;
			}
		}
		return (string) $fallback;
	}

	/**
	 * Classify the SOURCE image gallery's LAYOUT → the closest `gallery` shortcode DESIGN, so the converted
	 * gallery mirrors the source presentation instead of always the plain Grid. Returns `{ design[, columns] }`.
	 * Conservative — high-confidence structural signals only (marquee, JS/ARIA slider, CSS multi-column
	 * masonry, spanning-tile metro/mosaic); everything else falls back to the uniform Grid (which also carries
	 * the source col-spans as a per-column ratio, so a "featured" tile still reads wider).
	 */
	/** True when a row element is the band's own content container: a centred (`mx-auto` / auto margins) box whose max-width is
	 *  ≥ 1000px and whose equal side padding matches the site's declared container gutter (its inset is the gutter). */
	private static function row_is_container_box( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' ); $cls = ' ' . strtolower( self::cls( $el ) ) . ' ';
		if ( ! preg_match( '/(?:^|;)\s*max-width:\s*([0-9.]+)px/i', $cs, $mw ) || (float) $mw[1] < 1000 ) { return false; }
		if ( strpos( $cls, ' mx-auto ' ) === false && ! preg_match( '/(?:^|;)\s*margin(?:-left)?:\s*(?:0px\s+)?(?:auto|[1-9][0-9.]*px)/i', $cs ) ) { return false; }
		$pd = self::cs_decls_pad( $cs ); if ( null === $pd || $pd['left'] <= 0 || abs( $pd['left'] - $pd['right'] ) > 1 ) { return false; }
		if ( 0 === (int) self::$site_gutter_px && $el->ownerDocument ) { $g0 = (int) self::declared_container_gutter( (string) $el->ownerDocument->saveHTML() ); self::$site_gutter_px = $g0 > 0 ? $g0 : -1; } // (the sections are stitched before the chrome computes it — read it once here)
		$g = (int) self::$site_gutter_px; return $g > 0 && abs( $pd['left'] - $g ) <= 1;
	}
	private static $site_gutter_px = 0;

	/** A tile's `col-span-N` / `row-span-N` at the DESKTOP tier: the largest breakpoint prefix wins over the bare (mobile) utility
	 *  (`col-span-12 md:col-span-8` is 8 on desktop — the bare 12 had read every tile as full-width). 1 when none. */
	private static function tile_span( $cls, $axis ) {
		$cls = ' ' . (string) $cls . ' ';
		foreach ( array( '2xl:', 'xl:', 'lg:', 'md:', 'sm:', '' ) as $bp ) {
			if ( preg_match( '/(?:^|\s)' . preg_quote( $bp, '/' ) . $axis . '-span-([1-9]|1[0-2])(?:\s|$)/', $cls, $m ) ) { return (int) $m[1]; }
		}
		return 1;
	}

	private static function gcd_int( $a, $b ) { $a = abs( (int) $a ); $b = abs( (int) $b ); while ( $b ) { list( $a, $b ) = array( $b, $a % $b ); } return max( 1, $a ); }

	private static function detect_gallery_design( $el, $count ) {
		$grid = array( 'design' => 'grid' );
		if ( ! ( $el instanceof DOMElement ) ) { return $grid; }
		$scope = $el;
		for ( $i = 0; $i < 2 && $scope->parentNode instanceof DOMElement; $i++ ) { $scope = $scope->parentNode; }
		$doc = $el->ownerDocument;
		$hay = strtolower( (string) ( $doc ? $doc->saveHTML( $scope ) : '' ) );
		$cls = strtolower( self::cls( $el ) );

		// MARQUEE — a continuously auto-scrolling strip of images (CSS marquee animation / duplicated track).
		if ( preg_match( '/\bmarquee\b|animate-marquee|animate-scroll(?:-left|-right|-x)?(?=[\s"\'])|animation:[^;"\']*(?:marquee|scroll)/', $hay ) ) {
			return array( 'design' => 'marquee' );
		}
		// CAROUSEL / SLIDER — a JS slider lib, an ARIA carousel, or a snap / overflow-x scroll track.
		if ( preg_match( '/\b(?:swiper|slick|embla|keen-slider|glide|splide|flickity)\b|roledescription=["\']?carousel|\bsnap-x\b|overflow-x-(?:auto|scroll)/', $hay ) ) {
			return array( 'design' => 'carousel' );
		}
		// MASONRY — a CSS multi-column wall (`columns-N` / a `masonry` class): tiles of uneven heights.
		if ( preg_match( '/\b(?:columns-([1-6])|masonry)\b/', $cls . ' ' . $hay, $mm ) ) {
			return array( 'design' => 'masonry', 'columns' => self::wall_columns( $el, ! empty( $mm[1] ) ? $mm[1] : '3' ) );
		}
		// METRO — a bento mosaic: tiles carry VERTICAL spans (`row-span-2`), which a plain grid col-ratio can't
		// reproduce. (A grid with only horizontal col-spans stays 'grid' + col_ratio.)
		if ( preg_match( '/\b(?:[a-z]+:)?row-span-[2-6]\b/', $hay ) ) {
			$cols = method_exists( __CLASS__, 'grid_col_count' ) ? (int) self::grid_col_count( $el ) : 0;
			return array( 'design' => 'metro', 'columns' => (string) ( $cols >= 2 ? min( 6, $cols ) : 4 ) );
		}
		// …or a MANY-TRACK mosaic whose col-spans change from row to row (`grid-cols-12`: 8 | 4 then 4 | 8, at a fixed
		// `auto-rows-[240px]`): one col-ratio cannot hold two row patterns — metro on the reduced tracks (12 / gcd 4 = 3
		// columns, spans 2 | 1 / 1 | 2), the mapper dividing each span. Four tiles had rendered in one row at 10/40/40/10 (a
		// real-site audit).
		$tcols = (int) self::grid_col_count( $el );
		if ( $tcols >= 4 ) {
			$spans = array(); $rows = array(); $cur = 0; $rowp = array();
			foreach ( self::image_grid_tiles( $el ) as $t ) { $sp = self::tile_span( ' ' . self::cls( $t['el'] ) . ' ', 'col' ); $spans[] = $sp; $cur += $sp; $rowp[] = $sp; if ( $cur >= $tcols ) { $rows[] = implode( '/', $rowp ); $rowp = array(); $cur = 0; } }
			if ( $rowp ) { $rows[] = implode( '/', $rowp ); }
			$varies = count( array_unique( $rows ) ) > 1;
			if ( $varies && max( $spans ) > 1 ) {
				$g = $tcols; foreach ( $spans as $sp ) { $g = self::gcd_int( $g, $sp ); }
				if ( $g >= 1 && $tcols / $g <= 6 ) { return array( 'design' => 'metro', 'columns' => (string) ( $tcols / $g ), 'spanDiv' => $g ); }
			}
		}
		return $grid;
	}

	/** An ISOLATED text string reads like a post date: "Mar 5, 2026" / "5 March 2026" / "2 days ago" /
	 *  MM/DD/YYYY / YYYY-MM-DD. Checked on a single element's own text (NOT a concatenated card blob — the
	 *  converter's text() joins children WITHOUT spaces, which breaks the `\b`-anchored month match). */
	private static function looks_like_date( $t ) {
		$t = trim( (string) $t );
		if ( $t === '' || mb_strlen( $t ) > 40 ) { return false; }
		return (bool) ( preg_match( '/\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d{1,2}(?:,?\s*\d{4})?/i', $t )
			|| preg_match( '/\b\d{1,2}\s+(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d{4}\b/i', $t )
			|| preg_match( '/\b\d+\s+(?:min(?:ute)?|hour|day|week|month|year)s?\s+ago\b/i', $t )
			|| preg_match( '#^\s*\d{1,2}/\d{1,2}/\d{2,4}\s*$|^\s*\d{4}-\d{2}-\d{2}\s*$#', $t ) );
	}

	/** Does an element hold a DATE — a `<time>`, or a leaf child (`p`/`span`/`small`/`div`/`li`/`time`) whose
	 *  OWN text is a date. Per-element so the date isn't buried in a space-less concatenated card blob. */
	private static function has_date_signal( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( $el->getElementsByTagName( 'time' )->length > 0 ) { return true; }
		foreach ( array( 'time', 'span', 'p', 'small', 'div', 'li' ) as $tg ) {
			foreach ( $el->getElementsByTagName( $tg ) as $e ) {
				if ( $e->getElementsByTagName( '*' )->length > 1 ) { continue; } // leaf-ish only
				if ( self::looks_like_date( self::text( $e ) ) ) { return true; }
			}
		}
		return false;
	}

	/** A card cell carries a BLOG signal — a date (`<time>` / date text), an author byline, or a "Read
	 *  more"-style link — distinguishing a post card from a plain feature / service card. */
	private static function card_blog_signal( $k ) {
		if ( ! ( $k instanceof DOMElement ) ) { return false; }
		if ( self::has_date_signal( $k ) ) { return true; }
		// An author byline (checked per-element to avoid the concatenation trap).
		foreach ( array( 'span', 'p', 'small', 'div', 'a' ) as $tg ) {
			foreach ( $k->getElementsByTagName( $tg ) as $e ) {
				if ( $e->getElementsByTagName( '*' )->length > 1 ) { continue; }
				if ( preg_match( '/^\s*by\s+[A-Z][a-z]+/', trim( self::text( $e ) ) ) ) { return true; }
			}
		}
		// A blog-specific "read more" link (NOT the generic "learn more" a service card uses).
		foreach ( $k->getElementsByTagName( 'a' ) as $a ) {
			$at = strtolower( trim( self::text_no_icons( $a ) ) );
			if ( preg_match( '/^(?:read more|read article|read post|read story|continue reading|full (?:story|article))/', $at ) ) { return true; }
		}
		return false;
	}

	/** A BLOG / POST LISTING — a grid/flex of ≥2 cards, EACH a titled card, where nearly every card carries a
	 *  blog signal (date / author / read-more). Strict so a feature/service card grid stays a card_grid. */
	private static function is_posts_grid( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$cls = self::cls( $el );
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$is_grid = strpos( $cls, 'grid' ) !== false || strpos( $cls, 'flex' ) !== false
			|| strpos( $cs, 'display:flex' ) !== false || strpos( $cs, 'display:grid' ) !== false || strpos( $cs, 'display:inline-flex' ) !== false;
		if ( ! $is_grid ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		$cards = 0; $signal = 0; $with_img = 0;
		foreach ( $kids as $k ) {
			if ( ! ( $k instanceof DOMElement ) ) { continue; }
			$has_h = false;
			foreach ( array( 'h2', 'h3', 'h4', 'h5' ) as $h ) { if ( $k->getElementsByTagName( $h )->length > 0 ) { $has_h = true; break; } }
			if ( ! $has_h ) { continue; }
			$cards++;
			if ( self::card_blog_signal( $k ) ) { $signal++; }
			if ( $k->getElementsByTagName( 'img' )->length > 0 ) { $with_img++; }
		}
		// Most cells are titled cards, (nearly) all carry a blog signal, AND (nearly) all have a FEATURED IMAGE
		// — the image requirement is what separates a post-card feed from a date-stamped TIMELINE (imageless
		// vertical rail) and from a plain feature/service grid, since this recognizer sits above both.
		return $cards >= 2 && $cards >= count( $kids ) - 1 && $signal >= 2 && $signal >= $cards - 1 && $with_img >= $cards - 1;
	}

	/** Build the `posts` block — a DYNAMIC feed. Content is a live WP_Query (`post_type=post`), so only the
	 *  COUNT + detected layout/card design + which meta the source showed are carried, not the source cards. */
	private static function posts_grid_build( $el ) {
		$kids  = self::el_children( $el );
		$count = 0;
		foreach ( $kids as $k ) {
			if ( ! ( $k instanceof DOMElement ) ) { continue; }
			foreach ( array( 'h2', 'h3', 'h4', 'h5' ) as $h ) { if ( $k->getElementsByTagName( $h )->length > 0 ) { $count++; break; } }
		}
		$has_date   = self::has_date_signal( $el );
		$has_author = false;
		foreach ( array( 'span', 'p', 'small', 'div', 'a' ) as $tg ) {
			foreach ( $el->getElementsByTagName( $tg ) as $e ) {
				if ( $e->getElementsByTagName( '*' )->length > 1 ) { continue; }
				if ( preg_match( '/^\s*by\s+[A-Z][a-z]+/', trim( self::text( $e ) ) ) ) { $has_author = true; break 2; }
			}
		}
		$doc  = $el->ownerDocument;
		$html = $doc ? self::strip_cs( trim( (string) $doc->saveHTML( $el ) ) ) : '';
		return array(
			't'      => 'posts',
			'role'   => 'posts',
			'count'  => max( 3, $count ),
			'meta'   => array( 'date' => (bool) $has_date, 'author' => (bool) $has_author ),
			'design' => self::detect_posts_design( $el, $count ),
			'html'   => $html,
		);
	}

	/**
	 * Classify the SOURCE blog listing's LAYOUT + CARD STYLE → the closest `posts` shortcode design. Returns
	 * `{ layout_mode, card_style, columns }`. layout_mode = grid|list|masonry|slider; card_style = the image
	 * placement (standard=image-top, side-left=image-beside-text, overlay=text-over-image, minimal=no image).
	 */
	private static function detect_posts_design( $el, $count ) {
		$out = array( 'layout_mode' => 'grid', 'card_style' => 'standard', 'columns' => 3 );
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$scope = $el;
		for ( $i = 0; $i < 2 && $scope->parentNode instanceof DOMElement; $i++ ) { $scope = $scope->parentNode; }
		$doc = $el->ownerDocument;
		$hay = strtolower( (string) ( $doc ? $doc->saveHTML( $scope ) : '' ) );
		$cls = strtolower( self::cls( $el ) );

		// LAYOUT — slider (auto-scroll / JS slider / snap track) → slider; CSS multi-column → masonry; a single
		// stacked column of wide cards → list; else grid.
		if ( preg_match( '/\bmarquee\b|animate-marquee|\b(?:swiper|slick|embla|splide|glide|keen-slider|flickity)\b|roledescription=["\']?carousel|\bsnap-x\b|overflow-x-(?:auto|scroll)/', $hay ) ) {
			$out['layout_mode'] = 'slider';
		} elseif ( preg_match( '/\bcolumns-[1-6]\b|\bmasonry\b/', $cls . ' ' . $hay ) ) {
			$out['layout_mode'] = 'masonry';
		} elseif ( preg_match( '/\bgrid-cols-1\b/', $cls ) || ( strpos( $cls, 'flex-col' ) !== false && strpos( $cls, 'md:flex-row' ) === false ) ) {
			$out['layout_mode'] = 'list';
		}
		// COLUMNS — from the grid's column count (grid layout).
		$cols = method_exists( __CLASS__, 'grid_col_count' ) ? (int) self::grid_col_count( $el ) : 0;
		if ( $cols >= 1 ) { $out['columns'] = min( 6, max( 1, $cols ) ); }

		// CARD STYLE — inferred from the FIRST card's image placement.
		$card = null;
		foreach ( self::el_children( $el ) as $k ) {
			if ( $k instanceof DOMElement ) { foreach ( array( 'h2', 'h3', 'h4', 'h5' ) as $h ) { if ( $k->getElementsByTagName( $h )->length > 0 ) { $card = $k; break 2; } } }
		}
		if ( $card instanceof DOMElement ) {
			$has_img = $card->getElementsByTagName( 'img' )->length > 0;
			$ccls    = strtolower( self::cls( $card ) );
			if ( ! $has_img ) {
				$out['card_style'] = 'minimal';
			} elseif ( 'list' === $out['layout_mode'] || preg_match( '/\bgrid-cols-2\b|\bmd:flex-row\b|\bflex-row\b/', $ccls ) ) {
				$out['card_style'] = 'side-left'; // image beside the content (horizontal card)
			} else {
				// Text laid OVER the image (an `absolute inset-0` overlay holding the heading) → overlay card.
				foreach ( $card->getElementsByTagName( 'div' ) as $d ) {
					$dc = strtolower( self::cls( $d ) );
					if ( strpos( $dc, 'absolute' ) !== false && ( strpos( $dc, 'inset-0' ) !== false || strpos( $dc, 'bottom-0' ) !== false )
						&& $d->getElementsByTagName( 'h2' )->length + $d->getElementsByTagName( 'h3' )->length + $d->getElementsByTagName( 'h4' )->length > 0 ) {
						$out['card_style'] = 'overlay'; break;
					}
				}
			}
		}
		return $out;
	}

	private static function is_logo_strip( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		// A logo strip is chrome (brand marks in a row), never a content section — no headings inside.
		foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) {
			if ( $el->getElementsByTagName( $h )->length > 0 ) { return false; }
		}
		// Classic: ≥2 <img> brand marks — but NOT a photo GALLERY. Logo marks are contained/small
		// (`object-contain`, no cover fill); gallery tiles are `object-cover` cover photos filling their tile.
		// Bowing to logo_strip on any ≥2-image container wrongly stole captioned photo galleries (they became
		// loose media_image instead of a gallery), so require the images to be logo-like, not cover fills.
		$imgs = $el->getElementsByTagName( 'img' );
		if ( $imgs->length >= 2 ) {
			$cover = 0;
			foreach ( $imgs as $im ) {
				$ic = ' ' . strtolower( self::cls( $im ) ) . ' ';
				if ( strpos( $ic, 'object-cover' ) !== false || strpos( $ic, 'object-fill' ) !== false
					|| ( strpos( $ic, 'w-full' ) !== false && strpos( $ic, 'h-full' ) !== false ) ) { $cover++; }
			}
			if ( $cover < (int) ceil( $imgs->length * 0.5 ) ) { return true; } // contained marks → a real logo strip
			// else: cover-photo grid → not a logo strip; let image_grid claim it as a gallery.
		}
		// ≥2 BRAND icons (iconify simple-icons/logos, or fa-brands/si-/cib- classes) → a "trusted by" logo row.
		if ( self::logo_strip_brand_icons( $el ) >= 2 ) { return true; }
		// Inline-SVG / icon-font brand strip: ≥3 sibling items, each an icon + a short brand LABEL
		// (`<span><svg/> Unity</span>` ×5 — the AI-page/Tailwind "Trusted by" pattern). The label
		// requirement separates a real logo row from a label-less social-icon row; the ≥3 count keeps a
		// 1-2-icon accent from matching. Was image-only, so these strips were dropped (only the labels
		// survived, via the safety net) instead of becoming a native logo_grid.
		if ( self::logo_strip_icon_items( $el ) >= 3 ) { return true; }
		// TEXT brand marquee (no icons): >=4 sibling items each a SHORT brand-name label (`<div>YOUHODLER</div>`),
		// usually DUPLICATED for a scroll loop and/or clipped by an `overflow-hidden` wrapper. Distinguished from
		// a nav / feature row by short labels, no buttons/headings, and the marquee tell (dup labels or clip).
		// Without this the pure-text logo cloud fell through and each name stacked vertically, tripled.
		$labels = self::logo_strip_text_labels( $el );
		if ( count( $labels ) >= 4 ) {
			$dup = count( array_unique( $labels ) ) < count( $labels );
			$clip = false; $p = $el->parentNode; $d = 0;
			while ( $p instanceof DOMElement && $d < 3 ) { if ( strpos( ' ' . self::cls( $p ) . ' ', 'overflow-hidden' ) !== false ) { $clip = true; break; } $p = $p->parentNode; $d++; }
			if ( $dup || $clip ) { return true; }
		}
		return false;
	}

	/** The SHORT brand-name labels of a horizontal flex row where EVERY child is a clean label item (span/div/
	 *  a/li, 2-40 chars, no button/heading/img/p) - a pure-text logo strip. [] when any child breaks the shape. */
	private static function logo_strip_text_labels( $el ) {
		$out = array();
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		$c = ' ' . self::cls( $el ) . ' ';
		if ( strpos( $c, 'flex' ) === false || strpos( $c, 'flex-col' ) !== false ) { return array(); }
		foreach ( $el->childNodes as $ch ) {
			if ( XML_ELEMENT_NODE !== $ch->nodeType ) { continue; }
			if ( ! in_array( strtolower( $ch->tagName ), array( 'span', 'div', 'a', 'li' ), true ) ) { return array(); }
			if ( $ch->getElementsByTagName( 'button' )->length > 0 ) { return array(); }
			foreach ( array( 'h1','h2','h3','h4','h5','h6','p','ul','img' ) as $bad ) { if ( $ch->getElementsByTagName( $bad )->length > 0 ) { return array(); } }
			$t = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $ch ) ) );
			if ( mb_strlen( $t ) < 2 || mb_strlen( $t ) > 40 ) { return array(); }
			$out[] = $t;
		}
		return $out;
	}

	/**
	 * Count a strip's icon+label brand items — direct children each carrying exactly one brand icon (inline
	 * <svg> or an icon-font <i>) plus a SHORT text label (a brand name), and no button / heading / sentence.
	 * The signal that a flex row is a "trusted by" logo strip rather than a nav / social row / feature list.
	 */
	private static function logo_strip_icon_items( $el ) {
		$n = 0;
		foreach ( $el->childNodes as $ch ) {
			if ( XML_ELEMENT_NODE !== $ch->nodeType ) { continue; }
			if ( ! in_array( strtolower( $ch->tagName ), array( 'span', 'div', 'a', 'li' ), true ) ) { continue; }
			// A brand mark = an inline <svg>, an icon-font <i>, OR an iconify web-component (<iconify-icon
			// icon="simple-icons:unity">) — the last is how a Tailwind/React "trusted by" row carries brand
			// logos, and it renders in shadow DOM so no <svg> survives the capture. Count it so is_logo_strip
			// claims the row (else it fell to the feature_list recognizer with the marks stripped).
			if ( ( $ch->getElementsByTagName( 'svg' )->length + $ch->getElementsByTagName( 'i' )->length + $ch->getElementsByTagName( 'iconify-icon' )->length ) < 1 ) { continue; }
			if ( $ch->getElementsByTagName( 'button' )->length > 0 ) { continue; }
			$txt = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $ch ) ) );
			$len = mb_strlen( $txt );
			if ( $len < 2 || $len > 40 ) { continue; } // a short brand label — not empty, not a sentence
			$n++;
		}
		return $n;
	}

	/** Extract a logo strip's marks (each <img> → { url, name, link_url, link_target, svg }) in document order. */
	private static function logo_strip_items( $el ) {
		$out = array();
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		foreach ( $el->getElementsByTagName( 'img' ) as $img ) {
			$src = trim( (string) $img->getAttribute( 'src' ) );
			if ( '' === $src ) { $src = trim( (string) $img->getAttribute( 'data-src' ) ); }
			if ( '' === $src ) { continue; }
			$name   = trim( (string) $img->getAttribute( 'alt' ) );
			$link   = '';
			$target = '_blank';
			// Walk up to the enclosing <a> (a linked brand mark), stopping at the strip itself.
			$p = $img->parentNode;
			while ( $p && XML_ELEMENT_NODE === $p->nodeType ) {
				if ( strtolower( $p->tagName ) === 'a' ) {
					$link = trim( (string) $p->getAttribute( 'href' ) );
					if ( (string) $p->getAttribute( 'target' ) === '_self' ) { $target = '_self'; }
					break;
				}
				if ( $p === $el ) { break; }
				$p = $p->parentNode;
			}
			$out[] = array( 'url' => $src, 'name' => $name, 'link_url' => $link, 'link_target' => $target, 'svg' => '' );
		}
		// Inline-SVG / icon brand strip (no <img>): each sibling item's brand icon svg + its text label.
		if ( empty( $out ) ) {
			// The strip's text colour → tint iconify brand marks to match (a "trusted by" row on a dark hero is
			// white/light; simple-icons default to black, which would vanish). Hex for the iconify ?color= param.
			$strip_hex = self::color_to_hex( self::sc_css( $el, 'color' ) );
			foreach ( $el->childNodes as $ch ) {
				if ( XML_ELEMENT_NODE !== $ch->nodeType ) { continue; }
				if ( ! in_array( strtolower( $ch->tagName ), array( 'span', 'div', 'a', 'li' ), true ) ) { continue; }
				$sv   = $ch->getElementsByTagName( 'svg' )->item( 0 );
				$svg  = ( $sv && $ch->ownerDocument ) ? self::strip_cs( trim( (string) $ch->ownerDocument->saveHTML( $sv ) ) ) : '';
				$name = trim( preg_replace( '/\s+/', ' ', (string) self::text_no_icons( $ch ) ) );
				// No inline <svg> but an <iconify-icon icon="prefix:name"> (a React/Tailwind brand mark, rendered
				// in shadow DOM so it never inlines) → the iconify SVG API gives a real, self-describing brand logo:
				// https://api.iconify.design/<prefix>/<name>.svg[?color=<hex>]. Emitted as the logo image URL so the
				// logo_grid renders an actual mark instead of a bare name (or a dropped feature_list item).
				$icon_url = '';
				if ( '' === $svg ) {
					$ii = $ch->getElementsByTagName( 'iconify-icon' )->item( 0 );
					if ( $ii instanceof DOMElement ) {
						$icon = strtolower( trim( (string) $ii->getAttribute( 'icon' ) ) );
						if ( preg_match( '#^([a-z0-9]+(?:-[a-z0-9]+)*):([a-z0-9]+(?:-[a-z0-9]+)*)$#', $icon, $mm ) ) {
							// height=32 → the iconify API renders the SVG at 32px (its 16px default left logos tiny);
							// the logo_grid still controls the on-page size via its own CSS.
							$icon_url = 'https://api.iconify.design/' . $mm[1] . '/' . $mm[2] . '.svg?height=32';
							if ( '' !== $strip_hex ) { $icon_url .= '&color=' . rawurlencode( $strip_hex ); }
						}
					}
				}
				if ( $svg === '' && $icon_url === '' && $name === '' ) { continue; }
				$link = ''; $target = '_blank';
				if ( strtolower( $ch->tagName ) === 'a' ) {
					$link = trim( (string) $ch->getAttribute( 'href' ) );
					if ( (string) $ch->getAttribute( 'target' ) === '_self' ) { $target = '_self'; }
				} else {
					$a = $ch->getElementsByTagName( 'a' )->item( 0 );
					if ( $a ) { $link = trim( (string) $a->getAttribute( 'href' ) ); }
				}
				// `label`: the name is VISIBLE TEXT beside the mark (not an <img alt>), so the logo_grid shows it — an iconify
				// mark resolved to an API image URL is still a mark, not a wordmark. JS: logoStripItems.
				$out[] = array( 'url' => $icon_url, 'name' => $name, 'link_url' => $link, 'link_target' => $target, 'svg' => $svg, 'label' => ( '' !== $name ) );
			}
		}
		return $out;
	}

	/** The strip ROW inside a matched logo-strip element: the deepest descendant that still holds every <img> / brand mark
	 *  (the flex row of marks), or the element itself. */
	private static function logo_strip_row( $el ) {
		$node = $el; $guard = 0;
		$count = function ( $n ) { return $n->getElementsByTagName( 'img' )->length + $n->getElementsByTagName( 'svg' )->length + $n->getElementsByTagName( 'iconify-icon' )->length; };
		$total = $count( $el );
		if ( $total < 2 ) { return $el; }
		while ( $guard++ < 6 ) {
			$next = null;
			foreach ( self::el_children( $node ) as $k ) { if ( $count( $k ) === $total ) { $next = $k; break; } }
			if ( ! ( $next instanceof DOMElement ) ) { break; }
			// stop at the row: a node whose children are the ITEMS (≥2 children each holding a mark)
			$node = $next;
			$item_kids = 0; foreach ( self::el_children( $node ) as $k ) { if ( $count( $k ) >= 1 ) { $item_kids++; } }
			if ( $item_kids >= 2 ) { break; }
		}
		return $node;
	}

	/** Build the logo-strip block: a native `logo_grid` when ≥2 VISUAL logos (svg or img) extract, else the
	 *  verbatim strip. (A name-only extraction — icon-font with no resolvable mark — falls to verbatim.) */
	private static function logo_strip_build( $el ) {
		$logos  = self::logo_strip_items( $el );
		$visual = 0;
		foreach ( $logos as $l ) { if ( ! empty( $l['svg'] ) || ! empty( $l['url'] ) ) { $visual++; } }
		if ( $visual >= 2 ) {
			// The matched element may be the strip's WRAPPER (a container holding a caption <p> + the flex row of marks):
			// the ROW is the marks' common ancestor — the treatment (gap / opacity / item) is measured there, and every
			// text sibling around it (the "Trusted by …" caption) is carried as its own text block instead of dropped
			// (a real-site audit: the caption vanished and the row measured the wrapper's gap:normal).
			$row = self::logo_strip_row( $el ); $captions_before = array(); $captions_after = array(); $seen_row = false;
			if ( $row !== $el ) {
				foreach ( self::el_children( $el ) as $kid ) {
					if ( $kid === $row || self::is_ancestor( $kid, $row ) ) { $seen_row = true; continue; }
					$kt = trim( preg_replace( '/\s+/u', ' ', self::text_no_icons( $kid ) ) );
					if ( '' === $kt || $kid->getElementsByTagName( 'img' )->length || $kid->getElementsByTagName( 'svg' )->length ) { continue; }
					$blk = array( 't' => 'text', 'role' => 'text', 'cls' => self::cls( $kid ), 'cs' => (string) $kid->getAttribute( 'data-sc-cs' ), 'maxWidth' => '', 'text' => $kt, 'html' => self::leaf_text_html( $kid, $kt ), 'linkCs' => self::leaf_link_cs( $kid ) );
					if ( preg_match( '/text-center/', ' ' . self::cls( $kid ) . ' ' ) || 'center' === strtolower( trim( self::sc_css( $kid, 'text-align' ) ) ) ) { $blk['align'] = 'center'; }
					if ( $seen_row ) { $captions_after[] = $blk; } else { $captions_before[] = $blk; }
				}
				$el = $row;
			}
			// Carry the source strip's own treatment so the logo_grid matches it instead of the shortcode
			// defaults: the inter-logo GAP (`gap-8` = 32px), the mark SIZE (the icons are 1em at the strip's
			// font-size, e.g. `text-xl` = 20px — the 48px default made them oversized), the OPACITY dim
			// (`opacity-70`), and GRAYSCALE.
			$cls = ' ' . self::cls( $el ) . ' ';
			// The MEASURED desktop gap first (a `gap-8 md:gap-16` strip is 64px at 1440 — the bare class is the phone value); the class only when
			// nothing was captured. JS: logoStripTreatment.
			$gap = '';
			if ( ( $gc = self::sc_css( $el, 'gap' ) ) !== '' && preg_match( '/^([0-9.]+)px/', $gc, $gpm ) ) { $gap = (string) (int) round( (float) $gpm[1] ); }
			elseif ( preg_match( '/(?:^|\s)gap-(\d+)(?:\s|$)/', $cls, $gm ) ) { $gap = (string) ( (int) $gm[1] * 4 ); }
			$opacity = '';
			if ( preg_match( '/(?:^|\s)opacity-(\d{1,3})(?:\s|$)/', $cls, $om ) ) { $opacity = rtrim( rtrim( sprintf( '%.2f', (int) $om[1] / 100 ), '0' ), '.' ); }
			elseif ( ( $oc = self::sc_css( $el, 'opacity' ) ) !== '' && (float) $oc > 0 && (float) $oc < 1 ) { $opacity = (string) (float) $oc; }
			$grayscale = ( strpos( $cls, ' grayscale ' ) !== false ) || ( stripos( self::sc_css( $el, 'filter' ), 'grayscale' ) !== false );
			$isize = '';
			foreach ( $el->getElementsByTagName( 'span' ) as $sp ) {
				$fs = self::sc_css( $sp, 'font-size' );
				if ( preg_match( '/^([0-9.]+)px$/', $fs, $fm ) ) { $isize = (string) (int) round( (float) $fm[1] * 1.2 ); break; }
			}
			// The ITEM's own treatment (a `<span class="text-xl font-bold flex items-center gap-2">` mark + name): its mark→label gap, its
			// padding (the shortcode's .35rem default grew a 28px row to 35px) and the label's size / weight / line-height —
			// all scoped onto the logo_grid (n_logo_grid) so the converted row measures like the source's. JS: logoStripTreatment.
			$item = array();
			foreach ( self::el_children( $el ) as $it ) {
				if ( '' === trim( (string) self::text_no_icons( $it ) ) ) { continue; }
				$g = self::sc_css( $it, 'gap' ); if ( '' === $g ) { $g = self::sc_css( $it, 'column-gap' ); }
				if ( preg_match( '/^([0-9.]+)px/', $g, $gm ) ) { $item['gap'] = (int) round( (float) $gm[1] ); }
				$pd = self::sc_css( $it, 'padding' ); if ( preg_match( '/^[0-9.]+px(?:\s+[0-9.]+px){0,3}$/', $pd ) ) { $item['pad'] = $pd; } elseif ( '' === $pd ) { $item['pad'] = '0px'; }
				foreach ( array( 'font-size' => 'fs', 'font-weight' => 'fw', 'line-height' => 'lh' ) as $pr => $k ) { $v = self::sc_css( $it, $pr ); if ( '' !== $v && preg_match( '/^[0-9.]+(?:px)?$/', $v ) ) { $item[ $k ] = $v; } }
				break;
			}
			// an <img> strip: the mark height is the image's MEASURED height (`h-8` = 32px) — the 48px default drew every
			// logo half again as big as the source's
			if ( '' === $isize ) {
				foreach ( $el->getElementsByTagName( 'img' ) as $im ) {
					$ih = self::sc_css( $im, 'height' );
					if ( preg_match( '/^([0-9.]+)px$/', $ih, $ihm ) && (float) $ihm[1] >= 12 && (float) $ihm[1] <= 96 ) { $isize = (string) (int) round( (float) $ihm[1] ); break; }
				}
			}
			// the dim on each ITEM (`opacity-80` per child) when the strip itself carries none
			if ( '' === $opacity ) {
				$kids = self::el_children( $el ); $dims = array();
				foreach ( $kids as $it ) {
					$ic = ' ' . self::cls( $it ) . ' ';
					if ( preg_match( '/(?:^|\s)opacity-(\d{1,3})(?:\s|$)/', $ic, $om2 ) ) { $dims[] = (int) $om2[1] / 100; }
					elseif ( ( $oc2 = self::sc_css( $it, 'opacity' ) ) !== '' && (float) $oc2 > 0 && (float) $oc2 < 1 ) { $dims[] = (float) $oc2; }
				}
				if ( $kids && count( $dims ) >= (int) ceil( count( $kids ) / 2 ) ) { $opacity = rtrim( rtrim( sprintf( '%.2f', min( $dims ) ), '0' ), '.' ); }
			}
			$lg = array( 't' => 'logo_grid', 'role' => 'logo_grid', 'logos' => $logos,
				'gap' => $gap, 'opacity' => $opacity, 'grayscale' => $grayscale ? 'yes' : 'no', 'iconSize' => $isize, 'item' => $item );
			if ( $captions_before || $captions_after ) { return array_merge( $captions_before, array( $lg ), $captions_after ); }
			return $lg;
		}
		// TEXT-only brand marquee (no logo images): logo_grid needs a visual mark, so emit the DEDUPED brand
		// names as ONE centered inline row (a clean 'trusted by' line) instead of the raw marquee - which would
		// otherwise render each name stacked vertically AND repeated (the scroll-loop duplicates).
		$names = array();
		foreach ( $logos as $l ) { $nm = trim( (string) ( $l['name'] ?? '' ) ); if ( $nm !== '' && ! in_array( $nm, $names, true ) ) { $names[] = $nm; } }
		if ( count( $names ) >= 3 ) {
			$row = implode( '&nbsp;&nbsp;&nbsp;&middot;&nbsp;&nbsp;&nbsp;', array_map( 'esc_html', $names ) );
			return array( 't' => 'text', 'role' => 'text', 'cls' => 'sc-logo-strip', 'align' => 'center', 'text' => implode( '   ', $names ), 'html' => '<p class="sc-logo-strip">' . $row . '</p>' );
		}
		// Fallback (NOTHING DROPPED): keep the strip verbatim if no logos could be extracted.
		$doc = $el->ownerDocument;
		$v   = $doc ? self::strip_cs( trim( (string) $doc->saveHTML( $el ) ) ) : '';
		return '' !== $v ? array( 't' => 'html', 'role' => 'code', 'html' => '<div class="sc-tw">' . $v . '</div>' ) : null;
	}

	/** The button-styled <a>/<button> descendants of a band (Tailwind or computed-style). */
	private static function cta_buttons( $el ) {
		$out = array();
		if ( ! ( $el instanceof DOMElement ) ) { return $out; }
		foreach ( array( 'a', 'button' ) as $t ) {
			foreach ( $el->getElementsByTagName( $t ) as $b ) {
				if ( self::is_button( $b ) || self::cs_is_button( $b ) ) { $out[] = $b; }
			}
		}
		return $out;
	}

	/**
	 * A CALL-TO-ACTION band: a CENTERED wrapper with exactly ONE heading (h2–h6, NOT a hero h1), optional
	 * subtext, and exactly ONE button, with no other media / list / table / form / column content. TIGHT so
	 * a hero (h1 + media + 2 buttons), a feature grid, or a plain heading intro never qualifies.
	 */
	private static function is_cta_band( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		$tag = strtolower( $el->tagName );
		if ( ! in_array( $tag, array( 'div', 'section' ), true ) ) { return false; }
		// Centered band (Tailwind text-center or computed text-align:center).
		$cls = self::cls( $el );
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$centered = ( strpos( $cls, 'text-center' ) !== false ) || (bool) preg_match( '/text-align:\s*center/', $cs );
		if ( ! $centered ) { return false; }
		// Exactly one heading, and NOT a hero <h1> (a CTA uses h2–h6).
		if ( $el->getElementsByTagName( 'h1' )->length > 0 ) { return false; }
		$nh = 0;
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { $nh += $el->getElementsByTagName( $h )->length; }
		if ( 1 !== $nh ) { return false; }
		// No media / list / table / form content (would be dropped, or isn't a simple CTA).
		foreach ( array( 'img', 'picture', 'video', 'iframe', 'ul', 'ol', 'table', 'form', 'input', 'select', 'textarea' ) as $t ) {
			if ( $el->getElementsByTagName( $t )->length > 0 ) { return false; }
		}
		// Exactly ONE button (the native call_to_action has a single button slot; a 2-button CTA stays
		// assembled so the 2nd button is never dropped).
		$btns = self::cta_buttons( $el );
		if ( 1 !== count( $btns ) ) { return false; }
		// Any <svg> present must be INSIDE the button (an icon) — standalone svg art would be dropped.
		foreach ( $el->getElementsByTagName( 'svg' ) as $sv ) {
			$inside = false;
			$p = $sv->parentNode;
			while ( $p && XML_ELEMENT_NODE === $p->nodeType ) { if ( $p === $btns[0] ) { $inside = true; break; } if ( $p === $el ) { break; } $p = $p->parentNode; }
			if ( ! $inside ) { return false; }
		}
		// Reject a real multi-column / card-grid band (not a simple CTA).
		foreach ( self::el_children( $el ) as $k ) {
			if ( self::is_card_grid( $k ) || self::is_layout_row( $k ) ) { return false; }
		}
		// Must carry heading text.
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $t ) {
			$n = $el->getElementsByTagName( $t )->item( 0 );
			if ( $n ) { return '' !== self::text( $n ); }
		}
		return false;
	}

	/** Build the CTA block { title, message(html), button_label/link/target, heading level/cls/cs }. */
	private static function cta_build( $el ) {
		$h = null;
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $t ) { $n = $el->getElementsByTagName( $t )->item( 0 ); if ( $n ) { $h = $n; break; } }
		if ( ! $h ) { return null; }
		$title = self::text( $h ); // the CTA view prints the title with esc_html → PLAIN TEXT, not markup
		if ( '' === $title ) { return null; }
		$btns  = self::cta_buttons( $el );
		$btn   = $btns ? $btns[0] : null;
		$label = $btn ? self::text_no_icons( $btn ) : '';
		$href  = '#';
		$target = '_self';
		if ( $btn ) {
			if ( strtolower( $btn->tagName ) === 'a' && $btn->getAttribute( 'href' ) !== '' ) { $href = (string) $btn->getAttribute( 'href' ); }
			if ( (string) $btn->getAttribute( 'target' ) === '_blank' ) { $target = '_blank'; }
		}
		// Subtext: every non-empty paragraph (inline links preserved), in document order.
		$parts = array();
		foreach ( $el->getElementsByTagName( 'p' ) as $p ) {
			if ( '' === self::text( $p ) ) { continue; }
			$parts[] = '<p>' . self::clean_inline_html( $p ) . '</p>';
		}
		return array(
			't'             => 'cta',
			'role'          => 'cta',
			'title'         => $title,
			'message'       => implode( "\n", $parts ),
			'button_label'  => $label,
			'button_link'   => $href,
			'button_target' => $target,
			// The call_to_action view always renders the title as an <h2>, so scope the carried heading
			// style to `#cta h2` (not the source level) or the rule wouldn't match the rendered element.
			'level'         => 2,
			'cls'           => self::cls( $h ),
			'cs'            => (string) $h->getAttribute( 'data-sc-cs' ),
			// The button's own source classes + resolved computed style → the mapper paints the
			// call_to_action's `.btn.btn-1` with the source fill (so a distinctive amber/secondary
			// button isn't flattened to the shortcode's default look — no fidelity regression).
			'btn_cls'       => $btn ? self::cls( $btn ) : '',
			'btn_cs'        => $btn ? (string) $btn->getAttribute( 'data-sc-cs' ) : '',
		);
	}

	/**
	 * If $el (or a descendant div) is an OVERLAPPING ROUND-AVATAR STACK, return the avatar image URLs in
	 * document order; else an empty array. The signal that separates a reviewer stack from a normal image
	 * row is (a) OVERLAP — a Tailwind `-space-x-*` on the stack, or a negative `margin-left` on the avatar
	 * items/container (computed `data-sc-cs`) — AND (b) ROUND avatar imgs (>=2 imgs that are, or whose
	 * wrapper is, a circle: `rounded-full` / `border-radius:9999px|50%`). Both are required so a plain row
	 * of rectangular thumbnails can't misfire. Mirrors the JS capture-extract avatar detection.
	 *
	 * @param DOMElement $el
	 * @return array<string>
	 */
	/**
	 * Does $el read as a TIGHT reviewer-avatar wrapper (the stack itself, or the small "avatars + rating
	 * caption" cluster) — as opposed to a whole content COLUMN that merely contains a stack somewhere deep?
	 * Requires the overlapping round stack AND rejects any element that carries a heading (h1–h6) or a long
	 * body of text (> 160 chars) — so a hero's text+CTA column (h1 + prose) is never swallowed. This keeps
	 * the hero band decomposing normally (special_heading + buttons) while the compact stack is claimed.
	 *
	 * @param DOMElement $el
	 * @return bool
	 */
	private static function is_avatar_group( $el ) {
		if ( count( self::avatar_stack_urls( $el ) ) < 2 ) { return false; }
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		for ( $i = 1; $i <= 6; $i++ ) { if ( $el->getElementsByTagName( 'h' . $i )->length > 0 ) { return false; } }
		$t = trim( (string) preg_replace( '/\s+/', ' ', self::text( $el ) ) );
		if ( mb_strlen( $t ) > 160 ) { return false; } // a rating caption is short; a content column is long
		// a SKINNED STRIP of ≥ 3 groups (a trust card: faces + copy | divider | stars + score) is a layout row wearing its skin — the
		// avatar group claims only the faces' own cell inside it; claimed whole it became an avatar + a verbatim blob (a finding)
		if ( count( self::el_children( $el ) ) >= 3 && self::read_card_skin( $el ) ) { return false; }
		return true;
	}

	private static function avatar_stack_urls( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return array(); }
		$cands = array( $el );
		foreach ( $el->getElementsByTagName( 'div' ) as $d ) { $cands[] = $d; }
		foreach ( $cands as $c ) {
			$imgs = $c->getElementsByTagName( 'img' );
			if ( $imgs->length < 2 ) { continue; }
			$cls     = self::cls( $c );
			$ccs     = (string) $c->getAttribute( 'data-sc-cs' );
			$overlap = (bool) preg_match( '/-space-x-\d/', $cls );
			if ( ! $overlap && '' !== $ccs && preg_match( '/margin-left:\s*-/', $ccs ) ) { $overlap = true; }
			$urls  = array();
			$round = 0;
			$small = 0;
			foreach ( $imgs as $im ) {
				$icls = self::cls( $im );
				$wrap = ( $im->parentNode instanceof DOMElement ) ? $im->parentNode : null;
				$wcls = $wrap ? self::cls( $wrap ) : '';
				$wcs  = $wrap ? (string) $wrap->getAttribute( 'data-sc-cs' ) : '';
				$ics  = (string) $im->getAttribute( 'data-sc-cs' );
				if ( preg_match( '/rounded-full/', $icls . ' ' . $wcls ) || preg_match( '/border-radius:\s*(?:9999px|50%)/', $ics . ' ' . $wcs ) ) { $round++; }
				// Small: a low Tailwind sizing step (w-6..w-16 / h-6..h-16) on the img or its wrapper, or a
				// computed width/height <= 72px. Keeps genuine ~24-64px avatars in, big media rows out.
				if ( preg_match( '/\b[wh]-(?:[4-9]|1[0-6])\b/', $icls . ' ' . $wcls ) ) { $small++; }
				elseif ( preg_match( '/(?:^|;)\s*(?:width|height):\s*(\d+(?:\.\d+)?)px/', $ics . ' ' . $wcs, $sm ) && (float) $sm[1] <= 72 ) { $small++; }
				// Overlap can also surface as a negative margin on the avatar ITEM (space-x compiles to child margins).
				if ( ! $overlap && preg_match( '/margin-left:\s*-/', $ics . ' ' . $wcs ) ) { $overlap = true; }
				$src = trim( (string) $im->getAttribute( 'src' ) );
				if ( '' === $src ) { $src = trim( (string) $im->getAttribute( 'data-src' ) ); }
				if ( '' !== $src ) { $urls[] = $src; }
			}
			if ( $overlap && $round >= 2 && $small >= 2 && count( $urls ) >= 2 ) { return $urls; }
		}
		return array();
	}

	/**
	 * Build the block(s) for an avatar stack: a native `avatar` GROUP block (the images + a "+N" counter
	 * parsed from the adjacent text) PLUS, when a rating/label survives, a verbatim code block for the
	 * stars + score text (avatar stack stripped out). Mirrors the JS ratingRowNode (avatar group + the
	 * verbatim stars/score). Returns null if it isn't a genuine stack.
	 *
	 * @param DOMElement $el
	 * @return array|null
	 */
	private static function avatar_group_build( $el ) {
		$urls = self::avatar_stack_urls( $el );
		if ( count( $urls ) < 2 ) { return null; }
		$urls  = array_slice( $urls, 0, 8 );
		$label = trim( (string) preg_replace( '/\s+/', ' ', self::text( $el ) ) );
		$extra = '';
		// A "+N / 500+ / 2K+" social-proof counter for the stack, from the adjacent caption.
		if ( preg_match( '/(\d[\d,.]*\s*[kKmM]?\s*\+)/', $label, $m ) ) { $extra = (string) preg_replace( '/\s+/', '', $m[1] ); }
		$blocks   = array();
		$av = array( 't' => 'avatar', 'role' => 'avatar', 'avatars' => $urls, 'extra_count' => $extra, 'label' => $label );
		$rating = self::avatar_group_rating_html( $el );
		if ( '' === $rating ) { return array( $av ); }
		$rt = array( 't' => 'html', 'role' => 'code', 'verbatim' => true, 'html' => '<div class="sc-tw">' . $rating . '</div>' ); // verbatim: a star glyph row + score is an inline cluster, not a layout to mirror
		// The stack and its caption SIDE BY SIDE when the source lays them so (`flex items-center gap-4` around the `-space-x-3`
		// faces + the stars / text) → ONE nowrap row with the source gap and vertical centring — they were emitted as two stacked
		// block rows, the text beneath the faces (a fixture from the feed)
		$ecs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $ecs ) && ! preg_match( '/flex-direction:\s*column/i', $ecs ) ) {
			$gap = preg_match( '/(?:^|;)\s*(?:gap|column-gap):\s*([0-9.]+)px/i', $ecs, $gm ) ? (int) round( (float) $gm[1] ) : 16;
			$m = self::el_margin( $el );
			return array( array( 't' => 'row', 'role' => 'columns', 'valign' => 'middle', 'gap' => $gap, 'mt' => (float) ( $m['top'] ?? 0 ), 'mb' => (float) ( $m['bottom'] ?? 0 ), 'nowrap' => true, 'contentSized' => true, 'cols' => array( array( 'cls' => '', 'blocks' => array( $av ) ), array( 'cls' => '', 'blocks' => array( $rt ) ) ) ) );
		}
		$blocks[] = $av; $blocks[] = $rt;
		return $blocks;
	}

	/**
	 * The adjacent rating/label markup (stars glyphs + "4.9/5 from 500+ …") as verbatim HTML, with the
	 * overlapping avatar stack removed (those become the `avatar` shortcode). Empty when nothing textual
	 * remains beside the faces. Mirrors the JS capture-extract, which strips the avatar imgs and keeps the
	 * stars/score verbatim.
	 *
	 * @param DOMElement $el
	 * @return string
	 */
	private static function avatar_group_rating_html( $el ) {
		$doc = $el->ownerDocument;
		if ( ! $doc ) { return ''; }
		$clone   = $el->cloneNode( true );
		$removed = false;
		// Remove any overlapping avatar-stack container (`-space-x-*`) wholesale.
		foreach ( iterator_to_array( $clone->getElementsByTagName( '*' ) ) as $node ) {
			if ( ! ( $node instanceof DOMElement ) || ! $node->parentNode ) { continue; }
			if ( preg_match( '/-space-x-\d/', self::cls( $node ) ) ) { $node->parentNode->removeChild( $node ); $removed = true; }
		}
		// Fallback (no Tailwind class): strip each avatar img up to its bare (text-less) wrapper.
		if ( ! $removed ) {
			foreach ( iterator_to_array( $clone->getElementsByTagName( 'img' ) ) as $im ) {
				$n = $im;
				while ( $n->parentNode && $n->parentNode !== $clone && '' === trim( self::text( $n->parentNode ) ) ) { $n = $n->parentNode; }
				if ( $n->parentNode ) { $n->parentNode->removeChild( $n ); }
			}
		}
		if ( '' === trim( self::text( $clone ) ) ) { return ''; } // nothing but the faces — no rating text
		return self::strip_cs( trim( (string) $doc->saveHTML( $clone ) ) );
	}

	/**
	 * Is a grid child a feature/bento CARD (vs. a CTA button in a flex row)? A card is a non-button
	 * container that holds its own heading — that's what separates a feature card from a button row
	 * (the #1 false positive: a hero/CTA's `flex` button group looks grid-ish but has no headings).
	 *
	 * @param DOMElement $k
	 * @return bool
	 */
	/** Structural testimonials grid (utility-class / Tailwind): a flex/grid whose >=2 sibling cards each
	 *  read like a quote — quote marks, a star rating, or a "— Name" attribution. Quote/rating signals keep
	 *  it from matching plain feature/pricing grids. Mirror of the JS testimonialsOf() structural fallback. */
	private static function is_testimonials_grid( $el ) {
		$cls = self::cls( $el );
		$cs  = (string) $el->getAttribute( 'data-sc-cs' );
		$is_grid = strpos( $cls, 'grid' ) !== false || strpos( $cls, 'flex' ) !== false
			|| strpos( $cs, 'display:flex' ) !== false || strpos( $cs, 'display:grid' ) !== false || strpos( $cs, 'display:inline-flex' ) !== false;
		if ( ! $is_grid ) { return false; }
		$kids = self::el_children( $el );
		if ( count( $kids ) < 2 ) { return false; }
		$cards = 0;
		foreach ( $kids as $k ) { if ( self::looks_quote_card( $k ) ) { $cards++; } }
		return $cards >= 2 && $cards >= count( $kids ) - 1;
	}
	/** A card that reads like a testimonial (has a paragraph AND a quote/rating/attribution signal). */
	private static function looks_quote_card( $k ) {
		if ( ! ( $k instanceof DOMElement ) ) { return false; }
		if ( $k->getElementsByTagName( 'p' )->length === 0 && $k->getElementsByTagName( 'blockquote' )->length === 0 ) { return false; }
		// A GALLERY image tile — a full-bleed `object-cover` image with its (often quoted) caption in an
		// ABSOLUTE overlay — is NOT a testimonial: the image is the content, the caption just labels it.
		// Without this, a photo grid whose captions are quoted phrases ("Cinematic mountain…") is misread as
		// testimonials; excluding it lets the lower-priority image_grid recognizer claim the gallery.
		if ( self::is_gallery_image_card( $k ) ) { return false; }
		$t = self::text( $k );
		if ( mb_strlen( $t ) < 30 ) { return false; }
		if ( preg_match( '/["“”«»‘’]/u', $t ) ) { return true; }
		if ( self::testimonial_rating( $k ) !== null ) { return true; }
		return (bool) preg_match( '/(^|\s)[—–-]\s*[A-Z][a-z]+/u', $t );
	}
	/** A gallery-style image tile: a full-bleed cover image (object-cover) framed by the card (an
	 *  `aspect-` ratio or `overflow-hidden`) with any caption living in an absolutely-positioned overlay —
	 *  the photo is the content, not a testimonial avatar. */
	private static function is_gallery_image_card( $k ) {
		$imgs = $k->getElementsByTagName( 'img' );
		if ( ! $imgs->length ) { return false; }
		$img  = $imgs->item( 0 );
		$icls = self::cls( $img );
		$ics  = (string) $img->getAttribute( 'data-sc-cs' );
		$cover = ( strpos( $icls, 'object-cover' ) !== false ) || (bool) preg_match( '/object-fit:\s*cover/i', $ics );
		if ( ! $cover ) { return false; }
		// The tile MUST be aspect-ratio framed (`aspect-square`/`aspect-[4/3]` on the card, or a computed
		// `aspect-ratio`) — that is the gallery hallmark. A testimonial card that happens to carry a cover-image
		// avatar + an absolute badge is NOT aspect-framed, so it stays a testimonial (regression guard).
		$kcls = self::cls( $k );
		$kcs  = (string) $k->getAttribute( 'data-sc-cs' );
		if ( ! preg_match( '/\baspect-/', $kcls ) && ! preg_match( '/(?:^|;)\s*aspect-ratio:\s*[^;]+/i', $kcs ) ) { return false; }
		// And the caption must live in an absolute overlay (a gallery labels the photo), not be a flowing quote.
		foreach ( $k->getElementsByTagName( '*' ) as $d ) {
			if ( strpos( self::cls( $d ), 'absolute' ) !== false
				|| preg_match( '/position:\s*absolute/i', (string) $d->getAttribute( 'data-sc-cs' ) ) ) { return true; }
		}
		return false;
	}
	/** Star-rating glyph count in a card (svg/i with a `star` class), or null. */
	private static function testimonial_rating( $k ) {
		$n = 0;
		foreach ( array( 'svg', 'i' ) as $tg ) {
			foreach ( $k->getElementsByTagName( $tg ) as $g ) { if ( strpos( self::cls( $g ), 'star' ) !== false ) { $n++; } }
		}
		// a RATING is a row of stars (≥ 3): a lone `lucide-star` inside a card's 64px icon tile is the card's ICON — it made a
		// 3-up service-card grid a testimonials block (a fixture from the feed)
		return $n >= 3 ? min( 5, $n ) : null;
	}
	/** The author CANDIDATE texts of a testimonial card, the name first: short leaves, minus quote glyphs and an initials disc,
	 *  the heavier / uppercase line promoted to the front (the name), the rest in DOM order (the role, a location). */
	private static function author_candidates( $k, $quote, $tags = array( 'h3', 'h4', 'h5', 'h6', 'cite', 'strong', 'span', 'p', 'div' ) ) {
		$cands = array();
		$cand_w = array(); // text => [weight, uppercase] of the leaf, for the name / role choice below
		foreach ( $tags as $tg ) {
			foreach ( $k->getElementsByTagName( $tg ) as $e ) {
				$t = trim( self::text( $e ) );
				if ( $t === '' || $t === $quote || mb_strlen( $t ) > 40 || $e->getElementsByTagName( '*' )->length > 1 ) { continue; }
				// a lone QUOTE GLYPH (“ ” ❝ ") is decoration, never the author (it became author_name — a fixture from the feed)
				if ( ! preg_match( '/\p{L}/u', $t ) ) { continue; }
				// 2–3 uppercase letters inside a small rounded disc are an INITIALS avatar, not the name (a fixture from the feed)
				if ( preg_match( '/^\p{Lu}{2,3}$/u', $t ) ) {
					$disc = $e; $is_disc = false;
					for ( $i = 0; $i < 2 && $disc instanceof DOMElement; $i++, $disc = $disc->parentNode ) {
						$dcs = (string) $disc->getAttribute( 'data-sc-cs' );
						if ( preg_match( '/border-radius:\s*(?:9999px|50%)/i', $dcs ) && preg_match( '/(?:^|;)\s*(?:width|height):\s*([0-9.]+)px/i', $dcs, $dw ) && (float) $dw[1] <= 72 ) { $is_disc = true; break; }
					}
					if ( $is_disc ) { continue; }
				}
				$ecs = (string) $e->getAttribute( 'data-sc-cs' );
				$w = preg_match( '/(?:^|;)\s*font-weight:\s*([0-9]+)/i', $ecs, $wm ) ? (int) $wm[1] : 400;
				$up = (bool) preg_match( '/text-transform:\s*uppercase/i', $ecs ) || (bool) preg_match( '/\buppercase\b/', self::cls( $e ) );
				$cands[] = $t; if ( ! isset( $cand_w[ $t ] ) ) { $cand_w[ $t ] = array( $w, $up ); }
			}
		}
		$cands    = array_values( array_unique( $cands ) );
		// the NAME is the heavier / uppercase line, whatever the DOM order (a `div.font-bold + div.text-sm` author block, a
		// role set above the name) — the first candidate was taken blindly (three author-mapping defects in the feed)
		if ( count( $cands ) >= 2 ) {
			$best = 0; $bs = -1;
			foreach ( $cands as $ci => $ct ) { $sc = ( ( $cand_w[ $ct ][0] ?? 400 ) >= 600 ? 2 : 0 ) + ( ! empty( $cand_w[ $ct ][1] ) ? 1 : 0 ); if ( $sc > $bs ) { $bs = $sc; $best = $ci; } }
			if ( $best > 0 && $bs > 0 ) { $nm = $cands[ $best ]; unset( $cands[ $best ] ); array_unshift( $cands, $nm ); $cands = array_values( $cands ); }
		}
		return $cands;
	}

	/** Extract testimonial rows {quote,image,name,position,rating} from a grid's quote-cards. */
	private static function testimonials_items( $el ) {
		$rows = array();
		foreach ( self::el_children( $el ) as $k ) {
			if ( ! self::looks_quote_card( $k ) ) { continue; }
			$quote = ''; $qlen = 0;
			foreach ( array( 'blockquote', 'p' ) as $tg ) {
				foreach ( $k->getElementsByTagName( $tg ) as $p ) { $t = self::text( $p ); if ( mb_strlen( $t ) > $qlen ) { $qlen = mb_strlen( $t ); $quote = $t; } }
			}
			$image = ''; $imgs = $k->getElementsByTagName( 'img' ); if ( $imgs->length ) { $image = (string) $imgs->item( 0 )->getAttribute( 'src' ); }
			$cands = array();
			$cands = self::author_candidates( $k, $quote );
			// POSITION = role, plus a LOCATION line ("Portland, OR") and any FOOTER STAT ("Total savings
			// $14,200") folded in — the native testimonial has no field for those, so appending them here
			// keeps the content instead of dropping it. Location = a short "City, ST"-ish 3rd candidate.
			$position = isset( $cands[1] ) ? $cands[1] : '';
			if ( isset( $cands[2] ) && preg_match( '/^[A-Za-z .\'-]+,\s*[A-Za-z]{2,}$/', $cands[2] ) ) { $position = trim( $position . ', ' . $cands[2], ', ' ); }
			$rows[]   = array(
				'quote' => $quote, 'image' => $image,
				'name'  => isset( $cands[0] ) ? $cands[0] : '', 'position' => $position,
				'rating' => self::testimonial_rating( $k ),
				'extra'  => self::testimonial_extra( $k, $quote ), // per-testimonial stat/result rows (label + value)
				'look'   => self::testimonial_look( $k, $quote, $cands ), // the card's measured typography / avatar size / footer rhythm
			);
		}
		return $rows;
	}

	/**
	 * The MEASURED look of one testimonial card — what the shortcode's own defaults otherwise re-style: the avatar's
	 * rendered size (a 48px `w-12` portrait was drawn 128px), the name / role / quote colour + size + weight, and the
	 * footer stat row's label / value typography + its top rhythm (`mt-6 pt-6 border-t`). Each value is a computed
	 * declaration string the mapper scopes onto the rendered parts (a real-site audit: the role line was invisible
	 * — the theme's muted ink — and the "$14,200" figure lost its 20px bold).
	 */
	private static function testimonial_look( $k, $quote, array $cands ) {
		$look = array();
		$imgs = $k->getElementsByTagName( 'img' );
		if ( $imgs->length ) { $iw = self::sc_css( $imgs->item( 0 ), 'width' ); if ( preg_match( '/^([0-9.]+)px$/', $iw, $wm ) && (float) $wm[1] >= 16 && (float) $wm[1] <= 200 ) { $look['avatarPx'] = (int) round( (float) $wm[1] ); } }
		$typo = function ( $el ) { return $el instanceof DOMElement ? self::cs_text_decls( (string) $el->getAttribute( 'data-sc-cs' ) ) : ''; };
		$leaf_with = function ( $text ) use ( $k ) { foreach ( $k->getElementsByTagName( '*' ) as $c ) { if ( $c->getElementsByTagName( '*' )->length > 0 ) { continue; } if ( trim( preg_replace( '/\s+/', ' ', self::text( $c ) ) ) === $text ) { return $c; } } return null; };
		if ( '' !== $quote ) { foreach ( array( 'blockquote', 'p' ) as $tg ) { foreach ( $k->getElementsByTagName( $tg ) as $p ) { if ( self::text( $p ) === $quote ) { $look['quoteCs'] = $typo( $p ); break 2; } } } }
		if ( isset( $cands[0] ) && '' !== $cands[0] ) { $look['nameCs'] = $typo( $leaf_with( $cands[0] ) ); }
		if ( isset( $cands[1] ) && '' !== $cands[1] ) { $look['jobCs'] = $typo( $leaf_with( $cands[1] ) ); }
		foreach ( self::el_children( $k ) as $foot ) {
			$fc = ' ' . strtolower( self::cls( $foot ) ) . ' ';
			if ( strpos( $fc, 'border-t' ) === false && strpos( $fc, 'border-top' ) === false ) { continue; }
			$fm = self::el_margin( $foot ); $fp = self::el_padding( $foot ); $fpb = is_array( $fp['base'] ?? null ) ? $fp['base'] : array();
			$look['extraTop'] = (int) round( (float) ( $fm['top'] ?? 0 ) + (float) ( $fpb['top'] ?? 0 ) );
			$bc = self::sc_css( $foot, 'border-top-color' ); if ( '' !== $bc ) { $look['extraRule'] = $bc; }
			$leaves = array();
			foreach ( $foot->getElementsByTagName( '*' ) as $fe ) { if ( $fe->getElementsByTagName( '*' )->length > 0 ) { continue; } if ( '' !== trim( self::text( $fe ) ) ) { $leaves[] = $fe; } }
			if ( count( $leaves ) >= 2 ) { $look['extraLabelCs'] = $typo( $leaves[0] ); $look['extraValueCs'] = $typo( $leaves[1] ); }
			elseif ( count( $leaves ) === 1 ) { $look['extraValueCs'] = $typo( $leaves[0] ); }
			break;
		}
		return array_filter( $look, function ( $v ) { return '' !== $v && null !== $v; } );
	}

	/** The TEXT declarations of a computed-style stamp (colour / size / weight / line-height / letter-spacing /
	 *  transform / family) as one `prop:value;…` string — the safe subset a scoped rule may repeat verbatim. */
	private static function cs_text_decls( $cs ) {
		$out = array();
		foreach ( array( 'color', 'font-size', 'font-weight', 'line-height', 'letter-spacing', 'text-transform', 'font-family', 'font-style' ) as $p ) {
			if ( preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', (string) $cs, $m ) ) {
				$v = trim( $m[1] );
				if ( '' === $v || 'normal' === $v || 'none' === $v || 'inherit' === $v ) { continue; }
				if ( 'font-family' === $p && ! preg_match( '/^[a-z0-9"\', -]+$/i', $v ) ) { continue; }
				if ( 'font-family' !== $p && ! preg_match( '/^[a-z0-9()%.,#\s-]+$/i', $v ) ) { continue; }
				$out[] = $p . ':' . $v;
			}
		}
		return implode( ';', $out );
	}

	/**
	 * Per-testimonial EXTRA TEXTS — a bordered "footer" row (a `border-t` divider row) holding a stat/result
	 * (e.g. a muted "Total savings" label over a bold "$14,200" figure, or a lone "40% more closes") →
	 * an array of { label, value } rows for the testimonials shortcode's Extra Texts field. Prefers two
	 * distinct leaf texts (label + value); else splits a single "Label $Figure" string on the figure; else
	 * carries the whole line as a value-only row. Empty when the card has no footer stat.
	 *
	 * @param DOMElement $k     the testimonial card
	 * @param string     $quote the card's quote (so the stat scan never re-captures the quote text)
	 * @return array[] list of array( 'label' => string, 'value' => string )
	 */
	private static function testimonial_extra( $k, $quote ) {
		$extra = array();
		foreach ( self::el_children( $k ) as $foot ) {
			$fc = ' ' . strtolower( self::cls( $foot ) ) . ' ';
			if ( strpos( $fc, 'border-t' ) === false && strpos( $fc, 'border-top' ) === false ) { continue; }
			// Collect the footer's distinct LEAF text runs (a muted label + an emphasized figure are separate
			// elements in the common case) — order-preserving, deduped.
			$parts = array();
			foreach ( array( 'p', 'span', 'div', 'strong', 'b', 'dt', 'dd' ) as $tg ) {
				foreach ( $foot->getElementsByTagName( $tg ) as $fe ) {
					if ( $fe->getElementsByTagName( '*' )->length > 0 ) { continue; } // leaf only
					$t = trim( preg_replace( '/\s+/', ' ', self::text( $fe ) ) );
					if ( '' !== $t && $t !== $quote && mb_strlen( $t ) <= 60 && ! in_array( $t, $parts, true ) ) { $parts[] = $t; }
				}
			}
			if ( count( $parts ) >= 2 ) {
				$extra[] = array( 'label' => $parts[0], 'value' => $parts[1] );
			} else {
				$ft = trim( preg_replace( '/\s+/', ' ', self::text( $foot ) ) );
				if ( '' !== $ft && $ft !== $quote && mb_strlen( $ft ) <= 60 ) {
					// A single run — split "Total savings $14,200" / "…40% more closes" on the figure token.
					if ( preg_match( '/^(.*?)\s*((?:[$€£]\s?[\d.,]+|\d[\d.,]*\s*%|\d[\d.,]+)\b.*)$/u', $ft, $m ) && trim( $m[1] ) !== '' ) {
						$extra[] = array( 'label' => trim( $m[1] ), 'value' => trim( $m[2] ) );
					} else {
						$extra[] = array( 'label' => '', 'value' => $ft );
					}
				}
			}
			break; // one footer stat block per card
		}
		return $extra;
	}

	/** A SINGLE featured testimonial: a star rating (>=3 stars) PLUS a real quote (>=40 chars). The
	 *  rating+quote combo is distinctive enough to avoid stealing plain quote-styled headings, and it must
	 *  NOT already be a multi-card grid (that's the testimonials(92) path). */
	private static function is_single_testimonial( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return false; }
		if ( self::is_testimonials_grid( $el ) ) { return false; }
		// A WRAPPER around a testimonials GRID (a section: overline + heading + the card grid) is NOT a single
		// testimonial — its combined stars + one long quote used to make the WHOLE band read as one item, which
		// DROPPED the section heading and the other cards. Bow out when a descendant is a real testimonials grid,
		// so the band decomposes (heading → special_heading, grid → the multi-item testimonials recognizer).
		if ( $el->ownerDocument ) {
			$xp = new DOMXPath( $el->ownerDocument );
			foreach ( $xp->query( './/*[self::div or self::ul or self::section]', $el ) as $d ) {
				if ( $d !== $el && self::is_testimonials_grid( $d ) ) { return false; }
			}
		}
		// NOT a hero / CTA band: a real testimonial carries no primary H1 and no action buttons (a hero's
		// star row is small social-proof next to the H1 + CTAs — reject it so the hero decomposes normally).
		if ( $el->getElementsByTagName( 'h1' )->length > 0 ) { return false; }
		if ( $el->getElementsByTagName( 'button' )->length > 0 ) { return false; }
		foreach ( $el->getElementsByTagName( 'a' ) as $a ) {
			if ( preg_match( '/\bbtn\b|button|inline-flex|rounded-(?:full|lg|md|xl)/', self::cls( $a ) ) ) { return false; }
		}
		$r = self::testimonial_rating( $el );
		if ( $r === null || $r < 3 ) { return false; }
		// The quote must READ as a quote: a <blockquote> OR quotation-marked text, and be reasonably long —
		// so a hero/feature band that merely contains stars can't masquerade as a testimonial.
		$has_bq = $el->getElementsByTagName( 'blockquote' )->length > 0;
		$qlen = 0; $quoted = false;
		foreach ( array( 'blockquote', 'h2', 'h3', 'h4', 'p' ) as $tg ) {
			foreach ( $el->getElementsByTagName( $tg ) as $p ) {
				$t = self::text( $p ); $l = mb_strlen( $t );
				if ( $l > $qlen ) { $qlen = $l; $quoted = (bool) preg_match( '/["“”«»]/u', $t ); }
			}
		}
		if ( $qlen < 40 ) { return false; }
		return $has_bq || $quoted;
	}

	/** Extract the single testimonial row {quote,image,name,position,rating}. The AUTHOR line is a `<p>`
	 *  whose leading `<span>` is the NAME (bold block) followed by trailing ROLE text — split so they land
	 *  in author_name / author_job instead of running together ("Sarah JenkinsChief Executive Officer…"). */
	private static function single_testimonial_item( $el ) {
		$quote = ''; $qlen = 0; $author_p = null;
		foreach ( array( 'blockquote', 'h2', 'h3', 'h4', 'p' ) as $tg ) {
			foreach ( $el->getElementsByTagName( $tg ) as $p ) {
				$t = trim( self::text( $p ) );
				if ( $t === '' ) { continue; }
				// Author line: a <p> carrying a lone leading <span> (the name) + trailing role text.
				if ( $author_p === null && 'p' === strtolower( $p->tagName )
					&& $p->getElementsByTagName( 'span' )->length >= 1 && mb_strlen( $t ) <= 80 ) {
					$author_p = $p; continue;
				}
				if ( mb_strlen( $t ) > $qlen ) { $qlen = mb_strlen( $t ); $quote = $t; }
			}
		}
		$name = ''; $position = '';
		if ( $author_p ) {
			$span = $author_p->getElementsByTagName( 'span' )->item( 0 );
			if ( $span ) { $name = trim( self::text( $span ) ); }
			$full = trim( self::text( $author_p ) );
			if ( $name !== '' && strpos( $full, $name ) === 0 ) {
				$position = trim( mb_substr( $full, mb_strlen( $name ) ) );
			} else {
				$position = ( $name !== '' ) ? '' : $full;
			}
			$position = trim( $position, " \t\r\n,·–—-" );
		}
		// Fallback attribution when there's no span-split author: reuse the grid's short-text candidate scan.
		if ( $name === '' ) {
			// (the grid's scan, DIV lines included: a `div.font-bold + div.text-sm.text-muted` author block beside the avatar left
			// both fields empty — a fixture from the feed)
			$cands = self::author_candidates( $el, $quote );
			if ( isset( $cands[0] ) ) { $name = $cands[0]; }
			if ( isset( $cands[1] ) ) { $position = $cands[1]; }
		}
		if ( $quote === '' ) { return null; }
		$image = ''; $imgs = $el->getElementsByTagName( 'img' ); if ( $imgs->length ) { $image = (string) $imgs->item( 0 )->getAttribute( 'src' ); }
		// Author CASE + tracking: the source attribution is often an UPPERCASE letter-spaced kicker
		// (`<p class="uppercase tracking-widest">`). The native testimonials view renders the name/role in
		// their raw case, so carry the transform + letter-spacing (applied via custom_css in n_testimonials).
		$author_upper = false; $author_ls = '';
		if ( $author_p instanceof DOMElement ) {
			$ac  = ' ' . strtolower( self::cls( $author_p ) ) . ' ';
			$acs = (string) $author_p->getAttribute( 'data-sc-cs' );
			if ( strpos( $ac, ' uppercase ' ) !== false || stripos( $acs, 'text-transform:uppercase' ) !== false ) { $author_upper = true; }
			if ( preg_match( '/letter-spacing:\s*([0-9.]+px)/i', $acs, $lm ) && $lm[1] !== '0px' ) { $author_ls = $lm[1]; }
		}
		return array( 'quote' => $quote, 'image' => $image, 'name' => $name, 'position' => $position, 'rating' => self::testimonial_rating( $el ), 'author_upper' => $author_upper, 'author_ls' => $author_ls, 'extra' => self::testimonial_extra( $el, $quote ) );
	}

	/**
	 * Classify the SOURCE testimonial block's LAYOUT → the closest `testimonials` shortcode DESIGN, so the
	 * converted section mirrors the source presentation instead of always the Classic default. Returns
	 * `{ design, layout_choice, grid_columns }`; layout_choice/grid_columns matter only for the Classic
	 * ('default') design (single | grid | carousel). Conservative by intent: high-confidence patterns only
	 * (marquee wall, JS/ARIA slider, static grid, single) — anything unclear falls back to Classic
	 * single/grid/carousel rather than mis-picking an exotic design.
	 */
	private static function detect_testimonial_design( $el, $count ) {
		$single   = array( 'design' => 'default', 'layout_choice' => 'single',   'grid_columns' => 'row-cols-3' );
		$carousel = array( 'design' => 'default', 'layout_choice' => 'carousel', 'grid_columns' => 'row-cols-3' );
		if ( ! ( $el instanceof DOMElement ) ) { return $count >= 2 ? $carousel : $single; }
		// The slider / marquee machinery often lives on a WRAPPER, so scan the block + up to 2 ancestors.
		$scope = $el;
		for ( $i = 0; $i < 2 && $scope->parentNode instanceof DOMElement; $i++ ) { $scope = $scope->parentNode; }
		$doc = $el->ownerDocument;
		$hay = strtolower( (string) ( $doc ? $doc->saveHTML( $scope ) : '' ) );

		$cls = strtolower( self::cls( $el ) );

		// MARQUEE — a horizontally auto-scrolling wall (CSS marquee animation / duplicated track).
		if ( preg_match( '/\bmarquee\b|animate-marquee|animate-scroll(?:-left|-right|-x)?(?=[\s"\'])|animation:[^;"\']*(?:marquee|scroll)/', $hay ) ) {
			return array( 'design' => 'marquee', 'layout_choice' => '', 'grid_columns' => '', 'sub' => array() );
		}
		// SLIDER / CAROUSEL — a JS slider lib, an ARIA carousel, or a snap / overflow-x scroll track.
		if ( preg_match( '/\b(?:swiper|slick|embla|keen-slider|glide|splide|flickity)\b|roledescription=["\']?carousel|\bsnap-x\b|overflow-x-(?:auto|scroll)/', $hay ) ) {
			return $carousel;
		}
		// MASONRY — a CSS multi-column wall (`columns-N` / a `masonry` class): many cards, uneven heights.
		if ( $count >= 3 && preg_match( '/\b(?:columns-([1-4])|masonry)\b/', $cls . ' ' . $hay, $mm ) ) {
			$mc = (string) min( 4, (int) self::wall_columns( $el, ! empty( $mm[1] ) ? $mm[1] : '3' ) );
			return array( 'design' => 'masonry', 'layout_choice' => '', 'grid_columns' => '', 'sub' => array( 'masonry_columns' => $mc ) );
		}
		// BENTO — an asymmetric grid whose FIRST tile spans 2 cols/rows (a featured hero quote + smaller ones).
		if ( $count >= 3 ) {
			$kids = self::el_children( $el );
			if ( isset( $kids[0] ) && $kids[0] instanceof DOMElement
				&& preg_match( '/\b(?:[a-z]+:)?(?:col-span-2|row-span-2)\b/', strtolower( self::cls( $kids[0] ) ) ) ) {
				return array( 'design' => 'bento', 'layout_choice' => '', 'grid_columns' => '', 'sub' => array() );
			}
		}
		// SPLIT — a featured testimonial with a LARGE (non-avatar) photo beside the quote in a 2-column item.
		// Only when the source actually pairs a big image with the quote (split's media column needs a photo).
		if ( $count <= 3 && preg_match( '/\b(?:md:grid-cols-2|lg:grid-cols-2|grid-cols-2)\b|\bmd:flex-row\b/', $hay ) ) {
			foreach ( $el->getElementsByTagName( 'img' ) as $im ) {
				$ic = strtolower( self::cls( $im ) );
				$pc = $im->parentNode instanceof DOMElement ? strtolower( self::cls( $im->parentNode ) ) : '';
				if ( strpos( $ic, 'rounded-full' ) !== false ) { continue; } // a small round avatar is not a split media column
				if ( preg_match( '/\bw-(?:1\/2|2\/5|3\/5|full)\b|\baspect-|\bobject-cover\b|\bmin-h-/', $ic . ' ' . $pc ) ) {
					return array( 'design' => 'split', 'layout_choice' => '', 'grid_columns' => '', 'sub' => array() );
				}
			}
		}
		// STACKED — a single-column editorial LIST of testimonials separated by hairline dividers, no cards.
		if ( $count >= 2 && preg_match( '/\bdivide-y\b/', $hay ) ) {
			return array( 'design' => 'stacked', 'layout_choice' => '', 'grid_columns' => '', 'sub' => array() );
		}
		// CLASSIC — a static grid (≥2 cards) keeps its column count; a lone testimonial → Single (no slider
		// chrome), which is the faithful shape for a big centered editorial quote like AURA's.
		if ( $count >= 2 ) {
			$cols = method_exists( __CLASS__, 'grid_col_count' ) ? (int) self::grid_col_count( $el ) : 0;
			$n    = $cols >= 2 ? min( 4, $cols ) : ( $count >= 3 ? 3 : 2 );
			return array( 'design' => 'default', 'layout_choice' => 'grid', 'grid_columns' => 'row-cols-' . $n );
		}
		return $single;
	}

	private static function is_card_cell( $k ) {
		$tag = strtolower( $k->tagName );
		if ( $tag === 'button' || $tag === 'input' ) { return false; }
		foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) {
			if ( $k->getElementsByTagName( $h )->length > 0 ) { return true; }
		}
		return false;
	}

	/**
	 * Build the Mapper "cols" array from a grid's child cells. Each cell → an icon_box card when it
	 * carries an icon + heading; else a text cell; else verbatim HTML.
	 *
	 * @param DOMElement $grid
	 * @return array[]
	 */
	/**
	 * Pass #5 — a grid/flex row's inter-column GAP in pixels, for spacing-scale distillation onto the
	 * section's native Gap option. Priority: the container's computed `gap` (data-sc-cs, any framework);
	 * else a Tailwind `gap-N`/`gap-x-N` utility (N × 4px). 0 when no meaningful gap is declared.
	 *
	 * @param DOMElement $grid
	 * @return float pixels
	 */
	private static function grid_gap_px( $grid ) {
		$cs = (string) $grid->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*gap:\s*([0-9.]+)px/', $cs, $m ) ) { return (float) $m[1]; }
		$cls = self::cls( $grid );
		if ( preg_match( '/(?:^|\s)(?:[a-z0-9]+:)?gap(?:-x)?-(\d+(?:\.\d+)?)(?:\s|$)/', ' ' . $cls . ' ', $m ) ) { return (float) $m[1] * 4.0; }
		return 0.0;
	}

	/**
	 * The RESPONSIVE grid/flex gap — base + `md:` + `lg:` gutters, in px — so a source `gap-10 lg:gap-16`
	 * (40px → 64px) carries BOTH layers onto the Section's per-device Gap option instead of flattening to one.
	 * Base = an unprefixed `gap-N` class (N×4px), else the computed `gap:` (a visual-builder source with no
	 * utility class → base only, no responsive). md/lg = the matching `md:gap-N` / `lg:gap-N` when present.
	 */
	private static function grid_gap_responsive( $grid ) {
		$cls = ' ' . self::cls( $grid ) . ' ';
		$out = array( 'base' => 0.0, 'md' => 0.0, 'lg' => 0.0 );
		if ( preg_match( '/\sgap(?:-x)?-(\d+(?:\.\d+)?)\b/', $cls, $m ) ) { $out['base'] = (float) $m[1] * 4.0; }
		else { $out['base'] = self::grid_gap_px( $grid ); }
		if ( preg_match( '/\smd:gap(?:-x)?-(\d+(?:\.\d+)?)\b/', $cls, $m ) ) { $out['md'] = (float) $m[1] * 4.0; }
		if ( preg_match( '/\slg:gap(?:-x)?-(\d+(?:\.\d+)?)\b/', $cls, $m ) ) { $out['lg'] = (float) $m[1] * 4.0; }
		return $out;
	}

	/**
	 * The breakpoint a RESPONSIVE grid/flex row stacks BELOW — a source `lg:grid-cols-2` (or `flex-col
	 * lg:flex-row`) is a SINGLE column until `lg`, only splitting into columns at `lg`+. Returns 'sm'|'md'|
	 * 'lg'|'xl'|'2xl', or '' when the row is multi-column at ALL widths (a base `grid-cols-N` with no
	 * responsive prefix). Lets the mapper stack the converted columns until the SAME breakpoint as the source
	 * instead of the fixed `sm` default — so a hero `lg:grid-cols-2` stays stacked through tablet, as designed.
	 */
	private static function grid_stack_bp( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$cls = ' ' . self::cls( $el ) . ' ';
		// A base multi-column grid (`grid-cols-2`+ with NO responsive prefix) is multi-col everywhere.
		if ( preg_match( '/\sgrid-cols-[2-9]\b/', $cls ) ) { return ''; }
		if ( preg_match( '/\s(sm|md|lg|xl|2xl):grid-cols-[2-9]\b/', $cls, $m ) ) { return $m[1]; }
		if ( strpos( $cls, ' flex-col ' ) !== false && preg_match( '/\s(sm|md|lg|xl|2xl):flex-row\b/', $cls, $m ) ) { return $m[1]; }
		return '';
	}

	/** The FIRST descendant counter/stat grid inside $cell (document order = outermost), or null. Lets a
	 *  layout-row cell that wraps a stats panel decompose into heading + native counters instead of one
	 *  icon_box. Excludes $cell itself (that case is the section-level counter_grid recognizer's job). */
	private static function cell_wraps_counter_grid( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) || ! $cell->ownerDocument ) { return null; }
		$xp = new DOMXPath( $cell->ownerDocument );
		foreach ( $xp->query( './/*[self::div or self::ul or self::section]', $cell ) as $d ) {
			if ( $d === $cell ) { continue; }
			if ( self::is_counter_grid( $d ) ) { return $d; }
		}
		return null;
	}

	/** The FIRST descendant container that is an icon-text/feature list (icon+text rows) inside $cell, or
	 *  null. Lets a card cell that wraps a nested feature list (icon + heading + description followed by a
	 *  grid/flex of icon+text pills — e.g. modfii's "Loan Types Available" card) decompose into an icon_box
	 *  HEADER + a native feature_list, instead of one icon_box that claims the card by its heading and DROPS
	 *  the list. Excludes $cell itself (a bare list cell is the section-level icon_text_list recognizer's job). */
	private static function cell_wraps_icon_text_list( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) || ! $cell->ownerDocument ) { return null; }
		$xp = new DOMXPath( $cell->ownerDocument );
		foreach ( $xp->query( './/*[self::div or self::ul or self::section]', $cell ) as $d ) {
			if ( $d === $cell ) { continue; }
			if ( self::is_icon_text_list( $d ) ) { return $d; }
		}
		return null;
	}

	/** The cell's own content PHOTO (the first raster <img> that is NOT inside $exclude and not an SVG or
	 *  data-URI glyph) as a build_cell_items `image` block, or an empty array. Lets a decomposition branch
	 *  that bypasses card_from_cell() still carry the card's photo. */
	private static function cell_photo_block( $cell, $exclude ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return array(); }
		foreach ( $cell->getElementsByTagName( 'img' ) as $im ) {
			$within = false;
			for ( $pp = $im->parentNode; $pp instanceof DOMElement; $pp = $pp->parentNode ) {
				if ( $pp === $exclude ) { $within = true; break; }
				if ( $pp === $cell ) { break; }
			}
			if ( $within ) { continue; }
			$src = trim( (string) $im->getAttribute( 'src' ) );
			if ( '' === $src ) { $src = trim( (string) $im->getAttribute( 'data-src' ) ); }
			if ( '' === $src || 0 === strpos( $src, 'data:image/svg' ) || preg_match( '/\.svg(?:$|\?)/i', $src ) ) { continue; }
			$alt = trim( (string) $im->getAttribute( 'alt' ) );
			return array( array(
				'role' => 'image',
				'html' => '<img src="' . htmlspecialchars( $src, ENT_QUOTES ) . '" alt="' . htmlspecialchars( $alt, ENT_QUOTES ) . '" />',
			) );
		}
		return array();
	}

	/** The panel's OWN lead heading (the first h1-h4 that is NOT inside $exclude and not a counter label) →
	 *  build_cell_items role blocks (title [+ following subtitle <p>]). Empty array when there's no such
	 *  heading. Used to keep a stats-panel's title above its decomposed counter row. */
	private static function cell_lead_heading_block( $cell, $exclude ) {
		$blocks = array();
		if ( ! ( $cell instanceof DOMElement ) ) { return $blocks; }
		foreach ( array( 'h1', 'h2', 'h3', 'h4' ) as $htag ) {
			foreach ( $cell->getElementsByTagName( $htag ) as $hd ) {
				// Skip a heading that lives inside the counter grid (a stat number rendered as an <h*>).
				$within = false;
				for ( $p = $hd->parentNode; $p instanceof DOMElement; $p = $p->parentNode ) {
					if ( $p === $exclude ) { $within = true; break; }
					if ( $p === $cell ) { break; }
				}
				if ( $within ) { continue; }
				$txt = trim( preg_replace( '/\s+/', ' ', self::text( $hd ) ) );
				if ( '' === $txt ) { continue; }
				$blocks[] = array( 'role' => 'title', 'html' => $txt, 'cls' => self::cls( $hd ), 'cs' => (string) $hd->getAttribute( 'data-sc-cs' ) );
				$sib = $hd->nextSibling;
				while ( $sib && XML_ELEMENT_NODE !== $sib->nodeType ) { $sib = $sib->nextSibling; }
				if ( $sib instanceof DOMElement && 'p' === strtolower( $sib->nodeName ) ) {
					$st = trim( preg_replace( '/\s+/', ' ', self::text( $sib ) ) );
					$sib_cs = (string) $sib->getAttribute( 'data-sc-cs' );
					// A BOXED paragraph (a glass callout) is not subtitle copy — left to the normal scan as its own text block.
					if ( '' !== $st && ! ( class_exists( 'FW_Site_Converter_Mapper' ) && FW_Site_Converter_Mapper::text_is_box( $sib_cs ) ) ) { $blocks[] = array( 'role' => 'subtitle', 'text' => $st, 'cls' => self::cls( $sib ), 'cs' => $sib_cs ); }
				}
				return $blocks; // first eligible heading only
			}
		}
		return $blocks;
	}

	/** A cell's leading EYEBROW/OVERLINE label — a short (≤4 word) uppercase-ish text-only first child
	 *  (span/p/div, no icon), e.g. "The Problem" / "Our Solution" — or '' when the cell doesn't open with
	 *  one. Class-signalled (uppercase / text-xs / text-sm / eyebrow / label / kicker …) to avoid grabbing
	 *  ordinary lead copy. */
	private static function cell_lead_overline( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return ''; }
		$first = null;
		foreach ( self::el_children( $cell ) as $ec ) { $first = $ec; break; }
		if ( ! ( $first instanceof DOMElement ) ) { return ''; }
		$tag = strtolower( $first->nodeName );
		if ( ! in_array( $tag, array( 'span', 'p', 'div', 'small' ), true ) ) { return ''; }
		if ( $first->getElementsByTagName( 'svg' )->length || $first->getElementsByTagName( 'img' )->length ) { return ''; }
		$txt = trim( preg_replace( '/\s+/', ' ', self::text( $first ) ) );
		if ( '' === $txt || str_word_count( $txt ) > 4 ) { return ''; }
		$cls = strtolower( self::cls( $first ) );
		$cs  = strtolower( (string) $first->getAttribute( 'data-sc-cs' ) );
		$signal = preg_match( '/\b(uppercase|text-xs|text-sm|eyebrow|overline|kicker|label|tagline|badge)\b/', $cls )
			|| strpos( $cs, 'text-transform:uppercase' ) !== false
			|| ( $txt === strtoupper( $txt ) && preg_match( '/[A-Z]/', $txt ) );
		return $signal ? $txt : '';
	}

	/** The inner container whose OWN children are a cell's icon+text item cards (a `The Problem` column's
	 *  list). The first descendant element that has ≥2 child elements each bearing a heading, so grid_cols
	 *  can turn each into its own icon_box. Null when the cell has no such multi-item list. */
	private static function cell_inner_card_list( $cell ) {
		if ( ! ( $cell instanceof DOMElement ) ) { return null; }
		foreach ( self::el_children( $cell ) as $c ) {
			if ( ! ( $c instanceof DOMElement ) ) { continue; }
			$kids = self::el_children( $c );
			if ( count( $kids ) < 2 ) { continue; }
			$titled = 0;
			foreach ( $kids as $k ) {
				foreach ( array( 'h2', 'h3', 'h4', 'h5', 'h6' ) as $h ) { if ( $k->getElementsByTagName( $h )->length ) { $titled++; break; } }
			}
			if ( $titled >= 2 ) { return $c; }
		}
		return null;
	}

	private static function grid_cols( $grid ) {
		$grid_cols = self::grid_col_count( $grid );
		$out = array();
		$g_children = self::el_children( $grid );
		$g_shares   = self::track_shares( self::grid_px_tracks( $grid, count( $g_children ) ), count( $g_children ) ); // unequal measured tracks → 7 / 5, not 6 / 6
		$g_ci = -1;
		foreach ( $g_children as $cell ) {
			$g_ci++;
			$cls   = self::cls( $cell );
			// Tailwind's `col-span-N` is N of the PARENT's OWN `grid-cols-M` tracks — it is NOT N/12.
			// Treating it as a 12-grid span (which this did) shrank every cell of a non-12 grid: a
			// `lg:grid-cols-3` row with `lg:col-span-2` + `lg:col-span-1` became 2/12 (17%) and 1/12 (8%)
			// instead of 8/12 (67%) and 4/12 (33%), so a heading rendered 165px wide and a paragraph 59px,
			// and the wrapped text blew the section's height out several-fold. Rescale to the 12-grid.
			$span  = self::col_span( $cls );
			if ( $span >= 1 ) {
				$desk = ( $grid_cols >= 2 )
					? max( 1, min( 12, (int) round( $span * 12 / $grid_cols ) ) )
					: min( 12, $span ); // track count unknown → assume the source already used 12 tracks
			} elseif ( isset( $g_shares[ $g_ci ] ) ) {
				$desk = $g_shares[ $g_ci ];
			} else {
				$desk = $grid_cols > 0 ? (int) round( 12 / $grid_cols ) : 0;
			}
			$wResp = $desk >= 1 && $desk <= 12 ? array( 'desktop' => $desk ) : null;

			// A CAPTION TILE cell (a photo + an absolute caption) → the image box's overlay family, never a stacked card
			// (card_from_cell put the caption UNDER the photo — a fixture from the feed)
			$ct = self::caption_tile_block( $cell );
			if ( $ct ) { $out[] = array_merge( array( 'cls' => '', 'wResp' => $wResp, 'blocks' => array( $ct ) ), self::cell_geometry( $cell ) ); continue; }

			// A card whose PHOTO carries a floating BADGE (an event card: a two-line date chip pinned bottom-left over the image, then
			// a category chip / title / copy / a time | link row) — the image box has no layer for the chip, and it was dropped
			// (a fixture from the feed, recurring on two sites). The cell decomposes: the photo composite (media image + the pinned
			// chip, natively positioned) then the body's leaves inside a padded stack; the card's skin rides the column.
			$bfr = self::card_photo_badge( $cell );
			if ( $bfr instanceof DOMElement ) {
				$blocks = array();
				$comp = self::image_composite_decompose( $bfr );
				$cbl = array(); if ( is_array( $comp ) ) { foreach ( $comp as $cb ) { if ( is_array( $cb ) && isset( $cb['t'] ) ) { $cbl[] = $cb; } } }
				if ( $cbl ) { $frame = array( 't' => 'stack', 'role' => 'stack', 'gap' => 0, 'mt' => 0, 'mb' => 0, 'items' => $cbl, 'rel' => true ); if ( preg_match( '/(?:^|;)\s*height:\s*([0-9.]+)px/i', (string) $bfr->getAttribute( 'data-sc-cs' ), $fhm ) && (float) $fhm[1] >= 80 ) { $frame['frameH'] = (float) $fhm[1]; } $blocks[] = $frame; }
				foreach ( self::el_children( $cell ) as $kid ) {
					if ( $kid === $bfr || self::is_ancestor( $kid, $bfr ) ) { continue; }
					if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', (string) $kid->getAttribute( 'data-sc-cs' ) ) ) { continue; }
					if ( '' === trim( self::text( $kid ) ) && ! self::holds_icon_or_media( $kid ) ) { continue; }
					$hb = self::body_stack_blocks( $kid );
					if ( ! $hb ) { continue; }
					$kpad = self::el_padding( $kid ); $kp = is_array( $kpad['base'] ?? null ) ? $kpad['base'] : array();
					$has_pad = false; foreach ( array( 'top', 'right', 'bottom', 'left' ) as $ps ) { if ( (float) ( $kp[ $ps ] ?? 0 ) > 0 ) { $has_pad = true; } }
					if ( $has_pad || count( $hb ) >= 2 ) {
						$st = array( 't' => 'stack', 'role' => 'stack', 'gap' => (int) self::grid_gap_px( $kid ), 'mt' => 0, 'mb' => 0, 'items' => $hb );
						if ( $has_pad ) { $st['pad'] = $kp; }
						$kcs = (string) $kid->getAttribute( 'data-sc-cs' );
						if ( preg_match( '/(?:^|;)\s*justify-content:\s*space-between/i', $kcs ) && preg_match( '/flex-direction:\s*column/i', $kcs ) ) { $st['grow'] = true; }
						$blocks[] = $st;
					} else { $blocks[] = $hb[0]; }
				}
				if ( count( $blocks ) >= 2 ) {
					$pcol = array_merge( array( 'cls' => '', 'wResp' => $wResp, 'blocks' => $blocks ), self::cell_geometry( $cell ) );
					$pskin = self::cell_card_skin( $cell ); if ( $pskin ) { $pcol['cardBox'] = $pskin; }
					$out[] = $pcol;
					continue;
				}
			}

			// A cell that WRAPS a counter/stat grid (a "stats panel" = a section heading + a grid of
			// number+label cells, e.g. modfii's glassmorphic hero panel) must NOT collapse into one
			// icon_box — card_from_cell() would claim it by its heading and FLATTEN the counters to
			// stacked <p>. Decompose it into blocks instead: the panel's own heading (special_heading)
			// + the native counter row, which build_cell_items() renders stacked. Same heading-preserving
			// principle as the testimonials / accordion recognizer deferrals.
			$cgrid = self::cell_wraps_counter_grid( $cell );
			if ( $cgrid !== null ) {
				$cg = self::counter_grid_build( $cgrid );
				if ( is_array( $cg ) ) {
					// The panel's own PHOTO (a content <img> outside the stat grid) must ride along. This
					// branch bypasses card_from_cell(), which is the only other place a cell's image is
					// captured -- so without this a card that pairs a photo with a stat row lost the photo
					// entirely (urban_living_ams: 3 property photos, silently gone).
					$blocks = self::cell_photo_block( $cell, $cgrid );
					// the panel's HEADER ROW(S) before its heading (an icon + a "SCAN_01" chip in a justify-between row) — walked as
					// blocks so a scan panel keeps its chrome; only rows that hold neither the heading nor the stat grid
					$lead_h = null; foreach ( array( 'h1', 'h2', 'h3', 'h4' ) as $ht ) { foreach ( $cell->getElementsByTagName( $ht ) as $hd ) { $lead_h = $hd; break 2; } }
					foreach ( self::el_children( $cell ) as $kid ) {
						if ( $kid === $cgrid || self::is_ancestor( $kid, $cgrid ) || $kid === $lead_h || ( $lead_h && self::is_ancestor( $kid, $lead_h ) ) ) { break; }
						if ( preg_match( '/(?:^|;)\s*position:\s*(?:absolute|fixed)/i', (string) $kid->getAttribute( 'data-sc-cs' ) ) ) { continue; } // a decor layer
						if ( '' === trim( self::text( $kid ) ) && ! self::holds_icon_or_media( $kid ) ) { continue; }
						$hb = array(); self::collect_blocks_of( $kid, $hb, self::rules_get() );
						$hb = array_values( array_filter( $hb, function ( $b ) { return is_array( $b ) && isset( $b['t'] ); } ) );
						$kcs = (string) $kid->getAttribute( 'data-sc-cs' );
						if ( count( $hb ) >= 2 && preg_match( '/(?:^|;)\s*display:\s*(?:inline-)?flex/i', $kcs ) && ! preg_match( '/(?:^|;)\s*flex-direction:\s*column/i', $kcs ) ) {
							// a flex HEADER ROW (a mark | a chip, justify-between) stays a row: one content-sized cell per block, the source's justify
							$jc = preg_match( '/(?:^|;)\s*justify-content:\s*([a-z-]+)/i', $kcs, $jm ) ? strtolower( $jm[1] ) : '';
							$hrow = array( 't' => 'row', 'role' => 'columns', 'valign' => self::row_valign( $kid ), 'gap' => (int) self::grid_gap_px( $kid ), 'mt' => 0, 'mb' => 0, 'nowrap' => true, 'cols' => array() );
							if ( preg_match( '/^(space-between|space-around|space-evenly|center|flex-end|end)$/', $jc ) ) { $hrow['justify'] = $jc; } // the raw value — the row builder maps it (native Justify + content-sized cells)
							$hm = self::el_margin( $kid ); if ( ! empty( $hm['bottom'] ) ) { $hrow['mb'] = (float) $hm['bottom']; }
							foreach ( $hb as $b ) { if ( 'text' === ( $b['t'] ?? '' ) ) { $b['contentSized'] = true; } $hrow['cols'][] = array( 'cls' => '', 'blocks' => array( $b ) ); } // a flex item is content-sized (a boxed chip keeps its own width)
							$blocks[] = $hrow;
						} else {
							foreach ( $hb as $b ) { $blocks[] = $b; }
						}
					}
					$blocks = array_merge( $blocks, self::cell_lead_heading_block( $cell, $cgrid ) );
					$blocks[] = $cg;
					$pcol = array_merge( array( 'cls' => '', 'wResp' => $wResp, 'blocks' => $blocks ), self::cell_geometry( $cell ) );
					// …and the panel's OWN skin (a glass stone panel: fill / border / radius / blur / shadow) → the column's Box Preset
					$pskin = self::cell_card_skin( $cell ); if ( $pskin ) { $pcol['cardBox'] = $pskin; }
					$out[] = $pcol;
					continue;
				}
			}

			// An EYEBROW LABEL + a vertical multi-item icon list (a "The Problem" / "Our Solution"
			// comparison column) must NOT collapse into one icon_box — card_from_cell() would claim it by
			// the first item's heading, dropping the label AND the other items' per-item colored icons.
			// Decompose: keep the overline label and render EACH list item as its own icon_box (a 1-col
			// nested grid). Same heading/label-preserving principle as the counter-panel decomposition.
			$ov = self::cell_lead_overline( $cell );
			if ( '' !== $ov ) {
				// The label's own colour (source `text-destructive` red / `text-primary` green) so the
				// "The Problem" / "Our Solution" eyebrow keeps its tone instead of a faint default grey.
				$ovcolor = ''; $ovcs = '';
				foreach ( self::el_children( $cell ) as $ec ) {
					if ( trim( preg_replace( '/\s+/', ' ', self::text( $ec ) ) ) === $ov ) { $ovcolor = self::color_to_hex( self::sc_css( $ec, 'color' ) ); $ovcs = (string) $ec->getAttribute( 'data-sc-cs' ); break; }
				}
				$list = self::cell_inner_card_list( $cell );
				if ( $list !== null ) {
					$inner = self::grid_cols( $list );
					if ( count( $inner ) >= 2 ) {
						// The items are a VERTICAL stack (a `space-y-*` list), not a grid — strip the
						// per-cell width grid_cols() inferred from the child count (which would render them
						// 3-across) so each item stacks full-width under gridCols:1.
						foreach ( $inner as &$ic ) { unset( $ic['wResp'] ); }
						unset( $ic );
						// + the label's computed stamp (an `uppercase tracking-wider` eyebrow lost its transform / tracking — a real-site audit)
						$out[] = array( 'cls' => '', 'wResp' => $wResp, 'overline' => $ov, 'overlineColor' => $ovcolor, 'overlineCs' => $ovcs, 'grid' => array( 'cells' => $inner, 'gridCols' => 1 ) );
						continue;
					}
				}
			}

			// A card cell that WRAPS a feature/icon-text list (icon + heading + description, THEN a grid/flex
			// of icon+text rows — e.g. modfii's "Loan Types Available" card) must NOT collapse into one
			// icon_box: card_from_cell() claims it by its heading and DROPS the nested list. Decompose into the
			// card's icon+title+desc as an icon_box HEADER + the list as a native feature_list below it. Same
			// heading/content-preserving principle as the counter-panel + comparison-list deferrals above.
			$flist = self::cell_wraps_icon_text_list( $cell );
			if ( $flist !== null ) {
				$flblock = self::icon_text_list_block( $flist );
				if ( is_array( $flblock ) ) {
					// Parse the HEADER card from the cell with the list subtree temporarily detached, so the
					// icon_box's body text doesn't absorb the list labels; then restore the DOM.
					$lparent = $flist->parentNode; $lnext = $flist->nextSibling;
					if ( $lparent ) { $lparent->removeChild( $flist ); }
					$hdr = self::card_from_cell( $cell );
					if ( $lparent ) { $lparent->insertBefore( $flist, $lnext ); }
					if ( $hdr ) {
						$blocks = array( array( 't' => 'card', 'card' => $hdr ), $flblock );
						$bcol   = array( 'cls' => '', 'wResp' => $wResp, 'blocks' => $blocks );
						// The card's own box skin (bg/border/radius) → carried as cardBox so the mapper puts it on the
						// COLUMN (a Box Preset on the inner wrapper), wrapping BOTH the icon_box header and the list —
						// a multi-shortcode card must be boxed at the column, not on the icon_box alone.
						$ccard = self::read_card_skin( $cell );
						if ( $ccard ) { $bcol['cardBox'] = $ccard; }
						$out[] = $bcol;
						continue;
					}
				}
			}

			$card = self::card_from_cell( $cell );
			$col  = array( 'cls' => '', 'wResp' => $wResp );
			// The cell's own geometry / placement (min-height, vertical centring, order, align-self, min-width / sticky) — the
			// same record the layout-row path carries (carry_cell_geometry), so a card grid keeps a source `order:-1` or `align-self:end`.
			$col  = array_merge( $col, self::cell_geometry( $cell ) );
			// A card cell that is a TINTED BOX (source `p-5 rounded-xl border bg-*/5`, e.g. the Problem /
			// Solution items) → carry its box skin so each item renders in its coloured card, not flat.
			$ccard = self::read_card_skin( $cell );
			if ( $ccard ) { $col['cardBox'] = $ccard; }
			if ( $card ) {
				$col['card'] = $card;
			} else {
				$btns = self::buttons_from_cell( $cell ); // a CTA button-group cell?
				if ( $btns ) {
					$col['buttons'] = $btns;
				} else {
					// A text-only cell → an editable text_block (role 'text'), NOT an opaque code_block.
					// A truly EMPTY / decorative cell is DROPPED. Only a media/structural blob stays verbatim.
					$html  = self::clean_block_html( $cell );
					$plain = trim( preg_replace( '/\s+/', ' ', strip_tags( $html ) ) );
					$media = (bool) preg_match( '/<(img|svg|video|iframe|picture|canvas|input|button|select|textarea)\b/i', $html );
					if ( $plain === '' && ! $media ) { continue; }                                // drop empty / decorative cell
					$has_img = $cell->getElementsByTagName( 'img' )->length > 0;
					$has_txt = false;
					foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p' ) as $tg ) { if ( $cell->getElementsByTagName( $tg )->length > 0 ) { $has_txt = true; break; } }
					if ( $plain !== '' && ! $media ) { $col['role'] = 'text'; $col['text'] = $html; }  // editable text_block
					elseif ( $has_img && ! $has_txt ) { $col['role'] = 'image'; $col['html'] = $html; } // image-dominant cell → media_image
					else { $col['html'] = $html; }                                                     // media / structural → verbatim
				}
			}
			// The cell's OWN flex layout (from data-sc-cs) → replay via the column's native
			// content_direction / gap (a flex-ROW cell lays its children side-by-side).
			$cs = (string) $cell->getAttribute( 'data-sc-cs' );
			if ( preg_match( '/display:\s*(?:inline-)?flex/', $cs ) && count( self::el_children( $cell ) ) >= 2 ) {
				$dir = preg_match( '/flex-direction:\s*([a-z-]+)/', $cs, $dm ) ? $dm[1] : 'row';
				$gap = preg_match( '/(?:^|;)\s*gap:\s*([0-9.]+)px/', $cs, $gm ) ? $gm[1] : '';
				$col['flex'] = array( 'dir' => $dir, 'gap' => $gap );
			}
			// PRODUCT-CARD wrapper skin + hover + ribbon (image-bearing cells only) → the wc_products
			// mapper reproduces the card look via scoped CSS. REST skin from data-sc-cs (computed); HOVER
			// (shadow / lift) from the wrapper's `hover:*` classes (computed style can't see :hover).
			// Mirrors the JS capture-extract rowCols product-card capture. Was the gap that dropped the
			// source card's `hover:shadow-xl hover:-translate-y-2` + its badge.
			if ( $cell->getElementsByTagName( 'img' )->length > 0 ) {
				$wcls = self::cls( $cell );
				$cprop = static function ( $s, $p ) { return preg_match( '/(?:^|;)\s*' . preg_quote( $p, '/' ) . ':\s*([^;]+)/i', (string) $s, $m ) ? trim( $m[1] ) : ''; };
				if ( preg_match( '/border|shadow|rounded/i', $wcls ) || $cprop( $cs, 'border-radius' ) || $cprop( $cs, 'box-shadow' ) ) {
					$shadow = $cprop( $cs, 'box-shadow' );
					$col['wrap'] = array(
						'bg'          => $cprop( $cs, 'background-color' ),
						'radius'      => $cprop( $cs, 'border-radius' ),
						'borderW'     => $cprop( $cs, 'border-top-width' ),
						'borderStyle' => $cprop( $cs, 'border-top-style' ),
						'borderColor' => $cprop( $cs, 'border-top-color' ),
						'shadow'      => ( $shadow && 'none' !== $shadow ) ? $shadow : '',
						'hoverShadow' => preg_match( '/(?:^|\s)hover:shadow-(2xl|xl|lg|md|sm)(?:\s|$)/', $wcls, $hm ) ? $hm[1] : '',
						'hoverLift'   => preg_match( '/(?:^|\s)hover:-translate-y-([0-9.]+)(?:\s|$)/', $wcls, $lm ) ? $lm[1] : '',
					);
				}
				// A small uppercase pill inside the card → the ribbon/badge (e.g. "Best Seller").
				foreach ( $cell->getElementsByTagName( 'span' ) as $sp ) {
					$t = trim( self::text( $sp ) );
					if ( '' === $t || strlen( $t ) > 24 || $sp->getElementsByTagName( '*' )->length > 0 ) { continue; }
					$scs = (string) $sp->getAttribute( 'data-sc-cs' );
					if ( preg_match( '/text-transform:\s*uppercase/i', $scs ) && (float) $cprop( $scs, 'border-radius' ) >= 8 ) {
						$col['ribbon'] = array(
							'text' => $t, 'bg' => $cprop( $scs, 'background-color' ), 'color' => $cprop( $scs, 'color' ),
							'radius' => $cprop( $scs, 'border-radius' ), 'padding' => $cprop( $scs, 'padding' ),
							'fontSize' => $cprop( $scs, 'font-size' ), 'fontWeight' => $cprop( $scs, 'font-weight' ),
							'letterSpacing' => $cprop( $scs, 'letter-spacing' ),
							'borderW' => $cprop( $scs, 'border-top-width' ), 'borderColor' => $cprop( $scs, 'border-top-color' ),
						);
						break;
					}
				}
			}
			$out[] = $col;
		}
		return $out;
	}

	/**
	 * Extract an icon-card from a grid cell: an icon (material-symbol → FA class, or inline SVG),
	 * a heading, and the remaining prose (paragraph + any list, cleaned).
	 *
	 * @param DOMElement $cell
	 * @return array|null { icon, customIcon, title, titleTag, text, cls, iconLayout }
	 */
	/**
	 * The IMAGE-FRAME aspect ratio for a card photo — from the `aspect-[N/M]` / `aspect-square` /
	 * `aspect-video` class on the <img> or its wrapping frame (`<div class="relative aspect-[3/4]
	 * overflow-hidden">`), or a computed `aspect-ratio` in data-sc-cs. Cards in a grid share ONE ratio
	 * (`object-cover` crops each photo to it), so a naturally-portrait photo doesn't render taller than its
	 * siblings and push its title down. Returns e.g. "3/4", "1/1", "16/9", or '' when the source sets none.
	 */
	private static function img_frame_aspect( $im, $stop ) {
		$named = array( 'square' => '1/1', 'video' => '16/9' );
		$n = $im;
		for ( $i = 0; $i < 5 && $n instanceof DOMElement; $i++ ) {
			$c = ' ' . strtolower( self::cls( $n ) ) . ' ';
			if ( preg_match( '/\baspect-\[(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\]/', $c, $m ) ) { return $m[1] . '/' . $m[2]; }
			if ( preg_match( '/\baspect-(square|video)\b/', $c, $m ) ) { return $named[ $m[1] ]; }
			$cs = (string) $n->getAttribute( 'data-sc-cs' );
			if ( preg_match( '/(?:^|;)\s*aspect-ratio:\s*([0-9.]+)\s*\/\s*([0-9.]+)/', $cs, $m ) ) { return $m[1] . '/' . $m[2]; }
			if ( $n === $stop ) { break; }
			$n = $n->parentNode;
		}
		return '';
	}

	/** The bottom margin (px) of an element from its data-sc-cs — reads `margin-bottom:` first, else parses the
	 *  `margin` shorthand's bottom value (top right BOTTOM [left] / vertical horizontal / all). '' when none. */
	private static function heading_margin_bottom( $el ) {
		if ( ! ( $el instanceof DOMElement ) ) { return ''; }
		$cs = (string) $el->getAttribute( 'data-sc-cs' );
		if ( preg_match( '/(?:^|;)\s*margin-bottom:\s*([0-9.]+px)/i', $cs, $m ) ) { return $m[1]; }
		if ( preg_match( '/(?:^|;)\s*margin:\s*([^;]+)/i', $cs, $m ) ) {
			$parts = preg_split( '/\s+/', trim( $m[1] ) );
			$n = count( $parts );
			if ( $n >= 3 ) { return $parts[2]; }  // top right BOTTOM [left]
			if ( $n === 2 ) { return $parts[0]; } // vertical horizontal → bottom = vertical
			if ( $n === 1 ) { return $parts[0]; } // all sides
		}
		return '';
	}

	/** A card's eyebrow label: the nearest SHORT text element before the heading (document order) that is small or
	 *  uppercase and not the heading's own text — { text, cs } or null. JS: cardEyebrowOf. */
	private static function card_eyebrow( $cell, $heading ) {
		if ( ! ( $cell instanceof DOMElement ) || ! ( $heading instanceof DOMElement ) ) { return null; }
		$best = null;
		foreach ( $cell->getElementsByTagName( '*' ) as $e ) {
			if ( $e === $heading ) { break; }
			if ( ! in_array( strtolower( $e->tagName ), array( 'div', 'span', 'small', 'p', 'em', 'strong' ), true ) ) { continue; }
			if ( 0 !== $e->getElementsByTagName( '*' )->length ) { continue; } // a leaf only
			if ( self::is_ancestor( $e, $heading ) ) { continue; }
			$t = trim( preg_replace( '/\s+/', ' ', self::text( $e ) ) );
			if ( '' === $t || mb_strlen( $t ) > 40 || preg_match( '/[.!?]$/', $t ) ) { continue; }
			$cs = (string) $e->getAttribute( 'data-sc-cs' );
			$fs = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', $cs, $fm ) ? (float) $fm[1] : 16.0;
			$upper = (bool) preg_match( '/text-transform:\s*uppercase/i', $cs ) || ( preg_match( '/[a-z]/i', $t ) && $t === mb_strtoupper( $t ) );
			if ( $fs > 13 && ! $upper ) { continue; }
			// a HOVER-REVEALED line (`opacity-0 group-hover:opacity-100`, or a stamped opacity:0) is not resting content — a
			// collection tile's hidden "Collection" kicker had rendered as a permanent eyebrow (a real-site audit)
			if ( preg_match( '/\s(?:opacity-0|invisible)\s/', ' ' . self::cls( $e ) . ' ' ) || preg_match( '/(?:^|;)\s*opacity:\s*0(?:\.0+)?(?:;|$)/', $cs ) ) { continue; }
			$best = array( 'text' => $t, 'cs' => $cs );
		}
		return $best;
	}

	/** TRUE when $a comes before $b in document order (both under $scope). */
	private static function dom_precedes( $a, $b, $scope ) {
		if ( ! ( $scope instanceof DOMElement ) ) { return false; }
		foreach ( $scope->getElementsByTagName( '*' ) as $e ) { if ( $e === $a ) { return true; } if ( $e === $b ) { return false; } }
		return false;
	}

	/** TRUE when $a is an ancestor of $b. */
	private static function is_ancestor( $a, $b ) {
		for ( $n = $b->parentNode; $n instanceof DOMNode; $n = $n->parentNode ) { if ( $n === $a ) { return true; } }
		return false;
	}

	private static function card_from_cell( $cell ) {
		// Heading.
		$heading = null; $htag = 'h3';
		foreach ( array( 'h3', 'h4', 'h5', 'h2', 'h6' ) as $h ) {
			$n = $cell->getElementsByTagName( $h )->item( 0 );
			if ( $n ) { $heading = $n; $htag = $h; break; }
		}
		if ( ! $heading ) { return null; } // no title → not an icon-card
		$stat_eyebrow = null;
		// A STAT CARD (`h4.text-sm label + div.text-5xl "80+" + p.text-xs`): the DISPLAY-SIZE number leaf (≥ 2× the heading's
		// size) is the card's TITLE and the small heading its overline — the number was folded into the content paragraph where
		// the description's 12px won (a fixture from the feed). The h-tag stays the eyebrow via card_eyebrow (it precedes).
		$h_fs = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $heading->getAttribute( 'data-sc-cs' ), $hfm ) ? (float) $hfm[1] : 16.0;
		foreach ( $cell->getElementsByTagName( '*' ) as $nl ) {
			if ( ! in_array( strtolower( $nl->tagName ), array( 'div', 'span', 'p', 'strong', 'b' ), true ) || $nl->getElementsByTagName( '*' )->length > 0 ) { continue; }
			$nt = trim( preg_replace( '/\s+/', ' ', self::text( $nl ) ) );
			if ( ! preg_match( '/^[$€£¥]?\d[\d,.]*\s*(?:%|\+|×|x|k|K|M|\/\d{1,3})?$/u', $nt ) ) { continue; }
			$n_fs = preg_match( '/(?:^|;)\s*font-size:\s*([0-9.]+)px/i', (string) $nl->getAttribute( 'data-sc-cs' ), $nfm ) ? (float) $nfm[1] : 0.0;
			if ( $n_fs >= 24 && $n_fs >= 2 * $h_fs && self::dom_precedes( $heading, $nl, $cell ) ) { $stat_eyebrow = $heading; $heading = $nl; $htag = 'h3'; break; }
		}

		// Icon: first material-symbol span, else first <svg>.
		$icon = ''; $custom_icon = ''; $icon_box_cls = ''; $icon_box_cs = ''; $icon_cls = ''; $icon_chip_cls = ''; $icon_badge = ''; $icon_badge_color = ''; $icon_chip_cs = ''; $icon_color = '';
		foreach ( $cell->getElementsByTagName( 'span' ) as $sp ) {
			if ( strpos( self::cls( $sp ), 'material-symbols' ) !== false ) {
				$icon     = self::material_to_fa( trim( $sp->textContent ) );
				$icon_cls = self::cls( $sp ); // the icon's source classes (text-<token>…) → resolve its REST color in n_icon_box
				// The icon's WRAPPER is often a gray "image" placeholder box (a fill + a fixed height + rounded).
				// Capture it so the icon_box reproduces that box instead of showing a bare icon.
				$par = $sp->parentNode;
				if ( $par && XML_ELEMENT_NODE === $par->nodeType ) {
					$pcls = self::cls( $par );
					if ( strpos( $pcls, 'bg-' ) !== false && preg_match( '/(?:^|\s)(h-\d|min-h-|aspect-)/', $pcls ) ) {
						$icon_box_cls = $pcls;
						$icon_box_cs  = (string) $par->getAttribute( 'data-sc-cs' );
					}
				}
				break;
			}
		}
		// Native Lucide (data-lucide / lucide-<name> class / <iconify-icon icon="lucide:zap">) → library icon id.
		$lucide = '';
		if ( $icon === '' ) { $lucide = self::detect_lucide_in( $cell ); }
		// When the icon is a Lucide / iconify web component, the branch below (which reads the icon's class +
		// colour off a light-DOM <svg>) never runs — an <iconify-icon> renders its svg in shadow DOM. Capture
		// the icon element's class + COMPUTED colour + chip here, else every card's icon fell back to the
		// shortcode's default preset (so a source's green/yellow/green icons all rendered the same).
		if ( '' !== $lucide ) {
			$icon_el = self::lucide_icon_el( $cell );
			if ( $icon_el instanceof DOMElement ) {
				if ( '' === $icon_cls ) { $icon_cls = self::cls( $icon_el ); }
				$icon_color = self::sc_css( $icon_el, 'color' );
				$sp = ( $icon_el->parentNode instanceof DOMElement ) ? $icon_el->parentNode : null;
				if ( $sp && $sp !== $cell && '' === $icon_chip_cls ) {
					$pcls = self::cls( $sp );
					if ( ( strpos( $pcls, 'bg-' ) !== false && preg_match( '/(?:^|\s)(?:w-\d|h-\d|min-h-|aspect-|p-\d|rounded)/', $pcls ) ) || self::el_is_icon_tile( $sp ) ) {
						$icon_chip_cls = $pcls;
						$icon_chip_cs  = (string) $sp->getAttribute( 'data-sc-cs' );
						$cbg = self::sc_css( $sp, 'background-color' );
						if ( '' !== $cbg && 'transparent' !== $cbg && ! preg_match( '/rgba\([^)]*,\s*0?\.?0*\)$/', $cbg ) ) {
							$icon_badge_color = $cbg;
							$crad = self::sc_css( $sp, 'border-radius' );
							$rn   = (float) $crad;
							$icon_badge = ( $rn >= 9999 || strpos( $crad, '50%' ) !== false ) ? 'solid-circle' : ( $rn > 0 ? 'solid-rounded' : 'solid-square' );
						}
					}
				}
			}
		}
		if ( $icon === '' && $lucide === '' ) {
			$svg = $cell->getElementsByTagName( 'svg' )->item( 0 );
			if ( $svg && $cell->ownerDocument ) {
				$custom_icon = (string) $cell->ownerDocument->saveHTML( $svg );
				// Carry the icon's OWN color classes (e.g. `w-8 h-8 text-primary` / `text-secondary`) so
				// n_icon_box resolves the icon color from the source token instead of leaving it inherit-dark
				// — the golden fixture feature chips are green / amber / green per card, not the card's body color.
				if ( '' === $icon_cls ) { $icon_cls = self::cls( $svg ); }
				// The icon's COMPUTED ink: an <svg> is never stamped, so a currentColor glyph inherits from the nearest stamped ancestor
				// (its <iconify-icon> host / the chip: `text-white` on the tile) — else the icon fell back to the theme's default colour.
				if ( '' === $icon_color && ! preg_match( '/(?:^|\s)text-[a-z]/', self::cls( $svg ) ) ) { for ( $ap = $svg->parentNode, $ai = 0; $ap instanceof DOMElement && $ap !== $cell && $ai < 3; $ap = $ap->parentNode, $ai++ ) { $ac = self::sc_css( $ap, 'color' ); if ( '' !== $ac ) { $icon_color = $ac; break; } } }
				// Capture the icon's CHIP wrapper — a filled, fixed-size container (`bg-*` + a w/h/aspect/pad
				// sizing step, e.g. `w-16 h-16 bg-white rounded-2xl`) — as iconChipCls, so n_icon_box reproduces
				// the badge/bg behind the icon (icon_badge shape + fill) rather than an unstyled bare icon.
				$sp = ( $svg->parentNode instanceof DOMElement ) ? $svg->parentNode : null;
				// An icon HOST (an <iconify-icon> the capture filled with its shadow svg, a bare <i>/<span> glyph wrapper with no skin of its own)
				// is not the chip — the chip is the host's parent (`w-12 h-12 rounded-2xl bg-gray-600` around the web component).
				if ( $sp instanceof DOMElement && $sp->parentNode instanceof DOMElement && ( 'iconify-icon' === strtolower( $sp->tagName ) || ( in_array( strtolower( $sp->tagName ), array( 'i', 'span' ), true ) && false === strpos( self::cls( $sp ), 'bg-' ) && '' === self::sc_css( $sp, 'background-color' ) ) ) ) { $sp = $sp->parentNode; }
				// A real icon CHIP is a SMALL wrapper around ONLY the icon — never the CARD/CELL itself. The
				// card carries `bg-secondary p-8`, which matches the chip heuristic (bg + padding), so without
				// this guard the whole card was read as the icon's chip: its dark background got painted behind
				// the icon and the icon was forced display:flex full-width (centered), defeating icon_align.
				// Require the parent to NOT be the cell AND to hold no heading/paragraph (icon-only). (Matches
				// the `$sp !== $cell` guard the lucide path already has.)
				$chip_ok = $sp && $sp !== $cell;
				if ( $chip_ok ) {
					foreach ( array( 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p' ) as $tg ) {
						if ( $sp->getElementsByTagName( $tg )->length > 0 ) { $chip_ok = false; break; }
					}
				}
				if ( $chip_ok ) {
					$pcls = self::cls( $sp );
					if ( ( strpos( $pcls, 'bg-' ) !== false && preg_match( '/(?:^|\s)(?:w-\d|h-\d|min-h-|aspect-|p-\d)/', $pcls ) ) || self::el_is_icon_tile( $sp ) ) {
						$icon_chip_cls = $pcls;
						$icon_chip_cs  = (string) $sp->getAttribute( 'data-sc-cs' ); // full computed chip skin (fill/radius/shadow) → badge design
						// Prefer the chip's CAPTURED computed background + radius (authoritative) over compiling
						// the class — the Tailwind class compile was mis-resolving `bg-primary` to white. The
						// rendered data-sc-cs is the source of truth (e.g. the golden fixture feature chips = green
						// rgb(33,196,93), rounded-2xl). Mirrors the about-item icon-chip path. A transparent /
						// fully-alpha-0 fill is skipped so a bare icon stays a bare icon.
						$cbg = self::sc_css( $sp, 'background-color' );
						if ( '' !== $cbg && 'transparent' !== $cbg && ! preg_match( '/rgba\([^)]*,\s*0?\.?0*\)$/', $cbg ) ) {
							$icon_badge_color = $cbg;
							$crad = self::sc_css( $sp, 'border-radius' );
							$rn   = (float) $crad;
							$icon_badge = ( $rn >= 9999 || strpos( $crad, '50%' ) !== false ) ? 'solid-circle' : ( $rn > 0 ? 'solid-rounded' : 'solid-square' );
						}
					}
				}
			}
		}

		// Body = paragraphs + lists after the heading (cleaned of material-symbol noise + classes).
		$body = '';
		$body_cs = ''; // the description's full computed stamp → n_icon_box's text long tail (italic / shadow / clamp / …)
		$body_cs_sm = ''; $body_cs_md = ''; $body_cs_xl = ''; $body_hover = ''; // …and its phone / tablet / wide diffs, and its (group) hover
		$body_decor = array(); // EMPTY PAINTED BOXES inside the card (an aspect-ratio placeholder, a pattern tile) → n_icon_box scoped CSS
		$body_rhythm = ''; $body_p = 0; // the SECOND paragraph's top margin / top border (a `space-y-*` / `divide-y` rhythm) → `.icon-box__content p + p`
		$body_fs = ''; $body_lh = ''; // the card DESCRIPTION's computed font-size/line-height (first <p>). Source
		// cards use `text-sm` (14px) for body copy while the icon_box content defaults to the theme 16px — the
		// larger size wraps to more lines and inflates card height. Carried → n_icon_box scopes it onto the content.
		// Collect the card body in DOCUMENT ORDER: paragraphs AND stat-number lockups. A stat value like
		// "4.9 star" / "$76M+" is a `flex items-baseline` <div> (not a <p>), so the plain <p> sweep dropped it
		// and the stat rendered as a bare label ("Customer Satisfaction") with no number. Emit each stat number
		// as a bold line so the value renders above its label. (P4 audit fix.)
		foreach ( $cell->getElementsByTagName( '*' ) as $bel ) {
			$btag = strtolower( $bel->tagName );
			if ( $bel === $heading ) { continue; } // (a stat card's number leaf IS the title — never also a bold body line)
			if ( preg_match( '/\s(?:opacity-0|invisible)\s/', ' ' . self::cls( $bel ) . ' ' ) ) { continue; } // a hover-revealed line is not resting body copy
			if ( 'p' === $btag ) {
				$body .= '<p>' . self::clean_inline_html( $bel ) . '</p>';
				// CHILD RHYTHM (measured on the SECOND paragraph): its top margin (a `space-y-4` = 16px) and top border + padding
				// (a `divide-y divide-accent` hairline) → n_icon_box's `.icon-box__content p + p` rule. JS twin: cardOf bodyRhythm.
				$body_p++;
				if ( 2 === $body_p && '' === $body_rhythm ) {
					$pcs = (string) $bel->getAttribute( 'data-sc-cs' ); $rd = array();
