					$pm = $pg( 'margin' ); if ( preg_match( '/^([0-9.]+)px/', $pm, $mm ) && (float) $mm[1] > 0 ) { $rd[] = 'margin-top:' . (int) round( (float) $mm[1] ) . 'px'; }
